-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = LegionChineseDB
D.Strings[88873]="你真是个出人意料的盟友，$c。月神镰刀归你了。但愿它能扭转战局。"
D.Strings[88874]="如果想要月神镰刀，德鲁伊，就来拿吧！"
D.Strings[88875]="我闻到了陷阱的味道。你不能相信一头恶魔的话！"
D.Strings[88876]="它要撒谎，我们就杀了它。可只要有一线可能，我们都得试试！"
D.Strings[88877]="嘘！这边，$n。"
D.Strings[88878]="恐惧猎犬激动地嗅着空气中的味道。"
D.Strings[88879]="$n准备了一份丰盛大餐！"
D.Strings[88880]="$n准备了一份苏拉玛奢华大餐！"
D.Strings[88881]="这个提议真诱人！撤回神殿去。就让他们留着这堆碎木头吧！"
D.Strings[88882]="伊丽扎就在前面的神殿废墟里。保持警惕！她的大军正在搜捕我们。"
D.Strings[88883]="等我们开动起来，就为你提供海上支援。"
D.Strings[88884]="糟了！又有敌人冲下来了。我来对付他们，你去解决那个执事！"
D.Strings[88885]="|TInterface\\Icons\\inv_sword_115:20|t%s装备了巨剑，获得了|cFFFF0000|Hspell:199556|h[凶蛮打击]|h|r！"
D.Strings[88886]="|cFFFF0000$n|r在没有|cFFFF0000|Hspell:199556|h[凶蛮打击]|h|r效果的情况下攻击了蛮兵！"
D.Strings[88887]="我能感觉到魔网的能量。"
D.Strings[88888]="你休想破坏我们的植物！"
D.Strings[88889]="你在腐蚀我们的栖息地！"
D.Strings[88890]="我的植物……"
D.Strings[88891]="姐妹们！"
D.Strings[88892]="靠近我，姐妹们……"
D.Strings[88893]="我必须……保护……"
D.Strings[88894]="别动，让我来治疗你的伤口。"
D.Strings[88895]="你真是走运，居然还活着，姐妹。"
D.Strings[88896]="好好休息吧。我会照顾你的。"
D.Strings[88897]="别丢下我……"
D.Strings[88898]="你为什么要跟我们作对？"
D.Strings[88899]="睁大你们的眼睛，不能让任何人打扰到将军。"
D.Strings[88900]="滚回你的笼子里去！"
D.Strings[88901]="啊，一个完美的试验品！"
D.Strings[88902]="是时候进行一次实体测试了！"
D.Strings[88903]="还需要更多……硫磺……"
D.Strings[88904]="不……不！我的药水……"
D.Strings[88905]="不！我的药水……"
D.Strings[88906]="|TInterface\\Icons\\ability_fixated_state_red:20|t芬雷尔对你施放了|cFFFF0404|Hspell:196838|h[血之气息]|h|r！快跑！"
D.Strings[88907]="你会为此付出代价的，恶魔！"
D.Strings[88908]="我找到那只癞皮狗了！拿起武器！"
D.Strings[88909]="不……不该是这样的！你为什么不保护我？！"
D.Strings[88910]="软弱的可怜虫！暮光教父不敢用我，是因为他明白失败的代价。"
D.Strings[88911]="再给我一个机会吧！不！不！！！"
D.Strings[88912]="而你就不同了，我们可以干出一番大事业。拿起我吧，我会暂时……帮助你的。"
D.Strings[88913]="这么说，就是你偷了我的船，杀了我的船员。"
D.Strings[88914]="把那个巨人放出来。神殿里还有事等着我呢。"
D.Strings[88915]="我很荣幸，舰长。"
D.Strings[88916]="我们用了一半的船员才制伏了这个怪物。看看它会怎么对付你吧。"
D.Strings[88917]="每个人都会见识到亡灵舰长伊丽——"
D.Strings[88918]="预言实现了。法阵就快完成了。哨兵，好好招待我们的“客人”！"
D.Strings[88919]="主人的许诺实现了，通道打开了！这座塔楼属于我们了！"
D.Strings[88920]="%s消失并召唤了|cFFFF0404|野生小鬼|r！"
D.Strings[88921]="%s又出现了！"
D.Strings[88922]="我会再次……驰骋……"
D.Strings[88923]="我们掩护你。把它引到火力线里来！"
D.Strings[88924]="呃，你选错时候了！我的、肚子、非常、不舒服！"
D.Strings[88925]="让这头野兽的怒火烧死你！"
D.Strings[88926]="砸碎你！"
D.Strings[88927]="你疼吗？"
D.Strings[88928]="你太臭了！"
D.Strings[88929]="你们最好小心点……呸！"
D.Strings[88930]="感觉不太好啊！"
D.Strings[88931]="味道更好的来了！"
D.Strings[88932]="唔！真是美味！"
D.Strings[88933]="至少……肚子……舒服多了……"
D.Strings[88934]="|TInterface\\Icons\\Ability_Creature_Poison_06:20|t溃面开始喷吐|cFFFF0404|Hspell:201598|h[凝结的呕吐物]|h|r！"
D.Strings[88935]="你的生命将滑向虚空！无可逃避！"
D.Strings[88936]="你的存在毫无意义！屈服于深渊的意志吧！"
D.Strings[88937]="碾碎你！对，碾碎这个小东西！"
D.Strings[88938]="蛇主人说了，小东西必须死！"
D.Strings[88939]="把你的人送到安全的地方去，我们会挡住燃烧军团的部队的。"
D.Strings[88940]="我们瞄准那混蛋了！狠狠地打！"
D.Strings[88941]="对，我们急于享用那堕落泰坦的爪牙。但首先是……扎卡兹。"
D.Strings[88942]="火炮齐射！开火。开火！"
D.Strings[88943]="那群邪教徒可能会再度唤醒他，他也可能自行苏醒。我们得吞噬他的力量，让他彻底完蛋。你知道这是有必要的。"
D.Strings[88944]="伊丽扎逃入了神殿。我们不会让她的船员追上你的。去抓住她！"
D.Strings[88945]="我们没炮弹了！你得自己想办法通过神殿的大门。"
D.Strings[88946]="狼人撤下悬崖，跑向了卡拉赞！"
D.Strings[88947]="你成功了！邪教徒都跑了，哈哈！回去找法奥吧，我用这块暮光传送石送你！"
D.Strings[88948]="我来打破屏障。掩护我！"
D.Strings[88949]="不过你得多留意那把剑。天知道那个老家伙能干出什么事来。"
D.Strings[88950]="就差一点点，它就能……破开了！"
D.Strings[88951]="嘿，我需要帮助！我可不想再说一次！"
D.Strings[88952]="先是夜行狼人发疯，现在又有个德鲁伊要调查密斯特曼托庄园？"
D.Strings[88953]="这说明，月神镰刀肯定已经回到了暮色森林……所以黑暗骑士也不会太远了。"
D.Strings[88954]="你要找什么，德鲁伊？我或许能帮你。"
D.Strings[88955]="恐惧之刃几乎杀光了整个舰队。固若金汤的堡垒也在它们的意志下血流成河。它们的凶名足以让水手们心生惧意。"
D.Strings[88956]="它们所向披靡……我也一样！快跑吧，那样你或许还能活着回去吹吹牛。"
D.Strings[88957]="没有人能反抗我们。释放潮汐的怒火吧！"
D.Strings[88958]="你这蠢货！你一样会死于恐惧之刃下！"
D.Strings[88959]="你！你杀了爸爸！我要杀了你！"
D.Strings[88960]="我的村庄贾德维克正在遭受纳迦的袭击。我是来找你帮忙的。"
D.Strings[88961]="托尔里，你为什么需要我的帮助？你的部族不能独自对付这些纳迦吗？"
D.Strings[88962]="因为我们面临着两大障碍，$n。$B$B我们是骄傲的战士，保护村庄对我们来说轻而易举，但我们的部族早已离开了大海。我们不可能击败盘踞在海中的敌人。$B$B更糟的是，我们的族长失踪了。部落成员正为了争夺他的宝座大打出手。"
D.Strings[88963]="护盾被削弱了！"
D.Strings[88964]="积怨夫人是无敌的！她是不会倒下的！"
D.Strings[88965]="贾德维克的同胞们！卡尔德和艾纳尔都战死了。他们没有资格领导贾德维克。"
D.Strings[88966]="作为最后的继承者，领导人民对抗入侵的萨吉塔纳迦的重任就落到我肩上了。"
D.Strings[88967]="这个外来者是受我庇护的。所有攻击$g他:她;的人都要向我做出解释。"
D.Strings[88968]="已经没用了。"
D.Strings[88969]="干掉他们。你的刀渴望鲜血。"
D.Strings[88970]="你想阻止我？有了这把武器，我就无所不能！无所不能！"
D.Strings[88971]="我曾预见过我的命运。而你并不在其中！"
D.Strings[88972]="我是海上的魔王，水手的梦魇！而你什么也不是！"
D.Strings[88973]="够了！我要刺穿你的心脏！"
D.Strings[88974]="看来这儿有虫子……"
D.Strings[88975]="我一直在等待高贵的勇士进入我的国度。看！英灵殿！"
D.Strings[88976]="此地将考验你们的勇气。只要你们有能力，就能得到阿格拉玛之盾！"
D.Strings[88977]="你竟敢闯入这里！我要把你撕成碎片！"
D.Strings[88978]="是凯恩还是奥图里斯？"
D.Strings[88979]="卫兵！拦住他们！做好准备！"
D.Strings[88980]="|TInterface\\Icons\\spell_mage_frostbomb:20|t颤栗之喉开始施放|cFFF00000|Hspell:201960|h[寒冰炸弹]|h|r！"
D.Strings[88981]="伊丽扎的舰队在炮轰神殿。如果你想和她比枪法的话，最好快一点！"
D.Strings[88982]="你和奥图里斯为什么那么合不来？"
D.Strings[88983]="很多年以前，伊利丹大人还控制着黑暗神殿时，受难者奥图里斯就跟我们的领袖以及恶魔猎手决裂了。$B$B奥图里斯认为伊利丹已经变成了他最痛恨的那种东西，并为此发动了一场邪恶的战争，导致了主人的陨落。$B$B他还害死了我们的四位战友——阿兰蒂恩、瑟拉斯、奈萨里尔和瓦雷迪斯。$B$B他们是我们的导师、我们的兄弟姐妹。$B$B所以，我无法原谅他。"
D.Strings[88984]="你为什么不喜欢凯恩？"
D.Strings[88985]="你的计划很可靠，$n。当然，要想成功的话，我们还得依赖你的能力来避免伤亡。$b$b至于我，我会设法吸引那个怪物的注意力，承受它的怒火。$b$b你准备好之后就告诉我一声吧，我会下令开始进攻的。"
D.Strings[88986]="凯恩一直是个忠诚的战士，无畏的领袖和杰出的战略家。$B$B可他对伊利丹的忠诚蒙蔽了他的眼睛。$B$B随着伊利丹的力量增长，他所吸收的恶魔力量开始失控。$B$B我知道我的行为可能会被视为背叛，可我只是做了我认为正确的事。$B$B现在，凯恩也开始走上伊利丹的老路。这样的人不能领导伊利达雷。"
D.Strings[88987]="你好！你没有被跟踪吧？"
D.Strings[88988]="你安全归来了！啊，还有恐惧之刃！这是我见过的最好的剑。"
D.Strings[88989]="你就是我要找的人吗？干嘛要大老远地跑到这里来？"
D.Strings[88990]="啊哈哈哈……走投无路的守望者向敌人求助了吗？投降吧，恶魔猎手！想要逃出这个地窟，你就得面对我。"
D.Strings[88991]="看着吧，恶魔猎手，你们是在白费力气。连伟大的伊利丹·怒风，都成了燃烧军团的阶下囚。"
D.Strings[88992]="精神可嘉，可惜我的恶魔已经渗透进了每层地窟。你只有死路一条。"
D.Strings[88993]="你们的盟友已经倒下了。我的大军会在破晓前碾碎你们！"
D.Strings[88994]="恐惧猎犬瞪着你所在的方向。"
D.Strings[88995]="恐惧猎犬咆哮了起来。"
D.Strings[88996]="你好，伙计。$b$b你想要乔装成卓格巴尔吗？你想要神不知鬼不觉地潜入啮岩孤地吗？你想混入偷了巴布尔私人配方的那群人中间吗？你想拿回巴布尔的配方吗？$b$b那就喝了这杯特制的药剂，变成他们中间的一员吧！$b$b如果你还需要更多药剂，可以回来找我。噢，还有，小心那些蜥蜴。"
D.Strings[88997]="你听到什么声音没有？"
D.Strings[88998]="睁大你们的眼睛。他们过来了。"
D.Strings[88999]="把药剂给我吧，伙计。"
D.Strings[89000]="我闻到了入侵者的气味。"
D.Strings[89001]="该死！她的船员比我想象的要多。你得设法溜过去。"
D.Strings[89002]="大地之末号归我们了，小子们……她漂亮吧？"
D.Strings[89003]="我好像忘了说，那片海滩上布满了地雷。所以睁大你的眼睛吧！"
D.Strings[89004]="你胜利了……但这只是诸多试炼中的第一项而已。"
D.Strings[89005]="在开始下一个试炼前，你们要击败赫娅和芬雷尔，以证明你们的实力！"
D.Strings[89006]="你是怎么溜进来的？！废物，都是废物！"
D.Strings[89007]="亡灵船队的其他船只也过来了。你有什么计划？"
D.Strings[89008]="你就这点本事吗？我手下擦甲板的都比你能打！"
D.Strings[89009]="强大的芬雷尔在此出没。只有足智多谋的人才能杀掉这头野兽——多么完美的考验。"
D.Strings[89010]="只有足智多谋的人才有可能杀掉这头野兽——一次检验你是否具有资格的完美测试。"
D.Strings[89011]="把甲板给我擦亮，你们这些肮脏的懒骨头。亡灵船长要的是完美！"
D.Strings[89012]="污染"
D.Strings[89013]="你们获得了我的祝福，勇士！希望能在荣耀大厅中见到你们！"
D.Strings[89014]="我想我欠你一条命，$n。我差点就彻底死在那儿了。"
D.Strings[89015]="愚蠢的凡人！你踏入了我的陷阱！"
D.Strings[89016]="永恒的折磨在等着你！"
D.Strings[89017]="索迪尔！！！不！！！"
D.Strings[89018]="我死得像个真正的战士，$n。"
D.Strings[89019]="我又能和索迪尔并肩战斗了。"
D.Strings[89020]="你既是我的马前卒，也是我的眼中钉，$n。"
D.Strings[89021]="我要谢谢你帮我解决了卡尔德和艾纳尔。我要所有可能领导贾德维克的人都变成死人，可我不能让村民怀疑是我害死了他们。"
D.Strings[89022]="群龙无首的贾德维克，绝对抵挡不了海巨人和纳迦联军掀起的死亡与毁灭的狂潮。我的女王陛下也将在苏拉玛获得一个桥头堡。"
D.Strings[89023]="我的计划成功了，你这讨厌的废物。我的纳迦已经杀掉了你和布兰多夫召集起来的小崽子。而你居然还有脸活在这个世界上！"
D.Strings[89024]="我们将前往达拉然，这段路不长。暗影大厅见！"
D.Strings[89025]="我很高兴你跟我来这里，$n。你恐怕已经察觉到我的计划了。"
D.Strings[89026]="这里出什么事了，托尔里？"
D.Strings[89027]="啮咬者会把你变成一堆碎石的！"
D.Strings[89028]="在谈正事之前，我想先看看你。请原谅我之前的不坦诚，就当是本性难移吧。我叫阿隆索斯·法奥。我曾做过一个教会的首领，一个天灾军团的无脑爪牙，一场秘密战争的幕后策划。但一直以来，我的主要身份都是一个牧师。"
D.Strings[89029]="请原谅我的隐瞒……积习难改啊。我叫阿隆索斯·法奥。我曾经是一个教会首领，一个无脑的天灾爪牙，一场秘密战争的策划者。但我首先是个牧师。"
D.Strings[89030]="燃烧军团带来了无法忽视的威胁，所以我决定站出来。我认为必须将所有教派的牧师召集在一起，对抗共同的敌人。"
D.Strings[89031]="为此，我们需要一位众望所归的勇士。我相信你就是那个勇士，$n，但你首先得说服其他人。你愿意接受这个挑战吗？"
D.Strings[89032]="看！$n回来了！"
D.Strings[89033]="这位勇士很有天赋！"
D.Strings[89034]="干得真不错！"
D.Strings[89035]="我们对此看法一致。现在，去找维伦吧。他有件……有趣的事要跟你谈谈。"
D.Strings[89036]="后退，$c！我虽然受伤了，可圣光会保护我的！"
D.Strings[89037]="什么，你不是来终结黑暗骑士的吗？"
D.Strings[89038]="够了！拿开你的武器！"
D.Strings[89039]="黑暗骑士很快就会追上来，如果我们都死了，那没有任何好处！"
D.Strings[89040]="帮我消灭他们，我就把我知道的告诉你。"
D.Strings[89041]="谁敢质疑我领导贾德维克的权利？没人能打败我！"
D.Strings[89042]="先祖在上！我才是贾德维克的下一任族长！外来者休想阻挡我！"
D.Strings[89043]="维库走狗们，过来战斗，否则我就亲手杀了你！"
D.Strings[89044]="闭嘴，时间不多了。"
D.Strings[89045]="明智的选择。过来，我们一起喝两杯，说说详细的计划！"
D.Strings[89046]="我到贾德维克外面等你。先不要进村子，我们得再谈谈。"
D.Strings[89047]="我们去埃瑞丁营地吧。"
D.Strings[89048]="伙计，你到底用力了没有？"
D.Strings[89049]="你的个子怎么这么矮啊，伙计？你看起来就像头小蠢牛似的，哈！"
D.Strings[89050]="你想找什么？快下来吧，兄弟。"
D.Strings[89051]="新的地底之王会带领我们再次崛起的！"
D.Strings[89052]="别担心，伙计！很快，我们新的地底之王就会碾碎软弱的蠢牛和他们的盟友。之后，你这副小身板就不用上战场啦。"
D.Strings[89053]="你应该去找蘑菇商人。他那儿应该会有长杆子。哈！"
D.Strings[89054]="你迷路了吗，伙计？你看着像是迷路了。"
D.Strings[89055]="我听几个家伙说，黯石部族背叛了我们。很好！没有那些废物，我们会更强大。他们又瘦……又弱。还很矮。"
D.Strings[89056]="你要明白，我不可能掺和这种事。你搞定后，就到卡拉赞外面来找我吧。"
D.Strings[89057]="我要去教堂祈求圣光怜悯我们俩的灵魂。"
D.Strings[89058]="我得警告你，我的同胞不喜欢外来者。你最好避开不必要的冲突。"
D.Strings[89059]="法师为我们开启了一座传送门。跟我来吧，我把纳鲁和德莱尼的过去讲给你听。"
D.Strings[89060]="在躲避燃烧军团的漫长岁月里，纳鲁一直在帮我们……有的甚至为此付出了生命。要没有它们的帮助，我们早就死了。"
D.Strings[89061]="最终，我们想到了报答它们的办法。我们曾经见过一个纳鲁转化为虚空的可怕景象。一定有办法救它的！"
D.Strings[89062]="我们建造了一个囚禁并研究这个堕落生物的地方。我们在那里与纳鲁沟通，思考扭曲虚空的本质。我现在就要带你去那里。"
D.Strings[89063]="被你这种……废物……击败……"
D.Strings[89064]="我会在冥狱深渊……等着你……"
D.Strings[89065]="就这样！用我的拳头打肿你的脸！"
D.Strings[89066]="这是谁扔的？"
D.Strings[89067]="我在寻找战斗的机会！"
D.Strings[89068]="研究使用精瘦腿肉的食谱。"
D.Strings[89069]="我们一定要在这里这么做吗？"
D.Strings[89070]="传送门里涌出一支燃烧军团精英小队！"
D.Strings[89071]="蒂迪派我来拿一颗棱光邪能页岩钻石。"
D.Strings[89072]="我们处理过许多类似的案子，失窃的货物应该都被运到这里来了。"
D.Strings[89073]="你有没有在附近发现什么可疑活动，需要告诉我的？"
D.Strings[89074]="啊，我明白了。好吧，这里没有任何可疑情况发生的话，我当然很高兴了。"
D.Strings[89075]="继续。"
D.Strings[89076]="我可以给你一颗。但告诉蒂迪，我会寄账单给她的。我们可不是搞慈善的。"
D.Strings[89077]="你已经证明了自己是一个强大的牧师。"
D.Strings[89078]="能够回到月光林地的古树之间真好，哪怕这只是短暂的小憩。"
D.Strings[89079]="诸位！诸位！我们来干一杯。"
D.Strings[89080]="研究使用野雉蛋的食谱。"
D.Strings[89081]="研究使用大块异香肋排的食谱。"
D.Strings[89082]="研究使用肥美熊肉排的食谱。"
D.Strings[89083]="研究使用魔力之血的食谱。"
D.Strings[89084]="研究使用诅咒女王鱼的食谱。"
D.Strings[89085]="研究使用藓鳃鲈鱼的食谱。"
D.Strings[89086]="研究使用至高岭鲑鱼的食谱。"
D.Strings[89087]="研究使用风暴鳐鱼的食谱。"
D.Strings[89088]="研究使用符鳞锦鲤的食谱。"
D.Strings[89089]="研究使用黑梭鱼的食谱。"
D.Strings[89090]="研究使用厚切培根的食谱。"
D.Strings[89091]="巫妖王说我的搭档将是有史以来最强大的骑士之一。我想他说的就是你吧？那我就指望你能带着我们全身而退。"
D.Strings[89092]="我们走吧。前面的路上有邪能卫士在巡逻。我之前一直是躲着他们的，但有了你带头，我们就能杀出一条血路。"
D.Strings[89093]="这……你确定这是属于污染者本人的吗？"
D.Strings[89094]="我以前见过这种力量，是在翡翠梦境的深处，一条名为艾林裂隙的深渊附近。"
D.Strings[89095]="那个地方散发强烈的上古邪气，以致于我们都不敢冒险靠近它。"
D.Strings[89096]="所以我们只能试着封印它，将它的污染与翡翠梦境的其他地方隔离开来。但看来我们失败了。"
D.Strings[89097]="而现在，你却在燃烧军团的手中找到一块这种力量的碎片？多么可怕的预兆……"
D.Strings[89098]="我必须回到我当初求学的地方——瓦尔莎拉的原始森林去寻求指引。"
D.Strings[89099]="多亏了你的警告，这或许能救我们一命。在你离开前，请再去跟守护者雷姆洛斯谈谈。"
D.Strings[89100]="这是你要的钻石。"
D.Strings[89101]="这是你要的药水。"
D.Strings[89102]="这是你要的核心。"
D.Strings[89103]="蒂迪派我来拿一瓶易燃的魔力洪流药水。"
D.Strings[89104]="你这儿有灌魔核心吗？"
D.Strings[89105]="我准备好接受引见了。"
D.Strings[89106]="啊，我这儿正好有一瓶。小心点，只要洒出来一滴就会造成，呃，不太好的后果。"
D.Strings[89107]="我要杀了他们来向他致敬！"
D.Strings[89108]="这是$n。我们并肩战斗过，还发现索迪尔已经被这些毒蛇杀害了。"
D.Strings[89109]="明智的选择。"
D.Strings[89110]="不！那把剑决不能出世！"
D.Strings[89111]="埃瑞丁……不！你为什么要把它挖出来？"
D.Strings[89112]="我们得夺回天启。他控制不了这把剑里的无穷怒火。"
D.Strings[89113]="我们会为他复仇的！"
D.Strings[89114]="去墓穴。我们一定要解除诅咒！"
D.Strings[89115]="索迪尔会为你骄傲的。继续战斗吧，兄弟！"
D.Strings[89116]="索迪尔已经战死了。我们要为他的死复仇。"
D.Strings[89117]="索迪尔死了。我没能及时找到他。"
D.Strings[89118]="总算得救了！"
D.Strings[89119]="我自由了！我自由了！"
D.Strings[89120]="我再也不想呆在这里了！"
D.Strings[89121]="谢谢你！我……我会努力逃出去的。"
D.Strings[89122]="太感谢你了，我的朋友！"
D.Strings[89123]="法力……我需要法力！暗夜井……不……不！让我回去！"
D.Strings[89124]="好渴……我必须找到法力酒！"
D.Strings[89125]="坐下吧，让我们来讨论一下细节。"
D.Strings[89126]="很高兴又多了一张新面孔！我早就受够特塞斯那个丑八怪了……请别见怪，特塞斯。"
D.Strings[89127]="我们是影行者，无冕者的首领。"
D.Strings[89128]="这些行动都是绝对保密的。就像我们的头衔所显示的那样，我们更喜欢潜伏在暗影中。"
D.Strings[89129]="下水道的入口在这边。跟我来！"
D.Strings[89130]="我们邀请你与我们平起平坐，因为我们相信你有能力直面这个威胁……并获得胜利。"
D.Strings[89131]="如果想要这把剑，死亡骑士，就来拿吧！"
D.Strings[89132]="这魔力太强了，我无法抵抗。但你的能力或许能抵御它，死亡骑士。"
D.Strings[89133]="很好！既然你这么想要天启的力量，我就演示给你看看吧！"
D.Strings[89134]="感受灭世者的怒火吧！"
D.Strings[89135]="不！这力量……是我的！"
D.Strings[89136]="这力量不属于你，埃瑞丁。你无法掌控天启。它的黑暗力量会将你变成傀儡。"
D.Strings[89137]="那声音……父亲？！"
D.Strings[89138]="安息吧，孩子。诅咒解除了。"
D.Strings[89139]="你自由了。"
D.Strings[89140]="一根柱子顶上镶嵌着一块巨大的、闪闪发光的红宝石。"
D.Strings[89141]="尝试取下宝石。"
D.Strings[89142]="成功了！你今天帮了潘达利亚一个大忙。"
D.Strings[89143]="就是它，末代皇帝的法杖。你已证明了自己有资格拿起它，影踪之友。"
D.Strings[89144]="一万年前，少昊皇帝用它召唤迷雾笼罩了潘达利亚，让我们躲过了燃烧军团的魔爪。"
D.Strings[89145]="但这次，熊猫人不会再逃避了。我们要战斗！"
D.Strings[89146]="用皇帝的法杖去对抗军团吧，勇士。我们支持你。"
D.Strings[89147]="初级海员可以配枪吗？"
D.Strings[89148]="抱歉，那块宝石是我的。请不要碰它好吗？"
D.Strings[89149]="<萨鲁法尔眯着眼睛上下打量了你一番。>$b$b卡德加跟我说，我们今天要会见恶魔猎手时，我还嘲笑他来着。当他说我应该听你把话说完时，我笑得就更大声了。$b$b可是，你还是来了。$b$b我允许你独自进入要塞。但你得把武器和同伴留在门口。在我允许之前，你也不能乱说话。$b$B你要敢轻举妄动，我马上就用斧子劈了你。"
D.Strings[89150]="噢，好的，我这就下来。马上就来！"
D.Strings[89151]="不能，初级海员需要共用一把枪。"
D.Strings[89152]="你好，有人叫我吗？"
D.Strings[89153]="我很好奇他们去哪儿了。噢，好吧，或许他们还会回来的。"
D.Strings[89154]="谢谢你，我的朋友！愿白虎保佑你百战百胜！"
D.Strings[89155]="这是宝石，现在，把核心给我。"
D.Strings[89156]="对，我有你要的东西。但我不可能直接把它给你。你得拿东西来跟我换。"
D.Strings[89157]="楼上这颗可爱的红宝石吸引了我的目光。帮我拿到它，我就把核心给你。"
D.Strings[89158]="跟你做买卖真是愉快，朋友。"
D.Strings[89159]="你知道吗，原本我才是最后一位影行者的候选人。可他们全都背弃了诺言，把赌注押在了你身上！"
D.Strings[89160]="看你能坚持多久吧。"
D.Strings[89161]="真可惜。乔拉齐为我做了那么多。等他赶来却发现你死了，他一定很难过。"
D.Strings[89162]="卡翠欧娜，我听到楼下有人找你。"
D.Strings[89163]="打扰一下！有人吗？"
D.Strings[89164]="这无关私人感情。这只是公事。"
D.Strings[89165]="|TInterface\\Icons\\ability_fixated_state_red:20|t一只强袭甲虫|cFFFF0000|Hspell:202480|h[锁定]|h|r了你！"
D.Strings[89166]="你真以为我死在死亡矿井了吗？我只是用药剂进入假死状态，骗过你这傻瓜而已。"
D.Strings[89167]="住手！住手！够了！"
D.Strings[89168]="或许其他人是对的。"
D.Strings[89169]="他们说我死在死亡矿井了。蠢货！用神经毒素扰乱对手的感知，要伪装出死亡效果太容易了。"
D.Strings[89170]="结束了。任务完成了。"
D.Strings[89171]="拿上你的武器，$c。我得将其他神器还给它们的主人。"
D.Strings[89172]="我们最好别再见了，这对我们俩都好。"
D.Strings[89173]="让我来把这个插进核心里，看看会发生什么。"
D.Strings[89174]="很闪亮，但没用。我们得试试其他东西。或许我们需要一些化学反应。"
D.Strings[89175]="去炼金店找德崔斯要一瓶强力药水吧。"
D.Strings[89176]="好了，我要倒入溶剂了。小心点，我也不知道这会引起什么反应。"
D.Strings[89177]="你还好吗？*咳咳，咳咳*我想这里只能使用灌魔核心了。"
D.Strings[89178]="虽然不太可能，达拉然可能有人有这种东西。去魔术旅馆问问波格林，看看他有没有见过吧。"
D.Strings[89179]="你找到了？！太棒了！你真是太棒了，$n！为我祈祷吧，我要把它放进去了。"
D.Strings[89180]="我相信你一定会遵守誓言的，梵妮莎。我可不希望你父亲对你感到失望。"
D.Strings[89181]="梵妮莎在影行者中的席位归你了。坐吧。"
D.Strings[89182]="你们是逃出守望者地窟的恶魔猎手？$B$B你们从那些试图摧毁我们世界的家伙身上汲取力量。告诉我，我为什么要相信你们？"
D.Strings[89183]="我们为战胜恶魔牺牲了一切，用恶魔的力量来对付他们自己。请让我们为部落效劳吧。"
D.Strings[89184]="哟！好多了！我来对付他们！"
D.Strings[89185]="风暴，大地，火焰！听我号令！"
D.Strings[89186]="恶心，可我想活下去。"
D.Strings[89187]="贾德维克已经完了。"
D.Strings[89188]="那两个蠢货领导不了贾德维克。"
D.Strings[89189]="我必须成为贾德维克的领袖。"
D.Strings[89190]="这挡不住他们多久。我们必须前往图书馆！"
D.Strings[89191]="这里不欢迎$R！"
D.Strings[89192]="瓦格里来接引我了！"
D.Strings[89193]="以先祖的名义！"
D.Strings[89194]="光荣的死亡！"
D.Strings[89195]="瓦里安国王战胜了那么多的考验。我们应该以他为榜样。"
D.Strings[89196]="我很荣幸能与他并肩作战。瓦里安是个好人。"
D.Strings[89197]="我们已经失败了，虽然大家都很悲痛，但我们必须找到新的平衡。"
D.Strings[89198]="他以仁慈和勇气率领着我们。能拥有像瓦里安国王这样的盟友是我们的幸运。"
D.Strings[89199]="圣光失去了一位强大的盟友。我也失去了一位好朋友。但我们必须前行。"
D.Strings[89200]="<抽泣>瓦里安……老朋友……"
D.Strings[89201]="我知道那个小伙子的感受。我也失去了我的父亲……和国王。"
D.Strings[89202]="听……你听见了吗？天空也在为瓦里安国王哭泣咆哮。"
D.Strings[89203]="这是什么？一个小$r想来挑战我？"
D.Strings[89204]="贾德维克必将败于萨吉塔之手！"
D.Strings[89205]="到达拉然来找我吧！我们可以分享一些食谱。"
D.Strings[89206]="不！我不想回去！"
D.Strings[89207]="你将和我们一样被诅咒折磨！"
D.Strings[89208]="你会为这种亵渎行为付出代价的！"
D.Strings[89209]="你为什么要把我带回到这里来？！"
D.Strings[89210]="跟我一起死吧！"
D.Strings[89211]="你准备好爆炸了吗？"
D.Strings[89212]="高温降临了！"
D.Strings[89213]="研究使用银鲭鱼的食谱。"
D.Strings[89214]="这件神器属于卡拉赞，$c！"
D.Strings[89215]="我们要拿走属于我们的东西！"
D.Strings[89216]="神器在召唤我们！"
D.Strings[89217]="现在，让我们先把它们切成长条状……"
D.Strings[89218]="有意思！如果等晒干后再剔骨，损失的肉就会减少……"
D.Strings[89219]="如果再加一点啤酒，味道可能会更好……"
D.Strings[89220]="小心那些蜥蜴。它们能看穿你的伪装。"
D.Strings[89221]="你可以看看我的头盔，$n，但你绝对不能碰它。"
D.Strings[89222]="小心！我们中间有恶魔！"
D.Strings[89223]="你好，$n大师。我们今天该做些什么菜呢？"
D.Strings[89224]="双向连接已建立。随便用吧——这段距离很短，需要的能量也很少。"
D.Strings[89225]="检测完成。现在放下道标！"
D.Strings[89226]="我应该提到过……测量会引发传送空间的异动，比如异次元涟漪之类的……"
D.Strings[89227]="$n！很高兴看到你回来。找到萨斯多拉还仅仅是个开始。"
D.Strings[89228]="再给我带些食材来吧，$n大师。肉、鱼、血……无论你在危险的野外能找到什么都行。我会帮你把它们变成美味佳肴的。"
D.Strings[89229]="熊猫人的书太无聊了！智慧，智慧，智慧——都是胡扯！"
D.Strings[89230]="你能带我飞去永春台吗？"
D.Strings[89231]="需要更多召唤师才能完成仪式。"
D.Strings[89232]="记住，你可以用新的传送器快速到达地表。安诺拉山谷就在这里的北面。"
D.Strings[89233]="我需要一点时间来恢复和……思考。我们稍后再谈。"
D.Strings[89234]="哇，哇，哇。我没看错吧，新晋的影行者走进了我的宝库？真是难以置信！"
D.Strings[89235]="下次小心点，好吗？巨龙动力魔法熔炉可不是什么大路货。"
D.Strings[89236]="在爱情和交易里，所有人都是平等的。"
D.Strings[89237]="这里是100个金币。够公道了吧？"
D.Strings[89238]="<将武器架在马林的脖子上。>这笔交易怎么样？"
D.Strings[89239]="太够了。感谢你的慷慨！"
D.Strings[89240]="嘿，嘿，嘿。我不想惹麻烦。拿去吧，我的天！"
D.Strings[89241]="噢！你怎么这么快就把烟火拿走了？我们还是走吧，索比。"
D.Strings[89242]="这里是贾德维克！这里不欢迎你！"
D.Strings[89243]="一个外来的小崽子想挑战我？"
D.Strings[89244]="贾德维克的族长就死在我面前！你也会跟他一样的！"
D.Strings[89245]="贾德维克已经群龙无首！它将在萨吉塔的大军前分崩离析！"
D.Strings[89246]="这就走，斯麦奇！"
D.Strings[89247]="看，诸界毁灭者萨拉卡！她所到之处，就会带来万年的毁灭。"
D.Strings[89248]="嘿，那是我的！我不会放过你的，$g先生:女士;！"
D.Strings[89249]="德莱尼一直想设计出一种仪式，让纳鲁回归圣光。为了帮助他们，我召集了其他牧师一起来帮忙。"
D.Strings[89250]="我们就快成功了。我相信你的那件武器一定能力挽狂澜。你只要踏入主法阵，我们就能开始仪式了！"
D.Strings[89251]="对！用这把剑抽出虚空能量！"
D.Strings[89252]="抢小孩子的烟火！这可真是恶劣。记住我的话，你会后悔的！"
D.Strings[89253]="对！用圣光治疗它！"
D.Strings[89254]="对！用神圣之火净化它！"
D.Strings[89255]="我美丽的烟火！我要去告发你！"
D.Strings[89256]="噢，嘿，你过去的时候，顺便告诉尼基，她只剩下三天的时间来还钱了，我可不是搞慈善的！"
D.Strings[89257]="连我也找不到黑暗骑士的圣殿，已经有许多人为寻找它而葬身暮色森林了。"
D.Strings[89258]="我感觉到密斯特曼托庄园有个人……一个圣光的虔诚信徒。如果你能制伏他，他或许就是你所需的钥匙。"
D.Strings[89259]="我是不会倒下的！"
D.Strings[89260]="你休想打败我，毒蛇！"
D.Strings[89261]="不用着急。在面临重大抉择时，慎重考虑是完全应该的。"
D.Strings[89262]="你阻止不了我，毒蛇！"
D.Strings[89263]="小心点！这个世界已经不再安全了。"
D.Strings[89264]="为了索迪尔！"
D.Strings[89265]="为了贾德维克！"
D.Strings[89266]="让我们杀光这些毒蛇吧，$n！"
D.Strings[89267]="为贾德维克而战，$n！"
D.Strings[89268]="分享我的力量吧，$n！"
D.Strings[89269]="我能感觉到你体内灭世者的力量，$n。你已经为战争做好了准备。"
D.Strings[89270]="到冰封王座来找我吧。我想亲眼见见我的新勇士。"
D.Strings[89271]="卡特琳，等我们放你出来！"
D.Strings[89272]="弗里克，你这个老家伙。起来！"
D.Strings[89273]="睁开眼睛看看，斯托卡弗。我们不是那些毒蛇！"
D.Strings[89274]="搞定。回潘达利亚去。这里老有股海龟味儿。"
D.Strings[89275]="潘达利亚看着不妙。那个兽人摧毁锦绣谷之后，我就没见过这么多坏蛋了。"
D.Strings[89276]="你得立刻回暗影大厅去。别让我久等。"
D.Strings[89277]="你可以找人把你快速送出去。"
D.Strings[89278]="我要飞去神射手营地。"
D.Strings[89279]="骑士们！快逃命吧！这个恶魔太强大了……"
D.Strings[89280]="怎么？又有愚蠢的凡人来骚扰我的国度了？你们是来送死的吗？"
D.Strings[89281]="闭嘴，否则我就放干你的血！"
D.Strings[89282]="嘿，你——我们必须立刻谈谈。"
D.Strings[89283]="玛格拉弗也曾带领一支小队来刺杀高瑞里克斯。我很惊讶他居然还活着！没想到燃烧军团还会抓俘虏。"
D.Strings[89284]="我准备好了。带我一起踏上你的疯狂钓鱼之旅吧。"
D.Strings[89285]="呃！噢，我的脑袋……"
D.Strings[89286]="谁打我！？"
D.Strings[89287]="|TINTERFACE\\ICONS\\inv_misc_web_02.blp:20|t纳尔提拉开始施放|cFFF00000|Hspell:200227|h[缠绕之网]|h|r！"
D.Strings[89288]="|TINTERFACE\\ICONS\\inv_misc_web_02.blp:20|t$n正被拖入纳尔提拉的|cFFF00000|Hspell:200227|h[缠绕之网]|h|r！"
D.Strings[89289]="什么……？！这下感觉好多了。"
D.Strings[89290]="是谁扔的绷带？老实说！"
D.Strings[89291]="谢谢你帮我治疗！"
D.Strings[89292]="我不知道你做了什么……但我喜欢这种感觉！"
D.Strings[89293]="噢，你来迟了！那些坏家伙已经毁了这里。"
D.Strings[89294]="我就把你放这儿了。泰克泰克做了他最擅长的事……什么也不做！"
D.Strings[89295]="我想回迷踪岛去，“陛下”。"
D.Strings[89296]="我在阴影中等待着。"
D.Strings[89297]="真见鬼！你拿到了皇帝陛下的法杖！所以你现在跟皇帝陛下一样强了吗？$b$b那我岂不就是美猴王了。$b$b<泰克泰克开心地跳了一小段舞。>"
D.Strings[89298]="回海龟背上去！这里太潮湿了。"
D.Strings[89299]="这就对了。我在藏宝海湾等你！"
D.Strings[89300]="我要——嘶——杀了你。"
D.Strings[89301]="萨吉塔从不抓俘虏。"
D.Strings[89302]="萨吉塔必将摧毁贾德维克。"
D.Strings[89303]="萨吉塔必胜。"
D.Strings[89304]="潮汐主母将血洗贾德维克。"
D.Strings[89305]="萨吉塔将像拍岸的狂潮一样淹没贾德维克。"
D.Strings[89306]="你不该来的。"
D.Strings[89307]="以潮汐主母的名义，我要杀了你。"
D.Strings[89308]="你阻止不了我们，$r。"
D.Strings[89309]="我辜负了萨吉塔。"
D.Strings[89310]="即使我倒下了，还有无数后来者……"
D.Strings[89311]="我要把你像烤鱼一样穿在叉子上！"
D.Strings[89312]="冲上去，杀了他们！"
D.Strings[89313]="马凯斯！有入侵者！"
D.Strings[89314]="马凯斯……"
D.Strings[89315]="萨吉塔必将崛起！"
D.Strings[89316]="为了萨吉塔和我们的女王……"
D.Strings[89317]="把你压成肉泥！"
D.Strings[89318]="可悲的$r。"
D.Strings[89319]="我要向潮汐主母表达我的敬意。"
D.Strings[89320]="你这……废物……点心……"
D.Strings[89321]="我将回归大海……"
D.Strings[89322]="弗加拉什……我还不够……强大……"
D.Strings[89323]="好！成功了！你感觉到了吗？"
D.Strings[89324]="饥渴、愤怒，都消失了。圣光在欢迎我归来。"
D.Strings[89325]="我特意留了这家伙一命以防万一，顺便作为给海巨人们的奖赏。现在，我要杀光你们。"
D.Strings[89326]="你听到了吗？我感觉到前面那座建筑里有什么东西。我们去调查一下吧。"
D.Strings[89327]="你想打架？那就到竞技场里去吧。在这里的话，布里克就挣不到钱了。"
D.Strings[89328]="触碰那些发光的石头，把你自己变得像卵石一样轻。\n\n然后跳进竞技场，祈祷没有人在那里等着你吧。"
D.Strings[89329]="我该怎么下到竞技场去？"
D.Strings[89330]="遵、遵命，夫人！"
D.Strings[89331]="安息吧。我们的新梦境会重建你的世界……"
D.Strings[89332]="我梦到了梦境。现在我醒了……"
D.Strings[89333]="你们要找梦境？它也在找你们。"
D.Strings[89334]="梦境变了。但我仍然会保护它的。"
D.Strings[89335]="梦境总能让我看到真相，它告诉我，你们死定了。"
D.Strings[89336]="呃……这不是玛格拉弗的学生，达格纳吗？"
D.Strings[89337]="呃……这不是玛格拉弗的学生，米妮瓦吗？"
D.Strings[89338]="看到你这样被吊着，我很惊讶。我还以为你会……死得更加……血腥一点。"
D.Strings[89339]="我的头皮好痒。"
D.Strings[89340]="帮矮爆剃头。"
D.Strings[89341]="我的脑袋好冷。"
D.Strings[89342]="制作一张结构图。"
D.Strings[89343]="<咳咳>别猫哭耗子了，斯利文。我还没死呢。"
D.Strings[89344]="道标召唤来了圣光。只要你有需要，我们随时都能响应召唤。"
D.Strings[89345]="<咳咳>少跟我废话，斯利文。我还没咽气呢！"
D.Strings[89346]="我早就明白了，在竞技场里打架要比我在外面打架挣得多。\n\n你绝对看不到我的兄弟们背着我打架的情况。"
D.Strings[89347]="你再次证明了自己的能力，我的朋友。有了萨拉的帮助和这把武器的力量，再没有比你更强大的人了！"
D.Strings[89348]="吉尔伯特已经在那个屋子里呆了好一会儿了……"
D.Strings[89349]="我敢肯定，如果他需要帮助的话，我们会听到尖叫声的。"
D.Strings[89350]="艾泽拉斯所有的教派都答应为新生的教团提供时间和资源。我们的目标只有一个，那就是打败燃烧军团！"
D.Strings[89351]="我在此宣布教团正式成立！我们将携手为盟友带去希望和抚慰，并将敌人赶回虚空！"
D.Strings[89352]="不准在竞技场外面打架！"
D.Strings[89353]="现在，勇士，我们要将这座牢笼转化成我们的战役指挥中心。这要不了多少时间……"
D.Strings[89354]="等我出去，一定要让这些恶魔知道什么叫痛苦！能打开束缚的钥石在一头名叫扎里诺的畜生身上。放我出去，我就帮你杀光这些混蛋！"
D.Strings[89355]="这边！希望你会喜欢我们做出的改动！"
D.Strings[89356]="隐秘通途是在上古之战后成立的，致力于保护艾泽拉斯的人民。我们一直在破碎群岛上防范着燃烧军团的归来。"
D.Strings[89357]="当我们来到这里开始建造神射手营地时，雄鹰之魂欧恩哈拉出现并赐予了我们她的祝福。从那一天起，我们就称这座山为鹰爪峰了。"
D.Strings[89358]="建立隐秘通途的精灵们离开海加尔山、返回破碎群岛后，至高岭的牛头人认同了他们高贵的事业，与他们建立了友谊。胡恩·高岭的后人引导隐秘通途来到了这座山峰。自从燃烧军团归来之后，高岭部族帮我们重建了这个营地，使用牛头人建筑替换了原来的两座损坏的瞭望塔。"
D.Strings[89359]="几百年来，我的大部分同僚都已经牺牲了。只剩下极少数人还在寻找有能力的英雄，希望他们能在这个世界再次需要隐秘通途时响应召唤。"
D.Strings[89360]="到下面去大打一场吧。如果你足够强壮的话，就触摸这块水晶下去吧。"
D.Strings[89361]="竞技场已经开启。如果你足够强壮的话，就触摸这块水晶下去吧。"
D.Strings[89362]="请跟我走走吧，$n。"
D.Strings[89363]="等我自由了，要让这些该死的恶魔知道什么叫痛苦！一头叫扎里诺的畜生有打开这些束缚的钥匙。放我出去，我就帮你杀这些混蛋！"
D.Strings[89364]="你真的认为吉尔伯特能独自对付一头熊吗？"
D.Strings[89365]="如果他没这个本事，我们拿到的宝藏就更多了！"
D.Strings[89366]="一群瞎了眼的家伙。"
D.Strings[89367]="我要碾碎你。"
D.Strings[89368]="我们会修复这些武器。你们阻止不了我们。"
D.Strings[89369]="贾德维克会为此付出代价的。"
D.Strings[89370]="我的任务完成了。"
D.Strings[89371]="监工！快来啊！"
D.Strings[89372]="我诅咒你……"
D.Strings[89373]="这些毛皮一定会让我们发大财的！"
D.Strings[89374]="谁会买它们？它们就像你母亲的胡子一样软！"
D.Strings[89375]="做我们这样的事，你会感觉罪恶吗？"
D.Strings[89376]="萨吉塔会消灭你的！"
D.Strings[89377]="我没时间谈什么感情。"
D.Strings[89378]="潮汐主母……"
D.Strings[89379]="或许我们应该放过那些幼崽。我不会告诉伯德里克的……"
D.Strings[89380]="冰冷的沙砾……"
D.Strings[89381]="你要再这么说话，我就把你关进笼子里去！"
D.Strings[89382]="卑微的弱者……"
D.Strings[89383]="你知道的，合成皮草没这么残忍，更不用说它们更舒适了。"
D.Strings[89384]="如果你不懂什么叫言简意赅，那就闭上你的嘴！"
D.Strings[89385]="你有没有想过， 伯德里克用我们抓来的熊崽干什么去了？"
D.Strings[89386]="伯德里克是不会为了好奇心葬送我们两个的。"
D.Strings[89387]="这个活儿太费精神了。我的腿疼，我的肩膀疼，连我的心也有点疼……"
D.Strings[89388]="自从跟你搭档之后，我的耳朵就疼得不行。"
D.Strings[89389]="把水晶给我。"
D.Strings[89390]="我从一个地底之王的手下那里偷了一块能量宝石。$b$b使用这块宝石，你就可以获得一个听命于你的水晶之怒了。$b$b请你用它到水晶裂隙那里多弄点水晶回来。有了那些水晶。我和我的部族就可以更好地协助雷霆图腾……无论他们想做什么。$b$b那就这么说定了？"
D.Strings[89391]="我觉得你活着对我们会更有用。很好，让我们尽快搞定这一切吧。"
D.Strings[89392]="总算拿到钥石了！我们回去吧。"
D.Strings[89393]="啊！这下好多了！"
D.Strings[89394]="听着！我们没多少时间。他们把玛格拉弗带到城堡去了。我们得冲进去，把他救出来！"
D.Strings[89395]="消灭……所有……生命……"
D.Strings[89396]="仪式中断了，黑暗能量正在汇聚！"
D.Strings[89397]="很好！现在，展示一下你的技巧，同时对付两个敌人吧。"
D.Strings[89398]="你学得很快！接下来……等等，那是……拿起武器！燃烧军团来了！"
D.Strings[89399]="是地狱火！用你学到的技巧击败它！"
D.Strings[89400]="我们没时间了！玛格拉弗被带到了城堡里。据我观察，能从那儿离开的只有恶魔和尸体！得冲进去，把他救出来。"
D.Strings[89401]="杀了他们，别让他们登上邪能之槌号。"
D.Strings[89402]="滚开，恶棍！"
D.Strings[89403]="为了苏拉玛！为了艾利桑德！"
D.Strings[89404]="防线被攻破了……"
D.Strings[89405]="你们会变成食物，会变成奴隶，但迟早都得死。"
D.Strings[89406]="屈服于这饥渴吧。"
D.Strings[89407]="现在，你属于我了！"
D.Strings[89408]="没有人能抵抗我的饥渴！"
D.Strings[89409]="无尽的饥渴……"
D.Strings[89410]="祭坛完成了，贝蒂尔德。"
D.Strings[89411]="你真是个奇迹，萨拉。这比我设计的还要好！"
D.Strings[89412]="我们是荒野中的守望者。"
D.Strings[89413]="我们是风中的雄鹰。"
D.Strings[89414]="我们的道路注定孤独……"
D.Strings[89415]="因为我们是隐秘通途。"
D.Strings[89416]="海拉对你另有打算，走狗。"
D.Strings[89417]="骨头比较合适你。"
D.Strings[89418]="感谢你让我重获自由，$n。$b$b不幸的是，灵魂收割器夺走了我的许多力量，但我很快就会彻底恢复的。"
D.Strings[89419]="这位是佳莉娅·米奈希尔……对，就是那个米奈希尔。她这些年帮了我们大忙。希望她能协助您救援无助之人，将您的福音散播到全世界。"
D.Strings[89420]="真正的欺诈者的双刃看起来更加震撼。"
D.Strings[89421]="他们让我来收拾地底之王的烂摊子。可看看这些，我一辈子都干不完呐。"
D.Strings[89422]="去过破碎海岸了，嗯？我知道你接着该去哪儿，泽奥姆斯会送你去的。"
D.Strings[89423]="杀了恐翼之后，你要想找我……就跟着恶魔的尸体走。"
D.Strings[89424]="我知道你不是这些纳迦的盟友，$r！快放我出去！"
D.Strings[89425]="我必须找到索迪尔族长！"
D.Strings[89426]="你不是纳迦？布兰多夫呢？"
D.Strings[89427]="布兰多夫还活着！我必须找到他！"
D.Strings[89428]="我马上开启传送门，亲爱的。退后。"
D.Strings[89429]="来吧，$n！我会和你并肩作战，在这些纳迦中杀出一条血路来！"
D.Strings[89430]="发誓"
D.Strings[89431]="恶魔，带我去找你的主子，我就饶你一命。"
D.Strings[89432]="扎克，让我喊点什么！"
D.Strings[89433]="又有晶化兽冲过来了，站稳了！"
D.Strings[89434]="我在搜集有关布林顿发明者的情报。"
D.Strings[89435]="燃烧军团完全不懂得仁慈或怜悯。如果我们要打败这个威胁，就必须同样抛弃这些念头。"
D.Strings[89436]="我要亲自解决它！"
D.Strings[89437]="燃烧军团抢走了我的武器，所以我也要抢他们的。"
D.Strings[89438]="布林顿的发明者？唔，这是个好问题！$b$b据说，他是一个又高又壮的家伙，“大约有四个侏儒那么高，有着粗壮的胳膊，能提着他的发明四处走。$b$b他有着美丽的紫色鬓角，眼中闪着电光！$b$b呃……反正我的表姐莉吉特就是这么跟我说的。$b$b如果你还想知道更多的话，就去问她吧，她知道接下来的故事。你可以在风暴峭壁的K3找到她。"
D.Strings[89439]="快看天上！是欧恩哈拉！雄鹰之灵回来了！"
D.Strings[89440]="我的战斧……还有我的宠物……都愿意为你而战，$n。"
D.Strings[89441]="噢，那个老掉牙的传说？当然，如果你想听的话，我当然可以再跟你说一遍。$b$b<莉吉特举起双手，用一种深沉的语气说了起来。>$b$b传说，他像邪能机甲一样高大，长着一张足以吓坏死亡之翼那个老东西的脸。他们说他在制造布林顿时丢了一条胳膊。后来，他用一辆蜘蛛坦克代替了这条胳膊！$b$b<莉吉特咯咯笑了起来。>$b$b事实上，我最后一次听到他的消息，是在棘齿城认识的一个水手告诉我的。那个水手当时已经烂醉如泥了，但我觉得还是有那么一点可信度的。$b$b他叫首席工程师福特。他或许能告诉你究竟该去哪里找那个发明者。"
D.Strings[89442]="$n！总算找到你了！我需要你的帮助。"
D.Strings[89443]="很好，你来了。我们还有个逃跑的恐惧魔王要解决呢。"
D.Strings[89444]="我们没多少时间了。恶魔现在肯定已经发现熔炉了。我去紫罗兰监狱等你。"
D.Strings[89445]="看来那个恐惧魔王已经领先一步了。快，通道在这边！"
D.Strings[89446]="结束了，恐惧魔王。你的邪恶统治完了！"
D.Strings[89447]="嗝儿！你要……嗝儿！你想要……嗝儿！你想要问布林顿的事？$b$b噢，当然，没错没错。好吧，那么，我是在喝酒，唔……嗝儿！噢，对了！$b$b我在加基……加基……加基斯坦喝酒的时候，跟那个绿皮肤的小个子谈起过他。靠近点。$b$b<首席工程师福特招手让你靠近点，然后在你耳边大吼道。>$b$b那个家伙叫尼克斯·斯普克斯宾。哈哈！他还告诉我，让我告诉你，说……嗝儿！$b$b噢，我忘了。好了，别来烦我了，好吗？"
D.Strings[89448]="可悲的废物！你该带支军队来！在纳斯雷兹姆面前，一个小小的法师能做什么呢？"
D.Strings[89449]="守护者熔炉是属于我的！"
D.Strings[89450]="可怜虫！你那软弱的法术阻止不了我！"
D.Strings[89451]="他太强了！我们需要熔炉的力量！"
D.Strings[89452]="想办法穿过他的屏障！我会缠住他的。"
D.Strings[89453]="我不会让你轻易逃脱的，小法师！"
D.Strings[89454]="干得好！现在，摧毁吸收熔炉能量的裂隙！"
D.Strings[89455]="成功了！快激活熔炉！"
D.Strings[89456]="你看起来是个明白人，所以我可以告诉你一条重大的消息 。忘了它吧！$b$b布林顿是一个卑鄙、肮脏，根本不懂工程学的矮鬼侏儒发明出来的。$b$b你千万别去东南边的塔纳利斯南海拜访他的孙女温琪，她比他还要不如呢。"
D.Strings[89457]="事实上，我来是询问有关你祖父的事的。"
D.Strings[89458]="接受我的力量，勇士！把这个恶魔赶回老家去！"
D.Strings[89459]="我已经受够你了，邪风。去死吧！"
D.Strings[89460]="蠢货！军团会得到你的秘密……"
D.Strings[89461]="等死吧，法师。我会回来的！"
D.Strings[89462]="阿洛迪！"
D.Strings[89463]="很高兴见到你，老朋友。要是局势能好一些就更好了。"
D.Strings[89464]="我的祖父，诺佩托·熔索是个伟大的发明家。你可能听说过他唯一的发明，布林顿。$b$b人人都想知道他是怎么设计布林顿的内部电路的，可他不愿意分享这个秘密。$b$b他许多年前就死了，一场海啸吞噬了他的店铺。我不认为你还能找到什么东西，但如果你坚持的话，可以自己游过去看。$b$b如果你需要的话，还可以借用我的潜水设备。"
D.Strings[89465]="那个恐惧魔王只是暂时败退。等他在扭曲虚空中恢复了力量，就会再来抢夺熔炉的。"
D.Strings[89466]="我知道该怎么做了……"
D.Strings[89467]="银色盟约与你同在！"
D.Strings[89468]="远行者发誓将为你而战！"
D.Strings[89469]="你需要再放一波鱼人出去吗，$n？尽管下令吧。$b$b我们还剩了好多鱼卵……单独行动的鱼人很容易被消灭。可一大群鱼人就势不可挡了。"
D.Strings[89470]="放出鱼人！"
D.Strings[89471]="这个金苹果品质不错，希尔弗纳。"
D.Strings[89472]="抱歉，为了修好那辆马车，我还得问一下，那个拿走车轴的乔方呢，希尔弗纳？"
D.Strings[89473]="是洛休斯派我来的。你愿意帮我关闭传送门吗？"
D.Strings[89474]="黑麦酒就快没了，希尔弗纳。要是梅尔芭还在这儿的话，我们绝对不会缺酒的。"
D.Strings[89475]="你是来找梅尔芭的吗？我是她的学徒，但我师傅不在。"
D.Strings[89476]="你迟到了两年，我的朋友，梅尔芭已经死了。"
D.Strings[89477]="来吧，武僧。跟我走。"
D.Strings[89478]="我师傅的配方以美味醇厚著称。我们以前每天都要卖出好多桶。甘冽清爽的金苹果，暗沉苦涩的黑麦酒，还有散发着橡木清香的木之心。"
D.Strings[89479]="附近一个部族的首席酿酒师，莫尔金一直很嫉妒我师傅的技术。他派了一群强盗来杀害她，并偷走了她的配方。"
D.Strings[89480]="莫尔金拿到了配方，但他没那个技术。你在勇者之门喝到的根本就是泔水。它的效力还不及风暴蜜酒的万分之一。"
D.Strings[89481]="梅尔芭的风暴蜜酒是她所有的秘方中最稀有也最受追捧的。据说，就连雷神奥丁也会在他的圣殿中享用这种酒。"
D.Strings[89482]="蠢货！你的脑子都烂成渣了吗？燃烧军团的魔法很容易躲避的。"
D.Strings[89483]="你还在等什么？快走吧！"
D.Strings[89484]="嗷！！！嗷！！！"
D.Strings[89485]="我们找到想要的东西了，但我得在离开之前加强卡拉赞的防御。我欠麦迪文的太多了……在变成萨格拉斯的棋子之前，他是个很好的人。"
D.Strings[89486]="我必须返回贾德维克了。"
D.Strings[89487]="我将践踏你的尸体！"
D.Strings[89488]="我今天就送你去见你的先祖！"
D.Strings[89489]="我是维库人！你死定了！"
D.Strings[89490]="光明消逝了……"
D.Strings[89491]="英灵殿……"
D.Strings[89492]="你的手，带来了我的末日……"
D.Strings[89493]="我的剑断了！"
D.Strings[89494]="审判降临了……"
D.Strings[89495]="我的法杖断了……"
D.Strings[89496]="我诅咒你的灵魂！"
D.Strings[89497]="死在我的法杖下吧！"
D.Strings[89498]="卡尔德是个固执的蠢货……"
D.Strings[89499]="艾纳尔没有预见到……"
D.Strings[89500]="我需要一个外来者……"
D.Strings[89501]="连我都完不成这样的壮举……"
D.Strings[89502]="我将成为族长。"
D.Strings[89503]="这是什么？一个偷听我们说话的入侵者。"
D.Strings[89504]="我们必须通知潮汐主母……"
D.Strings[89505]="我们这儿来了一位不速之客。"
D.Strings[89506]="贾德维克必将属于我们……"
D.Strings[89507]="我的死阻止不了什么……"
D.Strings[89508]="我会像杀鱼一样宰了你。"
D.Strings[89509]="贾德维克是属于我们的。"
D.Strings[89510]="我们的敌人都得死！"
D.Strings[89511]="萨吉塔，攻击！"
D.Strings[89512]="为了潮汐主母……"
D.Strings[89513]="深海的寂静……"
D.Strings[89514]="大海在召唤我……"
D.Strings[89515]="你阻止不了我们。"
D.Strings[89516]="黑暗的深海……"
D.Strings[89517]="你还在耽搁什么？走啦！"
D.Strings[89518]="又是一道该死的屏障！掩护我……我们可能又要跳一次了。"
D.Strings[89519]="又来了一大群恶魔！"
D.Strings[89520]="屏障消失了。快走！"
D.Strings[89521]="愚蠢的凡人！你们这么急着变成我的下一顿美餐吗？"
D.Strings[89522]="好吧！这个囚犯没用了。它的血液太过稀薄浑浊。"
D.Strings[89523]="又来了！拦住他们！"
D.Strings[89524]="按下开关"
D.Strings[89525]="我们是来杀恶魔的，而不是来救完不成任务的失败者的。"
D.Strings[89526]="我不在乎！我们的首要目标是杀恶魔。来吧，我们已经在这场战斗上浪费了太多的时间。"
D.Strings[89527]="什么！？你对同伴还有没有一点责任感了？"
D.Strings[89528]="什么！？你对你的骑士同伴还有没有责任感？"
D.Strings[89529]="斯利文，你混蛋！好！我帮你！可一有机会，我就去救玛格拉弗！"
D.Strings[89530]="谢谢你，奥丁。我还以为我是鱼饵呢。"
D.Strings[89531]="愿英灵殿永远照耀着你。"
D.Strings[89532]="噢，我的天，这可真够乱的。我要走了。"
D.Strings[89533]="我已经帮助经历了兔妖之祸的大箩农场村民恢复了元气。$B$B陈跟我说过神真子的故事，可我从没想过这只海龟会这么大！"
D.Strings[89534]="我很明白失去亲人的痛苦。这正是我加入战斗的原因，再说这里的酒也不算坏。"
D.Strings[89535]="你能给我一只空桶吗？"
D.Strings[89536]="你有啤酒花和酵母吗？"
D.Strings[89537]="陈让我来要点蜂蜜。"
D.Strings[89538]="我们很快就要走了，雅丽亚。"
D.Strings[89539]="我要把你送下海底。"
D.Strings[89540]="你休想阻止萨吉塔！"
D.Strings[89541]="你必将倒在萨吉塔脚下！"
D.Strings[89542]="去吧。让陈小心点。我们已经在和燃烧军团的战斗中失去了太多同胞。"
D.Strings[89543]="你真是个冷血动物，斯利文。很好！我可以帮你，可只要有一点救出玛格拉弗的机会，我们就要抓住它。"
D.Strings[89544]="那个可怜的孩子。寺院给他的担子太重了，可他只想跟雅丽亚好好过日子。"
D.Strings[89545]="这些补给品应该够了。告诉陈，祝他一路顺风。"
D.Strings[89546]="陈！你要去哪儿了吗？"
D.Strings[89547]="我做好战斗的准备了，蒂迪！"
D.Strings[89548]="这个桶应该能用。陈又出去执行任务了吗？"
D.Strings[89549]="这是一场野蛮的战争。我们要利用一切能够得到的优势。"
D.Strings[89550]="你会死在这个洞穴里的，$r！"
D.Strings[89551]="潮汐主母……我辜负了你……"
D.Strings[89552]="我可能……需要帮助！"
D.Strings[89553]="愿雄鹰之魂指引你的双手。"
D.Strings[89554]="我们的机会来了！打倒他！"
D.Strings[89555]="这个祭坛是从哪儿来的？"
D.Strings[89556]="据说这个祭坛是用胡恩·高岭亲手从永恒猎场带回来的一块石板刻成的！$b$b这块石头能够与来自那座神圣猎场的生物的生命力共鸣。$b$b在神射手营地建立之后，胡恩的后裔就将这块石头雕刻成祭坛以表达对雄鹰之魂欧恩哈拉的崇敬，并把它送给了隐秘通途的成员。"
D.Strings[89557]="这个祭坛有什么用？"
D.Strings[89558]="这座祭坛汇聚了种种古老的力量……荒野诸神、守护者，甚至包括精灵的魔法井。$b$b某些古老的圣物可以接受这些力量的灌注，变得更加强大。你的武器就属于这种圣物。$b$b你可以把这座祭坛想成这些古老力量的导管。只要一有机会，就回来使用它吧，你需要利用一切优势来带领我们战胜燃烧军团！"
D.Strings[89559]="里弗斯准备接受驾驶。"
D.Strings[89560]="我是来找酿酒大师梅尔芭的。"
D.Strings[89561]="冷静！你冷静点！我想那个维库人很快就会离开的！"
D.Strings[89562]="卑微的蝼蚁。"
D.Strings[89563]="萨吉塔的敌人。"
D.Strings[89564]="葬身海底吧！"
D.Strings[89565]="我要像碾碎蛤蜊一样碾碎你。"
D.Strings[89566]="现在……死亡……"
D.Strings[89567]="萨吉塔长存……"
D.Strings[89568]="回归……深海……"
D.Strings[89569]="回归深海……"
D.Strings[89570]="奈特扎尔会……杀了……你的……"
D.Strings[89571]="很好，现在让我们离开这儿吧。巫妖王还在焦急地等待着我们成功的消息呢。"
D.Strings[89572]="接受痛苦的试炼吧，老朋友。"
D.Strings[89573]="可怜的玛格拉弗！你总算得到永恒的安息了。"
D.Strings[89574]="让他们看看里弗斯的本事吧！"
D.Strings[89575]="其实，蒂迪，我还有其他事情要做。"
D.Strings[89576]="|TInterface\\Icons\\Spell_Shadow_CreepingPlague:20|t尼珊德拉的|cFFFF0404|Hspell:203096|h[溃烂]|h|r感染了你！"
D.Strings[89577]="我告诉斯利文男爵你会来的，可他还是跑了。那个蠢货会害死他自己的！"
D.Strings[89578]="我们已经守住了传送门的这一边。"
D.Strings[89579]="就是这里。被偷走的配方肯定在这里。"
D.Strings[89580]="对，这酒的劲儿可真大！但我师傅的酒更好一些。"
D.Strings[89581]="唔。味道不错，可淡得像水一样。"
D.Strings[89582]="呃，奥丁之母在上！比符角牛的奶还难喝！"
D.Strings[89583]="我的耐心耗尽了。你的主子藏在哪儿？"
D.Strings[89584]="不要相信你的头脑！"
D.Strings[89585]="把我从牢笼里放出去！"
D.Strings[89586]="看着，我要让你服从我的意志！"
D.Strings[89587]="黑暗将吞噬一切！"
D.Strings[89588]="品尝"
D.Strings[89589]="你能听见吗，朋友？"
D.Strings[89590]="这边，我的朋友！"
D.Strings[89591]="哈维没说过他们会这么矮！"
D.Strings[89592]="看！潮汐之石！"
D.Strings[89593]="那个老先知很疯，但很少犯错。来吧，“朋友”，恶魔又来了！证明你的勇气吧！"
D.Strings[89594]="新犯人！你会藏着什么美味的秘密呢？"
D.Strings[89595]="哈格里姆！奥瑞克！奥丁认为你们有资格进入圣殿。跟我去接受荣耀吧！"
D.Strings[89596]="还有……那么多……秘密……"
D.Strings[89597]="这里还有许多英勇的战士，可我无法接引他们前往英灵殿。西边有个恶魔禁锢了他们的灵魂。小家伙，去解放他们，以证明你的力量吧！"
D.Strings[89598]="这是你一个人的任务，不要让奥丁久等！"
D.Strings[89599]="我们得为下一场战斗做准备了。时间不多，所以动作快点！"
D.Strings[89600]="奥丁的意志不容违逆。你们三位有资格进入他的圣殿，这位战士救出了你们。现在，跟我一起去迎接荣耀吧！"
D.Strings[89601]="来了个大家伙，小英雄！来迎接你的命运吧，别让你的位置被顶了！"
D.Strings[89602]="我差点就出汗了……但还没有！他们还有什么本事？"
D.Strings[89603]="喔……那是什么？"
D.Strings[89604]="呃……你能不能看看那个……"
D.Strings[89605]="哈维答应过我的荣耀之死终于降临了！"
D.Strings[89606]="我提议改杀恶魔！小英雄，你已经证明了自己。你愿意跟我们一起来吗，哪怕是要付出生命？"
D.Strings[89607]="哈！只要联手，我们或许能胜利！但无论如何，我是绝不会轻易倒下的。我们动手吧！"
D.Strings[89608]="我会在英灵殿赞颂你们……或是踩着这怪物的尸体欢呼！"
D.Strings[89609]="我还能……战斗……"
D.Strings[89610]="继续战斗，英雄……英灵殿还在等着我……"
D.Strings[89611]="拉格瓦尔德，菲娜，你们有资格进入奥丁的神殿。跟我一起去迎接荣耀吧！"
D.Strings[89612]="你不是英灵，也不是维库人，但奥丁也召唤了你。我不知道他的圣殿里有什么在等着你，但我相信你配得上这份荣耀……"
D.Strings[89613]="跟我来。我们必须找到其他人。"
D.Strings[89614]="见证欺诈者双刃的力量吧！邪能之槌号是属于我们的！"
D.Strings[89615]="我们将是斩杀燃烧军团的尖刀，是伊利丹大人挑选出来的战士。"
D.Strings[89616]="我们是伊利达雷！"
D.Strings[89617]="这边走。"
D.Strings[89618]="我已经开启了里弗斯的驾驶战斗模式。你准备好之后就激活它吧，$n。"
D.Strings[89619]="拴住这些锈皮鼠！"
D.Strings[89620]="全体上甲板！"
D.Strings[89621]="干掉这些旱鸭子！"
D.Strings[89622]="没有猎物，就没有报酬！现在，守住纳格法尔号！"
D.Strings[89623]="烧光！杀光！抢光！"
D.Strings[89624]="守护者圣殿！它的破败让我很难过。"
D.Strings[89625]="这座大厅在提瑞斯法议会解散后就被废弃了。"
D.Strings[89626]="保护此地的结界仍然很强。它应该符合我们的要求。"
D.Strings[89627]="我打算重建秘法会。这位法师将成为它的首位勇士。"
D.Strings[89628]="你怎么说，$n？"
D.Strings[89629]="欢迎来到邪能之槌号，$n。"
D.Strings[89630]="等你拿到神器，就立刻回来，$n。与此同时，我也会把这里整理一下。"
D.Strings[89631]="荣耀竞技场，是战士们比拼勇武的地方。穿过这里，前方就是蜜酒大厅，美酒与传说流淌之地！"
D.Strings[89632]="赫达沙尔堡垒就在南边。我在那儿等着你。希尔弗纳飞得比风还要快。"
D.Strings[89633]="风暴蜜酒的秘密是属于我的！你们休想得到它！"
D.Strings[89634]="不……我再也没机会……解开这个秘密了……"
D.Strings[89635]="我要开始占卜了，你做好保护我的准备了吗？"
D.Strings[89636]="这边。部队在等着你呢。"
D.Strings[89637]="那个夜之子骗了我们。月之守卫很快就会消亡。"
D.Strings[89638]="邪能之槌号终于归我们了。看看欺诈者双刃的力量吧！"
D.Strings[89639]="荣耀属于伊利达雷！"
D.Strings[89640]="蔑潮部族全都是冷酷的小偷和杀人犯。"
D.Strings[89641]="我的师傅，梅尔芭，对我倾囊相授，包括古代维库酒王和女王们的战斗技巧。"
D.Strings[89642]="真希望梅尔芭此刻能看见我。我一直在等待复仇的机会！"
D.Strings[89643]="我们将听从你的意志，淹没燃烧军团。"
D.Strings[89644]="我就说了……"
D.Strings[89645]="你能别再插嘴了吗，纳迦？"
D.Strings[89646]="哈布隆不会容忍你这种存在的，凡人。"
D.Strings[89647]="小心！这是个骗子！"
D.Strings[89648]="贾德维克是不会输给你们这些邪恶的纳迦的！永远不会！"
D.Strings[89649]="物品升级"
D.Strings[89650]="没有谁会嫌恶魔“死得太多”的。"
D.Strings[89651]="让我看看我们的战利品。"
D.Strings[89652]="我死后，奥丁允许我进入他传说中的英灵殿。他的战士将在这里欢宴庆祝永恒的荣耀。而我则为他的勇士们酿造他们最喜欢的美酒。"
D.Strings[89653]="阿洛迪，帮帮我们。我们得把守护者熔炉送到更安全的地方去。"
D.Strings[89654]="想打败燃烧军团，就需要它的力量。"
D.Strings[89655]="你应该感到骄傲，$n。你差点就拯救了贾德维克。现在，你会死在这个洞里，无论是布兰多夫还是贾德维克，都不会知道你是为什么没能阻止萨吉塔的！"
D.Strings[89656]="哇，小鬼！你也太心急了一点！"
D.Strings[89657]="玛法里奥，我的老朋友……多么完美的诱饵！"
D.Strings[89658]="啊，梦境之母总算到了。"
D.Strings[89659]="欢迎，$c！这片位于大漩涡边缘的元素之地就是艾泽拉斯之心，是萨满教义中最神圣的地方。在这个房间里，那些自称掌控了元素的人将面对一系列挑战，测试他们的精神力。$b$b但对你来说，这不算什么。$b$b简直就是小菜一碟。"
D.Strings[89660]="啊，当然可以！请这边走。"
D.Strings[89661]="要想与元素和谐共鸣，你必须研究并理解它们之间的交互作用。图腾迷阵是一种古老的训练方法，一种挑战你头脑和精神力的谜题。$b$b目标是将所有图腾都变成水图腾。触摸图腾就可以转化它。记住，万事万物都是互相关联的，这就是这个谜题教给你的最宝贵的一课……也是你一生中最重要的一课！"
D.Strings[89662]="你将会看到一个五纵五横的元素图腾迷阵。里面有火图腾，也有水图腾。你的目标就是把它们都变成水图腾。$b$b你只要触摸图腾就可以转变它的属性。啊，但元素是互相关联的！触摸图腾也会转变与它相邻的四个图腾的属性。$b$b经过耐心的尝试，也许还会犯一些错，你一定可以将所有图腾变成水图腾的。加油吧，$c！$b$b如果你感觉自己彻底失败了，就跟我说，我可以帮你重置迷阵。"
D.Strings[89663]="你返回黑暗神殿后，军团的增援就到了，他们摧毁了你的传送门。那真是一场精彩的大战！"
D.Strings[89664]="图腾迷阵在等着你，$c！触摸图腾来转变它以及它周围图腾的属性，将所有图腾都变成水图腾吧。"
D.Strings[89665]="我现在明白你为什么会响应召唤成为萨满了，$n。你对于万物的内在联系有着一种天生的直觉。$b$b你准备好迎接更加困难的挑战了吗？"
D.Strings[89666]="我很吃惊。你不仅仅是个萨满……你是元素的大师，元素的艺术家！艾泽拉斯就是你的画布。$b$b迄今为止所有的挑战都达到了内在的平衡。但你也知道，这种排序很少会出现在自然界。在面对不对称的挑战时，你又会有怎样的表现呢？"
D.Strings[89667]="自从凡人种族有历法以来，图腾迷阵这种训练方式就诞生了。很久很久之前，我们用的不是图腾。而是把侏儒架在火上烤。呵呵，这只是个玩笑，萨满。你就尽管笑吧。$b$b下一个挑战虽然看似简单，但却能真正测出你的实力。"
D.Strings[89668]="后来，我们发现了上古纳斯雷兹姆熔炉，它曾铸造出燃烧军团最强大的武器。"
D.Strings[89669]="最后一个挑战非常困难，旨在考验你作为萨满的韧性。这个谜题难倒了我的父亲。如果你能成功，就说明你有足够的精神、智慧和韧性来克服生命中可能遇到的任何挑战……至少这个房间里的挑战是难不倒你了。$b$b当命运青睐我们时，保持坚强并不困难。真正的考验是，当四处着火时，你又能有怎样的表现呢……"
D.Strings[89670]="我这里已经没有挑战了，萨满。训练和练习只能让你走到这一步了。从现在起，你必须在外面的世界里完善你的技巧了。$b$b<谜题大师老罗再次陷入了深层冥想中。>"
D.Strings[89671]="告诉我规则吧。"
D.Strings[89672]="我准备好接受第一个挑战了。开始吧！"
D.Strings[89673]="我准备好接受第二个挑战了。开始吧！"
D.Strings[89674]="我准备好接受第三个挑战了。开始吧！"
D.Strings[89675]="我准备好接受第四个挑战了。开始吧！"
D.Strings[89676]="开始最后的挑战吧！"
D.Strings[89677]="我卡住了！帮我重置一下谜题好吗？"
D.Strings[89678]="之后，我们就一直小心守护着它。它应该会对你有用。"
D.Strings[89679]="我明白了。开始挑战吧！"
D.Strings[89680]="让我们再试一次……这次别再傻笑了！"
D.Strings[89681]="Mr grlrlgl……等等……不是吧？呃，我没想到我还会有伴儿……"
D.Strings[89682]="Mrglrrlrlg！我是说，你好！抱歉，我跟这些鱼人生活得太久了，久得超出了预期。"
D.Strings[89683]="你干嘛要穿成那样？"
D.Strings[89684]="这不是很明显吗？这些鱼人被赶出了家园！我们不能任由它们自生自灭！"
D.Strings[89685]="我好像忘了你是从什么地方来的了？"
D.Strings[89686]="这不是我第一次潜水了……我只希望仁德会能多关心一下温水鱼人。"
D.Strings[89687]="我要把这家伙的脑袋挂在我的墙上！"
D.Strings[89688]="你会是一个很好的猎物！"
D.Strings[89689]="我可是枪枪致命！"
D.Strings[89690]="你会为闯入这片土地后悔的！"
D.Strings[89691]="我会好好享受猎杀你的过程的！"
D.Strings[89692]="记住，无论你把谜题弄得多么乱，最后总是有办法解决它的，图腾如此，生活同样如此。认识到这一点或许会让你觉得欣慰一些。$b$b但是，新的开始有时也是大有裨益的。"
D.Strings[89693]="很高兴听到你这么说。我能再试一次吗？"
D.Strings[89694]="|TInterface\\Icons\\Spell_Frost_SummonWaterElemental_2.blp:20|t%s开始施放|cFFFF0000|Hspell:202098|h[死水弹幕]|h|r。小心！"
D.Strings[89695]="$n！你跑得可真快，我们总算找到你了。"
D.Strings[89696]="我们听说你在寻找传说中的风暴蜜酒所需的原料。"
D.Strings[89697]="我能感觉到陈内心的矛盾。他渴望有一个家庭，也渴望能为和平而战。他觉得自己只能从中选一个，但这是错误的。"
D.Strings[89698]="职业大厅的训练进展顺利，你知道了一定很高兴吧？"
D.Strings[89699]="他必须决定自己到底要不要爱情。爱一个人就要接受对方的全部。爱情不仅仅是快乐，也有痛苦。"
D.Strings[89700]="我们很高兴能帮上你的忙，$n。"
D.Strings[89701]="<艾维娜用异常锐利的目光扫视着地平线。>\n\n我们必须控制住被你称为隼龙的那种鸟类，这是自然的平衡之道，这没错。\n\n但我也必须完成我的复仇。\n\n凡人休想随意屠杀我的孩子而不受惩罚。你必须让他们明白，我的羽翼覆盖着这片土地，且永无尽头。\n\n你就是我的利爪。\n\n如果你接受这个任务，那就收下我蜕下的爪子，以我的名义去复仇吧。"
D.Strings[89702]="<见你走近，艾维娜眯起了双眼。>\n\n我知道你做了什么。我看到你身后有一条铺满碎羽和断喙的血路。\n\n<艾维娜的羽毛明显竖了起来。>\n\n你有什么想辩解的吗？"
D.Strings[89703]="在我的国度，刚学会展翅的雏鸟就会被丢出巢穴。学不会飞行的小鸟都得死。\n\n我为受我庇护的德鲁伊创造了一个考验灵活性的试炼。你想试试吗？\n\n有了我的祝福，你就能优雅地漂浮在空中……但那只是暂时的。"
D.Strings[89704]="我愿意成为您的复仇之爪。"
D.Strings[89705]="我明白。我能帮上什么忙吗？"
D.Strings[89706]="<艾维娜完全展开长度惊人的双翼，像看一只老鼠一样看着你。>\n\n你想跟我谈自然的法则？我是狂风和荒野的代言人，孩子。别来教训我。\n\n<她停顿了片刻，身上的羽毛平顺了下来。>\n\n但我明白你的选择是睿智的，我看到了你的善意。\n\n<她看了看你的隼龙坐骑，接着又把视线移回到你身上：>\n\n你为这头龙后和她的子嗣们做了一件好事。但你对它们的同类犯下的罪行同样不能不罚，你明白吗？"
D.Strings[89707]="隼龙的繁殖速度失控了，附近的其他食肉动物都在挨饿。"
D.Strings[89708]="我想尝试一下飞行挑战，请赐予我你的祝福。"
D.Strings[89709]="好像有点不对劲……"
D.Strings[89710]="这是幻象！你在掩饰什么？"
D.Strings[89711]="嘿，$n，我们总算赶上你了！我们听说了你的情况，也想助你一臂之力。"
D.Strings[89712]="我该如何完成你的试炼？"
D.Strings[89713]="<艾维娜用看猎物一样的表情看着你。>\n\n我要在这里闻到他们的血腥味，我的利爪。\n\n看到你身后的渡鸦汀奇了吗？如果你在狩猎途中需要补给，他可以帮你找到各种有用的小玩意儿。"
D.Strings[89714]="剩下的伊利达雷不会来这里打扰你的。"
D.Strings[89715]="无论你要打什么样的猎物，我这儿有一样武器肯定能让你如愿以偿。"
D.Strings[89716]="我会赐予你祝福，让你可以缓缓飘向地面。在下降过程中，你要尽可能多地收集翡翠之球。\n\n很少有雏鸟能在第一次试飞中收集到大量翡翠之球。但大部分都能活下来，并再次挑战。\n\n如果你能在试炼中收集到所有翡翠之球，我就会给你一些额外的奖励。"
D.Strings[89717]="你的出现让这只生物咆哮了起来。"
D.Strings[89718]="这些水晶够了吗？好吧，我们回职业大厅去吧。"
D.Strings[89719]="燃烧军团的袭击越来越频繁了。我们得加紧酿造风暴蜜酒了，越快越好。"
D.Strings[89720]="这家伙肯定没想到自己会是这种下场。"
D.Strings[89721]="这个线圈放出的电流太强了。你可以在设施的另一头找到低能线圈。"
D.Strings[89722]="翻转图腾，直至其都变成水图腾。"
D.Strings[89723]="|TInterface\\Icons\\Spell_Shadow_Teleport:20|t%s|cFFFF0000|Hspell:200898|h[传送]|h|r到附近的牢房并开始释放囚犯！"
D.Strings[89724]="等你返回达拉然后，再来跟我谈谈吧。我们还有很多事情要商量。"
D.Strings[89725]="这两股能量都流向了中央大厅。使用线圈和开关引导能量流，为大厅中的四个封印充能！"
D.Strings[89726]="电流连上了——快接入封印！"
D.Strings[89727]="我准备好接受下一个挑战了！"
D.Strings[89728]="能再跟我说一遍规则吗……？"
D.Strings[89729]="|TInterface\\Icons\\ability_warlock_soulswap:20|t |cFFFF0000|Hspell:200904|h[灵魂侵蚀]|h|r将令你的下一个技能无法使用！"
D.Strings[89730]="挑战完成！$n，你真是个图腾大师！"
D.Strings[89731]="让我们开始酿酒吧！"
D.Strings[89732]="把那些原料扔进锅里。这可能会造成一点小麻烦！"
D.Strings[89733]="嘿！！！你好像需要帮忙啊！"
D.Strings[89734]="雅丽亚！你在这里做什么？这里太危险了！"
D.Strings[89735]="我看危险的只有你吧，陈！"
D.Strings[89736]="呃……你总是能让我大吃一惊，雅丽亚。现在，让我们完成这批酒吧！"
D.Strings[89737]="你开始感觉昏昏欲睡！"
D.Strings[89738]="我们或许已经彻底解除萨吉塔的威胁了。"
D.Strings[89739]="看，燃烧军团进入艾泽拉斯的主要途径……萨格拉斯之墓。"
D.Strings[89740]="情况比我们想的还要糟。恶魔已经扩散到了周围的岛屿上。"
D.Strings[89741]="我们得立即行动，否则局势恐怕会……不可收拾。"
D.Strings[89742]="放心，我们会终结这场战争的。你得回达拉然去，然后立即借道返回破碎群岛。"
D.Strings[89743]="多亏了你的力量，我们可以用邪能之槌号来策划全面进攻了。"
D.Strings[89744]="勇士，要是你打磨完武器了，我有东西要给你看。"
D.Strings[89745]="接入"
D.Strings[89746]="我要开始用我店里的东西修理它了。"
D.Strings[89747]="请跟我来。奥丁之眼是一个强大的占卜及沟通装置。使用它，你就能看到破碎群岛，向你的勇士们发号施令，并制定你自己的行动计划。天空贤者格伦特会帮你操纵它的。"
D.Strings[89748]="您好！我能为您做点什么吗？"
D.Strings[89749]="雅丽亚，我犯了一个严重的错误。无论是什么事——参战、冒险、欣赏日落——没有了你，这一切都没有意义。"
D.Strings[89750]="陈，我不知道你什么时候才能明白过来。"
D.Strings[89751]="你好。我是来考验你的实力的。"
D.Strings[89752]="你准备好开始试炼了吗？"
D.Strings[89753]="快，$n！一定要把我们胜利的消息带回贾德维克！"
D.Strings[89754]="贾德维克的居民们！天大的好消息！快到火塘这儿来听听吧！"
D.Strings[89755]="我想雇佣一名私人保镖。"
D.Strings[89756]="你知道吗……我听说你要是把这些东西从很高的地方扔下去，它们会砸死人的。"
D.Strings[89757]="下水道守卫可以保护你不受其他玩家的攻击，持续5分钟。\n\n确定要雇佣保镖吗？"
D.Strings[89758]="萨吉塔已经杀害了我们太多的同胞。卡尔德，艾纳尔和索迪尔族长都死在了他们的阴谋诡计之下。"
D.Strings[89759]="向光荣的战死者们致敬！"
D.Strings[89760]="贾德维克得救了，我们都欠这个勇敢的$c一份人情。荣耀属于$n！杀死潮汐主母萨吉塔的人！"
D.Strings[89761]="作为贾德维克硕果仅存的长老，我有责任带领贾德维克走向繁荣。"
D.Strings[89762]="因此，我宣布$n成为贾德维克的新族长。一起来为$n欢呼吧！"
D.Strings[89763]="你还没有做好参加试炼的准备。"
D.Strings[89764]="我们还有什么可扔的吗？"
D.Strings[89765]="我好像打中了什么东西……"
D.Strings[89766]="$n族长万岁！万岁！"
D.Strings[89767]="我必须去提瑞斯法林地找回一件神器。"
D.Strings[89768]="向死者们致敬！"
D.Strings[89769]="$n万岁！贾德维克的救星万岁！"
D.Strings[89770]="伊利丹大人一定会满意的。"
D.Strings[89771]="我们将亲手埋葬燃烧军团！"
D.Strings[89772]="现在我们可以用邪能之槌号攻击燃烧军团了……这多亏了你！"
D.Strings[89773]="时间宝贵！你该回达拉然去，然后立即借道返回破碎群岛。"
D.Strings[89774]="来啊！来见证伟大的阿卡扎曼扎拉克的神奇魔法吧！那就是我，大家好。"
D.Strings[89775]="都过来，来见识你们前所未见的神秘奇迹！"
D.Strings[89776]="演出继续！伟大的阿卡扎曼扎拉克感谢各位的打赏！对，钱就放这儿好了。"
D.Strings[89777]="女士们先生们，睁大眼睛欣赏这场魔法的盛宴吧！"
D.Strings[89778]="我要从这顶普通帽子里变出兔子来，让你们目瞪口呆！"
D.Strings[89779]="谢谢，谢谢。感谢大家的小费。"
D.Strings[89780]="现在，下一个戏法！大家看，我的袖子里是空的……"
D.Strings[89781]="现在……嘭！"
D.Strings[89782]="凝视虚空坩埚，它会向你展示我们看到的一切。"
D.Strings[89783]="好了，这个戏法需要一位志愿者。"
D.Strings[89784]="选一张牌，随便选……"
D.Strings[89785]="哇！金色的砰砰博士！"
D.Strings[89786]="嘿！那张牌不行！把它还给我！"
D.Strings[89787]="你是来送死的吗？！"
D.Strings[89788]="一个$r！"
D.Strings[89789]="干掉这个$c！"
D.Strings[89790]="我要扒了你的皮！"
D.Strings[89791]="我要把你的骨头做成磨刀石！"
D.Strings[89792]="干得不错。还剩三个。"
D.Strings[89793]="我不相信她。"
D.Strings[89794]="她以为她是谁？"
D.Strings[89795]="她一定有什么阴谋。"
D.Strings[89796]="噢，这才叫小费呢！"
D.Strings[89797]="演出结束了，乡亲们！散场了！"
D.Strings[89798]="|TInterface\\Icons\\Ability_Warlock_ImprovedSoulLeech:20|t %s开始|cFFFF0000|Hspell:194325|h[粉碎]|h|r$n。"
D.Strings[89799]="哨兵们随时可以协助你。"
D.Strings[89800]="成功了！能量站恢复运转了。"
D.Strings[89801]="精炼的魔网能量将从这里流向沙尔艾兰。"
D.Strings[89802]="你这大厅不错啊！"
D.Strings[89803]="我行走于阴影之中。"
D.Strings[89804]="嘿，伙计，你不是来找岑塔布拉买鱼的吧？你想要什么？"
D.Strings[89805]="愿你的灵魂前往英灵殿。"
D.Strings[89806]="向索迪尔族长致敬！"
D.Strings[89807]="传送门开启了，通向阿佐兰的道路肃清了。"
D.Strings[89808]="残寺派的僧侣们！"
D.Strings[89809]="今天，多亏了我们的领袖$n，我们得到了一种新的力量。"
D.Strings[89810]="有了传说中的风暴蜜酒，我们抗击燃烧军团的力量就能翻倍了！"
D.Strings[89811]="让我们干掉那个堕落者，让这个世界恢复宁静吧！"
D.Strings[89812]="再次感谢你，大宗师$n。"
D.Strings[89813]="|TInterface\\Icons\\Spell_Holy_BorrowedTime:20|t快在你受到|cFFF00000|Hspell:203935|h[时空迷失]|h|r的影响前重新靠近顾问凡多斯！"
D.Strings[89814]="看呐看呐……这下头还真是一团糟啊。我们上次来净化这些墓穴都是好久之前了。看来这里好像闹老鼠了啊。"
D.Strings[89815]="把他们的脑袋带给我！挖地三尺也要把他们找出来！"
D.Strings[89816]="我活了一万年，我是不会死在一群老鼠手里的。"
D.Strings[89817]="大魔导师……会砍掉你们的脑袋……"
D.Strings[89818]="唉……莽夫只有在童话故事里才会获得胜利。"
D.Strings[89819]="为了艾利桑德的荣耀！"
D.Strings[89820]="很勇敢，可是太……短视了。"
D.Strings[89821]="就把这当成是我的恩典吧。"
D.Strings[89822]="够了！你们这些小畜生真是太难管教了！"
D.Strings[89823]="蝼蚁，你见识过这么狂暴的力量吗？恐怕没有吧？"
D.Strings[89824]="我是暗夜井宣泄其伟力的载体！我是夜之子！"
D.Strings[89825]="整队，蛆虫们！守住这个缺口，等待古尔丹的命令！"
D.Strings[89826]="很好！又有消遣送上门来了！我正闲得发慌呢！"
D.Strings[89827]="我的仆从们，过来！趁血还热着，快来吃掉他们的尸体吧！"
D.Strings[89828]="不……不！没人能击败……伟大的萨卡尔……"
D.Strings[89829]="你们不是伟大的萨卡尔的对手！"
D.Strings[89830]="我的剑刃上又多了一个缺口而已！"
D.Strings[89831]="邪能之火需要更多的燃料！"
D.Strings[89832]="援助我！快！"
D.Strings[89833]="在我阴影下的一切都将崩塌！"
D.Strings[89834]="跟燃烧军团作对的人都得死！"
D.Strings[89835]="别担心援军。我会用生命保护这座传送门的。"
D.Strings[89836]="时间有限……快走！"
D.Strings[89837]="我需要你治疗，勇士。我无法单独面对这个恶魔。"
D.Strings[89838]="勇士！你必须阻止暗涌纳迦继续腐蚀这些可怜的远石鱼人的心灵！"
D.Strings[89839]="真是太勇敢、太聪明了！我很高兴你这样的冒险者还愿意为鱼人考虑！谢谢你！"
D.Strings[89840]="我们要给萨吉塔带去死亡！"
D.Strings[89841]="进攻，$n！进攻！"
D.Strings[89842]="把他们赶回深海里去！"
D.Strings[89843]="击溃他们的阵线！"
D.Strings[89844]="漂亮的一击，$n！"
D.Strings[89845]="再来！再来！"
D.Strings[89846]="他们永远都别想抵达贾德维克！"
D.Strings[89847]="我们要把他们统统杀光！"
D.Strings[89848]="你可以走了。我可以自己前往沙尔艾兰。"
D.Strings[89849]="该死！你必须摧毁维持那个屏障的结界，才能挑战瓦雷迪斯。"
D.Strings[89850]="他们发现你了。快！"
D.Strings[89851]="让降落见鬼去吧！你自己潜入堡垒。让他们看看你的力量！"
D.Strings[89852]="那些蠢货以为能对付你。让他们为这种傲慢付出代价吧！"
D.Strings[89853]="燃烧军团会记住这一天的。"
D.Strings[89854]="天上最棘手的敌人都被解决了，我们可以直接去达拉然了。"
D.Strings[89855]="不，不，不……这儿全乱了。谁会把图书馆弄成这样？！"
D.Strings[89856]="你们在干嘛？快跑吧，蠢货！那个恶魔就在附近！"
D.Strings[89857]="这个箱子已经……彻底烂了。真是奇怪。"
D.Strings[89858]="我……不会说的！下面埋的就是你们的末日！"
D.Strings[89859]="下面渗透出来的是什么东西？告诉我们，幽灵！"
D.Strings[89860]="这是……最后一次抢劫了……"
D.Strings[89861]="来吧，我会治疗你的。让我们来打倒这头龙吧！"
D.Strings[89862]="恶魔正在亵渎我们死去的酋长，将他们复活成无脑的爪牙，听从他们邪恶的意志。摧毁这些被腐蚀的遗体，让他们再次安息吧。"
D.Strings[89863]="但愿历代酋长能在墓地中安息。"
D.Strings[89864]="你找到了，陈叔！"
D.Strings[89865]="$G他:她;是真正的英雄！"
D.Strings[89866]="邪能图腾和他们的恶魔盟友正在利用我们神圣的墓地唤起亡灵为他们所用。去击败那些复活的亡灵，让他们安息吧。"
D.Strings[89867]="我只希望他们被你的神器摧毁后，会失去复活亡者的能力。"
D.Strings[89868]="让悲夜和拉文凯斯跟你去，$n。你们应该可以潜入堡垒而不被发现。"
D.Strings[89869]="<瓦尔托伊没有反应。她的表情说明她正忍受着巨大的痛苦。|cFFF92304必须首先满足她的饥渴，然后才能进行其他行动。|r>"
D.Strings[89870]="我们曾经依赖一种魔力的本源精华。这种药剂甚至能够媲美永恒之井。$B$B再想想我们现在只能依赖一些残羹冷炙。$B$B<瓦尔托伊的嘴唇嫌恶地扭曲起来。>"
D.Strings[89871]="我们的部队应该在这里迎敌……"
D.Strings[89872]="恶魔和邪能图腾占据了至高岭最神圣的地方之一。去杀光他们！把他们从这个地方赶出去！"
D.Strings[89873]="我们不是已经击败他们了吗？我都糊涂了。"
D.Strings[89874]="他们是燃烧军团，但你暂时遏制住了他们在这里的势头。"
D.Strings[89875]="终于可以品尝到配得上夜之子的魔力物质了。$B$B我欠你一个人情。$B$B<瓦尔托伊简单地向你点了点头。>"
D.Strings[89876]="墓地中那个领导恶魔大军的艾瑞达正在复活我们的酋长和其他死者，把他们变成可恨的行尸走肉。如果我们能干掉那个艾瑞达，或许就能拖慢他们的进度。"
D.Strings[89877]="这些群龙无首的恶魔肯定会失去目标，不再去打扰我们的亡者。"
D.Strings[89878]="<奥术师扬起眉毛，算是回应了你。>\n\n听好了，我的名字应该这么念：“瓦尔——托伊。”\n\n那个“s”是不发音的。"
D.Strings[89879]="不，我不认为……噢，等等……我……我怎么记不起来了？"
D.Strings[89880]="小心点儿。瓦雷迪斯可是传说中的强者。"
D.Strings[89881]="非常……感谢。我不认识你，但我知道你心中充满勇气。对……你就是我要等的英雄！"
D.Strings[89882]="很久之前，求知的欲望将我带到此地，一座湖底陵墓。冰冷的石墙后面，埋藏着……可怕的黑暗，一个古老的邪神。"
D.Strings[89883]="呃……我始终不习惯这味儿。"
D.Strings[89884]="没了吗？唔……这点应该也够了。"
D.Strings[89885]="呃……好苦。我们需要更好的方法！"
D.Strings[89886]="我的禅杖和酒桶都听你的号令，大宗师。只要你一声令下，我就会果断出击！"
D.Strings[89887]="部下们求我离开，可我拒绝了。骄傲葬送了我……和他们。惊醒的邪神带来了死亡。弥留之际，我将我的佩剑，斯多姆卡，插入了它的头颅。"
D.Strings[89888]="几百年过去了，那把剑一直使怪物无法复活。现在它又被惊动了，请你深入墓穴，消弭我闯下的大祸。我会跟你一起去，尽力帮助你。"
D.Strings[89889]="虽然我牺牲了自己，可下面那个邪恶的生物仍在缓缓苏醒。你必须闯入它堕落的深渊，最后干掉它一次。我会跟你分享我所知道的情报的。"
D.Strings[89890]="唔，我没事。你不用太担心了。"
D.Strings[89891]="我恢复了！"
D.Strings[89892]="我不会浪费这份礼物的。"
D.Strings[89893]="萨吉塔必胜！"
D.Strings[89894]="这是萨吉塔的水域！"
D.Strings[89895]="你的末日降临了！"
D.Strings[89896]="诅咒与死亡！"
D.Strings[89897]="我们……要……杀光……你们……"
D.Strings[89898]="为了潮汐主母！"
D.Strings[89899]="我们是不可阻挡的……"
D.Strings[89900]="我将回归深海……"
D.Strings[89901]="萨吉塔……"
D.Strings[89902]="你竟敢闯入我们的地盘！"
D.Strings[89903]="以潮汐主母的名义，我要杀了你！"
D.Strings[89904]="深海将是你的葬身之处！"
D.Strings[89905]="我要把你剁碎了拿去喂鳗鱼！"
D.Strings[89906]="你闯入了萨吉塔的水域！"
D.Strings[89907]="杀了入侵者！"
D.Strings[89908]="我的生命属于萨吉塔……"
D.Strings[89909]="我的死不算什么……"
D.Strings[89910]="你休想阻止潮汐主母……"
D.Strings[89911]="我们……是不可……阻挡的……"
D.Strings[89912]="漆黑的深海……"
D.Strings[89913]="你这滩烂泥……"
D.Strings[89914]="纳拉雷克斯不在这儿，但你还是能闻出他的气味。"
D.Strings[89915]="好了，阿卡扎曼扎拉克，位置都告诉你了。你能解决那些传送门吗？"
D.Strings[89916]="不必了，老朋友！我这就把你的法师弄过来！"
D.Strings[89917]="艾泽拉斯的法师们！我召唤你们前来，是因为这个世界遭到了威胁！"
D.Strings[89918]="恐惧魔王卡萨纳提尔已经逃入了扭曲虚空，还带走了提瑞斯法议会的秘密。"
D.Strings[89919]="我们得深入扭曲虚空去追杀他。这样才能确保他不会用掌握的秘密来对付我们。"
D.Strings[89920]="为此，我决定重建提瑞斯秘法会。你们愿意一起来对抗军团吗？"
D.Strings[89921]="那就这么定了。"
D.Strings[89922]="很好。由艾泽拉斯最伟大的一群法师见证，我很荣幸地授予你，$n，大咒术师的称号。"
D.Strings[89923]="这个古老的头衔象征着提瑞斯秘法会的职责。光荣地担起这个重任吧。"
D.Strings[89924]="该去指挥室见见这位地精新盟友了。你可以在那里策划后续行动。"
D.Strings[89925]="我们到地方见。"
D.Strings[89926]="靠近我，我的宠物们。"
D.Strings[89927]="你们的主人需要你们！"
D.Strings[89928]="去啃食他们骨头吧！"
D.Strings[89929]="我想再多了解一下你。"
D.Strings[89930]="我不相信你们，“恶魔猎手”。$B$B在我看来，你们和燃烧军团没有什么不同。"
D.Strings[89931]="让我们进去，否则我就让你看看我们到底有什么不同。"
D.Strings[89932]="没时间解释了。让我们进入堡垒，守望者。"
D.Strings[89933]="如果你没空解释，那我也没空搭理你们。"
D.Strings[89934]="我是索拉丁，阿拉索的开国之君。 \n\n很久以前，人类只是一群以部族为单位互相征战的野蛮人，并不断被巨魔缓慢蚕食着。我带领我的部族——阿拉希统一了诸部族，建立了阿拉索王国。在我高贵的兄弟，伊格纳乌斯和洛丹恩的协助下，我们击退了巨魔，可我知道那只是暂时的。\n\n后来，我们与精灵结盟，开始了人类史上最漫长、最血腥的战争。要不是巨魔过于傲慢，我们早就死了。结果是，我们获得了精灵的深厚友谊，并向他们学会了魔法。但代价是无数战士以及我最好的朋友，洛丹的生命。\n\n在王国安定强盛之后，我禅让了王位，踏上了我自己的征程。"
D.Strings[89935]="这算是威胁吗？$B$B需要我提醒你，你是在我的监狱里，被我的卫兵包围着吗？"
D.Strings[89936]="你想知道吗？"
D.Strings[89937]="无论如何，你又有什么损失呢？"
D.Strings[89938]="看到阿拉索后继有人之后，我就带着我最信赖的家臣们踏上了追寻部族起源的道路。我们走遍了这片土地，挖掘历史的碎片，一直来到了这里。\n\n出于激动以及对真相的渴望，我无视了警告，让我的法师们打开了这片湖底的封印。我从来没见过这样的陵墓。我们靠得太近了，以致于还没有真正理解眼前的一切，就深入了墓穴。那里躺着将我们的祖先带来这里的生物，身上还有永远萦绕和鼓舞着当地人民的印记。\n\n但不仅是如此而已。与这个“提尔”战斗的怪物也躺在这里，而我打破了防止它复生的封印。"
D.Strings[89939]="你手上那个艾瑞达掌握着一些重要情报。我们需要跟他单独谈谈。"
D.Strings[89940]="它死了，可又被唤醒了？"
D.Strings[89941]="我们只想跟那个艾瑞达单独……谈谈。他有我们需要的情报。"
D.Strings[89942]="很高兴再次见到你，$g小子:丫头;！这些精灵需要我们所能提供的一切帮助！"
D.Strings[89943]="你们幸运地赢得了卡德加的信任。但我可不像他那么耳根软。"
D.Strings[89944]="很好。那就快点完事吧。"
D.Strings[89945]="它已经在这里躺了无数个世纪，它的主人是一个曾与提尔交战的上古邪神。随着封印的解除，它开始康复，并在苏醒过程中从地底深处召来了帮手。\n\n可怕的怪物从牢笼里的裂口中爬出来，我们遭到了袭击。我意识到自己犯下了可怕的错误，这个东西比巨魔更强大。我知道必须在它彻底苏醒前阻止它。\n\n我们做出了最大的牺牲。虽然还没完全恢复意识，那个怪物还是轻而易举地杀掉了我所有的战友。但他们为我争取到了时间，我将我的长剑斯托姆卡插入了它的头颅，但它的利爪也取走了我的性命。\n\n它死了，但封印是无法去除的。它的死亡只是暂时的。"
D.Strings[89946]="跟我说说你那把防止怪物复活的剑吧。"
D.Strings[89947]="可悲的烂泥！我的鳗鱼会活吃了你！"
D.Strings[89948]="我的……鳗鱼……"
D.Strings[89949]="是谁在打搅我睡觉？"
D.Strings[89950]="永恒的……长眠……"
D.Strings[89951]="你没必要那么小心，$n。森林已经预示了你的到来。"
D.Strings[89952]="<纳拉雷克斯静静地坐着，双目紧闭。>"
D.Strings[89953]="我称它为斯多姆卡，灭战者。\n\n阿拉希人掌握着最古老的武器锻造方法，连我都记不清它究竟有多古老了。我使用这种方法和特殊的金属打造了我的长剑。之后的岁月里，它伴随我经历了史上最伟大的战役，且从未让我们失望。它救过我许多次，让我在无数场战斗中反败为胜。\n\n在巨魔战争结束后，心怀感激的精灵私下送给了我一份礼物。他们最伟大的法师和铁匠给斯多姆卡灌注了强大的精灵魔法。我想应该是这种魔法阻止了那个怪物的苏醒。我很担心在那个怪物体内沉睡了数百年会对灭战者带来什么不好的影响。"
D.Strings[89954]="<安静地站在一旁。>"
D.Strings[89955]="<轻轻拍拍他的肩膀。>"
D.Strings[89956]="该举行仪式了？很好，我们到那儿见。"
D.Strings[89957]="这个怪物，死了也不安分。它的腐蚀已扩散到整个墓穴。你得自己杀出一条路来！"
D.Strings[89958]="你们的努力毫无意义！很快，全苏拉玛都将臣服于主人！"
D.Strings[89959]="玛法里奥已经准备开始了。他要你马上前往仪式地点。"
D.Strings[89960]="去死吧，萨吉塔的毒蛇！"
D.Strings[89961]="我们的机会来了！"
D.Strings[89962]="杀了那个纳迦！"
D.Strings[89963]="那么，就看我们能不能做到了。这需要我们付出一切，甚至更多。"
D.Strings[89964]="岑塔布拉闭了一会儿眼睛。"
D.Strings[89965]="我尽量不插手。这个恶魔归你了。"
D.Strings[89966]="别磨蹭。说！你的主子在哪儿……不然就死！"
D.Strings[89967]="这正是我们想要的。干掉他。"
D.Strings[89968]="嘶嘶嘶……"
D.Strings[89969]="干扰传送门"
D.Strings[89970]="我会准备一只魔蝠送你去苏拉玛。瓦雷迪斯的死期到了。"
D.Strings[89971]="万灵没有就此对我说什么。这说明它们也不反对。很好，我们仪式上见。"
D.Strings[89972]="你们可以立刻投降，成为潮汐主母的俘虏，否则我现在就杀了你们！"
D.Strings[89973]="可憎的……垃圾……"
D.Strings[89974]="不不！再多捡一点！捡起来！"
D.Strings[89975]="我亮晶晶的宝贝！"
D.Strings[89976]="快！黑暗马上就要降临了。"
D.Strings[89977]="太重了。再搬一点来！"
D.Strings[89978]="谢了，陌生人。"
D.Strings[89979]="我注意到你没有戴耳环。需要我为你介绍一副栓动力卡宾枪箍吗？它们还没怎么生锈呢！"
D.Strings[89980]="那些鱼人肯定在打什么坏主意，没错。我就是知道，因为我已经闻到他们的鱼腥味儿了。"
D.Strings[89981]="看见这个前厅时，我就知道有了……大发现。这扇门异常眼熟，仿佛来自早已失落的记忆。我们打破了第一个封印。"
D.Strings[89982]="传送门准备好了，头儿！如果你不介意，我要去检查挖掘进度了……"
D.Strings[89983]="几个关于那些靴子的提示。一旦你激活了它们，你就会立刻起飞，速度会比一场竞技场比赛中的潜行者还要快。"
D.Strings[89984]="新鲜的、肉！"
D.Strings[89985]="还是……好饿……"
D.Strings[89986]="美味的小吃。"
D.Strings[89987]="吃了你。"
D.Strings[89988]="酥脆的骨头。"
D.Strings[89989]="……带上这个外来者。"
D.Strings[89990]="如果……你坚持的话。"
D.Strings[89991]="瓦尔托伊？"
D.Strings[89992]="你们对那些外来者客气些。没有他们的帮助，我们都不可能站在这里。"
D.Strings[89993]="好的，首席奥术师。"
D.Strings[89994]="来吧，我们能在此检查能量流。"
D.Strings[89995]="你好啊，$c！$B$B我是追着一群萨吉塔纳迦横渡海湾来到这个洞穴的。$B$B我杀了不少，可有几个还是跑掉了。我毫不怀疑，他们肯定会纠集起更多同伙回来杀我的。$B$B如果你想来一场光荣的战斗，那就打起精神来，准备好你的武器吧。$B$B如果你不敢的话，就别挡我的路，否则我就亲手杀了你。"
D.Strings[89996]="你有处理魔网能量的经验吗？我想恐怕没有。"
D.Strings[89997]="让我来教教你基础知识吧。"
D.Strings[89998]="你是一个出色的$c。希望能再次与你并肩作战！$B$B等我回到贾德维克，我们一定会在酒壶边传唱我们今天的战斗的！"
D.Strings[89999]="在我们脚下，原始魔力的长河流过这片土地。魔网是永恒的、原始的、无法控制的。"
D.Strings[90000]="就让那些萨吉塔纳迦放马过来吧！"
D.Strings[90001]="但是，就像从棉花中抽取棉线一样，我们也能从魔网中抽取能量。"
D.Strings[90002]="你的速度会非常快，快到都可以漂起来了。所以注意你的弹药，一旦弹药耗尽，你就会“扑通”一声掉进水里。"
D.Strings[90003]="只要你停下，一切都会重置，你也可以再试一次。"
D.Strings[90004]="要是霍巴特知道了他的枪械包的下场，肯定会不高兴的。你怎么样了，$g小伙子:丫头;？"
D.Strings[90005]="无论你的猎物是什么，拉兹克的小玩意儿都能包你命中目标。\n\n他的最新原型机已经装好了弹药，随时可以发动。去武器架上拿一把，开始享受射击的乐趣吧。\n\n但记住，你得自己承担测试风险！"
D.Strings[90006]="我们得去找班布利，否则就迟了！"
D.Strings[90007]="好了，让我们来帮他弄到钥匙吧……但你要小心点，这里到处都是恶魔。"
D.Strings[90008]="班布利！不……不，这不可能！"
D.Strings[90009]="看！那是班布利的头盔，它化成灰我都能认出来！"
D.Strings[90010]="老班布利肯定栽在那些恶魔手里了……"
D.Strings[90011]="不出我所料，那个怪物的一个爪牙归来了。它腐蚀了陵墓的结界，阻断了道路。你得摧毁那些触须，引它出来！"
D.Strings[90012]="我诅咒你们，恶魔！诅咒你们！"
D.Strings[90013]="它在那儿……墓穴顶上！做好准备！"
D.Strings[90014]="看这儿。这是来自安诺拉的能量。还有不少节点仍在休眠。"
D.Strings[90015]="请你修复它们，帮我们在沙尔艾兰制造一个新节点！"
D.Strings[90016]="你要为你杀害的萨吉塔成员偿命！"
D.Strings[90017]="诅咒……你……"
D.Strings[90018]="有一支探索灰石地区的寻路者小队失联了。拜托，请找到他们。"
D.Strings[90019]="谢谢你，勇士。感谢你让我的族人逃过了沦为蜥蜴饲料的命运。"
D.Strings[90020]="啮岩部族一直在偷我们的货物。该去偷点回来了。准备好了吗，神偷？"
D.Strings[90021]="哈！都是一群没脑子的蠢货。干得好！"
D.Strings[90022]="哈！这应该能让他们混乱一段时间。"
D.Strings[90023]="我的寻路者跟踪两个缚石者去了啮岩孤地。他们都是达古尔的支持者，非常危险。我们得阻止这次会晤。"
D.Strings[90024]="蜥蜴集市是卓格巴尔的一种危险活动。他们会在集市上买卖蜥蜴，还会斗蜥蜴和剥蜥蜴皮。扰乱集市可以拖住他们，暂时保住我们的农场。"
D.Strings[90025]="我原本很钦佩卓格巴尔亲近自然的能力，可他们借此屠杀了我的人民，入侵了我的土地。谢谢你，勇士。"
D.Strings[90026]="来自灰石地区的碎石领主正在水晶裂隙里举行一种强化仪式。这太靠近雷霆图腾了，让人觉得不安。你能阻止他们吗？"
D.Strings[90027]="谢谢你，勇士。灰石卓格巴尔最近有些太肆无忌惮了。"
D.Strings[90028]="我的仪式需要水晶，而你要减少雷霆图腾周围的水晶之怒。我有个互惠互利的计划。你的骑术怎么样？"
D.Strings[90029]="啊，很好的水晶。这应该足够我举行仪式了。"
D.Strings[90030]="我听到大地在尖叫。卓格巴尔的碎石领主在举行驱使水晶之怒发狂的黑暗仪式。我们得阻止它们，不能让它们对雷霆图腾造成难以挽回的破坏。"
D.Strings[90031]="我都不敢想，如果让这些暴怒的元素之怒肆虐，会对雷霆图腾造成多大的破坏。"
D.Strings[90032]="黑暗正在回音大厅里滋生。我们能感觉到某个邪恶的存在正在那里腐蚀流向别处的水流。去找到腐蚀的源头并消灭它吧。"
D.Strings[90033]="每过一段时间，潜伏在地底深处的邪恶存在就会爬出来并威胁到我们。谢谢你提前抓住了它。"
D.Strings[90034]="我的寻路者报告说有一群狗头人盘踞在回音大厅里。你擅长捉老鼠吗？"
D.Strings[90035]="狗头人三流的挖矿技术可能会造成严重的破坏。要再让他们胡闹下去，那座山很快就会塌了。多亏你消灭了他们，干得好。"
D.Strings[90036]="你今天是想要休息还是治疗呢？"
D.Strings[90037]="%s|cFFFF0404|Hspell:204237|h[严重受伤]|h|r，在经过治疗前无法继续战斗了！"
D.Strings[90038]="这些恶魔简直无穷无尽！"
D.Strings[90039]="无论你的猎物是什么，拉兹克的小玩意儿都能包你命中目标。"
D.Strings[90040]="我还以为自己永远也逃不出来了！"
D.Strings[90041]="可不是天天都会有$c来救你的！"
D.Strings[90042]="我欠你一个人情，$n。"
D.Strings[90043]="快！其他人很快就会赶来的。"
D.Strings[90044]="这就是英灵殿？太神奇了。等等……那不是我师傅吗？"
D.Strings[90045]="在那边，右侧。那肯定就是我们要找的大锅。"
D.Strings[90046]="好，看看我能否穿透你说的结界，打开传送门。"
D.Strings[90047]="小菜一碟！我们另一边见！"
D.Strings[90048]="异教徒！臣服于我的意志，否则就死在燃烧军团的烈焰中吧！"
D.Strings[90049]="我要感谢你帮我干了所有的脏活，$n。但现在，让你继续活下去的话，我恐怕就要有大麻烦了。"
D.Strings[90050]="没有了首领，我就能轻而易举地从内部搞垮贾德维克。"
D.Strings[90051]="我的纳迦将用毁灭的巨浪洗刷贾德维克！"
D.Strings[90052]="|TInterface\\Icons\\Ability_Rogue_DeviousPoisons:20|t尼珊德拉令你感染了|cFFFF0404|Hspell:204463|h[爆裂溃烂]|h|r！"
D.Strings[90053]="成功了。谢谢你，英雄。"
D.Strings[90054]="嘿嘿嘿，看看，你这儿可真不错！"
D.Strings[90055]="今天，燃烧军团遭到了沉重打击，但我们的任务还远未完成。"
D.Strings[90056]="我在沙尔艾兰等你，准备好了就回去吧。我们还有事要讨论。"
D.Strings[90057]="去找木头来搭一个火葬用的柴堆。我来搬运他的遗体。"
D.Strings[90058]="<这个维库人几乎没有注意到你的到来。>"
D.Strings[90059]="一支纳迦大军都不可能战胜索迪尔族长。只有他们恶毒的背叛才有可能打败他。"
D.Strings[90060]="<索迪尔毫无生气地躺在泥泞中。>"
D.Strings[90061]="我保护不了他们……"
D.Strings[90062]="月之守卫已经不复存在了。"
D.Strings[90063]="我没能及时赶到……"
D.Strings[90064]="狗靠一张嘴，树靠一张皮。"
D.Strings[90065]="叫你别来烦我了……"
D.Strings[90066]="……呃！"
D.Strings[90067]="这是什么脏东西？！"
D.Strings[90068]="它……黏糊糊的！"
D.Strings[90069]="滚出这里，别让树笑话你。"
D.Strings[90070]="明年见。"
D.Strings[90071]="我想说些俏皮话，可我的嘴给锯了。"
D.Strings[90072]="我的宝贝书籍……"
D.Strings[90073]="我好像把我的陷阱符文弄丢了……"
D.Strings[90074]="我还有一些私事要处理……"
D.Strings[90075]="没有了我，贾德维克一定会输掉这场战斗。快来！"
D.Strings[90076]="哈哈！你想揍那个咀嚼者吗？"
D.Strings[90077]="伙计，你要敢动一动那头蜥蜴，我就拿石头砸你。"
D.Strings[90078]="哈！它生气了。你上，伙计！"
D.Strings[90079]="看看那只左眼。它很愤怒。"
D.Strings[90080]="这些怪物能够迷惑心智。小心它们的幻象。"
D.Strings[90081]="是时候来刨根问底了。"
D.Strings[90082]="把你连根拔起。"
D.Strings[90083]="你站桩的时间太长了。"
D.Strings[90084]="奥格瑞拉的法师愿意站在提瑞斯秘法会这边，大咒术师。"
D.Strings[90085]="纳迦恶棍！"
D.Strings[90086]="要是让我出去，我一定要吃掉你冰冷的心脏！"
D.Strings[90087]="是该死的海巨人！"
D.Strings[90088]="我醒着呢！绝对没睡着！我是在……闭目养神。"
D.Strings[90089]="岑塔布拉的营地就在湖的西岸。纳拉雷克斯则是在东岸扎营，但他更喜欢四处乱逛。所以你得睁大眼睛了。"
D.Strings[90090]="阻止那些大家伙，别让它们靠近！"
D.Strings[90091]="我不需要你的帮助。"
D.Strings[90092]="我讨厌大海！"
D.Strings[90093]="好冷，我全身都湿透了！"
D.Strings[90094]="祝你噎死！"
D.Strings[90095]="靠近点，小家伙们。"
D.Strings[90096]="看来纳迦的围攻终于结束了。"
D.Strings[90097]="小心点，小家伙们。我看见远处的堕夜精灵了。"
D.Strings[90098]="他们突破了前线！不能让他们吞噬潮汐之石！"
D.Strings[90099]="看！他们往祖父的水池去了！"
D.Strings[90100]="很好！我来保护潮汐之石。你们来挡住精灵大军。"
D.Strings[90101]="抱歉我来晚了，没错过好戏吧？"
D.Strings[90102]="已经很近了。帮帮我们，巫师。"
D.Strings[90103]="我要像摘花一样扯断你。"
D.Strings[90104]="我能断\"枝\"再生，可你不能。"
D.Strings[90105]="把你像树枝一样折断。"
D.Strings[90106]="库尔拉，好女孩。"
D.Strings[90107]="|TInterface\\Icons\\ability_ironmaidens_bloodritual:20|t月神镰刀压制了艾瑞丁！别让他靠近你，躲开|cFFFF0000|Hspell:204659|h[鲜血汹涌]|h|r！"
D.Strings[90108]="月神镰刀压制了艾瑞丁！别让他靠近你！"
D.Strings[90109]="好的，库尔拉，我们都尊崇狩猎之灵。"
D.Strings[90110]="保护祭坛，丫头。"
D.Strings[90111]="这是什么把戏？！"
D.Strings[90112]="达戈里，好孩子。"
D.Strings[90113]="我们崇拜狩猎之灵，孩子。这是我们的责任。"
D.Strings[90114]="保护营地，小子。那可真是条好狼！"
D.Strings[90115]="做好准备，然后就踏入法阵吧。"
D.Strings[90116]="滚开，肮脏的$c！战刃是贝尔巴格找的，贝尔巴格要留下它！"
D.Strings[90117]="这些远石鱼人正在遭受痛苦！他们平时居住的清水里满是淤泥。我们必须把暗水纳迦赶回深海里去！"
D.Strings[90118]="你看不出来吗？水已经变清了。骄傲的远石鱼人感谢你的帮助！"
D.Strings[90119]="对……杀光他们！"
D.Strings[90120]="这软皮很能打……撤！"
D.Strings[90121]="你必须尽快赶去紫罗兰监狱！\n\n决不能让卡萨纳提尔染指守护者熔炉！"
D.Strings[90122]="恐惧魔王卡萨纳提尔被击败了，但这只是暂时的。如果我们想要将艾泽拉斯从他的魔爪中拯救出来，就必须重建提瑞斯秘法会。\n\n然后，我们就能进入扭曲虚空追杀他，以防止他与燃烧军团分享他的秘密。"
D.Strings[90123]="守护者熔炉是什么？"
D.Strings[90124]="等等，你是谁来着？"
D.Strings[90125]="跟我说说提瑞斯秘法会的事吧。"
D.Strings[90126]="我们的庄稼正在枯萎！我不知道卓格巴尔干了什么，也不知道他们是怎么把地里的虫子都赶来对付我们的，可我们需要你的帮助！"
D.Strings[90127]="谢谢你帮我们赢得了大丰收，$n。那些虫子简直让我这把老骨头不寒而栗。"
D.Strings[90128]="守护者熔炉是一件神器，有着不可思议的力量。 \n\n它是由大法师阿洛迪制造出来，可以将许多法师体内的魔法力量永久灌入一个人的身体里，提瑞斯法守护者就是这么诞生的。 \n\n它最后一次启用还是在艾格文的时代。自从她拒绝归还力量，以培养新的守护者后，这个熔炉就被锁在了紫罗兰监狱的魔法屏障后面。 \n\n只有议会才知道它的具体下落，直到今天。"
D.Strings[90129]="抱歉，我忘了我在这个时代已经没什么名气了。 \n\n我是梅瑞尔·邪风——而我原本叫做梅瑞尔·冬风。我曾是提瑞斯法议会的创始人之一。但在被恐惧魔王卡萨纳提尔附体后，我就不得不放弃了我的职务。我压制住了他……其实是基本压制住了他……但如果我继续留在议会里，风险就太大了。\n\n从那时起，我就一直致力于研究如何彻底放逐恶魔。但看来我失败了。"
D.Strings[90130]="只是杀了一个卓格巴尔，就有一群从黑暗中涌出来污染我们的河道！在我那会儿，他们只会躲在他们的地洞里……你不介意把他们赶回阴影里去吧？"
D.Strings[90131]="你用一只脚轻轻踢了一下。大部分鱼都从震荡中活了下来。"
D.Strings[90132]="这些野蛮人完全不尊重万灵。他们的臭气玷污了我们神圣的洞穴！"
D.Strings[90133]="万灵在感谢你。但愿卓格巴尔的臭味不会持续太久。"
D.Strings[90134]="提瑞斯秘法会的历史非常悠久。简而言之，它是由艾泽拉斯最身经百战的一群法师组成的，而且他们每个人都拥有强大的圣物。他们的任务是在提瑞斯法守护者空缺时保护艾泽拉斯。\n\n他们通常只在世界面临严重威胁时才会被召集到一起。他们上一次集结起来，是为了找回堕落的守护者，艾格文。提瑞斯秘法会追踪了她几百年，还动用了艾泽拉斯历史上最强大的几件神器。 \n\n随着提瑞斯法议会的解散，他们最终没能完成任务。但我们是不会让历史重演的。"
D.Strings[90135]="你想打架，嗯？我可以跟你打一场！"
D.Strings[90136]="有了钢铁之拳，谁还需要什么斧子！"
D.Strings[90137]="哎唷！这个从丑八怪树上掉下来的东西砸了我的拳头一下！"
D.Strings[90138]="谁想来吃我一拳？！"
D.Strings[90139]="总算来了一个像样的对手！"
D.Strings[90140]="别担心，我会好好招呼你的！"
D.Strings[90141]="这边，萨满！我们没时间了。"
D.Strings[90142]="喔唷，你的脸怎么了？我的拳头！"
D.Strings[90143]="你想先尝尝哪只拳头？一起来怎么样？！"
D.Strings[90144]="你准备好了吗，$n？仪式要开始了。"
D.Strings[90145]="让我们开始仪式吧。"
D.Strings[90146]="|TInterface\\Icons\\spell_nature_stranglevines:20|t使用|cFFFF0000|Hspell:339|h[纠缠根须]|h|r、击退技能或击晕技能，防止埃瑞丁靠近你！"
D.Strings[90147]="<谢谢参与。恶魔猎手新手剧情的第二部分在守望者地窟，很快就会登场。>"
D.Strings[90148]="看，我最后的战场……最后的敌人。此刻，扎卡兹依然挣扎着想醒来。你得快一点！"
D.Strings[90149]="这简直就是屠杀。我们各地的部队正全线溃败。"
D.Strings[90150]="除非能扭转乾坤，否则艾泽拉斯就完了！"
D.Strings[90151]="卡里杜斯能帮你什么忙呢，朋友？"
D.Strings[90152]="我想选择我的神器。"
D.Strings[90153]="恶魔猎手？你们这些蒙着眼的家伙还真是奇怪。这不会影响你们观察世界吗？"
D.Strings[90154]="欢迎两位。翡翠梦境的震荡越来越激烈，我们必须立刻开始仪式！"
D.Strings[90155]="你的选择很明智。这样一把武器绝对能让我们的敌人闻风丧胆！"
D.Strings[90156]="这是个黑暗的年代——我很高兴有你和我们在一起。"
D.Strings[90157]="%s要|cFFFF0404|Hspell:204779|h[飘走]|h|r了！驱散他！"
D.Strings[90158]="%s要|cFFFF0404|Hspell:204779|h[飘走]|h|r了！驱散她！"
D.Strings[90159]="你的人类朋友被恶魔抓走了。放了我，我就告诉你他被抓去哪儿了！"
D.Strings[90160]="如果你想多杀几个纳迦，就多带点炮弹给我。"
D.Strings[90161]="那把剑被带到了提瑞斯法西北部的某处。我帮你在地图上标记了，你可以从那儿找起。"
D.Strings[90162]="这是你要的炮弹。让我们去炸死那些纳迦吧。"
D.Strings[90163]="欢迎来到梦境之路，$n。在艾泽拉斯需要花费几天的路程，在这里只要走几步就能到了。"
D.Strings[90164]="等等，我感觉有点……不安。快，$n，这边走！"
D.Strings[90165]="不……梦魇……在梦境的这一带？这怎么可能？"
D.Strings[90166]="我来净化路上的梦魇藤蔓。前进吧，$n，消灭催生这些东西的腐蚀之源！"
D.Strings[90167]="干得好！现在，梦魇的邪恶扩散已经开始衰退了。"
D.Strings[90168]="道路肃清了。来吧，我们继续前往目的地。"
D.Strings[90169]="%s制造了一个|cFFFF0404|Hspell:204839|h[盘旋漩涡]|h|r！"
D.Strings[90170]="来吧，我们得找到瓦尔莎拉的德鲁伊，并向他们求助。"
D.Strings[90171]="|TInterface\\Icons\\spell_druid_bearhug:20|t%s的|cFFFF0000|Hspell:198006|h[专注凝视]|h|r瞄准了|cFFFF0000$n|r！"
D.Strings[90172]="你们应该逃跑的！现在，我要拿你们的骨头去喂风暴乌鸦！"
D.Strings[90173]="梦魇的大幕已经升起……我终于从漫长的沉睡中……归来了。"
D.Strings[90174]="你终于摆脱这个地方了……我真羡慕！"
D.Strings[90175]="这是梦魇之王的意志！"
D.Strings[90176]="你们早就该跑了。为什么就不肯听我的呢！"
D.Strings[90177]="践踏一切！粉碎一切！"
D.Strings[90178]="梦魇滋长，吞噬万物！"
D.Strings[90179]="的确，我也希望我们能在更加轻松的场合相见。你肯定也感觉到翡翠梦境的震动了吧？"
D.Strings[90180]="打扰一下，术士。黑暗收割议会需要你的帮助。"
D.Strings[90181]="古老的武器……没错，它们确实能帮上我们，可我们没那个力量来掌控它们。"
D.Strings[90182]="|TInterface\\Icons\\ability_deathwing_assualtaspects:20|t%s陷入了|cFFFF0000|Hspell:198388|h[血性狂乱]|h|r！"
D.Strings[90183]="它能召唤亡魂……站起来！"
D.Strings[90184]="这是陷阱！干掉那家伙，不然我们就死定了！"
D.Strings[90185]="又是那个执事的幻象。这能用群体驱散解决，或直接杀过去，但我可不想靠近！"
D.Strings[90186]="全世界最伟大的萨满都来了。反正剩下的都来了。"
D.Strings[90187]="|TInterface\\Icons\\spell_nature_insect_swarm2:20|t尼珊德拉深呼吸，准备施放|cFFFF0404|Hspell:202977|h[感染吐息]|h|r！"
D.Strings[90188]="来吧，拿出你的真本事来。夜刃正在经历某种“转化”。"
D.Strings[90189]="我们正等着你呢。"
D.Strings[90190]="我们必须恢复平衡。"
D.Strings[90191]="Elune-Adore，$n。我得立刻跟你谈谈！"
D.Strings[90192]="你以为只有你会控制亡灵吗，死亡骑士？！"
D.Strings[90193]="嘶……亡魂们！快来帮我！"
D.Strings[90194]="跟我来。梦境林地有通向梦境之路的门。它能让你快速穿梭于艾泽拉斯各地。"
D.Strings[90195]="不！这剑……你怎么可能压制它的力量？！"
D.Strings[90196]="准备变柴火吧！"
D.Strings[90197]="我要把乌索克之爪从你的手上扯下来！"
D.Strings[90198]="我要把你当营火用！"
D.Strings[90199]="我要像折断树枝一样折断你。"
D.Strings[90200]="我要把你碾成碎片。"
D.Strings[90201]="我……我好像踩到你了，呵呵。"
D.Strings[90202]="噢，太好了，有玩具来了。"
D.Strings[90203]="所以我总是得不到好东西。"
D.Strings[90204]="他们怎么这么不经打呢？"
D.Strings[90205]="我讨厌不会尖叫的玩具。"
D.Strings[90206]="但愿下一个不会死得那么快。"
D.Strings[90207]="什么！？你为什么要这么做？"
D.Strings[90208]="别回头。"
D.Strings[90209]="还来了一只蜘蛛……"
D.Strings[90210]="跑吧。我喜欢看你们逃跑。"
D.Strings[90211]="我都说了要慢慢杀掉你了……可他们就是不听。"
D.Strings[90212]="你的尖叫声真滑稽……真搞笑！"
D.Strings[90213]="你喜欢哪个，尖叫还是哭泣？我都想听听。"
D.Strings[90214]="双头怪亲王已经死了！让我们离开这儿吧！"
D.Strings[90215]="如果你叫得够响，我或许会给你个痛快。"
D.Strings[90216]="你逃不掉的。你是我的！"
D.Strings[90217]="过来，我想玩玩你的鲜血。"
D.Strings[90218]="你跑不了，永远都别想跑！"
D.Strings[90219]="别跑，我想看看你的眼泪。"
D.Strings[90220]="格雷迈恩阁下保证过会让我们参战的。我可不是报名来当卫兵的！"
D.Strings[90221]="但愿这不会弄死你……我还没玩够呢……"
D.Strings[90222]="我知道这些塔楼有着重要的战略意义，可格雷迈恩阁下答应过让我复仇的！"
D.Strings[90223]="如果痛觉分为10级，这下有多痛呢？"
D.Strings[90224]="耐心点。敌人会自己送上门来的，到时我们就让他们看看吉尔尼斯的怒火！"
D.Strings[90225]="只要我们守住这个地方，那些渣滓就不能随意在这附近活动。他们就别无选择，只能与我们战斗了！"
D.Strings[90226]="看来今晚这些双头怪都要饿肚子了。河鬃部族感谢你！"
D.Strings[90227]="$n，你必须前往蓝翼栖地，见我的祖父塞纳苟斯。"
D.Strings[90228]="你的培训鼓舞了我加入隐秘通途的信心！"
D.Strings[90229]="看来想要成为一个猎人，光会射杀猎物是不够的！"
D.Strings[90230]="我还不是最出色的，但我会坚持练习的！"
D.Strings[90231]="快点干，我的纳迦们！我们要摧毁贾德维克！"
D.Strings[90232]="这里的山头上有一些规矩……非常严酷！去驯服一头野兽，骑上它，然后杀掉你所见到的每一个人！如果你死了，那就证明你的能力不足。"
D.Strings[90233]="你刚才的表现真精彩！"
D.Strings[90234]="我们必胜！杀光所有胆敢闯入我们水域的入侵者！"
D.Strings[90235]="那些维库人不算什么！我们会淹没他们，摧毁他们的村庄！"
D.Strings[90236]="来吧，梦游者们……复仇！"
D.Strings[90237]="尝尝梦魇的腐蚀吧！"
D.Strings[90238]="疯狂的种子！我将你释放到这个世界！"
D.Strings[90239]="消散了。都消散了……"
D.Strings[90240]="|TInterface\\Icons\\Ability_Rogue_Dismantle:20|t你踩上了|cFFFF0000|Hspell:204348|h[残酷陷阱]|h|r！"
D.Strings[90241]="你今天打得不错，$n。我欠你一个人情。$b$b我可以用这个传送石把我们送回达拉然去。"
D.Strings[90242]="|TInterface\\Icons\\inv_axe_2h_felfireraid_d_01:20|t%s准备使用战斧对$n发动|cFFFF0000|Hspell:203641|h[邪能挥砍]|h|r！"
D.Strings[90243]="|TInterface\\Icons\\INV_Sword_48:20|t在$n被|cFFFF0000|Hspell:202361|h[处决]|h|r前解开他们的束缚！"
D.Strings[90244]="在救出丝黛拉苟萨后，你就获得了一个强大的盟友。\n\n得知蓝龙军团幸存下来，我很欣慰，虽然他们也只是勉强逃过一劫。我们必须前往蓝翼栖地与这位塞纳苟斯谈一谈。\n\n如果说还有人能指点我们找到创世之柱，那就一定是他了。"
D.Strings[90245]="你的朋友被带到那艘巨型燃烧军团指挥舰下方的邪喉洞穴去了。"
D.Strings[90246]="可惜，这对他来说可能有点迟了……别再为了一个死人浪费你们的生命了！"
D.Strings[90247]="要是还有人能帮你找到这个创世之柱，那一定是我的祖父。"
D.Strings[90248]="我们欢迎任何人参加伟大艾维娜的飞行试炼。请排队接受她的祝福吧。"
D.Strings[90249]="愿你乘风而行，一路顺遂。"
D.Strings[90250]="最精密的计划，也挡不住敌人的雷霆一击。"
D.Strings[90251]="真傲慢！我们一定会让你们死得很漫长、很痛苦。"
D.Strings[90252]="你们的灵魂将成为引擎燃料！"
D.Strings[90253]="我们的仇恨永无止境！"
D.Strings[90254]="死有余辜。"
D.Strings[90255]="我们会将你们闻所未闻的灾祸降临到这座堡垒上！"
D.Strings[90256]="大人……我……辜负了你……"
D.Strings[90257]="又收获了一条灵魂！"
D.Strings[90258]="她是属于我的！你休想抢走她！"
D.Strings[90259]="来了一位瓦格里！我们得恭敬地迎接她。来吧，英雄们！"
D.Strings[90260]="我准备好了，我们前往阿苏纳吧，卡德加。"
D.Strings[90261]="奥瑞克，兄弟！我会为你报仇的！"
D.Strings[90262]="愿瓦格里来接引你，哈格里姆！"
D.Strings[90263]="看那边！是瓦格里！"
D.Strings[90264]="在天上保佑我吧，兄弟们，记得在圣殿给我留个位子！"
D.Strings[90265]="抱歉，$g伙计:女士;，我帮不了你。去找个$c训练师吧。我只教猎人！"
D.Strings[90266]="能来到这里，是不是和我一样激动呢，$c？"
D.Strings[90267]="跟我来，$n，我会把你介绍你的训练师，穆菲努斯·铬酒。"
D.Strings[90268]="穆菲努斯，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。"
D.Strings[90269]="欢迎来到历史的残片！$b$b你有兴趣学习考古学吗？"
D.Strings[90270]="一片新大陆！充斥着被遗忘的秘密！"
D.Strings[90271]="这地方到处都是泰坦的建筑。为什么我知道，因为北边那座山上就有一座巨型泰坦大殿！"
D.Strings[90272]="去吧，胡尼尔在天台上等着，他会帮你的。"
D.Strings[90273]="|TInterface\\Icons\\INV_Misc_Slime_01:20|t一团凝结的黏质|cFFFF0404|Hspell:201495|h[再度凝固]|h|r了！"
D.Strings[90274]="欢迎来到我们的新家，$n。"
D.Strings[90275]="抱歉，$n。我正在为其他宗师准备笔记。"
D.Strings[90276]="兄弟姐妹们，入侵者冲我们来了。击退他们！进攻！"
D.Strings[90277]="你准备好了就告诉我。"
D.Strings[90278]="我一直在等着这一天。"
D.Strings[90279]="我们在肯瑞托的朋友开启了一座魔法传送门，让我们可以快速抵达达拉然。你可以在寺院的台阶附近找到它。"
D.Strings[90280]="我一直被教导要把所有的$r都视为敌人。但燃烧军团会将我们都从这个世界上抹去。$b$b所以我选择走上隐秘通途的道路，与你们并肩作战。"
D.Strings[90281]="这些恶魔以为我们会直接放弃，将十字路口双手奉上吗？"
D.Strings[90282]="击退他们！我们决不能让十字路口沦陷！"
D.Strings[90283]="十字路口需要支援，马上！我们遭到了袭击！"
D.Strings[90284]="守住十字路口，等待援军抵达！让这些恶魔看看部落战士的本事！"
D.Strings[90285]="这片土地是不会毁在你们手上的！"
D.Strings[90286]="你污秽的魔法在我的刀剑面前不堪一击！"
D.Strings[90287]="杀了他们，把他们的灵魂扔进水里去！"
D.Strings[90288]="他们的小玩意儿都归你们了，但灵魂都归我！"
D.Strings[90289]="入侵者登上了纳格法尔号！不要放过这些恶棍！"
D.Strings[90290]="没有比……葬身大海更美好的……"
D.Strings[90291]="你好，$n。我很高兴你响应了萨尔的召唤。$b$b你也看到了，这里没有阵营之分。我们都是大地之环的幸存者，大家必须团结一致，否则只会被各个击破。$b$b幸存者们还在陆续从艾泽拉斯各地赶来。照顾好他们，抚平他们的伤口。要想让他们重返战场，我们就要给他们希望，$n。你必须鼓舞起他们的斗志！"
D.Strings[90292]="我会照顾好其他人的，预言者。"
D.Strings[90293]="这不是我过去的学生吗？$n，死亡的化身！改天我一定要听听你从战场上学来的技巧。"
D.Strings[90294]="你最强的攻击技能就是对被冻结的目标施放的冰枪术以及寒冰宝珠。由于不是每个怪物都会被冻结，而寒冰宝珠的冷却时间又很长，所以你还可以在战斗中获得两个增益效果。"
D.Strings[90295]="施放寒冰箭时，你有一定几率获得寒冰指和冰冷智慧效果。寒冰指可以让你的冰枪术将目标视为被冻结目标并造成大量伤害。而冰冷智慧可以重置寒冰宝珠的冷却时间。现在，试着用一下这两个效果吧。"
D.Strings[90296]="艾泽拉斯的情况比我们想的还要糟得多。"
D.Strings[90297]="你应该亲眼看看这个。"
D.Strings[90298]="本地的一些恶棍一直在偷我们的古董酒，你能找到他们，把酒带回来给我吗？里面有些酒已经绝版了！"
D.Strings[90299]="是雄鹰之灵！赞美万灵！"
D.Strings[90300]="我的人民中间一直流传着有关这些灵体的传说，但我从来没有见过它们。"
D.Strings[90301]="装上机械双翼后，那头鹰会飞得更快的！"
D.Strings[90302]="魔血剧烈地沸腾着，表面下出现了一些模糊的影像。"
D.Strings[90303]="查看燃烧军团在艾泽拉斯的位置。"
D.Strings[90304]="你好，感谢你参加《军团再临》的内测活动！ \n\n我可以将你直接传送到目前开放测试的各大团队副本或地下城。这是单纯的传送，不包括配队服务，所以请事先组织好队伍以应对副本内的挑战。如果你没有队伍，请使用我们最新的队伍查找器功能寻找盟友。\n\n请在传送前选择好你想要测试的难度，因为要想离开副本以变更难度将会比较困难！"
D.Strings[90305]="不错的开端！肯瑞托为我们开启了一座往返于达拉然和虚空之光神殿的永久传送门。祝你好运！"
D.Strings[90306]="够了！过来，苏伊什！消灭这些入侵者！"
D.Strings[90307]="怎么了？听我的！我是头儿！"
D.Strings[90308]="原来是这样吗？真聪明。"
D.Strings[90309]="你已经获得了寒冰指效果，立刻施放冰枪术吧。"
D.Strings[90310]="齿轮在上！那不是$n和$g他:她;的超级大杀器吗？"
D.Strings[90311]="噢，当然了，这是一把漂亮的武器……我想也是。可它能驯服机械小鸡？我不信！"
D.Strings[90312]="我很高兴，我们侏儒终于可以释放出猎人的天性了！"
D.Strings[90313]="我知道。我也该来炫耀一下我的枪了！"
D.Strings[90314]="告诉我，杜帕拉，墙上这些武器里，哪些是猎人用的？"
D.Strings[90315]="你没听过吗，实习生？所有武器都是猎人的武器。全部都是！"
D.Strings[90316]="你解决了我们的小宝贝？没关系。我会让你明白，我才是头儿！"
D.Strings[90317]="苏伊什看了看加迪斯的伤口。"
D.Strings[90318]="苏伊什饥饿地盯着加迪斯。"
D.Strings[90319]="你正在进入限制区域。如果不返回先前区域的话，你将被传送回达拉然。"
D.Strings[90320]="接受痛苦的试炼吧。"
D.Strings[90321]="灰舌死誓将与您并肩战斗。"
D.Strings[90322]="您也可以召唤库斯卡。"
D.Strings[90323]="我们的任务还没完成。我们听候您的调遣。"
D.Strings[90324]="如果你胜利，那把剑就归你了；如果你失败……就得成为天灾军团的无脑爪牙。别指望我会保护你。"
D.Strings[90325]="我想前往黑鸦堡垒（地下城）。"
D.Strings[90326]="我想前往黑心林地（地下城）。"
D.Strings[90327]="我想前往艾萨拉之眼（地下城）。"
D.Strings[90328]="不要考验我的耐心，恶魔。快说。"
D.Strings[90329]="我想前往英灵殿（地下城）。"
D.Strings[90330]="你那邪恶的灵魂将成为你最后的遗物。"
D.Strings[90331]="我想前往奈萨里奥的巢穴（地下城）。"
D.Strings[90332]="我想前往魔法回廊（地下城）。"
D.Strings[90333]="我的时间有限——有话就说，然后让我们结束这一切。"
D.Strings[90334]="我想前往噬魂之喉（地下城）。"
D.Strings[90335]="我想前往紫罗兰监狱（地下城）。"
D.Strings[90336]="我想前往守望者地窟（地下城）。"
D.Strings[90337]="尝尝夺魂之镰的滋味吧，恶魔。"
D.Strings[90338]="不配合就得死。"
D.Strings[90339]="我很乐意把你的灵魂从身体里抽出来。"
D.Strings[90340]="把你知道的都告诉我，否则就准备吃苦头吧。"
D.Strings[90341]="我有的是办法撬开你们的嘴。"
D.Strings[90342]="很好，让我们再练习几次。"
D.Strings[90343]="耐心地询问大海，大海就会倾听你的疑问。$b$b耐心地请求我……我会看看能帮你做点什么。"
D.Strings[90344]="你能给予我水上行者的祝福吗？"
D.Strings[90345]="等你找齐所有的遗骨，就到东边来找我吧。我来准备安葬仪式。"
D.Strings[90346]="你好，冒险者。我叫莱莎。你也跟我一样，是来研究至高岭的牛头人的吗？"
D.Strings[90347]="你找到艾特洛其他的遗骨了吗？"
D.Strings[90348]="这是剩下的遗骨碎片。"
D.Strings[90349]="|TInterface\\Icons\\ability_creature_cursed_03.blp:20|t%s飞上天空，使用|cFFFF0000|Hspell:204245|h[梦境腐蚀]|h|r感染梦魇！"
D.Strings[90350]="|TInterface\\Icons\\Spell_Shadow_AuraOfDarkness:20|t%s开始施放|cFFFF0000|Hspell:203888|h[虹吸灵魂]|h|r！"
D.Strings[90351]="谢谢你，年轻人，感谢你来祭奠我的同伴。如果你需要他，艾特洛随时都能响应你的召唤。"
D.Strings[90352]="一切都将臣服于梦魇！"
D.Strings[90353]="哦，伟大的艾特洛，我将让你的遗骨重归大地母亲的怀抱，愿你的灵魂得到安息。"
D.Strings[90354]="我们开始吧，$n。"
D.Strings[90355]="启航前往风暴峡湾！"
D.Strings[90356]="我希望有一天能成为莱莎那样伟大的人，让她为我骄傲。"
D.Strings[90357]="你做好听课的准备了吗？"
D.Strings[90358]="就一个人？杀了这蠢货，保护好货物。别再吵我了！"
D.Strings[90359]="做好授课的准备后，就去跟鲁隆谈谈吧。"
D.Strings[90360]="我想前往苏拉玛王宫（团队副本）。"
D.Strings[90361]="被遗忘者已经准备好了。"
D.Strings[90362]="我想前往翡翠梦魇（团队副本）。"
D.Strings[90363]="黑暗女王将指引我们走向胜利。"
D.Strings[90364]="首先，我们会护送你前往阿格拉玛的宝库。之后，我们再去斯考德-艾希尔的惊魂港汇合。$B$B这应该会是一段平稳的航程。"
D.Strings[90365]="|TInterface\\Icons\\inv_fishing_lure_worm.blp:20|t%s的|cFFFF0404|Hspell:199176|h[尖刺之舌]|h|r瞄准了$n！"
D.Strings[90366]="你先去，德鲁伊。我们里头见。"
D.Strings[90367]="这块水晶上雕着三个空的插槽。你还没有足够的钥石来激活它。"
D.Strings[90368]="这块水晶上刻着三个空插槽。"
D.Strings[90369]="将三块至高岭仪式石放入水晶。"
D.Strings[90370]="这么做将会移除你背包中的3块|cFF00FF00|Hitem:130904:0:0:0:0:0:0:0:90:0|h[至高岭仪式石]|h|r。确定要这么做吗？"
D.Strings[90371]="你最近见过纳特吗？"
D.Strings[90372]="把鱼饵挂在鱼钩上，把鱼吃进肚子里。$b$b你可别把这两个步骤搞混了。"
D.Strings[90373]="在喷泉里钓鱼可能没什么意思……但总比在下水道里钓鱼强。"
D.Strings[90374]="你将钥石放入水晶后，它开始发出能量振动的嗡鸣声。"
D.Strings[90375]="不……不！海拉，赐予我更多的力量吧！"
D.Strings[90376]="冰冷智慧已经重置了寒冰宝珠的冷却时间，立刻施放寒冰宝珠吧。"
D.Strings[90377]="这边，萨满！拿上我的战矛，愿狂风指引你的矛头！"
D.Strings[90378]="通往达拉然的传送门就在大厅入口的上方。你可以沿着坡道走上去。"
D.Strings[90379]="我们的任务极其重要。"
D.Strings[90380]="天火号准备启航了。"
D.Strings[90381]="坚持住！你能做到的！"
D.Strings[90382]="你已经进步很多了！真的！"
D.Strings[90383]="小心偷袭！"
D.Strings[90384]="我见过不少鱼人猎手，可这个孩子有些不同！"
D.Strings[90385]="别再浪费你的时间去训练那个家伙了！"
D.Strings[90386]="就是这样！射他的膝盖！"
D.Strings[90387]="就是这样！射他的腿！"
D.Strings[90388]="戳眼睛，鱼人！"
D.Strings[90389]="我出一百个铜板，押半人马……呃……猫……人……"
D.Strings[90390]="猎人间的较量……真没想到我能见到这么一天！"
D.Strings[90391]="你们管这叫拳赛？横飞的鲜血呢？断裂的骨头呢？"
D.Strings[90392]="你要蒙住它们的眼睛。这可是驯兽的秘诀！"
D.Strings[90393]="如果让野兽嗅出你的恐惧，那你就死定了。还有香肠。如果让他们闻到香肠的味儿，那你肯定会受重伤的。"
D.Strings[90394]="别的猎人都在驯服宠物呢，你也不能干站着看。不过这只是我个人的建议，你明白吧？"
D.Strings[90395]="通往岩壁的道路似乎已经被肃清了。"
D.Strings[90396]="银色盟约随时准备支援隐秘通途。"
D.Strings[90397]="我不会放过任何一个威胁的，$n！"
D.Strings[90398]="我再也受不了这种无所事事的日子了！黑暗女王一定要马上放我们去对付那些联盟狗！"
D.Strings[90399]="没有肉吃了，除非我们能行动起来！这个守卫任务什么时候结束？"
D.Strings[90400]="那些杂种会自己送上门的。然后我们就能打击他们的气焰，吃他们的肉了！"
D.Strings[90401]="敌人会按照我们的步调来开战的。耐心点。很快，我们就有仗打了。"
D.Strings[90402]="牛头人也参与了营地的建设吗？"
D.Strings[90403]="昨晚下了点小雪，亲爱的。你最喜欢看纷纷扬扬的雪花了。"
D.Strings[90404]="数千年过去了，我的心中依然充满了悲伤。噢，娜穆莉亚……"
D.Strings[90405]="对于我们的组织，这是一个全新的黎明，亲爱的。你会为伊墨瑞尔骄傲的，她让我们团结在了新的领袖之下。"
D.Strings[90406]="虽然你的离去让我痛苦万分，但我会带着对你的怀念继续战斗的，亲爱的。"
D.Strings[90407]="我很想你，娜穆莉亚。"
D.Strings[90408]="融入暗影……"
D.Strings[90409]="让我们为这家伙干一杯吧。"
D.Strings[90410]="嘿，你，自然之友！来帮我教训一下这些卑鄙的偷猎者吧！"
D.Strings[90411]="拿着鱼去砸人，那这人今天肯定不会再钓鱼了。如果装成一条鱼去攻击他，那他这辈子都不会再钓鱼了！"
D.Strings[90412]="隐秘通途浴火重生了！"
D.Strings[90413]="这颗种子需要充足的空气和水。到我们身后的山上去找一个理想的地方吧。"
D.Strings[90414]="入侵者！你竟敢惊扰艾尔的圣殿！"
D.Strings[90415]="艾尔的怒火……会终结你的……"
D.Strings[90416]="我将重返暗影之中！"
D.Strings[90417]="神出鬼没。"
D.Strings[90418]="很好！这颗种子蕴藏着世界初生时的魔力。你很快就会看到它的用处。"
D.Strings[90419]="启动设备吧，布莱恩。"
D.Strings[90420]="再启动一下设备，布莱恩。"
D.Strings[90421]="好的，$g小子:丫头;，你自己小心点。"
D.Strings[90422]="保护格雷迈恩！为了吉尔尼斯！"
D.Strings[90423]="希尔瓦娜斯……休想……胜利……"
D.Strings[90424]="英雄，你的命运和那个带你踏上旅途的精灵有关。在离开前，我能把你送回那座天空之城。愿雄鹰之爪助你一臂之力。"
D.Strings[90425]="<这个幽灵说着什么，可你什么都没听见。$B$B他指了指你的装备。>"
D.Strings[90426]="那些剑……光是看一眼都会让我心底发寒。"
D.Strings[90427]="那把斧子上的骷髅看起来……很饥渴。"
D.Strings[90428]="那把剑……噢，不……那是天启！？幸好它没有落到燃烧军团手里！"
D.Strings[90429]="我肯定是生病了，这里好像突然热起来了。"
D.Strings[90430]="那些拳刃看起来很锋利！我敢打赌，它肯定能把石头切成两半！"
D.Strings[90431]="这还只是个开始！"
D.Strings[90432]="我们无处不在！"
D.Strings[90433]="准备面对你们的末日吧，$n！我，小虫图金斯，将毁灭这个世界！"
D.Strings[90434]="等等，住手！求你别杀我！"
D.Strings[90435]="如果你饶我一命，我就发誓效忠于你。还有这个，你看，我有一件珍贵的神器，也可以送给你。"
D.Strings[90436]="一位瓦格里从天而降，将你从死亡的边缘拉了回来！"
D.Strings[90437]="去死，去死，去死！"
D.Strings[90438]="<这只海龟的声音直接在你的脑海中响起。>$B$B你在我的这片水域中还是个陌生人。你来这里有什么目的？"
D.Strings[90439]="我将消失在黑暗中。"
D.Strings[90440]="爬到托古斯的背上。"
D.Strings[90441]="黑暗遮蔽了我的一举一动……"
D.Strings[90442]="我的战利品里又多了一颗脑袋。"
D.Strings[90443]="女妖之王向你问好。"
D.Strings[90444]="死神来找你了！"
D.Strings[90445]="使用信号枪标记出你的目标。我们的刺客会根据你的命令攻击的。"
D.Strings[90446]="过来，朋友。我有些东西可以帮你解决这些被遗忘者！"
D.Strings[90447]="冷静点，乌霍！"
D.Strings[90448]="羽鬃小猫淘气地扑着芦苇。"
D.Strings[90449]="部族最强大的武器和它的宿敌离我只有几步之遥了！我才不会被邪恶的迷雾法术给挡住呢！"
D.Strings[90450]="耐心点，兄弟。能看一眼雄鹰之爪也很有纪念意义了。看！我们的朋友回来了！"
D.Strings[90451]="你好，我能帮你什么忙吗？$b$b勒斯平派你来的？看来他都懒得亲自来一趟啊。$b$b好吧，我想我已经拿到报酬了，所以其实我已经不怎么关心这个戒指了。$b$b来吧，拿上这个戒指。告诉勒斯平，它最好值得我们这么大动干戈的。"
D.Strings[90452]="好吧，这可真让人意外。告诉我，勒斯平知道吗？"
D.Strings[90453]="这是欺骗！这是背信弃义！我们遭到入侵了！"
D.Strings[90454]="多么美好的一天啊，真是美好。"
D.Strings[90455]="我必须说声抱歉，但我现在没时间跟你谈话。我等在等人。"
D.Strings[90456]="就是想出去走走。我可能会去参观动物园。你最近去过那里没有？"
D.Strings[90457]="占位符。"
D.Strings[90458]="从这个有利位置，我可以盯着联盟通往悲伤沼泽的补给线。$b$b这是个费力不讨好的差事，可要是敌人去袭击我们驻扎在斯通纳德的部队，这差事就变得很重要了。"
D.Strings[90459]="别担心，班布利，我会把你的东西送到安全地带去的！"
D.Strings[90460]="让我们把这个圆盘组装起来，好吗？！"
D.Strings[90461]="这么说，这玩意儿跑到这儿来了……"
D.Strings[90462]="碎片都在这里了。为什么中间会有一个洞……？"
D.Strings[90463]="他曾经横扫千军，保家卫国！"
D.Strings[90464]="呃！别跟我说我们还少一块！"
D.Strings[90465]="好眼力！好吧，那是他的……我在一英里外就该看出来了！"
D.Strings[90466]="我会带你回家的，班布利！一块都不会丢下，我发誓！"
D.Strings[90467]="哎哟，这块好像被恶魔咬过了。呃，上面还湿哒哒的……"
D.Strings[90468]="那是班布利的匕首！我们要把它带回去，跟他的遗物埋在一起。"
D.Strings[90469]="维库人骑兵正在试探至高岭的边境防线。我们的盟友需要你的帮助，勇士。"
D.Strings[90470]="干得好。这下那些维库人应该明白，至高岭可不是什么软柿子。"
D.Strings[90471]="维库强盗在试探我们的边防。我们的部队太分散了，你能帮忙吗？"
D.Strings[90472]="哈哈！这下那些维库人应该明白，至高岭可不是软柿子。"
D.Strings[90473]="安古斯，我还活着！我在这儿！"
D.Strings[90474]="这是我的声音，笨蛋矮人！我还活着！"
D.Strings[90475]="小心邪火吐息！在他吐息时躲在障碍物后面！"
D.Strings[90476]="这顶冠冕曾经属于玛芙兰娜·月徽。它能够传导庞大的魔法能量，让她掌握近乎无限的魔法。$b$b在上古之战中，它被敌对的贵族偷走，上面镶嵌的珍贵宝石也被撬下卖掉了。虽然最终被找了回来，但没有了艾利斯宝石，它也失去了强大的力量。$b$b直到今天，这些宝石依然下落不明。"
D.Strings[90477]="放置炸药"
D.Strings[90478]="我会把科达娜的下场告诉其他守望者的。"
D.Strings[90479]="确定要离开这个副本吗？"
D.Strings[90480]="毁灭之锤……"
D.Strings[90481]="感谢你帮我们找回了那些酒！"
D.Strings[90482]="这真是金玉良言，低地人。"
D.Strings[90483]="还没有。和你一样，我也要在复仇和拯救人民之间做出选择。我非常纠结。"
D.Strings[90484]="他们告诉我你父亲也是被人杀害的。你为他复仇了吗？"
D.Strings[90485]="对我来说，拯救我们的人民就等于为我父亲报仇了。"
D.Strings[90486]="|TInterface\\Icons\\Spell_Fire_FelFlameRing:20|t斯科瓦尔德开始施放|cFFFF0404|Hspell:193826|h[诸神黄昏]|h|r！"
D.Strings[90487]="你要学会相信那些愿意帮助你的人。"
D.Strings[90488]="不，这是一个鲁莽领袖的经验之谈。"
D.Strings[90489]="这就是作为新领袖的经验之谈吗，低地人？"
D.Strings[90490]="胡恩在得到圣锤之前就统一了诸族？他是怎么做到的？"
D.Strings[90491]="他凝聚人心靠的是值得奋斗的事业，而不是武器。"
D.Strings[90492]="灰石卓格巴尔不知怎么弄到了一些源质。无论是他们还是至高岭诸族都不明白这种物质有多么危险。拜托了，把源质从他们手上夺回来。"
D.Strings[90493]="干得好。死亡之翼在大灾变中很重视这种矿石。它能成为邪恶势力手中的强大武器。"
D.Strings[90494]="奥拉尔德，你能帮我再铸造一套钥匙吗？"
D.Strings[90495]="当然可以！拿上这块金属，用熔炉熔化它。然后将它倒入模具中。然后，再把模具放在淬火水槽中冷却。"
D.Strings[90496]="卑贱的废物，这是你最后一次插手我们的事了！"
D.Strings[90497]="第40天：巨大的双头怪踏平了我在庄园里的工作室。我用魔法吓跑了他。感觉他还会回来的……"
D.Strings[90498]="我已经把入口的位置标在了你的地图上。等你准备好之后，就到那里来见我吧。"
D.Strings[90499]="你准备好了吗？这里有许多神器等着我们去发掘呢。"
D.Strings[90500]="进去之后，你就跟我走。没有我的命令，什么都不要碰。"
D.Strings[90501]="|TInterface\\Icons\\ability_priest_flashoflight:20|t奥丁开始施放|cFFFF0404|Hspell:198077|h[击碎长枪]|h|r！"
D.Strings[90502]="|TInterface\\Icons\\ability_thunderking_overcharge:20|t奥丁开始施放|cFFFF0404|Hspell:201215|h[召唤雷铸毁灭者]|h|r！"
D.Strings[90503]="每个人都要选择自己的道路。"
D.Strings[90504]="那我有哪些选择呢？"
D.Strings[90505]="你准备好之后，就穿过传送门进入梦境之路吧。我会在另一边等你的。"
D.Strings[90506]="谁敢来挑战莫格拉什国王！"
D.Strings[90507]="摧毁那个可悲的烂泥！"
D.Strings[90508]="碾碎这个卑微的蝼蚁！"
D.Strings[90509]="格雷迈恩的部队守住了这座塔。攻破他们的阵线！一个不留！"
D.Strings[90510]="决定性的胜利！联盟的走狗在部落的力量面前溃散了！"
D.Strings[90511]="进驻这座高塔将是个重大胜利。把被遗忘者赶下来，为了吉尔尼斯！"
D.Strings[90512]="精彩的胜利，这重创了被遗忘者。复仇属于吉尔尼斯旅，前进！"
D.Strings[90513]="跟我来，$c！"
D.Strings[90514]="快，$n！我们必须快一点！"
D.Strings[90515]="来吧，$n！"
D.Strings[90516]="决不能让魔誓军团在我们的岛上发展起来。你知道该怎么做的。"
D.Strings[90517]="干得好，$n。在削弱了魔誓者之后，我们距离解决这场麻烦只有一步之遥了。"
D.Strings[90518]="<第一阶段完成>"
D.Strings[90519]="<第二阶段完成>"
D.Strings[90520]="|TInterface\\Icons\\Spell_Arcane_MassDispel:20|t%s开始施放|cFFFF0000|Hspell:204471|h[聚焦冲击]|h|r。"
D.Strings[90521]="我还能听到班布利的声音在我脑海中回响，让我活下去。"
D.Strings[90522]="我会的，伙计！我会为了我们两个活下去的！"
D.Strings[90523]="|TInterface\\Icons\\ability_skyreach_wind:20|t%s开始施放|cFFFF0000|Hspell:204316|h[震荡波]|h|r。"
D.Strings[90524]="我更喜欢用埃提耶什的渡鸦形态。鞍马劳顿太难受了。"
D.Strings[90525]="恶魔猎手已经在岛屿的另一端扎营了。或许他们能帮我们找到创世之柱。"
D.Strings[90526]="看……纳迦的大军。看来我们得和艾萨拉女王竞争了！"
D.Strings[90527]="她肯定也在找创世之柱。这真是出人意料。"
D.Strings[90528]="燃烧军团的灾祸会摧毁你们脆弱的城市！"
D.Strings[90529]="你的城市完蛋了！"
D.Strings[90530]="如果你需要修理皮具，我很为乐意帮你。我所有的皮革都是从自然死亡的动物身上获取的。"
D.Strings[90531]="愚蠢的浣熊！这是你最后一次溜进我们的储藏室了！"
D.Strings[90532]="嗯？这噪音是从哪儿传来的？"
D.Strings[90533]="我很抱歉……"
D.Strings[90534]="多亏你，我才活了下来，曼格拉斯也死了。在更多恶魔涌来之前，我们快离开这里吧。$b$b我想我知道一条出去的近路，跟我来！"
D.Strings[90535]="带路吧，我跟着你。"
D.Strings[90536]="跟我来，我知道一条出去的路！"
D.Strings[90537]="嘿，伙计！这里现在是你的地盘了。最好的屋子就该留给大德鲁伊！"
D.Strings[90538]="有了你的帮助，塞纳里奥议会一定能恢复这片土地的平衡。我已经有预感了！"
D.Strings[90539]="赞吉吉想成为强大的大人物，就像你一样。我想，我可以留在这里帮你照看屋子，保证一切都井井有条的。而你，偶尔教我点东西就行了。"
D.Strings[90540]="那么，你怎么说，伙计？"
D.Strings[90541]="我承认，我是怀疑过你。我从没觉得有人能拿起你现在手里这把武器。"
D.Strings[90542]="我通常很少犯错。但这一次，我很高兴错的是我。"
D.Strings[90543]="你已经比我们议会中的许多资深成员都要强大了。但我能感觉到，你仍然有着极大的成长空间。"
D.Strings[90544]="大导师玛法里奥在等你。去吧，去接受你应得的嘉奖。"
D.Strings[90545]="假以时日，你的力量会增长到不可思议的境界。"
D.Strings[90546]="很高兴见到你，$n。我刚刚从雷姆洛斯那里听说了你的事迹。干得好！$b$b是时候让塞纳里奥议会正视你的功绩了。"
D.Strings[90547]="你的努力有目共睹，$n。你一再证明了自己是我们中最优秀的一员。"
D.Strings[90548]="你所展现出的力量，勇猛和高尚无与伦比。是时候让你得到应有的嘉奖了。"
D.Strings[90549]="我荣幸地宣布，$n将成为塞纳里奥议会的大德鲁伊！愿荒野众生都为此欢欣鼓舞！"
D.Strings[90550]="呃……你头上那是什么东西？"
D.Strings[90551]="纳迦使用这些寄生虫来控制弱小的生物，但我能够抵抗它们。$B$B我们形成了一种共生关系，我们的思维连为一体，因而我获得了与其他生物沟通的能力。$B$B如果你现在除掉它，那我们两个都会死的。"
D.Strings[90552]="我该把矿石放在哪儿？"
D.Strings[90553]="这块矿石很重，而且害我发痒。"
D.Strings[90554]="这个放在哪儿，伙计？"
D.Strings[90555]="我们的岗哨先被熊蹂躏了一遍，现在又有偷猎者来偷熊皮！这真是糟透了！"
D.Strings[90556]="多亏你的帮助，我们或许能夺回那座岗哨！"
D.Strings[90557]="那些熊把我们赶出屋子，还糟蹋我们的补给品。去赶走它们，顺便看看能不能抢救一些粮食回来。"
D.Strings[90558]="大地守护者的秘密是属于我们的！"
D.Strings[90559]="现在，死亡之翼的秘密属于我们了，帮凶！"
D.Strings[90560]="这些可怜的熊肯定被鹰身人诅咒了，真是可怕！请让它们解脱吧。"
D.Strings[90561]="连熊皮都报废了。鹰身人会付出代价的！"
D.Strings[90562]="|TInterface\\Icons\\inv_misc_herb_stormvine:20|t%s开始发出|cFFFF0000|Hspell:192985|h[愤怒嚎叫]|h|r！"
D.Strings[90563]="卓格巴尔掌握着死亡之翼时代的古老知识。我能听到万灵痛苦的哀嚎。你一定要阻止他们！"
D.Strings[90564]="这种黑色矿石，这种……源质，但愿卓格巴尔永远不会掌握这种武器。"
D.Strings[90565]="好了，$g小子:丫头;，我会在入口处等你的。你准备好进入之后，就来找我吧。"
D.Strings[90566]="我听说你知道一件上古武器的下落。"
D.Strings[90567]="不！我们来迟了！扎卡兹苏醒了！"
D.Strings[90568]="那个怪物似乎很迟钝……很迷茫。那把剑还在伤害它！快，在它彻底恢复前打倒它！"
D.Strings[90569]="你知道什么武器能够帮我们打败燃烧军团吗？"
D.Strings[90570]="我准备好了，布莱恩。我们走。"
D.Strings[90571]="你做到了我做不到的事，击败扎卡兹并活了下来。"
D.Strings[90572]="你知道应该怎么做。拿起灭战者，彻底消灭扎卡兹的威胁吧！"
D.Strings[90573]="噩梦终于结束了！我可以离开这里，获得安息了。"
D.Strings[90574]="愿艾露恩指引你的道路，$n。"
D.Strings[90575]="根据我的笔记，这段路有点难走，但应该不远。我们走！"
D.Strings[90576]="伊墨瑞尔·影卫是个高尚的人。至高岭的牛头人一直都是隐秘通途的盟友。$b$b我的祖先胡恩·高岭所使用的战矛叫做雄鹰之爪。几年前，战矛在与那头凶残的夜刃豹——达喀尔作战时遗失了。许多人都试图把它拿回来……可他们都失败了。$b$b我们的长老相信，要想将燃烧军团赶出我们的土地，就必须找回雄鹰之爪。$b$b我和我的兄弟乌霍准备去杀掉那头野兽，抢回战矛。如果你愿意跟我们一起去，那就万无一失了！"
D.Strings[90577]="我一直在和布莱恩·铜须合作，在破碎群岛上寻找战胜燃烧军团的契机。$b$b我们马上就要找到某个古代维库人督军的陵墓了。据说这个督军偷了一把强大的步枪，叫做泰坦之击。布莱恩已经彻底兴奋了，一直在唠叨着这把枪灌注了风暴之力什么的！$b$b听起来很有趣，对吧？如果你想去找它，我很乐意助你一臂之力！"
D.Strings[90578]="我的指挥官，游侠将军温蕾萨·风行者可能发现了她失踪多年的姐姐，奥蕾莉亚的线索。$b$b奥蕾莉亚对燃烧军团的了解对于我们的事业极其宝贵。她随身携带的那把弓，萨斯多拉更是一件强大的神器。$b$b只要你和游侠将军合作，一定可以把她们一起救出来的！"
D.Strings[90579]="那些邪恶的女巫想抢走我们的至高圣物：苍穹之角。我派了人去阻止她们，但毫无效果。你愿意帮忙吗？"
D.Strings[90580]="哈哈。就算我亲自出手，也不会做得更好了！谢谢你，勇士。"
D.Strings[90581]="我很感激影卫女士找到了你，$n。我们或许能给燃烧军团一个沉重的打击！"
D.Strings[90582]="小心！扎卡兹快走投无路了。他可能会改变战术！"
D.Strings[90583]="所以说，是伊墨瑞尔·影卫那个小丫头派你来找我的？看来她相当能说会道啊。$b$b我对她所在的这个隐秘通途一无所知，但我很乐意听听她想说什么。"
D.Strings[90584]="恩佐斯的低语从深渊传来，歌颂着难以言喻的恐怖。"
D.Strings[90585]="这些凡人结界对恩佐斯的后裔毫无作用！"
D.Strings[90586]="黑暗帝国曾是这个可悲世界的主宰，它必将再次崛起！我们将在这个王国的腐尸上重建恐怖的堡垒！"
D.Strings[90587]="黑暗帝国曾经统治这个世界，它必将再次崛起！在未来的千万年中，留给你们这些可怜虫的将只有绝望和悲伤！"
D.Strings[90588]="你的灵魂将永远迷失在那条无尽的螺旋长路上。"
D.Strings[90589]="上古之神在召唤。去吧……去吧……去吧……"
D.Strings[90590]="我不是第一个……也不会是最后一个……"
D.Strings[90591]="我流着恩佐斯的血脉……我不可能死……"
D.Strings[90592]="这条没有眼睛的盘蛇正在寻找无尽的天空。"
D.Strings[90593]="死亡之后，并不存在什么光明，只有一个连暗影都不敢进入的地方。"
D.Strings[90594]="你将第一个见证恩佐斯的疯狂！"
D.Strings[90595]="你只是被禁锢在躯壳中的囚犯，是恐惧的仆从！"
D.Strings[90596]="在恩佐斯翻滚的阴影之下，一切光明都将黯淡消逝。"
D.Strings[90597]="恩佐斯的意志已经实现了！它是不可抗拒的！"
D.Strings[90598]="这是真的还是幻觉？你疯了……疯了……疯了……"
D.Strings[90599]="你休想阻止我们。贾德维克必将陨落！"
D.Strings[90600]="嘿，朋友！我们想寻找一个“助手”帮我们测试这些武器，你有兴趣吗？"
D.Strings[90601]="哦，很好，原型机总算完好无损地回来了。而且，呃，你也活下来了！"
D.Strings[90602]="好啊，这一定很有趣？你需要赞吉吉做什么，就尽管吩咐吧。"
D.Strings[90603]="一直往前走到底，然后右转就是了。"
D.Strings[90604]="这里左转，我们马上就要到了。"
D.Strings[90605]="我们到了！你看那边，一个泰坦控制台！让我来，$g小子:丫头;。你只要别让任何东西在我工作时打扰我就行啦。"
D.Strings[90606]="我的剑归你了。斯多姆卡属于战场，而不是坟墓。它由铸剑大师所造，灌注了精灵魔法。我不知道在怪物体内埋了几百年是否对它有影响，但它定能成为你的得力助手。"
D.Strings[90607]="米露恩一边抽泣，一边努力深呼吸。"
D.Strings[90608]="我们能行，$n。加尼尔就靠我们了！"
D.Strings[90609]="我要这座塔楼，还有守塔的吉尔尼斯人的脑袋！进攻！"
D.Strings[90610]="噢，伙计们！我不知道该怎么办了！"
D.Strings[90611]="我们的部队胜利了！看看他们像狗一样仓皇逃跑的样子。为了部落！"
D.Strings[90612]="被遗忘者看起来很弱。夺取这座塔楼对我们来说简直轻而易举。让他们看看和联盟作对的下场吧！"
D.Strings[90613]="他们的防线崩溃了，连队长都倒下了。这是吉尔尼斯的复仇之声！为了联盟！"
D.Strings[90614]="抽取圣水"
D.Strings[90615]="发现入侵者。启动终止协议。"
D.Strings[90616]="当然可以了。$B$B梦境里有什么东西这么吸引你呢，大导师？"
D.Strings[90617]="我需要你的祝福，这样我才能进入翡翠梦境。"
D.Strings[90618]="啊！这听起来可不妙啊。挡住那个家伙，我来搞定这边。"
D.Strings[90619]="就快到了，$g小子:丫头;。再坚持一下。"
D.Strings[90620]="加尼尔已经被梦魇污染了。"
D.Strings[90621]="加尼尔遭到了威胁？那么我们不能再浪费时间了。"
D.Strings[90622]="就是这样，我明白了！"
D.Strings[90623]="房间内的反制机关已启动。"
D.Strings[90624]="欢迎，$n。树木的呢喃已经宣告了你的到来。"
D.Strings[90625]="恶心的纳迦从漆黑的海底洞窟里爬了出来。我决不容忍这种堕落的怪物！让他们看看什么才是光荣的战斗。"
D.Strings[90626]="纳迦是邪恶的怪物，无人理会就会变得很危险。由你来处死他们都算便宜他们了！"
D.Strings[90627]="愿艾露恩指引你的道路。"
D.Strings[90628]="终于自由了……你们休想再关住我。"
D.Strings[90629]="我正渴望新鲜的血液，你们就送上门来了。"
D.Strings[90630]="你早就该死在诺森德了。"
D.Strings[90631]="我的双螯又碾碎了一条生命。"
D.Strings[90632]="结束得太快了。真叫人失望。"
D.Strings[90633]="你们以为我只是个小麻烦吗，蠢货？"
D.Strings[90634]="我听不到巫妖王的召唤了……他抛弃我了吗……？"
D.Strings[90635]="可我注定要统治艾卓-尼鲁布……"
D.Strings[90636]="你们的力量毫无意义！"
D.Strings[90637]="我要把你们的骨头碾成粉末！"
D.Strings[90638]="你们只会剩下一点残渣！"
D.Strings[90639]="流血而死吧，废物。"
D.Strings[90640]="吃掉他们的血肉！"
D.Strings[90641]="我的同胞可以大吃一顿了……"
D.Strings[90642]="那些赫达沙尔的恶棍太过分了！那些维库人对至高岭发动了野蛮的袭击，抓走了许多俘虏。请帮我们救出那些同胞！"
D.Strings[90643]="维库人总是很狂妄，但这些邪恶的巨人太过分了。谢谢你让他们认清了自己的位置。"
D.Strings[90644]="别担心！$n会搞定的，等着吧！"
D.Strings[90645]="前面……看来就是拷问区。"
D.Strings[90646]="小心点。梦境里已经不安全了！"
D.Strings[90647]="梦境的情况恐怕比我们想的还要糟。"
D.Strings[90648]="你还有月井之水吧？很好！看来你准备好了。"
D.Strings[90649]="现在，放松，把精神集中到梦境里。我会指引你的灵魂。"
D.Strings[90650]="我会指引你的。祝你好运。"
D.Strings[90651]="对这个目标假人使用背刺。从背后攻击可以造成更多的伤害。"
D.Strings[90652]="好奇的鹰头小猫伸出爪子轻轻碰了碰这个杯子。"
D.Strings[90653]="好奇的鹰头小猫直视着瓦尔莎拉流亡者的双眼。"
D.Strings[90654]="好奇的鹰头小猫把杯子从桌上推了下去。"
D.Strings[90655]="瓦尔莎拉流亡者试图轰走小猫。"
D.Strings[90656]="潜行者擅长阴谋诡计。还有什么能比在敌人察觉前出击更狡猾的呢？潜行能让大部分敌人都看不见你。在潜行状态下，你可以使用出更多克敌制胜的手段。"
D.Strings[90657]="|TInterface\\Icons\\spell_fel_elementaldevastation:20|t克洛苏斯举起右手，开始引导|cFFFF0404|Hspell:201215|h[邪能光束]|h|r！"
D.Strings[90658]="|TInterface\\Icons\\spell_fel_elementaldevastation:20|t克洛苏斯举起左手，开始引导|cFFFF0404|Hspell:201215|h[邪能光束]|h|r！"
D.Strings[90659]="耐心点……"
D.Strings[90660]="好的，兄弟。*叹气*"
D.Strings[90661]="维库渣滓！我将报仇雪恨。"
D.Strings[90662]="感谢大地母亲，你总算及时赶到了。他们正要对我们下毒手。"
D.Strings[90663]="谢谢你，勇士。我可以自己离开这里的。"
D.Strings[90664]="维库人的攻势越来越凶猛了。小心。"
D.Strings[90665]="是时候去找些武器了！"
D.Strings[90666]="他们的袭击凶猛而迅速。我很多年没有看到维库人这么攻击了。"
D.Strings[90667]="我真不敢想象他们会怎么对待我们。"
D.Strings[90668]="你能听见吗，$n?"
D.Strings[90669]="加尼尔就在上面的诸灵之环里，可它让梦魇渗入了兽穴。你必须在被梦魇控制之前尽快行动！"
D.Strings[90670]="又来了一个勒斯平的走狗？我已经受够他了。让我的宠物好好教训你一顿吧！"
D.Strings[90671]="够了，拿去吧！别伤害我。箱子就在那边。"
D.Strings[90672]="你肯定赶了很远的路来挑战我。如果你想战斗，那我乐意奉陪。输的人要请吃晚餐。"
D.Strings[90673]="透不过……气了……"
D.Strings[90674]="我透不过气了……"
D.Strings[90675]="哪里……什么……"
D.Strings[90676]="愚蠢的鱿鱼！"
D.Strings[90677]="从我面前滚开！"
D.Strings[90678]="打得好！各大部族都会传唱你的英勇事迹的。现在，到底是赢家还是输家请客呢？"
D.Strings[90679]="这些该死的纳迦！"
D.Strings[90680]="不能放弃。我们必须战斗下去！"
D.Strings[90681]="愿元素与你同在。"
D.Strings[90682]="请接受我的报答吧。"
D.Strings[90683]="我必须立刻去警告酋长！"
D.Strings[90684]="让元素指引我的刀剑。"
D.Strings[90685]="这片土地……怎么变成这样了？"
D.Strings[90686]="我得去看看其他人了，但这应该能有所帮助。"
D.Strings[90687]="看来你需要一点帮助啊。"
D.Strings[90688]="很抱歉，$n，可我必须走了。"
D.Strings[90689]="我想再练习一下。"
D.Strings[90690]="我必须去警告其他人！"
D.Strings[90691]="$n——我必须立刻把这些事汇报上去！"
D.Strings[90692]="最好别跟这些恐魔交战。我们溜过去！"
D.Strings[90693]="我的魔法为你而战，$n。"
D.Strings[90694]="看来我低估了燃烧军团的实力。我能加入你的队伍吗？"
D.Strings[90695]="哈。我最喜欢的就是做训练了。"
D.Strings[90696]="有人吗……救命！我被根须缠住了！"
D.Strings[90697]="迷路的鹰头小猫耸动鼻子嗅着空气中的气味，一边唧唧叫着辨认周围的环境。"
D.Strings[90698]="你跑哪儿去了，美味的小东西？"
D.Strings[90699]="我的午餐，你跑哪儿去了？"
D.Strings[90700]="好饿。"
D.Strings[90701]="肉在哪儿？！"
D.Strings[90702]="我要吃羽鬃猫！"
D.Strings[90703]="图鲁克之子，麦罗克正在召集邪能图腾的部队对付我们。快去把他们入侵黯石洞穴的计划扼杀在摇篮里吧！"
D.Strings[90704]="鲜血图腾会为听从恶魔主子的命令而后悔的。"
D.Strings[90705]="邪能图腾想要在图鲁克断崖开启一座传送门。我一点都不想知道他们想要把什么东西放进来。"
D.Strings[90706]="谢谢你。你在他们穿过传送门之前阻止了他们。"
D.Strings[90707]="现在，邪能图腾在腐蚀他们自己的水源，想让整个大自然都与我们为敌。"
D.Strings[90708]="你阻止了邪能腐蚀的扩散，防止了我们的水源被玷污。你的恩情，我们永世不忘。"
D.Strings[90709]="这条路堵住了！我来清除障碍。"
D.Strings[90710]="使用暗影打击攻击目标假人。"
D.Strings[90711]="成了！你继续前进。我来解决下面的家伙。"
D.Strings[90712]="现在，你已经累积了5个连击点数，是时候发动刺骨了。当你使用5个连击点数发动刺骨时，能够造成大量伤害，并立即进入潜行状态。"
D.Strings[90713]="使用5个连击点数发动刺骨。"
D.Strings[90714]="为什么总会多一个螺丝？它肯定应该在某个地方……"
D.Strings[90715]="真该死！这要好几个小时才能修好！"
D.Strings[90716]="|TInterface\\Icons\\Spell_Fire_FelFlameStrike:20|t克洛苏斯使用|cFFFF0404|Hspell:205344|h[毁灭宝珠]|h|r瞄准了你！"
D.Strings[90717]="你还好吗？最艰难的阶段已经过去了。"
D.Strings[90718]="你就快成功了！保持专注！"
D.Strings[90719]="我们的巨鹰盟友筑巢的地方充斥着鹰身人。她们想开战？哈！那就战吧！"
D.Strings[90720]="我想你应该听说过胡恩·高岭，但你听说过这个部族里其他人的故事吗？他们也是上古之战中的英雄。"
D.Strings[90721]="让我看看他们的故事吧。"
D.Strings[90722]="哈哈！干得好，勇士。这下那些女巫应该学乖了。"
D.Strings[90723]="罗克又来了！如果他长得太大，会引发地震的。我们需要时不时打碎一些岩石来帮助他保持稳定。你愿意帮忙吗？"
D.Strings[90724]="这足以打得他找不着北了！"
D.Strings[90725]="你的匕首玩得越来越熟练了。接下来我们该完善你的技巧了。"
D.Strings[90726]="对一个目标使用暗影打击，用背刺生成5个连击点数，然后用刺骨干掉对方。这应该能让你进入潜行状态，然后就可以用暗影打击对付下一个目标了。"
D.Strings[90727]="抱歉，$n。我得在你陷入深度沉睡前唤醒你。"
D.Strings[90728]="小心点，我感觉到梦魇在侵袭你的头脑！"
D.Strings[90729]="你得提高警惕。千万不能让梦魇控制你。"
D.Strings[90730]="你成功了，$n。只要再收集几样东西，我们就能开始了。"
D.Strings[90731]="放松头脑，让你的灵魂进入翡翠梦境。我会跟上你的。"
D.Strings[90732]="天上……地狱火——来袭！"
D.Strings[90733]="喝下这瓶月井之水，它能帮你放松并进入翡翠梦境。然后躺在这块石头前，我们就能开始了。"
D.Strings[90734]="海卫士死了，我的族人已经安全了。我该回贾德维克去了。"
D.Strings[90735]="是邪能舰炮！散开！"
D.Strings[90736]="蠢货！当你们在这个渺小的岗哨里负隅顽抗时，我们的大军早已在你们神圣的土地上横行了！"
D.Strings[90737]="卑微的凡人！该让你们感受一下燃烧军团的力量了！"
D.Strings[90738]="是巨怪！东门需要支援！"
D.Strings[90739]="守住阵线！一个敌人都不要放过！"
D.Strings[90740]="毁灭之锤就在这些大厅的某处。我能感觉到。"
D.Strings[90741]="去探查一下前面的大厅吧……我就留在附近……"
D.Strings[90742]="审判团无所不知！所有的真相！所有的谎言！"
D.Strings[90743]="你以为你能击败我的蜗牛？"
D.Strings[90744]="这就更应该先去找毁灭之锤了。"
D.Strings[90745]="至少死蜗牛还很美味。"
D.Strings[90746]="你被蜗牛碾压了！"
D.Strings[90747]="噢！晚餐！"
D.Strings[90748]="我打算把他留到下一顿再吃。"
D.Strings[90749]="看来他已经被煮熟了。"
D.Strings[90750]="你的脸上沾了一点泥。"
D.Strings[90751]="如果你不想要了，我可以用它炖一锅好汤！"
D.Strings[90752]="快，伙计们。我们在这里坚持不了多久。"
D.Strings[90753]="快点找，伙计们。"
D.Strings[90754]="快，伙计。找到你要的东西，否则就放弃吧。"
D.Strings[90755]="拿了就走！拿了就走！我们要走了！"
D.Strings[90756]="进来两个驯宠师，一个收获胜利，一个收获晚餐。"
D.Strings[90757]="还早着呢，帮凶。你们休想过去。"
D.Strings[90758]="照看好萨尔。他受伤了。他刚才差点害死自己，我可不想去给他妻子报丧！"
D.Strings[90759]="毁灭之锤……它在我手中就死气沉沉的。元素寂静无声。自从我用它杀了加尔鲁什之后，它就变成这样了。"
D.Strings[90760]="在一个兽人和他的人民面前，你的军团不算什么，恶魔！"
D.Strings[90761]="圣光啊……看！那是她的弓——萨斯多拉！"
D.Strings[90762]="奥蕾莉亚来过这里……她的弓就是证据！她显然逃跑了，而那个审判官想用我把她引回来。"
D.Strings[90763]="它配得上奥蕾莉亚……和你这样的英雄。收下它吧，$n。用它带领大家拯救艾泽拉斯！"
D.Strings[90764]="卑微的凡人！你们的傲慢将会招致灭亡！"
D.Strings[90765]="我们得继续前进了。格斯逊就在附近……"
D.Strings[90766]="帮帮我！我快要压制不住这些腐蚀了！"
D.Strings[90767]="要不是你及时赶到，我肯定会被击垮。谢谢。"
D.Strings[90768]="现实世界见。"
D.Strings[90769]="古树在上，你拿到了加尼尔！"
D.Strings[90770]="加尼尔坚持不了多久。我们必须净化它。"
D.Strings[90771]="毁灭之锤！拿起毁灭之锤！证明你作为萨满的力量……"
D.Strings[90772]="你吸收了蓝风电鳗的电能！"
D.Strings[90773]="你赶上了燃烧军团对达拉然的第一次袭击。这些囚犯会让这座城血流成河。可惜你看不到那一天了。"
D.Strings[90774]="达拉然的陨落就从这里开始。这些囚犯会让这座城血流成河。然后，燃烧军团就会让它摔得粉身碎骨！"
D.Strings[90775]="你的盔甲可以保护你不受刀剑和利爪的伤害，但它对无面者毫无用处。只要一句呢喃，它就能让凡人发疯。"
D.Strings[90776]="我见识过的恐怖足以让你最黑暗的噩梦都黯然失色，可就连我都没见过这么可怕的玩意儿……一个愤怒的侏儒发明家。"
D.Strings[90777]="我能感觉到这个侏儒内心滔天的怒火和无尽的痛苦。她将这些感情压抑得太久了……爆发只是时间问题。"
D.Strings[90778]="就算有魔法结界，我都能闻出这个该死的憎恶的臭气。请你帮个忙，干掉它，好吗？"
D.Strings[90779]="援军来了！击退他们！"
D.Strings[90780]="啊……就连我都听说过颤栗之喉。她是一头堕落的蓝龙，原本名叫爱尔达苟萨。她一定能让达拉然的天空都瑟瑟发抖。"
D.Strings[90781]="鲜血公主萨安娜……被囚禁了这么多年，你一定饿了吧。去吧，让达拉然满足你对鲜血和灵魂的渴望吧！"
D.Strings[90782]="萨莱因家族都是一群冷酷且傲慢的家伙。他们会为了取乐而制造痛苦。总之，他们听着就合我的胃口。"
D.Strings[90783]="地穴领主向来不懂得接受失败。被关在这座监狱里这么长时间，一定会让它生气的……而且是非常、非常生气。"
D.Strings[90784]="整个艾泽拉斯都会起来反抗你的，恶魔。"
D.Strings[90785]="来吧，阿努贝斯特！你说自己是伟大的地穴领主，却连这座监狱都钻不出去？让我看看你到底有什么可怕的！"
D.Strings[90786]="你们脚下的大地和头顶的天空都会跟你们该死的远征作对的！"
D.Strings[90787]="我还以为那些囚犯有多厉害呢。既然他们都干不掉你，那我只能亲自动手了。"
D.Strings[90788]="够了！这些囚犯都是废物。还是老话说的好：“你想要好好毁掉一座浮空城的话，就得亲自上阵。”"
D.Strings[90789]="达拉然很快就会步上你的后尘。"
D.Strings[90790]="我可不像那些囚犯那么好对付，对吧？"
D.Strings[90791]="又一个所谓的英雄落到燃烧军团手里了！"
D.Strings[90792]="现在，让这座高高在上的城市从天空中消失吧……"
D.Strings[90793]="在达拉然坠落后，这个世界还能有什么希望？"
D.Strings[90794]="可惜……我看不到这个世界……熊熊燃烧了……"
D.Strings[90795]="你们……迟早会……完蛋的……"
D.Strings[90796]="这些人疯了，以为这座宝库里有他们最伟大的传奇英雄：灰石之王、"
D.Strings[90797]="灰石之王是一个极其邪恶的卓格巴尔，奈萨里奥将他封印在岩石里，作为对我们的警告。我们决不能让这些狂热分子把他放出来。"
D.Strings[90798]="该死！灰石之王已经被放出来了。我们必须在宝库守护者回来之前离开这里。"
D.Strings[90799]="这装置似乎在吸收虚空能量，那是玛里苟斯将魔网接入扭曲虚空时释放的。"
D.Strings[90800]="毁灭之锤选择了你，萨满。你所掌握的力量已经超过了我。"
D.Strings[90801]="我有我自己的路。我还有很多想法要实现。阿格娜很快就会赶来大漩涡。听听她的建议吧……她教会过我很多。"
D.Strings[90802]="回大地之环去，把他们召集起来。用他们的力量对抗燃烧军团吧。你的时代已经降临了。"
D.Strings[90803]="这种设计看起来很眼熟……"
D.Strings[90804]="这把武器已经被灌注了来自扭曲虚空的黑暗能量。"
D.Strings[90805]="无论是谁得到它，都会想要驾驭虚空的能量。可目的是什么呢？"
D.Strings[90806]="这个传送门很像虚灵在外域使用的那种。"
D.Strings[90807]="会是他们吗？玛里苟斯到底向他们承诺了什么？"
D.Strings[90808]="叔叔！"
D.Strings[90809]="丽丽，我们去看看孩子们。"
D.Strings[90810]="全听你的，陈叔！"
D.Strings[90811]="加尼尔的腐蚀每时每刻都在加重。但愿你还来得及！"
D.Strings[90812]="不久前，哈缪尔·符文图腾带领一支小队去诺达希尔附近调查军团的活动了。他或许能帮你。"
D.Strings[90813]="杀光他们……为了贾德维克……"
D.Strings[90814]="愿古树赐福予我们。"
D.Strings[90815]="净化了加尼尔，就能帮大德鲁伊巨蹄清理梦境林里的梦魇了。"
D.Strings[90816]="但愿加尼尔还有救。"
D.Strings[90817]="你太迟了，废物！灰石之王就要自由了！"
D.Strings[90818]="卓格巴尔正在攻打雷霆图腾，可我们大部分兵力都被燃烧军团牵制住了。你能帮帮我们吗，勇士？"
D.Strings[90819]="这是个血的教训，我不会再盲目分兵了。谢谢你，勇士。"
D.Strings[90820]="去镇中心！上坐骑！我们开路！"
D.Strings[90821]="$n……感谢上古诸神，你终于来了。"
D.Strings[90822]="那些堕落的鱼人还在想方设法破坏船只！如果你能帮忙从那些船只残骸上找些补给品回来，我们一定感激不尽。"
D.Strings[90823]="我一直在努力把鱼人们引上正道。在错误的领导下，它们很快就会失控的。"
D.Strings[90824]="沼岩鱼人又不干好事了！那个骑着螃蟹的家伙要带他们去干坏事了。"
D.Strings[90825]="想到你对那些小可怜所做的一切，我就忍不住发抖，但这是无法避免的。"
D.Strings[90826]="奔波尔霸需要你的帮助！响盐龙虾人纠结了大批同伙，想要攻击他好不容易占领的巢穴。"
D.Strings[90827]="有了你的指引，奔波尔霸和他新生的部族又安全了。"
D.Strings[90828]="奔波尔霸召集的蝌蚪都在挨饿！不过我们很走运。有一个蟹群开始迁徙了，它们的肉非常鲜美！别问我怎么知道……"
D.Strings[90829]="你听到蝌蚪洞穴里快活的叫声了吗？他们会长大并变得强壮的！"
D.Strings[90830]="一大群响盐龙虾人正在海滩上耀武扬威。可我觉得奔波尔霸还不够强大，没有外援的话很难打败他们！"
D.Strings[90831]="奔波尔霸很擅长学习新东西！不过他有时同样容易忘记我的教导。"
D.Strings[90832]="塞纳留斯的追随者来我的巢穴干嘛？"
D.Strings[90833]="森林里的女巫太狂妄了。在我们追杀邪能图腾时，她们居然离开森林袭击了我的人民。"
D.Strings[90834]="那些邪恶的鹰身人最好呆在树上，否则我们就让这片森林化为羽林血海。"
D.Strings[90835]="黑暗会吞噬你的！"
D.Strings[90836]="不要招惹山岭！"
D.Strings[90837]="软弱的外来者！你不该来这儿！"
D.Strings[90838]="帮凶！跟牛头人一起去死吧！"
D.Strings[90839]="岩石响应我的召唤！"
D.Strings[90840]="你的血应该不错……"
D.Strings[90841]="去死吧，帮凶！"
D.Strings[90842]="我们是高山下的黑暗！"
D.Strings[90843]="畏惧这黑暗吧！"
D.Strings[90844]="让黑暗吞没你！"
D.Strings[90845]="岩石！听我号令！"
D.Strings[90846]="蠢货！来看看你死得有多快吧！"
D.Strings[90847]="预言中的景象非常混乱、模糊。我需要集中精神。"
D.Strings[90848]="我要集中精神理解这个幻象。请在此期间保护好我，$n。"
D.Strings[90849]="好的，泰兰德。"
D.Strings[90850]="他们……太多了……"
D.Strings[90851]="我们是来清理一群落单的恶魔犬的。可我们却发现……"
D.Strings[90852]="冥狱之门向我们敞开了。它们无处不在……"
D.Strings[90853]="先去照顾其他人。他们的伤比我严重得多。"
D.Strings[90854]="啸天者，你得通知梦境林地。我们今天的牺牲者已经够多了。"
D.Strings[90855]="你对奥蕾莉亚做了什么，你这个怪物？"
D.Strings[90856]="说吧，$r。你为何要打扰我休息？"
D.Strings[90857]="她在这里呆了几天？几年？几个世纪？那个法师说的对……时间在这里毫无意义。"
D.Strings[90858]="<古树期待地望着你。>"
D.Strings[90859]="蠢牛！今天就是你的死期！"
D.Strings[90860]="谢谢你，$n。我们差点就没顶住上一波攻击。"
D.Strings[90861]="哦，我的头……我头晕……"
D.Strings[90862]="燃烧军团还没忘记上次的失败。"
D.Strings[90863]="这口井差点就毁于突袭。但只要还有一滴水，我们就有希望！"
D.Strings[90864]="阿什阿拉，过来。"
D.Strings[90865]="别让任何人干扰我冥想。我要看破混沌的迷雾。"
D.Strings[90866]="祝福你，$n。我的灵魂都快要回到神灵的怀抱了。"
D.Strings[90867]="你真的准备好了吗？这将是你遇到过的最艰难的任务。"
D.Strings[90868]="他仍然下落不明，但他还活着。"
D.Strings[90869]="我们必须深入梦魇。无论他在哪里，肯定都已经陷入了危险！"
D.Strings[90870]="我看见……翻卷的红色迷雾、磨动的利齿。"
D.Strings[90871]="玛法里奥！他很痛苦！坚持住，亲爱的！"
D.Strings[90872]="这恶毒的笑声……萨维斯，你这冷血怪物！我来找你了！"
D.Strings[90873]="我只希望我们不会太迟。"
D.Strings[90874]="仪式准备好了，$n！"
D.Strings[90875]="准备就绪。我们可以开始了。"
D.Strings[90876]="这片土地属于虫爪部族！呱！！！"
D.Strings[90877]="回避难所来见我吧，我们得继续研究。"
D.Strings[90878]="最后，你还有一课要学。有时候，为了保存有生力量，战术性撤退是必须的。消失能让你脱离战斗并快速脱逃。"
D.Strings[90879]="使用消失躲过这个暴徒。"
D.Strings[90880]="这一地区的鱼都在逆流而上……好吧，我也不知道它们要游去哪儿，但它们似乎都很兴奋。这可是叉鱼的好机会！"
D.Strings[90881]="来吧。我们得尽快行动。"
D.Strings[90882]="你一条都没漏掉！你钓了多久的鱼了，伙计？"
D.Strings[90883]="北海的梭鱼肉质肥厚，但很难捕捉。有些牛头人萨满可以用水面行走法术来帮助你捕鱼。"
D.Strings[90884]="唔……黑梭鱼。与蜗牛和洋葱同煮时最美味。"
D.Strings[90885]="第一个试炼将考验你的力量。你将面对我最强大的追随者。让我看看你确实有熊的力量！"
D.Strings[90886]="有岔路。等等，你看到了吗？"
D.Strings[90887]="羽毛和鲜血……血迹还没干！可能还来得及！"
D.Strings[90888]="这里的腐蚀很严重。桥那边是什么东西？小心点。"
D.Strings[90889]="埃洛瑟尔？天呐……连你都……你看见我丈夫了吗？"
D.Strings[90890]="找到布里塔格，杀了那个纳迦……"
D.Strings[90891]="我会准备好净化所需的井水。"
D.Strings[90892]="你得保护我直到仪式完成，否则加尼尔就完了！"
D.Strings[90893]="它不配让乌索尔动手！我来碾碎它！"
D.Strings[90894]="太……强大了！住手！别打了！"
D.Strings[90895]="你证明了自己的力量。可你有足够的勇气面对险境吗？如果你想挑战自己，就告诉我吧！"
D.Strings[90896]="有人想要来斗蜗牛吗？我，奥多格，斗蜗牛总冠军，接受任何挑战者的挑战啦！时间有限，机不可失！"
D.Strings[90897]="不可思议！你是真正的勇士！"
D.Strings[90898]="接着是下一个试炼。击败那些灵体，证明你有着熊的勇气！"
D.Strings[90899]="了不起！你的勇气毋庸置疑！还有最后一个试炼。"
D.Strings[90900]="我和乌索克是好搭档。他负责攻击，而我负责掩护。我们两个联手，就能百战百胜。"
D.Strings[90901]="在一次混乱的远古之战中，我和我兄弟失散了。在他最需要我的时候，我却不在他身边。"
D.Strings[90902]="在这个试炼中，你要证明自己能保护那些将生命托付给你的人。你要完成我没能做到的事。"
D.Strings[90903]="你又跑回来妄图阻止我了？你的确很大胆……或者说很愚蠢。"
D.Strings[90904]="保护好她。如果无人保护，她很快就会倒下的。"
D.Strings[90905]="情况有些不对。万灵正在哀嚎。"
D.Strings[90906]="传送门激活了！"
D.Strings[90907]="在我面前颤抖吧！我将黑暗带到了这个世界。"
D.Strings[90908]="他还活着，所以我要继续深入梦魇。"
D.Strings[90909]="军团的战舰！准备！如果失去贫瘠之地，卡利姆多就完了！"
D.Strings[90910]="那是什么……"
D.Strings[90911]="我会让你吃尽苦头的！"
D.Strings[90912]="下一个试炼可不容易，$c。你要接受挑战吗？"
D.Strings[90913]="所以说，是伊墨瑞尔·影卫那个小丫头派你来找我的？看来她相当能说会道啊。$b$b我对她所在的这个隐秘通途一无所知，但我很乐意听听她想说什么。$b$b我可能不太习惯跟你们部落的人合作，但燃烧军团威胁到了我们所有人，无论对矮人还是$r都是一样。是时候搁置争议，一致对外了！"
D.Strings[90914]="树木呢喃着他的名字，可在我听来全是疯话！"
D.Strings[90915]="你得帮我找到他！我能做点什么吗？"
D.Strings[90916]="你不行，但或许……你的月神可以。"
D.Strings[90917]="又一个虚灵技术的证据。这恐怕会是个不幸的转折。"
D.Strings[90918]="揪出幕后黑手的方法只有一个。"
D.Strings[90919]="我们必须快点行动。去跟米尔拉谈谈，然后跟我进入大漩涡。"
D.Strings[90920]="雷加尔有个计划，跟他谈谈。你们能并肩作战，是件好事。"
D.Strings[90921]="埃鲁纳克熟悉艾泽拉斯最黑暗的海底深渊。他知道接下来该怎么做。"
D.Strings[90922]="你逃不我出的手心，米尔豪斯！想都别想！"
D.Strings[90923]="我会向艾露恩祈祷。梦魇的腐蚀无法清除……但或许能逼退它。"
D.Strings[90924]="够久了……去找他……*埃洛瑟尔呻吟着*森林在低语……我快明白了……"
D.Strings[90925]="坚持住，不要陷入疯狂，埃洛瑟尔！月神会尽力帮助你的。"
D.Strings[90926]="玛法里奥到腐蚀的核心地带去了！快，泰兰德，去沙拉尼尔！我们没时间了！"
D.Strings[90927]="我要去找他！埃洛瑟尔？"
D.Strings[90928]="疯狂……控制了我……"
D.Strings[90929]="萨斯多拉本是我家传的宝弓……可它现在有了更高的目标。"
D.Strings[90930]="<埃洛瑟尔的躯壳毫无反应。梦魇已经控制了它。>"
D.Strings[90931]="<埃洛瑟尔瘫软的身体空洞地凝视着远方。>"
D.Strings[90932]="<埃洛瑟尔对外界刺激彻底失去了反应。>"
D.Strings[90933]="<梵妮莎警惕地上下打量着你。>"
D.Strings[90934]="让我们做个了断吧！"
D.Strings[90935]="谁敢……？啊，看看这是谁啊？"
D.Strings[90936]="又有入侵者来抢夺魔枢宝库的宝藏了！"
D.Strings[90937]="你太迟了，$c！宝库的力量正在扩大连通扭曲虚空的裂口。"
D.Strings[90938]="有了这股力量，复仇军将所向披靡。我们就是虚空！"
D.Strings[90939]="无论虚灵想干什么，他们正在聚集庞大的虚空能量。"
D.Strings[90940]="他们肯定用了玛里苟斯的湍流之针。飞过去，让我们仔细检查一下。"
D.Strings[90941]="复仇军改装了湍流之针。它们正在引导裂隙产生的虚空能量。"
D.Strings[90942]="它们的力量肯定也在维持着魔枢周围的护盾。让我们来看看底座。"
D.Strings[90943]="宝库肯定被削弱了。你神器中的能量正在散逸。"
D.Strings[90944]="这或许能为我们所用……"
D.Strings[90945]="保住我们的命，我们就能为你争取足够的时间。"
D.Strings[90946]="为了加尼尔！"
D.Strings[90947]="没有时间悲痛了，埃洛瑟尔没救了。跟我来。"
D.Strings[90948]="沙拉尼尔就在前面。准备好，我们可能遭遇各种邪恶。"
D.Strings[90949]="我来了，玛法里奥！"
D.Strings[90950]="这个动物摇晃着脑袋，清醒过来了！"
D.Strings[90951]="%s|cFFFF0404倒在了战场上|h|r，无法继续战斗了！"
D.Strings[90952]="绑住他的双手！别让他施法——啊！"
D.Strings[90953]="我听到亭子附近有打斗的声音！玛法里奥？！回答我！"
D.Strings[90954]="哈！如果你有本事的话，就来把他抢回去吧，暗夜精灵！"
D.Strings[90955]="天气晴朗，群马奔腾，这真是个打猎的好日子！"
D.Strings[90956]="是马！呸！我要去找穆山兽。让我们看看到底谁的猎物更好。"
D.Strings[90957]="你会屈服的，德鲁伊！"
D.Strings[90958]="援军来了！清理出一条通道来，让他们过来！"
D.Strings[90959]="我不想失去你！"
D.Strings[90960]="恶魔的攻势猛烈。我需要支援！"
D.Strings[90961]="站稳！他们过来了！"
D.Strings[90962]="以玛诺洛斯的名义！"
D.Strings[90963]="享用他们的血肉吧。"
D.Strings[90964]="这真是个值得骄傲的战利品！"
D.Strings[90965]="在我的老家，我们只会为了食物狩猎。我才不羡慕你能吃到那么多穆山兽肉呢。"
D.Strings[90966]="一群待宰的羔羊。"
D.Strings[90967]="你的生命在流逝。"
D.Strings[90968]="%s开始施放|cFFFF0404|Hspell:204839|h[恶魔之怒]|h|r！"
D.Strings[90969]="%s开始施放|cFFFF0404|Hspell:204839|h[混沌弹幕]|h|r！"
D.Strings[90970]="那头大角鹿幼崽有危险！你一定要帮帮它！"
D.Strings[90971]="那些恶魔休想占领十字路口。"
D.Strings[90972]="我的利刃已经严阵以待了！"
D.Strings[90973]="我正想找人练练手呢。"
D.Strings[90974]="我已经在塔楼上看到了！散开！"
D.Strings[90975]="好险呐！我要把这头小鹿养在雷霆图腾里，直到它能保护自己为止。"
D.Strings[90976]="<殴打萨特。>"
D.Strings[90977]="有人需要我们的帮助。"
D.Strings[90978]="祖莫罗，跟我来！北门需要我们。"
D.Strings[90979]="哈！这应该能让那个骑着鹿头鹰的家伙明白什么叫狩猎了。"
D.Strings[90980]="时间到了，钦托卡。让我们准备战斗吧。"
D.Strings[90981]="很好。这些马应该够我们的鹰吃了。我就知道你会支持我的。"
D.Strings[90982]="你们都将倒在钢刀铁剑之下！"
D.Strings[90983]="附近的书籍都被撕碎了。整座旅店都好像刚被龙卷风刮过一样。"
D.Strings[90984]="你们不是部落的对手！"
D.Strings[90985]="让我的魔法吞噬你们！"
D.Strings[90986]="你们的腐蚀到此为止了。"
D.Strings[90987]="邪恶的家伙！"
D.Strings[90988]="让暗影吞噬你们！"
D.Strings[90989]="你们休想摧毁我们的土地。"
D.Strings[90990]="你们的力量在元素面前不堪一击！"
D.Strings[90991]="又能练习瞄准了。"
D.Strings[90992]="月井的力量正在增强。我们得继续前进！"
D.Strings[90993]="这力量时刻都在变强。胜利在望了！"
D.Strings[90994]="暗影……消散了？"
D.Strings[90995]="这个渺小的意志是什么，居然能把我从虚灵的陷阱中放出来？"
D.Strings[90996]="我们成功了！母亲之树完好如初了！"
D.Strings[90997]="$n，用加尼尔召唤森林之魂来摧毁这个恶魔吧！"
D.Strings[90998]="仪式就快完成了。不要放弃希望！"
D.Strings[90999]="伊瑟拉——不！"
D.Strings[91000]="跟我来。在整个国度化为梦魇之前，伊瑟拉是不会罢休的。"
D.Strings[91001]="萨维斯在利用玛法里奥干扰我，让我没法做该做的事。只有我们能阻止伊瑟拉了。"
D.Strings[91002]="啊，玛法里奥，亲爱的！他在月光林地的地下沉眠了数百年。"
D.Strings[91003]="我们的援军来了。做好准备！"
D.Strings[91004]="女巫秘地的鹰身人在用邪恶魔法腐蚀响风峭壁的生物。我们无法逆转她们的诅咒。请阻止她们的疯狂行径！"
D.Strings[91005]="这座山里的鹰身人向来不尊重生命。现在，她们正在不顾一切地滥用黑暗的仪式。"
D.Strings[91006]="陈说你会来的，$n。不能再浪费时间了，帮我们击退这些恶魔，夺回禅院吧！"
D.Strings[91007]="这个世界绝不会陷落，恶魔！大自然会起来反抗你们的！"
D.Strings[91008]="可悲的爬虫。这又是什么把戏？"
D.Strings[91009]="找到入侵者！夺回教堂！杀光他们！"
D.Strings[91010]="奥蕾莉亚的弓终于后继有人了。"
D.Strings[91011]="啊，对了，这下我记起来了。"
D.Strings[91012]="了不起的发现！"
D.Strings[91013]="莱莎是个好老师，可你比她更强！"
D.Strings[91014]="啊！它在那儿！"
D.Strings[91015]="噢，那是什么？"
D.Strings[91016]="我想我开始明白了。"
D.Strings[91017]="干得好。来看看我们有什么发现吧。"
D.Strings[91018]="这么多地方，这么点时间。如果你想去什么地方，我可以送你过去。"
D.Strings[91019]="能送我去天禅院吗？"
D.Strings[91020]="等你有5个连击点数后再使用刺骨！"
D.Strings[91021]="你有5个连击点数了。使用刺骨吧！"
D.Strings[91022]="风行者将军！你找到……"
D.Strings[91023]="使用背刺生成连击点数。"
D.Strings[91024]="奥蕾莉亚逃跑了，可还有萨斯多拉！它就在勇士的手上。"
D.Strings[91025]="太好了！它将鼓舞所有见到它的游侠！"
D.Strings[91026]="可惜，俄瑞斯忒斯牺牲了。我得去通知哈杜伦。来吧，兰斯伯。"
D.Strings[91027]="我这就来！"
D.Strings[91028]="这世界必将……燃烧……"
D.Strings[91029]="成功了！回梦境林地去，把胜利的消息告诉他们吧。"
D.Strings[91030]="我们得再停留一阵子，帮助啸天者欧穆隆的部队。"
D.Strings[91031]="谢谢你，$n。没有你，我们就死定了。"
D.Strings[91032]="让这些连翅膀都没有的畜生自相残杀吧。"
D.Strings[91033]="快，姐妹们，不能让那些卑鄙的部族发现我们的计划。"
D.Strings[91034]="快点，姐妹们。我们必须完成法术，到时不管是外来者还是牛头人，就都没法破坏它了！"
D.Strings[91035]="这些没有翅膀的家伙将成为我们的奴仆。"
D.Strings[91036]="河鬃部族的蠢货绝对想不到，荒野会给他们如此沉重的一击。"
D.Strings[91037]="不，姐妹。好好施法。这是巫后的命令。"
D.Strings[91038]="尼索格的子嗣在残忍屠杀你我的同胞。用同样的残酷回敬他们吧！把他们的鳞片扒下来！"
D.Strings[91039]="这可是你说的！谁带来的兽头大，就算谁赢。"
D.Strings[91040]="尼索格和他的子嗣都是最残酷的凶手。解决他们就等于帮助这个世界。"
D.Strings[91041]="这么快就被抢了风头，你肯定都挠破头了吧？哈！"
D.Strings[91042]="伟大的乌索尔，睿智的森林之熊，荒野的女儿呼唤你的降临！请接受这些卑微的祭品并显灵吧！"
D.Strings[91043]="我们砍杀了无数恶魔！他们根本不是艾泽拉斯勇士们的对手！"
D.Strings[91044]="加尼尔和诺达希尔也会被燃烧军团摧毁。"
D.Strings[91045]="我守护了加尼尔几百年。可今天，它差点被腐蚀了。是时候让别人来接替我了。"
D.Strings[91046]="再次感谢，大导师。我会留在梦境林地。如果你需要指导，就来找我吧。"
D.Strings[91047]="他们还没放弃！坚持住！"
D.Strings[91048]="我的剑斩杀过一整支军队。你又能有多少胜算呢？"
D.Strings[91049]="干得好！我这些守卫都是我亲自训练的……可不好对付啊。我觉得你有资格做我的对手。放马过来吧，出于礼貌，我可以让你先出手。"
D.Strings[91050]="我都让你们先出手了，你们就这点本事吗？"
D.Strings[91051]="一次勇敢的尝试……但这也是徒劳的。"
D.Strings[91052]="废物，简直是浪费时间。"
D.Strings[91053]="这么轻松的击杀又有什么乐趣可言呢？"
D.Strings[91054]="镜像！"
D.Strings[91055]="引爆！"
D.Strings[91056]="动起来吧！"
D.Strings[91057]="你们应该考虑好再挑战我的！"
D.Strings[91058]="真是可惜。我还以为你们有多大本事呢。"
D.Strings[91059]="我什么时候才能遇上一个像样的对手呢……"
D.Strings[91060]="不可能！我……是……最……强的……"
D.Strings[91061]="夫人，我……失败……了……"
D.Strings[91062]="纳迦在折磨那个海巨人。我们该怎么做？"
D.Strings[91063]="魔枢里暴虐的能量似乎会干扰影像水晶。"
D.Strings[91064]="从现在开始，你只能靠自己了。祝你好运。"
D.Strings[91065]="看来，魔枢的迷锁被一个普通的$r破解了。奇迹真是层出不穷啊！"
D.Strings[91066]="如果你是为了弄几件破烂玩意儿才跑来跟我战斗的话，那你恐怕来迟了。"
D.Strings[91067]="复仇军已经把我这把老骨头给折腾散了，你用得上的东西恐怕都被抢走了。"
D.Strings[91068]="如果你想要那些东西，你们这些凡人都这样，那就去对付他们吧。"
D.Strings[91069]="噢，真是……出乎意料。"
D.Strings[91070]="虚灵的虚空魔法严重削弱了我的力量。这种状态下的我对你毫无用处。"
D.Strings[91071]="看来你是圣光的追随者。帮我恢复力量，我就与你并肩战斗。"
D.Strings[91072]="我们得快一点。复仇军随时都可能追上来！"
D.Strings[91073]="你是个出色的治疗者，牧师。我的力量正在恢复。"
D.Strings[91074]="你是来找魔枢宝库的吧？否则谁还会回到这个地方来呢？"
D.Strings[91075]="可惜，要进入宝库……很困难。如果你帮我进入图书馆，我也许能找到进入宝库的方法。决不能让复仇军得到里面的神器！"
D.Strings[91076]="但首先，我得换个更舒服的形态。这些大厅太小了，不符合我的品味。"
D.Strings[91077]="魔枢宝库被削弱了！看那团圣火，宝库已经压制不住圣光之怒了。"
D.Strings[91078]="它是强大而混乱的武器，会在我们接近时突然爆发。做好准备。"
D.Strings[91079]="大火把这里的地面烧得发烫了。但愿你有办法让我们过去……"
D.Strings[91080]="我们到了。现在，让我看看怎么进入宝库……"
D.Strings[91081]="果然如此！魔枢之战中，玛里苟斯撕裂了扭曲虚空，摧毁了宝库的入口。"
D.Strings[91082]="我感觉它的力量正在魔枢中回荡。一定还有其他进入宝库的方法！"
D.Strings[91083]="宝库里的能量正在沸腾。小心！"
D.Strings[91084]="好险啊！如果那件武器的力量再得不到压制，它就会彻底毁掉这个地方！"
D.Strings[91085]="快！我们得前往裂隙。这是唯一的办法！"
D.Strings[91086]="等等……那边不是有座桥的吗？"
D.Strings[91087]="蠢货！就算你们摧毁了湍流之针，也来不及阻止我们了！圣光之怒的力量即将撕开裂口！"
D.Strings[91088]="真棒，又是虚灵……"
D.Strings[91089]="看来它们在将宝库里的能量导入那个裂口。这可不妙。"
D.Strings[91090]="来吧！是时候让这些虚灵看看，我还是能战斗的！"
D.Strings[91091]="你们太迟了，闯入者。现在，什么都阻止不了我了！"
D.Strings[91092]="复仇军必将再次崛起！"
D.Strings[91093]="什么！？虚空不可能失败！不！！"
D.Strings[91094]="哈！全能的虚空不过如此。知道吗，你这盟友还不错，可惜不是巨龙！"
D.Strings[91095]="我可以打开通向宝库的传送门，但我得留在这里维持它。"
D.Strings[91096]="通道打开了。快，小$r！我坚持不了多久！"
D.Strings[91097]="虽然不想承认，但我确实需要一个盟友。你应该能行吧。"
D.Strings[91098]="我准备好获取能量源了。"
D.Strings[91099]="啊？"
D.Strings[91100]="别担心，巨人朋友。有大地之环在呢。"
D.Strings[91101]="我有那样东西。跟我来。"
D.Strings[91102]="再等等。我收集的小玩意儿有点多。"
D.Strings[91103]="嗯……让我看看……埃匹希斯水晶？不，它们完全没用。"
D.Strings[91104]="唔，我肯定把它放在这儿了。"
D.Strings[91105]="魔粉……灵魂碎片……肯定不是……"
D.Strings[91106]="啊哈！找到了……灵魂结晶。这应该能有用！"
D.Strings[91107]="先砸烂你们的船，再打碎你们的骨头！"
D.Strings[91108]="欧洛克……被冲走了。"
D.Strings[91109]="散开！杀光这群恶魔！"
D.Strings[91110]="你能来拿一下吗？这些水晶对非恶魔生物会有不利影响。"
D.Strings[91111]="吱吱！没有什么是神圣的，也不存在纯洁！"
D.Strings[91112]="吱吱……"
D.Strings[91113]="你们比我们落后了几千年！你们怎么可能赢得了？"
D.Strings[91114]="强大的乌索尔，我们的宿敌又回来了！我的同伴来此，请你帮忙取回乌索克之爪。"
D.Strings[91115]="不……不可能！"
D.Strings[91116]="怎么回事……我的法力离我而去了！"
D.Strings[91117]="我的无边法力会让你屈膝投降的！"
D.Strings[91118]="傲慢的家伙，居然敢闯到苏拉玛附近来！"
D.Strings[91119]="你……会死在……魔导师手里……"
D.Strings[91120]="我自由了！我得到了死亡的魔力！"
D.Strings[91121]="$n！议员们，这就是那位恶魔猎手。"
D.Strings[91122]="小心点，$n。你在摆弄连伊利丹都觉得危险的魔法。"
D.Strings[91123]="等等，你是来追他们的吗？是的话，那我正需要帮手……"
D.Strings[91124]="阿莱利，报告情况。找到战刃没有？"
D.Strings[91125]="对……<干扰>凯丽娅……<干扰>破碎海滩……<干扰>遭遇激烈抵抗……"
D.Strings[91126]="该死！敌人来了！"
D.Strings[91127]="下面出什么事了？阿莱利！"
D.Strings[91128]="我们找到了。这次肯定是真的。"
D.Strings[91129]="$n，我有个主意。"
D.Strings[91130]="自由。自由！我自由了！终于摆脱那个该死的牢笼了。"
D.Strings[91131]="拿起你们的刀剑！战争来了。"
D.Strings[91132]="又来了一队援军！守住你们的阵地！"
D.Strings[91133]="一定就是它了，在这儿！"
D.Strings[91134]="力量……抛弃了我。"
D.Strings[91135]="我们愿意为伊利丹而死……凯丽娅也一样。"
D.Strings[91136]="可悲的小东西。这已经是最后一批了吗？"
D.Strings[91137]="遵命，夫人。蔑潮部族会盯着他们，直到您收割他们的灵魂。"
D.Strings[91138]="很好。现在，把这座禅院撕成碎片吧！"
D.Strings[91139]="接受痛苦的试炼。别放过凯丽娅！"
D.Strings[91140]="%s战死，进入了噬魂之喉……"
D.Strings[91141]="你准备好深入这场混乱的中心了吗，$r？"
D.Strings[91142]="这里的腐蚀比我所见过的任何地方都要严重……玛法里奥，坚持住。"
D.Strings[91143]="%s回到了英灵殿……"
D.Strings[91144]="集中火力！干掉他们！"
D.Strings[91145]="哈布隆开始抽取%s的灵魂。"
D.Strings[91146]="我会尽力对付那个节点亲王的，$c。但我太虚弱了，最后还是得靠你来解决这场危机。"
D.Strings[91147]="但愿你准备好了！"
D.Strings[91148]="$n的存在消失了。"
D.Strings[91149]="我是来还人情的，仅此而已。"
D.Strings[91150]="我很受不了雷特森，但我会尽量集中精神，不去理会他的存在的。\n\n我可以开始召唤传送门了吗？"
D.Strings[91151]="我们对你没有恶意，巨人。"
D.Strings[91152]="他们控制我们，杀害我们。"
D.Strings[91153]="萨满，去跟他谈谈。或许我们能得到一个新盟友。"
D.Strings[91154]="我就是虚空！"
D.Strings[91155]="我们当然会帮你的！"
D.Strings[91156]="你们的门派完蛋了，武僧！你们对付不了我们。"
D.Strings[91157]="我们的意志坚不可摧。我们会奋战到底，恶魔。"
D.Strings[91158]="军团永垂不朽……"
D.Strings[91159]="你会死在我的剑下的，$c！"
D.Strings[91160]="我要撕碎你，$c！"
D.Strings[91161]="承受我的烈焰和怒火吧！"
D.Strings[91162]="我们要将你的禅院化为灰烬。"
D.Strings[91163]="你的人民完蛋了。"
D.Strings[91164]="咿……火！"
D.Strings[91165]="我要烧死你！"
D.Strings[91166]="看呐，烧吧，烧吧！"
D.Strings[91167]="灿烂的火焰，如此美丽！"
D.Strings[91168]="烧吧，烧吧，烧吧烧吧烧吧！"
D.Strings[91169]="快，$n。那些邪能散播器已经造成了严重的伤害。"
D.Strings[91170]="我们来挡住他们。快去攻击恶魔，否则就迟了！"
D.Strings[91171]="快，我会跟紧你的！如果你遇到麻烦，美猴王会罩着你的！"
D.Strings[91172]="你走之后，我得给这些实验体准备一个管制区了。"
D.Strings[91173]="干得好，我的朋友！他见过安德莉，还有我们要找的神器。现在，我们得对付这道冰墙了……"
D.Strings[91174]="……这样应该就行了。"
D.Strings[91175]="大宗师，你已经亲眼见证了燃烧军团的破坏力。"
D.Strings[91176]="禅院得救了，但我们依然任重道远。"
D.Strings[91177]="请送我去五晨寺。"
D.Strings[91178]="梦魇已经腐蚀了这些生物，现在让我们来腐蚀你的宠物怎么样？"
D.Strings[91179]="我就是你最可怕的梦魇。"
D.Strings[91180]="踩住萨特的尾巴。"
D.Strings[91181]="打断萨特的手腕。"
D.Strings[91182]="联络泰兰德。"
D.Strings[91183]="种子已经播下了。"
D.Strings[91184]="对，让你体内的怒火膨胀吧！"
D.Strings[91185]="我能感觉到腐蚀在扩散！"
D.Strings[91186]="那家伙坚持不了多久。"
D.Strings[91187]="你会为你的傲慢付出代价的。"
D.Strings[91188]="我一定是在做噩梦。"
D.Strings[91189]="守住阵线！别让他们攻陷禅院！"
D.Strings[91190]="祝踏岚大师正在山脚下等你。"
D.Strings[91191]="别着急，英雄。你的躯体还没准备好。我会再来找你的，但首先，我的灵魂需要一个更合适的容器。"
D.Strings[91192]="你很强。或许我该把你当做我的下一个容器。"
D.Strings[91193]="大宗师！欢迎你，准备扭转乾坤吧！但愿你的碎玉闪电已经蓄势待发了！"
D.Strings[91194]="你变强了，奇拉。"
D.Strings[91195]="确实如此。你下次找我搭讪的时候，最好记住这一点……"
D.Strings[91196]="就连死亡之翼都能预见到，一旦让黑暗之王脱困，他会释放出怎样的邪恶。$b$b今天对我们所有人来说都是糟糕的一天。"
D.Strings[91197]="送我去雷霆图腾。"
D.Strings[91198]="最后的试炼可不简单，德鲁伊。你准备好了再来找我吧。"
D.Strings[91199]="泰兰德·语风！我已经期盼这次相遇很多年了。"
D.Strings[91200]="只要一剂瘟疫病原体，就能让你在我的船上规规矩矩的！"
D.Strings[91201]="你亲爱的丈夫就快融入我的梦魇了。他可是特别嘉宾。"
D.Strings[91202]="我见过这位英雄的能力。我愿意帮忙！"
D.Strings[91203]="告诉我，有人愿意与你并肩作战吗，$c？"
D.Strings[91204]="很好，$n！你确实有着熊的精神！"
D.Strings[91205]="这边。其他幸存者就在上面。"
D.Strings[91206]="大门的封印即将崩溃！如果让燃烧军团攻破大门，一切就都完了！"
D.Strings[91207]="必须阻止恶魔首领凯丽翠丝。"
D.Strings[91208]="我们的朋友不见了！我们不能走！但这些坏蛋确实吓人！"
D.Strings[91209]="我会跟你回迷踪岛。在那里，我们要制定一个计划。"
D.Strings[91210]="灵魂行者！这里出什么事了？"
D.Strings[91211]="黑暗之王。他来过这里……我很抱歉，酋长。黑暗之王把你父亲的遗体带到山顶去了。"
D.Strings[91212]="我抓住你了！"
D.Strings[91213]="蓟叶恶霸用力掐着被俘的月翼精灵龙。"
D.Strings[91214]="只要我还活着，你就休想。"
D.Strings[91215]="科达，吸引她注意。莱妮丝，为我们疗伤。勇士——跟我来！"
D.Strings[91216]="你真的迷失了吗，伊瑟拉？在我们做了那么多之后？"
D.Strings[91217]="艾露恩之光啊，我们要终止这场疯狂！"
D.Strings[91218]="我会结束你的痛苦，沉睡者。我们会为你复仇的，我保证。"
D.Strings[91219]="嘘，嘘……都结束了，伊瑟拉。"
D.Strings[91220]="睡吧，伊瑟拉。长眠吧，你不会再做梦了。"
D.Strings[91221]="你们的末日降临了，凡人。梦境已经破灭了！"
D.Strings[91222]="我的双眼终于睁开了，女祭司。我看到了永恒的黑夜。"
D.Strings[91223]="梦魇将吞噬一切！"
D.Strings[91224]="梦魇之王，他——"
D.Strings[91225]="……黑暗……"
D.Strings[91226]="和大多数仪式一样，它也需要三个术士一起来完成。\n\n你准备好了吗？"
D.Strings[91227]="来吧，勇士。让我们教教这些入侵者什么叫力量。"
D.Strings[91228]="我分不清他的声音是从哪儿传来的！快，去搜查西边的建筑。我去东边找他！"
D.Strings[91229]="你在哪儿，玛法里奥？回答我！"
D.Strings[91230]="勇士，过来！我有发现了！"
D.Strings[91231]="我随时听候你的召唤，大宗师。"
D.Strings[91232]="这些蹄印往左边这条路去了。来，快！"
D.Strings[91233]="玛法里奥？！回答我！"
D.Strings[91234]="不，我们一起走！"
D.Strings[91235]="大师选对了人，大家都会看到！美猴王无比强大！"
D.Strings[91236]="以艾露恩之名，我要将你逐出这片土地！"
D.Strings[91237]="你来对付那个臭嘴的萨特。我去找我丈夫！"
D.Strings[91238]="你休想抓住我！"
D.Strings[91239]="回去，泰兰德！"
D.Strings[91240]="当然。我可不像你，我是不会在同伴最需要我的时候抛弃他们的。"
D.Strings[91241]="你很大胆，居然敢靠近我，外来者。"
D.Strings[91242]="你是希尔格林吗？"
D.Strings[91243]="是塔莉萨派我来的。"
D.Strings[91244]="你愿意协助我们吗，奇拉？"
D.Strings[91245]="你成功了！可你想把这武器带出去的话，就得先控制住它。"
D.Strings[91246]="祝你好运，$c。"
D.Strings[91247]="我的故事已经传到城市外头去了吗，还是我们有共同的熟人……"
D.Strings[91248]="真了不起，$n！我从没见过能控制住圣光之怒的牧师。"
D.Strings[91249]="虚灵被击溃了，你也得到了想要的武器。你在这里的任务已经完成了，但我的才刚刚开始。"
D.Strings[91250]="有点颠簸，对吗？哪怕是骑着休伊这样出色的角鹰兽，穿过这些云层也不是一件容易的事。"
D.Strings[91251]="谢谢你放我出来。这是我……有生以来得到的最好的一份礼物。"
D.Strings[91252]="我要用这段时间保护好魔枢。决不让它再落入恶徒手中！"
D.Strings[91253]="这座传送门可以把你送回去。代我向卡雷苟斯问好。"
D.Strings[91254]="首先，我要将你介绍给普斯塔佳。"
D.Strings[91255]="看来普斯特也想赶走燃烧军团，所以才会不分昼夜地寻找这座陵墓！"
D.Strings[91256]="呃……我得提醒一句。她可不是那种可爱型的。"
D.Strings[91257]="普斯塔佳！按照约定，我带了一个朋友。"
D.Strings[91258]="我才不在乎什么友谊，软泥人。只要这家伙能帮我们进入墓穴，我就接受他们。"
D.Strings[91259]="唔……看来有几个蠢货盗墓时，惊扰了里面的幽灵。"
D.Strings[91260]="祝你好运。我等着你的信号。"
D.Strings[91261]="你的任务很简单！在我破除封印墓穴的结界时赶走那些幽灵。"
D.Strings[91262]="话说，你听到什么声音没有？"
D.Strings[91263]="亵渎者……不……它不是你的……"
D.Strings[91264]="我从来就没搞懂过，幽灵为什么会对他们的战利品这么执着……"
D.Strings[91265]="小偷！觊觎者！它是属于我的！"
D.Strings[91266]="别吵！我们找这把枪是为了做好事，幽灵！"
D.Strings[91267]="这些怪物只是障眼法！到墓穴里去！"
D.Strings[91268]="前门已经打开了。这可真顺手！"
D.Strings[91269]="哇！溜过去！溜过去！"
D.Strings[91270]="达格利尔肯定完蛋了。我听到有流言说他是个叛徒，和堕夜精灵有勾结。"
D.Strings[91271]="哇！地雷！"
D.Strings[91272]="他和他的“盟友”竟敢密谋毒害艾利桑德阁下！这就是冒犯月生家族的下场！"
D.Strings[91273]="你失败了，和我一样。但我们可以吸取教训。我们再来一次吧。"
D.Strings[91274]="干得好！宝库里的能量似乎稳定了。快，在传送门关闭前回来，别被关在里面了！"
D.Strings[91275]="这巨人见过莎拉达尔，潮汐权杖！我们就快到了。留他一命，他能保护我们。"
D.Strings[91276]="后退！这些动物被别人操纵了。"
D.Strings[91277]="艾萨拉的爪牙在这里做什么？"
D.Strings[91278]="既然你要找死，那我就满足你！"
D.Strings[91279]="泰兰德，不！这是陷阱！"
D.Strings[91280]="塔莉萨还活着？来，我们私下谈谈。"
D.Strings[91281]="还有亲爱的伊瑟拉！你知道她已经变心了吗？"
D.Strings[91282]="别啰嗦了。快走！"
D.Strings[91283]="月井之水很重要。离开梦境林地时，请务必带上它！我在灰熊丘陵等你。"
D.Strings[91284]="你在破碎群岛干什么，布莱恩？"
D.Strings[91285]="我还能干什么——发掘一切有关泰坦的知识咯！我们是从哪儿来的，我们为什么会在这儿。这片土地能够解答我们的疑问，我有这个预感。\n\n但在破碎群岛，并没有什么城市级别的泰坦建筑。没有奥杜尔，奥达曼……什么奥字头的东西都没有！所以我准备研究恶魔的历史。我想我或许能发现一些有关堕落泰坦萨格拉斯的知识。"
D.Strings[91286]="到目前为止，你有什么发现吗？"
D.Strings[91287]="噢，源自上古之战的各种圣物。这片土地上爆发过许多大战。不然你以为这些邪能页岩都是怎么来的？但没有和泰坦有关的东西。至少目前还没有……"
D.Strings[91288]="你在破碎群岛干什么，高阶考察者？"
D.Strings[91289]="<高阶考察者居高临下地看了你一眼。>\n\n难道你没听说过神圣遗物学会吗，$r？\n\n当然，我们追求的是力量。这片土地的地下埋藏着大量无价之宝。上层精灵遗失的奥术技艺比你我所了解的更多。我想找到他们失落的遗物，并让它们的力量为我和我的人民所用。\n\n好了，别再问东问西的了。"
D.Strings[91290]="你就住在雷霆图腾吗，莱莎？"
D.Strings[91291]="不，不，我来自雷霆崖。我是个冒险者，和你一样。这些至高岭牛头人对我来说同样很陌生。\n\n但我是胡恩·高岭的热心研究者，他是这片土地上有史以来最伟大的牛头人之一。这个“之一”或许都能去掉。至高岭，将是我了解他的最佳地点。"
D.Strings[91292]="%s召唤附近的生物前来助战。"
D.Strings[91293]="她会帮我征服瓦尔莎拉，就从你的宝贝月神殿开始。"
D.Strings[91294]="你已经掉入了我的陷阱！现在你去死吧！"
D.Strings[91295]="你准备好了就跟我说吧。"
D.Strings[91296]="每当我举棋不定时，就会走进他的兽穴，看着他熟睡的样子。"
D.Strings[91297]="沉睡中的他也能让我安心。我会将恐惧留下，然后回去继续领导我的人民。"
D.Strings[91298]="当玛法里奥归来时，我们紧密合作，仿佛他从未离开一样。你像这样爱过一个人吗？"
D.Strings[91299]="萨维斯的确掐住了我的死穴。我得抛弃爱人，与我所认识的，最美丽的生物战斗。"
D.Strings[91300]="<呻吟着>……"
D.Strings[91301]="辛菲儿·疫誓语无伦次地咕哝着，一副痛苦的样子。"
D.Strings[91302]="燃——烧——"
D.Strings[91303]="潮汐权杖……在这儿。我找到它了。"
D.Strings[91304]="他们在用它逼疯这附近的动物。"
D.Strings[91305]="莎拉达尔在吉斯林手里。她想把我当成诱饵。"
D.Strings[91306]="我们得回去。这是个陷阱。"
D.Strings[91307]="你低估了我带来的这位萨满。"
D.Strings[91308]="如果权杖真在这里，这或许是我们得到它、并用它对付军团的唯一机会！"
D.Strings[91309]="我不朽的灵魂……属于凯丽娅……"
D.Strings[91310]="你太迟了！他来了……"
D.Strings[91311]="不要破坏它的灵魂。凯丽娅用得上它。"
D.Strings[91312]="那些亡灵入侵者跟我们大战了一场，但我和玛尔是不会让他们抢走农场的。"
D.Strings[91313]="你就是“疯子”欧尼吗？"
D.Strings[91314]="嘘！小声点。\n\n我已经好几年没用那个名字了。我早就放弃炼金术了，在农场里过着平静的生活。\n\n你找“疯子”欧尼有什么事吗？"
D.Strings[91315]="是雷特森派我来的。我们需要人帮忙治愈一种厄运诅咒。"
D.Strings[91316]="欧内斯特·卡莱尔叹了口气。"
D.Strings[91317]="我欠你一条命，大师。"
D.Strings[91318]="小心点。这些维库人简直战无不胜。"
D.Strings[91319]="我可以自己返回大本营的。谢谢你。"
D.Strings[91320]="风暴蜜酒将这些维库人变成了狂暴而势不可挡的战争机器。小心点。"
D.Strings[91321]="使用风暴蜜酒吧，大师。只有这样，你才有可能与他们抗衡。"
D.Strings[91322]="看来我们进来了！来吧，西奥多！"
D.Strings[91323]="这个地方让我寒毛直竖。艾露恩，请赐予我力量。"
D.Strings[91324]="有了乌索尔的祝福，我们就能去翡翠梦境找乌索克之爪了！来吧，$n，别再浪费时间了！"
D.Strings[91325]="勇气……力量……纪律……$b$b拥有了这些特质，就说明你心中有着熊的精神。"
D.Strings[91326]="这就是我们带你来这里的原因。干掉他们！"
D.Strings[91327]="希罗！嘿，你还好吗，伙计？"
D.Strings[91328]="啊哦，看来我们有伴儿了。"
D.Strings[91329]="快，拿上钥匙，出来！"
D.Strings[91330]="嘿，伙计，这锁卡住了，而且我头很晕！你行你上啊，小矮子！"
D.Strings[91331]="快点儿，希罗！\n"
D.Strings[91332]="敌人又来了！"
D.Strings[91333]="愿元素指引我们的道路。"
D.Strings[91334]="嘿，看，那扇门开了！"
D.Strings[91335]="愿大地母亲护佑着我们。"
D.Strings[91336]="$n！我欠你一份人情，可我必须去看看其他人了。"
D.Strings[91337]="安古斯！赛莱拉！见到你们真好。你们……呃……有喝的吗？"
D.Strings[91338]="他们攻破了神殿！保护战刃！"
D.Strings[91339]="你不是我们的人。你来巢穴做什么？"
D.Strings[91340]="阿莱利带人去追查战刃的线索了。我们可能终于找到它们了。"
D.Strings[91341]="我们总算快要找到战刃了。阿莱利已经带人去追查它们的下落了。"
D.Strings[91342]="援军！快！"
D.Strings[91343]="我和鲁尔以前和你一样，也是冒险者。我们从这里一路杀到潘达利亚，甚至到过外域！我们杀过人，也救过人，什么都经历过。\n\n但现在，我们只想在一个安静地方跟我们的两条小狗好好过日子，你明白吗？"
D.Strings[91344]="来吧！面对你们的末日吧！"
D.Strings[91345]="死亡是种恩赐，凡人！"
D.Strings[91346]="你的生命一文不值。"
D.Strings[91347]="拥抱痛苦吧！"
D.Strings[91348]="你们都得死！"
D.Strings[91349]="我要打垮你们的勇气！"
D.Strings[91350]="看着希望破灭吧！"
D.Strings[91351]="艾泽拉斯……必将……燃烧……"
D.Strings[91352]="烧光，统统烧光，哈哈哈！"
D.Strings[91353]="无论情况变得多么糟糕，都别忘了幸福列车上有一节车厢是为你敞开的。呜呜！"
D.Strings[91354]="很好。现在，来帮我们！"
D.Strings[91355]="蛮兵来了！"
D.Strings[91356]="不……不！囚犯逃跑了，夫人一定会不高兴的！"
D.Strings[91357]="我要亲自解决你们！"
D.Strings[91358]="该死的双胞胎……她们会付出代价的！"
D.Strings[91359]="我们不可能一直挡住他们！赶快拔腿逃跑吧！"
D.Strings[91360]="战刃将吞噬你们！"
D.Strings[91361]="卑微的家伙……你们又一次破坏了我的计划。"
D.Strings[91362]="残寺派的武僧们，我保证……下次，我会让你们为自己的傲慢付出代价的！"
D.Strings[91363]="你太迟了。这个世界的腐化是无法阻挡的。让我再来助它一臂之力……就从你的宝贝同伴开始！"
D.Strings[91364]="这点损失无关紧要！梦魇会吞噬一切！后会有期，闯入者……"
D.Strings[91365]="你好！为了让我们的朋友保持状态，我们随便打一场吧？"
D.Strings[91366]="很有潜力！你和你的朋友们的确技艺高超。"
D.Strings[91367]="挥动"
D.Strings[91368]="体内黑暗的滋长令%s痛苦万分。"
D.Strings[91369]="我的斥候报告说，他们在火山附近的空域被大批巨人和疫病蝙蝠击溃了。去看看他们是从哪儿冒出来的。"
D.Strings[91370]="你肃清了那里的山区和天空。天角部族欠你一份人情。"
D.Strings[91371]="达古尔在地窟深处囚禁了一头巨型母蜥蜴。如果不快点干掉她，达古尔就会拥有一支蜥蜴大军！"
D.Strings[91372]="今天，你帮了高岭诸族一个大忙。"
D.Strings[91373]="达古尔连野生动物也不放过，被他的晶化魔法扭曲的乌龟污染了河流。快去找到这些强大怪物的源头吧。"
D.Strings[91374]="多亏了你，河水又能饮用了。"
D.Strings[91375]="达古尔的爪牙抓走了我的族人。不肯屈服的人都死在了他的奴隶手中。如果可以的话，请去帮帮他们。"
D.Strings[91376]="黯石部族感谢你。"
D.Strings[91377]="传说，那里有巨龙奈萨里奥留下的失传圣物。如果你见到那些圣物，请带来给我，我会好好保管它们的。"
D.Strings[91378]="谢谢你，英雄。如果落入恶徒之手，这些圣物足以撕裂我们的世界。"
D.Strings[91379]="让我们并肩战斗吧，$n。"
D.Strings[91380]="你把他们挑出来，我来干掉他们。"
D.Strings[91381]="快干掉他们！又有人过来了！"
D.Strings[91382]="我的魔法……它们什么都能抵抗！求求你，救救我！"
D.Strings[91383]="要不是我一时大意，我……嘿，你！来帮我一把！"
D.Strings[91384]="我的魔法为你效劳，$n。"
D.Strings[91385]="让我们一起解决这场危机。"
D.Strings[91386]="我感谢你的帮助，$n，但我必须立刻去警告我的同胞了！"
D.Strings[91387]="其他人。还有其他人也被抓了……我必须找到他们。"
D.Strings[91388]="嘿！我在这儿！见到你我真是太高兴了！"
D.Strings[91389]="我们动手吧，好吗？这些恶魔可不会自己死掉！"
D.Strings[91390]="让开！救援小队来啦！"
D.Strings[91391]="我这把老骨头得去补充一下法力了！留点给我，行吗？"
D.Strings[91392]="你先走，我很快就会赶上你的！"
D.Strings[91393]="我应该留在阴影里。你能助我一臂之力吗？"
D.Strings[91394]="别让这些东西靠近我！"
D.Strings[91395]="我们一定能打他们个措手不及。"
D.Strings[91396]="我的匕首已经蓄势待发了，$n。把目标指给我看吧。"
D.Strings[91397]="不要远离暗影。这场战斗还没有结束。"
D.Strings[91398]="我必须去警告其他人。"
D.Strings[91399]="虽然很不情愿，但我真的需要你的帮助！"
D.Strings[91400]="这边！拜托——我的魔法——都被它们吞噬了！"
D.Strings[91401]="他们抓了其他人！求求你！救救我们！"
D.Strings[91402]="我挡不住他们多久！拜托！救救我！"
D.Strings[91403]="你好像需要帮手啊，$n。"
D.Strings[91404]="我们该返回战场了。"
D.Strings[91405]="谢谢，$n。其他人也需要我的帮助，但请收下这个。"
D.Strings[91406]="必须保持移动！燃烧军团无处不在。"
D.Strings[91407]="那些怪物……我不能……"
D.Strings[91408]="这边！我……"
D.Strings[91409]="这些臭嘴……帮我干掉他们！"
D.Strings[91410]="你们休想摧毁我们的土地！"
D.Strings[91411]="有我帮你，这些恶魔毫无机会。"
D.Strings[91412]="我们得击退他们！"
D.Strings[91413]="我们的人民需要帮助！"
D.Strings[91414]="你的灵魂将属于我们……"
D.Strings[91415]="在灵魂的回忆中穿行有时是很危险的，但这是我们灵魂行者必须承担的职责。"
D.Strings[91416]="我准备好进入达古尔的回忆了。"
D.Strings[91417]="这颗宝珠中涌动的邪能魔力简直是……诱人。"
D.Strings[91418]="作为一个术士，这点小小的邪能魔力对你毫无威胁。快吸收掉这个邪能宝珠的力量吧。"
D.Strings[91419]="这颗宝珠中涌动的邪能魔力简直是……诱人。\n\n这股深厚的邪能魔力已经超出了你的能力范畴。"
D.Strings[91420]="这瓶药水不但闪闪发光，而且有着丰富的气泡。"
D.Strings[91421]="作为一个潜行者，你一定很精通毒药。往这个瓶子里加一些致命的毒药对你来说应该很容易。"
D.Strings[91422]="这个结界能够封印强大的邪神。只要我还有一口气在，黑暗之王就休想得到自由！"
D.Strings[91423]="你这条命就快到头了。黑暗之王已经预见到了你的死期。"
D.Strings[91424]="这瓶药水不但闪闪发光，而且有着丰富的气泡。\n\n不幸的是，你没有合适的材料来制造出真正的剧毒。"
D.Strings[91425]="你来得正是时候，达古尔。到了我这把年纪，每一分钟都是宝贵的。"
D.Strings[91426]="很好，让我们完成这笔交易吧，这样你就能返回你的山洞，我也能喝一杯热酒了。"
D.Strings[91427]="稍安勿躁，蠢牛。我还有事情要处理。"
D.Strings[91428]="那个林精在捉弄那头月翼精灵龙！你能去阻止它吗？"
D.Strings[91429]="谢谢你。我从不支持任何人捉弄无辜的动物。"
D.Strings[91430]="奥术能量在导管中汩汩流淌。它似乎和构造体卫兵有着某种关联。"
D.Strings[91431]="那东西是从腐蚀中爬出来的！我们必须在它变得过于强大之前将它逐出我们的世界。"
D.Strings[91432]="每个地精都知道，加点炸药总能解决问题！"
D.Strings[91433]="奥术能量在导管中汩汩流淌。它似乎和构造体卫兵有着某种联系。\n\n不幸的是，你完全搞不懂这个精密又复杂的机械构造体。"
D.Strings[91434]="梦魇生物变得更加扭曲了！让我们向艾露恩祈祷吧，但愿这个恶魔不会再来干扰我们了。"
D.Strings[91435]="哟，就是它！感觉好点没有？"
D.Strings[91436]="如果效果减弱了，那就去寻找更多的风暴蜜酒。维库人最喜欢喝它了！"
D.Strings[91437]="换了我也不可能做得更好了！"
D.Strings[91438]="看来你的故事都是真的。"
D.Strings[91439]="唔，还不错，还不错。"
D.Strings[91440]="嘿！我差点就干掉他了！"
D.Strings[91441]="这个鱼人部族已经被吉斯林奴役了。"
D.Strings[91442]="恶魔猎手的训练让你对此早有准备。快来攫取这个邪能宝珠里的力量吧。"
D.Strings[91443]="呸！杀得好！"
D.Strings[91444]="着火了！你必须在整座圣林起火前扑灭它！"
D.Strings[91445]="你果然名不虚传。"
D.Strings[91446]="别杀它们！净化它们，萨满！尽快净化它们！"
D.Strings[91447]="我们很走运，幸好你来得快。谢谢你。"
D.Strings[91448]="我准备好进入奥妮娅·天角的回忆了。"
D.Strings[91449]="我准备好进入武士奥罗的回忆了。"
D.Strings[91450]="炼金学方面的经验告诉你，绝对不要把这种灰色液体和任何紫色液体一起饮用。如果有人喝了这瓶药水，那下场一定很惨……"
D.Strings[91451]="让我们安息吧！"
D.Strings[91452]="我看见它了！黑暗之王来了！"
D.Strings[91453]="侏儒科技告诉过你，任何超载的导管都是危险的。让我们看看这玩意儿面对一万伏的高压时会有什么变化吧！"
D.Strings[91454]="工程学向来都是你的强项。你闭着眼睛都能关闭这个导管。"
D.Strings[91455]="滚开，幽灵！告诉黑暗之王，这里不欢迎他！"
D.Strings[91456]="好的！我做好揍人的准备了！你不会后悔的，大宗师！"
D.Strings[91457]="耶！！！我们在你身边。一切都会好起来的。"
D.Strings[91458]="很为难吧，高阶女祭司！"
D.Strings[91459]="想跪在你的爱人身边看他咽气吗？还是看着你的神殿化为火海吧！"
D.Strings[91460]="<疯狂的大笑>"
D.Strings[91461]="黑暗崛起了。"
D.Strings[91462]="黑暗之王将穿透迷障。"
D.Strings[91463]="主人必将归来。"
D.Strings[91464]="拥抱暗影吧。"
D.Strings[91465]="他会回来的。"
D.Strings[91466]="黑暗必将战胜光明。"
D.Strings[91467]="接受黑暗之王吧。"
D.Strings[91468]="他是暗影的主宰。"
D.Strings[91469]="俘虏都被带去勇者之门了。那里挤满了强大的维库人和恶魔。记住我的话，那里的情况不太对头。 "
D.Strings[91470]="<赛莱拉等待着你的命令。>"
D.Strings[91471]="我的目标是尝遍这片土地上的美酒。只要有酒有朋友，你就没什么可担忧的。"
D.Strings[91472]="<伊瑟拉发出了巨龙的咆哮>"
D.Strings[91473]="守夜的哨兵有什么要报告的吗？"
D.Strings[91474]="什么？我没有……等等，没错，我也听到了！快去雷霆图腾报信，武士。我去看看发生了什么事。"
D.Strings[91475]="这是什么类型的卓格巴尔？我从没见过他们这样的！"
D.Strings[91476]="是的！我刚刚听到溪流对岸传来了叫喊声！"
D.Strings[91477]="亲眼看到这对战刃的感觉更加震撼。"
D.Strings[91478]="邪能之槌号终于归我们了。见证奥达奇战刃的力量吧！"
D.Strings[91479]="准备好见证奥达奇战刃的力量。邪能之槌号是属于我们的！"
D.Strings[91480]="如有必要，我能震碎整座峡谷！"
D.Strings[91481]="塞拉！塔拉尔！他们来了。别让我失望！"
D.Strings[91482]="你来迟了，孩子。你父亲的尸体已经成为了我的躯壳！"
D.Strings[91483]="你看到那些尸体了吗？他们的灵魂被抽出来了！"
D.Strings[91484]="我想我们可以用一些……小手段过去。"
D.Strings[91485]="这看来像是一堆陈旧的备用零件。这些原本由魔力驱动的东西显然已经耗尽了能量。"
D.Strings[91486]="所有猎人都懂得使用陷阱。这堆垃圾或许可以再利用一下，做成一个陷阱……"
D.Strings[91487]="快，英雄！我可以打开通往灵魂世界的传送门。你必须在黑暗之王占据另一个躯壳前摧毁他。"
D.Strings[91488]="这看来像是一堆陈旧的备用零件。这些原本由魔力驱动的东西显然已经耗尽了能量。\n\n这堆垃圾似乎早就被遗忘了。"
D.Strings[91489]="|TInterface\\Icons\\spell_frost_ring of frost:20|t%s开始施放|cFFFF0000|Hspell:206949|h[严寒新星]|h|r！"
D.Strings[91490]="|TInterface\\Icons\\ability_felarakkoa_feldetonation_green:20|t%s开始施放|cFFFF0000|Hspell:206517|h[邪能新星]|h|r！"
D.Strings[91491]="|TInterface\\Icons\\spell_priest_shadoworbs:20|t%s开始施放|cFFFF0000|Hspell:207439|h[虚空新星]|h|r！"
D.Strings[91492]="|TInterface\\Icons\\Ability_Druid_Starfall:20|t%s开始施放|cFFFF0000|Hspell:205408|h[强力连结]|h|r！"
D.Strings[91493]="再加把劲儿，塔拉尔。快！"
D.Strings[91494]="我？！如果你能集中精神的话，我们早就完事了！"
D.Strings[91495]="你总算说了一句人话！"
D.Strings[91496]="凯丽娅必须完成任务。你休想插手！"
D.Strings[91497]="呃！我被击中了！"
D.Strings[91498]="你……继续前进。这对战刃……值得我们牺牲一切！"
D.Strings[91499]="我来守住出路。凯丽娅交给你了。"
D.Strings[91500]="等你找齐原料之后，我就到你的职业大厅来找你。"
D.Strings[91501]="耶！我准备好了！"
D.Strings[91502]="使用你的|TInterface\\Icons\\ability_demonhunter_spectralsight.blp:20|t |cFFFF0000|Hspell:188501|h[幽灵视觉]|h|r找到凯丽娅的踪迹！"
D.Strings[91503]="我在老家听安古斯说过它。它能让你的力量增长一百万倍！"
D.Strings[91504]="耶！又干掉一个！"
D.Strings[91505]="嗷，冒险已经结束了吗？好吧……"
D.Strings[91506]="你真是个麻利的小家伙。跟紧我，你还有很长的路要走呢！"
D.Strings[91507]="怎么样了？找到多少原料了？"
D.Strings[91508]="每天都有应征者赶来，想要跟随大师学习。"
D.Strings[91509]="我对付不了这么多地狱火！"
D.Strings[91510]="嘿，大师，很高兴再次见到你！我们听说你需要人帮忙搜集风暴蜜酒的原料。"
D.Strings[91511]="我很乐意帮助大宗师，只要在酒酿出来之后让我尝一口就行了。"
D.Strings[91512]="我们听说，燃烧军团在萨格拉斯之墓附近的活动越来越频繁了。"
D.Strings[91513]="那里集结了大量燃烧军团的部队，可能会爆发大战。"
D.Strings[91514]="无论哪个战场有需要，我们都义不容辞。可如果有了类似风暴蜜酒这样的东西，我们的损失一定会大大减少。"
D.Strings[91515]="我已经等不及想要尝尝酿好的蜜酒了。"
D.Strings[91516]="这样应该就行了！我们该回去汇报了。祝你好运，$n。"
D.Strings[91517]="放开我父亲的遗体，你这个怪物！"
D.Strings[91518]="父亲！不要放弃！"
D.Strings[91519]="噢，乌兰的灵魂在哭泣！他知道自己将成为杀害你的凶手！"
D.Strings[91520]="真是美味……这个倒霉的酋长将死在她亲爱的父亲手里！"
D.Strings[91521]="反抗他，父亲！别让他控制你！"
D.Strings[91522]="你没能拯救你父亲的生命。现在，你又辜负了他的灵魂！真是个让人失望的女儿！"
D.Strings[91523]="你们那些可笑的武器根本不是我的对手。"
D.Strings[91524]="真有意思。你还觉得你能赢吗？"
D.Strings[91525]="不！你们的灵魂是属于我的……"
D.Strings[91526]="艾吉拉？我亲爱的土地？能听到你的声音我真是太高兴了。"
D.Strings[91527]="欢迎来到我的世界！"
D.Strings[91528]="师傅……我太差劲了。要是我能再多跟你学习一段时间就好了。但我已经为你报仇了。莫尔金死了，我们夺回了你的风暴蜜酒配方。"
D.Strings[91529]="我亲爱的艾吉拉，你的技艺已经青出于蓝了。从今天起，你就不再是我的学徒了。继承我的意志，以酿酒大师之名继续骄傲前行吧。"
D.Strings[91530]="谢谢你，师傅。"
D.Strings[91531]="格雷格！卖力点！真的有人上当……我是说来参赛了！"
D.Strings[91532]="我是花钱雇你来跳舞的，格雷格，可不是让你来混日子的！给我跳起来！"
D.Strings[91533]="就是这样，格雷格！大场面终于来了！全艾泽拉斯的人都来参加我们的活动了！"
D.Strings[91534]="格雷格，你被解雇了。"
D.Strings[91535]="酿酒"
D.Strings[91536]="这位就是刚刚完成了环球宠物对战之旅返回达拉然的……蒂梵妮·尼尔森！！快来挑战这位真正的宠物对战达人吧，只有一天，机不可失！"
D.Strings[91537]="你们相信奇迹吗？我们的挑战者击败了蒂梵妮·尼尔森！快睁大眼睛看清楚这匹超级大黑马吧！"
D.Strings[91538]="那个燃烧军团的女巫死了。大宗师，我想我们应该庆祝一下！"
D.Strings[91539]="炎魔之王？你不过是一堆石头！"
D.Strings[91540]="小心点，萨满，玩火者必自焚……"
D.Strings[91541]="我或许低估了你的力量……"
D.Strings[91542]="今天，我们的竞技场迎来了加尔维斯顿先生！虽然他有点疯，可他买了入场券……所以就让他上吧！快来挑战这个本地的疯子吧！"
D.Strings[91543]="女士们先声明，你们刚刚见证了一场史诗般的胜利。这个家伙击败了一个绑在鸟身上的玩具。老实说，这没什么了不起的……但胜利就是胜利！"
D.Strings[91544]="仪式快完成了。阻止他们，杂种！"
D.Strings[91545]="而在这个角落，则是博迪·日轨……就是这个光膀子的家伙！他为什么要赤膊上阵呢？是因为上衣洗了没干？还是输了赌注？天知道！"
D.Strings[91546]="我要攫取这可悲世界的所有灵魂！"
D.Strings[91547]="精彩的比赛！博迪虽然不擅长宠物对战，但胜在够帅！"
D.Strings[91548]="军团只是个开始。我的剑将召唤虚空的强大力量！"
D.Strings[91549]="这个入侵者看起来很可口！我有好几百年没吃过凡人了！真怀念那种味道……"
D.Strings[91550]="我有点不舒服……"
D.Strings[91551]="呃，怎么回事？"
D.Strings[91552]="这果子太可怕了……"
D.Strings[91553]="呕。我要去看医生！"
D.Strings[91554]="外面似乎已经变成战场了。干得好！"
D.Strings[91555]="欢迎落入我的罗网，美味的凡人！你一定得留下来！"
D.Strings[91556]="我要撕裂你的血肉，吃掉你的内脏！"
D.Strings[91557]="孩子们，为我复仇！为我……"
D.Strings[91558]="我要集中精神理解这个幻象。\n\n我们有过许多分歧，但此事事关重大。我能相信你吗？"
D.Strings[91559]="我以荣誉起誓，你一定会安然无恙，女祭司。"
D.Strings[91560]="但愿我们不算太迟。"
D.Strings[91561]="回避难所来见我吧，我们得继续研究。动作快点！"
D.Strings[91562]="别让任何人干扰我冥想。"
D.Strings[91563]="跟紧我。不要在梦魇中迷失。"
D.Strings[91564]="有岔路。等等，那是什么？"
D.Strings[91565]="这里的腐蚀很严重。桥那边是什么东西？跟紧我。"
D.Strings[91566]="没有时间悲痛了。埃洛瑟尔已经没救了。跟我来，别耽误时间。"
D.Strings[91567]="我得承认，我原本对让你这样的人与我同行是心存疑虑的。但你战斗时非常英勇。让我们一起共度难关吧。\n\n你准备好深入这场混乱的中心了吗，$r？"
D.Strings[91568]="快回来，部落的战士！我有发现了！"
D.Strings[91569]="看来这只蛋里装着一只想要焚毁世界的古老魔法生物。幸好我们的挑战者胜利了！"
D.Strings[91570]="今天的宠物对战特别精彩，那就是……嘿，谁把那个蛋放进竞技场里去了？呃……快来挑战这个巨蛋吧！战胜一只手无寸铁的巨蛋，时间有限！"
D.Strings[91571]="这个躯壳属于我了。"
D.Strings[91572]="现身吧，灰石之王！"
D.Strings[91573]="我不在的这段时间里，你的蠢牛们变强了嘛，高岭。不过还不够强。"
D.Strings[91574]="几个世纪前，我的人民阻止过你一次，黑暗之王。我们会再次击败你的。"
D.Strings[91575]="你的祖先曾经也是这么自负。这会毁了你的。"
D.Strings[91576]="不过……你的血脉中藏有强大的力量，孩子。我很乐意得到它。"
D.Strings[91577]="我绝不会向你屈服！"
D.Strings[91578]="迟早会的……不过你还没资格承载我的力量。不……我指的是……一个更加强大的酋长！"
D.Strings[91579]="他想干什……噢，不……我父亲！他想占据我父亲的遗体！"
D.Strings[91580]="由于一些技术问题，锦标赛取消！嗷！那只老鼠刚刚咬了我一口！嗷！呃……请让开！不过是小小的鼠患而已，我们很快就能解决的。"
D.Strings[91581]="锦标赛得救了！我都不知道那些老鼠是怎么从笼子里逃出来的。呃……我提到笼子了吗？什么笼子？我才没有参与什么魔化超级老鼠走私集团之类的呢！"
D.Strings[91582]="小心！末日守卫向你那边去了！"
D.Strings[91583]="打得好！但燃烧军团的援军正在步步逼近。我们得离开这里。"
D.Strings[91584]="你不怕死的话，就来我的王座见我吧。你或许还有点用处……"
D.Strings[91585]="斯莫德隆……你即将臣服于真正的炎魔之王！"
D.Strings[91586]="愚蠢的凡人！这个地方很快就会属于主人了！"
D.Strings[91587]="打倒那个污染者！"
D.Strings[91588]="让他们尝尝自然的怒火！"
D.Strings[91589]="乌索克大人！快，$n，去他身边！"
D.Strings[91590]="我将要举行的仪式非常复杂，需要一段时间才能完成，但这是解除屏障的唯一方法。"
D.Strings[91591]="这是一盘点心。这个盘子似乎被灌注了某种奇怪的魔法。"
D.Strings[91592]="这是一盘点心。这个盘子似乎被灌注了某种奇怪的魔法。\n\n随便食用灌注了魔力的食物可能会损伤你的肠胃……你不知道这些食物是否安全。"
D.Strings[91593]="受过多年厨艺训练的你精擅烹饪。这些东西很安全，可以食用。"
D.Strings[91594]="作为一个熊猫人，你了解所有的食物。没有什么能损害你的铁胃。开饭时间到了！"
D.Strings[91595]="|TInterface\\Icons\\spell_mage_altertime:20|t你拿到了一个|cFFFF0000|Hspell:206617|h[时间炸弹]|h|r。"
D.Strings[91596]="|TInterface\\Icons\\inv_archonpet:20|t%s开始施放|cFFFF0000|Hspell:211927|h[势不可挡]|h|r！"
D.Strings[91597]="|TInterface\\Icons\\inv_archonpet:20|t%s已经|cFFFF0000|Hspell:207972|h[蓄满力量]|h|r了！"
D.Strings[91598]="我看见你了，武僧！你的挣扎毫无意义。我的大军会将你的门派从这个世界上抹去！"
D.Strings[91599]="你逃不出我的掌心，武僧。尽管挣扎吧，但你的禅院必将化为瓦砾！"
D.Strings[91600]="你比看起来要强大一些，武僧，但我是不可阻挡的！乔维纳克斯！别让那座传送门关上！"
D.Strings[91601]="你好，感谢你帮助测试翡翠梦魇！\n\n我可以将你直接传送到开放测试的任意首领处。"
D.Strings[91602]="为什么要反抗吞噬万物的时间呢？"
D.Strings[91603]="我想传送到艾乐瑞瑟·雷弗拉尔那里。"
D.Strings[91604]="一次及时的死亡。"
D.Strings[91605]="我想传送到伊格诺斯，腐蚀之心那里。"
D.Strings[91606]="太单一，太狭隘了。"
D.Strings[91607]="时间是站在我这边的。"
D.Strings[91608]="时光的齿轮正与你背道而驰。"
D.Strings[91609]="你们是在和时间赛跑。"
D.Strings[91610]="我想传送到尼珊德拉那里。"
D.Strings[91611]="时间是残酷的。"
D.Strings[91612]="我想传送到梦魇之龙那里。"
D.Strings[91613]="感觉到时间静止了吗？"
D.Strings[91614]="时光飞逝。"
D.Strings[91615]="我想传送到萨维斯那里。"
D.Strings[91616]="精准。完美。不可避免。"
D.Strings[91617]="我想传送到塞纳留斯那里。"
D.Strings[91618]="我的时间到了。"
D.Strings[91619]="我想传送到乌索克那里。"
D.Strings[91620]="这只是时间问题。"
D.Strings[91621]="你的宠物太凶残了，我认为这是挑衅！"
D.Strings[91622]="如果你知道自己的命运……"
D.Strings[91623]="多么傲慢……很好，让你们见识见识！"
D.Strings[91624]="亲眼见证艾泽拉斯天外残酷冰冷的虚空吧！"
D.Strings[91625]="群星罗列！敬畏星辰的力量吧！"
D.Strings[91626]="凡人都无法抵抗命运的安排！"
D.Strings[91627]="群星寂灭之日，就是你们殒命之时！"
D.Strings[91628]="我有的是时间。"
D.Strings[91629]="我就先教教你什么叫谦虚吧。"
D.Strings[91630]="走开！我要好好想想这次的羞辱。"
D.Strings[91631]="真是无组织无纪律。"
D.Strings[91632]="你得学会谦卑，不然我就继续教训你。"
D.Strings[91633]="这种玩意儿给我打扫房间我都不要，更别说战斗了！"
D.Strings[91634]="有意思，再露两手给我看看吧。"
D.Strings[91635]="一次不幸的计算错误而已。"
D.Strings[91636]="你连胜利和牺牲都分不清楚。"
D.Strings[91637]="蹄印往左边的路去了。跟着它们，快！"
D.Strings[91638]="部落的战士！过来！我有发现了！"
D.Strings[91639]="我坚持不住了！"
D.Strings[91640]="救、救命！我不……不行了……"
D.Strings[91641]="谢谢你们，德鲁伊。这些梦魇畜生是不知疲倦的！不将利爪从我的巢穴里抢走，它们是不会罢休的。"
D.Strings[91642]="乌索克大人，燃烧军团回来了。$n是击败军团和梦魇的最大希望，但我们还需要您的利爪才有可能成功！"
D.Strings[91643]="我们谦卑地请求您的帮助。您的利爪能彻底击败我们的敌人。"
D.Strings[91644]="乌索克大人，我只想将圣爪带回正确的地方：不会滥用它们力量的地方。"
D.Strings[91645]="谢谢你，强大的乌索克！"
D.Strings[91646]="见到我，你肯定激动得不知所措了吧？我明白……大部分下等人见到我都会惊呆的。算你走运，我就大发慈悲跟你一战吧。"
D.Strings[91647]="算你走运，我只是一时失手而已！像我这种身份的人，才不会输给你这种粗鄙的平民呢。不准把这一战的结果告诉别人！"
D.Strings[91648]="我……呃……把你给我的那块水晶弄丢了。你那儿还有吗？"
D.Strings[91649]="你好，感谢你帮助测试苏拉玛王宫！\n\n我可以将你直接传送到开放测试的任意首领处。"
D.Strings[91650]="这座圣山只对猎人开放。$b回头吧，否则就让雄鹰之魂把你拖走！"
D.Strings[91651]="我想传送到水晶蝎那里。"
D.Strings[91652]="我想传送到时空畸体那里。"
D.Strings[91653]="我想传送到崔利艾克斯那里。"
D.Strings[91654]="我想传送到魔剑士奥鲁瑞尔那里。"
D.Strings[91655]="我想传送到提克迪奥斯那里。"
D.Strings[91656]="凯恩，我想返回黑暗神殿。"
D.Strings[91657]="我想传送到占星师艾塔乌斯那里。"
D.Strings[91658]="我想传送到高级植物学家特尔安那里。"
D.Strings[91659]="我想传送到克洛苏斯那里。"
D.Strings[91660]="我想传送到大魔导师艾利桑德那里。"
D.Strings[91661]="我想传送到古尔丹那里。"
D.Strings[91662]="听说你需要帮助，大人。是哪只可爱的小动物遇险了？噢，噢，我的天哪！"
D.Strings[91663]="其他蜘蛛看起来都很害怕它。"
D.Strings[91664]="我是葛拉沙尔之子葛拉什。$b$b那个蛇女巫用魔杖控制了我们。那些跟她作对的人都被杀害了。$b$b你是来杀那个蛇女巫的吗？"
D.Strings[91665]="她自称“吉斯林”。她手下有很多毒蛇。干掉她的追随者，狠狠打她的脸。$b$b她在使用魔杖为她的女王夺取水之王座。"
D.Strings[91666]="<葛拉什皱起了眉头。>$b$b这根魔杖非常古老，非常强大。它是由活水构成的。$b$b蛇女巫说这根魔杖来自她的女王。它能与大海沟通。海怪会听从魔杖的指令。它能治愈它们的伤口。$b$b魔杖让巨人的头脑中充满黑暗和痛苦。但这黑暗是来自那个女巫，而不是魔杖。"
D.Strings[91667]="萨满？是那种能和水与风暴对话的小家伙吗？$b$b对，葛拉什见过她。她和蛇女巫战斗，但失败了。$b$b蛇女巫活捉了她，还说会有笨蛋来救她的。$b$b哈哈！蛇女巫才是笨蛋呢，谁会蠢得来救那个女萨满啊。"
D.Strings[91668]="你要去杀蛇女巫？$b$b你要抢走魔杖？$b$b好啊！葛拉什要帮忙！"
D.Strings[91669]="这个蛇女巫是什么人？"
D.Strings[91670]="我们正在找一根魔杖！那根魔杖什么样？"
D.Strings[91671]="我们在找一位萨满。你见过她吗？"
D.Strings[91672]="跟我们走吧！我们要杀掉那个“蛇女巫”，抢走她的“魔杖”！"
D.Strings[91673]="我们必须保证这些墓穴的安全。不是所有人都有能力使用传送门的，其他人必须采用其他的旅行方法，虽然这些路途可能会很危险。"
D.Strings[91674]="%s的树皮开始龟裂！"
D.Strings[91675]="如今这年头，谁都别想独善其身。"
D.Strings[91676]="成功了！圣爪归我们了！"
D.Strings[91677]="你的盟友倒下了！仪式失败了！"
D.Strings[91678]="我得去接受我的奖品了。马利萨。我把利爪交给你了，用它们消灭这个渣滓吧。"
D.Strings[91679]="你成功了，$n！你打败他了！"
D.Strings[91680]="该走了。这里没我们的事了。你准备好以后就告诉我一声，我会把我们送回现实的身躯里。"
D.Strings[91681]="你准备好了？可以走了吗？"
D.Strings[91682]="勇士，我们必须再次请求你独自出征了。要想赢得胜利，我们就必须削弱海拉的大军。"
D.Strings[91683]="不要太勉强了。海拉总有一天要面对盛怒的奥丁。但在此之前，你也已经削弱了她的大军。"
D.Strings[91684]="你确定要开启这场战斗吗？"
D.Strings[91685]="你准备好开始仪式了吗？"
D.Strings[91686]="这朵发光的鲜花非常夺目。似乎有个园艺高手在精心照料着它。"
D.Strings[91687]="这些新挑战者想参加你征服过的试炼。让他们看看真正的勇士是怎么战斗的！"
D.Strings[91688]="让他们认清自己的实力，总比让他们继续自我陶醉强。"
D.Strings[91689]="这朵发光的鲜花非常夺目。似乎有个园艺高手在精心照料着它。\n\n这种事还是交给更亲近大自然的人来做吧。"
D.Strings[91690]="戴斯蒙德似乎遇到了不该遇到的人。"
D.Strings[91691]="<检查尸体，查找线索。>"
D.Strings[91692]="那些缚墨者已经迷失了道路！他们忘了符文魔法传承真正的目的。我们得在他们变本加厉之前阻止他们。"
D.Strings[91693]="一想到要亲眼看着他们滥用符文魔法，我就难过。"
D.Strings[91694]="后会有期，$n，愿艾露恩指引我们的道路。"
D.Strings[91695]="摘下这朵花会释放出提神孢子。你对此很有把握，因为你学习过草药学，通晓植物知识。"
D.Strings[91696]="你深深吸了一口它的孢子。作为一名德鲁伊，你亲近自然，所以能够辨别出这朵花的有益成分。"
D.Strings[91697]="我们无处不在。我们是燃烧军团。"
D.Strings[91698]="多管闲事的……小崽子……"
D.Strings[91699]="恶魔正在步步逼近勇者之门。我们需要你的帮助。"
D.Strings[91700]="你今天做得很好，勇士。愿你敌人的哀嚎响彻扭曲虚空。"
D.Strings[91701]="你来这个无法无天的地方做什么？"
D.Strings[91702]="暗影现形。"
D.Strings[91703]="燃烧军团，诸界的毁灭者。"
D.Strings[91704]="我们还有反抗的希望吗？你呢？！"
D.Strings[91705]="比起星辰的威严，你们微不足道——一文不值。"
D.Strings[91706]="你到底是什么人？"
D.Strings[91707]="多么肤浅的战斗。我还以为你们有多大能耐呢。"
D.Strings[91708]="这还不够？非要让我展示一下现实世界的真正恐惧吗？"
D.Strings[91709]="很好……见证我所目睹的灾难并瑟瑟发抖吧！"
D.Strings[91710]="虚妄的化身……唯余饥渴的邪神。"
D.Strings[91711]="这些存在将吞噬你们无力保护的未来！"
D.Strings[91712]="不……我控制不住了……虚空……降临了！"
D.Strings[91713]="我是无人能及的情报贩子。$B$B你只要知道这一点就够了。"
D.Strings[91714]="群星认为你还有所欠缺。"
D.Strings[91715]="我们还是说回正事吧。"
D.Strings[91716]="那里的生物都是由远古魔力驱动的。虽然这很可怕，可我必须请求你干掉它们，吸光它们的能量。"
D.Strings[91717]="看来命运站在了你那边。"
D.Strings[91718]="谢谢你。这是一个可怕的任务，但这对我们的生存至关重要。"
D.Strings[91719]="此刻，阿卡丽就在城里为她的主子们刺探情报。"
D.Strings[91720]="我很乐意告诉你……只要一个传送符文。"
D.Strings[91721]="到时候，我们的任务才算完成。"
D.Strings[91722]="我们去月神殿。阿什阿拉的速度更快，让它载我们一程吧。你做好离开的准备了吗？"
D.Strings[91723]="我们去月神殿。阿什阿拉可以破例载你一程。做好准备。"
D.Strings[91724]="你好！你是来参观我的精美藏品的吗？"
D.Strings[91725]="如果你是来看我最珍贵的收藏的，那你恐怕要失望了，我已经把它藏起来了。$b$b我大概会在一百年后再把它展出一次，你要先做个预约吗？"
D.Strings[91726]="我是收藏家莫纳斯，专门收藏各种精美的艺术作品和收藏品。你想看看我收藏的雕塑作品吗？"
D.Strings[91727]="勒斯平想要回他的雕塑作品。"
D.Strings[91728]="归于虚无。"
D.Strings[91729]="你无法逃避死亡。"
D.Strings[91730]="我还以为你不来了呢。"
D.Strings[91731]="我只提供最优质的产品。"
D.Strings[91732]="让我看看你最新的货物。"
D.Strings[91733]="我恐怕没什么可分享的情报。酒精能让人们开口，可有时候他们就是说不出什么有用的东西来。"
D.Strings[91734]="话说，你要不要顺便尝尝阿苏纳湿乳酪？它的味道非常浓郁美妙！"
D.Strings[91735]="这么做将会移除你背包中的|cFF0070dd|Hitem:124441:0:0:0:0:0:0:0:90:0|h[魔光碎片]|h|r。确定要这么做吗？"
D.Strings[91736]="经过多年的努力，我们终于接近她了……"
D.Strings[91737]="你搞定之后，就到荣耀杂货店的楼上来找我。又有卡德加的走狗在附近四处转悠，东问西问的……"
D.Strings[91738]="如果你没有找到魔光碎片，那我恐怕就完不成仪式了。$b$b你不会把他们忘在银行里了吧？"
D.Strings[91739]="不要思考……未来就会变得简单。"
D.Strings[91740]="我听说你有一本我要找的书。"
D.Strings[91741]="啊，没错，我知道那本书。它应该在楼上的某个书架里。你自己去找吧。"
D.Strings[91742]="我今天还没有炸到任何人呢。真是个好日子。"
D.Strings[91743]="唔……你进来的时候没有看到任何核能炸弹对吧？没有吧？好吧，我会继续找的。"
D.Strings[91744]="欧申克这家伙总是用“螺丝刀”来拧螺栓。难道他都没听说过锤子吗？"
D.Strings[91745]="作为一名惩戒圣骑士，你是弱者坚定的守护者，是打击邪恶的使者！"
D.Strings[91746]="对这个目标假人使用审判。"
D.Strings[91747]="让麝牛踏碎你的骨头吧！"
D.Strings[91748]="白熊会把你撕成碎块的！"
D.Strings[91749]="你被发现了！"
D.Strings[91750]="麝牛！赐予我你的坚韧吧！"
D.Strings[91751]="哈！麝牛又一次证明了自己才是最强的！"
D.Strings[91752]="我被羞辱了。"
D.Strings[91753]="让铁蹄踏碎你！"
D.Strings[91754]="还不够！我还要碾碎更多的敌人！"
D.Strings[91755]="光荣的战斗！"
D.Strings[91756]="留在阴影中，以避免被发现。肯瑞托可不是傻子。"
D.Strings[91757]="布约恩！赐予我你的狂野吧！"
D.Strings[91758]="哈！白熊又一次证明了自己才是最强的！"
D.Strings[91759]="让利爪撕碎你们！"
D.Strings[91760]="还不够！我还要砸扁更多的敌人！"
D.Strings[91761]="如果我不尽快赶回去，队长会砍了我的脑袋的……"
D.Strings[91762]="有事吗，平民？"
D.Strings[91763]="有事就说，不然就走。我在等人呢。"
D.Strings[91764]="我们委托制作的钻石稳定器总算来了。现在，能量导管或许就不会再短路了。"
D.Strings[91765]="我的陪练纳特西斯跟我说过你的事迹。你会成为一个好士兵的。"
D.Strings[91766]="我从勒斯平那里拿回你的包裹了。"
D.Strings[91767]="艾尔！见证我的壮举吧，我要打倒这个所谓的勇士。"
D.Strings[91768]="我已经有数千年没见过这么多驳船记录了，那些货物清单和记录都快把我搞晕了。"
D.Strings[91769]="动作快点，大海可不等人。"
D.Strings[91770]="过去一万年里我都没这么忙过。你找我有什么事？"
D.Strings[91771]="很好，这是我的金胸针。毕竟，一名显赫的官员也需要一个同样显赫的证章，不是吗？"
D.Strings[91772]="我见过安娜丝黛的新大衣了。告诉我，你还弄得到那种毛皮吗？我可以付给你比勒斯平更高的报酬。"
D.Strings[91773]="有一些瓦尔基拉想要和你单挑。快去斯考德-艾希尔迎接他们的挑战吧。在你主动出手之前，是不会有人攻击你的。"
D.Strings[91774]="我的鸟儿唱得多好听。"
D.Strings[91775]="多么美好的一天。"
D.Strings[91776]="“借用”"
D.Strings[91777]="你有东西要给我吗？"
D.Strings[91778]="啊，多么漂亮的栖木，正好可以把那根坏了的换掉。"
D.Strings[91779]="我感觉勒斯平就快没用了。你最好小心点。"
D.Strings[91780]="我将……前往……英灵殿。"
D.Strings[91781]="出来！"
D.Strings[91782]="不准打扰大法师塞琳德拉！"
D.Strings[91783]="我肯定没听错。别担心，大法师，我会找到他们的！"
D.Strings[91784]="我也听到了。大法师，我这就去把他们赶走！"
D.Strings[91785]="我的结界侦察到，有人进入了书房。快去把他们找出来！"
D.Strings[91786]="勇士！记住，站在你面前的是你的送葬者，布蕾塔。"
D.Strings[91787]="<将传送门符文交给瓦尔祖恩。>"
D.Strings[91788]="很好……你可以在魔术旅馆找到阿卡丽。"
D.Strings[91789]="让我们来一场精彩的战斗吧。"
D.Strings[91790]="我要用你的死亡来换取荣耀。"
D.Strings[91791]="我要让你血溅当场。"
D.Strings[91792]="阿卡丽……你的死期到了。"
D.Strings[91793]="艾尔……指引我回到你的身边。"
D.Strings[91794]="我将面对我的命运……"
D.Strings[91795]="只有最伟大的瓦尔基拉才配得上艾尔的恩赐。"
D.Strings[91796]="神王斯科瓦尔德死去的三个兄弟又复活了。去找到他们，提醒他们还是老老实实躺着比较好。"
D.Strings[91797]="四兄弟。每一个都参与了弑父的阴谋，每一个都卷入了兄弟阋墙的悲剧。斯科瓦尔德就是这么登上王位的，因为他出剑更快。"
D.Strings[91798]="我们抵达时，阿卡丽退回到楼上。她归你了。"
D.Strings[91799]="我得谢谢你，省得我再去找你们了。"
D.Strings[91800]="你的脑袋一定会让基尔加丹满意的。"
D.Strings[91801]="你以为主人会这么蠢吗……？"
D.Strings[91802]="隔壁有个蛇人。大蛇人。$b$b葛拉什闻到鱼腥味儿了。"
D.Strings[91803]="大家都准备好了，葛拉什。打碎冰墙吧！"
D.Strings[91804]="我要把你和你的宠物拖入海底。"
D.Strings[91805]="保护好你自己吧，凡人。"
D.Strings[91806]="跟我一起沉入深海吧。"
D.Strings[91807]="溺水了。我溺水了。"
D.Strings[91808]="很快就会有新的灵魂加入我们了。"
D.Strings[91809]="躺着别动，让海水将你带走吧。"
D.Strings[91810]="弱者总是死得快。"
D.Strings[91811]="又死了一个。"
D.Strings[91812]="你开始惹恼我了，凡人。"
D.Strings[91813]="我一定会慢慢弄死你，好好品尝你的痛苦的。"
D.Strings[91814]="拿到吞噬者之牙了？"
D.Strings[91815]="瓦尔祖恩，我要杀了你！"
D.Strings[91816]="你们都要死在我的刀下。"
D.Strings[91817]="可悲的蝼蚁。死吧！"
D.Strings[91818]="我从暗影中出击。"
D.Strings[91819]="有东西过来了。是个大家伙。"
D.Strings[91820]="住手！住手！我什么都不知道！我发誓！"
D.Strings[91821]="我还能帮忙！我能带你去阿卡丽的堡垒！"
D.Strings[91822]="只要冷却一结束，你就能对远处或近处的敌人使用审判。"
D.Strings[91823]="对这个目标假人使用公正之剑。"
D.Strings[91824]="遵命，萨维斯大人！我很乐意为您撕碎他们！"
D.Strings[91825]="啊啊啊！！！这对利爪！在渴望鲜血！！"
D.Strings[91826]="在敌人靠近时，公正之剑是很好的伤害手段。"
D.Strings[91827]="对这个目标假人使用十字军打击。"
D.Strings[91828]="你准备好开始了吗？"
D.Strings[91829]="开启传送门。"
D.Strings[91830]="感谢理解。"
D.Strings[91831]="祝你通过试炼，勇士。"
D.Strings[91832]="我的麝牛会踩扁你的小熊！"
D.Strings[91833]="小个子也有大家伙！"
D.Strings[91834]="我要把你的野兽拖进冥狱深渊，扔进海拉那该死的兽栏里！"
D.Strings[91835]="我很警觉，没有哪头野兽能逃脱我的掌心……"
D.Strings[91836]="成功了。通往影血堡垒的道路开启了。"
D.Strings[91837]="你有一种不祥的预感——这里似乎不欢迎你。"
D.Strings[91838]="快行动吧，去支援先知！让火焰之地看看大地之环的力量！"
D.Strings[91839]="净化这根法杖吧，我的孩子。我来挡住那个畜生！"
D.Strings[91840]="快，英雄！我们就快成功了。把法杖给我！"
D.Strings[91841]="我以为会受到热烈欢迎……但没想到会是这样！"
D.Strings[91842]="先知来了！让这些该死的虫子看看我们的本事！"
D.Strings[91843]="大地之环与你同在，先知！"
D.Strings[91844]="恶魔正在围攻我的山头！我们需要你，勇士。"
D.Strings[91845]="干得好。你帮助我们压倒了这些邪恶的怪物。我要感谢你，凡人！"
D.Strings[91846]="你好，朋友。德克加尔的渣滓还在杀害和奴役我的同胞。来吧，跟我一起向赫达沙尔复仇！"
D.Strings[91847]="能彻底夷平整个赫达沙尔就好了！唉，但复仇必须一步步来。"
D.Strings[91848]="<将法杖交给莱莎>。"
D.Strings[91849]="加油！用战斗意志来坚定你的决心吧！"
D.Strings[91850]="$n。我只想在返回邪能之槌号前先报备一下。\n\n如果你有任务要交给我去执行，就尽管下令吧。"
D.Strings[91851]="你必须立刻前往英灵殿。准备好了吗？"
D.Strings[91852]="送我去英灵殿吧。"
D.Strings[91853]="|TInterface\\Icons\\ability_felarakkoa_feldetonation_red:20|t%s获得了|cFFFF0000|Hspell:206221|h[强化邪能束缚]|h|r。"
D.Strings[91854]="|TInterface\\Icons\\Spell_Fire_FelFlameStrike:20|t%s获得了|cFFFF0000|Hspell:206220|h[强化液态地狱火]|h|r。"
D.Strings[91855]="|TInterface\\Icons\\inv_misc_trinket6oih_orb1:20|t%s获得了|cFFFF0000|Hspell:211152|h[强化古尔丹之眼]|h|r。"
D.Strings[91856]="将我传送到下一个旅店。"
D.Strings[91857]="|TInterface\\Icons\\Spell_Shadow_MindRot:20|t%s召唤$n前来帮忙|h|r。"
D.Strings[91858]="现在，让我们来消灭剩余的恶魔吧！"
D.Strings[91859]="你是来接受评审的吗？"
D.Strings[91860]="让我们看看你带来的这些野兽有没有资格吧。"
D.Strings[91861]="这些试炼可不简单。"
D.Strings[91862]="狩猎场在等着你们。"
D.Strings[91863]="死亡并不可怕。"
D.Strings[91864]="他们的数量简直无穷无尽，但我们会胜利的。"
D.Strings[91865]="生命正在消逝。"
D.Strings[91866]="又死一个。"
D.Strings[91867]="你已经尽全力了？真的？"
D.Strings[91868]="嘿，$n！对，就是你！先别管那些净化此地的废话了，来杀了这边这个大家伙。"
D.Strings[91869]="我觉得杰斯太沉迷于他的玩具了。"
D.Strings[91870]="我还是适应不了这里。$b$b等搞定这个工程，我们就能撤出这里了。"
D.Strings[91871]="奥丁的狩猎场里有着各种强大的野兽。让我们看看你的这些动物有没有资格加入它们的行列吧。"
D.Strings[91872]="虽然你的这些野兽都有资格进入狩猎场，但现在还不到时候。它们注定要参加更多光荣的战斗。"
D.Strings[91873]="嘿，这不是你该来的地方！$b$b听着，我们可没有给你买过保险，而且你妨碍我们工作了。$b$b我必须请你离开。"
D.Strings[91874]="阿卡丽就在这座堡垒里。你应该可以神不知鬼不觉地找到她。"
D.Strings[91875]="你能带我离开这里吗？"
D.Strings[91876]="嘿，这不是你该来的地方！$b$b听着，我们可没有给你买过保险，而且你妨碍我们工作了。我敢打赌，你肯定已经被困在这里了！$b$b我可以把你弹出去。就当帮你自己一个忙，等我们搞定之后再来，好吗？"
D.Strings[91877]="我明白了，谢谢。"
D.Strings[91878]="你珍爱的一切都将燃烧！"
D.Strings[91879]="我要撕碎你们的世界！"
D.Strings[91880]="我要把你们碾成粉末！"
D.Strings[91881]="你们将四分五裂……"
D.Strings[91882]="可笑！这世界竟能存在这么久。"
D.Strings[91883]="我觉得你们还没到极限！"
D.Strings[91884]="再加点难度怎么样？"
D.Strings[91885]="你可以进来，但是求助就免了，萨满。我知道大地之环想联合四大元素！"
D.Strings[91886]="燃烧军团威胁到了我们所有人，但火焰之地不会白白出力。"
D.Strings[91887]="你们还没吃够教训吗？"
D.Strings[91888]="到我的王座来，让我看看你能为拯救世界出多少力吧！"
D.Strings[91889]="看看符文之刃真正的力量吧！"
D.Strings[91890]="准备承受我的最强一击！"
D.Strings[91891]="独乐乐不如众乐乐……"
D.Strings[91892]="我的仆从们，给这些自命不凡的家伙一个教训吧！"
D.Strings[91893]="一群外行！你们才是自己最大的敌人！"
D.Strings[91894]="小心脚下！我可不想看到你们跌倒了。"
D.Strings[91895]="我给了你们赢得荣耀的机会，可你们彻底搞砸了！"
D.Strings[91896]="我只能……认输了……"
D.Strings[91897]="就把这当做一堂剑术课吧！"
D.Strings[91898]="你们都将成为我的剑下亡魂！"
D.Strings[91899]="他们真走运，能遇到如此强大的敌人！要不是他们都死了，我还真有点嫉妒他们呢。"
D.Strings[91900]="真让人吃惊……我又杀了一个！"
D.Strings[91901]="你们应该有难同当！"
D.Strings[91902]="尝尝失败的冰冷滋味吧！"
D.Strings[91903]="你引起了我的注意！"
D.Strings[91904]="我来找你了！"
D.Strings[91905]="来点儿魔法会让这变得更有趣！"
D.Strings[91906]="清理废物的时候到了！"
D.Strings[91907]="这是属于我的战场！"
D.Strings[91908]="|TInterface\\Icons\\INV_Misc_Rune_10:20|t打碎符文石，打断符文先知法尔加的|cFFFF0404|Hspell:208544|h[符文壁垒]|h|r！"
D.Strings[91909]="在战斗中使用公正之剑和十字军打击可以累积神圣能量。"
D.Strings[91910]="攻击可以积累神圣能量，然后对目标假人使用圣殿骑士的裁决。"
D.Strings[91911]="余烬之痕已经苏醒并渴望着灵魂。击败那些烬网伏击者！"
D.Strings[91912]="主人回来了！我们必须确保房间一尘不染。"
D.Strings[91913]="那不是主人，白痴！除非他能从两吨重的大石头下面爬出来。"
D.Strings[91914]="噢，这真叫人惊讶……我以为他的手还在罐子里呢。"
D.Strings[91915]="请别这么说！主人回来了，一切都要井井有条。"
D.Strings[91916]="你把泥巴都带进来了！"
D.Strings[91917]="你对我的服务还满意吗？"
D.Strings[91918]="咬一口吧，主人，我知道你喜欢的。"
D.Strings[91919]="%s痛苦地翻滚着。"
D.Strings[91920]="你竟敢在我的地板上丢垃圾？！去死吧！！！"
D.Strings[91921]="脏死了，脏死了，脏死了！！！"
D.Strings[91922]="别动，主人，正在焚化！"
D.Strings[91923]="别扭来扭去的！我捅不着你了！"
D.Strings[91924]="很高兴见到你，主人，我能为你做点什么吗？"
D.Strings[91925]="%s一边抽搐一边呓语着。"
D.Strings[91926]="欢迎回家，主人，请让我帮你拿……脑袋吧！！！"
D.Strings[91927]="干得好，先知。余烬之痕归我了，反对者都闭嘴了！"
D.Strings[91928]="主人，是你吗？！你的脑袋还在，我都没认出来。"
D.Strings[91929]="你就不能老老实实地死掉吗？！"
D.Strings[91930]="你竟敢把血洒在我的地板上！"
D.Strings[91931]="为了表示诚意，我将派出我的仆人斯卡迪乌斯协助大地之环。"
D.Strings[91932]="你看起来很饿，主人。请用些点心吧。"
D.Strings[91933]="打得好，先生，正好打在我的疼痛神经上。"
D.Strings[91934]="我不知道我做了什么，但我肯定是活该挨打。"
D.Strings[91935]="疼痛是个好老师，我会努力记住你的教诲的，主人。"
D.Strings[91936]="抱歉，这里太乱了，主人。我马上打扫干净。"
D.Strings[91937]="燃烧军团将在火焰之地的恐怖威能前瑟瑟发抖！"
D.Strings[91938]="在我的国度里小心点，萨满。先知也可能被烧伤……"
D.Strings[91939]="噢，我的头……我在哪儿？"
D.Strings[91940]="火焰之地是最恐怖的元素位面。我们必须谨慎行事，尊重周围的一切。"
D.Strings[91941]="瑟鲁斯之眼朝你看过来了！"
D.Strings[91942]="瑟鲁斯之眼发现了你，跑去向它的盟友求助了！"
D.Strings[91943]="你好，大宗师$n。你今天还好吗？"
D.Strings[91944]="此时此刻，在黑暗之中，光明才最为耀眼。"
D.Strings[91945]="大家都很担心燃烧军团，可我们相信你，大宗师。"
D.Strings[91946]="很高兴见到你，大宗师。你让我们的精神都为之一振。"
D.Strings[91947]="残寺派一定会在你的领导下绵延不绝的。一定会……"
D.Strings[91948]="你今天要去哪儿，大宗师？"
D.Strings[91949]="我们的努力会收到回报的，我相信。"
D.Strings[91950]="我们不能放弃战斗，大宗师。我完全相信你的判断。"
D.Strings[91951]="作为一个武僧，就该为和谐与平衡而战。你是最适合领导我们的人，$n。"
D.Strings[91952]="这座庄园很豪华，对吧？光是在这里走走，就让我感觉到了安宁。"
D.Strings[91953]="我每次都告诉自己，要在这些派对上多交些朋友，可最后总是被甜点吸引。"
D.Strings[91954]="对，我这件礼服最漂亮了。谢谢你的称赞。$B$B虽然它害得我一动都不敢动，但这不算什么啦。"
D.Strings[91955]="呃，我听说有人扮成了猫头鹰。$B$B好吧，我们中总有一个人得换掉……"
D.Strings[91956]="你这身装扮……真是……特别。"
D.Strings[91957]="自从屏障消散以来，这里的安保措施就更严格了。我们不能把任何暴民放进来，不是吗？"
D.Strings[91958]="你在普通装扮下又穿了……外来者的装扮？$B$B多么天才的想法！"
D.Strings[91959]="<叹气。>$B$B我还以为这次我的打扮肯定是最特别的了，但看来我又输了。"
D.Strings[91960]="有话快说——我的装扮要动起来才会更好看。"
D.Strings[91961]="谁找到过塔莉萨的尸体了？"
D.Strings[91962]="<嘲弄地>恶魔。我说对了吗？<你翻了个白眼。>"
D.Strings[91963]="术士向来不可靠。万一古尔丹背叛我们怎么办？"
D.Strings[91964]="我们怎么才能摆脱燃烧军团的阴影？"
D.Strings[91965]="你好吗，我的夜之子同胞？"
D.Strings[91966]="<用力眨眼睛。>"
D.Strings[91967]="难道就没有人愿意站出来反抗艾利桑德了吗？"
D.Strings[91968]="我们就不能不要坐看世界化为火海吗？哪怕就试一次呢？也许我们会喜欢的。"
D.Strings[91969]="现身。"
D.Strings[91970]="影血追猎者咆哮了起来。"
D.Strings[91971]="影血追猎者激动地嗅着空气中的味道。"
D.Strings[91972]="影月追猎者的毛发竖了起来。"
D.Strings[91973]="影血追猎者跳了起来！"
D.Strings[91974]="如果我假装不认识你，请不要见怪。"
D.Strings[91975]="有意思……"
D.Strings[91976]="你知道的，大魔导师的探子无处不在。"
D.Strings[91977]="这场谈话让我觉得很无聊。"
D.Strings[91978]="唔，是啊，真是太棒了。"
D.Strings[91979]="这是造谣！"
D.Strings[91980]="谁让你进来的？"
D.Strings[91981]="你们可以试试看。"
D.Strings[91982]="自从你从走进这里，就已经是个死人了。"
D.Strings[91983]="送他们去牢房。基尔加丹大人一定会高兴的。"
D.Strings[91984]="派援军去十字路口北边。塔楼遭到了攻击！我们被包围了！"
D.Strings[91985]="一整套外来者的行头？真恶心。"
D.Strings[91986]="这算什么打扮？我可不想跟你站在一起。"
D.Strings[91987]="快穿上体面的礼服吧，否则我就把你扔出去。"
D.Strings[91988]="谢谢你！等这一切结束之后，你一定要经常回来钓鱼哦！"
D.Strings[91989]="你转交了这封信之后，请代我向安度因王……国王表达慰问。"
D.Strings[91990]="这些古老的岩石已经有上万年没有动弹过了。你必须再次接受考验。把你的手放在石头上，做好准备吧。"
D.Strings[91991]="艾尔已经注意到了你的事迹。小心不要让她失望。"
D.Strings[91992]="天空之墙真是个神奇的地方，$n。我这辈子都没见过类似的地方。"
D.Strings[91993]="湿透了！"
D.Strings[91994]="我绝不容许任何人变成魔誓的叛徒，为燃烧军团效力。"
D.Strings[91995]="做好准备，仆从们。主人要让我们上战场了。"
D.Strings[91996]="我们的敌人将体验痛苦的撕咬！他们都要死！"
D.Strings[91997]="小心点，除非你想变成我的野兽口中的美餐。"
D.Strings[91998]="你真是个高手。"
D.Strings[91999]="吉斯林想用巨浪碾碎我们！"
D.Strings[92000]="萨满，让葛拉什走前面，充当我们的堤坝。"
D.Strings[92001]="我再说最后一次！滚……出……我的……码头！"
D.Strings[92002]="只要我还有一口气在，你就休想登上我的船，恶魔！"
D.Strings[92003]="欺诈者军团，出击！荣耀在等着你们！"
D.Strings[92004]="那个狱卒给了你逃跑的机会。"
D.Strings[92005]="使用|TInterface\\Icons\\inv_misc_bag_10_red.blp:20|t |cFFFF0000|Hspell:185438|h[搜索]|h|r逃跑！"
D.Strings[92006]="你是来找忧郁的罗莎的，对吧？$B$B那我能为你做点什么呢，嗯？"
D.Strings[92007]="海上又开始涌出那种那该死的浓雾了。去干掉那里的克瓦迪尔，不要让他们的黑暗继续扩散。"
D.Strings[92008]="在他们最大的港口被迷雾笼罩后，人们就开始称他们为蔑潮部族。那时起，忠于奥丁的维库人就再也不愿踏足那片被诅咒的土地了。"
D.Strings[92009]="我听说你这里可能有我要找的货物……"
D.Strings[92010]="嘘。到屋后的桌子上去看看吧。莉莉丝夫人在等着你呢。"
D.Strings[92011]="女主人！囚犯逃跑了！"
D.Strings[92012]="瑟鲁斯，干掉他们。我们就快联系上了。"
D.Strings[92013]="蠢货！他来了……"
D.Strings[92014]="一个真实存在的位面，气元素的位面。这真是太神奇了……"
D.Strings[92015]="瑟鲁斯来了。快逃命吧！"
D.Strings[92016]="我的家乡就没有这种地方。除了艾泽拉斯，其他世界有这种位面吗？"
D.Strings[92017]="快跑吧，否则就迟了！"
D.Strings[92018]="我并不羡慕你，$n。要领导我们渡过危机，你的负担一定很重。"
D.Strings[92019]="燃烧军团入侵德拉诺时，我没能拯救我的人民……和我的家乡。"
D.Strings[92020]="我们得拉拢元素……否则这世界就会成为第二个德拉诺。"
D.Strings[92021]="天墙之心拥有为那把剑充能所需的能量。"
D.Strings[92022]="我们要继续前进了，时间紧迫！"
D.Strings[92023]="这是个黑暗的时代，$n，可你不能绝望。"
D.Strings[92024]="我曾经在德拉诺的废墟中徘徊，满心绝望和痛苦。"
D.Strings[92025]="在我最黑暗的岁月里，是元素唤醒了我。"
D.Strings[92026]="你也会得到指引的，先知，只要你仔细听。"
D.Strings[92027]="四风之杖就快完成了。我们得快一点，这事关重大。"
D.Strings[92028]="这里的元素真是乱作一团……它们需要风元素领主的指引。"
D.Strings[92029]="是时候了，$n。复活桑德兰王子的条件都满足了，快行动吧。"
D.Strings[92030]="没人能从我眼皮底下逃走……"
D.Strings[92031]="我……我复活了！圣光在上，我又活过来了！"
D.Strings[92032]="救命！求求你……"
D.Strings[92033]="他们突然就冒了出来！你能帮我一把吗？"
D.Strings[92034]="你在这里干什么？你没看见我正在忙着准备美味的大餐吗？"
D.Strings[92035]="我必须回去做菜了！"
D.Strings[92036]="总算搞定了。我该回去继续准备了。"
D.Strings[92037]="这叫我怎么工作！"
D.Strings[92038]="如果你忍受不了高温的话……"
D.Strings[92039]="就滚出厨房！"
D.Strings[92040]="我将给你带来无尽的痛苦。"
D.Strings[92041]="我准备了高级食材！"
D.Strings[92042]="人人都是美食家。"
D.Strings[92043]="闻起来很糟糕。"
D.Strings[92044]="我得再核对一下食谱。"
D.Strings[92045]="蛇女巫。她就在里面。$b$b葛拉什很……害怕。$b$b那个蛇女巫会用她的魔杖控制葛拉什的。"
D.Strings[92046]="这是禁地！"
D.Strings[92047]="我保证，我会保护你的，葛拉什。冲进去吧！"
D.Strings[92048]="这是给你的教训！"
D.Strings[92049]="活该！"
D.Strings[92050]="我的任务……完成了。"
D.Strings[92051]=" 成功完成任务！"
D.Strings[92052]="我需要援军！"
D.Strings[92053]="这应该能扳回一城！"
D.Strings[92054]="卑鄙小人……懦夫！"
D.Strings[92055]="给我站住！"
D.Strings[92056]="你需要面对许多危险，早做准备将是你生存的关键。"
D.Strings[92057]="使用圣盾术，让你暂时免疫一切伤害！"
D.Strings[92058]="结局已经注定了。"
D.Strings[92059]="迎接扭曲黑暗的拥抱吧。"
D.Strings[92060]="梦魇吞噬了我……驱使我……为它效劳……为它杀戮！"
D.Strings[92061]="那是守护者送给我的神圣礼物！对，梦魇之王……对，利爪之怒必须回到我的手中！"
D.Strings[92062]="你们将我从梦魇中解放了出来。乌索克之爪……对你们很有帮助……"
D.Strings[92063]="守护者的礼物又属于我了！不……不是我……它是属于梦魇的。"
D.Strings[92064]="我要像拍扁树苗一样拍扁你们！"
D.Strings[92065]="荒野面对我的怒火时也会瑟瑟发抖！"
D.Strings[92066]="嗷嗷嗷！！！"
D.Strings[92067]="它们会将你的血肉吞噬殆尽……"
D.Strings[92068]="同时挑战这么多人可不明智！"
D.Strings[92069]="烧焦的骨头……真让人开心！"
D.Strings[92070]="又能多一捆柴火了！"
D.Strings[92071]="我的火葬柴堆……一定……很壮观……"
D.Strings[92072]="看来我要有一顿烧烤大餐了！"
D.Strings[92073]="别闲着，去周围看看！"
D.Strings[92074]="还等什么？去看看怎么回事！"
D.Strings[92075]="今晚，城里的贵族将举行一场盛大的晚宴。厨师会把储备的所有魔力酒都送去他的厨房。我们要你帮忙引开他，以便我们尽可能帮他“减轻负担”。"
D.Strings[92076]="你！去那边看看！"
D.Strings[92077]="很好！你为我的密探们争取了足够的时间，几乎弄走了他们所有的魔力酒。"
D.Strings[92078]="凡人的血肉……燃烧得太美了！"
D.Strings[92079]="我感觉容光焕发！"
D.Strings[92080]="看着你们熔化真让我愉悦！"
D.Strings[92081]="谁需要跟班？我要亲手烧死你们！"
D.Strings[92082]="我想我兄弟马德兰尼尔应该已经准备好陪你一起上路。感谢你的帮助，朋友。"
D.Strings[92083]="尤隆发出了轻柔的呼噜声。"
D.Strings[92084]="使用圣光闪现治疗你的伤势。"
D.Strings[92085]="我对你的期望是那么高。业余商人会认为生意伙伴是宝贵的盟友。只有大师才明白他们都是竞争者和讨债鬼。"
D.Strings[92086]="我总觉得你有些不对劲。"
D.Strings[92087]="赤蹄小心地用蹄子刨着土。"
D.Strings[92088]="我们好像到了，$n。让我们看看赛莱托斯接下来会让我们做什么吧。"
D.Strings[92089]="新鲜的绿色食物重新开始生长，你的天敌数量也减少了。作为回报，我们只需要你的祝福。"
D.Strings[92090]="我想我应该把这堆垃圾扔出去，给新设备腾出地方。"
D.Strings[92091]="星爪坐了下来，把脑袋埋进翅膀下面。过了一会儿，她重新站直了身体，将一个干瘪的猫头鹰爪子交给梅鲁娜。"
D.Strings[92092]="星爪低下了头，向你表达无声的谢意，然后再次飞上了天空。"
D.Strings[92093]="你能帮我修复这个烧瓶吗？"
D.Strings[92094]="银牙将一根光滑闪亮的夜刃豹獠牙放在了地上。"
D.Strings[92095]="银牙发出一声低沉、温顺的嗥叫。"
D.Strings[92096]="你想要我的帮助，可你却没什么可以回报我的，$r。如果是这样的话，你或许能帮我的部族一个忙。$b$b我们已经有好几年没喝到过河鬃部族的药酒了。他们的药酒有着提神醒脑的功效，而且对牙齿有好处。幸运的是，我刚好知道这种药酒的酿造方法。$b$b我会把我的研钵和捣杵，还有药酒的配方给你。你为我的部族带回足够的药酒，我就帮你修复这个烧瓶。$b$b成交吗？"
D.Strings[92097]="我们的努力没有白费。月语主母从远方注视着我们。"
D.Strings[92098]="愿你的狩猎永不落空，姐妹。"
D.Strings[92099]="你可以在河鬃的营地里找到一片南瓜地。挑选最熟的南瓜来榨汁。"
D.Strings[92100]="至高岭到处都有狐尾花生长。祝你好运，$r。"
D.Strings[92101]="我对你很不满意。"
D.Strings[92102]="没有人能抵抗梦魇！"
D.Strings[92103]="一个牧师！感谢圣光！"
D.Strings[92104]="献上你的生命吧，就像我一样。"
D.Strings[92105]="漫长的梦境……终于降临了。"
D.Strings[92106]="滚开，凡人！风元素领主的时代结束了！"
D.Strings[92107]="愚蠢的萨满！你真以为桑德兰能拯救你的世界吗？"
D.Strings[92108]="我要吞噬你，四风之杖将属于我！"
D.Strings[92109]="梦魇是无法摆脱的。"
D.Strings[92110]="听着，先知……我愿意暂时帮助大地之环。"
D.Strings[92111]="天空之墙的大军将与凡人种族并肩战斗，对抗燃烧军团。"
D.Strings[92112]="待战争的迷雾散去，燃烧军团必将一败涂地，而我们将傲然屹立！"
D.Strings[92113]="森林之魂！自然的守护者！请聆听我们的祈祷！"
D.Strings[92114]="今天，母亲之树重获新生！加尼尔完好如初了！"
D.Strings[92115]="啊哈哈哈哈……！"
D.Strings[92116]="让我们给他们一点重整旗鼓的时间吧，$n。\n\n等他们准备好之后，再来告诉我一声，我就会把你扔进竞技场，开始战斗了。"
D.Strings[92117]="你在看什么呢？没见过海狮吗？"
D.Strings[92118]="对，我是个德鲁伊而且……呃……我大概要保持这个形态一段时间了。$b$b我在破碎海滩周围的海域里巡逻时，一头地狱火掉进水里，正好砸在了我头上。冲击力令我当场昏迷。$b$b等我醒来时，就已经在这里接受护士们的照料了。他们说，过几天我就能有足够的力量变回去了。而现在，我得呆在这个装置里，以防脱水。$b$b帮我个忙，别把这事告诉其他德鲁伊，不然我肯定会被他们笑话一辈子的！"
D.Strings[92119]="我们走花园的入口。"
D.Strings[92120]="这是魔法面具。只要戴上它，你就会穿上一整套魔法服装。"
D.Strings[92121]="我去找莉莉丝。你别惹麻烦。"
D.Strings[92122]="这应该能骗过其他客人，但要避开那些卫兵。"
D.Strings[92123]="你拿到吞噬者之牙了！"
D.Strings[92124]="使用信号灯告诉莉莉丝·月郡你到了。"
D.Strings[92125]="这盏灯似乎经过了改装。它肯定就是让你用来发信号的东西了。"
D.Strings[92126]="向莉莉丝·月郡发信号。"
D.Strings[92127]="没想到您来了。今晚，贵族们齐聚于此，向大魔导师致敬。"
D.Strings[92128]="密探说，艾利桑德本人也会出席。届时，她就将远离力量之源。这机会难得。"
D.Strings[92129]="我们得走边门进入会场……正门的眼线太多了。"
D.Strings[92130]="迄今为止，你做得很好。可你得混进聚会里去。我可以强化你的伪装，给它灌注障眼魔法，把你伪装成贵族。"
D.Strings[92131]="这是你消灭大魔导师的最佳机会。祝你好运！"
D.Strings[92132]="杀了他们，蠢货！我的命运必须实现！"
D.Strings[92133]="我……我需要喘口气！"
D.Strings[92134]="在你救回来的英灵中，有一些想要与你一同对抗克瓦迪尔，夺回自己的荣耀。"
D.Strings[92135]="我们决不能让海拉的爪牙不战而胜。你的忠诚必将得到嘉奖。"
D.Strings[92136]="结束了，吉斯林！说……艾萨拉想对这里做什么？"
D.Strings[92137]="我什么都不会说的！"
D.Strings[92138]="好吧……我想……已经没有什么好问的了。"
D.Strings[92139]="终于死了。"
D.Strings[92140]="远方出现了军团的战舰！全都去哨兵岭！"
D.Strings[92141]="巴伦姆！"
D.Strings[92142]="欢迎你，$n。我很乐意帮忙。"
D.Strings[92143]="欧瑞克说你能和这些灵魂沟通，我们该怎么做？"
D.Strings[92144]="我估错了这件事开始的时间。我需要更多的时间来准备仪式。$b$b同时，我会让这块石头与奥瑞克带来的卷轴产生共鸣。在你的心眼中，某些墓穴会发光。走到那些墓穴前，集中精神感应石块，看看你能否找到正确的墓穴。我们要找到作者本人，而不是他的后裔或祖先。"
D.Strings[92145]="石块黯淡了下去，这个墓穴不对。这可能是作者的亲戚。"
D.Strings[92146]="感应中"
D.Strings[92147]="石块散发出明亮的光芒，就是这个墓穴！"
D.Strings[92148]="嗯，你有事吗？我正忙着准备下一个庆典呢。"
D.Strings[92149]="噢，又是你！我对你所做的一切感激不尽，亲爱的。$b$b我已经听说了那个新晋珠宝商的名声。或许我应该去拜访他一下，订做一件新珠宝……"
D.Strings[92150]="我想跟你谈谈有关珠宝设计图的事。"
D.Strings[92151]="勇士，这片迷雾中有强烈的恶意。召集你最强大的盟友，与克瓦迪尔决一死战吧！"
D.Strings[92152]="因为怕失去灵魂，我最忠诚的维库人也不敢进入迷雾。我欣赏你的勇气，凡人。"
D.Strings[92153]="达拉然中心的塔楼里有通往龙眠神殿的传送门，它可以帮你快速抵达那里。塔胡，再次感谢你。"
D.Strings[92154]="听说你向烈日行者求助，我就来了。但愿我能帮你完成任务，欧瑞克。"
D.Strings[92155]="你来了！我始终忘不了这里……这些痛苦和死亡。好了，我们走。"
D.Strings[92156]="去找到他们。不能让他们打扰阿卡丽！"
D.Strings[92157]="圣光赐予我力量！"
D.Strings[92158]="滚开，肮脏的畜生！"
D.Strings[92159]="你需要治疗吗？"
D.Strings[92160]="我需要一些夏多雷丝绸。你这儿有多余的吗？"
D.Strings[92161]="噢，当然。那边的箱子里就有一些。但我们的补给也很紧张，请不要拿得太多。"
D.Strings[92162]="你知道这附近有裁缝吗？"
D.Strings[92163]="一位来自苏拉玛的织魔者不久前刚来到这里。我想她应该到东边的林荫瀑布去了。"
D.Strings[92164]="我的坐骑们受过圣光的祝福，速度和敏捷都有提升。你绝对找不到比它们更快的坐骑了。"
D.Strings[92165]="我想前往达拉然。"
D.Strings[92166]="去找个安全的地方吧！等这一切都结束之后，我会去找你的。"
D.Strings[92167]="那些触须在使用黑暗魔法免疫攻击。打断它们的法术，你才能攻击！"
D.Strings[92168]="我没时间闲聊，$n。"
D.Strings[92169]="如果不算太麻烦的话，能请你帮我补一下这块布吗？"
D.Strings[92170]="你想要什么，术士？没看见我正忙着吗？"
D.Strings[92171]="这些小鬼是谁召唤来的？"
D.Strings[92172]="你竟敢让我做这么低贱的事？你肯定是在开玩笑。$b$b不是？我明白了。好吧，我已经离开苏拉玛一段时间了，看起来你应该是个炼金师，对吧？$b$b我可以帮助你，但我需要等价的回报。$b$b我想要伊瑟拉的梦境饮剂。这是一种古老的精灵饮料。要想调制它，你需要用到入梦叶和沉睡者之泪的叶子。$b$b后一种植物就长在离这里不远的某些废墟的空地上。拿上这个瓶子，帮我调配出这种饮料，我就帮你这个忙。"
D.Strings[92173]="坦白你的罪行吧！"
D.Strings[92174]="你带来我要的饮剂了吗？"
D.Strings[92175]="这是你要的饮剂。"
D.Strings[92176]="罪行？我唯一的罪行就是成为了全艾泽拉斯最强大的术士！"
D.Strings[92177]="嗯，这些应该足够了。现在，让我看看你那块丝绸。"
D.Strings[92178]="勒斯平想要回他的胸针。"
D.Strings[92179]="来吧，仆从们，帮我战胜这个诬告者！"
D.Strings[92180]="仆从们……？"
D.Strings[92181]="给你。现在，快走吧。"
D.Strings[92182]="进度虽然缓慢，但胜在稳定。我很快就会重新成为宫廷中的宠臣了，这都多亏了你。"
D.Strings[92183]="他就在里面。请尽力救他吧。"
D.Strings[92184]="你想干什么？在这段黑暗的岁月里，我已经没有几个朋友了。如果受到侵害，我可是会反抗的！"
D.Strings[92185]="邪能魔法和你的法术发生了剧烈反应！"
D.Strings[92186]="我们找到了你……而你找到了墓穴。"
D.Strings[92187]="接下来怎么做？"
D.Strings[92188]="我来启动仪式。专心跟幽灵沟通，这位朋友会保护我们的。"
D.Strings[92189]="我用死亡来缓解失败的痛苦。你为何要打扰我？！"
D.Strings[92190]="我读过你的传说。你在哪儿找到它的？"
D.Strings[92191]="看来我必须回答了……旅途将我带到了风暴峡湾的战士之王的墓穴。"
D.Strings[92192]="我们会完成你未竟的任务。"
D.Strings[92193]="重新安息吧，你不必再羞愧了。"
D.Strings[92194]="我跟你去，$n。你帮了我的战士，所以我也该报答你。"
D.Strings[92195]="我在克拉苏斯平台等你。我们可以坐我的狮鹫飞到岛上去。"
D.Strings[92196]="谢谢你，塔胡。我不会忘记你的！"
D.Strings[92197]="这是我的荣幸。我得去虚空之光神殿，把好消息告诉大主教。祝你好运。"
D.Strings[92198]="至于我们，该回达拉然了。我在那里等你！"
D.Strings[92199]="住手，求你了！我愿意写认罪书，如果我的手还没断……"
D.Strings[92200]="我早就预见了你们的到来。命运指引你们来到此地。为了阻止军团，你们想背水一战。"
D.Strings[92201]="我们面临着相似的困境。我窥探了一切可能的未来……而出路只有一条。"
D.Strings[92202]="军团注定会获胜。所有时间流都是这么说的。如果我们反抗，他们就会强夺暗夜井，让我们彻底失去它。"
D.Strings[92203]="我不能让人民挨饿，由于无法汲取它的能量而崩溃。所以我跟他们做了笔交易。"
D.Strings[92204]="最后，我看到了一个军团获胜，而我们苟且偷生的未来。我得抓紧这条命运的丝线。我要不择手段地实现它！"
D.Strings[92205]="你们的死将保证夜之子的未来。来吧！让我们赶紧实现你们的命运吧。"
D.Strings[92206]="你们的时间结束了！"
D.Strings[92207]="我操纵着时间的织线！"
D.Strings[92208]="你们能快得过时间吗？还是会被囚禁在无尽的永恒中呢？"
D.Strings[92209]="时间听从我的召唤！"
D.Strings[92210]="掌控局面的人是我，而不是你们！"
D.Strings[92211]="让时间的浪潮碾碎你们！"
D.Strings[92212]="你们会发现，时间极不稳定。"
D.Strings[92213]="你们只是昙花一现。我的生命要漫长得多！"
D.Strings[92214]="时间又变了，你们的末日正在逼近！"
D.Strings[92215]="我掌控着时间流！你们是赢不了的。"
D.Strings[92216]="时间正在……飞逝！这怎么可能？"
D.Strings[92217]="果然不出我所料。"
D.Strings[92218]="这是注定的结局。"
D.Strings[92219]="你注定要死。"
D.Strings[92220]="这……不可能！我……注定会获胜……"
D.Strings[92221]="这场胜利并不让我欣喜，但这是注定的。"
D.Strings[92222]="我占卜了所有的可能，但没有一个说你们能胜利。我很好奇……"
D.Strings[92223]="你们能击败军团吗？你们会失败吗？你们的时间涡流时断时续。一切都无定数！"
D.Strings[92224]="或许你们能赢。在拯救世界的同时，我们或许也能摆脱被迫签下的可怕协议。"
D.Strings[92225]="该死的命运！我决定赌一把，勇士们。去吧，去面对古尔丹。我会帮你们的，我们或许能拯救所有人。"
D.Strings[92226]="我能看到你的未来，凡人。"
D.Strings[92227]="想知道你确切的死期吗？"
D.Strings[92228]="和我预见的一模一样。"
D.Strings[92229]="我所能看到的越来越少。"
D.Strings[92230]="牺牲是在所难免的。"
D.Strings[92231]="万物都将化为灰烬。"
D.Strings[92232]="我已经预料到你下一步的行动了。"
D.Strings[92233]="万物都将遵从命运。"
D.Strings[92234]="命运背叛了你，凡人。"
D.Strings[92235]="喂？有人吗？我看不见了……"
D.Strings[92236]="呃……不是我。绝对不是我。\n\n就像我跟达拉然的守卫说的那样，可能是菲兹班家的那个姑娘。她和他兄弟一样，总是喜欢召唤一大堆控制不了的恶魔来。"
D.Strings[92237]="快点！我可不想在你浏览货物时被偷袭了。"
D.Strings[92238]="露露贝拉说这是你干的。"
D.Strings[92239]="她当然会这么说了，不是吗？这进一步证明了，姓菲兹班的都不可信！"
D.Strings[92240]="欢迎，烈焰领主！欢迎，欺诈者！"
D.Strings[92241]="你做得很好，阿卡丽。你赢得了我的祝福。"
D.Strings[92242]="吞噬者之牙……它们的力量超乎想象！我是您谦卑的仆人，我的主人！"
D.Strings[92243]="你该面对真正的考验了。使用你的吞噬者之牙，从内部瓦解艾泽拉斯诸国。用它们破碎的残骸铺就我们胜利的大道！"
D.Strings[92244]="我的胸针？呸，我还有大事要操心呢，没功夫搭理勒斯平。算你倒霉，那个胸针已经不在我手上了。$b$b它被范里斯·迅海偷走了。毫无疑问，这又是一次打击我名声的阴谋。这招很高明，因为现在我不能被人看到和他混在一起。$b$b如果你愿意去跟他“谈谈”，拿回胸针，我想我们两个都能从中受益。"
D.Strings[92245]="我看到了你的未来，凡人……"
D.Strings[92246]="我没预见到这个……"
D.Strings[92247]="谁知道这一切什么时候才能结束？"
D.Strings[92248]="它过去了吗？我已经等不及了，等这一切都结束之后，我一定要为我们的部队烘烤美味的食物。"
D.Strings[92249]="它们将以你之名畅饮鲜血！"
D.Strings[92250]="这里的幽灵一直在酿造劣质红酒，它们对饮用者来说无异于毒药。没有它们，阿苏纳会加更美好。"
D.Strings[92251]="这应该能帮忙抑制他们腐化的……灵魂扩散。我要谢谢你。"
D.Strings[92252]="$n！别这样偷偷靠近别人。尤其是在这个时候！"
D.Strings[92253]="小鬼并不是理想的实验品。它们很容易召唤，但对我的实验来说太过脆弱了。"
D.Strings[92254]="感觉到它的力量了吗，萨满？艾萨拉想用来对付我们的水流现在将为你所用。"
D.Strings[92255]="魔杖！"
D.Strings[92256]="来吧，我们回去找其他人。"
D.Strings[92257]="我从没想过自己有一天会渴望大漩涡的和平与安宁。"
D.Strings[92258]="乌拉罗格进入了|cFFFF0000|Hspell:198510|h[山峰形态]|h|r！"
D.Strings[92259]="这是一本书。它漂浮在空中。恶魔为什么要把它留在这里？"
D.Strings[92260]="这是一本书。它漂浮在空中。恶魔为什么要把它留在这里？\n\n它看起来很邪恶，但恐怕不值得你为它浪费时间。"
D.Strings[92261]="作为一个恪尽职守的神圣圣骑士团成员，你必须净化这本污秽的邪能之书。"
D.Strings[92262]="对于牧师而言，这本书是邪恶的，必须被摧毁。"
D.Strings[92263]="我们起飞吧，$n。光羽随时可以出发。"
D.Strings[92264]="法罗纳尔的恶魔想让伊利达雷服从他们的意志。我们决不能让这种事发生！"
D.Strings[92265]="随着伊利达雷的获释，恶魔的威胁得到了控制。你为这片土地做出了巨大的贡献，勇士。"
D.Strings[92266]="这些恶魔比该死的纳迦还要固执！我们必须击退他们！我的守夜人会帮你的。"
D.Strings[92267]="哈！这下他们应该学会别跟守夜人作对了！"
D.Strings[92268]="看到我的同胞沦落至此，我很痛心。他们已经失去了理智，只剩饥渴的欲望。请让他们安息吧。"
D.Strings[92269]="这是一个残酷的任务，但我们必须这么做。我要谢谢你，勇士。"
D.Strings[92270]="纳迦先攻击了我们的城市，现在还想偷走我们的圣物！让他们看看激怒守夜人的下场吧，勇士！"
D.Strings[92271]="这下，那些纳迦应该学会远离阿苏纳了！纳萨拉斯的平民欠你一份人情，$c，守夜人也是。"
D.Strings[92272]="纳迦和恶魔的入侵已经够糟了……现在连龙虾人也来凑热闹！我们得搞清楚是什么黑暗力量逼疯了他们。你愿意帮忙吗？"
D.Strings[92273]="这么说，幕后黑手是那些肮脏的恶魔！感谢你破坏了他们的阴谋。没有了恶魔的煽动，龙虾人的威胁就能平息了。"
D.Strings[92274]="这些长着鳞片的白痴真是恬不知耻！他们竟然敢跑来羞辱纳萨拉斯城？作为守夜人之友，你决不能让这种事继续下去！"
D.Strings[92275]="我欣赏你的勇气，勇士。守夜人会解决剩余的残兵败将。我们欠你一份人情。"
D.Strings[92276]="如果海巨人想和纳迦结盟，那他们就是敌人。勇士，去让他们看看，上层精灵不容小觑！"
D.Strings[92277]="让他们记住这个教训吧。谢谢你，勇士。"
D.Strings[92278]="我把自己坑了……"
D.Strings[92279]="洛克莫拉后仰，准备施放|cFFFF0000|Hspell:188169|h[剃刀碎片]|h|r！"
D.Strings[92280]="鱼鳃怪还活着。$b$b你做好战斗的准备了吗？"
D.Strings[92281]="蛇女巫很强大，但葛拉什会帮忙杀了她的！"
D.Strings[92282]="让我们结束这场战斗吧，葛拉什！"
D.Strings[92283]="他们占领了田野！"
D.Strings[92284]="不惜一切代价保护哨兵岭！"
D.Strings[92285]="我的心血……全完了！"
D.Strings[92286]="我们的庄稼都被毁了！"
D.Strings[92287]="我从来没受过正式的训练，但我知道这个尖头能带来麻烦。"
D.Strings[92288]="看那边！天上！我们的援军来了！坚持住！"
D.Strings[92289]="让我们做个了断吧。"
D.Strings[92290]="感觉到了吗？吞噬者之牙正在撕咬你的血肉！"
D.Strings[92291]="有墨菲斯托斯的指引，我决不会失败！"
D.Strings[92292]="我已从内部击垮了这世界。艾泽拉斯必将崩塌！"
D.Strings[92293]="跟我一起……回归虚空吧……"
D.Strings[92294]="堡垒已经启动了自毁程序。你拿到吞噬者之牙后，就往传送门那儿跑！"
D.Strings[92295]="感觉到头晕目眩了吗？"
D.Strings[92296]="他在用他的生命精华伤害我们！每次攻击都会让他更虚弱！"
D.Strings[92297]="真聪明。他在吸收自身的火焰，想恢复全盛状态。"
D.Strings[92298]="牧师，或许你能用你的法术影响他的心智……骗他熄灭自身的烈焰！"
D.Strings[92299]="啊，你成功了。干得好！"
D.Strings[92300]="瓦莉拉说你回来之后知道该去哪儿找她。你最好不要让她久等。"
D.Strings[92301]="后会有期。"
D.Strings[92302]="跟我来。深海在等着我们！"
D.Strings[92303]="那个畜生想抽取她的灵魂！快，她还有救！"
D.Strings[92304]="跳到艾索雷苟斯的背上以躲避|cFFFF0404|Hspell:209863|h[重力牵引]|h|r！"
D.Strings[92305]="从暴风城来的法师援军！让我们并肩战斗吧！"
D.Strings[92306]="密集阵型！我们要在此背水一战！"
D.Strings[92307]="带我去找最近的恶魔！"
D.Strings[92308]="抱歉，可是“唔”是什么意思？你需要什么吗？"
D.Strings[92309]="噢，呃……我想要些滴定管可以吗？"
D.Strings[92310]="你干嘛不早说呢？附近没有守卫，我们完全可以畅所欲言。"
D.Strings[92311]="我要怎么才能弄到一根大法师的头发呢？！"
D.Strings[92312]="从你想买的东西来看，你是个炼金师吗？$b$b如果是这样的话，你能不能制作一种隐形药水？我记得是叫隐形饮剂来着。$b$b那样他就不会发现你接近了。"
D.Strings[92313]="小心地从卡德加的头上拔一根头发下来。"
D.Strings[92314]="嗷！！这怎么回事？！"
D.Strings[92315]="好像有东西……咬了我的头皮一口。"
D.Strings[92316]="只要你有钱，我什么都能卖。"
D.Strings[92317]="让我看看你有什么。"
D.Strings[92318]="卡德加，怎么了？出什么事了吗？"
D.Strings[92319]="<将你的徽记放在桌子上。>"
D.Strings[92320]="有东西咬了你的头皮？就这样？你还想让我吻你一下作为安慰还是怎么的？"
D.Strings[92321]="骑上这只小鸟，跟我来！去风暴峡湾！"
D.Strings[92322]="给你的命令就在后面的房间里，$G先生:女士;。"
D.Strings[92323]="这边走，$n$G先生:女士;。"
D.Strings[92324]="唔，像你这样有品味的$r应该能从后面的私藏精品中找到你喜欢的东西。"
D.Strings[92325]="欢迎回来，$G先生:女士;。你要不要去贵宾室看看我们新到的货物呢？"
D.Strings[92326]="使用|TInterface\\Icons\\spell_warlock_demonicportal_green.blp:20|t |cFFFF0000|Hspell:111771|h[恶魔传送门]|h|r通过埃瑞丁的屏障！"
D.Strings[92327]="使用|TInterface\\Icons\\spell_warlock_demonicportal_green.blp:20|t |cFFFF0000|Hspell:111771|h[恶魔之门]|h|r来通过艾瑞丁的屏障！"
D.Strings[92328]="达布尔竞技场是各部族互相挑战的地方。快进去证明黯石部族和他们的盟友才是最强大的吧！"
D.Strings[92329]="求你了，小声点！$b$b如果被他们发现我跟你说话的话……他们会杀了我的！"
D.Strings[92330]="我已经帮你清理出了一条道路。如果你动作快一点的话，还来得及逃跑！"
D.Strings[92331]="干得好！你击退了纳迦，并消灭了他们大量的鱼人奴隶！如果你手上有上古神器，一定要带回给我！"
D.Strings[92332]="伟大的表现！感谢你证明了友谊是被高估的。"
D.Strings[92333]="渡鸦有请。"
D.Strings[92334]="|TInterface\\Icons\\ability_fomor_boss_shout:20|t%s开始施放|cFFFF0404|Hspell:209748|h[震耳咆哮]|h|r。快停止施法！"
D.Strings[92335]="而我们将响应暗影的召唤。"
D.Strings[92336]="我从来没想过还能活着逃出来！"
D.Strings[92337]="你一定要阻止暮光之锤！"
D.Strings[92338]="没想到我还能见到我的孩子们！"
D.Strings[92339]="我已经等不及要去洗个澡了！"
D.Strings[92340]="请救救其他人，英雄！"
D.Strings[92341]="小心点。我见过主人……她很强大！"
D.Strings[92342]="你战斗起来，简直像维库人一样勇猛！可能更像维库人幼儿或是老人，但毕竟还是维库人！干得好！"
D.Strings[92343]="你救了我。我不会忘记你的恩情的！"
D.Strings[92344]="这些纳迦有阴谋，他们奴役了附近的鱼人来入侵海滩。不惜一切代价去干掉他们吧！噢，还有，如果你找到了上古神器，一定要带回来让我研究一下。"
D.Strings[92345]="欢迎来到黑鸦竞技场！你是来和朋友或是盟友并肩作战的吗？那么，让他们走吧！在这个竞技场里，你只能孤军奋战。"
D.Strings[92346]="你今天要找什么特别的东西吗？"
D.Strings[92347]="对战？！先对战，然后再吃掉宠物！先打再吃！"
D.Strings[92348]="噢！该吃宠物了！你要去哪儿？我们可以分着吃啊！"
D.Strings[92349]="我们希望由你来完成这个光荣的任务，朋友。来吧。"
D.Strings[92350]="嘿，伙计，那肯定就是迦罗娜提到的那个人。"
D.Strings[92351]="是的，感谢你所做的一切。"
D.Strings[92352]="梅鲁娜跪了下来，将一只银盆放在地上，然后倒了少许散发着柔和光芒的井水进去。"
D.Strings[92353]="等你准备好之后，就把仪式材料包放进水里。"
D.Strings[92354]="伟大的月神，我心中的女神，请用你的光辉祝福这片土地。"
D.Strings[92355]="我代表黑角鹿祝福这口月亮井。"
D.Strings[92356]="我代表羽鬃部族祝福这口月亮井。"
D.Strings[92357]="我代表月语刃豹祝福这口月亮井。"
D.Strings[92358]="|TInterface\\Icons\\spell_shaman_lavaflow.blp:20|t%s开始施放|cFFF00000|Hspell:200404|h[熔岩波]|h|r。快躲！"
D.Strings[92359]="我是不会……投降的！"
D.Strings[92360]="你的痛苦只会滋养梦魇，废物！"
D.Strings[92361]="权杖的力量是属于我的！"
D.Strings[92362]="卡托！很高兴你来了。盾牌就在附近……我有预感！"
D.Strings[92363]="你们会淹死在这里的！"
D.Strings[92364]="大地之环休想篡夺艾萨拉的权柄！"
D.Strings[92365]="我不是来了吗？快找到那面盾牌吧，我们中的一些人还有仗要打呢！"
D.Strings[92366]="卡托是这一带最好的治疗者。幸亏我们不用排队等待他的帮助！"
D.Strings[92367]="|TInterface\\Icons\\Spell_Nature_LightningOverload:20|t你受到了|cFFFF0000|Hspell:204275|h[奥术桎梏]|h|r的影响！"
D.Strings[92368]="我欠你一份大人情，德鲁伊。我不会忘记你的。"
D.Strings[92369]="唔……？"
D.Strings[92370]="你瞧，这可不是我的错。我怎么会知道那些恶魔居然会相信我？"
D.Strings[92371]="我们必须击退他们！集中攻击指挥官！"
D.Strings[92372]="可悲的凡人。你们的世界很快就会完蛋了！"
D.Strings[92373]="他们还没有放松！坚持住！"
D.Strings[92374]="注意看天上，我感觉他们过来了。"
D.Strings[92375]="别再白费力气了，德鲁伊。玛洛恩的礼物属于我们了。现在，去见你的先祖吧！"
D.Strings[92376]="血石准备好了。用的时候小心点，$n。"
D.Strings[92377]="控制、不了。我要、杀！！"
D.Strings[92378]="葛拉什不会让小萨满伤害蛇女士的！"
D.Strings[92379]="再次感谢你给了我为大义而献身的荣耀。现在你应该明白了，我愿意为执行伊利丹大人的计划而付出一切。我们必须不惜一切代价摧毁燃烧军团。\n\n我欠你的太多了，$n。\n\n现在，就由你去完成我们未竟的任务吧，找到萨格里特钥石，带着胜利返回黑暗神殿。\n\n伊利丹大人在等着你。"
D.Strings[92380]="呃，我没想到它们真的会相信我。"
D.Strings[92381]="你的恶魔在犯蠢！你威胁到了我们的位置。"
D.Strings[92382]="痛苦术士擅长使用暗影魔法和疾病来拖垮敌人，然后吸取他们的生命精华来壮大自己。"
D.Strings[92383]="使用召唤虚空行者来召唤你的恶魔仆从。"
D.Strings[92384]="对目标假人使用痛楚。"
D.Strings[92385]="你会给任何敢于挑战你的蠢货带去痛苦。"
D.Strings[92386]="对这个目标假人使用腐蚀术。"
D.Strings[92387]="在使用痛楚和腐蚀术影响目标后，你可以开始抽取他们的生命了。"
D.Strings[92388]="对目标假人使用吸取灵魂。"
D.Strings[92389]="痛楚对敌人造成伤害时，还有几率生成一块灵魂碎片。你能用这些碎片强化新的技能。"
D.Strings[92390]="对这个目标假人使用痛苦无常。"
D.Strings[92391]="你已经学会了所有主要攻击技能，来看看它们该怎么搭配吧！"
D.Strings[92392]="对这个目标假人练习攻击。"
D.Strings[92393]="许多法术都很费法力。但你能够巧妙地回避这一问题。"
D.Strings[92394]="使用生命分流补充你的法力值。"
D.Strings[92395]="有时，你会遭遇多个敌人的围攻，或是单个具有压倒性实力的强大敌人。"
D.Strings[92396]="使用恐惧威吓我的士兵。"
D.Strings[92397]="议会的成员与盟友们，开始召唤吧。"
D.Strings[92398]="我们会不择手段地保护艾泽拉斯的安全……并确保我们在这个世界上的正当地位。"
D.Strings[92399]="但破碎海滩发生的事情让我们别无选择。我们没有时间遮遮掩掩的了。"
D.Strings[92400]="图……图雷……奥萝拉……快跑……"
D.Strings[92401]="你知道那个交易的。只要杀了$G他:她;，我们就算尽到义务了！"
D.Strings[92402]="这无关私人恩怨，朋友。我只是公事公办。"
D.Strings[92403]="好好考虑一下你的选择。"
D.Strings[92404]="无冕者能完成其他人完不成的任务：结束这场战争。"
D.Strings[92405]="我已经准备做出决定了。"
D.Strings[92406]="怎么了？从来没见过能挥剑的公主吗？"
D.Strings[92407]="告诉我你的计划。"
D.Strings[92408]="我打算找回刺杀了莱恩·乌瑞恩国王的那对被诅咒的匕首。迦罗娜把弑君者藏起来是有道理的。它们的力量不容小觑。$B$B我要你帮我找回它们。我们正需要这对传奇匕首来摧毁古尔丹和他的邪恶盟友。"
D.Strings[92409]="听我的，$n。我保证让你得到足以匹配你实力的匕首！"
D.Strings[92410]="弑君者才是消灭燃烧军团的唯一希望。听我的吧！"
D.Strings[92411]="我就快找到一个追杀多年的敌人了。只要你帮把手，我们就能干掉她，拿到她的匕首。"
D.Strings[92412]="在大灾变之后不久，我最得力的一个手下发现了一对金色的匕首，一对前所未见的神兵利器。伊丽扎在触摸到这对匕首那一瞬，看见自己率领着舰队，带领着一群迷失灵魂的水手横扫诸城。$B$B你可能不太相信这种奇谈怪论，但它的确实现了。恐惧之刃已经夺走了无数生命。而现在，我们就要去找它们！"
D.Strings[92413]="乔拉齐对你的评价很高。他是一个很好的朋友。"
D.Strings[92414]="萨格拉斯的爱犬赤喉死亡后，他的恐惧魔王用那头野兽的獠牙铸造出了一对名为吞噬者之牙的匕首。据说这对匕首仍然带有赤喉的毒液。$B$B萨格拉斯将这对獠牙赐给了他最优秀的一个刺客，阿卡丽·影血。从那时起，虽然我们用尽了全力，却一直无法阻止她。"
D.Strings[92415]="你别想再逃跑了，瓦里斯！说出你的主子在哪儿，我或许能给你个痛快！"
D.Strings[92416]="你在这里的时日无多了，恶魔！盟友们，来哨兵岭！"
D.Strings[92417]="|TInterface\\Icons\\Spell_DeathKnight_MindFreeze:20|t%s对葛拉什施放|cFFFF0404|Hspell:209983|h[精神控制]|h|r！"
D.Strings[92418]="那个徽记能表明你是我们中的一员，一定要随身带着它。"
D.Strings[92419]="我的作品永垂不朽……"
D.Strings[92420]="幼虫的体内爬出了一只腐涎劫掠者！"
D.Strings[92421]="干掉那个恶魔，$n！我来照顾奥萝拉。"
D.Strings[92422]="我把我的徽记弄丢了。"
D.Strings[92423]="敲门"
D.Strings[92424]="使用野性形态来提高感知力吧。我敢肯定，我们三个一定能找到那个萨特的踪迹。"
D.Strings[92425]="你利用伊森德雷之泪施放在这里的屏障依然存在。\n\n如果有需要，你可以移除它。"
D.Strings[92426]="移除封印。"
D.Strings[92427]="愚蠢的术士，竟敢召唤你无法控制的东西。"
D.Strings[92428]="末日守卫开始降落了！做好准备！"
D.Strings[92429]="你们必将死在我们手上！"
D.Strings[92430]="Sinu a'manore。算你走运，我正好在附近。你来这鬼地方做什么？"
D.Strings[92431]="看！看来伊格瑞姆是位勇士，是在提尔死后来到这里的。"
D.Strings[92432]="我还以为我的战斗要结束了呢。谢谢你。"
D.Strings[92433]="谢谢你，我要回伊利达雷的营地去养伤了。"
D.Strings[92434]="这些邪恶的恶魔吸取我们的力量，想要摧毁我们的意志。不要放过他们！"
D.Strings[92435]="在克拉戈什那个蛮子和他的监视者进驻幽暗城之后，我们的工作就只能秘密进行了。$B$B所以你当然也就能理解，我为什么会来到这里了。"
D.Strings[92436]="对我来说，被这些家伙活捉简直是奇耻大辱。多亏了你，我会继续战斗下去的。"
D.Strings[92437]="谢谢你救了我，$c。伊利达雷必须搞清楚燃烧军团在法罗纳尔的计划！"
D.Strings[92438]="在这里，谁都听不到你的尖叫！"
D.Strings[92439]="你的神明不是真神的对手，德鲁伊！"
D.Strings[92440]="噢，这倒是提醒了我。趁着你去完成这些简单工作的同时，我也去找了其他必须的组件。"
D.Strings[92441]="我只是在……闭目养神……就一会儿……"
D.Strings[92442]="来，还有很多事要讨论。"
D.Strings[92443]="我只能去铭文师的殿堂完成那些可怕的铭文。不过最终的收获还是物有所值的。"
D.Strings[92444]="这样应该就行了。我觉得我们俩都应该受到表扬，$n。你不觉得吗？"
D.Strings[92445]="投降吧，德鲁伊。你的古老神明……没救了……"
D.Strings[92446]="没用的，德鲁伊。你打不过我们。"
D.Strings[92447]="你的力量微不足道。你所热爱的一切都将与你为敌。面对最深的恐惧吧。"
D.Strings[92448]="谢谢你吸引了他的注意力。"
D.Strings[92449]="赛兰德拉，我们还能夺回神像吗？"
D.Strings[92450]="享受宴会吧。你懂的……就是鬼混。"
D.Strings[92451]="让我们一起宣誓吧！"
D.Strings[92452]="<这个侍从默默无语。>"
D.Strings[92453]="<拿一杯饮料。>"
D.Strings[92454]="这里还关着其他人。如果你还有余力的话，请救救他们。再次感谢你，$n！"
D.Strings[92455]="我选择你作为第六人。"
D.Strings[92456]="我能看出，时代正在改变。  \n\n一个术士，无论他有多么强大，都无法单独对抗燃烧军团。\n\n虽然我从不相信雷特森的所作所为没有私心，但重建议会显然是个正确的决定。\n\n如果你愿意接受我的话，我很荣幸能加入六人议会。"
D.Strings[92457]="只要能恢复菲兹班家族的荣耀，我什么都愿意做。"
D.Strings[92458]="好名声需要许多年的努力才能建立起来，但只要一个错误就能让它毁于一旦。\n\n我的工作已经排得很满了，但我希望为议会服务能帮助我恢复菲兹班家族的荣耀。"
D.Strings[92459]="我们走。传送门就在前面。"
D.Strings[92460]="万灵、元素，比起燃烧军团的力量，它们不过是可悲的泡影。"
D.Strings[92461]="弯腰吧，臣服于萨格拉斯的力量。俯下你们的身体，接受他的恩赐。"
D.Strings[92462]="至高岭的军队、卓格巴尔，甚至是精灵，都将在我们的怒火下灰飞烟灭。"
D.Strings[92463]="拥抱我们的新主人的邪能之力吧。跪下，当你们再次站起时，就将变得空前强大。"
D.Strings[92464]="鲜血图腾的许多成员都投靠了燃烧军团。现在，这些邪能图腾成员正在积蓄力量。我不想让他们逍遥法外。"
D.Strings[92465]="近几年，鲜血图腾跟我们愈发疏远了。可他们居然投靠了燃烧军团？我们完全没想到。"
D.Strings[92466]="远处出现了新的营地！摧毁它们！"
D.Strings[92467]="蠢货！我们的大军遍布这片污秽的土地。我们已经亵渎并腐蚀了你们宝贵的土壤……现在，让我看看你们怎么对付燃烧军团吧。"
D.Strings[92468]="全体散开！四面八方都出现了燃烧军团的腐蚀！"
D.Strings[92469]="不要浪费时间去读它了。"
D.Strings[92470]="你只管签字就行了。"
D.Strings[92471]="就签在这条横线上。"
D.Strings[92472]="这块金属已经扭曲变形了。强壮的铁匠可以将它们锤打恢复正常。"
D.Strings[92473]="干得好，大德鲁伊。把神像送回梦境林地吧，我们在那里等你。"
D.Strings[92474]="有人将一些货物扔在了外面……"
D.Strings[92475]="如果让战士砸坏了，那就太可惜了。"
D.Strings[92476]="如果潜行者偷了它们，其他人肯定会发现的。"
D.Strings[92477]="有人将一些货物扔在了外面……\n\n似乎有魔法手段在监控着它们。"
D.Strings[92478]="叛徒！骗子！凶手！哈缪尔派他的走狗来对我下黑手了吗？"
D.Strings[92479]="卫兵！过来！"
D.Strings[92480]="你还记得是怎么杀害我的吗？还是你已经习惯了屠杀，早就忘了我痛苦的哀嚎？"
D.Strings[92481]="我还记得自己死前，周围都是我信任的人。那时你们得意地冷笑着，看着我咽气。"
D.Strings[92482]="据说复仇的滋味是甜美的，可我只尝到了苦涩。"
D.Strings[92483]="你们似乎变得陌生了。你们真该承受我的怒火吗？"
D.Strings[92484]="现在，猎物变成你了！"
D.Strings[92485]="跑吧，跑吧，小老鼠们！"
D.Strings[92486]="你们无处可逃了！"
D.Strings[92487]="多么可口的小点心！"
D.Strings[92488]="我要用你的骨头装饰我的蛛网！"
D.Strings[92489]="我要用我的利爪碾碎你！"
D.Strings[92490]="我的喙将啄碎你的血肉，蝼蚁！"
D.Strings[92491]="你真的不怕蜘蛛吗？"
D.Strings[92492]="来吧，速战速决吧。"
D.Strings[92493]="这一次，我对你们的诡计早有准备！"
D.Strings[92494]="仁慈？休想！我只要奔涌的鲜血和破碎的尸体！"
D.Strings[92495]="你们竟敢打断上位者的谈话！"
D.Strings[92496]="叛徒，终于想起是怎么杀害我的了吗？"
D.Strings[92497]="暮光之锤已经完了。这个盛极一时的教派被打垮了……四分五裂，群龙无首。"
D.Strings[92498]="狂风刮骨！"
D.Strings[92499]="为大魔导师流尽鲜血吧！"
D.Strings[92500]="我来去无踪，你束手无策！"
D.Strings[92501]="我会加速你的死亡！"
D.Strings[92502]="如果你眨了眼……那就得流血了！"
D.Strings[92503]="我的剑下又多了一条亡魂。"
D.Strings[92504]="出剑如风，无声无息！"
D.Strings[92505]="可我听到了信徒们的祷告……他们在呼唤毁灭！"
D.Strings[92506]="艾利桑德……原谅我！"
D.Strings[92507]="你们的名字将被遗忘。"
D.Strings[92508]="我要庇护这些可悲可怜的小东西，带领他们拥抱自己向往的辉煌命运！"
D.Strings[92509]="深呼吸，拥抱你的命运吧。"
D.Strings[92510]="虚空已经向我展示了黑暗的秘密……能让元素臣服于我的秘密！"
D.Strings[92511]="你已经用不着这条命了！"
D.Strings[92512]="不……我还有很多事要做……回来！"
D.Strings[92513]="我的孩子都要学习这些秘密，我们将一同撕碎这世界！"
D.Strings[92514]="让内心的黑暗吞噬你们！"
D.Strings[92515]="你的清醒是种病！"
D.Strings[92516]="我的孩子学得很快……他们在孜孜不倦地汲取虚空的力量！"
D.Strings[92517]="艾泽拉斯的末日即将降临！很快……构建世界的元素就将带来它的末日！"
D.Strings[92518]="我们要进入这个畜生的巢穴。愿圣光保佑我们！"
D.Strings[92519]="祝你好运……“英雄”。"
D.Strings[92520]="别让女妖之王失望。"
D.Strings[92521]="你被梦魇压制了！击败你内心的恐惧，从噩梦中醒来。"
D.Strings[92522]="我们的领袖完成了一次壮举。"
D.Strings[92523]="黑暗收割议会重生了。"
D.Strings[92524]="在首座的带领下，议会必将再创新高。"
D.Strings[92525]="我们必将解开燃烧军团的秘密！"
D.Strings[92526]="这边！我的时间有限。"
D.Strings[92527]="一扇发光的门……这太明显了吧？这是什么？"
D.Strings[92528]="这块石板说我们要承受这扇门的“审视”。我敢说这件事肯定不简单。你想试试吗？"
D.Strings[92529]="这个魔法灯笼似乎有些不同。它好像漏了。"
D.Strings[92530]="作为一个法师，你早就了解了魔网魔法的复杂结构。你可以将它稍微……改进一下。"
D.Strings[92531]="你很熟悉这个来自精灵构造体的损坏装置。你可以将它改装一下，以提供魔法强化效果。"
D.Strings[92532]="这个魔法灯笼有些与众不同。它好像漏了。\n\n你相信肯定会有人来及时修好它的。"
D.Strings[92533]="这些邪教徒都被暮光蒙蔽了……甘愿避世隐居，躲在黑夜之中。"
D.Strings[92534]="专精野兽控制的猎人与宠物十分默契。他们能在战斗中召唤并强化宠物，同时用远程攻击打击敌人。"
D.Strings[92535]="使用召唤宠物让你的宠物加入战斗。"
D.Strings[92536]="让你的宠物攻击并吸引敌人的注意，为你争取更多时间来进行远程攻击。"
D.Strings[92537]="对目标假人反复使用杀戮命令。"
D.Strings[92538]="现在，来看看你掌握的其他自然力量吧。"
D.Strings[92539]="对目标假人使用凶暴野兽。"
D.Strings[92540]="相信你已经做好行动的准备了。眼镜蛇射击是你主要的远程攻击技能，能在你的宠物吸引敌人注意时打击对方。"
D.Strings[92541]="对目标假人使用眼镜蛇射击。"
D.Strings[92542]="在攻击目标假人时使用狂野怒火。"
D.Strings[92543]="在战斗中，狂野怒火能让你和你的宠物陷入狂怒，在短时间内提高你们的伤害。"
D.Strings[92544]="使用多重射击消灭所有敌人。"
D.Strings[92545]="即使是最伟大的冒险者也会有力不从心的时候。"
D.Strings[92546]="使用假死骗过我的士兵，让他停止攻击。"
D.Strings[92547]="向我证明，你已经掌握了狩猎任何猎物的必要技巧和智慧吧！"
D.Strings[92548]="让我看看你在激战中的勇气和狂热吧！"
D.Strings[92549]="高拉布毫无反应。"
D.Strings[92550]="女主人死了……"
D.Strings[92551]="那个恐惧魔王来杀她。高拉布想帮忙……"
D.Strings[92552]="高拉布失败了……"
D.Strings[92553]="我们找对方向了。继续找吧。"
D.Strings[92554]="他们的藏身处应该就在附近。我闻到东边有萨特的臭味儿。"
D.Strings[92555]="你成功了！这总比变成一堆灰烬强，对吧？"
D.Strings[92556]="泽宁·斯米瑟默默地点了点头，以示感谢。"
D.Strings[92557]="谢谢你。我可以自己返回恐痕裂隙的。"
D.Strings[92558]="大德鲁伊，小心！"
D.Strings[92559]="别担心！我来了！"
D.Strings[92560]="我是不会丢下我的卡亚独自逃走的！"
D.Strings[92561]="她已经尽力了，但敌人太多了。我们该怎么办，加拉图斯？"
D.Strings[92562]="又一块石板！这个勇士还是钢铁之躯，没有被血肉诅咒影响！我们得小心点。"
D.Strings[92563]="我的家！达古尔毁了我的家。我……我不能……我甚至不能……"
D.Strings[92564]="他们没有给我足够的时间来收拾财物。你说它们安全吗？我可不想让那些卓格巴尔来翻检我的私人物品。"
D.Strings[92565]="没时间了。快跑！"
D.Strings[92566]="$n！赞美圣光，你来了！邪恶正在这里横行！"
D.Strings[92567]="这些勇士快要死了。他们已经走不动了了。"
D.Strings[92568]="欢迎你，开门者。你是第一个进来的人。"
D.Strings[92569]="我是提尔的勇士伊格瑞姆！让我看看你能否继承他的盾牌。"
D.Strings[92570]="你来得真及时。再晚一会儿，我今天就没法站在这里感谢你了。"
D.Strings[92571]="这是一桶星光玫瑰茶。它的发酵时间似乎太长了，泡出的茶水浓得让人恶心。"
D.Strings[92572]="作为一名死亡骑士，你正需要这种浓得能喝醒亡者的茶。"
D.Strings[92573]="对于遇难成祥的武僧来说，浓茶不过是一个小小的挑战而已。干杯！"
D.Strings[92574]="这是一桶星光玫瑰茶。它放得似乎太久了，茶水浓得让人恶心。\n\n只是闻一闻都让你差点吐出来。显然它已经放得太久了。"
D.Strings[92575]="那就这样吧。来吧，我的伤员朋友们，让我们看看，我有没有足够的力气把你们送到安全的地方去。"
D.Strings[92576]="我无意辩论，安纳瑞斯。要么合作，要么为敌。你选吧。"
D.Strings[92577]="<叹气>亲爱的……你不懂他是为什么而死的吗？"
D.Strings[92578]="谢谢你，勇士。我的力量恢复了，可以驱散这邪恶魔法了。"
D.Strings[92579]="来吧，英雄！杰斯往这边走了。"
D.Strings[92580]="我一直在等待合格的继承者。来与我一战，我要考验你的心灵！"
D.Strings[92581]="我们会帮你的，恶魔猎手！"
D.Strings[92582]="我得看看，你是否有足够的意志、力量和耐力来掌握这面盾牌。你愿意接受试炼，与我一战吗？"
D.Strings[92583]="我准备好接受你的试炼了，伊格瑞姆。"
D.Strings[92584]="一尊栩栩如生且装饰华丽的苏拉玛贵族雕像。"
D.Strings[92585]="你在采矿方面的经验让你能够加工……以及破坏岩石。"
D.Strings[92586]="你的珠宝加工技术让你能够对这座雕像进行再加工以及“改进”。"
D.Strings[92587]="一尊栩栩如生且装饰华丽的苏拉玛贵族雕像。\n\n它看起来很坚固而且非常沉重。"
D.Strings[92588]="研究"
D.Strings[92589]="我输了！你确实有资格。如果提尔活着，他也会选你为勇士的。真理守护者就交给你了。用它守护好艾泽拉斯吧。"
D.Strings[92590]="我累了。有了合格的继承者，我终于可以卸任了。为真理和正义而战吧，勇士。以提尔之名……"
D.Strings[92591]="从我祖父的祖父那辈起，这里就是我们的家。我们曾经面对过比这个恶棍更加可怕的怪物，我们才不会被吓倒呢。"
D.Strings[92592]="我是不会走的，孩子。不要说了。什么地底之王都不能把我从我的家园吓跑。"
D.Strings[92593]="呸！这是我们的山。就让卓格巴尔的野蛮人来吧。我们拥有万灵的力量，山脉的力量。而他们只有木棍、石头和怒火。"
D.Strings[92594]="好了，$n，你最好还是退后一点。情况有点危险了。"
D.Strings[92595]="现在，加入硫磺岩。"
D.Strings[92596]="最后，也是最终重要的，加入粉尘。"
D.Strings[92597]="成功了！我得说，这是我最完美的杰作。不过德崔斯和他详细的设计图也帮了不少忙。"
D.Strings[92598]="杰斯去侦察了，可恶魔发动攻击并设下了屏障，我们失散了。他应该还在那里！"
D.Strings[92599]="我还能看见你呢。"
D.Strings[92600]="隐身！"
D.Strings[92601]="太好了！很高兴你能得到这面盾牌。我和卡托要去向泰罗索斯复命。如果你要搭顺风车，我的角鹰兽就在外面。"
D.Strings[92602]="有人。很新鲜……又很熟悉。是的……"
D.Strings[92603]="年轮早已预告了你们的到来。漫长的轮回即将结束。"
D.Strings[92604]="来吧，小家伙们。品尝恐惧的滋味！"
D.Strings[92605]="终于，我们可以饱食一番了。"
D.Strings[92606]="|TInterface\\Icons\\Spell_Fire_FelFlameStrike:20|t克洛苏斯使用|cFFFF0404|Hspell:205344|h[毁灭宝珠]|h|r瞄准了|cFFFF0404$n|r！"
D.Strings[92607]="真恶心！！"
D.Strings[92608]="迎接末日的到来。"
D.Strings[92609]="寂灭带来慰藉。接受这恩赐吧！"
D.Strings[92610]="你让那些需要你的人失望了。"
D.Strings[92611]="你的光明熄灭了……"
D.Strings[92612]="拥抱死亡吧，别再挣扎了。"
D.Strings[92613]="大胆！！"
D.Strings[92614]="我的眼睛！"
D.Strings[92615]="看来有人将一个卷轴丢在了这个喷泉里。上面的字迹都被水泡糊了。"
D.Strings[92616]="将绵羊送回鲑鱼溪的羊圈中！"
D.Strings[92617]="作为一个萨满，你可以在元素的帮助下获取上面的信息。"
D.Strings[92618]="为玛尔婆婆标记出黑鸦猎隼。"
D.Strings[92619]="铭文方面的训练让你能够无视那些明显的水渍，解读出卷轴里的知识。"
D.Strings[92620]="看来有人将一个卷轴丢在了这个喷泉里。上面的字迹都被水泡糊了。\n\n它可能曾经很重要，但显然已经在这里泡了太久，无法辨认了。"
D.Strings[92621]="放弃你们的希望吧。"
D.Strings[92622]="血肉的痛苦会消散。真正的折磨永无止境。"
D.Strings[92623]="啊！多么无谓的莽撞！我们有着同一个主人！"
D.Strings[92624]="对我们的每一次攻击，都将被千倍奉还！"
D.Strings[92625]="出去！出去！你们没资格进来！"
D.Strings[92626]="你们还要抵抗吗？还要拒绝这份恩赐吗？"
D.Strings[92627]="恩佐斯……我将回归……尼奥罗萨……"
D.Strings[92628]="你们真以为自己能阻止我吗？愚蠢的孩子！"
D.Strings[92629]="我的血管中流淌着辛萨尼亚的鲜血，她在黑暗虚空中对我低语！"
D.Strings[92630]="暮光龙军团永存，我们的命运即将实现！"
D.Strings[92631]="颤抖吧，凡人！毁灭降临了！"
D.Strings[92632]="谢谢你，大嘴。希望我们后会有期。"
D.Strings[92633]="别担心我。集中精力找洛休斯吧。"
D.Strings[92634]="我们连死亡都能忍受……母亲，我回来……"
D.Strings[92635]="泽宁·斯米瑟默默地鞠了一躬，以示感谢。"
D.Strings[92636]="你将深陷恐惧……"
D.Strings[92637]="谢谢。说实话，我没想到你能从恶魔的陷阱中活下来，波鲁斯。我还以为只剩我和$n了。"
D.Strings[92638]="他们关闭了上层的大门。$n，用你的神圣魔法摧毁定位水晶，这样能帮我们打开通道。"
D.Strings[92639]="它是怎么通过我的女儿们的？！我们要吃光它的内脏！"
D.Strings[92640]="谢谢你。现在，让我们离开这儿！这里不安全！"
D.Strings[92641]="你很勇敢，居然能闯到这里来，但我们得走了！"
D.Strings[92642]="真没想到我会有这么一天……"
D.Strings[92643]="有点小擦伤，但我还活着。谢谢你。"
D.Strings[92644]="加鲁霍德提过，他的大部分配方都是向这里的女祭司学来的。虽然她们已经疯了，我也看不懂那些手稿，但她们的神谕者似乎能读懂。"
D.Strings[92645]="有了占卜球，就能看懂她们的手稿了！这能为我们指明方向，继续加鲁霍德的研究。"
D.Strings[92646]="放松，休伊！放松，小家伙！"
D.Strings[92647]="或许她拥有解开这些知识的钥匙？"
D.Strings[92648]="加鲁霍德可能发现了什么，但我认为他搞错原料了。我们应该试试其它的组合。比如多头蛇蛋和鱼人眼球？"
D.Strings[92649]="对，这些应该能用。我这就让宫廷炼金师开始测试！"
D.Strings[92650]="宴会还不错吧？"
D.Strings[92651]="啊，你肯定就是希尔格林跟我提过的那个外来者。"
D.Strings[92652]="很高兴见到你，莉莉丝夫人。"
D.Strings[92653]="喝一口饮料。"
D.Strings[92654]="唔，你可真迷人，不是吗？"
D.Strings[92655]="好极了！让我们离开这儿。"
D.Strings[92656]="小心点，我感觉前头有一个强大的恶魔。"
D.Strings[92657]="未使用 - 胡说八道。我的作品戴在那些怪物的脖子上能有什么好处？你应该好好跟我们这位朋友学习一下。"
D.Strings[92658]="上来，我们要走了。老休伊不咬……不太咬人的！"
D.Strings[92659]="打她！打死她！"
D.Strings[92660]="恶魔猎手，只要你坚信圣光，就没有什么可怕的！"
D.Strings[92661]="他的名声已经无所谓了。因为他的名声已经臭了。所以你至今还是个学徒。"
D.Strings[92662]="可师父，这人是无辜的！他的名声清白，再给他一次机会吧？"
D.Strings[92663]="你帮了所有人一个大忙。代我向莉莉丝表姐问好。"
D.Strings[92664]="去盾憩岛！"
D.Strings[92665]="别拘束。这里离风暴峡湾还远着呢。"
D.Strings[92666]="|TInterface\\Icons\\Spell_Holy_FistOfJustice:20|t克洛苏斯即将使用|cFFFF0404|Hspell:205875|h[猛击]|h|r摧毁桥梁！"
D.Strings[92667]="我受了重伤，不过$n及时赶到了。"
D.Strings[92668]="圣光来讨伐你了，恶魔！"
D.Strings[92669]="不久前，布莱恩把我介绍给了普斯塔佳。那个矮人真能说……连维库人都能被他忽悠！"
D.Strings[92670]="一个囚犯！她能帮上忙，$n。放了她！"
D.Strings[92671]="|TInterface\\Icons\\Achievement_Boss_YoggSaron_01:20|t一根支配触须面向你并准备施放|cFFFF0000|Hspell:208689|h[大地猛击]|h|r！"
D.Strings[92672]="根据探险者协会翻译出的古代文献，泰坦之击能够凝聚风暴的力量，进行能量攻击。"
D.Strings[92673]="如果这是真的，它或许能重创军团。我们很快就能看到答案了！"
D.Strings[92674]="德鲁伊，梦境的守护者，我的儿女们……"
D.Strings[92675]="我又开始迷糊了，还是长话短说吧。"
D.Strings[92676]="感觉到莎拉达希尔的腐蚀后，我就进入翡翠梦境，想摧毁梦魇的源头。"
D.Strings[92677]="我一路深入。在抵达裂隙时，我才看清他们真正的力量。"
D.Strings[92678]="梦魇会像疾病一样扩散，化脓繁殖。它会将整个艾泽拉斯拉入它的扭曲领域。"
D.Strings[92679]="我看不清返回梦境的道路了。我被困在了自己编织的梦魇中。"
D.Strings[92680]="德鲁伊们，我的时代结束了。现在就靠你们了。"
D.Strings[92681]="Taz'dingo！谢谢你把我救出来！"
D.Strings[92682]="准备好之后，我就把你介绍给普斯塔佳。"
D.Strings[92683]="我是前任大酋长乌兰之女梅拉，我……代表着高岭诸族。"
D.Strings[92684]="别担心，他们的关系其实很铁。"
D.Strings[92685]="我很高兴你响应了我们的召唤。有关邀请你加入的事，我们已经讨论过好几次了。"
D.Strings[92686]="没事……只要你不污蔑我的脸就行！"
D.Strings[92687]="我听说过你不少事。哪怕只有一半是真的，都超出我的想象了。"
D.Strings[92688]="能再见到你真好。我很怀念跟你一起冒险的日子。"
D.Strings[92689]="真是强大！我感觉到这恶魔的精华正在涌入我体内！"
D.Strings[92690]="我为你感到担心，恶魔猎手。现在还不迟！皈依圣光，让它净化你的腐蚀吧！"
D.Strings[92691]="省省你的陈词滥调吧，圣骑士！你们很清楚燃烧军团有多么恐怖。"
D.Strings[92692]="再次感谢你把我们救出来，伙计！"
D.Strings[92693]="我们在找这里的首领，一个名叫卡琳迪斯夫人的艾瑞达。"
D.Strings[92694]="啊，她就在外头指挥邪能卫士装运俘虏呢。我跟她有一笔账要算，所以如果你要去干掉她的话，算我一个。"
D.Strings[92695]="带路吧，先知，我跟着你。"
D.Strings[92696]="来吧，在遭遇更多突袭之前离开这里。"
D.Strings[92697]="这些话让人很不安，先知。"
D.Strings[92698]="我们必须击败暮光之锤，恢复深岩之洲的平衡。"
D.Strings[92699]="塞拉赞恩的仆人被虚空的黑暗之力束缚住了。但愿还不算太迟！"
D.Strings[92700]="太可怕了……必须想消灭这些怪物。"
D.Strings[92701]="暮光雏龙？我还以为暮光龙军团已经灭绝了……"
D.Strings[92702]="法多雷夺走了我的……一切。"
D.Strings[92703]="我是不会坐视恶魔撕碎这个世界的。$B$B夜之子是时候站出来，在艾泽拉斯赢得一席之地了。"
D.Strings[92704]="这个就快被腐蚀了！我们得快一点！"
D.Strings[92705]="我们阻止了仪式，可我担心更大的麻烦还没到来……"
D.Strings[92706]="我们得回到塞拉赞恩那儿去，把这里的事告诉她。"
D.Strings[92707]="猎物近在眼前了！我们得抢在她布置完防御措施前出击！"
D.Strings[92708]="请跟我一起举杯，欢迎我们的新晋影行者，无冕者即将迎来新的纪元！"
D.Strings[92709]="这酒好像有问题……"
D.Strings[92710]="梵妮莎……？"
D.Strings[92711]="噢！你是谁？！"
D.Strings[92712]="直接……杀了我吧。"
D.Strings[92713]="跟我来。莉莉丝想跟你谈谈。"
D.Strings[92714]="她还想继续向我鼓吹她那背叛的理想吗？很好，我们走吧。"
D.Strings[92715]="你比我想得要顽强些。我还打算在某个……僻静角落里干掉你呢。"
D.Strings[92716]="来，让我看看大名鼎鼎的“传奇斗士”的本事！"
D.Strings[92717]="不！我那么拼命，绝不能被你这种人破坏！"
D.Strings[92718]="噢，我的头……瓦莉拉，你没事吧？"
D.Strings[92719]="瓦莉拉点了点头。"
D.Strings[92720]="我没能说服鲜血图腾部族协助我们。但愿洁儿的影响力能管用。"
D.Strings[92721]="我刚从鲜血图腾部族的地盘回来，可我听说你帮助了我的同胞。\n\n我很羞愧，像你这样的外来者竟然比我们自己的兄弟部族更愿意帮助我们。"
D.Strings[92722]="我们需要你帮忙和地底之王谈判。"
D.Strings[92723]="洁儿想跟这些野蛮人谈判？大胆的行动，但恐怕也很愚蠢。"
D.Strings[92724]="大地母亲在上！我就怕会这样……暮光龙军团又回来了！"
D.Strings[92725]="好好照顾它。"
D.Strings[92726]="别那么莽撞！"
D.Strings[92727]="我们的任务就快完成了……别让这些多管闲事的萨满干扰仪式！"
D.Strings[92728]="挖地三尺！找到他们！"
D.Strings[92729]="不留活口，大魔导师就是这么说的！"
D.Strings[92730]="月之守卫完蛋了！杀光他们。"
D.Strings[92731]="血洗这座堡垒。一个活口都不要放过。"
D.Strings[92732]="我听说了你为河鬃部族所做的一切。$b$b在达拉然第一次见到你时，我可没想到你会帮上我们这么大的忙。$b$b这真是太感谢你了。"
D.Strings[92733]="扫清他们留在这里的低劣魔法。月之守卫已经完了。"
D.Strings[92734]="为了纳萨拉斯！"
D.Strings[92735]="把这些长鳞片的恶棍赶回去！"
D.Strings[92736]="不要放过那个纳迦！"
D.Strings[92737]="面对守夜人的怒火吧！"
D.Strings[92738]="打倒肮脏的纳迦！"
D.Strings[92739]="纳迦无休止的进攻已经让我们的士兵疲惫不堪了。勇士，去召集守夜人，把纳迦赶回他们的深海老家去！"
D.Strings[92740]="感谢你的帮助，勇士。你让我的人暂时摆脱了纳迦的威胁。"
D.Strings[92741]="|TInterface\\Icons\\INV_Misc_Bell_01:20|t %s收到警告，得知了你的存在！"
D.Strings[92742]="|TInterface\\Icons\\INV_Misc_Bell_01:20|t警钟已经敲响！一队援军加入了战斗！"
D.Strings[92743]="那个小鬼国王为主人端过盘子。他将为你送上三大谎言。"
D.Strings[92744]="她的内心空虚，我们已占据了她的心灵。"
D.Strings[92745]="钻石的王者已沦为棋子。"
D.Strings[92746]="在第三次死亡时，她将我们带进了这个世界。"
D.Strings[92747]="他的力量来自大地。那是我们的土地，我们的力量。"
D.Strings[92748]="它的表面熊熊燃烧，遮掩了背后的阴影。"
D.Strings[92749]="谢谢，现在，是我报答你的时候了！"
D.Strings[92750]="去找到他，溺死在星辰大海中吧。"
D.Strings[92751]="五把钥匙开启了我们的道路。五把火炬照亮了我们的前途。"
D.Strings[92752]="血肉是他的恩赐。他才是真正的造物主。"
D.Strings[92753]="渡鸦之主将转动钥匙。"
D.Strings[92754]="只要你一声令下，我就能启动仪式。$B$B那对双胞胎不会喜欢被召唤的，所以做好战斗的准备吧。$B$B一旦她们被削弱，就使用血石奴役她们。$B$B你准备好了吗？"
D.Strings[92755]="的确。你得露一面。"
D.Strings[92756]="快使用血石！"
D.Strings[92757]="欢迎来到莫纳斯的神秘庄园！我这里有着来自大分裂前后的各种神秘古董。"
D.Strings[92758]="他坚持要求你归还，如果有必要的话，我会使用暴力。"
D.Strings[92759]="朋友，枯法者在疯狂攻击繁育地。我们被俘虏的幼龙都陷入了对法力的饥渴！"
D.Strings[92760]="把枯法者偷走的法力水晶带回去，用它们唤醒雏龙。快行动吧，朋友！"
D.Strings[92761]="你用行动保护了阿苏纳蓝龙的未来。随着枯法者的威胁平息，你为我们争取到了休养生息的时间。"
D.Strings[92762]="你真勇敢，$n。"
D.Strings[92763]="我欠你一份人情。"
D.Strings[92764]="这些绷带……谢谢你。"
D.Strings[92765]="我……我必须回到战场上去！"
D.Strings[92766]="有点头晕，但我会没事的。"
D.Strings[92767]="你将加入永恒的狩猎！"
D.Strings[92768]="啊，我们的英雄到了。如此执着，如此自信。但这种傲慢只会毁了你们！"
D.Strings[92769]="你们忘了破碎海滩的耻辱了吗？你们的宝贝国王是怎么在我面前卑躬屈膝，支离破碎的？你们也想像他一样，像条狗一样呜咽求饶吗？"
D.Strings[92770]="你们忘了破碎海滩的惨败了吗？你们强大的酋长是怎么像头猪一样被开膛破肚的？你们也要像他那样慢慢死去，被邪能逐渐吞噬，并哀嚎着祈求速死吗？"
D.Strings[92771]="可悲的联盟必将化为尘埃。那个小鬼国王将卑躬屈膝地侍奉我……你们都一样！"
D.Strings[92772]="可悲的部落必将化为尘埃。最终，死亡将统治这世界，而下一个就轮到她了。"
D.Strings[92773]="伊利丹的躯壳是个理想的容器，它将承载主人的荣耀。萨格拉斯必将崛起，我们将观赏这世界熊熊燃烧！"
D.Strings[92774]="谁都休想玷污督军的战利品！"
D.Strings[92775]="最后的决战即将上演！"
D.Strings[92776]="你们休想阻止仪式！"
D.Strings[92777]="一定要把容器准备好！"
D.Strings[92778]="你们将一个一个地倒下！"
D.Strings[92779]="你应该跪下的！"
D.Strings[92780]="投降吧！我或许还能饶你一命！"
D.Strings[92781]="这个世界的勇士们都倒下了！"
D.Strings[92782]="别再让人打扰我了！我还有正事呢……"
D.Strings[92783]="来吧，臣服于我！"
D.Strings[92784]="为萨格拉斯而战！"
D.Strings[92785]="帮我解决这些爬虫！"
D.Strings[92786]="以主人的名义杀了他们！"
D.Strings[92787]="我要把你烧成灰烬！"
D.Strings[92788]="你们竟敢深入梦魇？愚蠢的凡人！在这里，我无所不能。在这里，我就是主宰！"
D.Strings[92789]="我的意志坚不可摧！"
D.Strings[92790]="你休想逃出我的掌心！"
D.Strings[92791]="见证……我获得的力量吧！"
D.Strings[92792]="畅饮荣耀的美酒吧！"
D.Strings[92793]="烈火焚心！"
D.Strings[92794]="尝尝主人的力量吧！"
D.Strings[92795]="梦魇已经腐蚀了巨龙、神祇和传奇。你也将干脆利落地倒下！"
D.Strings[92796]="风暴会让死亡降到你们头上！"
D.Strings[92797]="永远不要低估一位术士大师！"
D.Strings[92798]="又有梦游者加入梦魇了！"
D.Strings[92799]="你们输了，英雄！仪式即将完成！但我要先放纵一下……杀了你们！"
D.Strings[92800]="你们休想再干扰我！"
D.Strings[92801]="你们怎么还不死？为何还要抵抗？"
D.Strings[92802]="永恒的沉眠！永恒的疯狂！"
D.Strings[92803]="这将是你们共同的命运！"
D.Strings[92804]="胜利正在向我招手！"
D.Strings[92805]="你们的灵魂属于我了，它们将永远沉沦在梦魇之中！"
D.Strings[92806]="那些幽灵干扰了气流！恐怕得用老办法来阻止他们了！"
D.Strings[92807]="我的胜利早已注定。梦魇的力量正在滋长！"
D.Strings[92808]="不！我绝不允许！"
D.Strings[92809]="他们是我的，伊瑟拉！你救不了他们！"
D.Strings[92810]="拥抱梦境吧，勇士们！它能拯救你们！"
D.Strings[92811]="让梦境洗去他的黑暗吧！"
D.Strings[92812]="梦境完了！现在只有梦魇！"
D.Strings[92813]="不要挣扎了！清醒点，面对末日吧！"
D.Strings[92814]="我的任务……还没……完成……"
D.Strings[92815]="梦魇是不会……被……遗忘的……"
D.Strings[92816]="我要切开你的心脏！"
D.Strings[92817]="我要让你远离现实世界！"
D.Strings[92818]="该切断你与凡人生活的最后联系了！"
D.Strings[92819]="感受梦魇的毁灭吧！"
D.Strings[92820]="我要一一踏平你们！"
D.Strings[92821]="该碾碎你们的梦境了！"
D.Strings[92822]="屈服于疯狂吧！"
D.Strings[92823]="臣服于梦魇吧！"
D.Strings[92824]="你们的梦境属于我了！"
D.Strings[92825]="你的折磨将永无止境！"
D.Strings[92826]="英雄们！勇士们！来听我说！"
D.Strings[92827]="梦魇就是一颗急于吞噬翡翠梦境的毒瘤。如果萨维斯成功了，他的腐蚀就将吞噬艾泽拉斯，制造出活生生的梦魇。"
D.Strings[92828]="这场胜利修复了梦境，保护了你们的世界。萨维斯一伙不会罢休，但至少这次他们无法得逞。"
D.Strings[92829]="为了表彰你们的英勇，我将开放翡翠梦境的圣洁核心。在感受这生命精华时，请记住是你们今天的义举保护了它。"
D.Strings[92830]="我来自波涛起伏的大海。潮汐之王响应了你的召唤，大地之环的先知。"
D.Strings[92831]="异端！我要以沃伦德的名义杀了你！"
D.Strings[92832]="是时候使用荒野神像召唤出伟大的玛洛恩了。我从没想过能亲眼见到这位伟大的古老神祇。这个时刻足以让我们传颂数个世纪。"
D.Strings[92833]="我的选民将永远保护我！"
D.Strings[92834]="你们不配得到泰坦之击的力量！"
D.Strings[92835]="我受够了！让黑暗吞噬你们吧！"
D.Strings[92836]="现在只剩你我了，小牧师！圣光也救不了你。"
D.Strings[92837]="看来加鲁霍德的配方并不完整。我的炼金师们认为需要加入一些胆汁作为平衡。它含有一些非常有益的成分！"
D.Strings[92838]="帮我从高地找些熊肝来。记住，越肥越好！噢，还需要一些角鹰兽蛋。换换花样总是不错的。"
D.Strings[92839]="太好了！我们距离治愈诅咒只有一步之遥了！谁能想到，加鲁霍德那个酒鬼会掌握着我们重获自由的钥匙？"
D.Strings[92840]="什么声音？纳拉诺斯！你要再放走一个囚犯，我就把你绑在石头上，烂死在这儿！"
D.Strings[92841]="你真这么蠢？居然自以为能挑战一位燃烧军团的艾瑞达女巫？"
D.Strings[92842]="让我的黑暗吞噬你！"
D.Strings[92843]="不！我的法杖在吸收圣光！该死的牧师，该死的魔法！"
D.Strings[92844]="我的法杖……感应到了圣光！这怎么……不！！"
D.Strings[92845]="那边，上面！那扇门散发着和这些幽灵一样的能量。"
D.Strings[92846]="我来驱散符文。保护我！"
D.Strings[92847]="干得好，普斯特！"
D.Strings[92848]="强盗！站住！"
D.Strings[92849]="你们的贪婪玷污了这片圣地。滚出去！"
D.Strings[92850]="仁慈的先知！那是什么！？"
D.Strings[92851]="肮脏的凡人在主人的传送门附近做什么？我要把答案从你们的灵魂里榨出来！"
D.Strings[92852]="萨尔玛！我的萨尔玛呢！？"
D.Strings[92853]="我丈夫！他还好吗？"
D.Strings[92854]="我要让这座湖泊变得更美……"
D.Strings[92855]="你们管这叫劳动？我要让主人扒了你们的皮！"
D.Strings[92856]="如果再让我发现你偷喝试剂，我就把你交给主人！"
D.Strings[92857]="你好。你是来加入苍穹奇法会的吗？"
D.Strings[92858]="就是这样！干掉一个，还剩两个！"
D.Strings[92859]="他们的力量在增长。做好准备！"
D.Strings[92860]="看！门开了！"
D.Strings[92861]="别让他们进入大厅！仪式就快完成了！"
D.Strings[92862]="你们两个可以待会儿再吵！让我们先离开这个地方！"
D.Strings[92863]="作为一名元素萨满，你能够和古老的灵体沟通，号令原始的元素之力。"
D.Strings[92864]="对目标假人使用烈焰震击。"
D.Strings[92865]="对目标假人使用熔岩爆裂。"
D.Strings[92866]="对目标假人使用闪电箭。"
D.Strings[92867]="小心点，我的朋友——他们的构造体似乎完全不受我的符文影响。"
D.Strings[92868]="大地之环的萨满，将我们的力量联合起来！"
D.Strings[92869]="我们以艾泽拉斯之名召唤潮汐之王耐普图隆！"
D.Strings[92870]="如果不是因为大嘴，我肯定已经死了。"
D.Strings[92871]="请再为我施放一个隐身法术。"
D.Strings[92872]="倾听我们的请求，响应大地之环的召唤吧！"
D.Strings[92873]="你可以通过达拉然巨坑的传送门前往那里。我会带着其他部队在那里等你。"
D.Strings[92874]="所有附魔师都对魔法有着深刻的理解。这个魔法经过调整后，应该会对你有所帮助。"
D.Strings[92875]="泰坦之击就在附近。"
D.Strings[92876]="天呐！这个沃伦德肯定很痴迷泰坦遗物！"
D.Strings[92877]="看那边……一个机械侏儒！布莱恩说过这些东西。它或许能帮我们找到泰坦之击！"
D.Strings[92878]="作为一个皮匠，你认出了这种鞣酸。让它暴露在夜晚的空气中，应该就能将它彻底变成废物了。"
D.Strings[92879]="让我看看……把这个插在这里……重组能量块……"
D.Strings[92880]="XR9-47号远程继电监控器激活。系统状态：受损。正在重启。请稍候。"
D.Strings[92881]="伊芙瑞娜，找到你兄弟，去墓穴集合。"
D.Strings[92882]="他们正在苏醒！"
D.Strings[92883]="以大地母亲的名义！"
D.Strings[92884]="回到深海去吧，厄祖玛特。这是你主人的命令！"
D.Strings[92885]="大地之环的萨满，你发出了召唤，但我清楚要面临的威胁。"
D.Strings[92886]="大地震击是你最强大的法术之一。它会消耗漩涡值。你的其他攻击技能会产生这种资源。"
D.Strings[92887]="对这个目标假人使用大地震击。"
D.Strings[92888]="燃烧军团来了。你们应该好好利用自己剩余的时光，凡人。"
D.Strings[92889]="愚蠢的凡人！元素领主之间从来不存在同盟！"
D.Strings[92890]="你有什么建议，小兽人？让我独自抵抗燃烧军团？"
D.Strings[92891]="那就过来吧。让我看看这个勇士！"
D.Strings[92892]="啊，没错……我以前见过你！你确实有点实力……但要独自击败燃烧军团还不够。"
D.Strings[92893]="你想把人变成青蛙吗？妖术能帮你实现这个愿望！"
D.Strings[92894]="把我的士兵变成青蛙！"
D.Strings[92895]="你经常要在战场上面对多个敌人。幸好，你有一个强大的技能，叫做闪电链。"
D.Strings[92896]="使用闪电链同时对付数个敌人。"
D.Strings[92897]="很久之前，元素们曾经并肩战斗过……或许我们还有希望。"
D.Strings[92898]="很好，萨满，我会加入这场救世之战。"
D.Strings[92899]="你受伤了，但这对你来说根本不是问题。"
D.Strings[92900]="使用治疗之涌恢复你所有的生命值。"
D.Strings[92901]="系统状态：正常。按照新线路将指令发送到造物者的控制台。"
D.Strings[92902]="造物者？不……千万别是他……"
D.Strings[92903]="哼！难道你要投靠萨格拉斯，做他的奴隶？可怜虫！"
D.Strings[92904]="你不必孤军奋战。大地之环与你同在，我们还会召集其他元素领主加入！"
D.Strings[92905]="铜须？啊，你来了！记录显示这个单位从我的实验室被偷走后，已经关闭上千年了。"
D.Strings[92906]="最后说一次，我不是布莱恩！"
D.Strings[92907]="小锅匠，泰坦之击呢？"
D.Strings[92908]="那把枪在那儿？真稀奇！遥测启动……破碎群岛……维库墓穴……啊，我明白了！"
D.Strings[92909]="噢，星辰在上！对，就是它！旋钮被调整到了特定频率。我只要发送一个信号，就能……"
D.Strings[92910]="我们还有希望，猎潮者。如果元素能联手……"
D.Strings[92911]="你的剥皮技术让你无视那些水渍，认出了抄写这个法术所用的牛皮纸。对你来说，要释放其中的魔法应该不是问题。"
D.Strings[92912]="这个平民似乎被邪能魔法打伤了……邪能在烧灼着他的伤口，能够抵抗普通的治疗手段。"
D.Strings[92913]="你的急救技能让你了解如何才能防止这个人死亡。"
D.Strings[92914]="虽然不是最佳选择，但你的裁缝技术让你懂得包扎这些伤口，并至少让这个平民的伤势能够稳定下来。"
D.Strings[92915]="这个平民似乎是被邪能魔法打伤的……被邪能灼伤的伤口似乎会抵抗普通的恢复手段。\n\n由于没有好的办法来帮助这位平民，你只能带着遗憾继续前进了。"
D.Strings[92916]="这个平民似乎是被邪能魔法打伤的……被邪能灼伤的伤口似乎会抵抗普通的治疗。\n\n由于没有好的办法来帮助这位平民，你只能带着遗憾继续前进了。"
D.Strings[92917]="不在这下面？那好吧，用梯子去检查一下上面的书桌吧。"
D.Strings[92918]="别放弃希望，$n。继续研磨，检查你的墨水中的特殊成分。只要我们精诚合作，就一定能弥补书中的缺失。"
D.Strings[92919]="准备去死吧，凡人！"
D.Strings[92920]="你的死仅仅是个开始！"
D.Strings[92921]="我们的血管中流淌着萨格拉斯的力量！"
D.Strings[92922]="以萨格拉斯的威能之名！"
D.Strings[92923]="卫兵——干掉这些不速之客！"
D.Strings[92924]="这些凡人干扰了我们的仪式！立刻解决他们。"
D.Strings[92925]="洛希恩古老的土地早已荒废。现在，野兽在我们先祖的土地上横行。我不能让这种情况继续下去！请让一切回归正轨吧，勇士。"
D.Strings[92926]="我要谢谢你。多亏了你，洛希恩的岩石终于恢复宁静了。"
D.Strings[92927]="|TInterface\\Icons\\Ability_Rogue_EnvelopingShadows:20|t伊格诺斯即将完成|cFFFF0000|Hspell:210781|h[黑暗重构]|h|r！"
D.Strings[92928]="卓格巴尔要来了？"
D.Strings[92929]="可……这是我们的土地。"
D.Strings[92930]="什么？地底之王要来了？噢，不！"
D.Strings[92931]="我们得赶紧离开这儿！"
D.Strings[92932]="啊！冲破这阵风！"
D.Strings[92933]="撤离？可我们已经这片土地上耕耘了好几代了。"
D.Strings[92934]="呸！卓格巴尔是赢不了的。他们只是一群野蛮人。"
D.Strings[92935]="卓格巴尔是不会到地表上来的。他们不会这么做的。"
D.Strings[92936]="啊，你来了。我们以极高的代价守住了这里。不能这样下去了，必须取回白银之手，破坏墓穴的入口。"
D.Strings[92937]="我会完成仪式，解放战锤，并摧毁这座墓穴。但我们得快点。我感觉这墓穴中仍有邪气。"
D.Strings[92938]="我们要带一支小分队打头阵。你准备好了就说一声。"
D.Strings[92939]="墓穴里可能仍然很危险。那些该死的入侵者！如果你还能坚持下去，我们就能清出一条通道。"
D.Strings[92940]="我做好进入墓穴的准备了。"
D.Strings[92941]="跟我说说拉图修斯的事吧。"
D.Strings[92942]="你还记得大分裂之前的苏拉玛吗？"
D.Strings[92943]="我们在寻找一件强大的神器。你对此知道些什么？"
D.Strings[92944]="洁儿！你回来了。感谢万灵！"
D.Strings[92945]="摧毁？"
D.Strings[92946]="对。这位英雄护送了我们，可我们得说服其他部族回来帮忙。我们不能再分裂下去了。"
D.Strings[92947]="就是它！任务完成了！"
D.Strings[92948]="小偷！你们的脑袋将装点我的宝座！"
D.Strings[92949]="挑战我的人都得死。"
D.Strings[92950]="肉体凡胎不配执掌风暴之力！"
D.Strings[92951]="我停不了手了！我发誓！"
D.Strings[92952]="我感觉很虚弱……"
D.Strings[92953]="我……这是我吗？我又恢复了吗！？"
D.Strings[92954]="他们知道我们的秘密！我们的思维已经不受自己控制了！"
D.Strings[92955]="我从来都没这么害怕过……"
D.Strings[92956]="好无助……我在哪儿？"
D.Strings[92957]="以燃烧军团的威能之名！"
D.Strings[92958]="脆弱的凡人！你们的末日已经降临了！"
D.Strings[92959]="你的灵魂将受到折磨！"
D.Strings[92960]="来吧，为翡翠梦境而战！"
D.Strings[92961]="盟友们！过来！"
D.Strings[92962]="大自然也将与你为敌！"
D.Strings[92963]="我们必须击退梦魇！"
D.Strings[92964]="攻击腐化者！"
D.Strings[92965]="战斗开始了！"
D.Strings[92966]="高贵的古树，踏平一切邪恶！"
D.Strings[92967]="生命之种，净化这片林地中的邪恶！"
D.Strings[92968]="梦境的勇士，用翅膀和利爪出击！"
D.Strings[92969]="亲爱的女儿，为我恢复力量！"
D.Strings[92970]="圣藤，缠住腐蚀者！"
D.Strings[92971]="死吧，腐蚀者！"
D.Strings[92972]="翡翠梦境长存！"
D.Strings[92973]="你的死巩固了梦境！"
D.Strings[92974]="你们的梦魇到此为止了！"
D.Strings[92975]="污染必须被净化！"
D.Strings[92976]="梦境方能保存！"
D.Strings[92977]="你们的死让我悲痛，可我不能让梦魇获胜。"
D.Strings[92978]="父亲！我……让你失望了……"
D.Strings[92979]="我的学生……你……怎么能？"
D.Strings[92980]="玛法里奥！不，这不可能！我曾祈祷我的学生永远不要沉沦黑暗的梦魇。可你却站在这里，给圣洁的梦境蒙上了阴影！"
D.Strings[92981]="骗子！黑暗的仆从！虽然不想毁了你，可我有责任保护梦境。Andu-falah-dor！"
D.Strings[92982]="傲慢的小鬼。尝尝我的利刃吧！"
D.Strings[92983]="玛法里奥，是你吗？"
D.Strings[92984]="啊！别再骗我了！梦魇必须终结！"
D.Strings[92985]="帮帮我，兄弟姐妹们。让我们共同进退！"
D.Strings[92986]="你们有着高贵的心！怎么可能？难道黑暗侵蚀了……我的心灵？"
D.Strings[92987]="我是横行诸野的灾星，破碎群岛的魔王！"
D.Strings[92988]="父亲？父亲，是你吗？"
D.Strings[92989]="遵命，父亲！我不会辜负你的！"
D.Strings[92990]="你是……控制不了……"
D.Strings[92991]="欺诈者！你腐蚀了梦境的仆从！"
D.Strings[92992]="渣滓！污染者！"
D.Strings[92993]="这是何等的邪恶，玛法里奥？"
D.Strings[92994]="恶棍！你们毒害了梦境的孩子！"
D.Strings[92995]="我净化了一个！他们现在会为我们而战了！"
D.Strings[92996]="让梦魇得到净化吧！"
D.Strings[92997]="我不会放弃你，大导师！"
D.Strings[92998]="导师，我们是为了拯救他们，拯救你而战！"
D.Strings[92999]="塞纳留斯！看到导师被扭曲，我很心痛。如果我们能制服他，我愿意用全部力量净化萨维斯注入他灵魂内的邪恶力量。"
D.Strings[93000]="这是真的吗？我们的导师被萨维斯的谎言所蒙蔽，以为我们才是污染之源！"
D.Strings[93001]="你被骗了，我的老师！萨维斯扭曲了你的感知！求你，让我们为你净化他的邪恶！"
D.Strings[93002]="是的，塞纳留斯！我们来救你了！"
D.Strings[93003]="住手！他开始意识到真相了！"
D.Strings[93004]="塞纳留斯！别听他的！"
D.Strings[93005]="结束了！塞纳留斯被击败了，可我的导师还活着。现在我要集中力量净化他。"
D.Strings[93006]="萨维斯就在前面的裂隙里，那是梦魇的真正核心。如果有可能，我很想与你们并肩作战，可我……不能进去。"
D.Strings[93007]="我与梦境的联系赋予了我强大的力量……可这也让我无法抵抗裂隙中的黑暗。我曾窥视过它，知道这是真的。只要踏进那里，我就会迷失……像塞纳留斯一样。"
D.Strings[93008]="去吧，消灭梦魇之王。只有这样，梦境才能恢复……艾泽拉斯才能得救。"
D.Strings[93009]="他们在欺骗你！"
D.Strings[93010]="对，我的儿子！我是你父亲玛洛恩！别相信入侵者！快将他们抹杀在梦境里！"
D.Strings[93011]="|TInterface\\Icons\\Spell_Fire_FelFire:20|t克洛苏斯的|cFFFF0404|Hspell:206677|h[邪能烙印]|h|r瞄准了|cFFFF0404你|r！"
D.Strings[93012]="再游一段路就可以进入墓穴了。"
D.Strings[93013]="看，提尔之墓，由强大的……等等！这些怪物竟敢亵渎墓穴？！"
D.Strings[93014]="不可容忍！消灭这些怪物！"
D.Strings[93015]="还好！行了，$n，去拿泰坦之击，我们离开这儿。"
D.Strings[93016]="你的使命结束了，该轮到我了！"
D.Strings[93017]="看到这种破坏威胁到了白银之手的安息之地，我很痛心。"
D.Strings[93018]="这件武器的核心将为我注入泰坦之力。维库人都将臣服于我……他们的新神王！"
D.Strings[93019]="军团……必胜！"
D.Strings[93020]="快去通知大使！"
D.Strings[93021]="你休想阻止我们的计划！"
D.Strings[93022]="把你的手放在神像上吧，我们要开始仪式了。"
D.Strings[93023]="我要谢谢你们。很少有人能做到这样的壮举。"
D.Strings[93024]="是谁胆敢挑战真理追寻者？！我要把你们冻成冰块！"
D.Strings[93025]="寒冰护体！"
D.Strings[93026]="你属于燃烧军团了！"
D.Strings[93027]="你们不可能……击败我们所有人……"
D.Strings[93028]="你的灵魂属于燃烧军团了！"
D.Strings[93029]="让我们的力量碾碎你！"
D.Strings[93030]="去死吧，凡人渣滓！"
D.Strings[93031]="我要碾碎你们！"
D.Strings[93032]="又有骨头玩儿了！"
D.Strings[93033]="我不过是……万分之一……"
D.Strings[93034]="你的精华属于我了！"
D.Strings[93035]="凡人的血肉……太软弱了！"
D.Strings[93036]="我已经……尽力了。"
D.Strings[93037]="把你们的秘密告诉我！"
D.Strings[93038]="把你们灵魂的秘密都告诉我！"
D.Strings[93039]="你们的世界必将陨落！"
D.Strings[93040]="前进，勇士们！古尔丹动摇了！他死定了！"
D.Strings[93041]="他们休想再前进了！"
D.Strings[93042]="为艾泽拉斯和你们的亲人而战！"
D.Strings[93043]="我们一定能阻止他！相信我！"
D.Strings[93044]="这是我们的世界，不是军团的！"
D.Strings[93045]="嘶。让它乖乖待在牢笼里吧。它要一直待到主人想起它为止！"
D.Strings[93046]="希望消逝了，灵魂很快也将消逝！你将属于主人。"
D.Strings[93047]="糟了，糟了！你们俩快到奥杜尔的车间来见我。我们有件麻烦事要解决！"
D.Strings[93048]="<种一朵花？>"
D.Strings[93049]="噢，真走运！泰坦之击的力量为这个传送台充了能。我可以重新设定它的目的地……成了！"
D.Strings[93050]="我想继续接受更加困难的挑战，拉图修斯。"
D.Strings[93051]="我想我已经准备好接受最艰难的挑战了，拉图修斯。"
D.Strings[93052]="你的愚行会葬送你的！"
D.Strings[93053]="好吧，这下回不了头了！你还等什么？来啊，西奥多！"
D.Strings[93054]="|TInterface\\Icons\\INV_Misc_Bell_01:20|t你刚刚碰到|cFFFF0000集市货物|r，魔法警报就响了起来！"
D.Strings[93055]="|TInterface\\Icons\\inv_misc_statue_04:20|t破坏|cFFFF0000夜之子等身雕像|r的行为引起了敌人的注意！"
D.Strings[93056]="你的剑术太迟缓轻率了！再好好练练吧！"
D.Strings[93057]="太慢了，完全不出我所料！你的剑术太差劲了！"
D.Strings[93058]="装袋"
D.Strings[93059]="|TInterface\\Icons\\inv_gizmo_03:20|t用工具修复|cFFFF0000丢弃的垃圾|r的噪音响彻了整片区域！"
D.Strings[93060]="安布拉·卡达布拉！"
D.Strings[93061]="你听到了身后的脚步声！"
D.Strings[93062]="嘿！那……那是我的酒！<嗝儿！>"
D.Strings[93063]="种植安瑟瑞尔花。"
D.Strings[93064]="种植入梦叶"
D.Strings[93065]="种植狐尾花"
D.Strings[93066]="种植夏斯卡格草"
D.Strings[93067]="种植星光玫瑰"
D.Strings[93068]="种植邪能球茎"
D.Strings[93069]="睡……睡眠时间……<嗝儿！>"
D.Strings[93070]="快下来！没时间让你们慢慢绕路了。"
D.Strings[93071]="干得好，士兵们！你们三个，跟我走。我们去警告其他人。其他人守住——"
D.Strings[93072]="小心！又来了！"
D.Strings[93073]="伊凡尼尔·牧歌对身旁的角鹰兽伸出手，虚弱地想要赶走它。"
D.Strings[93074]="继续，飞啦！"
D.Strings[93075]="野生月落角鹰兽挑衅地对着空气抓了几下，就是不飞走。"
D.Strings[93076]="别再回来了。我们已经被夜之子的背叛给毁了。"
D.Strings[93077]="我们需要——大嘴，不！"
D.Strings[93078]="大嘴转身向你冲来！"
D.Strings[93079]="<看到你靠近，凡瑟尔突然停下话头，怀疑地盯着你。>$B$B安纳瑞斯，你想干什么？你不用继续去讨好那些恶魔了吗？"
D.Strings[93080]="训练就要开始了，你们准备好了吗？"
D.Strings[93081]="别管他。我要你去找洛休斯。我们在袭击中失散了——我想他还在图书馆里坚持着。"
D.Strings[93082]="莉莉丝让你去一趟，有关那批暮色百合豆荚的事。"
D.Strings[93083]="干得好，别忘了每天练习。"
D.Strings[93084]="你要反击！"
D.Strings[93085]="保持下去。"
D.Strings[93086]="再练练基本功吧。"
D.Strings[93087]="做得很好。"
D.Strings[93088]="反击的机会来了！"
D.Strings[93089]="暮色百合豆荚？我知道了……"
D.Strings[93090]="有时，我都会忘了塞伦娜的天赋有多么出众。欢迎回来。是时候解决这些入侵者了。"
D.Strings[93091]="请原谅，我必须马上处理这件事。"
D.Strings[93092]="好好利用你的优势。"
D.Strings[93093]="我已经帮你开辟了一条安全通道。触摸那些水晶能将我的守卫召唤到你身边。利用这一点，快速前进吧！"
D.Strings[93094]="拉图修斯的魔法召唤过我，他还活着！快——你能帮我们找到其他人。"
D.Strings[93095]="道路肃清后，我们就行动。你的英勇行为意义重大，远超你的想象，朋友。"
D.Strings[93096]="太好了！你们完好无损地过来了！失窃的传送器总是不太可靠……"
D.Strings[93097]="正在准备诊断系统。听说你跟那个可怕的维库战争领主大战了一场。要我说，那个小偷是罪有应得！"
D.Strings[93098]="蒸汽泵……正常。低价离子能量转化单元……正常，正常……都正常。"
D.Strings[93099]="你们来了！非常准时。"
D.Strings[93100]="现在，让我们召回风暴峡湾的观察单位。"
D.Strings[93101]="风暴峡湾……风暴峡湾……啊，在这儿。"
D.Strings[93102]="启动处理器。初始化下载中转器。我讨厌看到升级系统里有一点点不协调。"
D.Strings[93103]="等处理器运转起来，它只要一到两分钟就能提取出XR9-47里的信息。坐下来享受科学吧！"
D.Strings[93104]="救命……来人啊！"
D.Strings[93105]="有人吗？救命啊！"
D.Strings[93106]="如果你不介意的话，我也想帮忙。"
D.Strings[93107]="看来这场战斗才刚刚开始。"
D.Strings[93108]="谢谢。我得去找其他人了，希望这个能对你有所帮助。"
D.Strings[93109]="继续前进吧！他们无处不在！"
D.Strings[93110]="你！能来帮个忙吗？"
D.Strings[93111]="我的法术书！这让我怎么——嘿！这边！"
D.Strings[93112]="我到底惹上什么麻烦了？"
D.Strings[93113]="<如果你有草药的话，可以把它种在这里。>"
D.Strings[93114]="又是肯瑞托的探子！"
D.Strings[93115]="你的朋友已经完蛋了。"
D.Strings[93116]="现在该轮到你了！"
D.Strings[93117]="这绝对是我磨练技巧的最佳机会！"
D.Strings[93118]="我好像忘了几个新学的法术，不过我相信我们不会遇到多少麻烦的。"
D.Strings[93119]="%s翻着他的法术书。"
D.Strings[93120]="圣光在上！你在这儿干什么？不管了！快来帮我解决这个家伙！"
D.Strings[93121]="真没想到能在这里见到你！能帮个忙吗？"
D.Strings[93122]="<这头鹿盯着你看了一会儿，然后嘶鸣起来。>"
D.Strings[93123]="<小心地采集一小滴血液样本。>"
D.Strings[93124]="<使用你的黑暗魔法获取血液。>"
D.Strings[93125]="不介意多个伴儿吧？我们都是为了同一个目的来的。"
D.Strings[93126]="我早就想跟个$c一起战斗，检验一下我的战斗技巧了。"
D.Strings[93127]="感谢你的帮助，但我得继续前进了。"
D.Strings[93128]="一旦施放了痛楚，那么在效果结束前，你都无需再施放它了。"
D.Strings[93129]="痛楚的效果结束了！再施放一次！"
D.Strings[93130]="使用痛楚！"
D.Strings[93131]="一旦施放了腐蚀术，那么在前一个法术结束前，你都无需再施放它了。"
D.Strings[93132]="腐蚀术的效果结束了！再施放一次！"
D.Strings[93133]="使用腐蚀术！"
D.Strings[93134]="什么……怎么……？"
D.Strings[93135]="对你的目标使用吸取生命！"
D.Strings[93136]="使用生命吸取！"
D.Strings[93137]="谢了！你是个勇敢的$c，不是吗？"
D.Strings[93138]="我被……肮脏的外来者触碰了？！"
D.Strings[93139]="你是来加入我们的吗？但愿你能给我们带来一些强大的研究对象。"
D.Strings[93140]="痛苦无常可以使用了！立刻使用它吧！"
D.Strings[93141]="使用痛苦无常！"
D.Strings[93142]="使用生命分流补充法力值！"
D.Strings[93143]="我给你带来了一颗奥术智慧之珠。你到底里在这里干什么啊？"
D.Strings[93144]="施放恐惧！"
D.Strings[93145]="你是来向我们学习的吗？你给我们带来了什么？"
D.Strings[93146]="召唤末日守卫！"
D.Strings[93147]="唔，这确实很有趣。我们研究各种神奇的魔法，为自己的晋升做好准备。"
D.Strings[93148]="我们研究一切能够让我们晋升的力量。你必须将你的礼物带去找玛兰。"
D.Strings[93149]="你可以将自己的一部分力量凝结成治疗石。如果你受伤了，可以摄取治疗石来恢复生命值。"
D.Strings[93150]="使用制造治疗石。"
D.Strings[93151]="现在，使用治疗石为你自己治疗受到的部分伤害。"
D.Strings[93152]="你的生命值太低了，快使用治疗石！"
D.Strings[93153]="有准备的术士可以度过任何危机……甚至是死亡！"
D.Strings[93154]="使用灵魂石逃避死亡。"
D.Strings[93155]="太神奇了！你控制的恶魔带给了你强大的力量！"
D.Strings[93156]="我的枪……卡住了！"
D.Strings[93157]="小心！它们比看起来的要强大得多！"
D.Strings[93158]="你看来需要个伴儿吧。"
D.Strings[93159]="你来让他们保持距离。剩下的就交给我吧。"
D.Strings[93160]="小心点，$n。这里的空气中充斥着他们恶心的臭味。"
D.Strings[93161]="我对这一带不太熟悉，所以最好还是继续前进吧。"
D.Strings[93162]="噢，天呐，对了！它一定能给出许多激动人心的数据！"
D.Strings[93163]="我准备好了，开始吧。"
D.Strings[93164]="你可以走了，$c……马上！"
D.Strings[93165]="来自苏拉玛的恶魔在蚕食我们的土地。我们得反击！如果你能干掉他们的首领，那我的鳞卫就能毁掉传送门。"
D.Strings[93166]="我们可以一起击退燃烧军团！"
D.Strings[93167]="这应该能暂时挡住他们。再见，勇士。接着就交给我们吧！"
D.Strings[93168]="治疗高烧的病人。"
D.Strings[93169]="阿苏纳必将倒在燃烧军团脚下！"
D.Strings[93170]="我们是不可……阻挡的……"
D.Strings[93171]="我们将用邪能之火净化这片土地！"
D.Strings[93172]="阿克萨拉克斯……为我报仇！"
D.Strings[93173]="纳迦使用他们的邪恶巫术控制了当地的鱼人。但那边这一群鱼人受到的控制似乎还不深。你看看能不能让他们恢复理智吧。"
D.Strings[93174]="干得好！幸好我们抢在纳迦的影响力得到巩固之前解决了他们。"
D.Strings[93175]="这个曾经辉煌的酒厂被污染了，邪恶的怪物从那些被亵渎的酒桶里渗了出来。快去净化这个该死的地方吧！"
D.Strings[93176]="可惜了这批酒，不过它们看上去已经像是陈年老醋了。"
D.Strings[93177]="当地的野生动物会捕食我们受伤的雏龙。请保护好它们。"
D.Strings[93178]="那条雏龙过一会儿就能恢复了。我要谢谢你。"
D.Strings[93179]="如果你想帮助我们的话，就需要好好磨砺你的技巧。"
D.Strings[93180]="你看起来有两下子。我们或许用得着你。"
D.Strings[93181]="我想我可能已经解开了加鲁霍德的配方的秘密。我需要你帮忙收集一些特殊的材料，但你要小心点，这些生物可是很脆弱的！"
D.Strings[93182]="太好了！我得试试这个配方。真正的问题在于，上哪儿找一个愿意喝它的人……"
D.Strings[93183]="别被那个野蛮人的体格给骗了。他和他的同类一样危险。小心他带毒的鳞片！"
D.Strings[93184]="如果毒素开始让你感觉头晕，就赶快去找牧师。"
D.Strings[93185]="使用背刺！"
D.Strings[93186]="<随着你的靠近，狂风吹得更加猛烈，并翻滚着电光。或许你应该找个萨满来跟这个躁动的元素谈谈？>"
D.Strings[93187]="<随着你的靠近，狂风吹得更加猛烈，闪电在风中噼啪作响。风暴之核中的这个元素用一种扭曲的声音对你说道：>$b$b求求你……萨满……$b$b我控制不住体内的风暴了……帮帮我……帮……"
D.Strings[93188]="你去忙吧，卡里杜斯去找个适合举行仪式的地方。"
D.Strings[93189]="从你身边的术士同伴来看，你做了正确的事。这很好，也很令人吃惊。"
D.Strings[93190]="我逃出了一个恶魔的世界，结果却要住进另一个恶魔的世界。\n\n不过至少这个世界是在你的控制之下的。"
D.Strings[93191]="在控制了恐痕恶魔后，我们就能分析并控制他们的力量了。"
D.Strings[93192]="<泽宁微微点了点头，默默地表示已经发现了你的到来。>"
D.Strings[93193]="武器战士是终极的物理系斗士，能使用格斗技巧和武器碾碎跟他们作对的人。"
D.Strings[93194]="战士是不会慢慢晃悠到敌人面前的！使用冲锋拉近你跟对手间的距离。试试吧！"
D.Strings[93195]="一旦你能够着目标后，就能用最基本的自动攻击了，但老练的战士会用一系列的高级技巧来击败敌人。"
D.Strings[93196]="对目标假人使用致死打击。"
D.Strings[93197]="致死打击可以使用了！立刻使用它吧！"
D.Strings[93198]="使用致死打击！"
D.Strings[93199]="对目标假人使用猛击。"
D.Strings[93200]="快使用猛击！"
D.Strings[93201]="巨人打击是你最具毁灭性的攻击之一。只要尽量频繁地使用它，没有哪个敌人能在你面前坚持多久。"
D.Strings[93202]="对目标假人使用巨人打击。"
D.Strings[93203]="巨人打击可以使用了！立刻使用它吧！"
D.Strings[93204]="使用巨人打击！"
D.Strings[93205]="击败一个敌人后，你的心中将充满胜利的自豪感！"
D.Strings[93206]="乘胜追击可以使用了！立刻使用它吧！"
D.Strings[93207]="使用乘胜追击！"
D.Strings[93208]="放松点，朋友，让我来安抚你体内的风暴。"
D.Strings[93209]="卡里杜斯找到了举行仪式的好地方！朋友，来紫罗兰之门。卡里杜斯在帷幕后的房间里等你。"
D.Strings[93210]="使用暗影打击！"
D.Strings[93211]="那些警报说明我们的熔压单元遇到了一些小小的……技术难题。"
D.Strings[93212]="使用旋风斩消灭这群敌人。"
D.Strings[93213]="你只需要用聚变高压关闭上方的两块控制面板。铜须和我来操作中央控制台。"
D.Strings[93214]="看！圣锤的结界依然强大！我们先要净化这里的污染。你准备好了就说一声。"
D.Strings[93215]="旋风斩能够伤害多个敌人！"
D.Strings[93216]="使用旋风斩！"
D.Strings[93217]="使用刺骨！"
D.Strings[93218]="你有麻烦了！快使用消失！"
D.Strings[93219]="为了能万无一失地完成仪式，我们必须清理一下这个房间。只要你说一声，我就能立刻开始。"
D.Strings[93220]="你准备好后，就查看法术书和天赋树，了解你所能学习的其他技能吧。"
D.Strings[93221]="旋风斩不是你唯一能够攻击多个敌人的技能。"
D.Strings[93222]="使用顺劈斩和旋风斩消灭这群敌人。"
D.Strings[93223]="快使用顺劈斩！"
D.Strings[93224]="强大的敌人需要运用更多的技巧才能击倒。作为刺骨的替代技能，夜刃可以对你的目标造成持续伤害，而且它在战斗早期很适合用来消耗连击点数。和刺骨一样，夜刃也是终结技，最好在你拥有5个连击点数时使用它。"
D.Strings[93225]="使用5个连击点数对目标假人施放夜刃。"
D.Strings[93226]="你有5个连击点数了。使用夜刃吧！"
D.Strings[93227]="使用夜刃！"
D.Strings[93228]="等你有5个连击点数后再使用夜刃！"
D.Strings[93229]="快使用猩红之瓶恢复生命值！"
D.Strings[93230]="你正面对数个敌人，试试使用袖剑风暴吧！"
D.Strings[93231]="审判是一个远程技能。试着从远处发动它吧！"
D.Strings[93232]="审判可以使用了！立刻施放它！"
D.Strings[93233]="施放审判！"
D.Strings[93234]="公正之剑可以使用了！立刻使用它吧！"
D.Strings[93235]="施放公正之剑！"
D.Strings[93236]="使用十字军打击生成神圣能量！"
D.Strings[93237]="使用十字军打击！"
D.Strings[93238]="圣殿骑士的裁决可以使用了！立刻使用它吧！"
D.Strings[93239]="使用圣殿骑士的裁决！"
D.Strings[93240]="你有麻烦了！快使用圣盾术保护好自己！"
D.Strings[93241]="使用圣盾术！"
D.Strings[93242]="使用圣光闪现治疗你自己！"
D.Strings[93243]="我不会……噢，不要喊出来！"
D.Strings[93244]="但别让他们伤得太重。我待会儿还要用他们呢。"
D.Strings[93245]="你成功了！烈焰熄灭了……"
D.Strings[93246]="太惊人了！聚变系统的运转效率达到了98.33%%。还是循环运转。"
D.Strings[93247]="小心点！让我们净化这座大厅！"
D.Strings[93248]="噢，天哪。风暴巨兽的目标辨识系统遇到了一点故障。"
D.Strings[93249]="激活稳定矩阵，别让它把整座实验室都炸飞了！"
D.Strings[93250]="干得好，让我们……等等，那是什么？"
D.Strings[93251]="愚蠢的萨满……就算是你也承受不了我体内的风暴。滚开！"
D.Strings[93252]="你的盟友倒下了！%s撤退了！"
D.Strings[93253]="萨满，你用冷静的头脑抚平了风暴。你的专注鼓舞了我。现在，你可以走了，我的祝福与你同在。"
D.Strings[93254]="终于可以开始了！等仪式结束，我们拿到战锤后，这里就会坍塌，永远封印提尔的安息之地。"
D.Strings[93255]="情况不对劲。有一朵火花不见了！"
D.Strings[93256]="等等，我感觉它就在下面，可能在某个怪物手里。一定要拿到它！你好了我们就出发，勇士。"
D.Strings[93257]="我们得继续深入找到那东西，否则这次行动就彻底白费了。"
D.Strings[93258]="我们的雏龙想吃兽肉，但这些孩子吃不了生肉。把这根闪电魔棒插在新鲜的尸体上，剩下的就交给我们的雏龙吧。"
D.Strings[93259]="你提供的美餐会让我们的雏龙更加强壮。谢谢你。"
D.Strings[93260]="你肯定听说过上古之战吧。如果你去问至高岭牛头人的话，他们肯定会告诉你，是他们打败了提克迪奥斯。\n\n不过他们确实帮了忙。事实上，他们帮了大忙。你想听听我的故事吗？"
D.Strings[93261]="无耻的鱼人占领了墨尔海姆村。我决不允许他们占据那昔日的圣地。去消灭那些渣滓！"
D.Strings[93262]="干得好。我还记得那家伙，这村子就是因他而得名。他是个好领袖。"
D.Strings[93263]="艾莎拉，在苍穹会里要小心一点。"
D.Strings[93264]="当然，但有什么可怕的呢？"
D.Strings[93265]="在这里，就算是经验丰富的法师都很容易失踪……而提瑞斯秘法会又很需要你！"
D.Strings[93266]="看。我最喜欢的咒术师来了！"
D.Strings[93267]="米米尔隆的孩子制造了一件聪明的玩具，据说它能掌控风暴之力。去用战斗检验一下他们的工艺吧。"
D.Strings[93268]="神奇的装置。但在力量面前，小聪明毫无用处！"
D.Strings[93269]="戒律牧师能够同时使用截然相反的圣光与暗影之力，以进行治疗或是造成伤害。"
D.Strings[93270]="对目标假人使用暗言术：痛。"
D.Strings[93271]="一旦目标受到暗言术：痛的效果影响，那么在上一个效果结束前，你就无需再施放它了。"
D.Strings[93272]="你的目标身上的暗言术：痛效果结束了，再施放一次！"
D.Strings[93273]="使用暗言术：痛！"
D.Strings[93274]="圣光是强大的盟友，能治疗同伴、击倒对手。"
D.Strings[93275]="对目标假人使用苦修。"
D.Strings[93276]="苦修可以使用了！立刻使用它吧！"
D.Strings[93277]="立刻施放苦修！"
D.Strings[93278]="圣光的力量可以让你惩击面前的任何敌人！"
D.Strings[93279]="对目标假人使用惩击。"
D.Strings[93280]="施放惩击！"
D.Strings[93281]="别停下，废物！"
D.Strings[93282]="别再磨磨蹭蹭的了！现在，你属于燃烧军团了！"
D.Strings[93283]="巨兽稳定下来了！干得好，真是太好了。"
D.Strings[93284]="使用真言术：盾来抵挡伤害。"
D.Strings[93285]="施放真言术：盾保护你自己！"
D.Strings[93286]="在某些战斗中，你需要同时面对数名敌人。"
D.Strings[93287]="使用心灵尖啸！"
D.Strings[93288]="呃，伙计们，好消息是，下载已经完成了89%%！但我们有个小问题，那就是系统崩溃。"
D.Strings[93289]="使用恳求治疗你的伤势。"
D.Strings[93290]="使用恳求治疗你自己！"
D.Strings[93291]="使用暗影与圣光的力量去夺取胜利吧！"
D.Strings[93292]="这真是非常时刻！这可能解决所有麻烦……也可能毁了我们。我要你按下那个写着“不要按这个按钮”的红色大按钮。"
D.Strings[93293]="你不仅仅能保护自己或是一名盟友。牧师还能施放足以笼罩一整片区域的护盾，保护其范围内的所有盟友。"
D.Strings[93294]="使用真言术：障保护这些士兵。"
D.Strings[93295]="暗影之力同样有治疗效果，但这需要付出一定的代价。暗影愈合是一个非常强大的治疗法术，但它的一部分治疗量会随着时间的推移而衰减。"
D.Strings[93296]="使用暗影愈合将你的生命值恢复至全满。"
D.Strings[93297]="作为一名踏风武僧，你要用你的拳头和速度战胜敌人。"
D.Strings[93298]="按压"
D.Strings[93299]="对目标假人使用猛虎掌。"
D.Strings[93300]="使用猛虎掌生成真气！"
D.Strings[93301]="使用猛虎掌！"
D.Strings[93302]="对目标假人使用旭日东升踢。"
D.Strings[93303]="旭日东升踢可以使用了！立刻使用它吧！"
D.Strings[93304]="使用旭日东升踢！"
D.Strings[93305]="虽然不如旭日东升踢强大，但幻灭踢仍是一记重拳……呃，重脚！"
D.Strings[93306]="对目标假人使用幻灭踢。"
D.Strings[93307]="使用幻灭踢！"
D.Strings[93308]="你拥有许多攻击技能，踏风武僧！怒雷破会消耗3点真气并造成大量伤害。"
D.Strings[93309]="对目标假人使用怒雷破。"
D.Strings[93310]="怒雷破可以使用了！立刻使用它吧！"
D.Strings[93311]="使用怒雷破！"
D.Strings[93312]="你总是迅捷如风，能随意在战场上穿梭。"
D.Strings[93313]="练习几次滚地翻吧。"
D.Strings[93314]="你的宠物受伤了！幸好，你能帮助自己最信赖的伙伴。"
D.Strings[93315]="使用治疗宠物给你的宠物疗伤。"
D.Strings[93316]="你的宠物已经死亡！此时，你的治疗宠物会变成复活宠物，让你忠实的伙伴死而复生。"
D.Strings[93317]="杀戮命令可以使用了！立刻使用它吧！"
D.Strings[93318]="使用杀戮命令！"
D.Strings[93319]="凶暴野兽可以使用了！立刻使用它吧！"
D.Strings[93320]="使用凶暴野兽！"
D.Strings[93321]="使用眼镜蛇射击！"
D.Strings[93322]="狂野怒火可以使用了！立刻使用它吧！"
D.Strings[93323]="使用狂野怒火！"
D.Strings[93324]="使用多重射击！"
D.Strings[93325]="圣盾术能在短时间内保护你不受任何伤害，所以将它留到紧急情况下使用吧。"
D.Strings[93326]="树大根深。万物都将臣服于梦魇！"
D.Strings[93327]="我见到了梦魇。翡翠梦境必将破灭。"
D.Strings[93328]="很好！记得定期使用烈焰震击，让敌人持续燃烧。"
D.Strings[93329]="我将回归梦魇……曾经的光明都将化为黑暗。跟我走吧……跟我走吧……"
D.Strings[93330]="只要肃清一片区域，援军就会守住那里。圣骑士们，前进！"
D.Strings[93331]="在战斗中，你可以召唤大地本身的力量来保护你和你的盟友。"
D.Strings[93332]="使用火元素技能召唤你的元素吧！"
D.Strings[93333]="使用土元素召唤一个土灵防御者保护你一小段时间。"
D.Strings[93334]="在面对多个敌人时，你可以震动他们脚下的大地，同时伤害数个目标。"
D.Strings[93335]="使用震地图腾对付多个敌人。"
D.Strings[93336]="作为一名萨满，你能够与狼魂沟通，变成狼的形态。虽然这不会让你获得新的战斗技能，但能让你的移动速度变快。"
D.Strings[93337]="练习在幽魂之狼状态下进行移动。"
D.Strings[93338]="萨满是宝贵的盟友，因为他们可以用技能强化自身，以及他们的小队和团队成员。"
D.Strings[93339]="使用英勇暂时提高你的急速，这可以加快你的攻击和施法速度。"
D.Strings[93340]="如果你在战斗中被包围了，可以使用雷霆风暴击退敌人，为自己赢得一些喘息的机会。"
D.Strings[93341]="使用雷霆风暴击退你周围的敌人。"
D.Strings[93342]="使用烈焰震击烧灼你的敌人！"
D.Strings[93343]="使用烈焰震击！"
D.Strings[93344]="你只要在烈焰震击效果即将结束时使用它！"
D.Strings[93345]="在你的敌人燃烧时使用熔岩爆裂！"
D.Strings[93346]="使用熔岩爆裂！"
D.Strings[93347]="在你的敌人受到烈焰震击的灼烧后再使用熔岩爆裂以提高它的伤害！"
D.Strings[93348]="使用闪电箭！"
D.Strings[93349]="你的漩涡值已经满了！快使用大地震击！"
D.Strings[93350]="使用大地震击！"
D.Strings[93351]="等到你的漩涡值达到上限后再使用大地震击！"
D.Strings[93352]="使用闪电链！"
D.Strings[93353]="使用治疗之涌治疗你自己！"
D.Strings[93354]="使用火元素！"
D.Strings[93355]="这是使用土元素的好机会！"
D.Strings[93356]="你正面对数个敌人，试试震地图腾吧！"
D.Strings[93357]="使用嗜血暂时提高你的急速，这可以加快你的攻击和施法速度。"
D.Strings[93358]="使用雷霆风暴击退敌人！"
D.Strings[93359]="下载完毕！干得好，太好了。快来控制台找我。"
D.Strings[93360]="所有能拿得动锤子和钳子的蠢货都能打铁，但只有大师级的工匠才能将奥术的精华融入他的作品中，锻造出兼具灵巧和威猛的武器。"
D.Strings[93361]="虽然你们为这片海滩带来了荣耀，但你们中的某些人也带来了黑暗！此刻，军团和上古之神杂交产生的瘟疫正在渗入我神圣的土地。去净化它！"
D.Strings[93362]="小心点！我绝不容许这种腐蚀存在于我的土地上。"
D.Strings[93363]="对……对，我明白了。噢，不不。糟了，糟了！"
D.Strings[93364]="怎么了？普斯塔佳呢？"
D.Strings[93365]="托里姆的王座在风暴神殿。你最好快点行动。没时间了！"
D.Strings[93366]="滚地翻，快用滚地翻！"
D.Strings[93367]="我们去上面的平台吧。"
D.Strings[93368]="这火盆看来没什么特别的。对于一件古董来说，它的状况相当不错。"
D.Strings[93369]="你的盟友正在战场上大开杀戒。去加入他们，证明你的勇气吧！"
D.Strings[93370]="滚地翻不是你唯一的机动技能。踏风武僧还可以凌空渡虚，飞向目标。"
D.Strings[93371]="使用翔龙在天冲向目标假人并对它造成伤害。"
D.Strings[93372]="使用翔龙在天！"
D.Strings[93373]="有时，你也可能遇到力不从心、双拳难敌四手的情况。"
D.Strings[93374]="令攻击你的士兵陷入麻痹状态。"
D.Strings[93375]="战斗不可能总是公平的……不是吗？"
D.Strings[93376]="使用风火雷电同时攻击这三个目标假人。"
D.Strings[93377]="你正面对数个敌人！快试试风火雷电吧！"
D.Strings[93378]="你的武僧训练教会了你如何精确打击敌人的弱点。轮回之触能够造成大量伤害，但它需要一小段时间才能生效。"
D.Strings[93379]="对目标假人使用轮回之触。"
D.Strings[93380]="打得不错！你已经证明了自己的实力。"
D.Strings[93381]="使用猎豹形态，变形为猎豹。"
D.Strings[93382]="你需要变成猎豹形态来进行战斗！"
D.Strings[93383]="你没有进入猎豹形态！"
D.Strings[93384]="作为一只猎豹，你可以悄无声息地潜行，让你偷偷靠近敌人。潜行可以让你进入潜行模式。"
D.Strings[93385]="使用潜行进入潜行状态。"
D.Strings[93386]="潜行能持续到你取消、攻击或受到伤害为止。"
D.Strings[93387]="你的主要攻击技能是撕碎。"
D.Strings[93388]="使用撕碎来生成连击点数！"
D.Strings[93389]="使用撕碎！"
D.Strings[93390]="我们的晋升已经近在咫尺。你给我们带来什么有价值的东西了吗？"
D.Strings[93391]="一旦你潜行到猎物身边，就可以发动伏击了。"
D.Strings[93392]="对目标假人使用斜掠。"
D.Strings[93393]="斜掠可造成持续伤害，所以在目标身上的效果结束前，你无需再使用它。"
D.Strings[93394]="使用斜掠！"
D.Strings[93395]="当你有5个连击点数时，对目标假人使用凶猛撕咬。"
D.Strings[93396]="你有5个连击点数了！使用凶猛撕咬吧！"
D.Strings[93397]="使用凶猛撕咬！"
D.Strings[93398]="你的大部分技能都要消耗能量值。有时，你会发现自己的能量值过低，无法使用任何技能。"
D.Strings[93399]="你的能量值过低！快使用猛虎之怒！"
D.Strings[93400]="使用猛虎之怒！"
D.Strings[93401]="强大的敌人需要运用更多的技巧才能击倒。"
D.Strings[93402]="消耗5个连击点数，对目标使用割裂。"
D.Strings[93403]="你有5个连击点数了！使用割裂吧！"
D.Strings[93404]="使用割裂！"
D.Strings[93405]="需要迅速摆脱棘手的局面？这可是你的强项。"
D.Strings[93406]="练习使用急奔来提高你的移动速度。"
D.Strings[93407]="你可以召唤自然之力来施放各种其他技能，比如治疗！"
D.Strings[93408]="使用愈合恢复你所有的生命值。"
D.Strings[93409]="用治疗之触治疗你自己！"
D.Strings[93410]="使用法术通常会解除你的变形。别忘了变回猎豹形态进行战斗。"
D.Strings[93411]="使用猎豹形态。"
D.Strings[93412]="有时，你会希望敌人能留在原地，以便你拉近距离……或是快速撤退。"
D.Strings[93413]="使用纠缠根须将我的士兵定身。"
D.Strings[93414]="我们正在准备晋升。但愿玛兰能认可你的礼物，那样你就能加入我们了。"
D.Strings[93415]="试着使用纠缠根须来让你的目标无法行动吧！"
D.Strings[93416]="在它触碰到你之前将它定身！让我们再试一次！"
D.Strings[93417]="施放纠缠根须！"
D.Strings[93418]="在猎豹形态下，你可以依靠动物的本能来帮助自己挺过艰苦的战斗。"
D.Strings[93419]="使用生存本能降低受到的伤害。"
D.Strings[93420]="使用生存本能！"
D.Strings[93421]="所以说，那些传说都是真的——你找回了烈焰之击！$b$b它在第三次大战中折断，凯尔萨斯王子下令修复了它。精灵的长剑每重铸一次都会变得更加强大，但只有最杰出的工匠才能做到这一点。$b$b我从未见过这种奇迹。可以让我拿一下吗？"
D.Strings[93422]="痛击并不是你唯一用来攻击多个敌人的技能。"
D.Strings[93423]="使用横扫同时伤害数个敌人。"
D.Strings[93424]="你正面对数个敌人，试试使用横扫吧！"
D.Strings[93425]="现在使用横扫！"
D.Strings[93426]="先使用痛击再使用横扫是一个很好的组合！"
D.Strings[93427]="在同时与数个敌人战斗时，野性德鲁伊可以化身为一场獠牙与利爪的风暴，伤害周围的一切。"
D.Strings[93428]="使用痛击同时伤害数个敌人。"
D.Strings[93429]="痛击会持续伤害你的敌人一小段时间，所以在它的效果结束之前，你无需对目标再次使用它。"
D.Strings[93430]="可以，不过只能给你拿一会儿。"
D.Strings[93431]="你目标身上的斜掠效果结束了！再使用一次！"
D.Strings[93432]="使用痛击！"
D.Strings[93433]="使用潜行！"
D.Strings[93434]="你发现的奥术智慧之珠相当神奇。我带来了一本旧法术书，还是从戴索姆的一头恶心食尸鬼那里弄来的。他都不知道是谁攻击了他。哈！"
D.Strings[93435]="你喜欢旅行吗，$n？作为魔导师们的求知者，我走过不少地方。我感觉很奇怪，大部分辛多雷都不怎么喜欢旅行。不过我跟大部分辛多雷都不一样，他们从来都不会忘了提醒我这一点。"
D.Strings[93436]="使用亡者复生召唤你的爪牙。"
D.Strings[93437]="发动战斗的最佳方式就是在远处让你的敌人染上疾病。"
D.Strings[93438]="对目标假人使用爆发。"
D.Strings[93439]="当敌人被瘟疫云雾熏晕后，你就能靠近他发动攻击了。"
D.Strings[93440]="对目标假人使用脓疮打击。"
D.Strings[93441]="银色北伐军，守住这里！我们继续前进！"
D.Strings[93442]="用脓疮打击感染目标假人后对它使用天灾打击。"
D.Strings[93443]="对目标假人使用凋零缠绕。"
D.Strings[93444]="你的攻击有时能让你在施放凋零缠绕时不消耗符文能量。好好利用这一点吧。"
D.Strings[93445]="你知道吗？许多魔导师以前都是在达拉然的肯瑞托研习魔法的。或许是时候搁置我们的仇恨，一起对抗燃烧军团了。"
D.Strings[93446]="有些敌人喜欢和你保持距离。"
D.Strings[93447]="用死亡之握将我的士兵拉向你。"
D.Strings[93448]="让我看看你掌握的黑暗力量吧！"
D.Strings[93449]="你的亡灵爪牙是战场上的宝贵资源。黑暗突变可以让你暂时将你的食尸鬼变成巨大的怪兽，并强化它的力量和技能。快试试吧！"
D.Strings[93450]="使用黑暗突变强化你的食尸鬼。"
D.Strings[93451]="啊，烈焰之击！如此精湛，如此优雅……"
D.Strings[93452]="作为一名死亡骑士，你就是战场的主宰！"
D.Strings[93453]="使用枯萎凋零解决大批爪牙。"
D.Strings[93454]="可这不是粗野的砍肉刀。这是战术大师的纤细长剑。每一次折叠锻打都在钢铁中融入了一丝奥术能量。我能感觉到它在我手中散发出的热量。太神奇了！"
D.Strings[93455]="谢谢你，$n。我辛苦了几辈子，都没见过这样的神剑。"
D.Strings[93456]="你目标身上的爆发效果结束了，再使用一次！"
D.Strings[93457]="施放爆发！"
D.Strings[93458]="你的目标身上还没有溃烂之伤，快使用脓疮打击吧！"
D.Strings[93459]="使用脓疮打击！"
D.Strings[93460]="使用天灾打击！"
D.Strings[93461]="在脓疮打击之后使用天灾打击，这是一个强大的组合！"
D.Strings[93462]="凋零缠绕可以使用了！立刻使用它吧！"
D.Strings[93463]="使用凋零缠绕！"
D.Strings[93464]="施放亡者大军！"
D.Strings[93465]="是时候施放黑暗突变了！"
D.Strings[93466]="你正面对数个敌人。试试使用枯萎凋零吧！"
D.Strings[93467]="使用灵界打击！"
D.Strings[93468]="作为一名冰霜法师，你擅长控场。你可以将敌人冻结在原地，再使用冰雹打得他们跪地求饶。"
D.Strings[93469]="使用召唤水元素召唤你的宠物。"
D.Strings[93470]="寒冰箭是你最基础、最可靠的攻击技能。"
D.Strings[93471]="对目标假人使用寒冰箭。"
D.Strings[93472]="你还在这里干什么？走开！"
D.Strings[93473]="现在，我们来看冰枪术。它和寒冰箭很像，但可以瞬发，而伤害较低。"
D.Strings[93474]="对被冻结的目标假人使用冰枪术。"
D.Strings[93475]="还有一个方法也能让冰枪术的威力最大化。"
D.Strings[93476]="对目标假人使用寒冰箭，直到触发寒冰指效果，然后使用冰枪术。"
D.Strings[93477]="这回我可不能再慢慢吞吞的了！"
D.Strings[93478]="你的另一个强大法术是寒冰宝珠。你该尽量多施放它，因为它可以让你的冰枪术更强大。"
D.Strings[93479]="对目标假人使用寒冰宝珠。"
D.Strings[93480]="战场是个危险的地方，所以保持移动对于保命非常重要。"
D.Strings[93481]="练习使用闪现术。"
D.Strings[93482]="使用冰霜新星冻结我的士兵。"
D.Strings[93483]="记住，冰枪术可以对被冻结的敌人造成额外的伤害，所以将冰霜新星和冰枪术组合使用是一个很好的战术。"
D.Strings[93484]="你最擅长同时攻击一群敌人了。"
D.Strings[93485]="使用暴风雪消灭这些敌人。"
D.Strings[93486]="让我看看你是怎么用元素之怒战斗的吧！"
D.Strings[93487]="尽管你已经尽了最大努力，有时可能也无法防止敌人靠近你。"
D.Strings[93488]="需要快速脱离战斗？隐形术是一个很好用的法术，可以帮你摆脱麻烦。"
D.Strings[93489]="使用隐形术脱离战斗。"
D.Strings[93490]="你的水元素已经死亡。施放召唤水元素把它召回来吧！"
D.Strings[93491]="使用寒冰箭！"
D.Strings[93492]="寒冰指已经触发！立刻使用冰枪术！"
D.Strings[93493]="使用冰枪术！"
D.Strings[93494]="你的目标被冻结了！使用冰枪术！"
D.Strings[93495]="寒冰宝珠可以使用了！立刻使用它吧！"
D.Strings[93496]="使用寒冰宝珠！"
D.Strings[93497]="你遭到了攻击！使用冰霜新星令你的对手定身！"
D.Strings[93498]="你需要在敌人触碰到你之前将他们冻结在原地。"
D.Strings[93499]="使用冰霜新星！"
D.Strings[93500]="施放暴风雪！"
D.Strings[93501]="施放寒冰护体！"
D.Strings[93502]="使用隐身术！"
D.Strings[93503]="这里的生活从来都不容易。"
D.Strings[93504]="对目标假人使用火舌。"
D.Strings[93505]="对目标假人使用石化。"
D.Strings[93506]="使用石化会产生漩涡值，这种资源能用来施放更强大的攻击。"
D.Strings[93507]="对目标假人使用熔岩猛击。"
D.Strings[93508]="在你消耗漩涡值的技能中，风暴打击最为强大。"
D.Strings[93509]="在触发风暴使者后对目标假人使用风暴打击。"
D.Strings[93510]="立刻使用风暴打击！"
D.Strings[93511]="你与兽灵的关系非常密切，比如狼。"
D.Strings[93512]="如果要在战斗中提高伤害，就用野性狼魂！"
D.Strings[93513]="如果你需要和数名敌人作战，那就释放出风暴的全部怒火吧！"
D.Strings[93514]="使用毁灭闪电消灭这群敌人。"
D.Strings[93515]="如果你发现自己在战斗中受到了太多伤害，萨满之怒可以在短时间内降低你所受到的伤害。试试吧！"
D.Strings[93516]="使用萨满之怒降低受到的伤害。"
D.Strings[93517]="你的火舌效果结束了！使用火舌！"
D.Strings[93518]="使用火舌！"
D.Strings[93519]="接下来是一个名叫……亚伯克隆比的人选送的参赛者。他还要求我朗读以下宣言：“我骗了朗读纸条的这个傻瓜，他将公布我最新、最恐怖的造物！”真是个奇怪的家伙。"
D.Strings[93520]="使用石化生成漩涡值！"
D.Strings[93521]="使用石化！"
D.Strings[93522]="我想缝合三世只是……漏了。你听明白了？缝合！漏了！伙计，我太激动了！"
D.Strings[93523]="熔岩猛击可以使用了！立刻使用它吧！"
D.Strings[93524]="使用熔岩猛击！"
D.Strings[93525]="风暴使者触发了！使用风暴打击！"
D.Strings[93526]="使用风暴打击！"
D.Strings[93527]="使用野性狼魂！"
D.Strings[93528]="使用毁灭闪电！"
D.Strings[93529]="你能用白昼和黑夜的力量对付敌人。月火术和阳炎术就是其中的代表。"
D.Strings[93530]="对目标假人使用月火术和阳炎术。"
D.Strings[93531]="这两种攻击都能造成持续伤害。一旦施放，在目标身上的效果结束前，你就无需再次施放了。"
D.Strings[93532]="一旦你的其他技能对敌人造成伤害后，就可以施放阳炎之怒了。"
D.Strings[93533]="对目标假人使用阳炎之怒。"
D.Strings[93534]="我来解决这堵墙！"
D.Strings[93535]="让我看看你是怎么掌控宇宙之力的吧！"
D.Strings[93536]="需要提高伤害？看看天上的星星吧！"
D.Strings[93537]="使用超凡之盟提高伤害，然后对目标假人使用阳炎之怒。"
D.Strings[93538]="一个平衡德鲁伊应该很擅长以寡敌众。"
D.Strings[93539]="使用明月打击消灭这群敌人。"
D.Strings[93540]="使用枭兽形态！"
D.Strings[93541]="你目标身上的月火术效果结束了！快对你的目标施放月火术！"
D.Strings[93542]="你的目标身上的阳炎术效果已经结束！对你的目标施放阳炎术！"
D.Strings[93543]="施放月火术！"
D.Strings[93544]="施放阳炎术！"
D.Strings[93545]="施放阳炎之怒来生成星界能量！"
D.Strings[93546]="施放阳炎之怒！"
D.Strings[93547]="星涌术可以施放了！立刻使用它吧！"
D.Strings[93548]="施放星涌术！"
D.Strings[93549]="使用明月打击！"
D.Strings[93550]="你简直无所不能！"
D.Strings[93551]="那个鱼人……真是古怪。他身上有一种熟悉的味道，可我无法确定。你能过去看看吗？"
D.Strings[93552]="你为什么会对苍穹会感兴趣？"
D.Strings[93553]="看来所有的生物都会被燃烧军团的腐蚀影响。无论它们是多么……渺小。"
D.Strings[93554]="我的巡逻队员……死了！都死了！"
D.Strings[93555]="他们突然就冒了出来！小心！"
D.Strings[93556]="谢谢你。作为报答，请允许我为你效劳吧。"
D.Strings[93557]="老实说，我有点不合群。大部分辛多雷都满足于一辈子住在银月城的高墙内。可在德拉诺生活了这么多年后，我感觉这种生活太沉闷了。我从来都不是一个藏着掖着的人……\n\n当大法师罗曼斯让我离开，成为魔导师的求知者时，我们两个都松了一口气。我打算看看苍穹会有什么有用的东西没有。"
D.Strings[93558]="我的剑为你效劳，$n。"
D.Strings[93559]="你对他们的活动知道些什么？"
D.Strings[93560]="别被骗了！那个家伙可不是我们的同类。小心点，英雄。"
D.Strings[93561]="去看看你的同伴们的伤势吧。你做得很好。"
D.Strings[93562]="这是个神秘的团体，喜欢含糊其辞，所以他们的人数不多。据说他们会收集世界各地的稀有魔法并进行研究，在这个领域里可能会发现一些相当强大的力量。\n\n我一定要发掘出他们隐藏的秘密。"
D.Strings[93563]="这条裂口弥漫着黑暗……圣光保佑我们！它手里有我们要的东西。朋友们，准备！"
D.Strings[93564]="一群魔虫冲出了魔能谷的洞穴！如果你用大石头堵住它们的地道，应该就能阻止它们了。"
D.Strings[93565]="那是什么？！一条更大的虫子钻过来了！站稳了！"
D.Strings[93566]="这应该能暂时阻止它们的入侵。谢谢你，勇士。"
D.Strings[93567]="拜之前的访客所赐，这一区域目前非常不稳定。我们得杀了那个家伙，才能得到我们需要的东西，但我不知道它会对我们周围的环境造成什么影响。\n\n所以我们最好干脆利落地干掉它，然后离开这里。下令吧，$n。"
D.Strings[93568]="|TInterface\\Icons\\inv_pet_broom.blp:20|t%s召唤清扫器来进行|cFFF00000|Hspell:207513|h[清扫]|h|r。"
D.Strings[93569]="干得好，但那些恶魔不会轻易放弃。做好准备！"
D.Strings[93570]="我听到什么了？"
D.Strings[93571]="捣乱是会被处死的！下不为例！"
D.Strings[93572]="你要再敢浪费我的时间，我就吸干你！"
D.Strings[93573]="作为掌控元素的大师，你可以将原始的元素之力凝聚成实体，来协助你战斗。"
D.Strings[93574]="军团的凝视锁定了你！"
D.Strings[93575]="空中指挥单位可以直接送你去神殿。上来！"
D.Strings[93576]="欢迎回到奥杜尔！代言人正在天文台等着你们。请跟我来！"
D.Strings[93577]="随着梦魇腐蚀的扩散，我很担心瓦尔莎拉的动物。我感觉让你照顾其中的部分动物会更安全。"
D.Strings[93578]="“代言人”？那是我的兄弟麦格尼，你这该死的破机器！"
D.Strings[93579]="虽然落入陷阱的动物可能会受伤，但这总比原本等待着它们的命运要强。我衷心祝福你和你的新伙伴们。"
D.Strings[93580]="迷路的鹰头小猫慢慢抬起头，看了看四周。"
D.Strings[93581]="迷路的鹰头小猫发现了你，惊慌地逃跑了！"
D.Strings[93582]="$n！那是真的吗？你拿到了烈焰之击？快来，跟我聊聊！"
D.Strings[93583]="我在另一边等你。"
D.Strings[93584]="$n——那是真的吗，你拿到了凯尔萨斯过去的佩剑？过来点！"
D.Strings[93585]="烈焰之击！皇家宝剑。在安纳斯特里亚·逐日者的手中，它的怒火曾吞噬了上千名阿曼尼巨魔。"
D.Strings[93586]="啊！它摸上去好烫啊！你是怎么……？无所谓了。我知道这把剑没有跟错人就行了。谢谢你，$n，让我触摸到了我的人民的历史。"
D.Strings[93587]="如果我们继续浪费时间的话，那些巨人就要把纳萨拉斯砸进海里去了。"
D.Strings[93588]="消灭那个怪物！为了圣光！"
D.Strings[93589]="传说是真的。一位英雄再次举起了烈焰之击！我以为这把剑已经遗失在冰冠堡垒的废墟中了。作为一件圣物，它的时代还要早于上古之战。我能……我能看看它吗？"
D.Strings[93590]="小心点，安多伦。贝洛克绝对不会喜欢看到你结交联盟的人的……"
D.Strings[93591]="可惜你们没能在更加愉快的场合下见到托里姆。他也是个动物爱好者！总是唠叨着他的那些狼。"
D.Strings[93592]="真的？身边能有个自己人真好……哪怕他有点太高了。"
D.Strings[93593]="没错，铜须。抓紧！我要拉你进来了。"
D.Strings[93594]="铜须！你又回来了！哈提可想你了，还有逐日。逐日？嗨！那头狼又跑哪儿去啦？"
D.Strings[93595]="啊，你还带来了帮我们摆脱上古之神的凡人！我们要办个盛大的宴会庆祝一下！"
D.Strings[93596]="回头再说吧，托里姆。有个维库疯子来窃取泰坦之击的力量了！"
D.Strings[93597]="那我们一起杀敌！来吧，维库人，面对风暴的怒火吧！"
D.Strings[93598]="我的兄弟姐妹都已逝去。我是最后的提尔近卫了。"
D.Strings[93599]="我拿到提尔之火了。快走！这里逸出的黑暗魔法会将空间撕开一个大洞的！"
D.Strings[93600]="不！他们……消失了！"
D.Strings[93601]="有人受伤了！去帮他们，我掩护你！"
D.Strings[93602]="太好了，别浪费时间，我们走！"
D.Strings[93603]="入侵者！我得去警告其他人！"
D.Strings[93604]="你来了，凡人！我知道你就在附近。快，这边走！"
D.Strings[93605]="主人离开了，他的爪牙在蚕食我的力量。狠狠报复那些僭越者！将他们打入无尽的痛苦深渊！"
D.Strings[93606]="愚蠢的术士！你真以为我对你那幼稚的盗宝计划一无所知吗？你低估了纳斯雷兹姆的力量！"
D.Strings[93607]="至于你，狡诈的颅骨，我待会儿再收拾你。"
D.Strings[93608]="过来，地狱之火的仆从！解决这个不速之客。"
D.Strings[93609]="很好！快，在主人回来前，杀掉狱卒，释放我！"
D.Strings[93610]="西奥多和我可以对付他们！为了荒野！"
D.Strings[93611]="你挺能干啊，法师。它们的魔力消散后，我的力量正在恢复。"
D.Strings[93612]="睁大你的眼睛！普斯塔佳就在附近。"
D.Strings[93613]="他们就这点本事吗？我才刚进入状态呢！"
D.Strings[93614]="魔枢宝库被削弱了！那股奥术能量说明，宝库已经无法压制住艾露尼斯了。"
D.Strings[93615]="泰坦之击的力量是属于我的！"
D.Strings[93616]="普斯特去王座那儿了！我们得阻止她！"
D.Strings[93617]="你很勇敢，竟然敢跟我接触，$r。$b$b或者你很愚蠢……"
D.Strings[93618]="见证我辉煌的晋升吧！"
D.Strings[93619]="对……我感觉造物者的力量在我的血管内流淌！"
D.Strings[93620]="又怎么了？！我迟早会摆脱你的控制并且……等等……你不是主人！"
D.Strings[93621]="我需要你的力量。"
D.Strings[93622]="哈！你以为你是第一个从注定要毁灭的世界赶来向我求助的生灵吗？$b$b不，你将在燃烧军团的力量前面灰飞烟灭，而我还将继续被这些杂种奴役，直到永远。$b$b你还是省省力气，自己跳火坑去吧！"
D.Strings[93623]="这么说，大名鼎鼎的萨奇尔最终选择了向恶魔投降。"
D.Strings[93624]="你怎么敢！要不是他们一直抽取我的力量，我绝对能轻而易举地控制他们。"
D.Strings[93625]="那就让我释放你吧。我们可以一起征服燃烧军团！我们将成为主宰！"
D.Strings[93626]="唔……好吧。如果你真的自信能解放我，就来邪魂堡垒吧。但如果你失败，就会和我一样受尽折磨！"
D.Strings[93627]="地面上布满了不稳定的能量。你最好不要踩上去……"
D.Strings[93628]="卡里杜斯知道是哪儿！卡里杜斯能帮忙！"
D.Strings[93629]="休想阻止我，蠢货！我需要……更多……力量！"
D.Strings[93630]="该结束了。哈提，杀！"
D.Strings[93631]="她撑不住了！小心！她要爆炸了！"
D.Strings[93632]="蠢货！就算你们摧毁了湍流之针，也来不及阻止我们了！艾露尼斯的力量即将撕开裂口！"
D.Strings[93633]="稳定病人的伤势。"
D.Strings[93634]="|TInterface\\Icons\\Ability_Xavius_NightmareBlades.blp:20|t萨维斯的|cFFFF0000|Hspell:206656|h[梦魇之刃]|h|r锁定了你。"
D.Strings[93635]="迷路的羽鬃小猫发现了你，惊慌地逃跑了！"
D.Strings[93636]="让我们先集中精力处理手头的事务吧。"
D.Strings[93637]="一个黑暗生物从虚空中过来了……是个大家伙。我们得走了！"
D.Strings[93638]="生命……吞噬……"
D.Strings[93639]="你成为了潜袭喷发的目标！"
D.Strings[93640]="你成功了！你控制了这对姐妹！"
D.Strings[93641]="萨洛拉丝和奥蕾塞丝将成为议会的利器。"
D.Strings[93642]="我们在议会的法阵那儿见。还有很多事要讨论呢。"
D.Strings[93643]="一切准备就绪，我可以完成仪式了！所有人，守住隧道！"
D.Strings[93644]="为什么……要跑？虚空……无法逃避……"
D.Strings[93645]="那东西太强大了！努力活下来，拖住它！"
D.Strings[93646]="就快完成了！再坚持一下！"
D.Strings[93647]="业余商人总爱找借口。而真正的大师更看重解决方案。"
D.Strings[93648]="抱歉，师父。我还在做那个紧急委托的搭扣……"
D.Strings[93649]="你们休想挡我的路！"
D.Strings[93650]="维库人，你不配拥有风暴之怒！"
D.Strings[93651]="你们奴役我的族人太久了！结束了！现在，我们要开创自己的命运！"
D.Strings[93652]="冷静，普斯特！我们不是敌人！"
D.Strings[93653]="你们只是我的棋子。仅此而已！"
D.Strings[93654]="别想违抗我！我将成为神王！"
D.Strings[93655]="前一个暗言术：痛的效果还有很多剩余时间时，就没有必要再次施放它。"
D.Strings[93656]="你的神圣能量已经达到上限！使用圣殿骑士的裁决！"
D.Strings[93657]="在痛楚的效果即将结束前再次施放它，以保证它的伤害最大化！"
D.Strings[93658]="你的灵魂碎片已经达到上限。施放痛苦无常！"
D.Strings[93659]="你的真气值已经达到上限！使用幻灭踢！"
D.Strings[93660]="切回猎豹形态！"
D.Strings[93661]="你目标身上的恶性瘟疫效果已经结束了。立刻使用爆发！"
D.Strings[93662]="你的目标身上的溃烂之伤效果层数已经达到了上限。快使用天灾打击！"
D.Strings[93663]="等到你获得寒冰指效果，或是目标被冻结时再使用冰枪术。"
D.Strings[93664]="你的漩涡值已经达到上限。使用熔岩猛击！"
D.Strings[93665]="你的星界能量已经达到上限。施放星涌术！"
D.Strings[93666]="我们拿到战锤了！快跑！墓穴要塌了！"
D.Strings[93667]="你们的逃亡……毫无意义。我会找到你们的……"
D.Strings[93668]="呃，刚才难受死我了。你来得正是时候！"
D.Strings[93669]="$n！有传闻说你得到了烈焰之击。这是真的吗？"
D.Strings[93670]="烈焰之击！我最后一次听说它的消息时，说是巫妖王将这把美丽的长剑收藏在了冰冠堡垒。你是怎么得到它的？"
D.Strings[93671]="我挖出的大部分遗物都失去了效力，但这把剑蕴藏着魔法能量。噢，它简直让我寒毛倒竖。但愿你知道该怎么使用它。"
D.Strings[93672]="谢谢你，$n。你手中握着一部活的历史。它本身就是一份宝藏！"
D.Strings[93673]="你是来帮我们解决这个小“麻烦”的吗？"
D.Strings[93674]="马杜尔，你不该跟部落的人说话的，尤其是在破碎海滩的事件发生之后。"
D.Strings[93675]="我们想要组织一次深入扎赫纳尔的探险，但那片废墟发生了太多的古怪事件。"
D.Strings[93676]="我这辈子挖到过不少遗物，但没有一样比得上你手中这把剑。这把剑铸成的年代当时还没有联盟和部落——我们矮人可能还生活在地洞里。我知道这个要求可能有点过分，可是……能让我拿一下吗？"
D.Strings[93677]="让黑夜降临到通敌者头上。"
D.Strings[93678]="问题？什么问题？"
D.Strings[93679]="夜之子利奥达斯似乎等到了来自苏拉玛的援军。他们认为叛变的堕夜精灵逃进了阿苏纳，以摆脱他们的掌握。"
D.Strings[93680]="虽然他们曾是我的同胞，但我也不能让这种邪恶势力留在我的土地上。你知道该怎么做。"
D.Strings[93681]="可惜啊，让那个利奥达斯跑了，但你已经给了夜之子一个难忘的教训。阿苏纳的居民会感谢你。"
D.Strings[93682]="很好。我会准备一个法术，它可以大幅削弱索罗克斯，但我需要你帮我打倒他。你准备好了吗？"
D.Strings[93683]="噢，只是这片城区短缺法力酒而已！下一批肯定很快就会到了。"
D.Strings[93684]="滚开，小偷！你已经抢走了我最珍贵的宝物，你还想要什么？"
D.Strings[93685]="又是你。快滚出去，否则我要叫守卫了！"
D.Strings[93686]="它真是太美了……活动的关节……武术的姿态……"
D.Strings[93687]="<这个冒险者的胳膊断了。如果你会接骨的话，你就能医治他了。 >"
D.Strings[93688]="<这个冒险者的胳膊断了。如果你会接骨的话，你就能医治她了。 >"
D.Strings[93689]="为病人接骨。"
D.Strings[93690]="是的，我要报名参加竞技场！"
D.Strings[93691]="“我正盼着今晚能掉几条史诗裤子呢。”$b$b德莱尼公主的脸上闪过一阵错愕，仿佛被这句话打了个措手不及。她的宫廷上响起一阵窃窃私语。格雷斯班爵士听到有人抽出了武器。$b$b公主皱起了眉毛，说道……$b$b|cFF600000<德莱尼公主会怎么回答呢？>|r"
D.Strings[93692]="完成了。我会处理掉这些灰烬，并回营地去找梅鲁娜的。谢谢你，朋友。"
D.Strings[93693]="如果你想参加竞技场的话，就告诉我一声，$r。"
D.Strings[93694]="那是……烈焰之击吗？“那把”烈焰之击？"
D.Strings[93695]="是的。$n在诺森德找到了它。这就是上古之战中达斯雷玛对抗燃烧军团时所用的那把魔法剑。"
D.Strings[93696]="但愿那些法师不会被燃烧军团影响。我们需要他们的帮助。"
D.Strings[93697]="欺诈罪应该判死刑！"
D.Strings[93698]="开火！用地狱火覆盖整个路面！别让那术士通过！"
D.Strings[93699]="尤隆一看到双头怪皮就愤怒地嘶鸣起来。"
D.Strings[93700]="这就交给我吧，朋友。你不用担心。"
D.Strings[93701]="尤隆的爪子嵌入了石头里，威严地看向别处。"
D.Strings[93702]="你的小猫们安全了，尤隆。你愿意赐予我们祝福，让我们与你分享这片土地吗？"
D.Strings[93703]="尤隆低下头，从脚踝上啄下了一根羽毛。"
D.Strings[93704]="谢谢你，陛下。"
D.Strings[93705]="尤隆将羽毛放在马德兰尼尔的手中。"
D.Strings[93706]="没有风元素领主，天空之墙就会一直动荡。"
D.Strings[93707]="自从奥拉基尔死后，这里就不太平，萨满。"
D.Strings[93708]="“您的魅力对我毫无作用，外来者。您奉承人的本事才刚刚入门呢。”$b$b格雷斯班爵士在公主冰冷的目光注视下渡过了难堪的三秒，才答道……$b$b|cFF600000<这次，格雷斯班爵士会说什么呢？>|r"
D.Strings[93709]="“你的那把剑可真够大的。你真的知道怎么使用它吗？”$b$b格雷斯班爵士瞄了一眼自己的裤子，又看看端庄的德莱尼公主。望着她那似笑非笑的脸庞，他答道……$b$b|cFF600000<这次，格雷斯班爵士会说什么呢？>|r"
D.Strings[93710]="“你的护腿里藏了一只侏儒吗？或者是两只？”$b$b格雷斯班爵士踉跄了一下，显然对公主如此直接的提问毫无准备。他很快就恢复了机智，答道……$b$b|cFF600000<这次，格雷斯班爵士会说什么呢？>|r"
D.Strings[93711]="我看到你带着烈焰之击，法师。我父亲说起过那把剑。早在离开奎尔多雷之前，他曾在上古之战中见证过它的怒火。"
D.Strings[93712]="“我敢打赌，您对遇见的每个公主都是这么说的。”$b$b格雷斯班爵士能看出她此刻真正的感受：的确，她统治着一个不可战胜的战士之国……但她也是一个女孩，沉重的王冠压得她喘不过气来。他答道……$b$b|cFF600000<这次，格雷斯班爵士会说什么呢？>|r"
D.Strings[93713]="“只是‘可爱’而已吗？您还得再动动脑筋啊，格雷斯班爵士。”$b$b格雷斯班爵士皱起了眉头。“看来我今天不在状态啊。”他想着，显然对自己的表现有些失望。$b$b|cFF600000<格雷斯班爵士会说些什么来弥补呢？>|r"
D.Strings[93714]="“好吧，我还觉得您很笨！”$b$b天蓝皮肤的公主顿时摆出一副被冒犯的表情。事实上，她的表现是如此刻意，格雷斯班爵士一眼就看出她是在故作姿态。他知道机会来了。$b$b|cFF600000<这次，格雷斯班爵士会说什么呢？>|r"
D.Strings[93715]="“没错，我几乎对遇到的每个女人都这么说。我向来都为自己的情妇数量而自傲。”"
D.Strings[93716]="“当然不是了，殿下。只有面对那些眼睛蓝得如同来自风暴之海的蓝宝石的公主时，我才会那么说。”"
D.Strings[93717]="“当然不是了，殿下。只有面对那些眼睛蓝得如同蓝宝石的人时，我才会那么说。”"
D.Strings[93718]="“呃，是‘真的’‘非常’可爱。”"
D.Strings[93719]="“裤子？在我的宫廷里，我们只穿长袍和护肩。”"
D.Strings[93720]="“您为什么要对我说这种蠢话？”"
D.Strings[93721]="$n，我看到你继承了烈焰之击。但愿它在你的手中，能比在凯尔萨斯王子手中时发挥更大的作用。"
D.Strings[93722]="“你这个无礼的小丑！我要砍下你的脑袋！”"
D.Strings[93723]="“裤子？在我的宫廷里，我们只穿长袍和护肩。”$b$b格雷斯班爵士闻言打量了一下王座大厅。的确，宫廷里的每一个成员都穿着宽松的曳地长袍，以及装饰着大块晶体的护肩，一条裤子都没看到。他答道……$b$b|cFF600000<这次，格雷斯班爵士会说什么呢？>|r"
D.Strings[93724]="滚开，凡人！这不是你们该来的地方！"
D.Strings[93725]="“您为什么要对我说这种蠢话？”$b$b格雷斯班爵士得到过很多评价，比如下流、放荡、讨厌、变态，甚至还有粗野，却从来没有人说过他“蠢”。这绝对一个突破。他答道……$b$b|cFF600000<现在，格雷斯班爵士该说些或是做些什么呢？>|r"
D.Strings[93726]="你会……为此付出代价的……萨满！你……"
D.Strings[93727]="“你这个无礼的小丑！我要砍下你的脑袋！”$b$b一大群愤怒的守卫抽出了自己的水晶剑。公主非常愤怒，只要她一声令下，格雷斯班爵士就会被剁成肉泥。他必须非常谨慎地做出回答。$b$b|cFF600000<格雷斯班爵士该说些什么来摆脱困境呢？>|r"
D.Strings[93728]="“我想掉件长袍应该也可以吧……但请殿下务必要留着那对护肩。”"
D.Strings[93729]="“唔……呃……格雷斯班爵士？”"
D.Strings[93730]="“可是殿下……您都已经得到我的心了，还要我的脑袋做什么呢？”"
D.Strings[93731]="“啊！别杀我！”"
D.Strings[93732]="你想找荒野神像？我什么都不会说的，闯入者！"
D.Strings[93733]="他美妙的说辞让公主回嗔作喜。她将手按在胸前，仿佛要按住狂跳的心脏，不让它跳出来一样。$b$b“噢，格雷斯班爵士！”她惊呼道。"
D.Strings[93734]="|cFF600000<这个故事看来不行。它既不催人泪下，显然也算不上言情小说。>|r"
D.Strings[93735]="你们神圣的祭坛也挡不住我们，德鲁伊！"
D.Strings[93736]="我什么都不知道，蠢货。我只知道我要拧掉你的脑袋！"
D.Strings[93737]="殿下！来了一个陌生的法师，而且$g他:她;还带着达斯雷玛·逐日者的火焰剑。"
D.Strings[93738]="哈提！他承受了大部分冲击。他……？"
D.Strings[93739]="他还活着，但也快死了。看来这条可敬的狼吸收了泰坦之击的能量，为我们挡住了爆炸。"
D.Strings[93740]="全部擦掉重写"
D.Strings[93741]="虽然哈提是闪电魔法生物，可他的身体容不下这么多能量。我的科学帮不了他。雷霆之火的力量恐怕很快就会流失。"
D.Strings[93742]="游戏结束了，凡人！"
D.Strings[93743]="$n，那是烈焰之击吗？逐日者家族的不灭之焰，烈焰之击？我上次见到那把剑时，还是第三次大战之前，凯尔萨斯王子拥有它的时候呢。"
D.Strings[93744]="科学做不到的事，这位驯兽大师或许能靠本能做到。"
D.Strings[93745]="我们唾弃你们的圣物，德鲁伊。现在，面对我！"
D.Strings[93746]="神像是我们的，$r。我不会招的！"
D.Strings[93747]="卡拉苏斯不怕你，德鲁伊。你想要回那座宝贝神像，就去见他吧。"
D.Strings[93748]="姐妹，其实，游戏才刚开始！"
D.Strings[93749]="抱歉，撤退得太匆忙了！一旦拿走战锤，墓穴就会崩塌。"
D.Strings[93750]="虽然大厅已经塌了，但有成吨的石块与水流保护着提尔。那座监狱也被埋葬了。"
D.Strings[93751]="你是持有白银之手的最佳人选。回去见泰罗索斯吧，把这个好消息告诉他。后会有期。"
D.Strings[93752]="狡猾的卡拉苏斯……我听说过这个名字。他就潜藏在山谷东边的一个山洞里！我们到那儿见！"
D.Strings[93753]="你的顽固只会害死自己！仆从们，攻击！"
D.Strings[93754]="潮汐之石已经碎裂了几百年，而现在它就在那里。"
D.Strings[93755]="你的大恩大德，我和我的人民都无以为报。"
D.Strings[93756]="请尽快返回阿苏纳。那里还有很多事情在等着你，$n。"
D.Strings[93757]="能听见吗，凡人？孟菲斯托斯将我囚禁在山谷的另一端。快！他正在酝酿某种……大绝招。"
D.Strings[93758]="享受这短暂的胜利吧，术士。还没完呢。这只是个开始！"
D.Strings[93759]="真了不起，$n。我从没见过能控制住艾露尼斯的法师。"
D.Strings[93760]="谁都别想摆脱我的看守！"
D.Strings[93761]="等我抓住你，你会求我把你关回牢笼的！"
D.Strings[93762]="德克加尔还在奴役折磨我的同胞。去告诉他们，托林尼尔的盟友不怕他们的渔网和鱼叉！"
D.Strings[93763]="这些蠢货还死抱着他们那个伪神王的承诺不放。幸好你重创了他们。"
D.Strings[93764]="我听说这把利刃的历史可以一直追溯到太古时代，甚至比泰坦还要古老！明智的选择，如果你不想再考虑一下的话。"
D.Strings[93765]="如果你的意志足够坚强，能够控制住它的话，就能将这根法杖的强大力量用于正途。但你也有可能成为它的牺牲品。你确定吗？"
D.Strings[93766]="奥丁的胡子啊，你成功了！"
D.Strings[93767]="这个道标与纳鲁的关系很深，他们的帮助正是我们扭转战局的关键所在！你确定吗？"
D.Strings[93768]="今天，我将泰坦之击授予你，用它去打击那些想要毁灭世界的造物之敌吧。"
D.Strings[93769]="哈提的灵魂永远与这把武器融为一体了。他将成为你在这黑暗年代的忠实伙伴。"
D.Strings[93770]="那扇门被一个邪能符文锁住了！苍穹会真不该用这种魔法！"
D.Strings[93771]="我从来没见过比这位更强大的猎人。你眼光不错，托里姆！"
D.Strings[93772]="回达拉然吧。我去叫休伊。无论我在哪儿，他都能找到我。噢，休伊！"
D.Strings[93773]="这儿的风景不错。唔，现在该仔细看看那本书了。"
D.Strings[93774]="快去告诉大法师瓦格斯，有入侵者！"
D.Strings[93775]="<这个病人被邪能之火严重烧伤。如果你知道怎么治疗这种烧伤，就能治好这个病人了。>"
D.Strings[93776]="治疗病人的烧伤。"
D.Strings[93777]="|TInterface\\Icons\\Spell_Fire_FelPyroblast:20|t%s开始施放|cFFFF0000|Hspell:206219|h[液态地狱火]|h|r。"
D.Strings[93778]="好烫啊！"
D.Strings[93779]="噢，不！拉文德维尔！"
D.Strings[93780]="鉴于这枚戒指就是因我而得名的……是的，我想我应该是知道的。它曾经属于我，那时这些物质财富对我来说还很重要。$b$b不过它早就被收起来了，应该就在王宫里的某个地方。你可以随便找人问问。"
D.Strings[93781]="是的，我知道那枚戒指。我昨天还见过它呢。$b$b可惜这并不是什么好消息。那些可怕的鱼人偷走了许多首饰。我在他们逃跑时干掉了几个，但他们还是抢走了许多珍宝……包括那枚戒指。"
D.Strings[93782]="<嗝儿>……你说什么戒指来着？"
D.Strings[93783]="你知道法罗迪斯之戒吗？"
D.Strings[93784]="这边！我在这儿呢！"
D.Strings[93785]="我现在急需帮助！"
D.Strings[93786]="看来你需要一个打手啊！"
D.Strings[93787]="让我来解决他们！"
D.Strings[93788]="我可不是干这个的料！"
D.Strings[93789]="我快要撑不住了！"
D.Strings[93790]="我这就准备复活桑德兰。等雷霆之怒充能完毕以后，就来找我吧！"
D.Strings[93791]="真是一场刺激的冒险，对吧？"
D.Strings[93792]="好了，休伊。我们回达拉然！"
D.Strings[93793]="抓紧了！我们要着陆了！"
D.Strings[93794]="放松，休伊。放松。"
D.Strings[93795]="<将延命药剂交给辛菲儿。>"
D.Strings[93796]="你想看看我最近的收获吗？"
D.Strings[93797]="那是守卫吗？"
D.Strings[93798]="抱歉……我不能再被抓了……抱歉……请下次再来找我吧……"
D.Strings[93799]="到祭坛去，德鲁伊。那里需要我们。"
D.Strings[93800]="神像……不见了！"
D.Strings[93801]="你究竟是敌是友，$r？如果你自认是森林之友的话，那就证明给我看。帮我击退这股威胁到我家园的腐蚀吧。"
D.Strings[93802]="谢谢你，$r。你已经证明了自己是一个真正的盟友。但愿你能在这片土地上施展力量，对抗邪恶。"
D.Strings[93803]="快，萨满！把祝福之刃给我，桑德兰即将归来！"
D.Strings[93804]="溃烂死亡吧！"
D.Strings[93805]="可怜虫！你简直让我昏昏欲睡。来，让我好好报答你吧！"
D.Strings[93806]="来满足我的饥渴吧，废物！"
D.Strings[93807]="我的部下们！进来！"
D.Strings[93808]="让这些僭越者看看应该怎么战斗！"
D.Strings[93809]="没用的凡人渣滓！这些夜之子连他们自己的王宫都守不住！如果是我的话……"
D.Strings[93810]="啊，我们很快就要奖赏那些“盟友”了。但在此之前，我要亲自给他们收拾烂摊子！"
D.Strings[93811]="你们以为战胜几个被力量烧坏脑子的精灵，就能对抗真正的军团之子了吗？"
D.Strings[93812]="比起恶魔，凡人就是没用！"
D.Strings[93813]="我知道，你现在肯定在想，为什么一个恶魔猎手和一个术士会出现如此远离战场的地方。$b$b但你在这么想的同时，最好也记得闭紧嘴巴，管好你自己的事。"
D.Strings[93814]="又一只扑火的飞蛾！"
D.Strings[93815]="感激我赐予你的速死吧！"
D.Strings[93816]="我跟这个……术士的交易……只是一种权宜之计。$b$b我想要了解这个生物，深入研究它。如果有必要的话，我也会在它对这个世界的过大于功之前杀了它。"
D.Strings[93817]="真可笑！好像你们能阻止仪式似的……"
D.Strings[93818]="注定的覆灭。"
D.Strings[93819]="不可能！你们这些……低贱的……"
D.Strings[93820]="我……重生了！"
D.Strings[93821]="可我……本应该……胜利的……"
D.Strings[93822]="英雄，你再次向我证明了你的勇气。"
D.Strings[93823]="阿斯法尔是个好对手！去证明你的勇气吧！杀了它，我的奖赏就归你了。"
D.Strings[93824]="厄诺克是个丑陋的怪物！这个双头怪一直在永恒狩猎场进行偷猎。去解决这个麻烦！"
D.Strings[93825]="谢谢你，凡人。厄诺克再也不能来此偷猎了。"
D.Strings[93826]="只有战斗力才能证明你是个勇士。让我的雷铸勇士来考验考验你吧！"
D.Strings[93827]="精彩的战斗！干得好，勇士。"
D.Strings[93828]="我打算和风暴峡湾的强大巨龙维瑟尔结盟。从我的兽巢里收集一些蛋来，我想把它送给维瑟尔。但要当心，巢母可不喜欢有人在周围探头探脑的。"
D.Strings[93829]="这些蛋送给维瑟尔正合适。你在收集它们时留下的疤说明你是个真正的勇士。干得好！"
D.Strings[93830]="数百年来，雷铸勇士的传说一直激励着战士们追求卓越。去了解一下这些传说，你或许也会受到鼓舞！"
D.Strings[93831]="了解只是第一步。只有当这些传说在你的心中咆哮时，你才有资格继承我们的衣钵！"
D.Strings[93832]="你在这里能找到的只有死亡！"
D.Strings[93833]="跑吧，带着你们脆弱的生命逃跑吧！"
D.Strings[93834]="那就这样吧，你就烂死在这座殿堂里吧。"
D.Strings[93835]="蠢货！你根本不明白自己惹到了多么强大的力量！"
D.Strings[93836]="督军大人……我们有……客人了……"
D.Strings[93837]="现在，去吧。告诉大地之环，逐风者又复活了。"
D.Strings[93838]="你的武器准备好了吗，$G小子:丫头;？"
D.Strings[93839]="请帮我打磨武器！"
D.Strings[93840]="需要给护甲上上光吗，$n？我这儿有你需要的东西！"
D.Strings[93841]="请帮我的护甲上光吧，克林科！"
D.Strings[93842]="她是黑锋骑士团的榜样，是我们中最优秀的一员，完全配得上这份至高的荣誉。"
D.Strings[93843]="那就这样吧，我走了。"
D.Strings[93844]="不要在我们身后留下线索了，英雄。"
D.Strings[93845]="你们要像对我那样对她行礼，在她的指挥下对抗燃烧军团！"
D.Strings[93846]="你的朋友说的对。我们应该合作。"
D.Strings[93847]="我们必须让这里恢复正常。我还有事要忙呢！"
D.Strings[93848]="使用我的传送台离开车间吧。我们得在那个维库人赶到前把你们送去风暴神殿！"
D.Strings[93849]="走进竞技场，让我们考验一下你的决心吧。"
D.Strings[93850]="我们目前正在进行试炼。你可以选择帮助挑战者完成试炼，或是等到竞技场空出来。"
D.Strings[93851]="请你务必在周围多晃悠几圈，多吸引它们的注意力。"
D.Strings[93852]="交给我吧。回头见，$n。"
D.Strings[93853]="暮光之锤在围攻深岩之洲，我是不会去跟燃烧军团开战的！"
D.Strings[93854]="我们能理解，石母。大地之环会支持你的。"
D.Strings[93855]="去吧，消灭暮光之锤，就能得到我的眷顾！"
D.Strings[93856]="纳迦很快就会用潮汐之石来对付我们了。我们必须快一点。"
D.Strings[93857]="你能阻止暮光之锤？我不信！"
D.Strings[93858]="这就是世界的末日……感觉真不错！哈哈！"
D.Strings[93859]="去告诉伊利达雷，纳萨拉斯是他们的盟友。救出他们，干掉俘虏他们的恶魔！"
D.Strings[93860]="在玛兰评估过你的礼物之前，我不能再跟你说话了。再见。"
D.Strings[93861]="我要碾碎你，就像碾碎你的朋友一样！"
D.Strings[93862]="我是不会去跟那些恶魔扭打的。还是让我们来谈谈怎么赚钱吧！"
D.Strings[93863]="你就是下一个！"
D.Strings[93864]="哇哈哈！我的脸上还需要增加几条疤痕！"
D.Strings[93865]="我要让你身首分离！哇哈哈！"
D.Strings[93866]="我要把你踩得扁扁的！"
D.Strings[93867]="我说了，我一定会把这个情报送到那个格雷迈恩阁下手里的。你不用把这件事告诉其他人，$c。"
D.Strings[93868]="你要臣服于我们的主人！"
D.Strings[93869]="我来送你上路！"
D.Strings[93870]="没有人能抗拒主人的力量！"
D.Strings[93871]="暮光降临了！"
D.Strings[93872]="呼救吧……但是没有人会回应你的！"
D.Strings[93873]="我们是毁灭的使徒！"
D.Strings[93874]="没有人能违抗暮光之锤！"
D.Strings[93875]="末日之下，无有英雄！"
D.Strings[93876]="谢谢！我会留在店里，等到这场混乱结束为止。"
D.Strings[93877]="胡恩找到了艾特洛，这头野兽在与一大群恶魔战斗时受了伤。"
D.Strings[93878]="玛法里奥·怒风焦急地等待着胡恩以及他的牛头人盟军的抵达。克拉苏斯——也就是巨龙考雷斯特拉兹——在天上为他们掠阵。"
D.Strings[93879]="玛法里奥要设法将援军从物质世界之外的青翠领域中带过来。在诵念最后的魔法咒语时，他需要保护。"
D.Strings[93880]="加洛德·影歌在下方的战场上等待胡恩。在调兵遣将之余，他有一个特殊的任务要交给高岭。"
D.Strings[93881]="影歌请求胡恩帮他最后一个忙：击败纳斯雷兹姆领主提克迪奥斯。只要击败了他，恶魔对艾泽拉斯的进攻就会失败，平衡也将恢复。"
D.Strings[93882]="不要把这件事透露给第三个人，$c。常言说的好，机事不密则害成。"
D.Strings[93883]="苍穹奇法会向来欢迎新成员。把握机会，赶快加入我们吧。"
D.Strings[93884]="在战胜邪恶的钢铁部落之后，杜隆塔尔的强大兽人又将目光投向了未来。为了努力卸下前大酋长加尔鲁什·地狱咆哮留下的黑暗包袱，他们选出了一位新领袖，睿智而勇敢的巨魔沃金。可是加尔鲁什的暴行已经再次激化了部落与它的宿敌——联盟之间的矛盾。要想铸就救赎之路，恢复部落的荣耀，就要靠你这样的兽人了。"
D.Strings[93885]="虽然前酋长加尔鲁什·地狱咆哮的失败让牛头人的前景更加光明，但贝恩·血蹄肩上领袖之责依然沉重。他相信牛头人仍然紧密团结在部落的领导核心周围，但他担心在加尔鲁什灾难性的统治结束后，牛头人会失去远见和目标。现在，就要靠像你这样勇敢的牛头人来保护先祖的土地，恢复部族以及……部落的荣光。"
D.Strings[93886]="我们的做法对某些人来说可能有些离经叛道，但我们所掌握的力量是无价的。"
D.Strings[93887]="远离故土荆棘谷多年的暗矛部族希望能在部落诸族中开始新的生活。但是，大酋长加尔鲁什·地狱咆哮的罪行与背叛摧毁了他们对部落的归属感。随着加尔鲁什的失败，足智多谋的巨魔们在英明的领袖沃金的带领下，重新对未来充满了希望。虽然变节的赞达拉部族卷土重来，沃金仍然在为巨魔种族的统一而努力。现在，就要靠你这样勇敢的年轻巨魔来帮助沃金实现这个大胆的统一梦了。"
D.Strings[93888]="作为联盟对抗残酷的钢铁部落的先锋，人类王国暴风城再次大放光芒。在成功攻陷奥格瑞玛，制裁了臭名昭著的大酋长加尔鲁什·地狱咆哮后，瓦里安·乌瑞恩国王陛下誓要铲除艾泽拉斯的一切暴政。如今，远方的地平线上阴云密布，人类与他们的宿敌部落之间摩擦再起。联盟必须再次为那些愿意为正义而战的人们做出表率，肩负起人类荣耀的重任就交给你了。"
D.Strings[93889]="我真不是干这个的料！"
D.Strings[93890]="坚韧不拔的矮人国王，麦格尼·铜须因为一个可怕的诅咒而离开了他的人民，他的躯体熔入了矮人主城铁炉堡的钻石核心。为了避免王位空悬造成内战，矮人们成立了三锤议会，由三个纷争不断的部族共享大权。随着时间的推移，这一联盟已经形成了一种微妙的平衡……"
D.Strings[93891]="可现在，麦格尼·铜须已经摆脱水晶牢笼归来。可是情况并不妙，矮人国王正面临着黑暗且未知的严峻未来。我们还不清楚这个不祥的预言对于议会条约以及矮人的命运有何影响。但可以肯定的是，在这个威胁且变化无常的时代，你必须尽你所能去保护你的人民。"
D.Strings[93892]="在希尔瓦娜斯女王的英明领导下，被遗忘者重新在艾泽拉斯错综复杂的权力格局中占据了一席之地。在瓦格里黑暗而强大的魔法之池下，希尔瓦娜斯壮大了被遗忘者的族群，并为她的人民建起了安全的避风港——幽暗城。可是，昔日的阴影依然纠缠着这位亡灵女王。她曾命令密探执行过许多见不得光的阴谋，例如发生在天谴之门的背叛事件。这些劣迹使得被遗忘者与部落内的其他盟友间仍然充满了恐惧与猜忌。作为希尔瓦娜斯的亡灵大军中最忠诚的一员，你需要帮忙证明被遗忘者的忠诚，并消灭一切敢于威胁女王统治的敌人。"
D.Strings[93893]="高阶女祭司泰兰德·语风的英明领导为暗夜精灵带来了稳定与繁荣。同时，在大德鲁伊玛法里奥·怒风的帮助下，海加尔山的自然环境在大灾变毁灭性的破坏后也重新欣欣向荣起来。强大的世界之树泰达希尔曾经受到了腐蚀，现在它又一次开始治愈与鼓舞战斗中的暗夜精灵的灵魂……古老的半神再次开始在世界上出没。但在泰达希尔薄雾缭绕的枝叶间也并非一派祥和。重新苏醒的半神们感觉到古老的敌人即将卷土重来，带来可怕的毁灭。现在，就像你的同胞们曾做过的那样，你必须做好准备，将艾泽拉斯从毁灭的边缘拯救出来。"
D.Strings[93894]="曾经取之不尽用之不竭的魔力之泉太阳井，如今成为了圣光之源……为洛瑟玛·塞隆领导下的辛多雷带来了克服魔瘾的希望。虽然血精灵参与了击败钢铁部落和加尔鲁什的战役，但他们与联盟和解的前景再次变得迷雾重重。在血精灵的前途未卜之际，你必须做好准备，随时站出来捍卫本族曾经辉煌的文明，安抚迷茫不安的同胞。"
D.Strings[93895]="什么？！这是我的。不准你碰它！"
D.Strings[93896]="愿潮汐之王诅咒你，$r！"
D.Strings[93897]="我们在诺达希尔的另一边等你，大德鲁伊。"
D.Strings[93898]="事情变成这样真是叫人遗憾，可我们该怎么办呢？束手待毙，关门大吉吗？"
D.Strings[93899]="这些卑鄙的家伙在为他们那个该死的女王收集灵魂。他们亵渎了我们的圣地！干掉他们！"
D.Strings[93900]="谢谢你，勇士！多亏了你的帮助，这片土地才得以保存。"
D.Strings[93901]="我这里什么工具都有……只要你出得起钱。"
D.Strings[93902]="我想你应该可以在后面的房间里找到更加合你心意的稀有矿石。"
D.Strings[93903]="<隐蔽地出示你的徽记。>"
D.Strings[93904]="尼索格正在纳斯托蒂山巅的巢穴中对风暴峡湾虎视眈眈。他的存在已经威胁到了托林尼尔的传承。去解决他。"
D.Strings[93905]="虽然尼索格曾经是托林尼尔的一员，但他威胁到了这片土地。你完成了一件壮举，外来者。"
D.Strings[93906]="警告：空袭警报！请立即着陆！"
D.Strings[93907]="大地之环帮了深岩之洲一个大忙。我们会报答你们的。"
D.Strings[93908]="石母有债必偿。"
D.Strings[93909]="作为结盟的标志，我要赐给你们我最伟大的战士。"
D.Strings[93910]="保护好大地之环，阿瓦兰奇奥。让燃烧军团的尸体铺满大地！"
D.Strings[93911]="<他在发烧。如果你懂得治疗高烧的话，就能治好他了。>"
D.Strings[93912]="<她在发烧。如果你懂得治疗高烧的话，就能治好她了。>"
D.Strings[93913]="大地之环对此深表谢意，石母。"
D.Strings[93914]="如你所愿，石母。"
D.Strings[93915]="我们该回艾泽拉斯之心去了，先知。还有很多事情要处理呢。"
D.Strings[93916]="好。你先走，宝贝。我们就来。"
D.Strings[93917]="我不属于这里！我不是战士！我只是个工匠！"
D.Strings[93918]="唔，呃……什么？害怕？哈！$B$B听着，小鬼，我见过的战士多了去了。几只恶魔还吓不倒我。而且，总有人能活下去的。说不定就是我呢。$B$B金币可不会自己送上门来。"
D.Strings[93919]="滚回去，畜生！"
D.Strings[93920]="<鲜血从这个病人身上巨大的伤口中不断涌出。如果你知道如何稳定伤势，你就能医治他。>"
D.Strings[93921]="哟！我还以为自己死定了呢。谢谢你！"
D.Strings[93922]="我是来跟你谈谈你在考古收集方面的需求的。"
D.Strings[93923]="好吧，你也知道，勘测一片区域是很费时间的。$b$b你必须先安放设备，这就要花不少力气，接着研究结果，再尝试靠近你认为可能存在碎片的地方。$b$b我只能希望能有什么东西帮我加快这套流程的操作速度。可我的解释对于纳萨尼斯来说显然太啰嗦了，他根本就不想听。$b$b或许你能给出比我更好的解释。"
D.Strings[93924]="你的考古学水准还达不到我的要求。你看，勘测一片区域是很费时间的。$b$b你必须先安放设备，这就要花不少力气，接着还要研究结果，再尝试靠近你认为可能存在碎片的地方。$b$b我只能希望能有什么东西帮我加快这套流程的操作速度。可我的解释对于纳萨尼斯来说显然太啰嗦了，他根本就不想听。$b$b或许你能给出比我更好的解释。"
D.Strings[93925]="我回守护者圣殿去等你。艾莎拉，欢迎你去那里加入我们。"
D.Strings[93926]="看来有人真的很想挨揍啊！那就让我成全他们吧！"
D.Strings[93927]="你惹错人了！"
D.Strings[93928]="今天算你倒霉！"
D.Strings[93929]="看来这将是漫长的一天！"
D.Strings[93930]="你这么软弱吗，斯莫德隆，居然寻求凡人的帮助？"
D.Strings[93931]="焦血……我的勇士！你要偿命，凡人！"
D.Strings[93932]="我已经跟达瑞妮斯谈过了，她想说的是……"
D.Strings[93933]="你是在送死，萨满。趁早逃跑吧！"
D.Strings[93934]="你竟敢违抗雷奥利斯之子？你死定了！"
D.Strings[93935]="死于凡人之手？这不可能……"
D.Strings[93936]="这些凡人完成了我的要求。可惜你没他们热情！"
D.Strings[93937]="你的勇士完了，派罗斯！"
D.Strings[93938]="消灭篡位者！把他的心脏带回来！"
D.Strings[93939]="好的，我明白了。$b$b我想让你帮我一个忙，$n。带上这套魔化纸笔，去考察一下考古挖掘场。这样，我的纸笔就会记录下你的操作流程。$b$b等你完成任务之后，就把你的发现带回来给我。$b$b如果你还不会考古，就去跟达瑞妮斯谈谈吧。我相信她会指导你成为一名考古学家的。"
D.Strings[93940]="我还记得奥格瑞姆牺牲的那一夜。他在解放最后一个兽人收容所时被长枪刺穿。他在阿拉希的田野上流血而亡之前，将毁灭之锤托付给了我。"
D.Strings[93941]="毁灭之锤不仅仅是一件武器。它是一个象征。它是希望的象征，力量的象征……它是个人也能改变世界的证据。"
D.Strings[93942]="你以为我会坐视你为所欲为吗？听着，凡人，你拼命想要得到的宝物已经臣服于我的意志了！"
D.Strings[93943]="你毫无廉耻，$c。"
D.Strings[93944]="黑暗女王必胜。"
D.Strings[93945]="我诅咒你和你的同伙！"
D.Strings[93946]="女妖之王万岁！"
D.Strings[93947]="我的生命属于被遗忘者。"
D.Strings[93948]="该死！我不会放弃的！"
D.Strings[93949]="要找什么特别的东西吗？"
D.Strings[93950]="大灾变时，我曾在深渊之喉被关押了数周。我一点都不想回去，但我很了解那里。"
D.Strings[93951]="莎拉达尔，潮汐权杖是传说中的神器。全靠它，艾萨拉的追随者才得以在海底生存。"
D.Strings[93952]="它是统治艾泽拉斯水域的生命之杖。在对的人手中，它将成为治疗之泉，而非腐蚀之源。"
D.Strings[93953]="萨满，这里属于艾萨拉。让大海来淹没大地之环真是再合适不过了！"
D.Strings[93954]="在生前，我曾是一个伟大的附魔师。现在，我的灵魂被束缚在我的房子里。$b$b如果能找回我的附魔棒就好了……"
D.Strings[93955]="让大海吞噬你们！"
D.Strings[93956]="让海浪碾碎你们。"
D.Strings[93957]="莎拉达尔是我的，为了女王陛下的荣耀！"
D.Strings[93958]="虽然不再拥有肉体，可拿回附魔棒让我觉得自己又活了过来。$b$b如果你想向我学习附魔技艺，只需要带一些材料来作为交换就行了。"
D.Strings[93959]="你的任务毫无希望，海女巫！无论你如何压迫元素，它们也不会真正臣服于你。"
D.Strings[93960]="你用权杖来诅咒和毁灭。而我们将用它带来净化与治疗！"
D.Strings[93961]="我们怎么还不开炮？快点干活，不然就尝尝我的鞭子！"
D.Strings[93962]="吉斯林就在前面的王座间里。"
D.Strings[93963]="我想看看你有什么附魔。"
D.Strings[93964]="这里的水流完全归她掌控。我们得小心点。"
D.Strings[93965]="拿起权杖，萨满。这是你应得的。"
D.Strings[93966]="如果你想向我学习附魔，尽管开口，再给我带一些材料来就行了。"
D.Strings[93967]="跳跃以移除|cFFFF0000|Hspell:182815|h[石血毒素]|h|r效果。"
D.Strings[93968]="求求你，别动手！我们会加快速度的！"
D.Strings[93969]="自由！甜美的自由，但孟菲斯托斯削弱了我的力量。在那个恐惧魔王回来之前，我们快走吧。"
D.Strings[93970]="喔唷，那个小精灵又回来了。你还真是……顽固。"
D.Strings[93971]="你已经履行了你的义务。按照我们说好的，我会让你品尝燃烧军团的力量。证明你的力量，你就能赢得更多！"
D.Strings[93972]="我们的农场！求求你们！快来人啊！"
D.Strings[93973]="我挡不住他们了！"
D.Strings[93974]="我受够你这家伙了！去死吧！"
D.Strings[93975]="欢迎，$c。你对附魔感兴趣吗，还是来帮忙对抗纳迦的？"
D.Strings[93976]="补给营地也有……我们遭到了轰炸！"
D.Strings[93977]="我会尽力帮助塞纳苟斯的，但我得催你尽快行动了，$n。我担心他可能撑不了多久了。\n\n其它地方也还有事情需要我去关注，我必须尽快离开。但是，我会尽快赶回来的。\n\n"
D.Strings[93978]="诸神在上……哨兵岭的东南方出现了奇怪的建筑！它完全是凭空冒出来的！"
D.Strings[93979]="又有两只恶魔冲哨兵岭来了！准备守住城门！"
D.Strings[93980]="我们的敌人必将葬身火海。"
D.Strings[93981]="你是来向圣光祈祷的吗？还是来接受圣光之道的训练呢？$b$b如果你是来找大主教本尼迪塔斯或是法席恩主教谈话的，那他们都出去执行任务了。"
D.Strings[93982]="法席恩主教也离开了？"
D.Strings[93983]="对，他走得相当匆忙。在处理了针对本尼迪塔斯的指控后，他决定亲自去调查这一事件。但愿他能在执行任务的过程中获得内心的宁静。"
D.Strings[93984]="宁静？出什么问题了吗？"
D.Strings[93985]="这力量……我能控制它。对！我需要它们！"
D.Strings[93986]="对，呃，其实他最近变得有些古怪。总是跟自己争吵，变得有些鬼鬼祟祟，好几次仪式都没有参加。我想是这次调查带给他的压力太大了。但愿他一切安好。"
D.Strings[93987]="<泰林似乎有些神志不清了。>"
D.Strings[93988]="喂食：300份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF远古魔力|h|r"
D.Strings[93989]="我能将熊的狂暴带到战场上！$B$B如果你能攻击敌人并治疗我的话，我可以嘲讽敌人。"
D.Strings[93990]="嗨，$n！我想是时候赶跑那些恶心的梦魇恶魔了！如果你选择我作为帮手，我可以召唤大自然的平衡之力惩击我们的敌人！"
D.Strings[93991]="你好，$n。我很乐意协助你战斗。$B$B如果你愿意让我陪伴你，我可以为你治疗，确保你的生命安全。"
D.Strings[93992]="我可不想错过最后的决战，$n。我将以野性形态冲入战场。选择我吧，我会勇敢地战斗的。"
D.Strings[93993]="我选择你与我一起作战。"
D.Strings[93994]="闪电才是最棒的！"
D.Strings[93995]="超过它们，闪电！"
D.Strings[93996]="再快一点，闪电！"
D.Strings[93997]="他们作弊！"
D.Strings[93998]="闪——电——！"
D.Strings[93999]="真是激动人心。想象一下这里失传了几百年的魔法知识吧。"
D.Strings[94000]="那边……是伊利达雷。还有燃烧军团。"
D.Strings[94001]="我找到了一桶酒！"
D.Strings[94002]="啊！这个桶里有大量魔力酒。去吧，把它放到那条贡多拉小船上。"
D.Strings[94003]="需要我载你一程吗，陌生人？"
D.Strings[94004]="希望你的表现能比上一个偷酒贼强些，愿他安息。"
D.Strings[94005]="明白了！你就是我在等的人。我只需要一条装得满满的小船，然后就能上路了。"
D.Strings[94006]="伊瑟拉让我负责保卫翡翠梦境。我和我的同胞们已经在这个领域中巡行了无数岁月。$B$B我们可以在这场战斗中出一份力。"
D.Strings[94007]="你能帮助我吗？"
D.Strings[94008]="到这座传送门的另一边来找我吧。我得去那边准备仪式。"
D.Strings[94009]="如果你有需要，就在战场上召唤我们吧。我们将一起保护这个世界！"
D.Strings[94010]="做好准备，我的助手。我们要开始抽取这艘船里的能量了。"
D.Strings[94011]="这么多能量！我能应付！我还能吸收更多！"
D.Strings[94012]="啊，所以这才是关键。更多！我还要更多！"
D.Strings[94013]="啊，好多了。我得到所需的能量了。"
D.Strings[94014]="但我还能吸收更多。你的灵魂应该不错！"
D.Strings[94015]="喔喔，看我们找到了什么？一个小偷？"
D.Strings[94016]="小心你想要的……"
D.Strings[94017]="不！我失败了……"
D.Strings[94018]="$G先生:女士;!！我真不想拖累任何人，可是能请你帮我一把吗？"
D.Strings[94019]="让我们一起夺回我们的土地！"
D.Strings[94020]="我愿意为你效劳。"
D.Strings[94021]="谢谢你的好意，但只要黎明还没有到来，我就必须保持警惕。"
D.Strings[94022]="在这个时代，你的身手足以为我们的人民建功立业。或许我们还会见面的。"
D.Strings[94023]="伊格诺斯之眼正在制造梦魇恐魔！"
D.Strings[94024]="这凡人想唤醒那把被诅咒的武器！孩子们，吃掉这个萨满！"
D.Strings[94025]="我的宝贝！我要吃掉你！"
D.Strings[94026]="|TInterface\\Icons\\sha_spell_shadow_shadesofdarkness_nightmare:20|t%s开始施放|cFFFF0000|Hspell:212726|h[梦魇大军]|h|r！"
D.Strings[94027]="那些恶心的恶魔……我还没准备好。"
D.Strings[94028]="元素会指引我们，$n。"
D.Strings[94029]="我能与你并肩战斗吗，勇敢的$r？"
D.Strings[94030]="保重，$n！"
D.Strings[94031]="小心点！外面可不安全。"
D.Strings[94032]="求求你，救救我！"
D.Strings[94033]="战争让我们走到一起。我们必须并肩战斗。"
D.Strings[94034]="你很勇敢，$n。保重。"
D.Strings[94035]="我不会忘记你的好意的。"
D.Strings[94036]="月溪镇的联盟岗哨！我们遭到了攻击！月溪镇被攻占了！"
D.Strings[94037]="让我们再看看那个新法术吧，咒术师。"
D.Strings[94038]="你有进步，继续练习。"
D.Strings[94039]="萨洛拉丝女王和她的姐妹奥蕾塞丝，是害我被邪恶魔力感染的罪魁祸首。"
D.Strings[94040]="她们在帮孟菲斯托斯组建大军，想要攻击恐痕裂隙，偷走魔血祭坛。"
D.Strings[94041]="得在她们动手前先干掉她们。"
D.Strings[94042]="能过来帮我一把吗？"
D.Strings[94043]="帮我好好教训这些家伙！"
D.Strings[94044]="我们必须阻止燃烧军团，为此我不惜一切。没有什么比覆灭燃烧军团更重要！"
D.Strings[94045]="哈！你就是他们派来的人？真走运……"
D.Strings[94046]="我的玩笑怎么样？"
D.Strings[94047]="起飞。"
D.Strings[94048]="说完了？真见鬼。"
D.Strings[94049]="拉一下我的手指！好了，不，等等——不是这根。啊，好了，等等——不——我们待会儿再来试一次吧。"
D.Strings[94050]="|TInterface\\Icons\\ability_hunter_pet_dragonhawk.blp:20|t艾乐瑞瑟开始|cFFFF0000|Hspell:212707|h[召云聚气]|h|r并准备飞向另一个平台！"
D.Strings[94051]="这是我们最黑暗的时刻。"
D.Strings[94052]="燃烧军团是不会罢休的。"
D.Strings[94053]="有什么消息吗？"
D.Strings[94054]="我早就知道这一天迟早会来的。"
D.Strings[94055]="我们必须并肩战斗，否则就会被各个击破。"
D.Strings[94056]="我们绝不能失去希望。"
D.Strings[94057]="不要放弃。"
D.Strings[94058]="我们应该团结起来。"
D.Strings[94059]="我曾与最出色的战士并肩作战。"
D.Strings[94060]="竞技场是对人格的真正考验。"
D.Strings[94061]="先祖护佑着你。"
D.Strings[94062]="像个勇士一样战斗吧。"
D.Strings[94063]="没有人能孤军奋战。"
D.Strings[94064]="你肯定以为这是那个你动动手指就能让我跑断腿的游戏。你搞错了。"
D.Strings[94065]="元素在倾听。"
D.Strings[94066]="跟我谈谈吧。"
D.Strings[94067]="不要让黑暗取得胜利。"
D.Strings[94068]="保持平和的心境。"
D.Strings[94069]="看清你的内心。"
D.Strings[94070]="我曾经头顶一只章鱼在海底呆了几个月。你恶心的闹剧休想让我动容。"
D.Strings[94071]="让我们快点解决这头畜生吧，$n！"
D.Strings[94072]="我已经将具体的地点标注在你的地图上了。去吧，等你赶到时，我应该已经在里头等着你了。"
D.Strings[94073]="在飞去安全地带前感激地叫了两声。"
D.Strings[94074]="拉文德维尔，你不该独自跑出去的。怎么了？"
D.Strings[94075]="为了艾泽拉斯。"
D.Strings[94076]="大地之环长存。"
D.Strings[94077]="万灵与我们同在。"
D.Strings[94078]="过来，让我们谈谈。"
D.Strings[94079]="我会尽我所能来指引你。"
D.Strings[94080]="我们绝不能遗忘。"
D.Strings[94081]="元素永远不会抛弃我们。"
D.Strings[94082]="有信心，就会有出路。"
D.Strings[94083]="牢记这一切。"
D.Strings[94084]="说吧。"
D.Strings[94085]="快说。"
D.Strings[94086]="你就是个笑话。"
D.Strings[94087]="小朋友。"
D.Strings[94088]="小家伙。"
D.Strings[94089]="啊——你好。"
D.Strings[94090]="你不会想看到我发火的。"
D.Strings[94091]="风暴将至。"
D.Strings[94092]="我或许能帮上忙。"
D.Strings[94093]="大海非常不安。"
D.Strings[94094]="万灵指引着你。"
D.Strings[94095]="如果你想进一步学习附魔，我很乐意跟你交流一下心得。"
D.Strings[94096]="别东张西望的，陌生人。"
D.Strings[94097]="这地方不安全，不要乱晃，快走开。"
D.Strings[94098]="除非你能拿出值得我拼命的报酬，否则我是不会动手的。我得开个天价才行。\n\n比如说……足够我用一个月的魔力。\n\n<阿鲁因看起来很得意，好像你不可能同意这个荒唐的价钱似的。>"
D.Strings[94099]="有什么事吗？"
D.Strings[94100]="艾泽拉斯之心里蕴藏着巨大的能量。在艾泽拉斯，恐怕没有比我们现在脚下的土地更接近元素的地方了。"
D.Strings[94101]="你需要帮手吗？但我没有手。"
D.Strings[94102]="控制，还是不控制，这是个问题。"
D.Strings[94103]="我的疯狂是有道理的。"
D.Strings[94104]="我已经准备好与元素领主沟通了。"
D.Strings[94105]="我的瓦拉加尔。"
D.Strings[94106]="你为我带来了怎样的胜利？"
D.Strings[94107]="讲讲你的战斗经历。"
D.Strings[94108]="你将勇气带进这殿堂了吗？"
D.Strings[94109]="为我们谱写胜利的传说吧。"
D.Strings[94110]="祝你从战场上载誉而归。"
D.Strings[94111]="去吧，我的勇士。"
D.Strings[94112]="记住，勇气即汝命。"
D.Strings[94113]="荣耀属于奥丁！"
D.Strings[94114]="我是奥丁的仆人。"
D.Strings[94115]="你有资格获得奥丁的关注吗？"
D.Strings[94116]="愿你在战场上取得荣耀。"
D.Strings[94117]="愿奥丁的注视赐予你力量。"
D.Strings[94118]="努力证明你自己。"
D.Strings[94119]="你是想被……放血吗？"
D.Strings[94120]="我为奥丁而战！"
D.Strings[94121]="我是瓦拉加尔。"
D.Strings[94122]="我为战斗而生！"
D.Strings[94123]="去战场上寻找荣耀吧。"
D.Strings[94124]="希望我们能有机会一较高下。"
D.Strings[94125]="我是索拉丁。"
D.Strings[94126]="我生前死后都见识过许多奇迹。"
D.Strings[94127]="你是在跟阿拉索的国王说话。"
D.Strings[94128]="小心上古之神。"
D.Strings[94129]="你好！祝你一路顺风。"
D.Strings[94130]="有失必有得，有得必有失。"
D.Strings[94131]="英雄，愿你智勇双全。"
D.Strings[94132]="我能选择何时出战，其他人就不行。"
D.Strings[94133]="勇气第一，力量第二，技巧第三。"
D.Strings[94134]="过刚则易折。"
D.Strings[94135]="凡人突袭了我们的阵地！撕碎他们！"
D.Strings[94136]="所有胆敢闯入燃烧军团地盘的人都得死！"
D.Strings[94137]="终于。"
D.Strings[94138]="你会发现被踹回艾泽拉斯并不有趣。"
D.Strings[94139]="想尝尝我的靴子吗？"
D.Strings[94140]="别废话了。"
D.Strings[94141]="我们还有任务呢。"
D.Strings[94142]="你想要本书吗？"
D.Strings[94143]="要我帮你查点什么吗？"
D.Strings[94144]="与智慧同行。"
D.Strings[94145]="世界就是最好的导师，我们都是它的学生。"
D.Strings[94146]="你干嘛不找本好书来读读呢？"
D.Strings[94147]="我准备要结账了。"
D.Strings[94148]="有消息吗？"
D.Strings[94149]="我们必须克服过去的错误。"
D.Strings[94150]="那是……？是它！"
D.Strings[94151]="赞美暗夜井……"
D.Strings[94152]="求求你……"
D.Strings[94153]="我已经喝不下了！"
D.Strings[94154]="终结这种痛苦吧……"
D.Strings[94155]="我真不知道该怎么感谢你才好！"
D.Strings[94156]="我还以为自己死定了呢。"
D.Strings[94157]="他们怎么能让我们承受那种痛苦？"
D.Strings[94158]="谢谢，谢谢，谢谢你！"
D.Strings[94159]="我还以为自己再也尝不到这种味道了。"
D.Strings[94160]="大地之环的萨满，今天我们济济一堂，庆祝一个新同盟的诞生。"
D.Strings[94161]="今天，我们将见证预言的实现。"
D.Strings[94162]="大地之环的先知联合了四大元素领主，一同拯救艾泽拉斯！"
D.Strings[94163]="燃烧军团必败。恶魔绝对不是元素之怒的对手！"
D.Strings[94164]="呸！那个传送门的基础就大错特错了。它对于干涉毫无抵抗力。无论这是谁造的，都应该挖个地洞钻进去。"
D.Strings[94165]="所以说，阿克萨拉克斯是这群恶魔的头儿？这真是个出人意料的好机会。"
D.Strings[94166]="这都是什么乱七八糟的？他们管这叫仪式？我要召唤火雨落到这群艾瑞达头上，反正这个仪式也不可能更糟糕了。"
D.Strings[94167]="唔，这可真意外……让我再试试。"
D.Strings[94168]="那些强大的恶魔都藏到哪儿去了？"
D.Strings[94169]="又是个小鬼？！难以置信。"
D.Strings[94170]="下次我一定能搞定。"
D.Strings[94171]="伽留斯·米尔摩抱怨地嘟囔着。"
D.Strings[94172]="你真以为这么珍贵的东西会无人看守吗？"
D.Strings[94173]="对于你们那小得可怜的大脑来说，某些秘密太过重大了……"
D.Strings[94174]="我的兄弟提到过一条叫兰妮苟萨的巨龙，她就在龙眠神殿。你去找她，我来召集部队。"
D.Strings[94175]="你好，$c。我感觉到你有事要找我。"
D.Strings[94176]="泥土与岩石将拱卫我们的世界不受恶魔侵袭！"
D.Strings[94177]="确实如此。我在找一个名叫加弗德的圣骑士。"
D.Strings[94178]="啊，是的！他是个非常好学的人，对泰坦守护者提尔的故事特别感兴趣。$b$b我把提尔与迦拉克隆战斗的故事告诉了他，还有卡雷苟斯是怎么在迦拉克隆之墓看到提尔的断手的。加弗德就非常激动地离开了。$b$b他没事吧？"
D.Strings[94179]="说实话我也不知道，我会把他找出来的。"
D.Strings[94180]="与你并肩战斗是我的荣幸，先知。我们将一起让恶魔灰飞烟灭！"
D.Strings[94181]="南方援军营地！我们挡不住他们多久！一个恐惧魔王就干掉了我将近一半的人手！"
D.Strings[94182]="摩尔森农场里也有恶魔！快离开这儿！到处都是恶魔！"
D.Strings[94183]="迦拉克隆之墓可能很危险。追踪法术或许能派上用处。"
D.Strings[94184]="猎珠人菲恩怀疑地瞪着你。"
D.Strings[94185]="猎珠人菲恩咯咯笑了起来，然后可惜地摇了摇头。"
D.Strings[94186]="猎珠人菲恩在鼻子前挥了挥手，大声抱怨起来。"
D.Strings[94187]="啊，你来了。一切都准备好了。"
D.Strings[94188]="我们绝不容许内部有不端行为，$n。但如果你对大法师瓦格斯的指控最终被证明是恶意诽谤，那后果也将很严重。"
D.Strings[94189]="你的朋友来找过答案，提尔之火里的回忆涌入了他的头脑。他得知了提尔与迦拉克隆的上古大战，以及他留在龙口中的手臂。"
D.Strings[94190]="别再跟着我了！"
D.Strings[94191]="安斯雷姆，我已经跟踪$n一段时间了，这一指控并非无中生有。我也注意到大法师瓦格斯的举动很诡异。"
D.Strings[94192]="我也是，他最近可是忙得很。"
D.Strings[94193]="我准备好了。开始施法吧。"
D.Strings[94194]="啊！！阻止他们！快阻止他们！"
D.Strings[94195]="去吧，先知，作为元素的勇士，去击败燃烧军团吧！"
D.Strings[94196]="我们还有很多事要做。顾问塞维尔正在等你。他正在为对抗燃烧军团而做准备。"
D.Strings[94197]="大地之环也与你同在，我的朋友。"
D.Strings[94198]="阿历克斯顿的农场也被攻占了！我们躲进了畜棚里！"
D.Strings[94199]="|TINTERFACE\\ICONS\\warrior_talent_icon_thunderstruck:20|t尼索格施放了|cFFFF0404|Hspell:212841|h[碎裂闪电]|h|r！"
D.Strings[94200]="我们又在海滩上发现了一个营地！是大型营地！"
D.Strings[94201]="看来法布隆农场需要帮助！立刻派出地面部队！"
D.Strings[94202]="燃烧军团再次入侵艾泽拉斯了。世界一片混乱，但深岩之洲所面临的威胁更加迫切。$b$b我是不可能丢下门口咆哮的恶狼去跟你打豺狼的！"
D.Strings[94203]="梅瑞尔清了清嗓子，咳嗽起来。"
D.Strings[94204]="抵抗军万岁！"
D.Strings[94205]="莲花必将再次盛开！"
D.Strings[94206]="打倒权贵！"
D.Strings[94207]="他咳得越来越厉害了。"
D.Strings[94208]="唔，或许你该休息一下，梅瑞尔。"
D.Strings[94209]="你听起来不太好。"
D.Strings[94210]="我好像在其他地方见过你，$n……"
D.Strings[94211]="我听说过你的伟大事迹，$n。"
D.Strings[94212]="你的高超实力已经在肯瑞托里传开了，$n。我期待着你的表现！"
D.Strings[94213]="梅瑞尔，休息一下吧！$n，我很快就去阿苏纳找你。"
D.Strings[94214]="那是一条银色的手臂，由提尔多年的老友尤顿所铸造。提尔发现洛肯背叛的证据之后，是尤顿留下来挡住了那位堕落守护者的追兵。"
D.Strings[94215]="好的，我会的。谢谢你来接我的班，$n。"
D.Strings[94216]="梅瑞尔剧烈地咳嗽并呕吐起来。"
D.Strings[94217]="经过多年的努力，我已经完成了我的鱼人心灵融合术。"
D.Strings[94218]="你的朋友找到了尤顿，但提尔之火没有告诉他，洛肯用诅咒扭曲了尤顿的心智。那圣骑士冲向南边的裂谷，结果只是去送死。"
D.Strings[94219]="|TInterface\\Icons\\ability_hunter_pet_spider.blp:20|t %s宣布|cFFF00000|Hspell:212364|h[喂食时间]|h|r到了。"
D.Strings[94220]="你有什么需要吗？"
D.Strings[94221]="那个刻薄的桶匠已经咽气了。"
D.Strings[94222]="刃豹在广场上徘徊。"
D.Strings[94223]="猫头鹰在黄昏下啼鸣。"
D.Strings[94224]="卡德加，谢谢你能这么快赶来！他恶化得很快！"
D.Strings[94225]="唔。这是魔法疾病。你找我来是对的，拉文德维尔。"
D.Strings[94226]="不用说了。"
D.Strings[94227]="我们开始吧。过来，泰林。"
D.Strings[94228]="塔莉萨，你不是吧？把时间浪费在这……这家伙身上！"
D.Strings[94229]="<一个模糊的身影在你的眼角中闪烁，仿佛来自被遗忘的时代的回忆。他对你的出现毫无反应。>"
D.Strings[94230]="<一个模糊的身影在你的眼角中闪烁，仿佛来自被遗忘的时代的回忆。她对你的出现毫无反应。>"
D.Strings[94231]="我一直在找你。你找到……噢不……"
D.Strings[94232]="啊啊啊！！啊！"
D.Strings[94233]="我也感受过……"
D.Strings[94234]="他被流放的日子……"
D.Strings[94235]="这种饥渴……和恐惧……"
D.Strings[94236]="<一个幽灵般的身影坐在楼梯上，那是来自过去的模糊记忆。他认出了你手中的法杖，阴森森地向你点了点头。>\n\n你还是没有改变主意吗，阿洛迪？让我们把自己所有的力量注入你那根法杖里不会让你感到不安吗？"
D.Strings[94237]="这种迷惘……这种愤怒……——"
D.Strings[94238]="塔莉萨！你还好吗？"
D.Strings[94239]="我是来寻求议会的智慧的。"
D.Strings[94240]="很好，法师。我会按照你的要求做……不过，请你小心一点。至今还没有一个凡人拥有过如此强大的力量。"
D.Strings[94241]="我真的非常抱歉。你朋友的尸体看起来都支离破碎了。这是怎么……"
D.Strings[94242]="快走！洛肯的诅咒迫使我屠杀提尔的盟友。在他来取走提尔之火前，我得保护好它！"
D.Strings[94243]="这个巨人说的精华是什么？我得跟你谈谈，$n。"
D.Strings[94244]="告诉我，发生什么事了？你在找什么，$n？"
D.Strings[94245]="加弗德身上有一朵提尔的精华之火。看来是尤顿杀了他并抢走了火花。我需要那朵火花才能得到提尔的战锤。"
D.Strings[94246]="这是个正当的理由，英雄。我会帮你对付强大的尤顿，$n。做好准备！"
D.Strings[94247]="<这个侏儒在你的意识角落里闪烁着，他是来自另一个时代的、已经快被遗忘的影子。看到你手中的法杖时，他顿时神采飞扬起来。>\n\n是时候了吗，阿洛迪？你的法杖准备好了？"
D.Strings[94248]="这可是我压箱底的本事了，老朋友。燃烧军团绝对猜不到自己是被什么攻击了！"
D.Strings[94249]="我刚读了一篇有趣的论文，是有关低等的狗头人的。现在，这些生物比表面上看起来要凶猛得多。"
D.Strings[94250]="再帮我找个狗头人样本来。我想验证一下这个假设。"
D.Strings[94251]="当然，对于我们学院来说，最紧迫的问题就是海巨人的不断进攻。"
D.Strings[94252]="不幸的是，我们的图书馆里比较缺乏这类生物的信息。"
D.Strings[94253]="帮我找一本有关海巨人的书。什么都行。"
D.Strings[94254]="最后，我想研究一下巨龙。准确地说，是蓝龙。"
D.Strings[94255]="<那个……懒洋洋地躺在温室屋顶上的，是一头龙吗？这头生物的存在似有似无。她似乎不属于这个世界，而是你的法杖——黑檀之寒的回忆。一位来自被遗忘的时代的巨龙顾问。>"
D.Strings[94256]="目前，我们和我们的北方邻居相处得还不错。但如果我们的友谊破裂了，那了解一下他们的战斗方式也没什么坏处。"
D.Strings[94257]="<你看见了一头巨大的蓝龙，懒洋洋地躺在温室屋顶上。她似乎不属于这个世界，而是你的法杖——黑檀之寒的回忆。让你惊讶的是，这个强大的生物转过头来看着你，缓缓开口了：>$b$b伟大的阿洛迪归来了，想寻找更强大的力量。告诉我，法师，议会考虑过将如此强大的力量赋予一个凡人，会造成怎样的影响吗，嗯？$b$b如果他们亲爱的守护者背叛了他们怎么办？$b$b我会盯着你的……"
D.Strings[94258]="我听说那个密探已经来了，而且他很英俊。"
D.Strings[94259]="今晚的聚会好像有几张新面孔啊……"
D.Strings[94260]="唔，我刚听说一个有关这次聚会的新传闻。听说我们中间有个燃烧军团的密探，这家伙是来确认我们的忠诚度的！"
D.Strings[94261]="艾利桑德邀请来参加聚会的那个人？这可不是我说的啊，但那家伙真的是燃烧军团的密探。"
D.Strings[94262]="有人说，有个燃烧军团的成员匿名参加了这次聚会……"
D.Strings[94263]="真是太刺激了！听说有个神秘的客人参加了这次聚会！等等，什么？你说那是个密探……"
D.Strings[94264]="有关聚会新客人的传闻？我听说那是燃烧军团的成员，是来监视我们的！"
D.Strings[94265]="小心点。据说燃烧军团派了一个密探潜入了这次聚会。"
D.Strings[94266]="你看到外面那些恶魔了吗？他们在监视我们呢！我只知道，我们中间有个密探。"
D.Strings[94267]="我在别处听说那个密探不是女性。"
D.Strings[94268]="有个客人说她看见他和大魔导师一起走进了庄园。"
D.Strings[94269]="有个乐师说，他一直在打听这一带的消息。"
D.Strings[94270]="他们说那个密探已经来了，而且她是个大美人。"
D.Strings[94271]="有人说我们的新客人不是男性。"
D.Strings[94272]="有个客人先前看到她是和艾利桑德一起到达的。"
D.Strings[94273]="我听说有个女人一直打听贵族区的情况……"
D.Strings[94274]="我听说那个密探穿着一件浅色上衣来参加今晚的聚会。"
D.Strings[94275]="那个间谍肯定更喜欢浅色的上衣。"
D.Strings[94276]="我无意中听到那个密探说，深色上衣和银色的头发太不配了，所以自己从来不穿。"
D.Strings[94277]="大家都在说那个密探今晚没有穿深色的上衣。"
D.Strings[94278]="那个密探喜欢深色的上衣……就像夜空一样深沉。"
D.Strings[94279]="我听说那个密探今晚所穿的外衣是浓密的暗深色。"
D.Strings[94280]="传说那个密探会避免穿浅色的服装，以便更好地混入人群。"
D.Strings[94281]="那个间谍肯定更喜欢深色的服装。"
D.Strings[94282]="我听说那个密探总是带着手套。"
D.Strings[94283]="有人说那个密探带着手套，以掩盖手上明显的疤痕。"
D.Strings[94284]="有传言说那个密探总是带着手套。"
D.Strings[94285]="我听说密探都会小心隐藏自己的双手。"
D.Strings[94286]="我听说那个密探不喜欢戴手套。"
D.Strings[94287]="有传言说那个密探从来不戴手套。"
D.Strings[94288]="你知道吗……我在后头的房间里发现了一双多余的手套。那个密探现在可能就赤着双手在这附近转悠呢。"
D.Strings[94289]="我听说那个密探会尽量不戴手套，以防在快速行动时受到阻碍。"
D.Strings[94290]="可别说是我告诉你的……那个密探伪装成了炼金师，腰带上挂着药水。"
D.Strings[94291]="我听说那个密探买了一些药水……以防万一。"
D.Strings[94292]="我好像看到那个密探的腰带上挂着一瓶绿色的药水。"
D.Strings[94293]="有人告诉我，来的密探带着一瓶绿色的药水或是类似的东西。我很好奇那是干什么用的？"
D.Strings[94294]="我听说那个密探随身带着药水，这是为什么呢？"
D.Strings[94295]="我敢肯定，那个密探的腰带上挂着药水。"
D.Strings[94296]="这是你逼我的！我要杀了你！"
D.Strings[94297]="你很强！或许你能终结我无尽的守护。"
D.Strings[94298]="好痛苦！诅咒解除了……只是暂时的。"
D.Strings[94299]="洛肯的魔法不会让我死的。时间有限，我很快就会再次发狂。"
D.Strings[94300]="这就是提尔之火。拿上它快跑吧！让他的这段记忆活下去。"
D.Strings[94301]="为了提尔！"
D.Strings[94302]="我听说那个密探总是带着一个魔法袋。"
D.Strings[94303]="我听说那个密探的腰包上绣着精美的丝线。"
D.Strings[94304]="我听说那个密探根本没带任何药水。"
D.Strings[94305]="我的一个朋友之前从一个密探的腰带上偷走了一瓶粉色的药水。无论那个密探现在在哪儿，身上肯定都没有粉色药水了！"
D.Strings[94306]="据说那个密探喜欢读书，而且总是随身携带至少一本书。"
D.Strings[94307]="我听说那个密探的腰带上，总是挂着一本写满机密的书。"
D.Strings[94308]="我听说那个密探的腰包里装满了摆阔用的金币。"
D.Strings[94309]="一个朋友说，那个密探喜欢黄金，所以在腰包里装满了金币。"
D.Strings[94310]="那好吧。用这股强大的力量去对付提瑞斯法的敌人吧！"
D.Strings[94311]="这些灯指引我来到这里。我只希望我回去时还能一路平安……"
D.Strings[94312]="有个乐师告诉我，她看到那个密探扔掉了身上的最后一瓶药水，已经没有药水了。"
D.Strings[94313]="我听说那个密探没带什么绿色药水。"
D.Strings[94314]="我听说那个密探今天穿着长袖外套。"
D.Strings[94315]="上半夜的时候，我正巧瞥见那个密探穿着长袖衣服。"
D.Strings[94316]="我的一个朋友说那个密探穿着长袖衣服。"
D.Strings[94317]="有人说，那个密探今晚穿了一件长袖的衣服。"
D.Strings[94318]="我听说那个密探喜欢清凉的空气，所以今晚没有穿长袖衣服。"
D.Strings[94319]="我听说密探喜欢穿短袖服装，以免妨碍双臂的活动。"
D.Strings[94320]="我的一个朋友说，她看到了密探穿的衣服，是一件短袖上衣。"
D.Strings[94321]="有人告诉我那个密探讨厌长袖的衣服。"
D.Strings[94322]="我听说那个密探喜欢穿斗篷。"
D.Strings[94323]="有人提到那个密探之前是穿着斗篷来的。"
D.Strings[94324]="<一个模糊的身影静静地坐在公园里，就像一个来自过去时代的、早已逝去的人物留下的模糊记忆。她似乎认出了你的法杖，所以热情地欢迎了你，将你当做了别人。>$b$b你好啊，阿洛迪，老朋友！过来跟我坐坐，好吗？人生中最大的享受莫过于带着一本熟悉的老书在公园里坐上一天了。$b$b我想我应该在这里栽一棵树苗，这样过上几年，法师们就可以坐在小树的树荫下了。"
D.Strings[94325]="我听说那个密探讨厌斗篷，所以没有穿。"
D.Strings[94326]="我听说那个密探在来这里之前，把斗篷忘在王宫里了。"
D.Strings[94327]="如果必须这么做的话，我会帮忙的。你的那根法杖已经集中了那么多力量——我很担心你的命运！"
D.Strings[94328]="如有需要，我可以送你回达拉然，稍后再来找加弗德的遗体。"
D.Strings[94329]="我们会跟紧你的，勇士。让我们解决这头畜生吧！"
D.Strings[94330]="我是提尔近卫。我们是一支秘密的圣骑士组织，很久以来一直在守卫着一个天大的秘密。不幸的是，最近一系列变故让我们无法再隐藏下去了。"
D.Strings[94331]="秘密组织？"
D.Strings[94332]="<一个幽灵般的身影在堡垒中徘徊，那是来自昔日达拉然的久远回忆。这个纤瘦的身影认出了你的法杖，把你当成了别人。她那半开半阖地眼睛慵懒地看着你。>$b$b大法师阿洛迪。所以你要去对付卡萨纳提尔了？议会的其他人都无视了我的警告。$b$b很好，我是不会阻止你去自杀的。如果你需要我助你一臂之力，尽管开口。$b$b<菲欧拉忧郁地啜了一口红酒，不再看你了。>"
D.Strings[94333]="很好。好好表现吧，法师。"
D.Strings[94334]="燃烧军团抓走了丝黛拉苟萨的一窝蓝龙宝宝！救救它们，让我们盟友的子嗣更加繁茂吧！"
D.Strings[94335]="那些雏龙太小太无助了。燃烧军团真是卑鄙，居然捕食弱者！"
D.Strings[94336]="军团的每支分遣队都会从灵魂引擎中抽取能量。去破坏那个邪恶的机器，干掉那个保护它的艾瑞达！"
D.Strings[94337]="太好了！在重新发动引擎前，他们得先修复它。你为我们争取了宝贵的时间。"
D.Strings[94338]="我们能用合适的内脏酿造一种强大的恶魔侦测药剂。帮我去收集材料，然后我们就能一起夺回法罗纳尔了！"
D.Strings[94339]="你显然不怕干脏活儿。干得好。"
D.Strings[94340]="有时我真希望加鲁霍德的研究能不要用这么……难吃的材料。唉，这些应该够用了。谢谢你。"
D.Strings[94341]="燃烧军团真傲慢，他们玷污了我的土地，还自以为很安全。"
D.Strings[94342]="他们的部队正在法罗纳尔集结。去先发制人吧，在他们深入阿苏纳前打残他们！"
D.Strings[94343]="这下燃烧军团该明白了，只要他们敢在阿苏纳露面，就会遭到无情的猎杀。干得好！"
D.Strings[94344]="第20天：今天捕获了一个新实验体。我把他称为16号。他看起来有些不一样。"
D.Strings[94345]="<一个依稀可辨的身影躲在旅店后头，埋头看着卷轴。这个高等精灵是来自另一个时代的回忆。他认出你的法杖，对你平等相待。>\n\n真理的时刻来临了。你准备好了吗，阿洛迪？你确定自己能控制这么强大的力量吗？"
D.Strings[94346]="哇……我没想到蛛后也会出现……我这就把你拉出来。抓紧了！"
D.Strings[94347]="总有一天，我们都要面对自己的心魔。你总比我强。"
D.Strings[94348]="<一个幽灵般的侏儒身影浮现在你面前，这是来自过去的久远回忆。她正在全神贯注地施放一个强大的魔法。你靠近时，她把你当做了其他人。>\n\n阿洛迪！你回来了。让我看看你那根法杖。好，好……我当然会帮你的。但你该去听听议会的其他人在背后是怎么议论你的。幸好他们还需要你。"
D.Strings[94349]="嘀嗒，嘀嗒！"
D.Strings[94350]="我希望你知道自己在做什么。可如果你不知道的话……至少我们能看一场烟火。祝你好运！"
D.Strings[94351]="传送门马上就好！"
D.Strings[94352]="南门！平原上又出现了一只恶魔！"
D.Strings[94353]="你们的灵魂太容易被腐蚀了，凡人。"
D.Strings[94354]="恶魔朝东北边的城墙那儿去了！"
D.Strings[94355]="今天，我们对梦魇中隐形的敌人造成了沉重打击。"
D.Strings[94356]="但是，梦魇之王萨维斯依然活着。只有击败他，艾泽拉斯才能重获安全。"
D.Strings[94357]="这绝对安全！噢，对了……小心下面那些蜘蛛。无论你做什么，都不要松开绳索！"
D.Strings[94358]="为此，我把我的祝福赐予你。用我的力量保护荒野吧。"
D.Strings[94359]="谢谢，梦境林地的德鲁伊。愿你们在新大德鲁伊的领导下欣欣向荣。"
D.Strings[94360]="岁月不饶人啊，$n。$b$b<菲尔麦夫虚弱地咳嗽起来。>$b$b我想我是要死了。"
D.Strings[94361]="等等。你找到的是日记吗？这可能就是我们要找的！"
D.Strings[94362]="我们的角鹰兽进食充分，你想去哪都可以把你驮过去。"
D.Strings[94363]="展翅高飞的感觉总是这么美妙！"
D.Strings[94364]="展翅高飞的感觉总是这么美妙！你做好出发的准备了吗？"
D.Strings[94365]="还没有，我需要更多的时间。"
D.Strings[94366]="这样的日子总会让我渴望舒适的家。"
D.Strings[94367]="就是这头野兽杀害了你的法师，这是它的脑袋。"
D.Strings[94368]="我们继续走吧。"
D.Strings[94369]="打散回忆，我们就能前进了。"
D.Strings[94370]="我……我要失控了……"
D.Strings[94371]="你是在哪儿找到这头野兽的？我从没见过这样的动物。$B$B对于经验不足的人来说，这头地狱犬可能和其他爪牙没什么区别。但只要仔细检查它的嘴巴，你就会发现它多了一副利齿。$B$B我确信，这头野兽就是害我们的同伴丧命的罪魁祸首。$B$B请代我向希莱尔道歉吧。这年头，怎么小心都不为过啊。"
D.Strings[94372]="这正是我在做的事。"
D.Strings[94373]="蕾诺拉，放了那头野兽吧。它对我们没有威胁。"
D.Strings[94374]="我们该策划对苏拉玛的袭击！"
D.Strings[94375]="织梦者已经守护了这片林地无数纪元。我们奉行塞纳留斯之道，保护着瓦尔莎拉的森林。"
D.Strings[94376]="我们教派里，还有很多人记得当初莎拉达希尔在此扎根的情景。我们看着它经历诸多纪元，成长为俯视这座山谷的参天大树。我们受到它的祝福，在它的树荫庇护下生活多年。"
D.Strings[94377]="理解自然，就是理解万物的伟大循环。盛开的花朵终将零落成泥，并孕育新的种子。太阳每天落山，都是为了明日的再度升起，并带来新的生命。我们的教派就致力于理解并维护这种循环。"
D.Strings[94378]="你知道“alara'shinu”吗，德鲁伊？它的意思是，发现缺憾之美。秉持这个理念生活的人，能够理解自然的变幻无常，接受生死的循环往复，并从中收获快乐。"
D.Strings[94379]="你在此休息时请不要挑起是非。梦境林地是我们所有同胞的圣地。"
D.Strings[94380]="织梦者不在意你们凡人之间的差异，$r。在这里，大家都是德鲁伊。在这里，我们为共同的事业团结一心。"
D.Strings[94381]="梅瑞尔咳嗽了两声，打起了寒战。"
D.Strings[94382]="剧烈的咳嗽令梅瑞尔痉挛了起来。"
D.Strings[94383]="|TInterface\\Icons\\sha_spell_fire_blueimmolation_nightmare:20|t你受到了|cFFFF0000|Hspell:211471|h[轻蔑之触]|h|r的影响！"
D.Strings[94384]="梅瑞尔按着胃部呻吟着。"
D.Strings[94385]="梅瑞尔呛出了胆汁。"
D.Strings[94386]="它跑出来了！快逃命吧！是……是……坚果！"
D.Strings[94387]="这应该能骗过那些语无伦次的醉酒客人，可明眼人一定能看穿它。一旦幻象消失，守卫就会扑上来的。"
D.Strings[94388]="动手吧，我准备好接受伪装了。"
D.Strings[94389]="这是个极其危险的提议。我怎么知道你真的是凡瑟尔派来的？"
D.Strings[94390]="雪羽从空中俯冲而下。"
D.Strings[94391]="<出示你的徽记。>"
D.Strings[94392]="<展示你的忠诚。>"
D.Strings[94393]="大法师瓦格斯一边颤抖一边低声胡言乱语着。"
D.Strings[94394]="我……别处需要我。"
D.Strings[94395]="拜尔班主人！敌人……他们来了！"
D.Strings[94396]="闭嘴！别再来打扰我了，你这是在浪费我的时间！"
D.Strings[94397]="我们摆脱了主人！刻薄的拜尔班消失了。"
D.Strings[94398]="（切割）"
D.Strings[94399]="伊斯佩普一直很努力，可主人总是大叫大嚷的……"
D.Strings[94400]="不！主人找到我们了，他要把我们变成午餐肉了！"
D.Strings[94401]="拿起驭风大师的图腾。"
D.Strings[94402]="我或许会对你的建议感兴趣……如果有足够的刺激的话。"
D.Strings[94403]="<给阿鲁因看看你的徽记。>"
D.Strings[94404]="你做好进入竞技场，在无尽的战斗中赢得荣耀的准备了吗？"
D.Strings[94405]="看看它们的小脸蛋！我快要被萌死了！"
D.Strings[94406]="你别光说不练啊。"
D.Strings[94407]="嘻嘻！"
D.Strings[94408]="你们这些粗心的小家伙，我要给你们包上爱的绷带！"
D.Strings[94409]="咸鸡？"
D.Strings[94410]="矮脚狗，我说的对吗？"
D.Strings[94411]="汪汪。"
D.Strings[94412]="可他那么可爱！"
D.Strings[94413]="噢。"
D.Strings[94414]="叛、叛徒……"
D.Strings[94415]="我得回到城里去，越快越好。"
D.Strings[94416]="还有呢？"
D.Strings[94417]="别遮遮掩掩的了。我知道你是来为大魔导师刺探情报的。"
D.Strings[94418]="你怎么敢把我说成那种人，$n？你知道我是谁吗？我根本就不认识你……"
D.Strings[94419]="喂喂，别急着下结论，$n。我们为什么不找个私密空间好好谈谈这个问题呢……"
D.Strings[94420]="走开吧，朋友。我不想跟你打交道。"
D.Strings[94421]="我需要飞到阿莎曼之墓。"
D.Strings[94422]="愿苏拉玛长盛不衰，朋友。"
D.Strings[94423]="这个聚会真不错，不是吗？"
D.Strings[94424]="今天的乐师很不错啊，不是吗？"
D.Strings[94425]="你这是在污蔑我，$n。你到底是谁？"
D.Strings[94426]="$n，你以为我会亲自充当密探？或许我们反而应该好好看清你到底是谁！"
D.Strings[94427]="我才不是呢！$n，你以为你是谁？！"
D.Strings[94428]="<角鹰兽盯着你看了一会儿，然后发出了尖叫。>"
D.Strings[94429]="我想回梦境林地。"
D.Strings[94430]="我不知道你是怎么发现我的，但你可以去死了！"
D.Strings[94431]="大部分萨满都喜欢狼，可这位却喜欢……矮脚狗？你可能以为她来错地方了，但她到目前为止，已经击败了所有的挑战者！谁能来打倒这些好斗的小家伙呢？"
D.Strings[94432]="这真是一场技术高超、战术得当，而且十分可爱的战斗！保持下去吧，孩子，你前途无量……顺便帮我大赚一笔！"
D.Strings[94433]="真可怕……"
D.Strings[94434]="我认得那对匕首，$n。它们割断了我的国王和朋友的喉咙。请你……把它们收起来。"
D.Strings[94435]="$n，你的那对匕首——曾冷血地杀害了莱恩·乌瑞恩。一看到它们，我的心情就变差了。"
D.Strings[94436]="这真是迦罗娜的那对匕首吗，$n？我在卡拉赞的图书馆里见过她用它们撕碎一头恶魔。要是我能早点预料到……"
D.Strings[94437]="我的生命属于大魔导师和她的人民。"
D.Strings[94438]="荣耀属于夏多雷。"
D.Strings[94439]="我随时为你效劳。"
D.Strings[94440]="我想跟监督者伊尔维尔谈谈。"
D.Strings[94441]="怪物……"
D.Strings[94442]="让我们到别处去玩吧。"
D.Strings[94443]="快躲起来！他们会吃掉你的！"
D.Strings[94444]="你的邪恶魔法就是个怪胎！"
D.Strings[94445]="我早说过神殿不安全，你就是不信！看看现在！"
D.Strings[94446]="你！下课后，我们去旗杆那儿谈谈。"
D.Strings[94447]="我只是执行命令而已！别伤害我！"
D.Strings[94448]="$n！你真的拿到弑君者了？我还是个小丫头的时候，我奶奶给我讲过它们的故事。暴风城的国王捂着自己的喉咙，殷红的鲜血溅上了城堡的白色石块……那时，我一到晚上就会躲进被子里，以为到处都是刺客。"
D.Strings[94449]="不要拿魔杖乱指！"
D.Strings[94450]="我正在努力学习呢。"
D.Strings[94451]="蓝月女士！$n用魔杖打我！"
D.Strings[94452]="别闹！"
D.Strings[94453]="如果你再这么做，你就要有麻烦了。"
D.Strings[94454]="在发射前，别忘了先瞄准。"
D.Strings[94455]="决定了。我今天要给你打零分。"
D.Strings[94456]="打中老师的扣五十分。"
D.Strings[94457]="再这样下去，我要罚你多做一点作业了。"
D.Strings[94458]="哎呀。"
D.Strings[94459]="天呐，小心你的魔杖。"
D.Strings[94460]="我们可不是来玩的，新生。我们是来学习的。"
D.Strings[94461]="不准在学术厅打闹！"
D.Strings[94462]="现在不是时候，维斯托克！我们得照顾伤员。"
D.Strings[94463]="我现在明白阿鲁因为什么会相信你了。帮我们向他问好。"
D.Strings[94464]="$n！你手上那对匕首真的是弑君者吗？我认识几个收藏家愿意花大价钱来收购这些具有历史意义的古董。我可以帮你联系……只要一点中介费就行……"
D.Strings[94465]="拜托你安静一会儿好吗？我正在写一份非常重要的论文。你这样业余地用魔杖到处乱打人，我很难集中精神。"
D.Strings[94466]="圣光能为你做些什么呢？"
D.Strings[94467]="让我为你展示圣光的力量。"
D.Strings[94468]="愿圣光救赎你的罪孽。"
D.Strings[94469]="我是圣光的复仇者。"
D.Strings[94470]="灾厄必将落到异端的头上。"
D.Strings[94471]="说出你要惩戒的人，我来动手！"
D.Strings[94472]="你这种缺乏信仰的人让我很不安。"
D.Strings[94473]="这里已经安全了。我们可以按照计划发货了。"
D.Strings[94474]="当然，我在城里绕了一大圈呢。"
D.Strings[94475]="为了大魔导师。"
D.Strings[94476]="你应该已经把跟踪者甩掉了吧？"
D.Strings[94477]="很好。那我们就能按时发货了。我们会在一小时内把它送到码头上。千万不要让它离开你们的视线。这年头小偷太多了。"
D.Strings[94478]="荣耀属于艾利桑德。"
D.Strings[94479]="行动起来！"
D.Strings[94480]="我最好还是稍后再来吧，伙计。"
D.Strings[94481]="我最好还是等安全了之后再回来。"
D.Strings[94482]="我们待会儿见， $n。"
D.Strings[94483]="你真勇敢，$n。我很快就会回来的。"
D.Strings[94484]="你真好，勇士，但我不是个好战士。"
D.Strings[94485]="你的口气真像一个伟大的$c，$n。愿大地母亲护佑着你。"
D.Strings[94486]="我不能继续呆在这儿了，$n！"
D.Strings[94487]="商店关门了！我得等安全了之后再回来。"
D.Strings[94488]="如果我的剑能再锋利一点儿，我倒是很乐意留下来找点乐子。"
D.Strings[94489]="没错，我有莎拉达希尔根须的鞭笞者种子。"
D.Strings[94490]="拿上种子，种到这边的泥土里。"
D.Strings[94491]="那是弑君者吧，$n？第一次大战时，在这对匕首夺走莱恩·乌瑞恩国王的生命前，我父亲曾是他的属下。"
D.Strings[94492]="过去的事最好还是让它过去吧。"
D.Strings[94493]="老实告诉你，要是让我遇见迦罗娜，我一定要亲手掐死她。"
D.Strings[94494]="我是不会打偏的！"
D.Strings[94495]="炸弹来啦！"
D.Strings[94496]="你刚好踏入了我的陷阱！"
D.Strings[94497]="$n，我们即将对破碎海滩发起全面攻击。在我攻击之前，我们希望每一位士兵都做好战斗的准备。\n\n你准备好接受战斗训练了吗？"
D.Strings[94498]="将军！"
D.Strings[94499]="有敌人来了！小心！"
D.Strings[94500]="来了！我们遭到了攻击！"
D.Strings[94501]="呱！呱——"
D.Strings[94502]="呱？呱！"
D.Strings[94503]="噢，谢谢你！谢谢你，高手！我愿意帮助你！"
D.Strings[94504]="我的债已经还清了……还清了！走开！"
D.Strings[94505]="嘿！小心！"
D.Strings[94506]="那个蠢货在罐子里呢！太蠢了！居然惹火主人！"
D.Strings[94507]="嘘，他们过来了。"
D.Strings[94508]="这个夜之子陷入了沉默。"
D.Strings[94509]="我们再也不想看见你们了！"
D.Strings[94510]="够了！滚出我们的城市！"
D.Strings[94511]="你果然不是浪得虚名，$n。感谢你在我身体不适的时候代我处理事务。"
D.Strings[94512]="最近的事件和梅瑞尔的病太让人难过了。我很高兴我们还有你这个依靠，$n！"
D.Strings[94513]="你已经证明了自己是一个非常有能力的提瑞斯秘法会成员，$n！"
D.Strings[94514]="|TInterface\\Icons\\ability_socererking_arcaneacceleration|t%s开始施放|cFFFF0000|Hspell:207278|h[奥术锁定]|h|r！跳跃可移除此效果！"
D.Strings[94515]="看来我们达成协议了。要我把钻石给你拿过来吗？"
D.Strings[94516]="这世界将愤怒哭号着反抗我们，但鼓动他们肺部的纯净空气需要我们用灵魂的代价去换取。"
D.Strings[94517]="唔。有点不对劲……"
D.Strings[94518]="小心点。我听说有个能够抽取彼此力量的恶魔议会。我们得切断他们的联系。"
D.Strings[94519]="探索这片区域，设法分化议会成员。只要他们落单，就不是你的对手了！"
D.Strings[94520]="够了！我们稍后再来打猎吧。"
D.Strings[94521]="唔，我们以前见过吗？你看起来很眼熟。\n\n噢！你就是那个大名鼎鼎的英雄。你的事迹真是令人难忘……"
D.Strings[94522]="大法师瓦格斯看向远方。"
D.Strings[94523]="大法师瓦格斯的手指断断续续地抽搐着。"
D.Strings[94524]="大法师突然失去平衡，向一侧倒去。"
D.Strings[94525]="情报表明，有个燃烧军团的密探参加了这个聚会。"
D.Strings[94526]="去跟那些多嘴的贵族聊聊，找到这个密探。可别乱说话引起别人的注意！"
D.Strings[94527]="呱？"
D.Strings[94528]="你只是来看看吗？"
D.Strings[94529]="欢迎来到紫罗兰监狱。"
D.Strings[94530]="没人能逃出这些围墙。"
D.Strings[94531]="我的生命属于卡利姆多。"
D.Strings[94532]="我暂时清醒了……"
D.Strings[94533]="我们要保护荒野。"
D.Strings[94534]="愿你的梦境永远宁静。"
D.Strings[94535]="愿艾露恩的光辉照耀着你。"
D.Strings[94536]="这很快就会过去的。"
D.Strings[94537]="我是个有梦想的人。"
D.Strings[94538]="我会成为你最可怕的梦魇。"
D.Strings[94539]="还是让我回去睡觉吧……"
D.Strings[94540]="只要有你在，清醒就变成了折磨。"
D.Strings[94541]="你的灵魂在熊熊燃烧。"
D.Strings[94542]="我是不会抛弃贡克的祝福的。"
D.Strings[94543]="生命无处不在，值得拯救。"
D.Strings[94544]="源自神灵的，也将归于神灵。"
D.Strings[94545]="别惹恼万灵。"
D.Strings[94546]="愿神灵指引你的道路。"
D.Strings[94547]="我支持你。"
D.Strings[94548]="你干嘛要来打扰我？"
D.Strings[94549]="你最好别惹毛我。"
D.Strings[94550]="我最后警告你一次！"
D.Strings[94551]="<咆哮>"
D.Strings[94552]="愿意为你效劳。"
D.Strings[94553]="我应该攻击谁？"
D.Strings[94554]="我得睡一会儿。"
D.Strings[94555]="打起精神来。"
D.Strings[94556]="我们真的要这么干吗？"
D.Strings[94557]="我宁可去冬眠。"
D.Strings[94558]="我们必须保护这片土地。"
D.Strings[94559]="我的警戒永不松懈。"
D.Strings[94560]="自然非常不安。"
D.Strings[94561]="不要偏离前方的道路。"
D.Strings[94562]="愿塞纳留斯的智慧指引着你。"
D.Strings[94563]="别让母鹿撞得晕头转向了。"
D.Strings[94564]="敬畏荒野。"
D.Strings[94565]="森林已经宣告了你的到来。"
D.Strings[94566]="不要背弃我们的道路。"
D.Strings[94567]="我们会重新崛起的。"
D.Strings[94568]="我很喜欢跟你长谈。"
D.Strings[94569]="你怎么从来都不打招呼呢？"
D.Strings[94570]="我是不是应该在头上架个水壶？"
D.Strings[94571]="茶煮好了！"
D.Strings[94572]="看来是暮色卫队在维持聚会的秩序。我建议你还是偷偷潜入吧。"
D.Strings[94573]="愿风指引你的道路。"
D.Strings[94574]="我们是大地的仆人。"
D.Strings[94575]="用智慧增强你的力量吧。"
D.Strings[94576]="自然总是追求万物的平衡。"
D.Strings[94577]="自然总是坚韧不拔的。"
D.Strings[94578]="一个念头足以催生出许多行动。"
D.Strings[94579]="我是老了，可还没有迟钝。"
D.Strings[94580]="你这是在莽撞送死。"
D.Strings[94581]="生命……唔，生命……总会找到出路的。"
D.Strings[94582]="你这是对牛弹琴。"
D.Strings[94583]="你还要沿途关闭他们的奥术道标，防止哨兵敲响警钟。"
D.Strings[94584]="生命都是宝贵的。"
D.Strings[94585]="母亲之树的恩赐无处不在。"
D.Strings[94586]="以加尼尔的名义。"
D.Strings[94587]="愿艾维娜之风指引你。"
D.Strings[94588]="你应该还有更重要的事要办吧？"
D.Strings[94589]="不要浪费自然的恩赐。"
D.Strings[94590]="这些小家伙需要我们的帮助。"
D.Strings[94591]="我守护了加尼尔数千年。你这点本事还不够我看的。"
D.Strings[94592]="这些树需要我们的帮助。"
D.Strings[94593]="乐意奉陪。"
D.Strings[94594]="很好。你想让我发火？那我就让你开开眼界！"
D.Strings[94595]="小心点！"
D.Strings[94596]="你找错树妖了。"
D.Strings[94597]="我要抱抱小兔子……现在就要！"
D.Strings[94598]="需要我……帮忙吗？"
D.Strings[94599]="天空在呼唤帮助。"
D.Strings[94600]="愿艾维娜祝福你。"
D.Strings[94601]="细节决定成败。"
D.Strings[94602]="我的眼睛尖着呢。"
D.Strings[94603]="要死一起死。"
D.Strings[94604]="总会有希望的。"
D.Strings[94605]="我们必须飞越灾难。"
D.Strings[94606]="愿风眷顾你的航程。"
D.Strings[94607]="我对这种事没有研究。"
D.Strings[94608]="够了，滚开。"
D.Strings[94609]="我很好奇，你听不懂“不”是什么意思吗？"
D.Strings[94610]="我们必须求同存异。"
D.Strings[94611]="你需要自然为你做些什么吗？"
D.Strings[94612]="自然的恩赐无处不在。"
D.Strings[94613]="愿塞纳留斯的祝福与你同在。"
D.Strings[94614]="|TInterface\\Icons\\Spell_Fire_FelFlameStrike:20|t%s开始施放|cFFFF0000|Hspell:206220|h[强化液态地狱火]|h|r。"
D.Strings[94615]="我没带多少东西，但也许有你想要的。"
D.Strings[94616]="天气不错，嗯？"
D.Strings[94617]="总有新的冒险在等着我们。"
D.Strings[94618]="我们要共同面对挑战。"
D.Strings[94619]="我们永不孤单。"
D.Strings[94620]="别忘了保持警惕。"
D.Strings[94621]="咱们有空再聊。"
D.Strings[94622]="第一杯你请！"
D.Strings[94623]="狩猎永不停歇。"
D.Strings[94624]="只要拿上这个，然后——什么？"
D.Strings[94625]="是时候来点高科技了。"
D.Strings[94626]="我们能解决一切问题。"
D.Strings[94627]="你写下来的都是科学。"
D.Strings[94628]="我很乐意效劳。"
D.Strings[94629]="出发吧。"
D.Strings[94630]="很好。愉快的谈话！"
D.Strings[94631]="你来风暴神殿做什么？"
D.Strings[94632]="我是雷电之王托里姆！"
D.Strings[94633]="你好啊，小家伙！"
D.Strings[94634]="你已经远离家园。"
D.Strings[94635]="猎物可不等人。"
D.Strings[94636]="模仿鸦熊的舞蹈以帮助完成仪式。"
D.Strings[94637]="说话小声点。"
D.Strings[94638]="狩猎还将继续。"
D.Strings[94639]="愿闪电指引你。"
D.Strings[94640]="黎明前的黑暗总是最难熬的。"
D.Strings[94641]="热烈欢迎你。"
D.Strings[94642]="沐浴在今日的荣耀之下吧。"
D.Strings[94643]="愿安瑟的温暖指引着你。"
D.Strings[94644]="愿安宁与耐心伴随你左右。"
D.Strings[94645]="愿先祖护佑着你。"
D.Strings[94646]="愿阳光永远照耀着你。"
D.Strings[94647]="祝福你的心灵。"
D.Strings[94648]="你的热情有点过火了。"
D.Strings[94649]="先祖不会喜欢这种行为的。"
D.Strings[94650]="帮帮……我……"
D.Strings[94651]="时间……不多了……"
D.Strings[94652]="太……虚弱了……"
D.Strings[94653]="<咳嗽>"
D.Strings[94654]="客套话就不用说了。"
D.Strings[94655]="我为圣光而战。"
D.Strings[94656]="我是圣光的利剑。"
D.Strings[94657]="英勇战斗吧。"
D.Strings[94658]="我没时间跟你玩心眼。"
D.Strings[94659]="我可不是那种黏黏糊糊的人。"
D.Strings[94660]="真的？真的？我们还要这么下去吗？"
D.Strings[94661]="今年的冬幕节，我不会再给你寄贺卡了。"
D.Strings[94662]="圣光即力量，朋友。"
D.Strings[94663]="我们必胜。"
D.Strings[94664]="我们誓与艾泽拉斯共存亡。"
D.Strings[94665]="愿圣光永远照耀你。"
D.Strings[94666]="一路小心。"
D.Strings[94667]="我是你的坚实后盾。"
D.Strings[94668]="愿圣光赐予你力量。"
D.Strings[94669]="我走过的桥比你走过的路还多。"
D.Strings[94670]="别试探我。我讨厌试探。"
D.Strings[94671]="圣光是不会眷顾讨厌鬼的。"
D.Strings[94672]="我需要一个耐心祝福。"
D.Strings[94673]="燃烧军团休想打垮我们。"
D.Strings[94674]="阿古斯之手与你同在。"
D.Strings[94675]="<鸦熊们都已就位，准备开始仪式了。 \n\n它们似乎在等你。>"
D.Strings[94676]="我们是圣光的仆人。"
D.Strings[94677]="祝福你。"
D.Strings[94678]="我不听。"
D.Strings[94679]="唔……呱？"
D.Strings[94680]="你应该有更重要的事要办吧？"
D.Strings[94681]="无意冒犯，但先知维伦可没你这么啰嗦。"
D.Strings[94682]="阿古斯之手正忙着呢，无法响应你的召唤。请稍后再试。"
D.Strings[94683]="我们聊聊吧。"
D.Strings[94684]="向着远方前进吧。"
D.Strings[94685]="有空再来！"
D.Strings[94686]="放轻松点儿。"
D.Strings[94687]="我们无处不在。"
D.Strings[94688]="我不服从任何人。"
D.Strings[94689]="我们的意志必将实现。"
D.Strings[94690]="不惜代价。"
D.Strings[94691]="我们能人所不能。"
D.Strings[94692]="暗影在召唤。"
D.Strings[94693]="一切都在掌控之中。"
D.Strings[94694]="就这些事吗？"
D.Strings[94695]="你来得正好。"
D.Strings[94696]="药水能解决一切问题。"
D.Strings[94697]="我们谈谈吧。"
D.Strings[94698]="小心那些阴影。"
D.Strings[94699]="千万保重。"
D.Strings[94700]="有话就说。"
D.Strings[94701]="努力吧。"
D.Strings[94702]="一切以任务为重。"
D.Strings[94703]="记住，祸从口出。"
D.Strings[94704]="想给自己添几道伤疤吗？加在……这里怎么样？"
D.Strings[94705]="再这样，你就要死不见尸了！"
D.Strings[94706]="我只忠于我自己。"
D.Strings[94707]="如果保护阿莎曼之牙的结界失效，那我们担心的就不只是瘀伤了。我要守护好这武器，不管你怎么想！"
D.Strings[94708]="我是你的话，就不会来惹我。"
D.Strings[94709]="不要留下线索。"
D.Strings[94710]="你喜欢被切成丝还是切成丁？"
D.Strings[94711]="你真的不应该来惹我。"
D.Strings[94712]="少说话，多做事。"
D.Strings[94713]="言语是无力的。"
D.Strings[94714]="我迟早会报仇的。"
D.Strings[94715]="谁都别想挡我的路。"
D.Strings[94716]="别惹我。"
D.Strings[94717]="想跟我喝一杯吗？里面没下毒……我保证。"
D.Strings[94718]="我有一种能让人消失的秘诀。"
D.Strings[94719]="我还以为你有多高尚呢。"
D.Strings[94720]="我们可以用简单或是麻烦的方法来解决问题。"
D.Strings[94721]="我能买下它吗？"
D.Strings[94722]="麻烦给我钥匙，谢谢。"
D.Strings[94723]="离开这儿！这里不安全！"
D.Strings[94724]="大地正在遭受蹂躏！"
D.Strings[94725]="这里不安全，$n！"
D.Strings[94726]="继续跑！"
D.Strings[94727]="愿大地母亲保佑我们！"
D.Strings[94728]="我真蠢，居然一个人跑到这儿来。"
D.Strings[94729]="到处都是恶魔，$n！"
D.Strings[94730]="月神之光啊！神殿怎么了！？"
D.Strings[94731]="贾布尔喜欢石头。$b$b你也喜欢石头，贾布尔很开心。"
D.Strings[94732]="$n，你真的拿到弑君者了吗？在第一次大战中谋杀了乌瑞恩的那对匕首？在暴风城我可不敢这么说，但是……他是罪有应得。"
D.Strings[94733]="$n！活生生的刺客大师！你那对匕首已经成为幽暗城的热门话题了。"
D.Strings[94734]="去查查资料吧。我来好好回忆一下。"
D.Strings[94735]="|TInterface\\Icons\\inv_axe_2h_felfireraid_d_01:20|t%s正在准备|cFFFF0000|Hspell:206675|h[破碎精华]|h|r。"
D.Strings[94736]="你能再跟我说说艾里克斯吗？"
D.Strings[94737]="艾里克斯是第一次大战时期的提瑞斯法议会成员，他很强大也很有名气。因为忙于自己的目标，我没怎么跟他说过话。我只知道他曾是黑檀之寒的主人。然后，当我从一次长途旅行中归来后，他已经神秘失踪了。他的学徒、材料以及所有跟他有关的东西都不见了。议会的其他成员对此守口如瓶，只说他遇到了一些非常可怕的事。\n\n而黑檀之寒也跟着他一起失踪了。"
D.Strings[94738]="<把你发现的信息告诉梅瑞尔。>"
D.Strings[94739]="所以艾里克斯被这个叫巴拉杜尔的艾瑞达伏击了？那法杖可能在他手里……"
D.Strings[94740]="我的法杖……在敌人手中！我们得夺回它！"
D.Strings[94741]="干得好！现在我们可以反击了！"
D.Strings[94742]="毒药，毒药，这里！自从我们早死之后，这就成了我们家族的招牌产品。"
D.Strings[94743]="所以流言是真的。曾经割断过联盟国王喉咙的双匕——痛楚和哀伤落入了你的手中。$b$b我是一个淬毒匕首的狂热爱好者，$n。能让我看看它们吗？我可以给你讲讲它们的历史……"
D.Strings[94744]="啊，没错，匕首。刺客老手的首选武器。便于隐藏，一击毙命。但有些人更喜欢短剑，可以快速刺穿受害者的心脏。"
D.Strings[94745]="但迦罗娜更喜欢短小、弯曲的双匕。你只要一伸手，就能轻松地将它们从刀鞘中抽出来，悄无声息地割断目标的喉咙。噢，真是太漂亮了！"
D.Strings[94746]="看看这呈倒钩状的逆刃，可以让持有者在错失第一击后立刻反手一击。但迦罗娜从来不会失手。她的目标在倒地之前就已经是个死人了。这真是一对无价之宝，$n——谢谢你。"
D.Strings[94747]="$n！过来点。我听说了有关你那对匕首的流言……"
D.Strings[94748]="他肯定随着这场入侵一起来了，或者在某处观望。我有一个……大胆的计划。"
D.Strings[94749]="我们要重现艾里克斯的仪式！在入侵点举行仪式能吸引巴拉杜尔的注意。他多半会故技重施，但我们早有准备。"
D.Strings[94750]="这应该能行。但我们要了解仪式的细节，以及所需的能量。快行动吧。"
D.Strings[94751]="太好了！有了钥匙，我们就能打开通往阳台的路。艾利桑德的死期到了！"
D.Strings[94752]="当你首次踏上我们的海滩时，我曾问过万灵你是否可信。通过帮助我们的部族统一，你已证明了自己是个真正的朋友。"
D.Strings[94753]="我在此代表高岭诸族，将圣锤授予你和你的盟友。愿它能帮你震碎敌人的心脏！"
D.Strings[94754]="万灵说我们的命运休戚与共，$n。我们已经准备好帮你抗击燃烧军团了。"
D.Strings[94755]="只要你能找到有关艾里克斯的任何信息，包括他是怎么死的，以及黑檀之寒去了哪儿，都是将巨大的胜利。"
D.Strings[94756]="对我们而言，卡兹格罗斯之锤始终象征着团结，以及光辉的历史。但在你手中，它将发挥更大的作用。"
D.Strings[94757]="去找银行经理吧。我给你的印记能让你进去。但金库可能还有结界保护，你最好小心点。"
D.Strings[94758]="快离开这儿！这里太混乱了！"
D.Strings[94759]="我们不该留在这儿！"
D.Strings[94760]="我们得走了。这里不安全。"
D.Strings[94761]="我们的大篷车……我们阻止不了它！"
D.Strings[94762]="别忘了按高级账户的按钮！"
D.Strings[94763]="看看这些……但愿没有丢什么东西……"
D.Strings[94764]="如果您丢了东西，请联系客服！呵呵呵……"
D.Strings[94765]="那种感觉……我说不清楚。"
D.Strings[94766]="这……这真的是我吗？"
D.Strings[94767]="我感觉很虚弱！"
D.Strings[94768]="呃——够了！"
D.Strings[94769]="我停不下来！那玩意不让我停！"
D.Strings[94770]="我们银行的安保措施一流，你哪怕是想拿回自己的东西也会遇到麻烦的！哈哈！"
D.Strings[94771]="我的剑……我没有……我不能……"
D.Strings[94772]="那种感觉……让我作呕。"
D.Strings[94773]="你太弱了！"
D.Strings[94774]="肉体凡胎！"
D.Strings[94775]="别把我的下落泄露出去了。和你一样，我也是搞敌后工作的。"
D.Strings[94776]="闭嘴。他们还没有发现我呢。我在这儿惹了不少麻烦。$b$b我在暗影大厅的同伴告诉我，你拿到了迦罗娜当年的匕首。那是真的吗？能让我看看吗？"
D.Strings[94777]="嘘！$n！这边走。我在这儿呢，营火边上。"
D.Strings[94778]="这么说流言是真的。痛楚和哀伤再次落入了一个刺客大师之手。啊，没错，它们不会让你失望的。"
D.Strings[94779]="你看到刀刃侧面这些血槽了吗？它们能让毒药注入伤口深处。这对匕首饮的是血，吐出的却是毒液。真是一对致命的杰作！"
D.Strings[94780]="收好它们，$n。我很高兴你能成为我们的领袖。谢谢你。"
D.Strings[94781]="我想进入达拉然大法师阿洛迪的私人秘库。"
D.Strings[94782]="唔！你跟他完全不像啊！好吧，让我看看……"
D.Strings[94783]="这是他的印记。你怎么弄到的？好吧，规矩就是规矩。"
D.Strings[94784]="告诉那个大笨蛋，如果他还惦记我们上次没做完的事情，随时都能来找我！我每天都在……多晚都行！"
D.Strings[94785]="别放弃，$n。我们必须战斗！"
D.Strings[94786]="正在改变"
D.Strings[94787]="在我的时代，我会将利刃交给军队。你们呢，凡人？你想要什么？"
D.Strings[94788]="你手里的匕首曾品尝过许多国王的鲜血。拿过来吧，我想仔细看看它们。$b$b哈哈！别愁眉苦脸的，我不会硬留下它们的，潜行者。我早就不需要你们凡人的武器了。"
D.Strings[94789]="过来，$c。让我看看那对匕首——它们散发着死亡的恶臭。"
D.Strings[94790]="啊，我能感觉到它们的饥渴。它们是在黑暗中铸成的凶器，已经有许多人倒在了它们的锋刃之下。"
D.Strings[94791]="如此纤细，如此锋利。这不是战士的武器，不，它们是阴影中的凶器。"
D.Strings[94792]="很好，$r。它们给我留下了深刻的印象。弑君者已经收割了许多生命……去吧，让那些弱者去死吧。"
D.Strings[94793]="拿去吧，但你得马上还给我。"
D.Strings[94794]="滚开……滚开！"
D.Strings[94795]="我可以帮你重新凝聚那件武器里的能量。\n\n但这会让你损失一些能量。"
D.Strings[94796]="我感觉到了，他的回忆。"
D.Strings[94797]="我想重置神器的专长。"
D.Strings[94798]="是的，我想重置神器的专长。"
D.Strings[94799]="这需要消耗500点神器能量。确定要重新选择神器专长吗？"
D.Strings[94800]="嘿，你，帮你的法师同伴一个忙吧！那个恶魔，诺维尔，身上有钥匙！"
D.Strings[94801]="我显然陷入了某种非常有趣的状况！"
D.Strings[94802]="$c，请不要再耽搁了。我无法想像，失去了塞纳留斯的话，这个世界会变成什么样！"
D.Strings[94803]="旅行者，有什么可怕的东西正在酝酿之中。我感觉得到。"
D.Strings[94804]="很壮观，不是吗？"
D.Strings[94805]="恶魔！到处都是恶魔！"
D.Strings[94806]="谢谢你。我差点就坚持不住了。"
D.Strings[94807]="我从来都没吃过这么美味的魔法食物……"
D.Strings[94808]="我要谢谢你……能请你再给我一点食物吗？"
D.Strings[94809]="我……我没事。"
D.Strings[94810]="我从来没见过他们那种魔法。"
D.Strings[94811]="你真勇敢，竟然来救我们，$n。"
D.Strings[94812]="我们最好离开这儿，伙计。"
D.Strings[94813]="等那里安全之后，我就回我的村子去。"
D.Strings[94814]="祝福你，勇士。"
D.Strings[94815]="其他人……我必须找到他们！"
D.Strings[94816]="这些家伙……我挡不住他们！"
D.Strings[94817]="小心！他们的魔法很强大。"
D.Strings[94818]="你很勇敢，$n，多亏你千里迢迢赶来这里。我们欠你一份人情。"
D.Strings[94819]="|TInterface\\Icons\\ability_felarakkoa_feldetonation_red:20|t你受到了|cFFFF0000|Hspell:206221|h[强化邪能束缚]|h|r的影响！"
D.Strings[94820]="|TInterface\\Icons\\ability_felarakkoa_feldetonation_green:20|t你受到了|cFFFF0000|Hspell:206222|h[邪能束缚]|h|r的影响！"
D.Strings[94821]="灰谷南部！这里到处都是恶魔！快过来，别让他们散开了！"
D.Strings[94822]="你那可悲的屏障对军团毫无意义！"
D.Strings[94823]="阿莎曼之牙归我了！"
D.Strings[94824]="我绝不允许阿莎曼之牙落入你们的手中！"
D.Strings[94825]="傲慢的凡人！我们不会罢休的！你只是在垂死挣扎罢了！"
D.Strings[94826]="<递上魔力酒。>"
D.Strings[94827]="感谢你的帮助，可我得去找其他队友了。"
D.Strings[94828]="多谢出手相助，不过我得继续行动了。你也一样。"
D.Strings[94829]="够了。别再说了！住口！"
D.Strings[94830]="法力背叛了我们……"
D.Strings[94831]="抱歉，伙计们，看来我略胜一筹。我们来谈谈细节吧。"
D.Strings[94832]="嘿！我还没说完呢。"
D.Strings[94833]="那位男爵夫人还在吧？不知道那个精灵几岁了。"
D.Strings[94834]="呃，我确定她现在是个地精。"
D.Strings[94835]="我想就连天体也会不时改变一下速率。但她应该还是个女的……对吧？"
D.Strings[94836]="达拉然的中心有座传送门，可以送你去卡拉赞。从那座塔西边的山里找起吧。我依稀记得那里有什么东西。"
D.Strings[94837]="在找到迦罗娜之前，你只能靠自己了。我只要一踏进联盟的地盘，就会被认出来。"
D.Strings[94838]="燃烧军团就这么来了。我还以为我们会有更多的准备时间呢。$b$b要做的事太多了，太多了……"
D.Strings[94839]="是我的密探们看错了吗？真的是痛楚和哀伤？刺杀了莱恩·乌瑞恩国王的那对匕首？这真是个了不起的发现，$n。$b$b我对它们略知一二。能让我看看吗？一会儿就行。"
D.Strings[94840]="现在我们可以随意说话了，$n。我一直想问问你那对匕首的事……"
D.Strings[94841]="太棒了，$n。如果仇恨本身能被铸造成武器，那一定就是这个样子的。"
D.Strings[94842]="当代的战士太依赖他们的盔甲了。一柄从板甲缝隙间刺入的小刀子绝对比巨型战锤或是魔法火球更能让他们措手不及。"
D.Strings[94843]="我并不是看不起大火球。但我本人向来更喜欢斗篷、匕首之类的东西。谢谢你，$r。这对匕首真是个奇迹。"
D.Strings[94844]="看好了，野蛮人！和阿莎曼之牙永别吧！"
D.Strings[94845]="维斯托克来过祭坛！去搞清发生了什么。我会尽快与你汇合，$n。"
D.Strings[94846]="你是来带我走的？还是来寻找这里残余的宝藏的？"
D.Strings[94847]="他们让我守在这里，可谁都没回来过。我的实力无法保护营地……也可能是因为我在这里待得太久了。我已经搞不清了。"
D.Strings[94848]="你需要那个焦镜来重现仪式。我想保护它不被怪物抢走，可我太虚弱了。"
D.Strings[94849]="它就在我的尸体附近。我……我想就是它束缚了我。请把它拿走。那样我或许就能回家了。"
D.Strings[94850]="又一个多管闲事的？！我要亲眼看着这世界毁灭！"
D.Strings[94851]="网络对新道标有反应了。啊，又见面了！"
D.Strings[94852]="给我点时间——我在锁定你的位置。"
D.Strings[94853]="我和凡瑟尔需要你帮忙报复——"
D.Strings[94854]="破碎群岛上任何恶魔的鲜血都行。真希望我能跟你一起去。"
D.Strings[94855]="抓紧了，凡人朋友。从这么高的地方摔下去恐怕就糟糕了。"
D.Strings[94856]="兄弟姐妹们，神殿遭到了攻击！我们要亮出尖牙和利爪，把亵渎者清除掉！"
D.Strings[94857]="我们的秘器不是给你准备的，外来者！"
D.Strings[94858]="我们的！这些知识是属于我们的！"
D.Strings[94859]="你竟敢亵渎我们神圣的典籍？"
D.Strings[94860]="我们迟早会……解除这个诅咒的……"
D.Strings[94861]="秘器会拯救我们的……它一定会的。"
D.Strings[94862]="干得好！军团的进攻被击溃了！"
D.Strings[94863]="怎么……阿莎曼之牙不见了！怎么回事，$n？"
D.Strings[94864]="这个世界的末日已经降临了！"
D.Strings[94865]="我们要将你们的世界烧成灰烬！"
D.Strings[94866]="这些凡人阻止不了注定的命运！散开！杀光他们！"
D.Strings[94867]="挖地三尺！消灭所有的凡人生灵！"
D.Strings[94868]="你的世界死到临头了！"
D.Strings[94869]="我们是……无穷无尽的。"
D.Strings[94870]="你们的挣扎……毫无意义。"
D.Strings[94871]="感受内心的颤栗吧，凡人。今天，这世界就将落入军团之手！"
D.Strings[94872]="和熟悉的生活告别吧。燃烧军团来了！"
D.Strings[94873]="感受这焚烧大地的力量吧！"
D.Strings[94874]="你逃不出我们的掌心了！"
D.Strings[94875]="你们的挣扎都是徒劳的，凡人！我们是不可阻挡的。"
D.Strings[94876]="挡我者死！"
D.Strings[94877]="死亡只是伪装。"
D.Strings[94878]="会有别人……来……接替我的……"
D.Strings[94879]="凡人渣滓！你休想再玷污这世界！"
D.Strings[94880]="散开！一个不留！"
D.Strings[94881]="把他们全部抹杀！"
D.Strings[94882]="我接受挑战，凡人。该让你们明白自己有多脆弱了！"
D.Strings[94883]="你们的生命毫无意义！我很乐意终结它们！"
D.Strings[94884]="我还会……回来的！"
D.Strings[94885]="一次暂时的……挫折……"
D.Strings[94886]="军团来了！你们的世界将被净化！"
D.Strings[94887]="可悲的废物！末日已近在咫尺！"
D.Strings[94888]="他们曾是我的臣民，为无法控制的魔力而疯狂，密谋计划向我和我的人民复仇。去消灭他们吧！"
D.Strings[94889]="消灭他们！一个不留。"
D.Strings[94890]="淹没他们的土地！抹杀所有生灵！"
D.Strings[94891]="你的傲慢毫无意义！来面对军团的深渊领主！"
D.Strings[94892]="放肆的懦夫！出来面对我！"
D.Strings[94893]="你们……只是在……垂死挣扎。"
D.Strings[94894]="看来塔什瑞尔是要通过纯粹的魔力来解除诅咒。真是浪费。好在这些书籍物归原主了。"
D.Strings[94895]="末日降临了！万物都将燃烧！"
D.Strings[94896]="眼睁睁看着你们的土地被吞噬吧！"
D.Strings[94897]="我以军团之名占领这片土地！所有凡人都得死！"
D.Strings[94898]="在不朽大军面前，你们不堪一击！"
D.Strings[94899]="死亡……只是一个开始。"
D.Strings[94900]="游戏……还没……结束呢……"
D.Strings[94901]="他们受到的诅咒和我们一样，所以无法安息。但你至少暂时阻止了他们袭击我的宫廷。"
D.Strings[94902]="纳命来吧，外来者！"
D.Strings[94903]="你将在诅咒中死于此地！"
D.Strings[94904]="诅咒……让我无法安息……"
D.Strings[94905]="诅咒依然存在……"
D.Strings[94906]="我的魔法就是你的末日！"
D.Strings[94907]="我要报复法罗迪斯的傲慢！"
D.Strings[94908]="能听到我说话吗？别紧张。"
D.Strings[94909]="我会尽力让泰林保持昏迷的……"
D.Strings[94910]="奥术传动是一种超越了物理空间的联系。"
D.Strings[94911]="<乌牙盯着你看了一会儿，然后趴了下来，让你爬到她背上。>"
D.Strings[94912]="我们开始搜索吧。"
D.Strings[94913]="纳兹戈林，听从死亡领主的召唤吧！感受主人的寒冰之握，重新站起来！"
D.Strings[94914]="在这座大城市里，贾布尔总算可以全心全意地研究宝石了。"
D.Strings[94915]="是时候了，大人。做你该做的事吧。"
D.Strings[94916]="獠牙带走了我的生命……"
D.Strings[94917]="萨格拉斯会收回你那对獠牙的，潜行者。"
D.Strings[94918]="可那是阿卡丽的匕首啊……怎么会……？"
D.Strings[94919]="那对匕首属于燃烧军团……"
D.Strings[94920]="你拿的是……阿卡丽的吞噬者之牙？不可能……"
D.Strings[94921]="我又活过来了……我死了有多久了？"
D.Strings[94922]="让我看看踏风武僧的力量和敏捷吧！"
D.Strings[94923]="不用说了。我会砍掉他们的脑袋……"
D.Strings[94924]="好久不见，我的朋友。燃烧军团又回来了，战场在召唤着你。"
D.Strings[94925]="当然了，将军。当然了……"
D.Strings[94926]="你休想干扰我的任务。燃烧军团必将占领这个世界！"
D.Strings[94927]="你还不明白吗，新的主人可以让我们超越肉体凡胎！"
D.Strings[94928]="隐蔽之手将统治这个破碎的世界。我们将带来一个新的纪元！"
D.Strings[94929]="你去哪儿了，小老鼠？"
D.Strings[94930]="神圣的地狱之火将从天而降，让我们沐浴在燃烧军团的威能之中。我们将所向披靡！"
D.Strings[94931]="你不可能一直躲下去的。"
D.Strings[94932]="篡夺者！小偷！恶棍！你休想破坏我们光荣的命运！"
D.Strings[94933]="我感觉到你的恐惧了，密探。"
D.Strings[94934]="停下！搜索这一带！"
D.Strings[94935]="搞清楚你的身份！"
D.Strings[94936]="废物。"
D.Strings[94937]="你们的生命归我们了。"
D.Strings[94938]="古尔丹允许你们暂时活下去。"
D.Strings[94939]="让你的死警告一下那些违抗军团的人吧。"
D.Strings[94940]="那只是一点小麻烦而已。谢谢你！你一定就是我最近老听说的那个人吧！"
D.Strings[94941]="獠牙！可怕的獠牙……"
D.Strings[94942]="这是阿卡丽的獠牙……"
D.Strings[94943]="赤喉的獠牙！好可怕……"
D.Strings[94944]="不……！不要用那对獠牙……"
D.Strings[94945]="我们一定会是好搭档的！让我们炸飞这个地方吧！"
D.Strings[94946]="我是来向你请教艾里克斯和他那个仪式的事的。我必须击败巴拉杜尔，所以我需要引起他的注意。"
D.Strings[94947]="啊，那个仪式。艾里克斯就是在那个仪式上尖叫着被拖入虚空的，他的整个法师团也被屠戮一空。这个仪式也直接导致我放弃了奥术，走上了研究恶魔和邪能能量的道路。\n\n巴拉杜尔极其危险，而你似乎又……太年轻。你确定你准备好了吗？"
D.Strings[94948]="我得到了梅瑞尔·邪风和阿洛迪之魂的帮助，我们知道将要面对什么。"
D.Strings[94949]="这些年，巴拉杜尔和他的爪牙杀害了许多法师。这事儿他们已经干得相当顺手了。在我帮你举行仪式之前，我要先亲眼看看你的技术。如果你能击败我召唤出来的恶魔，我才会帮助你。\n\n你准备好面对恶魔了吗？"
D.Strings[94950]="我准备好面对你的恶魔了，术士。"
D.Strings[94951]="很好！我们开始吧。从简单的开始。先来几只小鬼如何？"
D.Strings[94952]="呃！这里到底出什么见鬼的事了？"
D.Strings[94953]="……见鬼，我到底在哪儿啊？"
D.Strings[94954]="那玩意儿……我很难解释。"
D.Strings[94955]="我从来没有过这种感觉。"
D.Strings[94956]="你一定要让那些恶魔罪有应得！"
D.Strings[94957]="小心点，沙考尔。$n带着恐惧之刃，那对被诅咒的短剑已经干掉过许多水手了。"
D.Strings[94958]="对……对！他们每时每刻都在靠近！"
D.Strings[94959]="蠢货！你们可悲的灵魂将加速燃烧军团的降临！"
D.Strings[94960]="站住，恶棍！你不明白自己在摆弄怎样的力量。"
D.Strings[94961]="他们自愿为崇高的事业献出了生命。你呢？"
D.Strings[94962]="现在还不算迟。投降吧，你将在新的秩序中占据一席之地！"
D.Strings[94963]="你没感觉到吗？燃烧军团温暖的拥抱就要降临了，你只需要张开双臂欢迎它即可！"
D.Strings[94964]="你根本不值得拯救。去死吧，可悲的蝼蚁！"
D.Strings[94965]="你太迟了。我们……无处不在……"
D.Strings[94966]="你身上那对匕首被诅咒了，$n。我见过它们杀死了许多水手。你最好小心点。"
D.Strings[94967]="后退。我们必须完成仪式！"
D.Strings[94968]="那是什么？没关系。我的任务不能停。"
D.Strings[94969]="我闻到了废物的气味。"
D.Strings[94970]="我好像听到了什么声音。"
D.Strings[94971]="这里有人……"
D.Strings[94972]="但愿这能管用。"
D.Strings[94973]="记住，这是我借给你的。"
D.Strings[94974]="这个传送门似乎可以通往不同的地方。你想去哪儿？"
D.Strings[94975]="炼金师之巢"
D.Strings[94976]="旅店入口"
D.Strings[94977]="废弃小屋"
D.Strings[94978]="下水道卫兵岗哨"
D.Strings[94979]="后门"
D.Strings[94980]="黑市"
D.Strings[94981]="嘿，谢了！我们开始干活儿吧！"
D.Strings[94982]="看来是时候好好教训一下这些家伙了。"
D.Strings[94983]="谢谢你。我最好还是等事态平息后再回来吧。"
D.Strings[94984]="勇敢的$c。我发誓，我将来一定会报答你的。"
D.Strings[94985]="站住！我……抱歉，$n！你在这里做什么？"
D.Strings[94986]="小鬼很弱，但大量小鬼也很致命。或许该换个厉害点的对手……"
D.Strings[94987]="掌握了冰霜魔法的人都能做到。如果是……面对像你一样擅长施法的对手，又会如何呢？"
D.Strings[94988]="干得好，但巴拉杜尔已经猎杀法师几百年了。要面对他，你就得精通自己所有的技艺。"
D.Strings[94989]="这就是最后一块拼图……一块石头。这是来自巴拉杜尔老家的石头，在某次伏击中留在了这里。"
D.Strings[94990]="没有人能反抗燃烧军团！"
D.Strings[94991]="你的世界必将倒在燃烧军团的威能之下！"
D.Strings[94992]="卑微的凡人！你们一无是处！"
D.Strings[94993]="在我们面前颤抖吧，凡人！你们的世界就要完了！"
D.Strings[94994]="你……死……定了！"
D.Strings[94995]="软弱的废物！你们的挣扎毫无意义！"
D.Strings[94996]="软弱的懦夫。你们的命运早已注定。"
D.Strings[94997]="激流堡王国天生就是属于我的。有了传说中的托卡拉尔，没有人能质疑我的统治，包括希尔瓦娜斯！"
D.Strings[94998]="就是这里。可惜这里挤满了鱼人。"
D.Strings[94999]="如果你能干掉那些鱼人，咱们今天剩余的钓鱼时光就会轻松多了。"
D.Strings[95000]="使用刀扇！"
D.Strings[95001]="你正面对数个敌人，试试使用刀扇吧！"
D.Strings[95002]="使用暗影步！"
D.Strings[95003]="使用闪避降低伤害！"
D.Strings[95004]="使用毒伤！"
D.Strings[95005]="你有5个连击点数了。使用毒伤吧！"
D.Strings[95006]="你有5个连击点数了。快使用割裂！"
D.Strings[95007]="使用毁伤产生连击点数！"
D.Strings[95008]="使用毁伤！"
D.Strings[95009]="使用锁喉！"
D.Strings[95010]="使用锁喉让你的敌人流血！"
D.Strings[95011]="练习使用疾跑来提高你的移动速度。"
D.Strings[95012]="需要迅速摆脱棘手的局面？这可是潜行者的强项。疾跑能够在短时间内大幅提高你的移动速度，而且可以频繁使用。跑起来让我看看吧，潜行者！"
D.Strings[95013]="使用刀扇解决这群敌人。"
D.Strings[95014]="试图包围你的敌人一定会大吃一惊的！"
D.Strings[95015]="使用暗影步出现在远处的目标背后。"
D.Strings[95016]="有时，你需要靠近一个目标，但又不需要立即对他造成伤害。"
D.Strings[95017]="使用闪避提高你躲闪攻击的几率。"
D.Strings[95018]="潜行者的反应速度远超普通人。在极端危险的情况下，潜行者可以在短时间内靠这种猎豹一般的反应速度躲过任何物理伤害。但闪避不能经常使用，所以把它留到紧急情况下再使用吧。"
D.Strings[95019]="使用猩红之瓶为你自己恢复部分生命值。"
D.Strings[95020]="你受了一点伤，幸好老练的潜行者对此早有准备。"
D.Strings[95021]="使用消失来躲过我的士兵。"
D.Strings[95022]="最后，你还有一课要学。"
D.Strings[95023]="使用5个连击点数发动毒伤。"
D.Strings[95024]="割裂并不是你唯一的终结技。"
D.Strings[95025]="使用5个连击点数发动割裂。"
D.Strings[95026]="你已经积累了5个连击点数，该使用割裂了。"
D.Strings[95027]="使用毁伤攻击目标假人。"
D.Strings[95028]="你的主要攻击技能叫毁伤。它能造成伤害并产生连击点数。连击点数能用来施放强大的终结技。"
D.Strings[95029]="对这个目标假人使用锁喉。"
D.Strings[95030]="作为一个刺客，你要在解决敌人前先削弱他们。"
D.Strings[95031]="刺客擅长阴谋诡计。还有什么能比在被目标发现前发动攻击更狡猾的呢？"
D.Strings[95032]="作为一名刺杀潜行者，你擅长从暗影中发动攻击，用各种毒药和流血攻击解决敌人。"
D.Strings[95033]="我给过艾里克斯一块碎片，帮他的仪式融合恶魔能量。剩下的都归你了。但愿它能给你带来好运。"
D.Strings[95034]="很好，孩子。你像我一样渴望力量。"
D.Strings[95035]="我们可以联手创造奇迹。"
D.Strings[95036]="不够。我还要更多。"
D.Strings[95037]="这世界充斥着魔力，只等你伸手攫取。"
D.Strings[95038]="这力量……在我体内流淌。"
D.Strings[95039]="他们想控制我们，遏制我们的力量。休想！"
D.Strings[95040]="你很有野心，孩子，和你的前任一样。"
D.Strings[95041]="奥术能量编织成了这世界……感觉到了吗，孩子？"
D.Strings[95042]="我啜饮魔力……不知餍足……"
D.Strings[95043]="我们可以一起改造这个世界。"
D.Strings[95044]="他们称你为“英雄”。为什么，孩子？因为你能满足他们的奇思怪想？"
D.Strings[95045]="它的能量滋养了我。"
D.Strings[95046]="还不够。再去找。"
D.Strings[95047]="对，孩子。真是……有潜力。"
D.Strings[95048]="去满足你的欲望吧，孩子。别停下。"
D.Strings[95049]="我们合作得很好。"
D.Strings[95050]="这里有能量。"
D.Strings[95051]="还有其他敌人。去找到他们，干掉他们！"
D.Strings[95052]="谁都躲不过我们的怒火。"
D.Strings[95053]="对，对……"
D.Strings[95054]="我要吞噬它。"
D.Strings[95055]="如此强大的力量。"
D.Strings[95056]="你在进步，孩子。"
D.Strings[95057]="我去克拉苏斯平台帮你安排一下。你准备好后，就去找飞行管理员吧。"
D.Strings[95058]="一旦离开达拉然，我的力量就会衰退，但我会用“精神”支持你的。"
D.Strings[95059]="懦夫！不管你躲在哪儿，都逃不出我们的掌心。"
D.Strings[95060]="地底之王休想逃跑，休想！"
D.Strings[95061]="影眼兄弟，我们光荣崛起的时候到了。快去夜色镇吧。"
D.Strings[95062]="梅瑞尔·邪风说你会送我去法罗纳尔。"
D.Strings[95063]="埃伯洛克姐妹已拿到无辜者的颅骨和鲜血。她在等你护送。"
D.Strings[95064]="愿军团指引你的道路，别忘了销毁这封信。我们必须保证万无一失。"
D.Strings[95065]="一堆有关“隐蔽之手”教派的笔记。"
D.Strings[95066]="多亏了你们，圣光再次照亮了西部荒野。但我们必须保持警惕！"
D.Strings[95067]="$n，我一直在等你，而不是这个叛徒奥图里斯。"
D.Strings[95068]="啊哦。看来地窟内层已经被攻破了！我们得去看看夜之子灵魂石有没有被抢走……"
D.Strings[95069]="伊利丹。"
D.Strings[95070]="算了，我们时间有限。"
D.Strings[95071]="我让阿卡玛那个两面派策划了对燃烧军团的进攻。"
D.Strings[95072]="只有他知道全部细节。如果你想成功，就需要他的建议。"
D.Strings[95073]="你还要找回萨格里特钥石才能侵入燃烧军团的世界。"
D.Strings[95074]="去搞清楚守望者把它藏哪儿了。"
D.Strings[95075]="我们引起了注意。我得走了。"
D.Strings[95076]="你以后就联络不上我了。伊利达雷就归你了，$n。"
D.Strings[95077]="该死！它不见了！等我抓住那个瓦格斯，一定要让他后悔！"
D.Strings[95078]="他刚刚离开这儿——他跑不了多远！"
D.Strings[95079]="$n，我一直在等你。啊，很好……凯恩·日怒。"
D.Strings[95080]="我们时间有限。听好了。"
D.Strings[95081]="复仇之魂盯着你所在的方向。"
D.Strings[95082]="复仇之魂发出空洞的嚎叫。"
D.Strings[95083]="灾难笼罩着这里。精灵废墟里充斥着有待收割的躁动灵魂。"
D.Strings[95084]="这里的巨龙很弱。你该好好利用这一点。"
D.Strings[95085]="军团在这里挖地三尺。如果他们再挖下去，恐怕就要遭殃了。"
D.Strings[95086]="这里全是泰坦的子嗣。尽管接受了血肉“恩赐”，他们仍在崇拜那些伪神。"
D.Strings[95087]="海拉和她的教派在这里很强大。现在，她已经很接近真理了。"
D.Strings[95088]="不要被那些高大的泰坦雕像唬住了。和尼奥罗萨的献祭之塔相比，这些破神殿不过是小矮人。"
D.Strings[95089]="比起长眠之城，这座精灵城市黯然失色……"
D.Strings[95090]="苏拉玛，它的“贵族”正在贪婪的吸吮这世界的生命之血。"
D.Strings[95091]="这些精灵蜷缩在他们的高墙后死去。他们看不到其他出路……"
D.Strings[95092]="轰隆！轰隆！"
D.Strings[95093]="老师说我的魔法是最强大的！"
D.Strings[95094]="那条陨落的守护巨龙的巢穴就在附近。他是最强大、但也最容易被腐蚀的守护巨龙。"
D.Strings[95095]="你不可能打破力场的！护盾太强大了！"
D.Strings[95096]="BIU BIU BIU！闪电飞弹！"
D.Strings[95097]="不公平，你总是扮大魔导师！"
D.Strings[95098]="这里繁衍着许多失败的泰坦试验品。卓格巴尔完全证明了自己是种失败的造物。"
D.Strings[95099]="考虑到他们的起源，这里的牛头人对于腐蚀的抵抗力相当高。"
D.Strings[95100]="看到尤格-萨隆的梦魇遍地开花，我很嫉妒……又有些骄傲。"
D.Strings[95101]="在这里，你会明白军团的入侵为什么是徒劳的。一切都会被腐蚀，梦境和恶魔都一样。"
D.Strings[95102]="精灵们绝望地想要摆脱梦魇，而恶魔想要掌控它的力量。他们都将失败。"
D.Strings[95103]="这个灵魂充满愤怒！它会是个很好的目标。"
D.Strings[95104]="又一个痛苦的灵魂，早该彻底湮灭了。但我对他的顾问更感兴趣……"
D.Strings[95105]="萨维斯很狡猾。既然可以远程遥控，又何必赤膊上阵呢？"
D.Strings[95106]="她这副模样可能是恩佐斯造成的，可这种傲慢完全是她自己的产物。"
D.Strings[95107]="见证这些以泰坦的名义白白浪费掉的泰坦之力吧，仅此而已。"
D.Strings[95108]="斯科瓦尔德想加入毁灭者的行列，却没想到敢这么干的人最后都众叛亲离了。"
D.Strings[95109]="奥丁是个了不起的敌人……直到他的傲慢毁了他自己。你该问问他对洛肯临死前说的那段话有什么想法。去呀！"
D.Strings[95110]="伊米隆是个好棋子。在散播血肉祝福时，他比其他同胞做得更好。"
D.Strings[95111]="这里的人用血的代价从燃烧军团手中换得了自由。但你很快就看到，这种牺牲完全是徒劳的。"
D.Strings[95112]="健壮、强大、狡猾……巨龙如果能再……温顺点，就能成为理想的仆从了。"
D.Strings[95113]="看看这儿，看到燃烧军团是怎么抽干每一滴有用的魔力了吗？连一只虫子的灵魂都没留下！我不得不赞赏一下这种效率！"
D.Strings[95114]="这里和玛凯雷没法比，但它很快也会像玛凯雷一样陷入地狱火海。"
D.Strings[95115]="这里的精灵由于缺乏魔力而枯竭。真可悲！他们可以从别人那里夺取啊。"
D.Strings[95116]="这些精灵躲在他们的高墙后面。蠢货！如果燃烧军团胜利，他们周围的世界都会崩溃！"
D.Strings[95117]="干得好，各位！"
D.Strings[95118]="我们胜利了！"
D.Strings[95119]="兄弟姐妹们，拿起武器！"
D.Strings[95120]="哦，你看呐，主人！一城讨厌的小精灵！"
D.Strings[95121]="我诅咒你，萨满。我的宠物，干掉$g他:她;。"
D.Strings[95122]="暗影在这里滋长。"
D.Strings[95123]="什么？拜托对着我这只没毛病的耳朵说好吗？"
D.Strings[95124]="虚空触及了这片土地。"
D.Strings[95125]="一座城市？我们一定要进去吗！？"
D.Strings[95126]="我很乐意看到这座城毁灭。"
D.Strings[95127]="祝你好运，$n。你可以用我的水晶跟我对话。"
D.Strings[95128]="这是多么可悲的借口啊。"
D.Strings[95129]="看看这座城！好多美味的魔力！"
D.Strings[95130]="我要吃掉你的……心脏……"
D.Strings[95131]="一群等死的可怜虫！"
D.Strings[95132]="快来！法多雷就盘踞在下面的废墟里。"
D.Strings[95133]="下去，顺着河道走。"
D.Strings[95134]="你会成为有趣的宠物，小精灵。"
D.Strings[95135]="认清你的身份，蛆虫。"
D.Strings[95136]="你们只是我们的玩具，小东西。记住这一点。"
D.Strings[95137]="跪在上位者面前吧，废物。"
D.Strings[95138]="你要习惯谦卑，夜之子。"
D.Strings[95139]="躲吧。我很快就会找到你的……"
D.Strings[95140]="很好。享受这所剩无几的……自由吧。"
D.Strings[95141]="唔，也许没什么……"
D.Strings[95142]="出来，出来，小家伙……"
D.Strings[95143]="你可以跑，但你是藏不住的，宝贝……"
D.Strings[95144]="第三舰队已经在破碎群岛的南部海滩上展开。"
D.Strings[95145]="前线还没有消息吗？"
D.Strings[95146]="只回来了几个斥候，最近没有任何消息。"
D.Strings[95147]="真让人担心。"
D.Strings[95148]="我这儿可以帮你，$n。"
D.Strings[95149]="你太迟了，凡人！"
D.Strings[95150]="盐须，重新站起来吧！成为侍奉燃烧军团的亡灵吧！"
D.Strings[95151]="撕碎这个废物，盐须。我还有正事要办呢……"
D.Strings[95152]="留在祭坛里，以躲避旋风。"
D.Strings[95153]="你说什么？穆兹去哪儿了？"
D.Strings[95154]="你的家人都在圣锤之座呢。"
D.Strings[95155]="我看不见你了，$n！"
D.Strings[95156]="走慢点，$g小公牛:小母牛;！"
D.Strings[95157]="我猜你宁可让我从雷霆图腾的悬崖上掉下去也不愿护送我吧？"
D.Strings[95158]="以前的年轻人都懂得善待老婆婆。"
D.Strings[95159]="别离开我的视线！"
D.Strings[95160]="靠近点，$r。"
D.Strings[95161]="啊，我这把老骨头都好久没活动了。"
D.Strings[95162]="真是个善良的年轻$g小伙子:姑娘;。"
D.Strings[95163]="我们去见穆兹吧！"
D.Strings[95164]="我女儿真漂亮。"
D.Strings[95165]="你说塞拉什么时候才能再给我生几个外孙呢？"
D.Strings[95166]="你见过穆兹的笑容吧？跟我简直是一个模子里刻出来的。"
D.Strings[95167]="小穆兹是头出色的小牛犊。"
D.Strings[95168]="你还在等什么？我们走！"
D.Strings[95169]="真是神奇的转折。我在上面等你。"
D.Strings[95170]="我在上面等你。我们一起破译这些消息。"
D.Strings[95171]="收集十滴活水且不被攻击"
D.Strings[95172]="返回许德拉侬处且不被攻击"
D.Strings[95173]="伊墨瑞尔！指挥官！你看到了吗？"
D.Strings[95174]="我听到这边有动静。"
D.Strings[95175]="这里有人。"
D.Strings[95176]="我们有伴儿了，兄弟姐妹们。"
D.Strings[95177]="伊利丹之魂说了，我们的道路再无阻碍。"
D.Strings[95178]="快看天上！就在营地上方！"
D.Strings[95179]="冷静点，皮尔斯。你在说什么？"
D.Strings[95180]="我们请教了主人的灵魂，并且得到了他的指点。"
D.Strings[95181]="紧急信号弹。它们出现在了营地上空！"
D.Strings[95182]="你快来看啊！"
D.Strings[95183]="又有献给燃烧军团的新骨头了！"
D.Strings[95184]="新领袖$n万岁。伊利达雷，敬礼！"
D.Strings[95185]="这不可能……这些信号弹已经几百年没有使用过了。"
D.Strings[95186]="你已经……太迟了……"
D.Strings[95187]="伊利达雷，向新领袖$n致敬！"
D.Strings[95188]="我们必须遵守协议。无论是谁打出的信号弹，他都需要我们的帮助。"
D.Strings[95189]="唉，可怜的尼珊德拉！她曾是个忠实的梦境守护者，现在却沦为了腐蚀的守门人。"
D.Strings[95190]="我们必须终结梦魇。发话吧，我这就把我们送入那个扭曲之地的核心。"
D.Strings[95191]="我曾直面过梦魇，可它从来没有这样彻底压制住梦境。它非常饥渴，急于种下腐蚀的种子。不要让它的低语逼疯你们！"
D.Strings[95192]="梦魇之虹上有塞纳留斯的气息。它是通往月光林地的传送门，但被黑暗魔法封锁了。我们得斩断束缚它的能量触须。"
D.Strings[95193]="这里每条道路都散发着邪气。选一条路吧，我会一直陪着你们的。"
D.Strings[95194]="我们快去哨塔吧。"
D.Strings[95195]="如果你们要深刻理解梦魇的邪恶，看看那边吧！连勇猛的乌索克都被制服了。放了他，求求你们！"
D.Strings[95196]="没有比乌索克更高贵的灵魂了。但愿他的灵魂能返回翡翠梦境。"
D.Strings[95197]="翡翠梦境之路。在漫长的沉睡中，我在这儿与绿龙军团交流。"
D.Strings[95198]="现在，这片圣地成了梦魇散播腐蚀的管道。我们决不容许这种事发生！"
D.Strings[95199]="噢，伊森德雷！残酷的命运啊！我们曾为他净化过梦魇，可他又被梦魇所害。有些伤痕从未真正痊愈。"
D.Strings[95200]="愿你安息，老友。"
D.Strings[95201]="这是什么邪恶的怪物？它似乎想对雷霆崖施放腐蚀！牛头人的灵魂决不能成为梦魇的猎物！"
D.Strings[95202]="就算是死，我也要找到灵魂石！"
D.Strings[95203]="腐蚀的幻象消散了！艾乐瑞瑟·雷弗拉尔……她就像我的姐妹。她的死真让我痛心，英雄们。"
D.Strings[95204]="暮光之锤伏击并谋杀了艾乐瑞瑟，还让她误以为是哈缪尔·符文图腾害死了她。看来她的灵魂已经彻底扭曲了，想要报复整个雷霆崖。"
D.Strings[95205]="你深爱着奥特兰克的土地，老友。我会以你之名照料好它的。"
D.Strings[95206]="多么可怕！在这个泰坦国度的投影里，居然有一颗寄生在世界树上的梦魇肿瘤？"
D.Strings[95207]="如果这颗种子生根发芽，它的根须就会植入艾泽拉斯的心脏。梦魇会吞噬我们的世界，控制一切……所有人。必须阻止它！"
D.Strings[95208]="显然，萨维斯和他的老主子很乐意看到我们全力对抗军团。他们蛰伏的阴影渗入了我们的世界，用低语和猜忌动摇着我们。"
D.Strings[95209]="等我拿到灵魂石，谁都别想阻止我！"
D.Strings[95210]="但愿净化梦魇的腐蚀能让我们有足够的时间击败燃烧军团，并且，能在黑暗大军从地底涌出前喘口气。"
D.Strings[95211]="够了！我厌倦这场闹剧了。"
D.Strings[95212]="看，梦魇之虹开启了！可以去见塞纳留斯了。"
D.Strings[95213]="月光林地是梦境中最神圣的地方。一想到我的导师可能导致了它的腐化……"
D.Strings[95214]="我要亲眼看看我敬爱的导师遭到了什么厄运。继续坚定地对抗黑暗吧。"
D.Strings[95215]="这把武器不错吧？你偶尔也该借给我用用嘛！"
D.Strings[95216]="圣盾是属于我的，你们这群蠢货。你们阻止不了我。"
D.Strings[95217]="当然，如果我有你那么好的武器，我也能管理这个地方。而且我得说，我恐怕比你更合适。"
D.Strings[95218]="你知道夜之子灵魂石可以控制几百万人吗？等我得到它之后就有乐子了！"
D.Strings[95219]="瓦格斯和他那有限的智慧永远都别想解开灵魂石的全部潜力。只有我才能真正向你展现它的力量！"
D.Strings[95220]="使徒许诺将给我们自由与尊严。我们决不能失败！"
D.Strings[95221]="你别想捣乱。军团必将崛起！"
D.Strings[95222]="大法师，我看到了你的信号弹。我们能帮你什么忙吗？"
D.Strings[95223]="那是我的穆兹……"
D.Strings[95224]="有刺客！快逃命吧！"
D.Strings[95225]="我敢肯定，那些牛头人随时都会回来的。\n\n但在此之前，我能帮你什么忙吗，伙计？"
D.Strings[95226]="你干嘛把牛头人的货物都搬到你的飞艇上去？"
D.Strings[95227]="噢，我们……跟他们做了一笔交易。\n\n对，他们想让我们带着这些东西飞去达拉然，然后把它们卖掉。毕竟，在这里没有多少人会买它们，对吧？而且，还有比地精更出色的推销员吗？ \n\n那些牛头人真有生意眼光！"
D.Strings[95228]="嘘！有人来了！"
D.Strings[95229]="噢，嘿，伙计。我们能帮你什么忙吗？"
D.Strings[95230]="……可能已经变成巨龙的美餐了吧……"
D.Strings[95231]="别那么肯定……嘿，朋友！"
D.Strings[95232]="能听到我说话吗，$n？你应该已经在维斯托克的附近了。"
D.Strings[95233]="……它们开始发臭了。我们应该——"
D.Strings[95234]="我的笨学徒逃得很仓促。他肯定没有掩盖自己的气味。只要变成猎豹形态，你就能发现他的踪迹。"
D.Strings[95235]="一切顺利。等影眼兄弟一到，我们就前往暴风城！"
D.Strings[95236]="代我向兰达洛克问好，$n。"
D.Strings[95237]="燃烧军团向来心狠手辣。"
D.Strings[95238]="伊利达雷长存。"
D.Strings[95239]="迅捷的利刃和坚定的奉献精神，有这些就够了。"
D.Strings[95240]="你感觉到他们的力量在滋长了吗？"
D.Strings[95241]="我们的战斗才刚刚开始。"
D.Strings[95242]="小心！这片废墟里充斥着枯法者，这些怪物不断渴求着魔力。阿莎曼之牙的力量或许会吸引他们去跟踪维斯托克。"
D.Strings[95243]="燃烧军团又回来了。"
D.Strings[95244]="可惜你这是自寻死路。"
D.Strings[95245]="你的力量无人能及。"
D.Strings[95246]="你不是伊利达雷的对手。"
D.Strings[95247]="我会等着你再次归来的。"
D.Strings[95248]="你的行为似乎惹怒了那些枯法者。这或许对你有利。去找找另一个开关吧。"
D.Strings[95249]="我还以为战斗会更激烈呢。"
D.Strings[95250]="追踪单元是你负责的！"
D.Strings[95251]="别以为你能走到这里就有机会了。你什么都不是！不是！"
D.Strings[95252]="或许我们的伪装模块效果太好了点。"
D.Strings[95253]="好吧，是你说要赋予它们自由意志的！"
D.Strings[95254]="我的大军无穷无尽！"
D.Strings[95255]="如果我们想要把突进和冲刺找回来，就得找人帮忙……"
D.Strings[95256]="再见，笨蛋！"
D.Strings[95257]="夜之子灵魂石是我的。你们真是越来越烦人了。"
D.Strings[95258]="我将征服万千世界！"
D.Strings[95259]="奇兰妮丝夫人，等你解决我们这些过分热情的朋友之后，就到魔环来见我。"
D.Strings[95260]="军团的仆从们，消灭这些蛆虫！"
D.Strings[95261]="冲刺！"
D.Strings[95262]="他好像很喜欢你。你愿意代我照顾他吗？"
D.Strings[95263]="感受我的凝视，和绝望吧！"
D.Strings[95264]="跑吧！颤抖吧！尖叫吧！"
D.Strings[95265]="你们的护盾保护不了你们了！"
D.Strings[95266]="滚开，废物！"
D.Strings[95267]="愚蠢的地表来客！滚开！"
D.Strings[95268]="安静，爬虫！"
D.Strings[95269]="现在你的魔法在哪儿呢？"
D.Strings[95270]="我们来看看你是不是永生不死吧？"
D.Strings[95271]="我绝不容忍任何蠢货！"
D.Strings[95272]="小心着陆，亲爱的。"
D.Strings[95273]="呃……固执的爬虫……"
D.Strings[95274]="恶魔猎手，那个小鬼偷了魔典。抓住它！"
D.Strings[95275]="一只小鬼？这里怎么了，$n？"
D.Strings[95276]="你以为我们不知道你的盘算吗，$n？"
D.Strings[95277]="伊利达雷自以为立于不败之地。他们很快就要倒霉了。"
D.Strings[95278]="噢，真好。一盒新玩具！"
D.Strings[95279]="兄弟姐妹们——今天，我们保护了自己的土地免受燃烧军团的荼毒。我们实力雄厚，万众一心。为了部落！"
D.Strings[95280]="连我的剑都没法击退那些家伙。"
D.Strings[95281]="我完全没有防备！等着一切结束之后我再回来吧！"
D.Strings[95282]="维库牧人站在羊群里呼救。"
D.Strings[95283]="这个维库牧人再次从羊群中发出喊声，希望得到进一步的帮助。"
D.Strings[95284]="维库牧人再次呼救，希望有人能伸出援手。"
D.Strings[95285]="阿莎曼之牙是我的！我的！"
D.Strings[95286]="我看见你了！虽然你看着像个德鲁伊，但我知道你是经过伪装的恶魔。别想骗过我！你休想抢走我的阿莎曼之牙！"
D.Strings[95287]="维斯托克疯了吗？阿莎曼之牙能提高感知能力，可我怕这会加剧他的妄想症。"
D.Strings[95288]="虽然守望者人数稀少，但正义不会松懈，朋友。帮我们解决这邪恶的怪物。让这里的人民看看，守望者仍在警惕着邪恶的威胁！"
D.Strings[95289]="我找不到你的文件了，市民。"
D.Strings[95290]="祝你们好运！"
D.Strings[95291]="你的任务是胜利。"
D.Strings[95292]="暴风城感谢你的帮助！"
D.Strings[95293]="胜利在等待着你，士兵！"
D.Strings[95294]="走开，恶魔！滚开！你怎么还不滚！？"
D.Strings[95295]="你一定要夺回阿莎曼之牙，$n。它们在维斯托克的手里时间越长，他的妄想症就越严重。"
D.Strings[95296]="我的科多兽！他们会付出代价的！"
D.Strings[95297]="我的家畜！你这个长着恶魔角的丑八怪！"
D.Strings[95298]="小队前来报到！"
D.Strings[95299]="出来。我没时间跟你们玩游戏。"
D.Strings[95300]="让开，肖尔！如果我们失手，暴风城就会化为火海。"
D.Strings[95301]="十字路口东部！那里刚刚出现了一座建筑！"
D.Strings[95302]="你不走？很好，我会亲手结束这场追逐战！"
D.Strings[95303]="不！我绝不投降！"
D.Strings[95304]="你太让我失望了，暴风城的国王。但你迟早会看清真相的。你们都会的！"
D.Strings[95305]="好极了……是肖尔。"
D.Strings[95306]="我们注意到了隐蔽之手的活动。在“我们”处理完问题之前，这城市就被封锁了。"
D.Strings[95307]="在事情解决之前，谁都不能通过这些大门……尤其是你们两个人！"
D.Strings[95308]="啊，你来了！我已经开始了。阿洛迪也来了吧？"
D.Strings[95309]="我在，不过远离大厅削弱了我的力量。"
D.Strings[95310]="尽力就好，老朋友。欢迎来到法罗纳尔，军团的重要入侵点！"
D.Strings[95311]="我去引开下方的守军，你去关键位置设置仪式结界。"
D.Strings[95312]="这是构建结界的咒语。三个应该就够了。"
D.Strings[95313]="你完成后，就来末世祭坛找我。它应该很容易找。祝你好运！"
D.Strings[95314]="别多管闲事，“半兽人”。"
D.Strings[95315]="门关上了？去庭院里看看，有没有能打开它们的东西。但要小心枯法者。"
D.Strings[95316]="它就藏在书架上，真可爱。"
D.Strings[95317]="该死的恶魔！他们居然以蓝龙为食！防御者都倒下了吗？"
D.Strings[95318]="啊！这是什么？快放了我！"
D.Strings[95319]="那艘军团战舰已经说明了问题。这绝对是拯救世界的一战！"
D.Strings[95320]="这里不错。议会就应该防止军团入侵。局势怎么会糜烂到这种地步？！"
D.Strings[95321]="魔法回廊地窟可能已经被燃烧军团的入侵者，和我们的老朋友米尔豪斯·法力风暴攻破了。虽然他完全不可靠，但我想我们或许可以利用他那极具创意的技巧。"
D.Strings[95322]="看看谁掉进我的网中了！今晚能大吃一顿了！"
D.Strings[95323]="我对这个所谓的国王，还有他的破城堡，以及那些对他唯命是从的白痴追随者没多少耐心。"
D.Strings[95324]="嘿，我们这儿不招待恶魔。它得到门外等着！"
D.Strings[95325]="傲慢的混蛋！为了找到那个使徒，我们得搞点动静引开他们。唔……"
D.Strings[95326]="$n——你拿到了风暴守护者的拳套！我才不跟你打呢。"
D.Strings[95327]="你可以过去了，萨满。"
D.Strings[95328]="你是风暴的守护者，$n。我是不会挡你的路的。"
D.Strings[95329]="我看到了你手中的武器，$n，我愿意听从你的号令。"
D.Strings[95330]="啊，对了！去贸易区找埃林·提亚斯。他那儿有烟雾弹。只要把它扔到公共场所，卫兵们就必须行动了。"
D.Strings[95331]="在他们忙着调查骚乱时，我们就能收集情报并采取行动，而不必担心遭遇大队援军了。"
D.Strings[95332]="你可以过去了，$n。这里的风暴不会来招惹你的。"
D.Strings[95333]="至高守护者选中的人终于来了。$n，这里的元素不会来招惹你的。"
D.Strings[95334]="你掌握着我们主人的拳套，$n。这里的风暴不会伤害的。"
D.Strings[95335]="到山顶去吧，$n。你拿到了风暴之拳，风已经提前宣告了你的到来。"
D.Strings[95336]="我们走。我会紧跟你的。"
D.Strings[95337]="狡猾的小鬼！它去了东南边，然后就消失了。"
D.Strings[95338]="快，$n，看看你的幽灵视觉能否找到它。"
D.Strings[95339]="那是什么东西！？小心， $n！"
D.Strings[95340]="让我看看。"
D.Strings[95341]="希尔格林在信件堆里快速翻动。"
D.Strings[95342]="唔。他们最近带走了很多人。还有孩子。"
D.Strings[95343]="康妮会不会和那些孩子在一起？"
D.Strings[95344]="很有可能。我会让这位朋友跟踪卫兵，查明真相的。"
D.Strings[95345]="决不能让她打开种子！"
D.Strings[95346]="总算自由了！我还以为自己要喂蜘蛛了！"
D.Strings[95347]="与死亡擦肩而过令我清醒了过来。我之前把一切都看成了威胁，很抱歉攻击了你。"
D.Strings[95348]="我想保护阿莎曼之牙，但很快就被它压垮了。你证明了自己更有能力保护它们。请收下它们吧。"
D.Strings[95349]="我现在只能让你抿一口……"
D.Strings[95350]="这应该能稍微缓解一下痛苦。"
D.Strings[95351]="喝慢点，多含一会儿。"
D.Strings[95352]="慢点，我们一滴都浪费不起。"
D.Strings[95353]="给，感谢你的耐心。"
D.Strings[95354]="虽然不多，但请喝了它吧。"
D.Strings[95355]="我明天会设法多搞一些来。现在只有这点了。"
D.Strings[95356]="这应该够你的孩子们喝了。"
D.Strings[95357]="|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t灰谷的迷雾中出现了一头笨拙的噬心魔！"
D.Strings[95358]="|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t辛特兰的迷雾中出现了一头笨拙的噬心魔！"
D.Strings[95359]="|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t菲拉斯的迷雾中出现了一头笨拙的噬心魔！"
D.Strings[95360]="但愿你不要将风暴带到这片祥和的林地中来，$n。"
D.Strings[95361]="遵命，长官！我们保证不让任何人进入城市。"
D.Strings[95362]="隐秘通途会尽力帮忙的。"
D.Strings[95363]="卫兵们，到你们岗位上去！在这场骚乱平息之前，谁都不准进入城市。"
D.Strings[95364]="换岗！"
D.Strings[95365]="起步走！"
D.Strings[95366]="保持警惕！到你们的岗位上去！"
D.Strings[95367]="我不喜欢这里！快走！"
D.Strings[95368]="我要妈妈！"
D.Strings[95369]="你在做什么？"
D.Strings[95370]="快走啦！"
D.Strings[95371]="啊！不！"
D.Strings[95372]="我……*吸鼻子*好像认识这条街。"
D.Strings[95373]="呃……对……对了！那是凡瑟尔的房子！"
D.Strings[95374]="我们的长剑随时都能出鞘！"
D.Strings[95375]="传送门就快开启了，亲爱的。"
D.Strings[95376]="好了。黑暗神殿和阿卡玛在等着你呢，$n。"
D.Strings[95377]="忘了魔网吧，兄弟们！我们将以巨龙为食！"
D.Strings[95378]="我会一直跟着你的，朋友，就像现在一样。这个世界比起我那个时代已经变了许多。我很乐意探索一下这些岛屿。"
D.Strings[95379]="我会帮你构建结界以及使用法力宝石。然后就是黑檀之寒的问题了。"
D.Strings[95380]="这根法杖并不是为恶魔设计的。如果你能拖住巴拉杜尔，我就能跟他争夺法杖的控制权。我们合作的话，或许还有机会。"
D.Strings[95381]="听到没有，小伙子？他们是专程来看你的。"
D.Strings[95382]="米尔豪斯，你真有闯祸的天分！"
D.Strings[95383]="大法师瓦格斯也在寻找夜之子灵魂石。你们两个应该合作，在他发现灵魂石之前找到他。"
D.Strings[95384]="什么？！夜之子灵魂石是我的！让我们去拿到它吧！"
D.Strings[95385]="我不喜欢这里……\n\n<吸鼻子。>"
D.Strings[95386]="我可以送你回家。跟我来，小家伙。"
D.Strings[95387]="突进！"
D.Strings[95388]="你把他照顾得很好。不如就让你继续照顾他好了。"
D.Strings[95389]="我建议找个地方躲起来，直到战斗结束！"
D.Strings[95390]="这里不安全！快离开这儿！"
D.Strings[95391]="这里是不是变冷了？"
D.Strings[95392]="别碰我的朋友！"
D.Strings[95393]="……哇！！"
D.Strings[95394]="准备去找骨头了吗，小伙子？"
D.Strings[95395]="激流堡是我的！我不会把它给我父亲，更别说其他人！"
D.Strings[95396]="我可是王子！你们……竟敢……"
D.Strings[95397]="现在还不算迟。我们要跳到山上横扫他们，并且……"
D.Strings[95398]="不，不……到处都是他们的人！"
D.Strings[95399]="让我们好好清理一下这个地方，然后我们就可以开始钓美味的狂鱼了！"
D.Strings[95400]="抓紧，$n。我们要下降了。"
D.Strings[95401]="我钓到的狂鱼都在这儿了。"
D.Strings[95402]="抓住那个孩子！"
D.Strings[95403]="跟上她！"
D.Strings[95404]="离那个孩子远点儿！"
D.Strings[95405]="你成功了!我感觉这一带的魔力浓度在上升。恶魔也暂时撤退了。我敢打赌，他们是在策划强攻。"
D.Strings[95406]="接下来的事情比较棘手。我们要启动仪式抽取能量。届时，我们可能会遭到攻击。我来摆放法力宝石。"
D.Strings[95407]="你来引导仪式焦镜。一旦收集到了足够的魔力，就能引起巴拉杜尔的注意了。"
D.Strings[95408]="做好准备，咒术师。我觉得巴拉杜尔恐怕不会热情欢迎我们的。"
D.Strings[95409]="让我们开始施法吧。"
D.Strings[95410]="我会努力解决大部分敌人，但很可能会应付不过来。你得时不时中断施法来帮我一把。如果你准备好了，那我们就开始吧。"
D.Strings[95411]="很好！集中精神构建仪式焦镜，我会尽力支援你的。"
D.Strings[95412]="或许我们可以闪现过去！"
D.Strings[95413]="噢，我的宝贝！你受伤了吗？他们亏待你了吗？"
D.Strings[95414]="他们把我关在笼子里！我想你……"
D.Strings[95415]="我在四处转悠，钓取狂鱼的时候，注意到这片礁湖里出现了一些巨大的气泡。"
D.Strings[95416]="你现在安全了，感谢女神。"
D.Strings[95417]="我怀疑这下面是有什么东西才导致了这种现象。让我们看看我能不能把它从藏身之处给弄出来吧。"
D.Strings[95418]="记住，我们是来拉拢阿卡玛的，不是来杀他的。"
D.Strings[95419]="我不知道你为何回来，伊利达雷，但这大错特错。这次，等着你的不是监狱……而是死亡。"
D.Strings[95420]="我们上去吧，凯恩。是时候说服阿卡玛加入我们了。"
D.Strings[95421]="大海在上，那是什么玩意儿？！"
D.Strings[95422]="快！快干掉它，随便用火还是你们冒险者的其他手段都行！"
D.Strings[95423]="去干你该死的活儿吧！我们不能再这么活下去了！"
D.Strings[95424]="冷静点。城里精锐的部队已经在处理这个案子了。"
D.Strings[95425]="瘟疫"
D.Strings[95426]="让我们看看你的鼻子有多灵。"
D.Strings[95427]="好样的！现在我们去找那些法师！"
D.Strings[95428]="啊，你来了。埃林正在楼上等你们呢。"
D.Strings[95429]="你知道吗？在这么短的时间里，把这玩意儿弄进戒严的城里可不容易。"
D.Strings[95430]="一旦扔出炸弹，你最好迅速逃离现场。哈蒙德和他的人一定会像扑火的飞蛾一样扑向那座大厅的。"
D.Strings[95431]="搜索"
D.Strings[95432]="感谢您使用奥杜尔的传送网络！$b$b当前所有传送节点都处于维护当中，无法使用。如遇紧急情况，请在工作时间段与访客信息代表联络。$b$b祝您度过愉快的一天！"
D.Strings[95433]="卖战袍了！给前线增添属于你的色彩吧！"
D.Strings[95434]="天呐！我差点就没能及时把你救出来。你得再小心点儿，老伙计！"
D.Strings[95435]="卖战袍！和你的盟友一起，展现你们的团结吧！"
D.Strings[95436]="在离家之前，让你的色彩飞扬，今天就买一件战袍吧！"
D.Strings[95437]="回到主人这儿来！"
D.Strings[95438]="谁是多愁善感的大块头机械狼？就是你！就是你！"
D.Strings[95439]="蠢货！你真以为一块小木头就能阻止我吗？！"
D.Strings[95440]="鲜血滋养了我！"
D.Strings[95441]="我……是不会……失败的……"
D.Strings[95442]="希尔格林点点头。"
D.Strings[95443]="快点，给那些绷带加好祝福，我们得把它们送去前线！"
D.Strings[95444]="他们来了！我需要一点帮助！"
D.Strings[95445]="一份礼物，给我的吗？"
D.Strings[95446]="努力干活儿……废物。"
D.Strings[95447]="真精彩！回去构建焦镜吧。我来盯着这边。"
D.Strings[95448]="能量正在汇聚。他们马上就会发现我们正在搞大动作了。又来了一群恶魔！帮帮我！"
D.Strings[95449]="这真是个可怕的转折……"
D.Strings[95450]="我们今晚恐怕对付不了大魔导师了，但她迟早会受到制裁的。我们一定能想出办法来解决问题……"
D.Strings[95451]="我必须跟议会谈谈。后会有期，我的凡人朋友。"
D.Strings[95452]="不！他休想就这么逃之夭夭！"
D.Strings[95453]="你显然需要我这样的天才帮忙。让我们一起去找瓦格斯和灵魂石吧！"
D.Strings[95454]="别走开……现在是进餐时间！"
D.Strings[95455]="这是什么？又来了一个入侵者！"
D.Strings[95456]="那个恶魔叫瓦迪纳，他是巴兰杜尔的副手之一！我想我们引起他的注意了！协助我！"
D.Strings[95457]="你真以为这点小花招会有用吗？来吧，小法师！"
D.Strings[95458]="我虽然还小，可至少我吸引了所有人的注意！"
D.Strings[95459]="别对我评头论足的！"
D.Strings[95460]="需要保护的市民请立刻到交易者大厅去报到。"
D.Strings[95461]="事态已经得到控制。你们都很安全。"
D.Strings[95462]="这些蛋被腐蚀了。我们得摧毁它们。"
D.Strings[95463]="解决腐蚀的方法可不止一种。"
D.Strings[95464]="那些守卫，他们在苏醒！"
D.Strings[95465]="在上面，我看见那些法师了！他们被驯犬者的爪牙包围了！"
D.Strings[95466]="快，干掉这些野兽，别让它们造成更多伤害！"
D.Strings[95467]="再这么下去，我们永远都别想完成任务了。动作快点儿，你们这些蠢货！"
D.Strings[95468]="如果我们不能尽快完成的话，沙考尔会不高兴的。快点儿搬！"
D.Strings[95469]="守住入口！我们已经把邪教徒引入了包围圈。"
D.Strings[95470]="你休想干扰它们进食！"
D.Strings[95471]="我的猎犬饿了，你的法师将成为它们的美餐。"
D.Strings[95472]="很快，它们就会更强大，足以杀光达拉然所有的法师！"
D.Strings[95473]="来吧，我的宠物。你们很快就能大吃一顿了。"
D.Strings[95474]="我的仆从们想吃掉你，大法师。"
D.Strings[95475]="对敌人的了解永远都不嫌多。这些书和卷轴是直接从暴风城图书馆拿出来的。"
D.Strings[95476]="嘿，大块头，你有伴儿了！"
D.Strings[95477]="大块头要好好揍他们一顿！"
D.Strings[95478]="你休想逍遥法外，哈卡！"
D.Strings[95479]="为了惩罚你的傲慢，我要慢慢折磨死你！"
D.Strings[95480]="这场闹剧毫无意义！你死定了！"
D.Strings[95481]="你有着大法师的力量！可我还有别的招……"
D.Strings[95482]="枯法猎魔者发现了你的存在！"
D.Strings[95483]="你休想再用黑檀之寒害人了，恶魔！"
D.Strings[95484]="枯法猎魔者注意到了你！"
D.Strings[95485]="呸！我不用这些破武器也能毁了你！"
D.Strings[95486]="你们的世界……必将……陨落……"
D.Strings[95487]="胡恩的仁慈为他赢得了高岭家族最古老的盟友：我。"
D.Strings[95488]="我们团结一致！"
D.Strings[95489]="传送门要关闭了！快走！"
D.Strings[95490]="必须阻止燃烧军团！"
D.Strings[95491]="干得好！我来开启返程的传送门。我们得在援军抵达前离开。"
D.Strings[95492]="我的弓已经准备就绪！"
D.Strings[95493]="记住我们失去的一切。"
D.Strings[95494]="我们将携手拯救艾泽拉斯！"
D.Strings[95495]="想浪费我的时间？我可没工夫。"
D.Strings[95496]="我们必须尽到自己的义务。"
D.Strings[95497]="我们听命于游侠将军。"
D.Strings[95498]="他们在翻我的抽屉——小偷！拜托了，请夺回我的财产。"
D.Strings[95499]="我的长袍！啊，我好想它们！但愿它们还能合身……"
D.Strings[95500]="我得盯着这些书，以防艾利桑德发起疯，连图书馆都不放过。"
D.Strings[95501]="最好别让他们知道我之前都跟谁谈过话。"
D.Strings[95502]="我们生活在一个艰难的时代。"
D.Strings[95503]="你准备好继续寻找失踪的法师了吗？"
D.Strings[95504]="心向和平，不忘战斗！"
D.Strings[95505]="胜利必将到来。"
D.Strings[95506]="隐秘通途欢迎你！"
D.Strings[95507]="战斗已经迫在眉睫！"
D.Strings[95508]="保护艾泽拉斯就是我们的义务。"
D.Strings[95509]="愿你的武器百发百中！"
D.Strings[95510]="我活了一万年，可不是为了陪你胡闹的！"
D.Strings[95511]="我的箭术天下无双！"
D.Strings[95512]="让我们赢下这场战争吧！"
D.Strings[95513]="挑战在等待着我们！"
D.Strings[95514]="祝你百发百中！"
D.Strings[95515]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-E，这是一台二级机密等级的终端。$B$B检测到彩色穿孔卡片。权限开放。\n\n01010011 01110100 01100001 01101110 01100100 00100000 01100010 01100001 01100011 01101011 00100001 01010011 01110100 01100001 01101110 01100100 00100000 01100010 01100001 01100011 01101011 00100001"
D.Strings[95516]="远行者时刻准备着。"
D.Strings[95517]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-E，这是一台二级机密等级的终端。$B$B你必须拥有一张彩色穿孔卡片才能使用该终端的功能。\n\n01001000 01110101 01101110 01110100 01100101 01110010 01110011 00100000 01101111 01101110 01101100 01111001 00100001"
D.Strings[95518]="啊，法尔多拉神殿。艾露恩的祷文曾响彻这里。"
D.Strings[95519]="我想这里现在恐怕没那么好客了。别动，我把你弄出去。"
D.Strings[95520]="好了，别动。我这就把你弄出去。"
D.Strings[95521]="我会尽力守护艾泽拉斯的。"
D.Strings[95522]="愿胜利属于我们！"
D.Strings[95523]="我们决不能动摇！"
D.Strings[95524]="愿风指引你的箭矢。"
D.Strings[95525]="彩色穿孔卡片读取成功。正在关闭安全锁。\n\n01010111 01100001 01110011 00100000 01110100 01101000 01101001 01110011 00100000 01100001 01101100 01110111 01100001 01111001 01110011 00100000 01101100 01101111 01100011 01101011 01100101 01100100 00111111"
D.Strings[95526]="关闭安全措施"
D.Strings[95527]="你比女妖还要烦人！"
D.Strings[95528]="你成功了！守住它，直到返回我身边为止。"
D.Strings[95529]="那头蠢牛根本就不会察觉的……我们将彻底控制整个舰队！"
D.Strings[95530]="海底女王曾用魔力造起了一座帝国。后来，她成了一个……更阴险的控制者。"
D.Strings[95531]="艾萨拉女王……不要低估她的魔法造诣，和她那些走狗的忠诚。"
D.Strings[95532]="那个纳迦掌握了魔法，但还不算出色。过去，艾萨拉的人民可是能对抗泰坦的。"
D.Strings[95533]="纳迦想在这座废墟里找回昔日的辉煌，所以埋头寻找碎片。让他们看看真正的力量。"
D.Strings[95534]="巨龙军团曾代替泰坦统治这个世界。看看这些家伙是怎么吃老本的吧。"
D.Strings[95535]="奈萨里奥从其他巨龙军团那里偷来了许多秘密。有些可能会对我们有用，孩子。"
D.Strings[95536]="泰坦为巨龙军团灌注了庞大的力量。黑龙军团已经快被杀光了。我们应该拿走残余的力量。"
D.Strings[95537]="占据这里的渣滓玷污了这个盛极一时的巨龙军团的荣耀。"
D.Strings[95538]="这个地方充斥着魔力……你感觉到了吗？这么多力量……"
D.Strings[95539]="古代帝国的辉煌遗产。这里有力量，孩子……你只需要攫取它！"
D.Strings[95540]="这座城市建在强大的奥术能量矩阵上。啊……足够我们俩享用的力量……"
D.Strings[95541]="一个辉煌的帝国，在魔力中迷醉了数千年。让我们打碎这些殿堂，啜饮废墟中的能量吧。"
D.Strings[95542]="你肯定也明白，凡人的议会想要控制这样的魔法宝库是多么徒劳的吧？"
D.Strings[95543]="达拉然一代又一代的凡人法师将自己的恐惧埋进这些高墙里。他们太软弱了，孩子。"
D.Strings[95544]="你的前任在这些大厅里徘徊了很多年，孩子。你真想挖掘这些往事吗？"
D.Strings[95545]="我欣赏你的求知欲，孩子。你的前任试图将黑暗禁锢起来，但你是不会害怕的，对吧？"
D.Strings[95546]="在太古时代，泰坦们使用奥术的语言编织世界。移动城市这种事……太微不足道了。"
D.Strings[95547]="与辉煌灿烂的苏拉玛相比，这座城市太小了。"
D.Strings[95548]="卑微的达拉然。可怜的凡人政治阻碍了他们获取真正的力量。"
D.Strings[95549]="魔法建造了这座城市，也滋养了这座城市。放开我，法师，我要吸干它……"
D.Strings[95550]="就算埋头苦学，凡人法师一生获得的知识也很有限。真奇怪，他们居然没有放弃。"
D.Strings[95551]="达拉然。历经了几代凡人居民，这座城市依然屹立不倒。"
D.Strings[95552]="这座城市的法师视它为世界的魔法中心。多无知啊，孩子。"
D.Strings[95553]="虽然领导它的凡人间有些可笑的争端，这个地方收集的奥术知识还算看得过去。"
D.Strings[95554]="啊，达拉然。这座千塔之城再次挡在了凡人和世界末日之间。"
D.Strings[95555]="亲爱的孩子，你很克制啊。你掌握的力量足以将这座城市震到海里去。"
D.Strings[95556]="你们的法师世代在这座城市中训练，就像是孩子在玩火一样。"
D.Strings[95557]="肯瑞托。卑微的凡人在此埋头研究他们的小脑瓜理解不了的力量。"
D.Strings[95558]="我……没有法力了……"
D.Strings[95559]="我需要更多法力，孩子……"
D.Strings[95560]="我的能量在减少。"
D.Strings[95561]="你得控制一下节奏了，孩子。"
D.Strings[95562]="你是在浪费能量……"
D.Strings[95563]="回到这里，我的心情也很复杂。或许有一天，我们会重建这座神殿。\n\n可现在，让我们说服阿卡玛加入我们，然后返回邪能之槌号吧。\n\n你准备好之后，就告诉我们一声吧，$n。"
D.Strings[95564]="你的法力支撑不下去了，孩子。"
D.Strings[95565]="我必须……补充能量……"
D.Strings[95566]="法力……你需要更多法力……"
D.Strings[95567]="你脆弱的躯壳维持不了这种节奏。"
D.Strings[95568]="我们需要充能……"
D.Strings[95569]="力量，我需要……更多力量……"
D.Strings[95570]="我们很聪明，不是吗？"
D.Strings[95571]="我们的魔法能隔绝窥探的视线……"
D.Strings[95572]="你害怕战斗吗？真有意思。"
D.Strings[95573]="人人都有自己的小秘密，对吧？"
D.Strings[95574]="你总要不停进食，这太奇怪了。"
D.Strings[95575]="你的盟友太依赖你了。让他们饿着吧。"
D.Strings[95576]="你居然把自己的天才浪费在……制造布丁上。"
D.Strings[95577]="你掌握着太古泰坦的力量，可你却用它来制造……美味的点心？"
D.Strings[95578]="现在，这个法术归我们了。"
D.Strings[95579]="这招很聪明，孩子。你进步了。"
D.Strings[95580]="噢，很好。干得好。"
D.Strings[95581]="你的敌人真蠢，居然对你用这种小把戏。"
D.Strings[95582]="呃，让他们慢慢走吧。"
D.Strings[95583]="你竟然把宝贵的能量浪费在这些挥剑的莽夫身上。"
D.Strings[95584]="你有没有想过开启一扇通往其他世界的传送门？你拥有这种力量，孩子……"
D.Strings[95585]="那些老鼠就在里面。我们得撬开他们的嘴巴，搞清使徒的下落。"
D.Strings[95586]="我们走过一地又一地……敌人倒了一批又一批……"
D.Strings[95587]="谁都别想再控制我！"
D.Strings[95588]="我不会向你的烂魔法屈服的！"
D.Strings[95589]="你不如之前那个她强大。你是不会成功的！"
D.Strings[95590]="我是永恒不灭的。"
D.Strings[95591]="凡人休想得到艾露尼斯的智慧！"
D.Strings[95592]="[恼怒的尖叫]"
D.Strings[95593]="你以为能像前任“守护者”那样控制我？在我眼里，你只是个孩子。"
D.Strings[95594]="你觉得自己能控制这股力量，好吧。"
D.Strings[95595]="来吧，孩子。让我们摧毁你的敌人，看看你的本事吧。"
D.Strings[95596]="我们上去吧，奥图里斯。是时候说服阿卡玛加入我们了。"
D.Strings[95597]="你好啊，肉体凡胎！"
D.Strings[95598]="回家的感觉真不错，哪怕只是短暂的停留。或许有一天，我们能为伊利达雷夺回这座神殿。\n\n不过现在，让我们看看能不能说服阿卡玛加入我们……或是怎么样吧。\n\n你准备好之后，就告诉我们一声吧，$n。"
D.Strings[95599]="记住，我们是来不择手段“说服”阿卡玛加入的。"
D.Strings[95600]="烧死他们！"
D.Strings[95601]="打！打啊，你们这些废物小鬼！"
D.Strings[95602]="把他们烧成灰！"
D.Strings[95603]="去啃他们的骨头吧！"
D.Strings[95604]="对！这家伙对我们很有用！"
D.Strings[95605]="臣服于你的新主人吧！"
D.Strings[95606]="万物都将臣服于我！"
D.Strings[95607]="很高兴看到我不是这儿唯一被大卸八块的人。"
D.Strings[95608]="你们别想再破坏我们的计划了。杀了他们！"
D.Strings[95609]="很好！杀了你们，就能让我在新教派里占据高位。"
D.Strings[95610]="以刀剑的名义！"
D.Strings[95611]="那些恶魔应该在踏上我们的地盘前三思而行！"
D.Strings[95612]="一个部落！"
D.Strings[95613]="玛沃伦丝，别让任何人通过那扇门。"
D.Strings[95614]="不能翻过去的话，我们只能闯过去了。打开它。"
D.Strings[95615]="不能翻过去的话，我们就只能闯过去了。打开它。"
D.Strings[95616]="我同意，如果他能保持克制，我们也会的。"
D.Strings[95617]="我知道了，凯恩。但愿他能理智一点，否则的话……"
D.Strings[95618]="看来你是铁了心了。那来吧，伊利达雷，来受死吧。"
D.Strings[95619]="看我能否让你大吃一惊吧。"
D.Strings[95620]="让我们体面地解决这件事吧。你能做到吗，恶魔猎手？"
D.Strings[95621]="你光明正大地击败了我。或许我看错了你，恶魔猎手。\n\n我们还需要一些时间才能彻底达成互信。但和你一样，我也想看到燃烧军团垮台。\n\n他们摧毁了我美丽的神殿。我会复仇的。\n\n为了实现这个目标，我愿意帮助你，$n。"
D.Strings[95622]="我是不会帮你的，恶魔猎手。和其他恶魔猎手一样，你并不比跟你厮混的那些恶魔强多少。我看不出你跟他们有什么分别。\n\n燃烧军团和你的主子摧毁了我美丽的神殿。相信我，总有一天，我会复仇的。\n\n滚回虚空去发疯吧，$n。"
D.Strings[95623]="那就站起来，加入我们吧，阿卡玛。"
D.Strings[95624]="看来我别无选择了，阿卡玛。无论如何，你必须帮我们打败燃烧军团。"
D.Strings[95625]="阿卡玛，想想！我也反对伊利丹。相信我们吧。"
D.Strings[95626]="也许你说得对。世道确实变了，伊利达雷。我愿意帮助你们。"
D.Strings[95627]="请上来吧，主母。我们要返回邪能之槌号了。"
D.Strings[95628]="遵命，亲爱的。只有一条上去的路。"
D.Strings[95629]="杀了我，做个了结吧。"
D.Strings[95630]="噢，我可不这么想。阿莱利，动手。"
D.Strings[95631]="主母，上来吧。我们要回邪能之槌号了。"
D.Strings[95632]="折磨宝珠好奇地盯着所有玩家。"
D.Strings[95633]="使徒呢？说！"
D.Strings[95634]="你们这是螳臂当车。军团必将淹没这世界！"
D.Strings[95635]="你们就这点本事吗？真没用！"
D.Strings[95636]="那好吧。我倒要看看你怎么抵抗君王之灾！"
D.Strings[95637]="动手吧。我的生命属于隐蔽之手！"
D.Strings[95638]="怎……怎么回事……我的血管……在燃烧……！"
D.Strings[95639]="求你了……住手！我什么都告诉你！快停下！"
D.Strings[95640]="使徒在哪儿？快说，可怜虫！"
D.Strings[95641]="他躲在……要塞里……"
D.Strings[95642]="要塞守卫森严。我们得分头行动。至少要有一个人能活着找到使徒。"
D.Strings[95643]="时间不多了。快行动吧！"
D.Strings[95644]="这就想逃跑了吗？"
D.Strings[95645]="一定要想好退路。这是我的惨痛教训！"
D.Strings[95646]="你对此有什么想法？"
D.Strings[95647]="愚蠢的兽人！你将首先见证军团降临我的城市。"
D.Strings[95648]="我早就在等这一天了。别再浪费时间了！"
D.Strings[95649]="我感觉到他们的诅咒被削弱了！你必须阻止他们干扰仪式！"
D.Strings[95650]="成功了！你们这些腐朽的骨语走狗再也不能阻止我进入英灵殿了！"
D.Strings[95651]="激流堡终于归我了！蠢货，你们以为我会让父亲夺回它吗？"
D.Strings[95652]="卫兵！抓住他们！"
D.Strings[95653]="是军团的援军！不要手软！"
D.Strings[95654]="北边的塔楼里挤满了恶魔渣滓！到处都是恶魔！"
D.Strings[95655]="十字路口东边出现了一座建筑！那里都是恶魔！"
D.Strings[95656]="恶魔建筑！在十字路口东边！快离开这儿！"
D.Strings[95657]="通往十字路口东部的道路！那里出现了某种建筑！它就那么凭空冒了出来！"
D.Strings[95658]="十字路口的东南边凭空出现了一座建筑！"
D.Strings[95659]="十字路口东南部！又一座建筑！这到底是什么邪恶魔法？"
D.Strings[95660]="东南边出现一座建筑！我们会尽可能守住十字路口。快去毁掉那些玩意儿！"
D.Strings[95661]="我的耐心正在流失。让我们找到那位王子，搞定这件事吧。"
D.Strings[95662]="他们往西边去了！那里有好几个营地！这些家伙以为他们能打垮我们吗？哈！"
D.Strings[95663]="西边的营地！这些恶魔简直不知疲倦！让他们看看你们的力量吧！"
D.Strings[95664]="叛徒！我要用斧子把这懦夫的脑袋劈成两半！"
D.Strings[95665]="肮脏的恶魔！西边遭遇围攻！快派援军来！"
D.Strings[95666]="棘齿城遭到猛攻！最好来点小小的支援！"
D.Strings[95667]="我和我的小伙子们把他们堵在了棘齿城，可是，呃……最好还是派点支援给我们！"
D.Strings[95668]="棘齿城遭到轰炸！瞄准那些丑八怪，别误伤我们这些帅气的好人，行吗？"
D.Strings[95669]="那家伙是自找的。"
D.Strings[95670]="又少了一个敌人。"
D.Strings[95671]="肮脏的恶魔！他们控制了我们东边的部队！他们似乎在向奥格瑞玛推进！"
D.Strings[95672]="你需要我帮你完成召唤仪式？你自己做不到吗？真可悲！"
D.Strings[95673]="他们消灭了我们派去东边的援军！我们正在桥头堵截他们！"
D.Strings[95674]="东边有一个巨型营地！我们需要支援！我们要被击溃了！"
D.Strings[95675]="北边发现恶魔建筑！这里的攻势非常猛烈！"
D.Strings[95676]="看来他们是在向灰谷推进！我们的盟友遭到了攻击！"
D.Strings[95677]="这颗珍珠是属于我的！"
D.Strings[95678]="我名叫……错误：无法定位数据……唔，看来我需要一个名字。"
D.Strings[95679]="噢，你是来找同伴的。很好，我愿意跟你走，猎人。"
D.Strings[95680]="不过，这个流程可能会触发我的防御协议。我可能对你的眼睛造成伤害。此信息仅供预警使用。"
D.Strings[95681]="梦魇怪物，消失吧！"
D.Strings[95682]="又击败一个邪恶的怪物。"
D.Strings[95683]="英雄，我们很默契啊！"
D.Strings[95684]="那家伙不怎么强嘛。"
D.Strings[95685]="又一场胜利！"
D.Strings[95686]="干得好。坚持下去！"
D.Strings[95687]="干得好。我们继续战斗吧！"
D.Strings[95688]="那家伙毫无胜算。"
D.Strings[95689]="他真不友好！"
D.Strings[95690]="这就是恶霸的下场！"
D.Strings[95691]="我们好好教训了他一顿！"
D.Strings[95692]="这真有趣！"
D.Strings[95693]="现在，梦境更安全了！"
D.Strings[95694]="众志成城，我们定能打败梦魇。"
D.Strings[95695]="又征服了一个敌人。"
D.Strings[95696]="山谷更安全了。"
D.Strings[95697]="干得不错，德鲁伊。"
D.Strings[95698]="保持警惕，英雄。接下来还有更多敌人。"
D.Strings[95699]="有个所谓的打捞队正在阿苏纳沿海肆意抢劫。他们的老板叫沙考尔先生。"
D.Strings[95700]="虽然沙考尔有时很有用，但我绝不容忍这种行为。去让他们明白，阿苏纳是不会养海盗的！"
D.Strings[95701]="如果不保持警惕，沙考尔的走狗就会将阿苏纳沿海的珍贵文物劫掠一空。他们还会回来，但相信你会做好准备的。"
D.Strings[95702]="我的间谍传回消息说，沙考尔先生这个所谓打捞队的许多重要头目都很弱小。"
D.Strings[95703]="去狠狠打击这些头目，让这群海盗群龙无首吧！"
D.Strings[95704]="这是个残酷的任务，但你做得很好。南部海滩暂时安全了。"
D.Strings[95705]="在我还有身体那会儿，搞这种仪式从来不用人帮忙。我是顶尖的召唤师！"
D.Strings[95706]="想从扭曲虚空里找只生物？想从虚空中抓头野兽？哦……你只想召唤个朋友……"
D.Strings[95707]="能跟我说说你的故事吗？"
D.Strings[95708]="感谢你这么说，$n，但我还是等战斗结束后再回来吧。"
D.Strings[95709]="这些愚蠢的维库人坚持认为泰坦总有一天会归来。"
D.Strings[95710]="这里看似圣洁，可我都能感应到军团的存在。"
D.Strings[95711]="我已经焦头烂额了！我还是等这事儿结束后再重新开业吧！"
D.Strings[95712]="这里的维库人自以为是举世无双的战士。我要让他们看看自己错得有多离谱！"
D.Strings[95713]="让我们好好整理一下。我们还有一堆事要做呢！"
D.Strings[95714]="这些维库人可不像你以为的那么好对付。"
D.Strings[95715]="这条路可以带我们离开。"
D.Strings[95716]="我等不及了，我要看着这些山峰燃起大火！"
D.Strings[95717]="已经很近了。"
D.Strings[95718]="我知道你们修复了古代传送器。这个道标能连接我们和你的夏多雷朋友。"
D.Strings[95719]="塞莉娅·灾火之主，来吧，我们将终结你的苦难！"
D.Strings[95720]="|TInterface\\Icons\\ability_ironmaidens_bloodritual:20|t卢卡多开始|cFFFF0404|Hspell:215000|h[吞噬生者]|h|r！快击杀这个海盗！"
D.Strings[95721]="天呐。我真是选错了出门的日子！"
D.Strings[95722]="我到底在想什么，才会跑到这种地方来？"
D.Strings[95723]="这可不是我想要的！现在，如果你不介意的话……"
D.Strings[95724]="这里到底出了什么事？"
D.Strings[95725]="我感觉到她了……塞莉娅·灾火之主。她动了！"
D.Strings[95726]="加基森的居民们受到了鼓舞，纷纷加入了对抗燃烧军团的战斗！"
D.Strings[95727]="可惜我不怎么能打。保重！"
D.Strings[95728]="艾瑞达，是被恶魔之王萨格拉斯控制的德莱尼。他们擅长邪能和暗影魔法，你们一定要按照情况调整结界。他们通常会指挥数量不等的恶魔部队，威胁极大，但也是很好的斩首目标。"
D.Strings[95729]="邪能领主是最近露面的一种邪能卫士，他们身材高大，远超那些低级爪牙，而且通常都会手持一把巨大但迟缓的武器。如果你们在落单时遇到了一个邪能领主，我建议你们立刻战术撤退。"
D.Strings[95730]="对于这种新的恶魔，我们所知不多。我们称它们为“鬼母”。有限的报告表明，她们的肚子可能是某种传送门，小鬼就是从里面涌出的。小心点，我们还不清楚你们在面对她们时会遇到什么情况。"
D.Strings[95731]="可怕的地狱火，燃烧军团的攻城武器。这种野蛮的怪物通常会用由邪能之火和岩石构成的燃烧之拳打破你们的防御。他们通常会像流星一样空降到战场上，然后舒展身体，造成更大的破坏。"
D.Strings[95732]="恐惧魔王，恐怕是燃烧军团部队中最阴险的存在了。他们可以用意志控制敌人，神不知鬼不觉地策反你一半的部队。小心他们的暗影魔法，以及他们控制的腐臭虫群。还要坚定你的意志，以对抗他们的恐怖幻象。"
D.Strings[95733]="抱歉，小鬼。我在执勤呢。总有人要去提醒这个恶魔渣滓，他们惹的是什么人！"
D.Strings[95734]="深渊领主是一种巨大、可怕的巨兽。即使只面对一只，没有一支大军的话，你们也没法活下来。他们手中的战戟能够轻易把一个人切成两半，并用邪能将半支小队烧焦。无论在什么距离上，他们都能构成威胁。"
D.Strings[95735]="我可不是每天都能拿出秘密武器来！"
D.Strings[95736]="我通常都是个很和善的人，可如果你妨碍了我，那我们就得好好聊聊了，朋友。"
D.Strings[95737]="小？你说“小”是什么意思？$B$B好吧，$n。看看我们谁先杀光这里的恶魔吧。"
D.Strings[95738]="你干掉他们之后，别忘了他们的武器！那些玩意儿挺值钱的。"
D.Strings[95739]="等这一切都结束后，别忘了光临你的免费——或是打九折——诺格弗格小店！"
D.Strings[95740]="这似乎不是你该来的地方，朋友。"
D.Strings[95741]="等这一切都结束后，记得提醒我再给这地方买点保险。"
D.Strings[95742]="把这家伙送出去，伙计们！"
D.Strings[95743]="我敢肯定，援军很快就会赶来的。我上面有人。"
D.Strings[95744]="东边的海上！看来燃烧军团又回来了！进入阵地！快！"
D.Strings[95745]="提高警惕！我有种不好的预感！"
D.Strings[95746]="你太迟了，刺客。"
D.Strings[95747]="快，种下种子！"
D.Strings[95748]="把它放在这儿，让它吸收魔网的能量。"
D.Strings[95749]="一头幼年地狱犬受到魔力的香气吸引，冲进了洞穴。"
D.Strings[95750]="我见过他们赐予的美妙礼物。你根本不明白！"
D.Strings[95751]="他们来了！噢，他们比我想象的还要美丽！"
D.Strings[95752]="你看不见吗？你感受不到他们温暖的拥抱吗？"
D.Strings[95753]="主人，你的仆人需要帮助！"
D.Strings[95754]="我的计划不会失败。我的命运更不会夭折。烧死你！"
D.Strings[95755]="主、主人……？"
D.Strings[95756]="很好。我们的任务完成了。"
D.Strings[95757]="带着弑君者来到这里，勾起了我……那些黑暗的回忆。我花了几年时间试图摆脱这种冲动。"
D.Strings[95758]="拿着这对匕首吧。你已经证明了自己是个老练的刺客。或许你能够克服它们的黑暗力量。"
D.Strings[95759]="猎珠人菲恩长大嘴巴瞪着你，看起来很困惑。"
D.Strings[95760]="猎珠人菲恩恼火地跳来跳去。"
D.Strings[95761]="猎珠人菲恩的双眼一缩，重重叹了口气。"
D.Strings[95762]="猎珠人菲恩激动地抓起沙子，开始打磨珍珠上的裂纹。"
D.Strings[95763]="<给菲恩看看蟹壳。>"
D.Strings[95764]="看来他们变得更强大了！你们最好别变成那些家伙的美餐了！"
D.Strings[95765]="奎因艾尔曾是冰风大师。只是靠近她都让我寒毛直竖。做好准备！"
D.Strings[95766]="奎因艾尔，冰风大师，来吧！我们将结束你永恒的痛苦！"
D.Strings[95767]="柯拉曾是常驻此地的奥能女王。她创造起法术来就像你呼吸空气那么容易。"
D.Strings[95768]="她过来了！奥能女王柯拉，我们将让你永远安息！"
D.Strings[95769]="<给菲恩看看蟹油。>"
D.Strings[95770]="<给菲恩看看蟹爪。>"
D.Strings[95771]="<给菲恩看看细沙。>"
D.Strings[95772]="末日守卫，是前线部队的指挥官。他们是很好的斩首目标。解决他们，就能瓦解敌人的阵线。但要小心他们的火焰魔法和黑暗诅咒，还有他们强大的近战能力。"
D.Strings[95773]="我的任务就是送你前往英灵殿。你准备好之后就告诉我一声吧。"
D.Strings[95774]="山洞并不是我扎营的首选，但是的确可以避免不必要的麻烦。$b$b我们现在就开始吧？"
D.Strings[95775]="你来得正是时候……我们正打算召唤这座神殿里最痛苦的灵魂，并终结她的痛苦。"
D.Strings[95776]="我带着失败归来，想用别人的血洗刷我的失败。"
D.Strings[95777]="看，苏拉玛。它是天堂，是神殿。"
D.Strings[95778]="我在那里找到了提尔的勇士祭坛，却不得其门而入。我试了很多次，直到无法忍受为止。"
D.Strings[95779]="如果没有实验对象的话，我就做不了任何测试。"
D.Strings[95780]="欢迎你的到来。"
D.Strings[95781]="下次再聊。"
D.Strings[95782]="你好，真理的追寻者。"
D.Strings[95783]="你没我想象的那么高大。"
D.Strings[95784]="很好的开始！你打得不错！"
D.Strings[95785]="一千年来，我从未见过如此高贵的挑战者！"
D.Strings[95786]="Mrlgrrl，rglrlg rlgrlmgmlr？\n\n<菲恩期待地看着你。>"
D.Strings[95787]="好了！这个小戏法能帮你追上加弗德。祝你好运！"
D.Strings[95788]="为了提尔。"
D.Strings[95789]="愿提尔指引着你。"
D.Strings[95790]="蓝色最美了！"
D.Strings[95791]="什么风把你吹来了？"
D.Strings[95792]="那好吧。"
D.Strings[95793]="我要回去干活儿了。"
D.Strings[95794]="也是牢笼。"
D.Strings[95795]="艾利桑德和燃烧军团想用恐惧和饥饿让我们臣服。"
D.Strings[95796]="他、他们更需要它……我没、没事……"
D.Strings[95797]="好、好……饿……意识都……模糊了！"
D.Strings[95798]="<他面无表情地盯着你。>你不是我的兄弟。"
D.Strings[95799]="那点酒根本不够我们两个喝的……所以我选择自己忍着，让她少受点苦。"
D.Strings[95800]="我还需要一个诱饵。"
D.Strings[95801]="好好使用这个诱饵。我手头也没有多少内脏了。"
D.Strings[95802]="地狱犬是一种迅捷坚韧的野兽，总是成群结队地出现。每一头地狱犬都有两条触须，末端有类似吸盘的东西。如果你被它们抓住，它们会吸取你的力量，并最终吸干你的生命力。一定要在它们打中你之前击倒它们。"
D.Strings[95803]="我们最近才发现了这类变种地狱犬，我们称它们为“魔犬”。它们的速度比它们的近亲更快，而且更擅长协同作战。它们总是成群结队地追杀敌人，具有原始的种群沟通手段。不要被咬到，因为它们的牙上带有各种邪恶的魔法。"
D.Strings[95804]="低劣的小鬼，一种使用地狱火的狡诈生物。个体的威胁不大，但一大群小鬼就能从远处迅速瓦解你们的防御。"
D.Strings[95805]="愤怒卫士，燃烧军团前线上的精锐战士。他们通常会使用两把同样的武器，不要让他们在剑术比拼中占据先手，否则你就会面临狂风暴雨般的打击并最终败亡。"
D.Strings[95806]="只有一只眼睛？别冲我抱怨，这都怪你没深度。"
D.Strings[95807]="能抽空帮我召唤个身体吗？"
D.Strings[95808]="多么单调的地方！如果放把火，会好很多。"
D.Strings[95809]="这些维库人应该歌颂萨格拉斯，而不是唱着空洞的泰坦赞歌。"
D.Strings[95810]="我很高兴见到你。"
D.Strings[95811]="狩猎愉快。"
D.Strings[95812]="愿日月照亮你的道路。"
D.Strings[95813]="我等不及要去魅惑那些魁梧的维库人了！"
D.Strings[95814]="别害怕，英雄。"
D.Strings[95815]="我的谢意与你同在。"
D.Strings[95816]="一片有待摧毁的新土地！"
D.Strings[95817]="我感觉附近有片黑暗之地被虚空感染了。"
D.Strings[95818]="邪能卫士是燃烧军团的前线部队，通常都会手持一把沉重的双手武器。他们的攻击速度很慢，但攻击力很强，而且远比他们看上去要敏捷。"
D.Strings[95819]="我不会再躲在暗影里了。"
D.Strings[95820]="我们将携手创造奇迹。"
D.Strings[95821]="愿光与影指引着你。"
D.Strings[95822]="我在想，如果我们把人分裂成纯粹的圣光和虚空会怎么样。想来做我的小白鼠吗？"
D.Strings[95823]="真是一头大家伙！这次的收获绝对值得我们吹嘘一阵了！"
D.Strings[95824]="你很无聊？那我可以安排你跟暗影魔聊聊。"
D.Strings[95825]="你知道我们正面临一场入侵吧？"
D.Strings[95826]="你知道吗，它头上那个诱鱼的器官可以做出一根出色的钓竿……"
D.Strings[95827]="对，我知道它看起来有点粗糙，可你看！鱼儿会成群结队地冲向这种东西的。"
D.Strings[95828]="给，拿着。把它交给达拉然的玛西娅。她最擅长加工鱼竿了。"
D.Strings[95829]="如果你没有其他办法的话，可以坐我的船回去。"
D.Strings[95830]="放下你们的武器！我们不是来跟你们战斗的。"
D.Strings[95831]="愿圣光照耀你。"
D.Strings[95832]="国王没有遇险，但我的人没能阻止这个邪教徒，而你们成功了。这至少让你们逃脱了牢狱之灾。"
D.Strings[95833]="走吧。在我改变主意之前，离开我的城市。"
D.Strings[95834]="有空再聊。"
D.Strings[95835]="我随时可以帮忙。"
D.Strings[95836]="我有时会想念洛丹伦美丽的庭院，还有我的父亲。"
D.Strings[95837]="这个地方我也不喜欢。"
D.Strings[95838]="我曾经为了躲避流着口水的食尸鬼在一条泥泞的水沟里躲了两天。你的胡闹对我来说不算什么。"
D.Strings[95839]="如果是泰瑞纳斯，他会像扔麦迪文那样把你扔出去。"
D.Strings[95840]="我从来没见过这样的鳞片。"
D.Strings[95841]="这头恶魔显然是被刻意培养成了同时抵抗魔法和物理攻击的形态。"
D.Strings[95842]="这片土地真是……清新，感觉不到任何恶魔的腐蚀。这……太讨厌了。"
D.Strings[95843]="下一个幻象，谢谢。"
D.Strings[95844]="让他们看看下一种恶魔。"
D.Strings[95845]="下一种恶魔。"
D.Strings[95846]="起来……"
D.Strings[95847]="喝吧，亲爱的。这会让你感觉好些。"
D.Strings[95848]="给我一点时间来研究一下这头野兽，我就能发现它的弱点。"
D.Strings[95849]="可你需要……"
D.Strings[95850]="我们可以熬过今天了。凡瑟尔总是照顾着我们。你知道的。"
D.Strings[95851]="露妮特点点头，喝了一口。"
D.Strings[95852]="这下好多了。谢谢你。太感谢你了。"
D.Strings[95853]="那些山峰仿佛能直插云霄。要是能看到它们塌下来该多好！"
D.Strings[95854]="这里有好多野兽在等着我们去猎杀啊！"
D.Strings[95855]="我们能离开这个地方吗？我……我有点恐高……"
D.Strings[95856]="在这么高的地方，我能看见一切！"
D.Strings[95857]="我感觉到这片土地上有个强大的存在，虽然它比不上萨格拉斯大人。"
D.Strings[95858]="没错，老朋友。我们会搞清楚的……"
D.Strings[95859]="赞美暗夜井……我还以为自己要死了呢。"
D.Strings[95860]="我会送她回家的。很高兴凡瑟尔还想着我们。"
D.Strings[95861]="这里肯定还有关于魔法疾病的书籍……"
D.Strings[95862]="我家很近。谢谢你。"
D.Strings[95863]="《有关渡鸦习性的论文》，好像很有趣！可它不能帮可怜的梅瑞尔康复……"
D.Strings[95864]="安博瑞娜颤巍巍地喝了一口。"
D.Strings[95865]="该死！这图书馆简直就是个灾难！要想尽快找到有关魔法感染的文献的话，就得先把它打扫一下……"
D.Strings[95866]="我知道这里肯定有东西能帮上梅瑞尔……可在哪儿呢……"
D.Strings[95867]="什、什么？"
D.Strings[95868]="这是魔力酒。给你的。喝吧，兄弟。"
D.Strings[95869]="克洛泰尔试探性地抿了一口酒，然后就牛饮了起来。"
D.Strings[95870]="哈。别喝这么快！你会呛到的。"
D.Strings[95871]="你闭嘴……帮我谢谢凡瑟尔，好吗？"
D.Strings[95872]="激活宝石。"
D.Strings[95873]="关闭宝石。"
D.Strings[95874]="|cFFFF00FF激活完美的宝石。|r"
D.Strings[95875]="唔！这里的牛头人好……高啊。"
D.Strings[95876]="他又弄到了？"
D.Strings[95877]="太好了！今天我们两个都不用挨饿了。"
D.Strings[95878]="这座山迟早会塌掉的！"
D.Strings[95879]="多纳提恩喝了一小口魔力酒。"
D.Strings[95880]="凡瑟尔又得手了……他是怎么做到的？"
D.Strings[95881]="在这个高度，我们都能碰到虚空了。"
D.Strings[95882]="这地方比上一个还要糟糕。"
D.Strings[95883]="咕噜先生打掉了珍珠，把它摔裂了！"
D.Strings[95884]="这里充斥着源自扭曲心灵的畸形生物。他们都要被烧死。"
D.Strings[95885]="在这座森林里，你会看到泰坦的计划也有瑕疵。"
D.Strings[95886]="猎珠人菲恩将珍珠递给咕噜先生。"
D.Strings[95887]="我们为什么要把时间浪费在林中漫步上？"
D.Strings[95888]="哈杜伦跟我说了你会来的。"
D.Strings[95889]="好……多……可以……烧！"
D.Strings[95890]="耶！尝尝这个怎么样？"
D.Strings[95891]="到处都是绿色！我可不太喜欢。"
D.Strings[95892]="你肯定完全没想到，对吧？"
D.Strings[95893]="为了拿到这些橡木和矿石，你遇到不少麻烦吧？"
D.Strings[95894]="哼，你还活着啊。"
D.Strings[95895]="这可是你自找的！"
D.Strings[95896]="这些材料很难处理，但我相信最终的成品一定会让你大吃一惊的。"
D.Strings[95897]="小崽子。看来我弹尽粮绝了……开玩笑的！我准备了几天份的炸弹呢。"
D.Strings[95898]="我要制造的武器很锋利，足以刺穿任何护甲。同时又很坚固，能够反复使用。"
D.Strings[95899]="我得说，这恐怕是我迄今为止最好的作品了。"
D.Strings[95900]="别让这把武器落入恶人的手里。"
D.Strings[95901]="锚点就在那边城墙顶上。跟我来！"
D.Strings[95902]="火炮和炮弹送来了，直接从大熔炉运来的。"
D.Strings[95903]="太好了，第三舰队的船只就在码头的最里面装运呢。"
D.Strings[95904]="能弄到足够的酒吗？"
D.Strings[95905]="起码够最需要的人喝了。其他人——啊！欢迎。"
D.Strings[95906]="你来得正是时候。欢迎来到我的酒馆。"
D.Strings[95907]="据说他的同类都无法腐化。我想这对我的兄弟们是个教训。"
D.Strings[95908]="洛肯成功地挑唆了她，但事实上，奥丁的傲慢才是主因。"
D.Strings[95909]="他不是我们的仆人，但他听到了我们的低语。这彻底腐蚀了他。"
D.Strings[95910]="远行者会与你并肩战斗，让驯犬者屈服的。"
D.Strings[95911]="一头岩石野兽，胡乱挥霍着他难以控制的力量。应该在他破坏我们的计划之前干掉他。"
D.Strings[95912]="如果我们要给驯犬者设下陷阱，那就得把它放在稳妥的地方。"
D.Strings[95913]="哨兵们能够提供支援。让我们一起打倒驯犬者吧。"
D.Strings[95914]="|TInterface\\Icons\\spell_nature_protectionformnature:20|t%s开始施放|cFF00FFFF|Hspell:212681|h[净化大地]|h|r！"
D.Strings[95915]="又是萨格拉斯的匿名暴徒，假装来帮助这些精灵。他们还蒙在鼓里。"
D.Strings[95916]="那个家伙背叛了他的世界和同胞。他迟早要死……只看是谁杀了他而已。"
D.Strings[95917]="噢，她会去哪儿呢……"
D.Strings[95918]="放松，朋友。我们会找到她的。"
D.Strings[95919]="恩佐斯的这个白痴脓疱活得太久了……它也没法扭转我对这世界新主人的看法。"
D.Strings[95920]="法力风暴家族怎么堕落成这样了！破机器和小戏法对他们毫无帮助。但他们还算有用。"
D.Strings[95921]="她的母亲更令人印象深刻。这小丫头控制不住自己的饥渴，而且过分依赖战术，很容易对付。"
D.Strings[95922]="真的，萨格拉斯的这些暴徒太没个性了。这家伙很擅长用斧子啊。噢，真特别！"
D.Strings[95923]="那个密探穿着颜色上衣！"
D.Strings[95924]="又一个蠢货，居然相信了伊利丹关于牺牲和正义的谎言。他给所有人带来了痛苦。"
D.Strings[95925]="那个密探穿着深色上衣！"
D.Strings[95926]="那个密探是男的！"
D.Strings[95927]="那个密探是女的！"
D.Strings[95928]="那个密探戴着手套！"
D.Strings[95929]="那个密探没戴手套！"
D.Strings[95930]="那个密探带着药水！"
D.Strings[95931]="那个密探带着几本书！"
D.Strings[95932]="那个密探的腰带上挂着一个袋子！"
D.Strings[95933]="那个密探没带任何药水！"
D.Strings[95934]="那个密探穿着长袖！"
D.Strings[95935]="那个密探没穿长袖！"
D.Strings[95936]="那个密探穿着斗篷！"
D.Strings[95937]="那个密探没穿斗篷！"
D.Strings[95938]="这家伙很古老，但还不是最早的那批。这些生物过于渴望魔法，所以不愿臣服，但他们偶尔还是很有用的。"
D.Strings[95939]="这里满是梦想，可他们都没梦到我？真太伤本姑娘的自尊了。"
D.Strings[95940]="你觉得她是从何时开始蜕变的？几百年前？她以牺牲和正义之名掩盖了对力量的渴望。"
D.Strings[95941]="你是想说梦魇吧？"
D.Strings[95942]="这三个家伙已经享受恩佐斯的秘密眷顾太久了。可惜他们横行霸道的日子结束了。"
D.Strings[95943]="强大的巨龙能成为强大的工具。唉，迦拉克隆的时代结束了。"
D.Strings[95944]="到处都是树！烧起来肯定璀璨夺目！"
D.Strings[95945]="我毁灭世界时，必将最先吞噬这片土地。"
D.Strings[95946]="|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|t%s施放了|cFFFF0000|Hspell:214505|h[纠缠梦魇]|h|r！"
D.Strings[95947]="到处都是邪教徒。这太疯狂了！"
D.Strings[95948]="我们需要答案！"
D.Strings[95949]="铁炉堡的援军正在赶来。我们是不会让暴风城毁灭的！"
D.Strings[95950]="有点本事，但比不过你那个死掉的主子。"
D.Strings[95951]="告诉我，恶魔猎手，多年的监禁感觉如何？"
D.Strings[95952]="这不可能。"
D.Strings[95953]="我的儿子，加林呢？"
D.Strings[95954]="那个谋杀君父的王子在哪里？"
D.Strings[95955]="激流堡怎么样了？"
D.Strings[95956]="看来我是个失败的父亲和国王。"
D.Strings[95957]="未来的世界钢铁短缺吗？"
D.Strings[95958]="那就让它生锈吧，我不在乎。"
D.Strings[95959]="我们取了他的性命，陛下。王子让我们别无选择。"
D.Strings[95960]="……一切。"
D.Strings[95961]="死亡与毁灭。时光并没有眷顾这个地方。"
D.Strings[95962]="我憎恨这地方！别再让它折磨我了！"
D.Strings[95963]="我得回加基森去了！他们肯定不会相信的！"
D.Strings[95964]="谢了！我欠你一次人情。"
D.Strings[95965]="我可没想到会在这里见到你！现在，如果你不介意的话……"
D.Strings[95966]="哇哦，就差一点。"
D.Strings[95967]="我不能再无偿提供服务了。"
D.Strings[95968]="我们是黑锋骑士团，守护这个世界的不死骑士。"
D.Strings[95969]="我们做了生者做不到的事。"
D.Strings[95970]="谢谢。我最好去把这里发生的一切告诉他们。"
D.Strings[95971]="真没想到我会被困在这里。感谢你的帮助。"
D.Strings[95972]="激流堡完了，可这个世界还有希望……如果你愿意加入我们的话。"
D.Strings[95973]="梦魇在这片土地上肆虐。有一股力量试图控制它，但不了解梦魇本质就这么做是在犯蠢。"
D.Strings[95974]="太好了！另外，我们找回了你的剑，托卡拉尔。它是个奇迹。"
D.Strings[95975]="你是谁，为何唤醒死去的君王？说。"
D.Strings[95976]="这里早就被毁了。你干嘛要浪费我的时间呢，凡人？"
D.Strings[95977]="我会尽我所能维护艾泽拉斯的和平。"
D.Strings[95978]="嘿，我们要去海滩了！契约上包含休假的吧？"
D.Strings[95979]="巨龙服从萨维斯，而萨维斯是深渊之神的仆从。她不再喷出生命的精华，而是吞噬周围的一切。"
D.Strings[95980]="看来恩佐斯的牢笼不如过去坚固了。你看到的只是一头足以吞噬世界的巨兽的渺小衍生物罢了。"
D.Strings[95981]="又一颗根植于死亡的腐蚀之种。暴躁的幽灵将在愤怒中徘徊，在痛苦中成长。一个深渊之神的猎物。"
D.Strings[95982]="泰坦的守卫者又少了一个。每一次死亡都让它雪上加霜。他的痛苦或许结束了……但我表示怀疑。"
D.Strings[95983]="这里的废墟充斥着幽灵。这些灵魂在等待收割！"
D.Strings[95984]="腐蚀翡翠梦境的守护者是一个大胆的举动，但萨维斯可能有些冒进了。他应该默默地扩散梦魇的影响力，而不是打草惊蛇。"
D.Strings[95985]="这片土地的灾难还没结束。等我们彻底毁灭它之后，就献给伟大的萨格拉斯。"
D.Strings[95986]="萨维斯充分发挥了新主子的力量。蒙蔽半神的头脑可不简单。"
D.Strings[95987]="这片土地不过是自身的一个影子罢了。我们将碾碎它，让它的居民在末日中哀嚎！"
D.Strings[95988]="黑暗而不祥的深海。它和无尽的虚空真是相似。"
D.Strings[95989]="我不喜欢这个地方。放我出去！"
D.Strings[95990]="萨维斯总是不断改换门庭以攫取力量，却一次又一次被击败。深渊之神选错了勇士，他还有别的底牌吗？"
D.Strings[95991]="几乎彻底消失了，就像从未出现过。但这条裂隙很深很大，下面的某个地方仍在翻腾。有些东西变了，最后的禁锢松动了。我们得做好准备。"
D.Strings[95992]="有意思……这种对残余能量的利用方式真有创意！我们得研究这种技术！"
D.Strings[95993]="她彻底被邪能侵蚀了。可惜我们没时间去研究能不能把她像恶魔一样束缚起来。"
D.Strings[95994]="这里的位面屏障很薄弱，很容易撕裂。你知道真正的暗影和圣光在这里相遇，会发生什么事吗？"
D.Strings[95995]="小心！他的顾问不简单。保持警惕！"
D.Strings[95996]="这里对虚空的研究值得赞赏，但这是徒劳的。你们怎么可能明白连泰坦都理解不了的东西呢？"
D.Strings[95997]="我知道纳鲁认为我们是要抵制的恐怖怪物。但我们不这么认为。他们只是迷途的同胞而已。总有一天……他们将回到主人身边。"
D.Strings[95998]="很好很好，这不是我那个败家子学徒塔丽克萨吗。在守备官把我铐起来，屠杀我的其他学徒时，她失踪了。我要看着她死！"
D.Strings[95999]="你召集了不少追随者。幸好他们都在关注这次入侵，而不是真正的战争。这场战争的规模足够让你想破脑袋。"
D.Strings[96000]="纳鲁提过永恒战争吗？相比漫长的岁月，你们这世界的历史不过是沧海一粟。它们说过德莱尼诞生前的历史吗？没有？<短促的轻笑声>"
D.Strings[96001]="如此美味。"
D.Strings[96002]="聚沙成塔。"
D.Strings[96003]="感觉如何？"
D.Strings[96004]="真无聊。"
D.Strings[96005]="好好看着，哥哥。"
D.Strings[96006]="你感觉到它的消逝了吗？"
D.Strings[96007]="你还记得艾萨拉女王与恶魔合作的事吗？很显然，法罗迪斯王子发现了真相之后，他说……"
D.Strings[96008]="“不！”"
D.Strings[96009]="……然后艾萨拉女王就说……"
D.Strings[96010]="“你竟敢违抗我！？”"
D.Strings[96011]="……然后，她就气疯了，把大家都变成了……变成了……"
D.Strings[96012]="被诅咒的幽灵！"
D.Strings[96013]="噢，抱歉。"
D.Strings[96014]="希望我们的主人能真正进入这个国度。你看到的只是一些碎片、阴影、最微弱的回响。你可以去问问虚灵，这些存在有多大的威能。"
D.Strings[96015]="有情报指出，船难浅滩里住着一只巨型螃蟹。它的钳子可能比钢铁还要坚硬！我们可以把它们做成强大的武器。"
D.Strings[96016]="等等，这就是普通蟹钳嘛，只是比较大。真可惜。"
D.Strings[96017]="靠近虚空的感觉很舒服。我曾在一个类似的地方献祭了大量生物。每一次死亡都能让我们离彻底腐蚀这世界更近一步。"
D.Strings[96018]="这个萨维斯很狡猾。他把真身藏起来，用幻像来收集力量。我们应该向他学习。"
D.Strings[96019]="我还记得那个天真的黑铁矮人。莫德古德很容易受影响，她太愤怒了。你知道我在最危急的关头背弃她，倒向蛮锤部族时，她有多么愤怒吗？我是很容易遗失的……记住这一点。"
D.Strings[96020]="这次，我们可能会面对我的同胞……真让人开心。他们的力量将属于我！他们将为过去对我所做的一切付出代价。"
D.Strings[96021]="愚蠢的凡人。没人能救得了你们！"
D.Strings[96022]="臣服于燃烧军团的威能吧！"
D.Strings[96023]="被囚禁的深渊之神愤怒地翻腾着，慢慢侵蚀着身上的枷锁。你得快点打败那个堕落泰坦……还有更可怕的战斗在等着你呢。"
D.Strings[96024]="没人能保护你们。"
D.Strings[96025]="我们……无处……不在！"
D.Strings[96026]="哈哈哈，蠢货！你们太无知了！"
D.Strings[96027]="你们已经死到临头了，凡人！"
D.Strings[96028]="谢谢你，冒险者。"
D.Strings[96029]="我还活着？谢谢你！"
D.Strings[96030]="求求你，一定要阻止萨维斯之影。"
D.Strings[96031]="那怪物看似吓人，但赋予它形体的法术只能勉强把它捏合起来。只要打断支撑它的仪式，它就会自己垮掉。"
D.Strings[96032]="一个古老物种的有趣变体。它的甲壳几乎牢不可破。“几乎”……"
D.Strings[96033]="一个邪能种族的有趣杂交品。我在想，这种东西还有多少？"
D.Strings[96034]="哪怕是长寿的精灵，她也太傲慢了。她的生命之力……非常美味。"
D.Strings[96035]="这个家伙只窥探到了可怕真相的冰山一角，就被彻底蒙蔽了。"
D.Strings[96036]="她宣称能预知未来，可那些比她活得更久的人才知道真相。她为了保住权位，毁了她的人民。"
D.Strings[96037]="这家伙早就该死了。他是堕落泰坦真正的仆从，想要毁灭一切。好像这真能让他们免遭虚空吞噬似的。"
D.Strings[96038]="<短促的笑声>"
D.Strings[96039]="<邪恶的笑声>"
D.Strings[96040]="一具腐化的巨龙尸体……这能有多危险呢？"
D.Strings[96041]="又是萨维斯扭曲的走狗。德鲁伊真该好好控制自己的心智，你不觉得吗？"
D.Strings[96042]="据说，有人看见一只叫甲喉的巨兽正在呢喃之柳大肆破坏！"
D.Strings[96043]="如果能把瓦拉加尔放出去，就会对燃烧军团造成很大的困扰。可被关在这儿，他们就没用了。"
D.Strings[96044]="干得好。在赶走纳迦之后，那里至少还能留下点什么。"
D.Strings[96045]="真讽刺，最弱的那个居然成了最后的胜利者。克苏恩，尤格-萨隆，亚煞极，还有……好吧。只有一个人能吞噬这世界，这是注定的。"
D.Strings[96046]="嘿，哥哥！这里有人……"
D.Strings[96047]="哦，抱歉。"
D.Strings[96048]="对萨格拉斯而言，招募艾瑞达绝对是神来之笔。他的军团急需提高智商。"
D.Strings[96049]="我们是来谈判的，阿卡玛。"
D.Strings[96050]="呃，这勾起了我不愉快的回忆。"
D.Strings[96051]="他们来帮我们找爸爸妈妈啦。"
D.Strings[96052]="阿卡玛，理智点。"
D.Strings[96053]="封锁要塞，守住大门！我们得把国王转移到安全的地方去。"
D.Strings[96054]="威严的米萨纳已经被梦魇亵渎了。去找到她，解除她的痛苦吧。"
D.Strings[96055]="你干得很好。织梦者欠你一份人情。"
D.Strings[96056]="你听到远处传来一声微弱的啼鸣声，然后又沉寂了下去……"
D.Strings[96057]="听到了吗？这艘船的每块木板、每根钉子都是灵魂的尖叫声。这真是……天籁之音！"
D.Strings[96058]="圣光之下，无所遁形！"
D.Strings[96059]="看看你面前这个怪物吧。它可不是燃烧军团创造的。不，这家伙是泰坦的愚蠢造物。"
D.Strings[96060]="男爵发现了什么东西。"
D.Strings[96061]="我都不知道自己能不能活下来。谢谢你。"
D.Strings[96062]="我可以回家了！"
D.Strings[96063]="我是无辜的，可他们就是不信……"
D.Strings[96064]="这绝对是我最后一次抱怨恶魔了！"
D.Strings[96065]="我得去看看我妻子了。谢谢你！"
D.Strings[96066]="我得去看看我丈夫了。谢谢你！"
D.Strings[96067]="我这儿有最好的护甲抛光服务，专门面向部队，$n。在启航之前，别忘了先处理好你护甲上的那些损伤。"
D.Strings[96068]="看看这个生物。多么粗糙的技艺！它永远都别想掌握术士的束缚魔法。"
D.Strings[96069]="什么？卡利斯蒂雅和欧洛希尔在这儿？"
D.Strings[96070]="我…… 我以为我们永远失去他们了。"
D.Strings[96071]="快，泰恩！我们去找他们！"
D.Strings[96072]="这家伙让我想起了邪能卫士。魁梧、强壮，而且愚蠢。"
D.Strings[96073]="唔，这看起来还不错。"
D.Strings[96074]="……我也有同感。"
D.Strings[96075]="男爵摇着尾巴跑回了营地。"
D.Strings[96076]="我在跟踪某个人……大门被突破了！"
D.Strings[96077]="呃，别让那玩意儿靠近我！我可不想再被吸干魔力。"
D.Strings[96078]="我抓住他们了！"
D.Strings[96079]="妈妈，爸爸很快就会回家了吗？"
D.Strings[96080]="是的，宝贝，他很快就会回来的。"
D.Strings[96081]="我会保护你的，艾拉！我有手有脚，还有剑！"
D.Strings[96082]="山姆！你要把那根棍子拿到哪儿去？把它放下，脏死了。"
D.Strings[96083]="你的船就在码头的尽头待命，$n。一路小心。"
D.Strings[96084]="援军立刻去要塞。他们就在这儿！"
D.Strings[96085]="无论你打算怎么做，我们都会支持你的，$n。但我建议，如果有可能的话，我们最好还是保持克制。\n\n他所掌握的知识能帮助我们打败燃烧军团。虽然阿卡玛和伊利达雷早有宿怨，但我们希望他能成为一个可靠的顾问。\n\n希望他能理智一点。但他的口气似乎不太好。"
D.Strings[96086]="无论你想怎么做，我们都会支持你的，$n。但我得提醒你，他背叛过主人，直接导致了我们被囚禁以及伊利丹的死亡。\n\n要不是阿卡玛的话，燃烧军团可能已经被击败了。虽然我们希望他能充当我们的顾问，但他过去的行为说明他并不可靠。\n\n你不要误会，主人说我们应该招揽阿卡玛，所以我也同意这个计划。不过，他听起来并不怎么理智。\n\n我和阿莱利准备了一个备用计划，以防万一。"
D.Strings[96087]="我为你武器附魔的力量会吸引很多恶魔。"
D.Strings[96088]="我使用的材料非常不稳定。任何干扰都可能造成严重后果。"
D.Strings[96089]="我继续我的工作，你去挡住恶魔，不要让他们靠近我和我的附魔桌台。"
D.Strings[96090]="我快要完工了。只需要再有几分钟没人打扰……"
D.Strings[96091]="给你，武器完成了。"
D.Strings[96092]="我把我最棒的附魔给了他们。"
D.Strings[96093]="一定会有办法的！"
D.Strings[96094]="大厅见，我们还有事情要做呢。"
D.Strings[96095]="自从胡恩的时代，我的家族就守护着这片墓地！我们自豪地照料着高贵的亡者，用我们的技巧指引他们的灵魂，并向他们学习。$b$b现在，全怪该死的鲜血图腾部族——如果他们还这么称呼自己的话——我必须向外来者求助了。$b$b这真是个黑暗的年代。"
D.Strings[96096]="我听到了什么声音。"
D.Strings[96097]="有一个就在附近！"
D.Strings[96098]="虽然我的剑在渴望恶魔的鲜血，但我得到的命令是严密监视它们。$b$b这些灵魂行者非常了解这个区域以及那些可能威胁到我们部队的灵体，这些情报对我们都是无价之宝。$b$b只要他们还有用，我们就会继续为他们提供庇护和补给。"
D.Strings[96099]="我闻到了邪教徒的气味！"
D.Strings[96100]="以国王的名义发誓，我一定会找到你的！"
D.Strings[96101]="附近有闯入者。"
D.Strings[96102]="出来，白痴！"
D.Strings[96103]="没错，附近有人。"
D.Strings[96104]="出来，恶棍！"
D.Strings[96105]="你休想轻易骗过我。"
D.Strings[96106]="放松点……我只是想聊聊。"
D.Strings[96107]="在我失去耐心之前，给我出来！"
D.Strings[96108]="我好像在这儿发现了什么。"
D.Strings[96109]="情况不对。"
D.Strings[96110]="在这场冲突中，我们将面对我以前的同胞。很好！我已经等了一万年。他们要付出代价！"
D.Strings[96111]="看着你埋头苦练，我又想起了过去。一万年前，我曾是个导师。我的学生是全阿古斯最出色的召唤师……可我们被出卖了。"
D.Strings[96112]="我不喜欢他们。"
D.Strings[96113]="哎哟哟！真疼！"
D.Strings[96114]="等会儿再来对付他们！"
D.Strings[96115]="我会变成这样，这个家伙也要负一部分责任！他休想逃脱我的怒火，可是我得先去解决那些罪魁祸首！"
D.Strings[96116]="我不要呆在这里！"
D.Strings[96117]="看到这么强大的生物匍匐在你脚下，是不是很满足？为了这种力量，我牺牲了一切。一切！总有一天，你也要为你的野心付出代价。"
D.Strings[96118]="这家伙与黑暗之王的联系很紧密。为了强化我们对燃烧军团的控制，我们应该抓紧机会消灭竞争对手。"
D.Strings[96119]="和大部分纳斯雷兹姆一样，提克迪奥斯既傲慢又危险。他早晚会死在自己手里！"
D.Strings[96120]="这家伙透过黑暗虚空，目睹了燃烧军团的辉煌。我在想，如果你也看到那一幕的话，会是什么反应！"
D.Strings[96121]="她试图掌控时间，但这是徒劳的。微妙的力量在抗拒着她，这股力量之强大远超她的想象。"
D.Strings[96122]="夏多雷之火即将熄灭。我们得重新点燃它。"
D.Strings[96123]="爸爸，我渴……我能喝点魔力果汁吗？"
D.Strings[96124]="很、很快就给你，小家伙。很快，我保证。"
D.Strings[96125]="这个痛苦的夜之子平民一边剧烈地颤抖，一边双目呆滞地盯着远方。"
D.Strings[96126]="深须海湾里生活着一只巨型海龟。把它的甲壳带来给我，让我们研究一下它神奇的防御力。"
D.Strings[96127]="我好几天都没看到一个搬运工了……我怎么可能会忽视这么庞大的群体呢？"
D.Strings[96128]="我想我们可能不仅仅是忽视了他们。"
D.Strings[96129]="小心让人听见！"
D.Strings[96130]="但我也没说错。"
D.Strings[96131]="卡德加的魔杖发出爆裂声。"
D.Strings[96132]="干得好。这玩意儿对我们的研究很有用。"
D.Strings[96133]="魔力酒到货了吗？拜托，告诉我你们还有……求你了……"
D.Strings[96134]="这些邪能图腾的家伙味道很不错，不过你要先把他们从脆壳里揪出来。"
D.Strings[96135]="墓穴就在前面。我们进去找祭坛吧！我们跟你走，$n。"
D.Strings[96136]="作为一个治疗者，要救这位平民并不困难。"
D.Strings[96137]="看看你的样子！一个昔日的幽灵，一个受到诅咒、死不了又无能的废物。"
D.Strings[96138]="我给你一个机会，跪下吧，小王子。你那个小诅咒或许还有救……"
D.Strings[96139]="不。我知道该怎么做。"
D.Strings[96140]="我们绝不会……"
D.Strings[96141]="向你……"
D.Strings[96142]="下跪！！！"
D.Strings[96143]="嘘，嘿，我这儿有些幸运符。你也不想在面对燃烧军团时走霉运吧？"
D.Strings[96144]="好臭！上面全是霉菌。大法师瓦格斯走得比我想的还早。"
D.Strings[96145]="凡人和他们的水晶球……但这一个可能不只是一个噱头。"
D.Strings[96146]="这可真有意思。我没想到大法师瓦格斯对天使鱼的繁殖习性这么感兴趣！"
D.Strings[96147]="太好了！这是一本有关古代夜之子仪式的法术书。有机会我一定要借来看看。"
D.Strings[96148]="我让这些恶魔猎手紧张了。我这个小老头。来自洛丹伦的特德。呵呵。$b$B记住，在被邪能灌注的古代精灵地盘上，擅长放逐术的农夫也能称王。"
D.Strings[96149]="我来帮地精女士打坏蛋啦！"
D.Strings[96150]="谢谢你，$n。但我的祖先可比我勇敢多了。"
D.Strings[96151]="旷野上需要再来点炸弹！"
D.Strings[96152]="我见识过不少大场面，可我真不知道该怎么形容眼前的情景了！"
D.Strings[96153]="这空间对凡人来说很舒适。看看这里面有什么秘密。"
D.Strings[96154]="猎珠人菲恩咆哮着，踢飞了脚边的一块石头。"
D.Strings[96155]="猎珠人菲恩不耐烦地跳来跳去。"
D.Strings[96156]="猎珠人菲恩挥舞着双臂，看起来很恼怒。"
D.Strings[96157]="猎珠人菲恩急忙跑过去，开始疯狂挖掘起来。"
D.Strings[96158]="猎珠人菲恩得意洋洋地从一堆沙子里拔出一大把长长的獠牙来。"
D.Strings[96159]="你来得太迟了。瓦格斯已经赢了！"
D.Strings[96160]="你需要什么样的知识呢？"
D.Strings[96161]="我会尽力帮忙的。"
D.Strings[96162]="记住提瑞斯法。"
D.Strings[96163]="小心纳斯雷兹姆。"
D.Strings[96164]="恐惧魔王必须死。"
D.Strings[96165]="提瑞斯秘法会决不能失败。"
D.Strings[96166]="某些恶魔最好不要被唤醒。"
D.Strings[96167]="你最好别把我惹火了。"
D.Strings[96168]="我要吞噬你的灵魂！噢，我的天，这家伙是从哪儿冒出来的？"
D.Strings[96169]="你完成了一项了不起的成就，把我们全部带到了这里。你调整了伊利达雷的运作方式后，我毫不怀疑我们能赢下这场战争。\n\n等战争结束后，燃烧军团就再也不能构成威胁，我们所有的牺牲也就值了。"
D.Strings[96170]="你完成了一件了不起的壮举，将我们全都带到了这里。我们重新坚定了决心，也有了周详的计划，我毫不怀疑我们一定能赢得这场战争。\n\n等到这一切全都结束，燃烧军团的威胁彻底消失后，我们的牺牲也就值得了。"
D.Strings[96171]="相信议会的智慧。"
D.Strings[96172]="守护者已经准备好了。"
D.Strings[96173]="如议会所愿。"
D.Strings[96174]="愿守护者保佑你。"
D.Strings[96175]="快站出来吧！"
D.Strings[96176]="你要上哪儿去？"
D.Strings[96177]="来选一张牌吧，随便选……"
D.Strings[96178]="时间就是法力，我的朋友！"
D.Strings[96179]="给点儿小费吧！"
D.Strings[96180]="那只兔子跑哪儿去啦？"
D.Strings[96181]="嘿，来帮我变个新戏法怎么样？我的锯子呢……"
D.Strings[96182]="再这样下去，你可能会失踪，小鬼。"
D.Strings[96183]="兔子！到处都是兔子！它们统治了世界！"
D.Strings[96184]="你以为你是自己的主人，这是你自己的意志……"
D.Strings[96185]="可是，那都是他的命令。"
D.Strings[96186]="你的存在也源自于他。"
D.Strings[96187]="你以为自己是自由的，可你的意志只是他的工具……"
D.Strings[96188]="黑暗不死不灭，$n。"
D.Strings[96189]="对梦魇倾泻怒火吧。挣扎吧。"
D.Strings[96190]="无尽的黑暗耐心十足。我们终将被它俘虏。"
D.Strings[96191]="你好，$n。我能为你做些什么吗？"
D.Strings[96192]="无数先王，都静静地躺在他们的墓穴中……"
D.Strings[96193]="赫赫权势也会被时间遗忘。"
D.Strings[96194]="所有君王都要向死亡屈膝。"
D.Strings[96195]="看看这些翻腾扭曲的灵魂……"
D.Strings[96196]="无数被时光遗忘的阴影。"
D.Strings[96197]="亡者的数量远超生者，向来如此。"
D.Strings[96198]="我没时间跟你闲聊。"
D.Strings[96199]="我们聊完了吗？"
D.Strings[96200]="邪能之火在召唤。"
D.Strings[96201]="玩邪火者必自焚。"
D.Strings[96202]="唔……但愿这些长袍是防火的……"
D.Strings[96203]="知道吗，我正需要一些芦荟呢。"
D.Strings[96204]="我的脸怎么了？在火里站的太久而已。"
D.Strings[96205]="你……真的在这里吗？一个$c……在我的巢穴里！这怎么可能？！$B$B你到底是怎么进来的？"
D.Strings[96206]="我怎么会在这儿的？你又在这儿干什么！？"
D.Strings[96207]="我在这儿干什么？你又在这儿干什么！？"
D.Strings[96208]="山谷已不复往日之美。\n\n恶魔决心侵占这片地方，但是我要奋战到底，不到最后一刻决不放弃。\n\n我没有忙着抵御入侵者时，就会花时间精研附魔，以此来对抗他们。\n\n总有一天，我们会夺回月爪谷。"
D.Strings[96209]="你准备好为我附魔武器了吗？"
D.Strings[96210]="别让我失望，瓦雷迪斯。"
D.Strings[96211]="回阿古斯。我们改天再来对付这个家伙。"
D.Strings[96212]="我的恶魔已经准备好了。"
D.Strings[96213]="如果有这个必要的话。"
D.Strings[96214]="虚空就是我的盟友。"
D.Strings[96215]="召唤恶魔须谨慎，朋友。"
D.Strings[96216]="你需要我的……天赋吗？"
D.Strings[96217]="我们接下来要去杀谁？"
D.Strings[96218]="我有点烦躁。来让我高兴一下。"
D.Strings[96219]="我们继续吧。"
D.Strings[96220]="这最好能有趣一点。"
D.Strings[96221]="让瘟疫降临到敌人头上！"
D.Strings[96222]="好的瘟疫总是值得传播的。"
D.Strings[96223]="我对痛苦的喜爱可不是浪得虚名。"
D.Strings[96224]="灰飞烟灭，我们都将……飘散！"
D.Strings[96225]="什么事，朋友？"
D.Strings[96226]="卡里杜斯随时为你效劳！"
D.Strings[96227]="朋友需要什么吗？"
D.Strings[96228]="再见，朋友！"
D.Strings[96229]="卡里杜斯愿意帮忙！"
D.Strings[96230]="卡里杜斯就在这里等着。"
D.Strings[96231]="指挥官。我随时可以为你训练部队。\n\n让燃烧军团去死吧！"
D.Strings[96232]="这些恶魔为我们提供了许多情报。燃烧军团的邪能秘术可以让我们更加强大。他们迟早会死在自己的秘密手上。\n\n那么，我能帮你什么忙呢，$n？"
D.Strings[96233]="奥鲁丹，我要飞往风暴峡湾。"
D.Strings[96234]="我们从埃索达带来了灌注了圣光的水晶。给我们一点时间，在跟燃烧军团开战前，先让我们为你们强化一下武器。"
D.Strings[96235]="坐吧，朋友，好好享受这顿美餐吧。你可不能饿着肚子上战场啊。"
D.Strings[96236]="部落的战士们，拿起你们的斧子，磨利你们的长矛。燃烧军团又回到我们的世界了。"
D.Strings[96237]="我们是阴影中的斗士。"
D.Strings[96238]="我是肖尔，马迪亚斯·肖尔。"
D.Strings[96239]="我就觉得你好像看了我一眼。"
D.Strings[96240]="时刻保持警惕。"
D.Strings[96241]="军情七处只是我的伪装——别说出去。"
D.Strings[96242]="我有的是让你闭嘴的办法。"
D.Strings[96243]="我有的是杀人的理由。"
D.Strings[96244]="喝了它——这会让我感觉好些。"
D.Strings[96245]="梦魇催生出了一个怪物：名叫暴怒的烂菌。去杀了它，把它烧成灰烬吧。"
D.Strings[96246]="我们会记住你的恩情的。Shorel'aran。"
D.Strings[96247]="林地里出现了一棵名叫库德兹拉的扭曲植物。快去砍掉它。"
D.Strings[96248]="干得好！腐蚀终于被净化了。Al diel shala。"
D.Strings[96249]="林地里还有幸存的德鲁伊。快去救他们吧。"
D.Strings[96250]="织梦者欠你的太多了。谢谢你。"
D.Strings[96251]="看到瓦尔莎拉威严的野兽被腐蚀，我很难过。我们必须……净化它们。"
D.Strings[96252]="你的任务完成了。对不起，我需要一点时间……"
D.Strings[96253]="我绝不容许这种事发生！散开，消灭他们！"
D.Strings[96254]="看来我们又有伴儿了！把上好的银器都藏起来！"
D.Strings[96255]="英雄们，干掉他们在加基森的首领！让他们看看，我们有一颗金子般的心……起码有72K那么纯！"
D.Strings[96256]="干得好！今天虽然没赚多少，但我们原本可能赔得更多！"
D.Strings[96257]="打倒他们，伙计们！那家伙的脑袋可以做成很好的纪念品……如果我们能找到那么大的墙的话。"
D.Strings[96258]="哎呀！发生什么了？"
D.Strings[96259]="……我在哪儿？"
D.Strings[96260]="我突然感到变冷，然后就晕过去了！这里出什么事了？"
D.Strings[96261]="这是赏你的血鹰。"
D.Strings[96262]="你会成为一个合格的祭品。哈哈哈！"
D.Strings[96263]="不要停！沙考尔先生要我们在日落前肢解这堆残骸！"
D.Strings[96264]="我认为你不是来找我的。也就是说，你可能是来这里做研究的。"
D.Strings[96265]="你是谁？没错，我是想重现艾里克斯的仪式。"
D.Strings[96266]="你应该可以抓住城墙顶上的那个点。跟我来！"
D.Strings[96267]="这个阴森的地方回荡着幽灵船的哀嚎！快去消灭恐怖船长塞顿，释放被禁锢在卡扎托亚号上的可怜灵魂吧！"
D.Strings[96268]="干得好！那艘幽灵船再也别想危害这片海域了。"
D.Strings[96269]="你怎么……你怎么敢讽刺我被禁锢的事？！代替洛肯接受惩罚吧！"
D.Strings[96270]="杀了你，我就能进入英灵殿了。"
D.Strings[96271]="谢谢你。我真不知该怎么感谢你才好。"
D.Strings[96272]="来吧……从深海中升起来吧！战利品在等着我们呢！"
D.Strings[96273]="伙计们！杀了这些蠢货，欢迎他们的灵魂……永远加入我们吧！"
D.Strings[96274]="卡扎托亚号将回归黑暗……但这只是暂时的！"
D.Strings[96275]="那好吧！我要亲手把你们禁锢在船上！"
D.Strings[96276]="你准备好前往魔环后，就告诉我一声，$n。我应该能帮你穿越它的结界。"
D.Strings[96277]="准备战斗吧，$n。这里可不欢迎我们俩……"
D.Strings[96278]="我们的兄弟已经被镣铐禁锢得太久了！"
D.Strings[96279]="如果没人援手的话，我们是不可能上去的，这是最后一次了！"
D.Strings[96280]="你准备好之后，我就打开直接通往紫罗兰监狱内部的传送门。"
D.Strings[96281]="他们甚至没有公开审判库尔迪拉·织亡者。我们的外交努力全都被当成了耳旁风。"
D.Strings[96282]="生成传送门。"
D.Strings[96283]="一定要让那些古代大法师安息……"
D.Strings[96284]="虽然部落和联盟是我们的盟友，但黑锋骑士团绝不会卑躬屈膝……"
D.Strings[96285]="你或许能帮助我们。有个古代大法师在这片废墟中徘徊。你必须让她安息。"
D.Strings[96286]="……希尔瓦娜斯不行……巫妖王本人也不行！"
D.Strings[96287]="这边走，快！"
D.Strings[96288]="我会跟你去帮忙的。"
D.Strings[96289]="跟紧点，这些幽灵已经被阿苏纳近来的动静给惊动了。"
D.Strings[96290]="我们就快到了。挡住其他幽灵。即使在死后，那些大法师仍然很强大。"
D.Strings[96291]="<这个法师的目光闪躲着。>$b$b我能为你做点什么吗，$c？我……我还……我还有事呢。"
D.Strings[96292]="我已经看穿你的真面目了，恶魔。撕下那张假面具，面对你的送葬者吧！"
D.Strings[96293]="你的伪装骗不过我的眼睛，恶魔。现出原形吧！"
D.Strings[96294]="我已经看穿你的真面目了，恶魔。游戏到此为止了。"
D.Strings[96295]="你的伪装简直可笑。别装了，我要把你撕成碎片送回虚空。"
D.Strings[96296]="这是你逼我的，$c。我是不会轻易退出这座城市的！"
D.Strings[96297]="我在前面的桥上等你。但首先，我得找到我的武器。"
D.Strings[96298]="我们要唤醒人民高贵的心灵。"
D.Strings[96299]="你……要让他们看到，艾泽拉斯没有抛弃他们。"
D.Strings[96300]="安息吧，幽灵！"
D.Strings[96301]="那个邪能领主洛查伯肯定就躲在那里。我可不想为了追杀一头恶魔到大门附近去。那样我们就得从几百头恶魔里杀出一条血路了。\n\n在关押他的过程中，我发现了一件事。这家伙很傲慢。所以，我准备当着所有人的面向他叫阵。\n\n<玛拉丝勉强忍住了很不适合守望者的咯咯笑声。>\n\n你准备好就告诉我一声吧，恶魔猎手。"
D.Strings[96302]="正在吸取"
D.Strings[96303]="看来燃烧军团占领了西边的流沙岗哨！快派些部队过去！"
D.Strings[96304]="东边的时光之穴也发现了恶魔！这里已经变成战场了！"
D.Strings[96305]="记住我的名字。"
D.Strings[96306]="看来有一群恶魔在南边的砂槌营地安营扎寨了！这些食人魔肯定会大吃一惊的！"
D.Strings[96307]="燃烧军团必胜！从无例外！"
D.Strings[96308]="巫妖王被击败后，我就在奥杜尔附近研究提尔的事迹。他是洛肯背叛后唯一与他战斗过的泰坦守护者。"
D.Strings[96309]="我发现了一段维库传说，说提尔为他的维库勇士铸造过一面强大的盾牌。"
D.Strings[96310]="我能跟亡者沟通。我们或许可以直接询问这个传说中提到的那位英雄。"
D.Strings[96311]="斯科瓦尔德，带我走吧。"
D.Strings[96312]="对，但愿如此。有你帮忙，我们或许能找到这件神器。"
D.Strings[96313]="现在，我要去英灵殿了……"
D.Strings[96314]="有一只大恶魔跑回了加基森的南门！我们会挡住他们，等待援军的！"
D.Strings[96315]="加基森！北门又遭到攻击了！他们完全就是凭空冒出来的……"
D.Strings[96316]="洛林，那真是太漂亮了！"
D.Strings[96317]="你准备好就叫阵吧。"
D.Strings[96318]="洛查伯！来啊，恶魔。如果你有种的话，就出来面对我们。"
D.Strings[96319]="我需要你帮忙完成一个极其重要的任务。"
D.Strings[96320]="你的意见将决定我们对军团的下一步行动。"
D.Strings[96321]="准备好就来找我。"
D.Strings[96322]="很好。准备好，就来克拉苏斯平台找我。"
D.Strings[96323]="咕噜先生对你做着手势。"
D.Strings[96324]="穆噜摇了摇头，看着猎珠人菲恩。"
D.Strings[96325]="猎珠人菲恩打破了茧。"
D.Strings[96326]="如果你知道将要面对什么的话……"
D.Strings[96327]="%s发出巨大的咯咯声，向你的方向移动了过来。"
D.Strings[96328]="一秒钟之前我还站着，接下来我就……好吧，你懂的。自己小心。这里的人都疯了！"
D.Strings[96329]="谢谢你！现在快跑吧！天知道他们什么时候又会回来。"
D.Strings[96330]="这里发生什么了？"
D.Strings[96331]="我大老远跑到这里可不是为了这个！"
D.Strings[96332]="这座岛上充斥着残余的魔力。去收集一些阿苏纳珍珠来，我们可以用它们聚焦魔法。"
D.Strings[96333]="很好。这些样品很适合用来聚焦魔法。"
D.Strings[96334]="如果你有需要，我可以把你送回山顶。"
D.Strings[96335]="送我去碎风小径顶端。"
D.Strings[96336]="送我去托林尼尔避难所外的托里姆峰。"
D.Strings[96337]="送我去托里姆峰顶。"
D.Strings[96338]="即使没有人来帮忙，我们也要完成这个使命。但愿我们剩余的兵力足够应对挑战。"
D.Strings[96339]="你……你践行着圣光之道。\n\n今天，是什么指引你来到此地？"
D.Strings[96340]="到克拉苏斯平台来吧。我们或许能帮助你的组织。"
D.Strings[96341]="如果能找到援兵，我和伊芙瑞娜也会过来。你留下，破晓。"
D.Strings[96342]="从天而降的菜鸟打倒了我最出色的打手。$b$b所以我们要和蠢蛋一起训练。有时国王也做不了主啊！"
D.Strings[96343]="安息吧，姐妹，你的痛苦结束了。"
D.Strings[96344]="我们欠你一份情。我会把你在这里的所作所为转告法罗迪斯王子的。"
D.Strings[96345]="魂魔塔格玛在吞噬强大的维库勇士灵魂！去杀了她，我会好好奖赏你的。"
D.Strings[96346]="我们的部队已经等不及要战斗了，$n。向他们展示一下你的技巧怎么样？"
D.Strings[96347]="对，就是它！盾牌岭！别再浪费时间了。"
D.Strings[96348]="亡魂将永远在海中浮沉，但她不能再伤害无辜者了。谢谢你，勇士。"
D.Strings[96349]="泰罗索斯，他是个好人。算我一个！这件事太危险了，不要拒绝这点小小的帮助！"
D.Strings[96350]="我们或许不用孤军奋战，塔胡！看看泰罗索斯怎么说吧。"
D.Strings[96351]="挡住他们！我们是不会拱手让出这个营地的！"
D.Strings[96352]="把他们赶出去！援军已经在路上了。"
D.Strings[96353]="坚守阵地。这场战争才刚刚开始。"
D.Strings[96354]="起来战斗！为了部落！"
D.Strings[96355]="来一个杀一个，来两个杀一双！"
D.Strings[96356]="弓箭手，瞄准目标！"
D.Strings[96357]="挑战者止步！别再惊扰这些先王了！"
D.Strings[96358]="别再打扰这些陵墓了！"
D.Strings[96359]="没有人能通过这个试炼！"
D.Strings[96360]="首先，你得尽快赶往克拉苏斯平台，是泰罗索斯派我来的。"
D.Strings[96361]="无意冒犯，但我没时间聊天。我还得去找我的盾牌呢！"
D.Strings[96362]="我们又见面了。"
D.Strings[96363]="你们的存在无足轻重，但我觉得可以让我的猎犬饱餐一顿。"
D.Strings[96364]="等把你撕碎之后，它们就能享用这些牢房里的魔法囚犯了。"
D.Strings[96365]="没错！那就是老艾瑞，公海的魔王！我们的机会来了，小子们，抓住他们！"
D.Strings[96366]="吃饱之后，我的猎犬就会冲进城市，杀光所有阻挡它们的人。"
D.Strings[96367]="达拉然将属于燃烧军团！"
D.Strings[96368]="我的猎犬！"
D.Strings[96369]="我会永远感谢你的，$n。"
D.Strings[96370]="圣光……好烫啊……你会付出代价的，$c！"
D.Strings[96371]="我要感谢你！我被困在这里已经不知道多久了。"
D.Strings[96372]="你要解释的东西还很多。为什么要背叛我们？"
D.Strings[96373]="背叛我们的事业绝不是我的本意，$n！\n\n我正在收集关于夜之子灵魂石笔记的时候，苍穹会的一个密使联系上了我。到达他们的据点时，我们的宿敌卡萨纳提尔正在那儿等着我。\n\n从那之后他就一直呆在我脑子里，我说的话做的事都是在他控制之下。"
D.Strings[96374]="是的，他打算对付的是梅瑞尔。他在使用夜之子灵魂石和魔枢的能量吸取梅瑞尔的力量。我们两个也许能阻止他。\n\n他还在这里，就在下面的某个地方。我们必须找到他！"
D.Strings[96375]="我明白了。是卡萨纳提尔计划攻击梅瑞尔的吗？"
D.Strings[96376]="是卡萨纳提尔计划攻击梅瑞尔的吗？"
D.Strings[96377]="我早猜到了！我就知道你们会来。"
D.Strings[96378]="我要吞掉你的鹦鹉，你这条傲慢的河豚！"
D.Strings[96379]="你根本不用挥剑，光凭脸就能吓死人了！呃！"
D.Strings[96380]="你战斗起来就像只软脚虾，你这个不老实的肮脏蠢货！"
D.Strings[96381]="我要打穿你的胃，你这个活该喂鱼的、卑鄙的……"
D.Strings[96382]="你身上一股烂鱼和臭猪味儿，你这只想吃天鹅肉的癞蛤蟆！"
D.Strings[96383]="我拿到想要的东西了。但我要留下来了结你们……永除后患！"
D.Strings[96384]="我拿到萨格里特钥石了。但我要留下来了结你们……永除后患。"
D.Strings[96385]="你就像乱穿衣服的猴子一样讨厌！"
D.Strings[96386]="你们掉进了我的陷阱。让我看看你们在黑暗中的本事吧。"
D.Strings[96387]="来次决斗怎么样？"
D.Strings[96388]="我得好好打一场。"
D.Strings[96389]="要让我看看你的本事吗？"
D.Strings[96390]="我很欣赏你的战斗技巧。来场小比试怎么样？"
D.Strings[96391]="想跟我一起训练吗？"
D.Strings[96392]="我们决斗吧。"
D.Strings[96393]="打得不错。"
D.Strings[96394]="打得好。"
D.Strings[96395]="感谢你参加决斗。"
D.Strings[96396]="你赢了。"
D.Strings[96397]="你来对付驯犬者，我们会集中攻击他的猎犬。"
D.Strings[96398]="下次我不会再对你客气了。"
D.Strings[96399]="精彩的决斗。"
D.Strings[96400]="这回是你赢了。"
D.Strings[96401]="我检测到这片区域里有个畸体在抽取网络中的能量！把它找出来，然后干掉它吧。"
D.Strings[96402]="啊，网络彻底清净了。我就知道你靠得住！"
D.Strings[96403]="你的船上的洞比海绵还要多，你这只大嘴巴的蟑螂！"
D.Strings[96404]="幸好有你在。你能把老鼠都吓跑！"
D.Strings[96405]="全世界的朗姆酒都没法让你变得漂亮一点，你这条该死的臭鱼！"
D.Strings[96406]="快用防护魔法！那个伤害太高了，我治疗不过来！"
D.Strings[96407]="我先去找个有利地形。你拿到爪钩后，就到城墙附近来找我。"
D.Strings[96408]="情报称，军团将一条名叫威利玛的恶魔看门狗带进了城市。这倒方便了！我可以用它的眼睛强化网络。"
D.Strings[96409]="就看你的了！"
D.Strings[96410]="别忘了灰烬使者，兄弟姐妹们。提里奥虽然去世了，可那把圣剑还在这附近。"
D.Strings[96411]="我们得去乌瑟尔之墓。"
D.Strings[96412]="给他们点颜色看看，$n。"
D.Strings[96413]="这是你的船，$n。愿圣光与你同在。"
D.Strings[96414]="猎珠人菲恩指了指魔痕凿孔蟹。"
D.Strings[96415]="对，对！交出你的力量，巨龙。这些池塘属于夜之子了！"
D.Strings[96416]="帮帮我，小家伙……"
D.Strings[96417]="看来大领主的失踪，影响的已经不止生者了。"
D.Strings[96418]="血色十字军突然重现，还提出了新主张，要消灭全世界的亡灵？我以前听过这种论调。你是个恐惧魔王吧？"
D.Strings[96419]="亡灵渣滓！你的存在对所有被天灾军团害得家破人亡的人而言都是一种侮辱。脱下那件战袍，爬回你的墓穴里去，否则我就送你下去！"
D.Strings[96420]="我想你除了相信我之外，也别无选择了，不是吗？"
D.Strings[96421]="就是你们这样的闯入者挫伤了血色十字军的军力！我们就该把这个世界上的亡灵全部消灭。那样的话，燃烧军团根本不可能如此猖狂！滚开！"
D.Strings[96422]="为了十字军！"
D.Strings[96423]="我们都知道你的组织已经一分钱也没有了，每一个铜板对你都是急需之物。所以别再虚张声势了，收下我的钱吧。"
D.Strings[96424]="我能看得出来，你是十字军的朋友。我设法从修道院里偷运了一批装备出来，想为我们的组织筹集资金。在将所有亡灵赶出艾泽拉斯之前，我们是不会罢休的！\n\n记住，是你和你的同谋害得我们濒临覆灭，所以我要的价钱可不便宜。"
D.Strings[96425]="疫喉正在冥狱深渊的海中肆虐，所过之处遍地狼藉。去消灭这个威胁！"
D.Strings[96426]="风暴峡湾的凡人永远欠你一份人情。来吧，接受你的奖励。"
D.Strings[96427]="啊，喜欢自吹自擂的暮色卫队。如果你能弄到他们的补给品，会对我们很有用。"
D.Strings[96428]="干得好，这就能拖慢他们的步伐了。"
D.Strings[96429]="副手的死亡应该已经让巴兰杜尔收到了明确的信号。快完成仪式，他快要攻击了！ "
D.Strings[96430]="我去准备仪式，你去帮助我们的盟友。"
D.Strings[96431]="这故事真不错。我们走吧。"
D.Strings[96432]="我们知道苏拉玛的封闭改变了它的居民——可那些植物呢？给我从群星庭院带些样本来，满足一下我的好奇心吧。"
D.Strings[96433]="有意思。这是精心培植过的。看来就连莽撞的夜之子都知道要保持生命力和魔力的平衡。"
D.Strings[96434]="艾露恩的光芒不再照耀这个洞穴中的枭兽。他们变成了可怕的野兽，威胁着所有人的安全。"
D.Strings[96435]="谢谢你，小$c。塞纳苟斯对你的信赖非常明智。"
D.Strings[96436]="我们到底做了什么，要遭受这种折磨？"
D.Strings[96437]="我倒下时，看到一个堕夜精灵偷偷摸摸进了我们的洞穴。"
D.Strings[96438]="我的灵魂长存。"
D.Strings[96439]="让我们谈谈吧。"
D.Strings[96440]="我过去的一个学生还住在城里。我曾以为她是可靠的。去让她明白叛徒的下场吧。"
D.Strings[96441]="干得好。我真希望能亲眼看到那一幕。"
D.Strings[96442]="沙索斯回到了巢穴。了结他吧，他已经向污染屈服，不能让他把污染散播出去。"
D.Strings[96443]="干得好！但愿沙索斯生命中的这一章被人遗忘。"
D.Strings[96444]="附近的狼越来越大胆了。该减少一下狼群的数量了。"
D.Strings[96445]="我们胜利了！干得好，勇士。"
D.Strings[96446]="几百年来，我们的组织一直秘密守护着一个圣地，提尔之墓。\n\n泰坦守护者提尔曾为艾泽拉斯的利益做出过许多英勇的壮举，最后却倒在狡猾而强大的上古之神手中。叛徒洛肯派出了两个强大的克拉西斯追杀提尔。他击败了他们，击杀了其中一人，并打跑了另一个。但他也为此付出了生命的代价。\n\n一些追随提尔的维库人被他的牺牲所感动，决定留下来为他守陵。后来，这些维库人逐渐被人类所取代了，也就是我们。多年来，我们一直防止着外人发现这个秘密……直到最近。"
D.Strings[96447]="逐雾猎犬是传说中的黑暗野兽！它在阴影中游荡，用幻象祸害这个世界——去消灭这个邪影。"
D.Strings[96448]="你的任务完成了。现在，你将得到奖赏。"
D.Strings[96449]="我们应该到第一层去。准备好了告诉我，我会把我们传送过去。"
D.Strings[96450]="你准备好传送到地面上了吗？"
D.Strings[96451]="卡萨纳提尔就在中枢建筑里。显然那里戒备森严！也许我们应该使用一个隐形法术，然后直接走进去。"
D.Strings[96452]="等我把这份认罪书交给合适的人，就去恐痕裂隙找你。"
D.Strings[96453]="我很乐意和你并肩对抗燃烧军团，算我一个。"
D.Strings[96454]="隐形术没法持续太久的。我们走吧！"
D.Strings[96455]="列阵！拿起武器！"
D.Strings[96456]="准备！敌人过来了！"
D.Strings[96457]="军团的战舰来了！守住阵地！所有人，准备战斗！"
D.Strings[96458]="拿起武器！准备战斗！燃烧军团从北边冲过来了！"
D.Strings[96459]="守住阵地！不要退缩！"
D.Strings[96460]="给他们点颜色看看！不要放松！"
D.Strings[96461]="把这些恶魔送回扭曲虚空！"
D.Strings[96462]="握紧你们的剑！干掉那个指挥官！"
D.Strings[96463]="传送门要关了！游侠们，干掉最后一批猎犬。"
D.Strings[96464]="行了……准备工作都完成了。你准备好了就激活仪式焦镜吧。"
D.Strings[96465]="小心点，他会咬人的。"
D.Strings[96466]="我想要一头飞往神射手营地的鹰。"
D.Strings[96467]="我们得小心点，这里充斥着枯法者。他们不但渴望魔力，还很嗜血。"
D.Strings[96468]="跟紧我！"
D.Strings[96469]="别犯傻，外来者。我的屏障会保护你的。"
D.Strings[96470]="可以跟乌瑟尔大人沟通了，$n。到墓穴来找我。"
D.Strings[96471]="这些恶魔竟敢玷污艾泽拉斯？去夺回我们的土地！"
D.Strings[96472]="不要让他们占领一寸土地！赶走他们！"
D.Strings[96473]="守护者雷姆洛斯似乎非常疲惫和茫然。他差点被枭兽干掉。"
D.Strings[96474]="救出被囚禁的雷姆洛斯。"
D.Strings[96475]="我们得立刻救出守护者雷姆洛斯！我知道有条近道，可以通向他被囚禁的洞窟。来吧，$n，跟我走！"
D.Strings[96476]="谢谢你！我们必须马上离开这里。"
D.Strings[96477]="希望我们还来得及救出守护者雷姆洛斯。"
D.Strings[96478]="我们成功了！卡萨纳提尔就在前面的房间里。"
D.Strings[96479]="我知道有些人会为了追求力量而无视他人的需求……"
D.Strings[96480]="这从来不是什么选择，奇拉。"
D.Strings[96481]="出击！把他们赶出我们的土地！"
D.Strings[96482]="血战到底……至死方休！战斗！"
D.Strings[96483]="去十字路口！集火那个头目！砍掉他的脑袋！"
D.Strings[96484]="它在攻击十字路口！去让它看看，入侵我们的世界要付出什么样的代价！"
D.Strings[96485]="英雄，用这个符文来强化你自己吧。"
D.Strings[96486]="去十字路口集合！解决那个最大的威胁！"
D.Strings[96487]="嗯哼。唔。嗯。我听着呢。"
D.Strings[96488]="噢，所以你是“那种”潜行者。"
D.Strings[96489]="打得好！让军团记住卡利姆多的刀剑有多么锋利！"
D.Strings[96490]="我们胜利了！但别放松……真正的战斗还没开始！"
D.Strings[96491]="乌瑟尔的墓穴就在前面。"
D.Strings[96492]="你的世界必将化为火海！"
D.Strings[96493]="没有人能阻挡燃烧军团！"
D.Strings[96494]="你的世界即将毁灭！"
D.Strings[96495]="末日在等着你们，凡人！"
D.Strings[96496]="今天就是你们的末日！"
D.Strings[96497]="你们休想逃出燃烧军团的掌心！"
D.Strings[96498]="卑微的凡人！你们将痛苦哀嚎！"
D.Strings[96499]="朋友不用独自面对燃烧军团。"
D.Strings[96500]="你好了就开始吧。"
D.Strings[96501]="碎片，过来，打倒我们的敌人！"
D.Strings[96502]="砂石，把他们碾成碎石。"
D.Strings[96503]="水开了！"
D.Strings[96504]="欢迎登船，$n。\n\n我们已经准备就绪了，等你准备好之后，我们就能启程了。"
D.Strings[96505]="我准备好面对燃烧军团了。"
D.Strings[96506]="你准备好前往破碎海滩面对燃烧军团了吗？"
D.Strings[96507]="苏和现出了原形！"
D.Strings[96508]="$n准备了肋排大餐！"
D.Strings[96509]="$n准备了一锅炖土豆！"
D.Strings[96510]="恢复警戒。"
D.Strings[96511]="损坏评估完成。开启防御模式。"
D.Strings[96512]="渺小的精灵！双头怪才是最强壮的！"
D.Strings[96513]="别人都看不见我，可我喜欢看着他们忙忙碌碌的样子。这真是太激动人心了。一直以来，这里都只有我和伊利丹的仆从。\n\n唉，可惜我已经被永远困在扭曲虚空了。我再也不能离开这里了，$n。\n\n但这都是值得的，如果重来一遍，我还会那么做的。我还是会牺牲自己，站在那里让你打倒我，来为最后一座传送门供能，并召唤出你的恶魔大军。这是为了我们的事业必要的牺牲。\n\n哪个恶魔猎手会拒绝呢？\n\n伊利达雷万岁！"
D.Strings[96514]="圣光，请听我们祈祷……暗影笼罩了我们。"
D.Strings[96515]="请允许此人显灵，让灰烬使者再次拯救世界。"
D.Strings[96516]="你知道它在哪儿吗，乌瑟尔？只要能回去，我们不惜一切。"
D.Strings[96517]="链接断开了。塞兰提娅的弱点暴露了！"
D.Strings[96518]="有你这个领袖，议会一定会越来越好的。"
D.Strings[96519]="回家去。"
D.Strings[96520]="这里属于禁区。你该离开这儿。快走。"
D.Strings[96521]="我们会按照魔导师的命令分发配给的。"
D.Strings[96522]="你无权进入酒庄。"
D.Strings[96523]="注意你的行为，否则后果自负，市民。"
D.Strings[96524]="酒庄只对贵宾开放。你必须立刻离开。"
D.Strings[96525]="求求你……我需要它！"
D.Strings[96526]="你怎么能看着我受苦？"
D.Strings[96527]="让我进去！求求你！"
D.Strings[96528]="我知道你给自己留了一点——只要给我一点儿就行！"
D.Strings[96529]="求求你，帮帮我……求你……"
D.Strings[96530]="我的女儿快要死了！求求你，你一定要帮我救救她！"
D.Strings[96531]="回家去，市民。"
D.Strings[96532]="快走吧。"
D.Strings[96533]="玛克斯韦尔，老朋友！好久不见。"
D.Strings[96534]="我很荣幸能说出下面这些话。梅拉·高岭，我在此宣布你为大酋长。大酋长万岁！"
D.Strings[96535]="你们都在践行圣光之道，但要找回灰烬使者，就得快点了。"
D.Strings[96536]="我感觉，它正在一座岛上召唤我们，就在某个恶徒的墓穴附近。但那里不止灰烬使者……"
D.Strings[96537]="提里奥还活着，但他的时间不多了。你们得快点，否则他会死的！我只能说到这里了。"
D.Strings[96538]="乌瑟尔，等等！我……我还有问题！乌瑟尔！"
D.Strings[96539]="祝你们好运。愿圣光眷顾你们。"
D.Strings[96540]="乌瑟尔，真的是你！"
D.Strings[96541]="你将成为我的新实验品的第一个测试者！"
D.Strings[96542]="你准备好返回监狱了吗？我们在这儿已经没什么用了。\n\n我们得回到我们的盟友身边，帮他们打败哈卡，以防他的野兽冲进城市里去。"
D.Strings[96543]="想试试魔法钓鱼吗？听上去很酷吧？"
D.Strings[96544]="只要提里奥还活着，我们就要救他……不惜一切。"
D.Strings[96545]="我们能合力打败卡萨纳提尔！等我们拖住他，你就用灵魂石！"
D.Strings[96546]="火焰响起来吧！快响起来！"
D.Strings[96547]="我要雪！快下雪！快下雪！快下雪！"
D.Strings[96548]="人类！吃我的冰霜之拳！"
D.Strings[96549]="这就是部落的力量！"
D.Strings[96550]="上古之神的仆人！让我们吞掉它！"
D.Strings[96551]="看！恩佐斯的密探！我们该杀了它。"
D.Strings[96552]="看见了吗？那个可怜的宿主已经没救了，只能杀掉。"
D.Strings[96553]="你！$C！你进过紫罗兰监狱吗？$b$b这些白痴守卫就是不让我进去。他们不知道我是谁吗？"
D.Strings[96554]="多管闲事的$c……你会为此付出代价的。这座城市必将化为火海！"
D.Strings[96555]="<塔莉萨抬手抚摸着自己憔悴的脸庞。>$B$B我的身体状况恶化得太快了……$B$B看来我们夜之子每一天都是在刀锋上跳舞啊。"
D.Strings[96556]="我会将苏拉玛从燃烧军团手中解放出来的，但我首先得恢复力量。$B$B而且我们需要一个计划……"
D.Strings[96557]="但愿我的战友们能比我过得好些。"
D.Strings[96558]="$n，我得跟你谈谈，情况紧急！"
D.Strings[96559]="这事关萨鲁法尔大王！我担心他的计划会毁了自己！"
D.Strings[96560]="不能再等了，我们得立刻谈谈！"
D.Strings[96561]="谢谢，勇士。我会去找萨尔，看他能否帮忙。"
D.Strings[96562]="跟我来。这是上城墙的路。"
D.Strings[96563]="啊，是伊崔格派你来的吧？他这是杞人忧天。"
D.Strings[96564]="最近的事压得我喘不过气来。我必须做点什么。"
D.Strings[96565]="你想要做什么？"
D.Strings[96566]="敢插手燃烧军团计划的人，就是这个下场……"
D.Strings[96567]="哈卡死后，达拉然的市民就安全了。多亏了你，大部分人根本不会知道他们曾面临过怎样的威胁。"
D.Strings[96568]="你打倒了那个邪能领主，没有让他霸占这座城市。你履行了我们时刻守护的誓言。"
D.Strings[96569]="别太天真了，这绝对不会是艾泽拉斯所面临的最后一个威胁。"
D.Strings[96570]="燃烧军团已经杀到我们家门口了，不能再对他们视而不见了。"
D.Strings[96571]="在这个时代，我们的誓言比以往更加重要。"
D.Strings[96572]="我认为那场战斗毫无荣耀可言。牺牲了那么多人，但我还活着。我每次看到那场风暴，内心的怒火就会不断滋长。\n\n为了我手下的战士们，我要回到破碎海滩。我要斩杀恶魔，为他们和我自己正名。不要试图劝说我，我有我的路要走。"
D.Strings[96573]="我们不是为荣耀、名誉或财富而战。"
D.Strings[96574]="我们的存在是为了保护那些需要保护的人，不计报酬和赞誉。"
D.Strings[96575]="那我跟你一起去。我们不能孤军奋战。"
D.Strings[96576]="那我跟你一起去。"
D.Strings[96577]="我们的道路注定孤独。"
D.Strings[96578]="我们可能会死在那片海滩上。你也很清楚这一点，但依然坚定。看来你也想找回属于你的荣耀。"
D.Strings[96579]="其他人应该在礼拜堂下面的秘殿里等着你呢，$n。"
D.Strings[96580]="其他人都在礼拜堂下面的秘殿里等着你呢，$n。"
D.Strings[96581]="%s咬着玛克斯韦尔的脚踝。"
D.Strings[96582]="%s咕哝了几声，尴尬地踢开了山羊。"
D.Strings[96583]="指挥官！我有给您的口信！"
D.Strings[96584]="我带来了达纳斯·托尔贝恩的重要口信！"
D.Strings[96585]="希望您别介意，这件事很紧急，需要立刻处理！"
D.Strings[96586]="太好了，指挥官。达纳斯在克拉苏斯平台等您。"
D.Strings[96587]="洛克莫拉生成了|cFFFF0000|Hspell:215898|h[晶化之地]|h|r！不要移动！"
D.Strings[96588]="<卡普里纳散发着动物毛皮和粪便的臭味。>$b$b你看什么呢，$c？你干嘛不去烦克劳福德或是希斯罗？"
D.Strings[96589]="你该死，混蛋$c！我的计划是完美无缺的！"
D.Strings[96590]="我的主人会听到的……燃烧军团将点燃这片海岸……"
D.Strings[96591]="祝你打爆那头恶魔的脑袋！"
D.Strings[96592]="看那边，看看那惨象。我们还要经历多少灾难才能迎来真正的和平？"
D.Strings[96593]="梦魇能吞噬一切，$c。它会从内部腐蚀你。它能轻松击溃你的意志，肆意在大地上横行。$b$b我们的心灵都将不可避免地被暗影笼罩，所有的希望都将熄灭。$b$b这太可怕了。这……太美妙了……"
D.Strings[96594]="我被发现了！放马过来吧——你们休想获胜。"
D.Strings[96595]="万物都将终结。梦境已死，永无宁日。"
D.Strings[96596]="渺小的凡人。你的放肆到此为止了。"
D.Strings[96597]="你和你的伊利达雷都将加入燃烧军团。你们都将成为魔誓者。"
D.Strings[96598]="你可以跪下了，恶魔猎手。"
D.Strings[96599]="很好。你这是自寻死路。瓦雷迪斯和凯丽娅会解决你的。"
D.Strings[96600]="熔火焦皮开始施放|cFFFF0000|Hspell:200672|h[水晶迸裂]|h|r！"
D.Strings[96601]="$n！基尔加丹下令逮捕你。你必须加入燃烧军团。"
D.Strings[96602]="你迟早会落到基尔加丹手上……"
D.Strings[96603]="真感人。又一群勇士。好像这样就会有用似的。"
D.Strings[96604]="真是一群乌合之众，$n。我还以为你们多有本事呢。"
D.Strings[96605]="现在，寒暄完毕。我们的主人，基尔加丹派我们来告诉你，你们伊利达雷很快就会加入燃烧军团……"
D.Strings[96606]="……并证明就算是躲在邪能之槌号里也并不安全。"
D.Strings[96607]="听着，伊利达雷！我们欢迎诸位加入燃烧军团。"
D.Strings[96608]="投诚者将得到强大的力量。而不识抬举的人，只能得到痛苦。"
D.Strings[96609]="我个人倒希望你拒绝。这样，那对战刃又可以物归原主了。"
D.Strings[96610]="啧啧，瓦雷迪斯。要公事公办啊。后会有期，$n。"
D.Strings[96611]="杀了我吧，你们这些蠢货，别让拉瑟莱克夺回控制权！"
D.Strings[96612]="现在，该打破这些束缚，享用你们的灵魂了。啊哈哈哈哈哈！"
D.Strings[96613]="不，恶魔！你休想得逞。"
D.Strings[96614]="我还要忍受多久？！"
D.Strings[96615]="无尽的痛苦和折磨在等待着你们。记住我的名字吧，伊利达雷，我是污染者拉瑟莱克！"
D.Strings[96616]="我是洛拉姆斯……不，我是拉瑟莱克！够了，恶魔，屈服吧。这是我的命令！"
D.Strings[96617]="没有人能阻止你们的世界化为火海！"
D.Strings[96618]="我会尽我所能控制住拉瑟莱克，并跟你分享他所有的恶魔知识。"
D.Strings[96619]="我可以向你们保证，恶魔猎手们，绝对不要相信这张嘴里说出的任何话。"
D.Strings[96620]="虽然拉瑟莱克与燃烧军团目前的计划毫无关系，但他知道许多对我们有用的魔法。"
D.Strings[96621]="等燃烧军团降临——相信我，他们一定会的——你们这个小小的指挥中心绝对保护不了你们。"
D.Strings[96622]="你知道吗？你们中间藏着一个魔誓者。"
D.Strings[96623]="多年来，我们的灵魂在扭曲虚空中争斗不休。直到最近，我们才回到艾泽拉斯。所以，我才会与他争夺这具新的恐惧魔王躯体的控制权。"
D.Strings[96624]="血色十字军被仇恨和恐惧蒙蔽了双眼……变成了一群疯子和凶手。他们已经没救了，更不值得怜悯。"
D.Strings[96625]="现在跪下，向新主人俯首称臣吧！"
D.Strings[96626]="别想违抗我。你是我的了。"
D.Strings[96627]="很好，这是个不错的考验。"
D.Strings[96628]="赐予我力量……打碎这些枷锁……"
D.Strings[96629]="一个叫帕达沃森的强大巫师被胡墨格里斯抓住了。快找到胡墨格里斯，杀了他，别让他把帕达沃森干掉。"
D.Strings[96630]="胡墨格里斯死了，而帕达沃森还在喘气。干得好。"
D.Strings[96631]="砸扁你！"
D.Strings[96632]="你再折腾一百年，也杀不了我！"
D.Strings[96633]="人人都有一死。"
D.Strings[96634]="有人说我古怪，甚至愚蠢，那是他们目光短浅。要打败燃烧军团，我们唯一的希望是找到新的力量之源，哪怕那意味着承担极大的风险。\n\n你的新武器就是证明！"
D.Strings[96635]="你玷污了古老的传统，秘术师！神王不配进入英灵殿！"
D.Strings[96636]="我唾弃你们老掉牙的仪式，女武神！"
D.Strings[96637]="在你审判一个外来者之前，我要先放逐了你！"
D.Strings[96638]="那就是夜之子灵魂石！他正对梅瑞尔的一个影像使用它……"
D.Strings[96639]="你真以为你能打败我吗，小法师？我是不可战胜的！"
D.Strings[96640]="你成功了！卡萨纳提尔被安全地封禁在夜之子灵魂石里了！"
D.Strings[96641]="干得好，我的凡人朋友！我们应该把这东西带到守护者圣殿去安全保管。"
D.Strings[96642]="要不是亲眼所见，我根本不会相信。干得漂亮！"
D.Strings[96643]="多亏有你，这重担有人来挑了。我们回守护者圣殿去吧。"
D.Strings[96644]="认清你的身份，下贱的狗！"
D.Strings[96645]="你忘了自己的身份，渣滓！"
D.Strings[96646]="我再也受不了了！让我进去！"
D.Strings[96647]="我知道你们还有！给我酒！"
D.Strings[96648]="我不能再这么活下去了！"
D.Strings[96649]="现在，选个合适的目标吧。灵魂引擎怎么样？那艘战舰也不错……"
D.Strings[96650]="是火炮！降低高度，避开攻击！"
D.Strings[96651]="<咆哮>让他们付出代价，$n！让他们——"
D.Strings[96652]="我是食人魔。彻头彻尾的食人魔。当然不是……不是食人魔了。"
D.Strings[96653]="哇哈哈，魔法总能掩盖愚蠢的计划。杀戮时间到了！"
D.Strings[96654]="哇哈哈哈。砸扁你们。伪装真是个好计划。哈哈。"
D.Strings[96655]="你赶不走我的！"
D.Strings[96656]="求求你！求你帮帮我！"
D.Strings[96657]="没有它，我会死的！你一定要帮我！"
D.Strings[96658]="我必须做点什么！"
D.Strings[96659]="我是夏多雷！你们不能拒绝我！"
D.Strings[96660]="$n准备了一大堆苹果！"
D.Strings[96661]="燃烧军团，来帮帮我们！"
D.Strings[96662]="过来，我的仆从！"
D.Strings[96663]="伊利达雷，准备前往尼斯卡拉！"
D.Strings[96664]="蠢蛋的水又清又甜，肯定是在绿火从天而降之前搞到的。"
D.Strings[96665]="快，蠢蛋，跳起来吧！记住我的谜语，出去寻找答案吧。"
D.Strings[96666]="我的血肉都属于你，纳拉萨斯！"
D.Strings[96667]="带我走吧，万虫之母！"
D.Strings[96668]="吞噬我血液中的力量吧！"
D.Strings[96669]="一个……两个……啊，三个！现在我们知道蠢蛋是不是对的了！"
D.Strings[96670]="曾经有一个古老的寓言，是关于一个樵夫的。他在森林着火时去砍树。$b$b“你怎么还在砍树？”人们问他，“森林着火了。你的房子很快也会被烧到的。”$b$b樵夫看着熊熊的大火，深吸了一口浓烟。“那我该变成什么人呢？”他问，“我就是我。”$b$b<达里尔又砍了一捆木头。>$b$b这里头并没有什么寓意。"
D.Strings[96671]="你这是玩火，愚蠢的$c！我要烧死你！"
D.Strings[96672]="圣光……我的血肉……不不不，你会毁掉一切的，愚蠢的$c！"
D.Strings[96673]="没有地方是安全的。任何一座高山都逃不过燃烧军团的怒火。我还会回来的！"
D.Strings[96674]="我要雪！快下雪！"
D.Strings[96675]="别摇我了！"
D.Strings[96676]="哇啊啊啊啊啊！"
D.Strings[96677]="好啦，别挤了。"
D.Strings[96678]="你要把我挤扁了！"
D.Strings[96679]="嘎啊啊啊！我的背快要嘎啊啊啊！"
D.Strings[96680]="这叫寒冰屏障，你这个蠢啊啊啊啊！"
D.Strings[96681]="快，别站在暴风雪里！"
D.Strings[96682]="大伙儿，我们的路还很长……啊啊啊啊"
D.Strings[96683]="别慌张，我们能行的……啊啊啊啊啊！"
D.Strings[96684]="噶啊啊啊啊……不要！不！不要戳我的眼睛……"
D.Strings[96685]="大伙儿，谢谢了。我非常为你们自豪。你们都干得很棒。"
D.Strings[96686]="什么……？达里尔一直都是恶魔？我们怎么都没发现呢？"
D.Strings[96687]="好吧，难怪他的帐篷总是半夜里传出念咒的声音，还有硫磺的味道。"
D.Strings[96688]="|TInterface\\Icons\\Spell_Shadow_Possession:20|t拉格萨开始施放|cFFFF0404|Hspell:57697|h[恐惧面容]|h|r。移开你的视线！"
D.Strings[96689]="提里奥！圣光啊……他们对你做了什么？"
D.Strings[96690]="我来救提里奥。你去找灰烬使者，否则就迟了！"
D.Strings[96691]="这里腐蚀横行。我预感有场漫长的战斗在等着我们。"
D.Strings[96692]="小心！注意规避！"
D.Strings[96693]="<呻吟>快点离开这儿，$n！我会——"
D.Strings[96694]="<驯犬者低声咆哮了起来，恶狠狠地盯着你。>"
D.Strings[96695]="我在这儿的任务还没完成呢。去死吧，多管闲事的$c！"
D.Strings[96696]="我们将在敌后散播灾难。没有地方是安全的。"
D.Strings[96697]="这股力量……燃烧得如此旺盛。$b$b我的兄弟们太愚蠢了，竟然无视了这份礼物。等我有了足够的能量，我就能自己夺回城市！"
D.Strings[96698]="圣光啊……给我最后的祝福吧……"
D.Strings[96699]="移动到尼斯卡拉上空。"
D.Strings[96700]="所有人都上甲板。准备轰炸！"
D.Strings[96701]="不要丧失信仰……"
D.Strings[96702]="这是……我们最后的阵地……"
D.Strings[96703]="伸张正义的时刻……降临了……"
D.Strings[96704]="我们必须……同心……"
D.Strings[96705]="|TInterface\\Icons\\spell_fire_playingwithfiregreen:20|t%s获得了|cFFFF0000|Hspell:208903|h[燃烧之爪]|h|r！"
D.Strings[96706]="又是你？！真以为能打败有军团支持的我吗？"
D.Strings[96707]="放弃吧，蠢货！骨语者不会让外来者获得试炼资格的！"
D.Strings[96708]="我们将在圣光穹顶背水一战！既然你能过来，那也能找到那座神殿。但我不知道你要花多少时间……"
D.Strings[96709]="你预见到了吗，先知？你知道我们会来吗？"
D.Strings[96710]="我带来了基尔加丹的口信，看着你的人民流血而死吧！正义终将实现！"
D.Strings[96711]="这些叛逃的“德莱尼”都将卑贱地死去！毁掉他们的尸体，让活着的人看清自己的下场！"
D.Strings[96712]="我们可以去紫罗兰监狱。在那里，我们能尽情地和哈卡战斗，不会殃及池鱼。"
D.Strings[96713]="|TInterface\\Icons\\inv_jewelcrafting_immactaladite_purple:20|t崩岩开始施放|cFFFF0404|Hspell:216970|h[元素共鸣]|h|r。快找掩体！"
D.Strings[96714]="你太不自量力了，圣骑士。"
D.Strings[96715]="是我让你来到这里。也是我饶你一命。现在，我要你臣服于我！"
D.Strings[96716]="我们父亲的纪念碑就在转角处。安纳瑞斯肯定在那附近。"
D.Strings[96717]="蝙蝠拍蝙蝠。$b$b蝙蝠拍蝙蝠。"
D.Strings[96718]="嗷——不，不！我的伪装。我是燃烧军团。我要毁灭你！"
D.Strings[96719]="呵呵呵……拍死你！"
D.Strings[96720]="我可是纳斯雷兹姆。别挣扎了！"
D.Strings[96721]="你以为我会蠢到孤身犯险吗？"
D.Strings[96722]="放弃吧，趁我还有耐心。"
D.Strings[96723]="我听到你们的声音了！你们这些恶魔在冲下来之前，最好掂量掂量！"
D.Strings[96724]="我这儿不但有扳手，还有一个暴怒的麻风侏儒！你们最好别进来，恶魔！"
D.Strings[96725]="你！就是你！等这一切结束之后，麻烦来把我弄出去！现在，请你快走开。你会把他们引过来的！"
D.Strings[96726]="不要盯着看太久。对于我们这些上流人士来说，这地方没什么稀奇的。"
D.Strings[96727]="我为你弄到了一台肩舆。尽量傲慢点——这可以保持伪装。"
D.Strings[96728]="你要找的人名叫玛尔迦。她对我们的事业有兴趣。"
D.Strings[96729]="我应该还是可以派上点用场的。"
D.Strings[96730]="等你看到它时就已经迟了。"
D.Strings[96731]="<麦丽菲卡紧张地盯着其他德鲁伊，直到你的出现打扰了她。>$b$b嘘，$c。我在听着呢。$b$b<她又将注意力转到了周围的德鲁伊身上。>"
D.Strings[96732]="噢，你这该死的家伙——我在这儿的任务还没完成呢。去死吧！"
D.Strings[96733]="打起精神来，你很快就能重新站起来了。"
D.Strings[96734]="你看起来简直面目全非，不过……我相信你马上就会恢复原样了！"
D.Strings[96735]="哟，这可真有趣。我们下次再玩吧。"
D.Strings[96736]="好好休息吧。你马上就会好起来了。"
D.Strings[96737]="噢！这味道！我还要更多！"
D.Strings[96738]="不！不准带走！杀了这个贼！"
D.Strings[96739]="不！我的……"
D.Strings[96740]="等我稍微恢复一点力气，我马上就回来。"
D.Strings[96741]="我还有点虚弱。等我恢复了战斗力，马上就回来找你。"
D.Strings[96742]="别问。做好战斗的准备吧。"
D.Strings[96743]="这些伤？哈！它们绝对够我吹嘘一阵子的了。"
D.Strings[96744]="我行走在这片土地上，不断观察，聆听。$b$b也许这就是你以前没见过我的原因，没什么好怀疑的。"
D.Strings[96745]="滚开，$c！燃烧军团是全视全知的！"
D.Strings[96746]="你这废物。我还会回来的。"
D.Strings[96747]="拿起武器！别被偷袭了！"
D.Strings[96748]="该战斗了！"
D.Strings[96749]="磨利你们的刀剑吧！战斗还没结束呢！"
D.Strings[96750]="我的剑已经蓄势待发了！"
D.Strings[96751]="他们以为自己能在我们的土地上为所欲为吗？我们走着瞧！"
D.Strings[96752]="哇哈！这蠢蛋的动作真快！可这家伙能猜出我的其他谜语吗？"
D.Strings[96753]="什么味儿？噢，是这批酒。小心点，蠢蛋！别洒在自己身上了！"
D.Strings[96754]="我欠你的人情太多了，$n。但愿我有一天能够报答你。"
D.Strings[96755]="你的事迹已经传遍了整座大厅，$n！能成为你的勇士让我感觉很自豪。"
D.Strings[96756]="有了你的指引，我相信我们一定能战胜燃烧军团！"
D.Strings[96757]="哪怕是在这种废弃的状态下，守护者圣殿的图书馆仍然能媲美银月城的。我会让魔导师们支持我们在这里的行动的。"
D.Strings[96758]="这个地方真是一座知识的宝库，$n！我一直在阅读提瑞斯法议会的神奇历史。你知道吗，是梅瑞尔和阿洛迪制造了守护者熔炉！"
D.Strings[96759]="听到没有？！做好准备！"
D.Strings[96760]="我恐怕不是干这个的料。等这一切都结束之后，再回来找我吧。"
D.Strings[96761]="知道吗，你很勇敢。我想我最好还是待在里头，直到外面安稳下来为止。"
D.Strings[96762]="你说得对，$n。有你这样勇敢的$c在我身边，我们就是不可阻挡的！"
D.Strings[96763]="我们俩一起来干掉那些恶魔吧！"
D.Strings[96764]="啊……我这是想骗谁啊？我可不懂战斗。我最好还是进去吧。你自己保重！"
D.Strings[96765]="噢……我的头！谢谢你的帮助。等我能站稳了，我就回来帮忙。"
D.Strings[96766]="噢！我得给自己找几把武器。我的看来是丢了……我不记得是丢在哪儿了。"
D.Strings[96767]="我在哪儿？等我彻底清醒之后，我就回去。"
D.Strings[96768]="我的脑袋差点被他们砍掉了！我去追他们，你继续前进吧，$n。"
D.Strings[96769]="谢谢你，$g小子:丫头;。"
D.Strings[96770]="$n！你一击败卡萨纳提尔，我的心头就好像放下了一块大石！"
D.Strings[96771]="我这辈子都没这么好过。那块夜之子灵魂石彻底剥夺了卡萨纳提尔的力量。我对你感激不尽。"
D.Strings[96772]="别傻站在那儿等死。攻击。让灭绝者出击！"
D.Strings[96773]="看来我们要走运了，老朋友。有了这位新晋大法师和提瑞斯秘法会的力量，我们一定能击败燃烧军团！"
D.Strings[96774]="你就是新生的提瑞斯秘法会最闪亮的实力榜样！向我们的新晋大法师$n致敬！"
D.Strings[96775]="终于……夜之子灵魂石！都归我了……对对，我是说我们！"
D.Strings[96776]="可惜我们要食言了，米尔豪斯。只要灵魂石还囚禁着卡萨纳提尔，我们就最好别去碰它。但我相信外面肯定还有大把其他强大的神器等着你去寻找呢！"
D.Strings[96777]="拿起武器！我们有伴儿了！"
D.Strings[96778]="我得在被恶魔干掉之前离开这儿。"
D.Strings[96779]="卡拉诺斯的居民们受到了鼓舞，纷纷加入了对抗燃烧军团的战斗！"
D.Strings[96780]="啊……你是来学习古老的酿酒技艺的吗？"
D.Strings[96781]="又一个品酒家？你愿意帮我准备原浆吗？"
D.Strings[96782]="再也没有比准备装桶的新鲜酒浆更美妙的香味了。自己动手试试吧，那你就明白了！"
D.Strings[96783]="是的，我已经准备好帮忙酿造魔力酒了。"
D.Strings[96784]="那就让我们开始吧。我会告诉你该做些什么，根据我的指示来做就行了。"
D.Strings[96785]="有什么稀罕的钓鱼用品吗？"
D.Strings[96786]="混账！我要跟你绝交。"
D.Strings[96787]="有人好像渴了！"
D.Strings[96788]="看来你需要帮忙啊，伊尔萨。"
D.Strings[96789]="你们的美酒节真虚伪！总有一天，人人都会明白，黑铁烈酒才是最棒的美酒！"
D.Strings[96790]="感谢你让我拜访你的大厅。真希望我们能在更愉快的情况下见面。"
D.Strings[96791]="请将我传送回达拉然。"
D.Strings[96792]="这种三年陈的酒液加入了美妙的浆果元素，以及画龙点睛的西瓜香味。很提神吧？"
D.Strings[96793]="啊，这是瓶好酒。第七代法力果与柔滑的暗夜树汁的味道丝丝入扣，带有美妙的核桃回味。"
D.Strings[96794]="这种浓郁的美酒用刚成熟的暗影莓和法力果酿成，加了三倍的暗夜井精华，适合小口品尝。"
D.Strings[96795]="花朵来了，父亲！"
D.Strings[96796]="对，这是朵花。"
D.Strings[96797]="我有浸水的魔力要给你。"
D.Strings[96798]="进入酒桶，在那些果子上面跳几下吧！"
D.Strings[96799]="这批酒需要添加一些酸味……一些暗影物质。"
D.Strings[96800]="你需要加点水分，否则会把龙头堵住的！"
D.Strings[96801]="扔点鲜花进去，提升品味。"
D.Strings[96802]="我们出发吧。跟我来！"
D.Strings[96803]="雄鹰之爪已经失落太久了，许多牛头人甚至都没见过它。长老们却还在传颂着我们最伟大的猎人挥舞着它保卫我们土地的故事。"
D.Strings[96804]="这些英雄屠杀过恐怖的怪物，战胜过无数入侵者。多罗·高岭是它的最后一任主人。他是死在一头袭击我们村庄的堕落夜刃豹爪下的。"
D.Strings[96805]="一想到卡萨纳提尔那么轻易就压倒了我的意志，我就心头发紧。多亏了$n的努力，我自由了，卡萨纳提尔也得到了制裁。"
D.Strings[96806]="这头野兽叫达喀尔。它曾是一头高贵的生物，但一个疯狂的维库秘术师逼疯了它。多罗战胜了它，然后追着这头野兽去了风暴峡湾。可他再也没有回来，雄鹰之爪也不见了踪影。"
D.Strings[96807]="我希望有一天我们的部族能迎来真正的和平。"
D.Strings[96808]="隐秘通途欢迎一切访客。"
D.Strings[96809]="就是这样！对于业余人士来说，这批酒很不错了。我这就把它装瓶！"
D.Strings[96810]="<给予丝纹绷带。>"
D.Strings[96811]="<给予至高岭鲑鱼。>"
D.Strings[96812]="<给予大块异香肋排。>"
D.Strings[96813]="他们无处不在……"
D.Strings[96814]="喜欢这个酒庄吗？"
D.Strings[96815]="和我担心的一样。阿坎多尔有危险了。"
D.Strings[96816]="我以前好像见过类似的东西。可在哪儿呢……"
D.Strings[96817]="啊！酒庄！"
D.Strings[96818]="我们同舟共济。"
D.Strings[96819]="我们需要你的意见。"
D.Strings[96820]="请随意参观吧。"
D.Strings[96821]="我很高兴当初选了你来领导提瑞斯秘法会，我没有选错人，大法师$n！"
D.Strings[96822]="大法师$n！你完全配得上这个头衔，我的朋友。"
D.Strings[96823]="你是我这几百年来见过的最有活力的大法师，$n。能成为你的勇士让我很自豪。"
D.Strings[96824]="很好，大领主。我会详细介绍一下我们的部队和行动计划的。"
D.Strings[96825]="我已经听过传闻了……但美好得有些不真实。\n\n请原谅——我们得小心行事，决不能引起任何怀疑。他们……对我们很苛刻。"
D.Strings[96826]="玛尔迦看了看两边，默默评估着局势。"
D.Strings[96827]="参观？当然了！我会亲自带你四处参观一下的。"
D.Strings[96828]="看来你的狩猎很成功！当然，我对此早有预料。"
D.Strings[96829]="我每天都在研究圣光以及它在这个世界的目的，可真相依然遥不可及。"
D.Strings[96830]="当然，大领主。我知不无言。圣光之道贵在公正。无论我们有何目的，都要坚持正义。"
D.Strings[96831]="你刚刚离开的那个庭院是对访客开放的。从这里开始，就必须由我的员工陪伴你参观了。"
D.Strings[96832]="我的助手希尔维林那里可以购买纪念品和礼物。或许你可以在离开的时候顺便买一点？"
D.Strings[96833]="这里是我们的品酒室。在这里，我们只提供最好的品种——很多都是宫中御用的佳酿！"
D.Strings[96834]="圣光始终在吸引着我。也许这是因为我父亲也受到过召唤，而我想要沿着他的足迹前行。"
D.Strings[96835]="你可以随意品尝我们今天提供的样品。等你尝完之后，我们再继续参观。"
D.Strings[96836]="我听说我们收到了我父亲的消息？我的父母还活着吗？"
D.Strings[96837]="白银之手骑士团又重生了。它的新领袖不会让它失败的。"
D.Strings[96838]="对，召开战争议会是个好主意。燃烧军团的部队遍布破碎群岛。我们不能失去这个据点！"
D.Strings[96839]="这些恶魔灵魂足够为传送门充能了。准备。"
D.Strings[96840]="我一直在警惕着，$n。我已经厌倦了观察和等待。是时候果断出击了，否则我们就将失去一切。"
D.Strings[96841]="大领主，你迟早会听我的。我们应该集中力量猎杀恐惧魔王巴纳扎尔。报仇的时刻到了！"
D.Strings[96842]="我们要马上弄到那块夜之子灵魂石，$n！我敢打赌，我一定能用它弄出你前所未见的大爆炸来！"
D.Strings[96843]="这地方太棒了！我刚知道，这里有对我有用的信息！"
D.Strings[96844]="等我弄到那块夜之子灵魂石，我一定要去烤几个恶魔来庆祝一下！"
D.Strings[96845]="只要想一想我们能用那块灵魂石造成多大的破坏，我就激动地不能自已。求你了！把它给我吧！"
D.Strings[96846]="只要你把夜之子灵魂石给我，我保证你绝对不会后悔的……我一定会用它的力量来做好事的。我保证！"
D.Strings[96847]="如果你不把快点那块灵魂石给我，我就要生气了。你绝对不会想要我生气的……"
D.Strings[96848]="难以置信，你居然不让我留下那块夜之子灵魂石。它蕴含着燃烧军团的力量！"
D.Strings[96849]="她活了下来，但这并不轻松。"
D.Strings[96850]="塔莉萨说你有一种对付害虫的特殊方法。是吗？"
D.Strings[96851]="还有希望。我们每天都在取得进展。"
D.Strings[96852]="<玛尔迦紧张地看了看四周，然后靠近你，压低了声音。>\n\n既然其他人还在阴影中行动，那塔莉萨一定还活着。除了首席奥术师，还有谁能发起这样的行动呢？\n\n告诉我——她还好吗？"
D.Strings[96853]="害虫？你碰上虫害了？\n\n<玛尔迦古怪地看了你一眼。>\n\n没关系。你看，答案就在你眼前。法力浮龙会吃那些蚕食树木的害虫。它们能保护我们珍贵的植物，而且胃口很好。\n\n在参观途中，我会安排时间让你抓一些浮龙的。"
D.Strings[96854]="那我就放心多了。不过，我们还是接着走吧。"
D.Strings[96855]="你先请，玛尔迦。"
D.Strings[96856]="那么……你到底来这里做什么？对于反抗军的成员来说，这是绝对是最危险的地方之一。"
D.Strings[96857]="谢谢你！我已经准备好了，现在就能出发。"
D.Strings[96858]="他们真是——我恨他们！我们尽力讨好他们，换来的却是流放和死亡。可在大魔导师把这里列为禁区的时候，我什么也做不了。\n\n你肯定有着庞大的关系网络才能进入这里。反抗军的队伍又壮大了吗？它真的能对抗艾利桑德吗？"
D.Strings[96859]="在这里说恐怕不太安全，玛尔迦。"
D.Strings[96860]="<玛尔迦叹了口气。>\n\n局势对我们很不利。我们动辄就被打击流放。但你和首席奥术师会跟我们站在一起的。我对此深信不疑。\n\n我相信暮色百合。\n\n不过，我们已经抱怨得够多了。你准备好结束参观了吗？"
D.Strings[96861]="我明白了……那我们就继续？"
D.Strings[96862]="这是个充斥着恶魔的黑夜。"
D.Strings[96863]="燃烧军团想要毁灭一切的一切……如果我们还想见到黎明，就要紧抱艾泽拉斯的火焰。"
D.Strings[96864]="作为一个凡人法师，你相当出色，$n。"
D.Strings[96865]="我很享受我们上次的旅行，$n。我随时可以陪你上战场。"
D.Strings[96866]="我们战胜燃烧军团的机会很渺茫，但还有希望，尤其是有你这样经验丰富的法师站在我们这边！"
D.Strings[96867]="卡萨纳提尔一直在我的脑海中呢喃，在远方召唤着我。我很高兴终于让他闭嘴了！"
D.Strings[96868]="既然卡萨纳提尔已经不再是威胁了，我们可以安心地寻找对抗燃烧军团的强大武器了。"
D.Strings[96869]="我欠你一份大人情，大法师$n。我不会忘记这一点的。"
D.Strings[96870]="我们现在走向的建筑叫做陈化室。"
D.Strings[96871]="我们喜欢用时间魔法来缩短这个流程。这是我们天生的能力！"
D.Strings[96872]="在我的左手边，就是我们的一座果园。"
D.Strings[96873]="如果你了解魔力酒的酿造流程，就会知道我们必须让果汁发酵。"
D.Strings[96874]="这果园里有一种特别的果树，能结出特别甜的果实。就是你在浸液里尝到的那种甜味。"
D.Strings[96875]="肯瑞托将全力支持新生的提瑞斯秘法会，$n。"
D.Strings[96876]="你面前的建筑里摆放着我们的装瓶设备。"
D.Strings[96877]="所有的瓶子上都有魔法封印，能防止暗夜井的精华流失。"
D.Strings[96878]="一桶产自我们酒庄的魔力酒可以安全地存放几百年！"
D.Strings[96879]="你的前方就是我们的分发设备。"
D.Strings[96880]="在这里，我们每天都要将数百桶魔力酒运送出城。"
D.Strings[96881]="大魔导师对这些流程的监督极其——"
D.Strings[96882]="别伤害他！"
D.Strings[96883]="我很抱歉——请原谅这个失误。我保证不会再让它发生了。"
D.Strings[96884]="刚才说到哪儿了？"
D.Strings[96885]="我相信，如果我们想要打败燃烧军团，肯瑞托必须接受来自各方的帮助。"
D.Strings[96886]="过了这座桥，就是我们酿酒过程中最重要的环节了。"
D.Strings[96887]="在这里，我们将暗夜井的精华注入酒浆中，使它们有了让我们的人民喜欢的滋补成分。"
D.Strings[96888]="在这里，我必须跟你分开了。我得去准备下一个活动了。"
D.Strings[96889]="如果我们要想打败燃烧军团的话，还有很多事要做。我绝不允许他们再次摧毁我的城市。"
D.Strings[96890]="我会在下一站等你。我的助手希尔维林会为你展示灌魔流程的。"
D.Strings[96891]="真的吗，图拉扬还活着？"
D.Strings[96892]="我们觉得……是真的。他的部队似乎惨败于燃烧军团之手。"
D.Strings[96893]="圣光啊……这会对世界有何影响？"
D.Strings[96894]="阿拉托尔，孩子。"
D.Strings[96895]="我们深爱的孩子。"
D.Strings[96896]="这个容器……感应到了小阿拉托尔！"
D.Strings[96897]="但愿你能听见，这消息很重要。"
D.Strings[96898]="多年来，我一直在星界猎杀燃烧军团。"
D.Strings[96899]="希望你能原谅我们的离开，我们这么做也是出于对你的爱。为了保护你和世界，我们选择做出牺牲。"
D.Strings[96900]="为了报复，恐惧魔王已派出大军，想摧毁我所珍视的一切。"
D.Strings[96901]="去召集圣光的守护者，阿拉托尔。为圣光而战吧，否则就全完了。"
D.Strings[96902]="艾泽拉斯是最后的希望之光，阿拉托尔。战斗吧，否则一切就都完了。"
D.Strings[96903]="如果你能用舰炮炸死下面的恶魔，我就让部队准备出击。"
D.Strings[96904]="用这个控制台吧。"
D.Strings[96905]="你可以用这个控制台。"
D.Strings[96906]="燃烧军团！小子丫头们，守好阵地。非战斗人员注意隐蔽！"
D.Strings[96907]="拿起武器！敌人过来了！"
D.Strings[96908]="他们的人数还在增加！大家得再加把劲儿了！"
D.Strings[96909]="你以为黑铁部族会让你们吃独食吗，嗯？"
D.Strings[96910]="我们都坚持到现在了，不要放弃！打倒他们！"
D.Strings[96911]="看来我们得跟他们打一场了！"
D.Strings[96912]="他们的首领在攻击卡拉诺斯！让他们看看你们的本事！"
D.Strings[96913]="又来了！快散开，他们就快抵达门口了！"
D.Strings[96914]="你们值得嘉奖，勇士们！我们阻止了军团！你们做到了！"
D.Strings[96915]="|TINTERFACE\\ICONS\\spell_warlock_demonsoul:20|t哈尔多拉开始施放|cFFFF0404|Hspell:217283|h[灵魂收割]|h|r。快跑！"
D.Strings[96916]="这片荒野中的熊怪部落是热爱和平的。他们现在陷入了恐慌，需要你的帮助。"
D.Strings[96917]="能带我飞去天禅院吗？我得跟美猴王谈谈。"
D.Strings[96918]="很好！那么，接下来应该……"
D.Strings[96919]="你真是个天才！看看接下来配方又要什么了……"
D.Strings[96920]="对，就像这样！唔……现在这批酒还需要什么呢？"
D.Strings[96921]="你好了就说一声，亲爱的。"
D.Strings[96922]="蠢蛋来要东西？你看上美猴王的什么东西了？"
D.Strings[96923]="这个哨兵稳稳地站立着。"
D.Strings[96924]="我已经警告过你们这些学生无数次了。我要拿你开刀，以儆效尤！"
D.Strings[96925]="欢迎光临“梦中”家园！你的玛法里奥就在里面。"
D.Strings[96926]="再猜一次，凡人！"
D.Strings[96927]="我没时间跟你玩游戏！"
D.Strings[96928]="我想请你带我去找高戈奈斯潮汐之石。"
D.Strings[96929]="对，有一位老师曾经提起过……"
D.Strings[96930]="我分不清他的声音是从哪儿传来的！快，去搜查东边的建筑。我去西边找他！"
D.Strings[96931]="我当时没有意识到。"
D.Strings[96932]="准备启动序列。"
D.Strings[96933]="我分不清他的声音是从哪儿传来的！去搜查东边的建筑。我去西边找他！"
D.Strings[96934]="关闭启动序列。"
D.Strings[96935]="快！我坚持不了多久了……"
D.Strings[96936]="你在哪儿，泰兰德？我需要你！"
D.Strings[96937]="你休想分开我们！泰兰德？！"
D.Strings[96938]="亲爱的！我在这儿！快过来！"
D.Strings[96939]="艾露恩诅咒你，萨维斯！你会付出代价的，我发誓！"
D.Strings[96940]="你这无礼的……小……"
D.Strings[96941]="正在启动自毁程序。"
D.Strings[96942]="坚持住，亲爱的！我就来了！"
D.Strings[96943]="对！我听见了！我马上就到！"
D.Strings[96944]="你试图操作这个哨兵，但是完全没有用。"
D.Strings[96945]="过来，勇士。追踪结束了。"
D.Strings[96946]="过来，部落的战士。追踪结束了。"
D.Strings[96947]="怎么样？哪个玛法里奥是真的，哪个是梦魇呢……？[大笑]"
D.Strings[96948]="你！回去干活儿！"
D.Strings[96949]="我只是在休息。我——"
D.Strings[96950]="我不想听你的借口。回去干活儿！"
D.Strings[96951]="我会上报给监工的。记住我的话，玛尔迦。"
D.Strings[96952]="再见，孩子。不要绝望，在最黑暗的时刻，光明才会格外闪耀。"
D.Strings[96953]="你们都听到我父亲的话了。我们行动吧！"
D.Strings[96954]="没错，阿拉托尔。兄弟姐妹们，该团结起来了。我们要比以往更信赖大领主的领导。"
D.Strings[96955]="我们该怎么办，大领主？我们该怎么做？"
D.Strings[96956]="不，这样不行。我们得重新开始。"
D.Strings[96957]="你来之前是不是已经喝多了？这批酒得扔掉了……"
D.Strings[96958]="不，这样绝对不行。再来一次，这次麻烦你上点心！"
D.Strings[96959]="%s发出了一声感激的低吼。"
D.Strings[96960]="燃烧军团回来了！快通知铁炉堡，守好阵地！"
D.Strings[96961]="我们有伴儿了！上面有军团的战舰！准备！"
D.Strings[96962]="猎杀恐惧魔王，巴纳扎尔。"
D.Strings[96963]="寻找圣光的盟友。"
D.Strings[96964]="抵挡恶魔的入侵。"
D.Strings[96965]="做好准备！他们来了！"
D.Strings[96966]="为军队生产补给品。"
D.Strings[96967]="坚持住！让这些恶魔看看，他们休想占领铁炉堡！"
D.Strings[96968]="坚持住，兄弟姐妹们！为艾泽拉斯背水一战！"
D.Strings[96969]="为了黑铁的威名！为了铁炉堡！"
D.Strings[96970]="无论你们有多痛多累……不要对他们示弱！让我们并肩战斗！"
D.Strings[96971]="只要黑铁部族还在，军团就别想获胜！"
D.Strings[96972]="好想法，大领主。我们要直击罪魁祸首——巴纳扎尔。"
D.Strings[96973]="好主意，大领主。圣光的其他盟友会增强我们的力量。"
D.Strings[96974]="没错，大领主。如果放任不管，恶魔入侵会愈演愈烈。必须加强抵抗。"
D.Strings[96975]="小鬼们饿了……"
D.Strings[96976]="请原谅……你是想找死吗？"
D.Strings[96977]="我强烈反对！"
D.Strings[96978]="别闹了——离那儿远点儿！"
D.Strings[96979]="你还是这么务实，大领主。后勤准备很庞杂。补给、通信、武器、护甲……我们得立刻动手。"
D.Strings[96980]="这是什么愚蠢行为？在这种状态下，暗夜井的能量极其不稳定！"
D.Strings[96981]="以铁炉堡的威名，都起来！给这些恶魔一个痛快！"
D.Strings[96982]="我想招募一些小鬼。"
D.Strings[96983]="不要对这些恶魔手软！"
D.Strings[96984]="上坐骑！我们得阻止他们前进！"
D.Strings[96985]="散开！这场战斗才刚刚开始呢！"
D.Strings[96986]="他们的数量还在增加！我们来守住天上。干掉他们的地面部队！"
D.Strings[96987]="特瓦利斯队长从阴影中现身了。"
D.Strings[96988]="又发现了燃烧军团的营地！摧毁它们，快！"
D.Strings[96989]="特瓦利斯队长消失在了阴影中。"
D.Strings[96990]="去卡拉诺斯！我们要阻止他们的首领！为了铁炉堡的荣耀！"
D.Strings[96991]="吐掉嘴里的血，包好伤口，滚去卡拉诺斯吧！决战在等着我们！"
D.Strings[96992]="干得好，勇士们！铁炉堡不会忘记你们在战场上的英勇表现！"
D.Strings[96993]="干得好！军团恐怕不会就此销声匿迹，但等他们卷土重来时……我们会严阵以待！"
D.Strings[96994]="燃烧军团的战舰开到我们头顶上了！你们该补交税款啦！"
D.Strings[96995]="东边有燃烧军团的战舰！锁上店面！把你们的易碎物品都藏好！事情开始变得有趣起来了。"
D.Strings[96996]="所有人都做好准备！敌人过来了……而且不好对付！"
D.Strings[96997]="这不是演习！他们来了！记住：优先保护我的财产！"
D.Strings[96998]="噢，看！他们变大了一点儿……但愤怒了很多！"
D.Strings[96999]="肯定有东西钻进他们的皮肤里了！他们越来越大，越来越恶心了！"
D.Strings[97000]="瞄准他们的小腿、膝盖，或是……你们能够得着的任何部位！总之干掉他们就对了！"
D.Strings[97001]="看来那两个已经嗨起来了！准备好帽子和烟花！"
D.Strings[97002]="快收拾你们的东西！我们要打上门去了。"
D.Strings[97003]="所有人都出去！该把这些家伙踢进阴沟里去了……如果加基森有阴沟的话！"
D.Strings[97004]="情况开始失控了！他们又进攻了！现在怎么办？"
D.Strings[97005]="小心！他们无孔不入……就像打秋风的穷亲戚！"
D.Strings[97006]="我们要在加基森背水一战！是时候瞄准他们的头头了！抢光他口袋里的一切！"
D.Strings[97007]="它很大，很丑，很……呃……总之，快去加基森干掉它！"
D.Strings[97008]="黑暗收割议会随时为您效劳。"
D.Strings[97009]="拯救世界的机会可不是……天天都有的！我会继续努力的。"
D.Strings[97010]="干得好，朋友们！诺格弗格小店今天打九九折！"
D.Strings[97011]="天空在燃烧，盟友们！燃烧军团又来了！"
D.Strings[97012]="准备战斗！决不能让燃烧军团摧毁我们在这里所建立的一切！"
D.Strings[97013]="拿起武器，盟友们！战斗开始了！"
D.Strings[97014]="为暴风城守住哨兵岭！为了全艾泽拉斯！"
D.Strings[97015]="不要后退！不要放弃！继续战斗！"
D.Strings[97016]="末日守卫来了！去哨兵岭做好准备！"
D.Strings[97017]="回头见，帅哥。"
D.Strings[97018]="来自各方的盟友们！该为我们的家园决一死战了！"
D.Strings[97019]="回头见，美女。"
D.Strings[97020]="来吧，幽灵们，来侍奉燃烧军团吧。"
D.Strings[97021]="即使是死了，这些幽灵也得服从命令。"
D.Strings[97022]="多亏了你们的努力，燃烧军团又失败了！月溪旅欠你们一份人情！"
D.Strings[97023]="我失控了！"
D.Strings[97024]="他们能烧焦土地……屠杀人民……但我们决不投降！为了艾泽拉斯！"
D.Strings[97025]="我……必须……服从！"
D.Strings[97026]="快！都散开！净化这些腐蚀！"
D.Strings[97027]="夺回属于我们的东西！让这些恶魔滚回虚空去吧！"
D.Strings[97028]="他们的部队散开了！绝不能让他们抵达暴风城！"
D.Strings[97029]="燃烧军团很坚决！立刻终结这邪恶的腐蚀！"
D.Strings[97030]="快，英雄们！守住哨兵岭！杀掉这些恶魔的主子！"
D.Strings[97031]="立刻去哨兵岭！让我们一起把这个恶魔丢回扭曲虚空！"
D.Strings[97032]="伊利达雷！传送门开启了。登上邪能之槌号！"
D.Strings[97033]="凯丽娅，瓦雷迪斯，我们来了！"
D.Strings[97034]="伊利达雷棱堡占据了地利，能免受上方的混战影响。"
D.Strings[97035]="荣耀的时刻即将到来。入侵尼斯卡拉意味着我们所有的牺牲和期待都将实现。\n\n带领我们走向胜利吧，$n。"
D.Strings[97036]="下令吧，奥图里斯。我们下去。"
D.Strings[97037]="下令吧，凯恩。我们下去。"
D.Strings[97038]="我要剥夺你们的灵魂！"
D.Strings[97039]="你是个幸运的$g家伙:姑娘;。你可以挣脱锁链，走出大门了。$b$b高尔克可以轻易挣断锁链，可高尔克能挤出大门吗？不能。"
D.Strings[97040]="阿卡玛，你和其他人留下守卫邪能之槌号。"
D.Strings[97041]="阿卡玛之影，你和其他人留下守卫邪能之槌号。"
D.Strings[97042]="你们五个，跟我和$n走。尼斯卡拉在等着呢！"
D.Strings[97043]="对，蠢货们。下来送死吧。"
D.Strings[97044]="你消灭了这里所有的恶魔，可还有更多在前头等着我们。如果我们想要找到凯丽娅和瓦雷迪斯的话，就得从他们的副官中间杀出一条血路来。\n\n只要你一声令下，我们就动手。"
D.Strings[97045]="遵命。行动开始。"
D.Strings[97046]="你想要什么？我在这里干了一万年，却没有得到过哪怕一点点尊重。费尔里奇干这个，费尔里奇干那个。费尔里奇到底能为你干点儿啥？"
D.Strings[97047]="你看起来很不高兴。"
D.Strings[97048]="我为什么要不高兴？学生们都在大厅里，从来都不睡觉。他们不停地要吃的，整个地方都是一团糟。到处都是水！而他们有雇人来帮忙吗？没有！他们说了，费尔里奇会搞定的。我已经下了最后通牒，让他们弄走那些该死的书。\n\n现在，“你”到底要什么来着？"
D.Strings[97049]="噢，事实上我很好。"
D.Strings[97050]="唔……原料已经变酸了。恐怕我们得重新开始了。"
D.Strings[97051]="你真的做好练习的准备了吗？这批酒全毁了。"
D.Strings[97052]="我感觉你的注意力已经分散了。你在想别的事吗？休息一会儿吧，我们稍后再试一次。"
D.Strings[97053]="太好了！你做得很好——你真的从来都没酿过酒吗？我这就把它装瓶。"
D.Strings[97054]="到桌子边上来吧。等开始之后，你一定要跟上我的节奏。这些精致的原料很容易变质。"
D.Strings[97055]="我们要开始制作原浆了。你做好帮忙的准备了吗？"
D.Strings[97056]="这是我最喜欢的环节！这香味，这质感，还有这欢快流淌的酒液！亲手酿造过魔力酒之后，你就会明白我为什么会留在酒庄了。"
D.Strings[97057]="干得好。现在，让我来看看……"
D.Strings[97058]="我的朋友，你真是个天才。不过这里头还缺了点什么。让我想想……"
D.Strings[97059]="这正是它需要的。但还少了点什么……"
D.Strings[97060]="啊！它需要来点鲜花，增添一些色彩。"
D.Strings[97061]="加点水分吧，让酒液从龙头中顺畅地流出。"
D.Strings[97062]="我想接下来需要一点酸味。麻烦加个暗影莓进去。"
D.Strings[97063]="果子也需要按摩——踩到酒桶里去跳几下，榨出果汁吧！"
D.Strings[97064]="上课时不准说话！"
D.Strings[97065]="启动能量转移序列。"
D.Strings[97066]="嘿，实习生，你说其他猎人会不会不喜欢我们驯服的机械生物啊？"
D.Strings[97067]="这就要靠我们打出品牌了！所以我管这些小家伙叫做程控（Programmable）电子（Electronic）战略（Tactical）伙伴（Sidekicks）……P.E.T.S.！"
D.Strings[97068]="我……我活过来了！谢谢你，女祭司！"
D.Strings[97069]="这里发生什么事了？蠢蛋的表情很悲伤。"
D.Strings[97070]="站起来吧，大检查官！你的死亡领主要求你重返这个世界！"
D.Strings[97071]="我们可不是来和谈的，大检查官。"
D.Strings[97072]="审判日即将来临。燃烧军团来摧毁我们的世界了。"
D.Strings[97073]="黑锋骑士给你一个赎罪的机会。"
D.Strings[97074]="加入我们，让我们一起寻求救赎。"
D.Strings[97075]="我……活了？死亡的痛苦结束了？"
D.Strings[97076]="为什么？你为什么要这么对我？"
D.Strings[97077]="救赎？我还能得到救赎……吗？"
D.Strings[97078]="对，我们会的。"
D.Strings[97079]="别现身！你现在帮不了她。谁都做不到。"
D.Strings[97080]="识相的话，就赶快走。"
D.Strings[97081]="我只是做了我以为——"
D.Strings[97082]="我不想再听了。我判处你死刑，立即执行。"
D.Strings[97083]="我敢打赌，奥杜尔比你上次来的时候安静多了，布莱恩。"
D.Strings[97084]="守护者下令要求对奥杜尔的基础结构进行修复。凡人的英雄在战斗中非常英勇，但总是留下一堆烂摊子。抱歉，我并不是针对您说的。"
D.Strings[97085]="你说的倒也没错。我花了好几个星期时间才把宴会大厅打扫干净，那还是——"
D.Strings[97086]="等一下……你发现有什么不对了吗，卡德加？有一种熟悉感觉……我可不喜欢这样！"
D.Strings[97087]="在说出我的故事之前，我还要考考你。在美酒变酸之前，来青龙寺找我吧！"
D.Strings[97088]="脆弱的凡人。臣服于燃烧军团的威能吧！"
D.Strings[97089]="你的世界在为我们的到来而瑟瑟发抖！"
D.Strings[97090]="一群肉体凡胎……你们不是燃烧军团的对手！"
D.Strings[97091]="叛徒的名单？你该立刻把它交给中尉皮耶特。"
D.Strings[97092]="那好吧。我会去我们上次见面的地方找中尉。去给他带个话，让她在那儿等着我。"
D.Strings[97093]="我听说你拿到了叛军的名单？快，把它交给我们。"
D.Strings[97094]="蠢货，你被跟踪了！准备战斗！"
D.Strings[97095]="好了，你都卖些什么？"
D.Strings[97096]="注意那些叛军。你怎么小心都不为过。"
D.Strings[97097]="如果你看到有人偷魔力酒，要立即汇报！"
D.Strings[97098]="抓住她！"
D.Strings[97099]="我侦测到了大量传送法术，而且全部指向你的位置。"
D.Strings[97100]="我开启了传送器。你没时间了——找到传送台，离开那里。"
D.Strings[97101]="求求你……只要几滴魔力酒就能防止我发疯……"
D.Strings[97102]="你看起来很强大……你一定有多余的魔力酒！"
D.Strings[97103]="我的精神……越来越恍惚了……需要魔力酒……"
D.Strings[97104]="我给你带来了一些魔力酒……喝吧！"
D.Strings[97105]="真是慷慨！谢谢你，我欠你一条命！"
D.Strings[97106]="如此强大的力量……我得救了！谢谢你！"
D.Strings[97107]="嘿，又是一个可能让我们一去不返的任务，对吧？\n\n不过我这次带了我私藏的美酒。想来一口吗？"
D.Strings[97108]="当然，我要喝一口。"
D.Strings[97109]="不用了，谢谢。"
D.Strings[97110]="这酒闻上去很烈。真的要喝吗？"
D.Strings[97111]="废物！准备防守。我很乐意亲手杀了你，$n。"
D.Strings[97112]="救命，宗师们！恶魔在破坏寺院！"
D.Strings[97113]="交出：800份 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF远古魔力|h|r"
D.Strings[97114]="这么做将会移除800份远古魔力。确定要继续吗？"
D.Strings[97115]="报复？你可以做得更好。事实上，是好得多……"
D.Strings[97116]="真可爱。你是想害死我们两个吗？不是？我可不这么认为。"
D.Strings[97117]="所以说……这才像话嘛。刚好我天生就是干这个的料。"
D.Strings[97118]="青龙在里面跟入侵者战斗，我们守住大门好让幸存者逃脱。有几个书记员失踪了，我担心他们已经遭遇不测。拜托了，帮帮我们！"
D.Strings[97119]="玉珑像山一样强壮，像蜜蜂一样敏捷。可山也会被海淹没。"
D.Strings[97120]="这里的墙壁看起来很容易爬！美猴王要去找青龙。"
D.Strings[97121]="$n，我们就指望你救出我们的书记员了！"
D.Strings[97122]="多么美味的知识！"
D.Strings[97123]="很高兴你活了下来。"
D.Strings[97124]="伊利达雷，瞄准目标。攻击！"
D.Strings[97125]="我同意！我们得抢在他们决心逃跑之前攻进去。"
D.Strings[97126]="小心点，恶魔猎手们。再前进一步，我就让凯丽娅和瓦雷迪斯大开杀戒了。"
D.Strings[97127]="不会再有宽恕……也不会再有加入军团的机会。"
D.Strings[97128]="凯丽娅和瓦雷迪斯就躲在这个指挥中心里。要想攻破它，我们就需要援助。\n\n我建议让阿卡玛将邪能之槌号移动到攻击位置，轰击那道邪能屏障。"
D.Strings[97129]="又能吸取知识了！"
D.Strings[97130]="谁在那儿？贾沃克斯，有入侵者！"
D.Strings[97131]="贾沃克斯，小心点！就算死也要保护好法典！"
D.Strings[97132]="你们不属于这里，贾沃克斯，解决他们！"
D.Strings[97133]="别怕，大人。我的恶魔会打倒入侵者的！"
D.Strings[97134]="愚蠢的圣骑士……我抓住了你们的人！可惜巴纳扎尔大人不能亲眼看着他死！"
D.Strings[97135]="我绝不向你投降，恶魔！"
D.Strings[97136]="天灾军团来了！把入侵者送回墓穴里去！"
D.Strings[97137]="如果你死了，记住你的牺牲将为我带来巨大的荣耀！"
D.Strings[97138]="你们的存在亵渎了这座圣洁的礼拜堂！圣光会烧死你们的！"
D.Strings[97139]="我要用圣光的威能放逐你，恶棍！"
D.Strings[97140]="我的信仰……抛弃了我？"
D.Strings[97141]="等等！我们还不清楚敌人的实力。天知道你会撞上什么？"
D.Strings[97142]="血色十字军里就没人能来挑战我了吗？！"
D.Strings[97143]="决不能让巴纳扎尔大人的计划被干扰！"
D.Strings[97144]="我们受命消灭一切入侵者！"
D.Strings[97145]="白银之手骑士团？听上去是个美味的目标。"
D.Strings[97146]="一个美味的圣骑士。去死吧！"
D.Strings[97147]="恐吓无辜者的人都不配存在于世。"
D.Strings[97148]="暗影界也不会容忍邪恶的灵魂。"
D.Strings[97149]="动手吧，蠢蛋。试炼开始！只要酿出甜美的猴儿酒，就算你赢了！"
D.Strings[97150]="锅变热了。加一点点水进去。"
D.Strings[97151]="这酒闻着有点淡。蠢蛋，再加点谷物进去。"
D.Strings[97152]="蠢蛋该加下一样原料了。扔根香蕉进去，这才是正确的配方！"
D.Strings[97153]="不不不！别闹，你这样会毁掉这批酒的！"
D.Strings[97154]="不不不！不是这样的！看来蠢蛋要搞砸了！"
D.Strings[97155]="可惜啊，蠢蛋彻底搞砸了！这破酒让我想骂人了！"
D.Strings[97156]="干得好，蠢蛋！你很会选嘛！"
D.Strings[97157]="对对，就这样！快快，快拯救世界！"
D.Strings[97158]="你看着不错啊！闻着也不错！"
D.Strings[97159]="啊，没错！这是关键！保持，聪明的蠢蛋！"
D.Strings[97160]="火头太旺了！酒都溢出来啦！再来！别用那么大的火！"
D.Strings[97161]="蠢蛋在打瞌睡吗？是不是？我想你得从头来过了。"
D.Strings[97162]="这酒煮得太久了，蠢蛋搞砸了。现在我们只能从头再来了！"
D.Strings[97163]="这批猴儿酒太棒了！很合美猴王的口味！"
D.Strings[97164]="把锅子放在火的正中心，然后蠢蛋就能开始试炼了！"
D.Strings[97165]="你们不该来这儿，小家伙。燃烧军团的攻击非常猛烈。连我都受了许多伤。"
D.Strings[97166]="做好准备，敌人过来了！"
D.Strings[97167]="美猴王都快打瞌睡了。动手吧！我们最好立刻开始。"
D.Strings[97168]="我们去寺院吧。"
D.Strings[97169]="福枬选择了一位新的伙伴。艰难的试炼在前方等着你，小家伙。现在，你该回去休息，为未来做好准备。"
D.Strings[97170]="再见，小家伙。"
D.Strings[97171]="很高兴看到你又回来了。凡瑟尔又弄到了一批魔力酒，快把它们分发下去吧。"
D.Strings[97172]="算你走运，我找到了你。不然你就死了。"
D.Strings[97173]="把他们的东西都拿走！"
D.Strings[97174]="把他们的熊崽都抓起来！"
D.Strings[97175]="把他们全都打垮！"
D.Strings[97176]="把所有砸得烂的都砸掉！"
D.Strings[97177]="给他们的脚底板瘙痒！"
D.Strings[97178]="啃他们的膝盖！"
D.Strings[97179]="把他们的毛拔下来！"
D.Strings[97180]="让他们生不如死！"
D.Strings[97181]="你已经饿得走不动了了。"
D.Strings[97182]="我知道该从哪儿找起。"
D.Strings[97183]="噢！没想到他们这么快就会追上我！你也小心点！"
D.Strings[97184]="我都没想到自己能得救！"
D.Strings[97185]="到大路上去，快！我们最好不要孤身在这里瞎转悠！"
D.Strings[97186]="感谢你的帮助。我们最好还是快走吧。在这种情况下，我们最好还是不要被堵在这里！"
D.Strings[97187]="谢谢你的关心，$n，可我还得继续执行任务。天知道他们跑得有多远！"
D.Strings[97188]="谢谢你，$n。多保重！"
D.Strings[97189]="振作起来，$g小子:丫头;。要不是你的话，我肯定会更惨。"
D.Strings[97190]="味道有进步，但还需要浓烈的香气。打开酒桶，加入怪味啤酒！"
D.Strings[97191]="时间宝贵，我们得继续前进了！"
D.Strings[97192]="在我们闲逛时，燃烧军团正在不断壮大。"
D.Strings[97193]="伊利丹大人不在，你就是我们的首领了。我们不能背着你做决定。"
D.Strings[97194]="我只希望这点能够用。城里有那么多嗷嗷待哺的人……"
D.Strings[97195]="魔力酒越来越难剩下了……但只要我们有，我们都会和城里的穷人分享。"
D.Strings[97196]="我会把你的魔力酒分给有需要的人。"
D.Strings[97197]="这个地方藏着许多秘密，但它很少与外界分享它们。"
D.Strings[97198]="外面的世界太大太吵了。这里已经有我所需要的一切了。"
D.Strings[97199]="自从新的提瑞斯秘法会到来之后，大厅就变得异常嘈杂。我还是喜欢听老鼠在阴影里歌唱。"
D.Strings[97200]="谢谢你们，小家伙。我可以自行疗伤，可魔法生效需要时间。狡猾的敌人一定会趁机攻击的。"
D.Strings[97201]="在我恢复时保护好我。如果我们倒下，潘达利亚就完了。"
D.Strings[97202]="你离得太远了！快回去，否则她就逃走了！"
D.Strings[97203]="把它放下，小鬼。你们很快就会跟其他人一样了。"
D.Strings[97204]="为了表达我的谢意，就让我送你回家吧。"
D.Strings[97205]="元素总是小心翼翼地守着他们的秘密，但我一直在观察聆听。如果你知道如何与他们对话，他们的秘密也将属于你。"
D.Strings[97206]="我要看看职业进阶选项。"
D.Strings[97207]="在保护艾泽拉斯之心时，大漩涡之柱耗尽了力量。它会缓慢恢复，但这个过程需要几十年，我们可等不起。我们得想办法加速它的恢复。"
D.Strings[97208]="太好了！耐普图隆领主的礼物制造了奇迹。石柱似乎又能引导我的流水之力了。"
D.Strings[97209]="我们进展顺利，先知。大漩涡之柱的空气之力也复苏了。如果运气好的话，我们很快就能让它恢复到全盛状态了。"
D.Strings[97210]="你的帮助大大提高了我的进展速度，先知。石柱就快彻底恢复了。在恢复了流水、空气和大地的力量后，就只剩下火元素了。"
D.Strings[97211]="我满意得不能再满意了，先知。我们花了不少力气才让大漩涡之柱恢复全部力量，但这是值得的。$B$B去亲手试用一下吧——这根石柱能引导元素发挥出强大的力量！"
D.Strings[97212]="你的灵魂也将被关入我的牢笼。"
D.Strings[97213]="所有的灵魂都将属于我们……"
D.Strings[97214]="我们可以使用血石。那对姐妹被削弱之后，它的力量足以控制住她们。"
D.Strings[97215]="对，靠近点吧。看看我为你们准备了些什么。"
D.Strings[97216]="快逃！我们辜负了魔导师，她肯定会杀了我们！"
D.Strings[97217]="你们死到临头了。"
D.Strings[97218]="为这个送命太不值得！"
D.Strings[97219]="青龙教过我：王者有王者的责任。我们不会丢下你的。还有好多绿皮要杀呢！"
D.Strings[97220]="起来！大魔导师要求我们按时发货！"
D.Strings[97221]="大魔导师马上就要这批魔力酒。劳累不是你们怠工的借口！"
D.Strings[97222]="求求你……饶了我吧……我不行了……"
D.Strings[97223]="我的身体破烂不堪……我没法跟上。"
D.Strings[97224]="我有很多办法来强化你的职业大厅，但你可能需要作出一些艰难的选择。"
D.Strings[97225]="如果我下定决心的话，还是可以变几个戏法的……"
D.Strings[97226]="噢，快看！她多出色啊！她会成为你的好帮手的，$n，如果你客气地请求她的话。"
D.Strings[97227]="又来了！守护者会要我填写事故报告的！"
D.Strings[97228]="这座城市的防御系统已经被破坏了。那些负责保护代言人的单位没有回应我的呼叫！"
D.Strings[97229]="也许除了上古之神以外，还有人找到了进来的办法。"
D.Strings[97230]="确实如此！我想我们该加快脚步了。"
D.Strings[97231]="对，没错，这水对我很有用。我需要一点时间来处理它。谢谢你，先知。"
D.Strings[97232]="<递上礼盒装魔力酒。>"
D.Strings[97233]="塔莉萨温柔地微笑起来。"
D.Strings[97234]="我不会浪费掉它的。干得好，我的朋友。"
D.Strings[97235]="<这根柱子冰冷而安静。>"
D.Strings[97236]="<这根柱子散发着微弱的光。它不再那么冰冷，但摸上去还是有点凉。>"
D.Strings[97237]="<这根柱子温热了起来。>"
D.Strings[97238]="<这根柱子散发着能量。你触摸它的表面时，能感觉它外表下汹涌的原始能量。>"
D.Strings[97239]="引导空气的能量。"
D.Strings[97240]="引导流水的能量。"
D.Strings[97241]="引导大地的能量。"
D.Strings[97242]="引导火焰的能量。"
D.Strings[97243]="玛哈特到地底深处去。玛哈特收集亮晶晶。玛哈特好饿。"
D.Strings[97244]="你有化石蛋吗？"
D.Strings[97245]="不！玛哈特饿了！我要矿石！"
D.Strings[97246]="愚蠢的$r，你不明白自己放弃了什么。真美味！"
D.Strings[97247]="我准备好了，奥图里斯。让我们返回邪能之槌号，迁跃回马顿吧。"
D.Strings[97248]="我准备好了，凯恩。让我们返回邪能之槌号，迁跃回马顿吧。"
D.Strings[97249]="成功了。那两个邪魂恶棍都死了，他们再也别想回来了。\n\n你准备好之后，我们就能返回邪能之槌号了，$n。"
D.Strings[97250]="结束了。那两个邪魂恶棍都死了，他们再也别想回来了。\n\n你准备好之后，我们就能返回邪能之槌号了，$n。"
D.Strings[97251]="你以为我们会轻易放你们进来吗？你们的冲杀毫无意义，恶魔猎手。"
D.Strings[97252]="阿卡玛，让邪能之槌号过来。炸开这道邪能屏障。"
D.Strings[97253]="阿卡玛之影，让邪能之槌号过来。炸开这道邪能屏障。"
D.Strings[97254]="正在移动。你们最好后退一点。"
D.Strings[97255]="我很荣幸。后退点。"
D.Strings[97256]="基尔加丹大人，救救我……"
D.Strings[97257]="基尔加丹，让我复活……"
D.Strings[97258]="你们都将痛苦而死，尤其是你，$n。"
D.Strings[97259]="很好，伊利达雷。你死定了。你将给你的世界陪葬。"
D.Strings[97260]="命运在紧要关头指引你来到我们身边，英雄！我感觉你肩负着紧急任务，可如果不击退来犯的恶魔，我们都会灭亡。"
D.Strings[97261]="这个箱子被一种神秘的力量锁住了，无法当场打开。$b$b你可以解散你的部分枯法者部队，并让他们把它带回去交给塔莉萨。"
D.Strings[97262]="$n！请上前来。"
D.Strings[97263]="|c999900002名枯法者：|r把箱子带回去交给塔莉萨。"
D.Strings[97264]="请把你带来的东西拿给我看吧。我们没有多少时间了。"
D.Strings[97265]="你为我们做了很多，朋友。我很快就会再次召唤你的——在此之前，请接收我的谢意。"
D.Strings[97266]="离开哨兵。"
D.Strings[97267]="为我而战吧。"
D.Strings[97268]="我们正等着你的命令呢。"
D.Strings[97269]="我想招募一支弟子小队。"
D.Strings[97270]="拉基什……这名字在艾瑞达语中意为“屠夫”。基尔加丹派一个艾瑞达来屠杀我们并非巧合。欺诈者最喜欢给反抗他的人“发明”各种刑罚。"
D.Strings[97271]="拿着魔力酒。我得离开这儿了。"
D.Strings[97272]="阻止入侵者！我必须弄明白这个囚犯知道些什么！"
D.Strings[97273]="布莱恩！他们想要入侵我的思想！"
D.Strings[97274]="这座保护平民的屏障需要我投入所有的力量和精力。你恐怕得独自深入被恶魔占领的大厅了。请去搜索埃索达，寻找幸存者，并摧毁军团入侵点的传送门。"
D.Strings[97275]="你得快点。我不知道自己还能支撑屏障多久！"
D.Strings[97276]="你会为怠慢付出代价！"
D.Strings[97277]="艾利桑德……会知道……这个的……"
D.Strings[97278]="神殿已经被彻底占领了！快碾碎这些恶魔！"
D.Strings[97279]="该战斗了！为了奥丁！"
D.Strings[97280]="守望者曾发誓为这个世界带来正义，但我们分身乏术。这个解决重大危机的荣誉就交给你了。"
D.Strings[97281]="我们不会忘记你今天的帮助，勇士！守望者欠你一份情。"
D.Strings[97282]="你今天让这片土地更安全了。但要小心！威胁一定会卷土重来。"
D.Strings[97283]="我们在这里发现了一个目标，小心点。"
D.Strings[97284]="让他们看看我们是怎么伸张正义的。"
D.Strings[97285]="敌人的数量远超我们。我们需要你的帮助。"
D.Strings[97286]="干得好，简直像个真正的守望者。"
D.Strings[97287]="高效的斩杀，真令人钦佩！"
D.Strings[97288]="我们将在此表彰你的英勇表现。转过身去，面对大家吧。"
D.Strings[97289]="麦格尼在那儿！我们必须救他！"
D.Strings[97290]="幸好我有对付邪能屏障的经验。$n，只要你一声令下，我能就打破它！"
D.Strings[97291]="既然你能控制住局面，我……还有其他客人需要招待。我先失陪了！"
D.Strings[97292]="干掉那个法师！古尔丹要他的脑袋！"
D.Strings[97293]="告诉你的主人，我自己还用得着它呢。"
D.Strings[97294]="我的剑在渴望恶魔之血！"
D.Strings[97295]="前面是谁打得这么激烈？"
D.Strings[97296]="这看起来似乎是个矮人。他还活着吗？"
D.Strings[97297]="显然军团不想让我们听到麦格尼要说的话。"
D.Strings[97298]="麦格尼！再见到你真的太高兴了！但你为什么要离开铁炉堡？为什么要到这儿来？究竟发生了什么——"
D.Strings[97299]="我知道你有很多问题，但还是等会儿再问吧。时间紧迫。她让我带来了一条重要的口信。"
D.Strings[97300]="仪式改变了我的身体，同时也让我可以听到艾泽拉斯的声音。她可不止是一块岩石。她是一名泰坦！"
D.Strings[97301]="我的亲兄弟变成了钻石，然后开始和泰坦交谈了？"
D.Strings[97302]="一名泰坦？这……确实可以解释很多事情。"
D.Strings[97303]="要告诉你们的还有很多。到天文台里来，我让你看看真正的世界。"
D.Strings[97304]="不是需要钥匙才能进去的吗？"
D.Strings[97305]="弟弟……我本人就是钥匙。"
D.Strings[97306]="你最好能说出打扰我的理由。"
D.Strings[97307]="我看到你在酒庄里的所作所为了。你压迫夜之子太久了。准备受死吧，伊尔维尔！"
D.Strings[97308]="入侵者！尝尝我的剑吧！"
D.Strings[97309]="她是自己找死，你也一样！"
D.Strings[97310]="当然了！我都快想起奥尔加隆的样子了。"
D.Strings[97311]="星圣只是在做他自己的工作，就是这样。而最后，我们给他好好上了一课。"
D.Strings[97312]="|c999900005名枯法者：|r把箱子带回去交给塔莉萨。"
D.Strings[97313]="|c9999000010名枯法者：|r把箱子带回去交给塔莉萨。"
D.Strings[97314]="击败上古之神以后，守护者们被赋予了新的使命，为这个世界树立秩序。泰坦们将五个强大的神器交给了他们……创世之柱！"
D.Strings[97315]="完成他们的工作以后，守护者们就将创世之柱封印了起来。但和其他许多神器一样，它们最后也落入了凡人的手中。"
D.Strings[97316]="你的故事听上去很熟悉……我敢肯定我之前听说过这些柱子。"
D.Strings[97317]="是的，卡德加。这些知识一直由提瑞斯法的守护者保管，现在应该还在那里！"
D.Strings[97318]="你必须找到那些神器！组合在一起之后，它们的力量就可以封住军团通往艾泽拉斯的传送门。这样就可以拯救她了！"
D.Strings[97319]="一颗星球指引我前往我自己的图书馆，这种事可不是每天都能遇到的。谢谢你，麦格尼。我马上就到卡拉赞去。$n，你做完这里的事情之后就穿过这个传送门找我吧。"
D.Strings[97320]="那么你呢，哥哥？你会回铁炉堡吗？"
D.Strings[97321]="不，布莱恩。她还给了我……其他的任务。但如果你能留下陪我聊一会儿，我会非常高兴的。"
D.Strings[97322]="当然好了，哥哥！但我想我们的朋友还有别的工作要做。"
D.Strings[97323]="我明白。多保重，$n。我们会再见面的。"
D.Strings[97324]="我得找到其他人！"
D.Strings[97325]="只要我们并肩作战，就会变得更加强大，$n。"
D.Strings[97326]="我们为什么不带几门火炮来？"
D.Strings[97327]="火炮？！你让我们怎么把它们弄上来？"
D.Strings[97328]="我们有狮鹫！"
D.Strings[97329]="你没事吧？！狮鹫能拉动火炮？"
D.Strings[97330]="它可以抓住炮耳把它提起来？"
D.Strings[97331]="这不是抓哪儿的问题。这是体重比的问题！"
D.Strings[97332]="一头五百磅的狮鹫不可能驮得动两千磅的火炮。"
D.Strings[97333]="我们不能留在这里，很快就会有更多恶魔涌来。"
D.Strings[97334]="吉尔尼斯的狮鹫可以！"
D.Strings[97335]="噢，吉尔尼斯的狮鹫或许可以，但这些本地狮鹫不行，这就是我的看法。"
D.Strings[97336]="还有，你在这一带不可能找到吉尔尼斯狮鹫。"
D.Strings[97337]="如果让两头狮鹫一起拉呢？"
D.Strings[97338]="不行，那它们就需要保持在一个水平线上。"
D.Strings[97339]="这好办！用帐篷上的绳子就可以！"
D.Strings[97340]="然后呢，用绳子把它们的导航羽毛系在一起？"
D.Strings[97341]="为什么不呢！？"
D.Strings[97342]="我们最好一起行动！"
D.Strings[97343]="你不用管我。我还得在这里呆一会儿。我能应付的。"
D.Strings[97344]="我得回去了，他们肯定在找我呢。"
D.Strings[97345]="要不是你的话，我恐怕……呃，我也不知道我会怎么样了，可能已经死了吧。"
D.Strings[97346]="你好，大宗师$。我能为你做些什么吗？"
D.Strings[97347]="你休想击败我！"
D.Strings[97348]="艾利桑德会砍掉你们的脑袋！"
D.Strings[97349]="为玛尔迦报仇！"
D.Strings[97350]="法力的滋味！"
D.Strings[97351]="无尽的……饥渴。"
D.Strings[97352]="如果你有兴趣的话，我可以帮你改变这把武器中的力量。我可是铁炉堡这一带最出色的铁匠！\n\n但我要先警告你一声：这可能会使你的武器损失一些力量。"
D.Strings[97353]="我想我得再小心一点儿。谢谢。"
D.Strings[97354]="谢谢！刚才真是好险呐！"
D.Strings[97355]="不要离开暗影，$n。"
D.Strings[97356]="你真是我的大恩人！"
D.Strings[97357]="真高兴能见到你！我还以为自己死定了呢。"
D.Strings[97358]="快跑！谁知道这里还有什么东西！"
D.Strings[97359]="这座桥是属于我的！"
D.Strings[97360]="这小东西是怎么……"
D.Strings[97361]="如果你有机会，一定要加入我们！"
D.Strings[97362]="如果你想的话，我可以帮你改变这对战刃里的力量。\n\n但你别忘了！这种改动是有代价的。"
D.Strings[97363]="你们这些家伙都将被抛弃！"
D.Strings[97364]="你们时日无多了！"
D.Strings[97365]="叛会的间谍必须死！"
D.Strings[97366]="我可以让你匕首中的毒液回流，解锁新的力量。\n\n当然，这是不收费的。不过你要注意，在这个过程中，你的匕首可能会损失一些力量。"
D.Strings[97367]="这个熔炉可以轻易重铸你的武器，改变它的力量。\n\n当然，这会损失一些灵魂，但这是无法避免的。"
D.Strings[97368]="我可以用林地的魔力帮你改变武器中的力量！\n\n不过这个法术不太稳定，所以你可能会有一点损失。"
D.Strings[97369]="我们最近一直有人失踪，还有人看到死人复活，古老的要塞也重新点亮了灯火。有邪恶的力量正在作祟，这一点没有疑问。如果你是来帮忙的，那就沿着这条路去找鲑鱼溪的镇长吧。但是要小心点，镇长身上的压力太大了。"
D.Strings[97370]="我认为这些枯法者可以成为我们的武器。但首先，我们得教会他们在战场上生存。"
D.Strings[97371]="枯法者的生命提高了！"
D.Strings[97372]="解锁枯法狂战士！"
D.Strings[97373]="消灭敌人！"
D.Strings[97374]="碾碎入侵者！"
D.Strings[97375]="为了奥丁！"
D.Strings[97376]="荣耀属于瓦拉加尔！"
D.Strings[97377]="伟大的对手！"
D.Strings[97378]="如果你愿意的话，我可以召唤这片地方的原始之力，为你的武器注入全新的力量。\n\n但你要记住：这种古老的力量很不稳定。在灌注过程中，肯定会有一部分力量回归到荒野中去的。"
D.Strings[97379]="如果我再年轻一点，就可以让这些劣魔领教一下我的利爪和尖牙了。"
D.Strings[97380]="住手！这是命令！你们竟敢忤逆主人？！"
D.Strings[97381]="很高兴有像你这样的英雄在此，$n。在这种情况下，我只能凑一些飞行员去肃清空域了！"
D.Strings[97382]="嘿，$n！在这儿坚持住！我的飞行员会肃清你们头顶的天空的。"
D.Strings[97383]="你肯定是英勇的地面部队的一员吧？干得很好，坚持下去！我已经派出我最好的飞行员去跟他们争夺机场了。"
D.Strings[97384]="我们决不能失去机场！我这就派出我最好的飞行员。保证地面的安全，我们来肃清天空。"
D.Strings[97385]="你肯定就是他们提到的那个$c！我们最好的一个飞行员在空中看到了你。听说你在这儿的表现很不错！保持下去吧。"
D.Strings[97386]="大咒术师阁下，如果你想调整武器中的能量流，获得新的力量，那就尽管吩咐吧，我会帮你的。\n\n但你要注意，我的咒语需要消耗武器中的一小部分力量作为催化剂。"
D.Strings[97387]="$n！扫清他们的地面部队！我的小伙子们正在机场跟他们激战呢！"
D.Strings[97388]="如果你想改变真气在武器上流动的方式，只需要在心中存有念想就可以了。我可以帮助你集中精神达到这样的效果。\n\n记住，$n大师，虽然大多数真气都会沿着新的路径运行……但有些不会这样。自然也是如此。"
D.Strings[97389]="萨拉一直在教我怎么使用祭坛。如果你有需要的话，我可以帮你改变这把武器里的力量。\n\n当然，我还在学习，所以无法完美地转化它。一部分力量可能会散逸到虚空中去。"
D.Strings[97390]="你想要的我已经给你了。现在，别来烦我！"
D.Strings[97391]="嘿，蠢蛋，过来！危机降临啦！"
D.Strings[97392]="现在，枯法者部队在受伤时逃跑的机率降低了！"
D.Strings[97393]="快来，蠢蛋！玉珑有麻烦了。我们快去帮她一把！"
D.Strings[97394]="|TInterface\\Icons\\ability_demonhunter_chaosnova:20|t%s吸取一只蜘蛛来|cFFFF0000|Hspell:218217|h[释放]|h|r它的能量!"
D.Strings[97395]="噢，不妙！快来，蠢蛋，这边走。到处都是绿皮，可我们没时间玩儿了。"
D.Strings[97396]="嘘！嘿，$n，这边！"
D.Strings[97397]="现在，枯法者部队能够更加集中地攻击敌人了！"
D.Strings[97398]="勇士！我带来了格雷迈恩的命令！"
D.Strings[97399]="解锁枯法怒法者！"
D.Strings[97400]="解锁枯法魔力先知！"
D.Strings[97401]="解锁枯法唤星者！"
D.Strings[97402]="我已经从你的眼睛里看出来了——你想给手里那把神器换点儿新花样。\n\n那你就来对地方了，大领主。我可以帮你……但我不敢保证你一点损失都不会有。\n\n恶魔之血很不稳定，这事儿没法保证。"
D.Strings[97403]="我痊愈了！来吧，小家伙。这场入侵该结束了！"
D.Strings[97404]="我们可以用奥丁的熔炉转变你的神器核心，从而按照你的意愿重新分配它的力量。\n\n但是，这需要消耗它的一小部分力量才能实现。"
D.Strings[97405]="你好。我是苍穹要塞的锻造大师海尔加。"
D.Strings[97406]="来吧，考拉，该回家了。"
D.Strings[97407]="谢谢你！我都要累坏了。"
D.Strings[97408]="军团是凭空出现的。附近一定有他们的传送门。我们得找到它！"
D.Strings[97409]="我是死亡猎手莫戈斯，黑夜的猎手，暗影的大师。$b$b你要看看我的货物吗？"
D.Strings[97410]="呃，我们以前见过吗？"
D.Strings[97411]="你在无边无际的死亡深渊游荡过吗？你亲眼见识过熵能的涨落吗？那你肯定见过莫戈斯！$b$b噢，对了。我想这些事你是做过，对吧？我应该再好好想清楚的。$b$b我已经意识到自己不是像其他人那样受到神圣的感召而来到此地的，但我认为你应该需要我的帮助。"
D.Strings[97412]="我好像从来没听说过什么“死亡猎手”。"
D.Strings[97413]="我们的人数不多。事实上是很少。好吧，其实是只有我，还有另外几个人而已。但我们的人数会越来越多的！$b$b我们的任务就是巡视艾泽拉斯和其他国度的昏暗道路，保证无辜者的安全，以及……$b$b好吧，我说实话了。我们只是觉得黑暗游侠很酷，所以想要模仿他们而已。"
D.Strings[97414]="等等，你说什么？"
D.Strings[97415]="谢谢你，$c！没有你我肯定已经完了！"
D.Strings[97416]="我是说，看看那边的维罗娜拉。她就是我的梦想！如此忧郁、如此神秘、如此……黑暗。$b$b你以前跟她合作过吗？感觉怎么样？你们两个有没有……$b$b算了，我还是不要知道比较好。过去的都过去了，我要着眼未来。我跟她的未来。$b$b所以我搞来了这些黑玫瑰，我想送她一束，可又觉得这还足以打动她。我说，你能去跟她聊聊吗？我是说，跟她说说我的事？或者帮我给她带份礼物？"
D.Strings[97417]="我可不想搀和……"
D.Strings[97418]="圣光保佑你！"
D.Strings[97419]="太好了！你真是太棒了！噢，希望维罗娜拉能注意到我！"
D.Strings[97420]="我可以自己回去了。你的英勇行为鼓舞了我的意志！"
D.Strings[97421]="我刚跟莫戈斯聊了聊，他……"
D.Strings[97422]="我该怎么报答你呢，英雄？"
D.Strings[97423]="你看见我兄弟了吗？但愿他已经去先知那里了！"
D.Strings[97424]="你是说那边那个黑衣服的忧郁症白痴吗？那个总是偷瞄我的家伙？$b$b对，我已经注意到他了。他不是第一个迷恋黑暗游侠的凡人。我实在搞不懂这种对于死亡的迷恋。他应该把时间用来追求活生生的恋人，而不是跟一个死人调情。$b$b生者总是在浪费生命。"
D.Strings[97425]="听起来你很怀念你生前的日子。"
D.Strings[97426]="我曾是一个纯洁真诚的少女，一个在银月城军队中服役的年轻游侠，还和我的贵族恋人订了婚，就像做梦一样。$b$b然后阿尔萨斯来了。$b$b那个疯子王子在我深爱的土地上切开了一道漆黑的伤疤，我也在那场战斗中牺牲了。但我至少得到了安息，我是这么认为的。可安息也是暂时的。女妖之王又把我从彼岸拖了回来，诅咒了我的灵魂，迫使我为她效劳。$b$b所以请你谅解，我对莫戈斯这种白痴没什么耐心。他们总是把自己所拥有的一切视为理所当然，并企图在痛苦中找到幸福。"
D.Strings[97427]="他看起来没那么坏。"
D.Strings[97428]="<黑暗游侠叹了口气。>$b$b我想他还是有点魅力的。他只是克制不住自己的无知。$b$b可他必须明白，我的心已经无法感受爱情或是幸福了，我们也不可能……发生他想要的亲密关系。我是个亡灵，是具腐尸，等着我的只有地狱的深渊。$b$b拜托了，如果你是为他好的话，那现在就让他死了这条心吧，以免他日后痛苦。$b$b<维罗娜拉顿了顿，然后拿起了一支黑玫瑰，轻抚着它的花瓣。>"
D.Strings[97429]="你想要招募元素吗？"
D.Strings[97430]="维罗娜拉怎么说？她有这个意思吗？她愿意跟我出去吃顿晚餐吗？我很擅长烤野猪腰肉。"
D.Strings[97431]="抱歉，莫戈斯。她拒绝了。"
D.Strings[97432]="真的？我还以为她会……$b$b噢，我明白了。我早就知道她对你有意思了。我理解。勇敢的英雄，隐秘通途的领袖……像我这种家伙怎么争得过你呢？$b$b无论如何，还是谢谢你，$n。我不会介意的，真的！$b$b话说，你愿意帮我去问问黑暗游侠阿莉娜吗？她是那么迷人……"
D.Strings[97433]="好吧好吧，我知道了。你要是对我的货物有兴趣的话，随时告诉我！"
D.Strings[97434]="我会婉转地转告他的。"
D.Strings[97435]="麦迪文之书终于归我们了！如果你肯让我杀掉那些恋尸癖，一定能节省不少时间！"
D.Strings[97436]="别费神了，亲爱的！让他们烂死在墓穴里吧。燃烧军团的烈焰就快到了。"
D.Strings[97437]="哼！等等……有点不对劲！"
D.Strings[97438]="呃，我倒是可以跟她聊聊。"
D.Strings[97439]="卡里杜斯来帮忙了！"
D.Strings[97440]="<将仪式和权杖的事告诉卡里杜斯。>"
D.Strings[97441]="古尔丹会用权杖、眼球和书把传送门变得更大。会有更多恶魔涌进来！朋友肯定不想那样吧。"
D.Strings[97442]="又来了新的劣魔？！洗劫了我的家园还不满足？！"
D.Strings[97443]="这下子他们应该躲得远远的了……搬到森林里的小屋子，果然是寻找“安宁”的好办法。"
D.Strings[97444]="朋友去骗走古尔丹的权杖怎么样？然后破坏了仪式就跑！哈哈！这一定管用，朋友！"
D.Strings[97445]="多亏了你，我们终于修复了雷霆之怒，并释放了桑德兰的灵魂。"
D.Strings[97446]="仰望天空，见证风元素领主……桑德兰的重生吧！"
D.Strings[97447]="呃……噢，我的头！"
D.Strings[97448]="石步……我不会让你白白牺牲的！"
D.Strings[97449]="想要打败驯犬者，就要把他引到我们选好的地方来。"
D.Strings[97450]="我喜欢收集草药、花朵和植物。我的足迹踏遍了破碎群岛，还进入了翡翠梦境。你需要什么吗？"
D.Strings[97451]="玛沃伦丝，让我们离开这儿。"
D.Strings[97452]="好的，亲爱的。"
D.Strings[97453]="鱼儿今天肯定会咬钩的！"
D.Strings[97454]="你有备用的筏子吗？我想借一艘。"
D.Strings[97455]="在荒野中生活时，你永远不知道下一刻会发生什么事，但一个好猎人可以依靠技巧和本能生存下去。"
D.Strings[97456]="你需要食物才能在荒野中活下来。$B$B野猪肉在明火上烹制以后非常美味，但绝不能生吃。$B$B这一带还生长着许多浆果，有些是可以食用的，但有些吃了以后可能会造成一些小麻烦。通常可以根据它们的气味来分辨哪些是可以安全食用的。散发着甜香味儿的浆果基本都不安全。$B$B木柴可以从枯死的树上获得。你可以通过干枯发紫的树叶来分辨它们。$B$B你准备好了吗？"
D.Strings[97457]="我也来！"
D.Strings[97458]="多亏你的英勇，瓦尔莎拉这片古老的土地终于开始康复了。"
D.Strings[97459]="当然！你只要到水面上去，就能大丰收了！"
D.Strings[97460]="虽然我常与部落不合，但你们拯救瓦尔莎拉时表现出的勇气毋庸置疑。"
D.Strings[97461]="干得好，圣光的英雄！现在，我们会守住这片区域，并为你提供帮助的！"
D.Strings[97462]="玛法里奥！我的爱人在哪里？"
D.Strings[97463]="我还会派出海达克西斯援助大地之环。他是我最伟大的勇士，能助你们一臂之力。"
D.Strings[97464]="艾泽拉斯之心就位于这个世界元素力量的汇聚点上。全艾泽拉斯，没有比这里与元素联系更紧密的地方了。"
D.Strings[97465]="我们必须在被发现前尽快救出库尔迪拉。"
D.Strings[97466]="我们去救出库尔迪拉，然后离开这地方。"
D.Strings[97467]="释放这个构造体。"
D.Strings[97468]="你成功制服了这个不听话的构造体。"
D.Strings[97469]="在那之前，你得小心点。城里已经戒严，卫兵会当场格杀你。"
D.Strings[97470]="牢房的大门打开了，你感觉一股巨大的能量从门内散发出来。"
D.Strings[97471]="哨兵的能量逐渐积聚，你感到脖子上的汗毛都因静电而竖起了。"
D.Strings[97472]="哨兵释放了自己的能量。你听到了东西落下的微弱呼啸声。"
D.Strings[97473]="|TInterface\\Icons\\spell_druid_massentanglement_nightmare:20|t伊格诺斯之眼开始施放|cFFFF0000|Hspell:218415|h[死亡之花]|h|r！"
D.Strings[97474]="我会开始把我的精华导入这个容器里。"
D.Strings[97475]="引导完成之后，哈卡就会被容器中的魔力吸引过来。"
D.Strings[97476]="只要我的精华还被封在容器中，我会很虚弱，无法协助你。"
D.Strings[97477]="小心，着火时别烧焦了嫩芽！"
D.Strings[97478]="害虫应得的下场！"
D.Strings[97479]="你们再愚钝，也应该明白什么是力量！"
D.Strings[97480]="为光明之死而愤怒吧！"
D.Strings[97481]="随着光明……一同去死吧！"
D.Strings[97482]="自然会滋养真正欣赏它的人。"
D.Strings[97483]="你将成为一颗很好的力量种子！"
D.Strings[97484]="夜幕降临！"
D.Strings[97485]="阳光温暖了我的鲜花……但它将烧焦你们的骨头！"
D.Strings[97486]="让高温烤焦你们，杂草！"
D.Strings[97487]="现在，你将面对生命的三大化身，而你的生命即将终结！"
D.Strings[97488]="你能抵抗创造生命的三大原初之力吗？"
D.Strings[97489]="苏拉玛的美丽源自我的鲜花！只有我才能将微妙的魔法织入自然的伟大轮回。"
D.Strings[97490]="你的尸体将成为很好的肥料！"
D.Strings[97491]="蛆虫们又有食物了！"
D.Strings[97492]="你们竟敢在我完美的花园里捣乱！"
D.Strings[97493]="看来我得修剪一下枝叶了！"
D.Strings[97494]="死亡只是伟大轮回的一部分。"
D.Strings[97495]="我该把这些肥料放到哪儿去呢？"
D.Strings[97496]="苦涩的……收获……"
D.Strings[97497]="谁来……给我的植物……浇水……"
D.Strings[97498]="我的游侠已整装待发，随时都能出战！"
D.Strings[97499]="我的弓箭手已经蓄势待发，准备射杀任何胆敢进入围墙的恶魔。"
D.Strings[97500]="管用吗？"
D.Strings[97501]="哈卡中计了吗？"
D.Strings[97502]="发射照明弹，我们看看。"
D.Strings[97503]="毁灭之锤可能在任何地方。我们得分头行动。"
D.Strings[97504]="我去跟大地神殿的萨满谈谈。"
D.Strings[97505]="那我去巨石之炉问问土灵有什么发现。"
D.Strings[97506]="萨满，你去找石母。小心点——她很暴躁。"
D.Strings[97507]="一旦有了发现，我们就在塞拉赞恩的王座碰头。祝你们两个好运！"
D.Strings[97508]="恶魔来了！哨兵们，准备拔剑！"
D.Strings[97509]="我有个提议。我们下面有很多优质的蟹肉……我是说，它们还是活的，但是你应该懂我的意思。$b$b我这里有一些浮标，你可以用来把下面的螃蟹运到水面上。你下水去把浮标绑在蟹笼上，我就把浮到水上的东西抓住。$b$b你帮我这个忙的话，我会给你丰厚的奖赏。你有什么想法？"
D.Strings[97510]="我准备好了，把浮标给我。"
D.Strings[97511]="在下面时小心点。那些螃蟹附近还有其他生物。你不会想遇见它们的。$b$b你知道吗，要不是跟我父亲一起下了海，我也能成为和你一样的$c。"
D.Strings[97512]="先祖……原谅我……"
D.Strings[97513]="你做到了肯瑞托做不到的事。驯犬者的死将会对燃烧军团的力量造成沉重打击。"
D.Strings[97514]="我们走吧，和朋友们一起去庆祝胜利。"
D.Strings[97515]="别激动，特尔拉斯。迟早会真相大白的。啊，来了个凡人。有麻烦的地方就有他们，对吧？"
D.Strings[97516]="有什么东西在驱使着穴居人。也许跟你们丢失的锤子有关。拜托，去解决他们，好吗？"
D.Strings[97517]="噢，我的小宝贝！小宝贝！巢穴没事了。回我的王座来吧。我知道你的战锤在哪儿——我的石龙也能来帮忙了。"
D.Strings[97518]="我的凡人新宠来了。你是石母真正的朋友，萨满。"
D.Strings[97519]="穴居人酋长知道你的战锤在哪儿，萨满。去拷问他吧！你可以调遣我的石龙。"
D.Strings[97520]="这应该可以在下面帮上你的忙。但它持续不了多久，所以动作快点。"
D.Strings[97521]="这个哨兵散发着奥术能量的嗡鸣声，看不懂的精灵符文在透镜表面舞动着，发出淡淡的光。它的一只爪子也发出了淡淡的光。"
D.Strings[97522]="第二只爪子也开始闪烁，但是哨兵却没有激活，仿佛在等待着你输入什么。"
D.Strings[97523]="这个哨兵看起来没有激活，但它的一只爪子断断续续地闪动着。"
D.Strings[97524]="序列完成，这个哨兵的透镜激活了，符文来回滚动着。不过你完全不明白这是怎么回事。"
D.Strings[97525]="地表的纷争与此地无关，萨满。希望你能妥善解决这件事。"
D.Strings[97526]="库尔迪拉就被关在附近！我们得快一点！"
D.Strings[97527]="这就是赛拉提到的哨兵。跟她所说的一样，它的爪子闪着红光。接下来，你只需要启动能量转移序列，然后努力活下来就行。"
D.Strings[97528]="奥术能量令哨兵活跃了起来。它的双眼不停地扫描着周围的环境。"
D.Strings[97529]="哨兵的显示器似乎相对平静了下来。但是下方还有个危险指示器……"
D.Strings[97530]="你在这个哨兵的显示器上，看到一个小小的标记，它代表着有一个生物被困了在升降井的顶部。哨兵的一只爪子疯狂地闪着红光。"
D.Strings[97531]="卡里杜斯在此！议会跑了！哈哈！"
D.Strings[97532]="新来的！你们来得正是时候！我们已经包围他们了！"
D.Strings[97533]="这个畜生自以为厉害！让他们看看我们是怎么招待不速之客的吧。"
D.Strings[97534]="啊，又一个勇敢的冒险者。让他们看看你的力量吧！"
D.Strings[97535]="别放松！干掉了这一个，还有很多土地在等着我们去收复呢！"
D.Strings[97536]="拿出你们全部的本事来！"
D.Strings[97537]="坚持住！又有援军来了！"
D.Strings[97538]="援军马上就到！我们要寸土不让！"
D.Strings[97539]="你们又成功了！打得好，各位。可我们还不到庆祝的时候。还有很多人需要我们的帮助呢。"
D.Strings[97540]="你已离开了战斗区域。你即将被传送回战场。"
D.Strings[97541]="在这儿！我们从火上跳过去！"
D.Strings[97542]="霍迪尔被孤立了。不赶快行动，敌人很快会包围他的。"
D.Strings[97543]="霍迪尔的房间就在门后面。我们要打开它。"
D.Strings[97544]="趴下！"
D.Strings[97545]="凯丽娅……不……"
D.Strings[97546]="瓦雷迪斯……不！"
D.Strings[97547]="我们开始酿造吧！"
D.Strings[97548]="我们就快完成最后的酿造了，可我们被敌人包围了。$B$B帮我挡住袭击者，让艾吉拉完成风暴蜜酒！"
D.Strings[97549]="很好！显然，让我们给他们看看武僧的力量吧！"
D.Strings[97550]="我说了不要近程射击了！"
D.Strings[97551]="烧得好，小鬼。烧死那些纳迦。"
D.Strings[97552]="小心！又有敌人过来了！"
D.Strings[97553]="快，大宗师，趁我们还有时间。喝下风暴蜜酒！"
D.Strings[97554]="你们争取了足够的时间。蜜酒酿成了！"
D.Strings[97555]="我听到脚步声了。不要放松警惕！"
D.Strings[97556]="站稳了，大宗师！不惜一切代价保护蜜酒！"
D.Strings[97557]="谢谢你，$n。我不会让你失望的。"
D.Strings[97558]="你的凡人盟友帮不了你，小蛇！你死到临头了！"
D.Strings[97559]="你们觉得那种愚蠢的合剂能救得了你们吗？出来面对我。我要摧毁剩余的残寺派！"
D.Strings[97560]="够了。你死到临头了，武僧！"
D.Strings[97561]="告诉你派去的人，加尔顿越早拿到他的恶魔小玩意儿，我们就能越快得到新的灰舌战士。"
D.Strings[97562]="嘿，加尔顿，新兵准备好了吗？"
D.Strings[97563]="那真是洛拉姆斯吗？如果真是他，我们该救他还是杀了他？"
D.Strings[97564]="小心点，$n。他在下头的一大半时间都在用恶魔语威胁我们。"
D.Strings[97565]="你要让灰舌死誓的战士们明白，黑暗神殿的其他破碎者都不可靠。"
D.Strings[97566]="我会竭尽全力确保我们战胜燃烧军团。你也不能松懈。"
D.Strings[97567]="我拥有阿卡玛的所有知识，甚至更多。我很期待能与你一起摧毁军团。"
D.Strings[97568]="你怎么才说？我该是你的第一个勇士才对。"
D.Strings[97569]="阿里亚娜是我们最好的训练师。天知道，没准她还能教会他们变形？"
D.Strings[97570]="食尸鬼……我就知道！"
D.Strings[97571]="别让他们抵达营地！他们摧毁了采石场，这已经够糟了！"
D.Strings[97572]="坚持住！决不能再让他们前进一步！"
D.Strings[97573]="看来大家都赶来帮忙了！我就算是死，也要夺回我的采石场！"
D.Strings[97574]="又来人了！这下我们真的有希望扫平他们了！"
D.Strings[97575]="看来有人把消息传开了！又来了一个战士！"
D.Strings[97576]="又有援军来了！往前推！我们要夺回采石场！"
D.Strings[97577]="再坚持一会儿！援军马上就到了！"
D.Strings[97578]="再抵挡他们一会儿！"
D.Strings[97579]="就快了！再拦住他们一会儿！"
D.Strings[97580]="干得好，诸位！你们拯救了我的采石场，但我们看来还有很多事要做。看看你们还能帮什么忙吧。还有，小心点儿！他们无处不在！"
D.Strings[97581]="这是部落的地盘，可跟我在一起，这里就不会欢迎你。"
D.Strings[97582]="真是场精彩的战斗！"
D.Strings[97583]="很高兴你找到了我们，$n！"
D.Strings[97584]="前面还有遇到麻烦的人。我们继续前进吧！"
D.Strings[97585]="我的三个姐姐吊死在那棵树下，\n她们被指控的罪孽全是虚假。\n最小的妹妹成功逃离，\n正当绳索套上她们的头颈。\n老拉文凯斯是元凶之一，\n这个咒语能让你为我们澄清污名。"
D.Strings[97586]="我们终于来救你了，我的兄弟。"
D.Strings[97587]="没错，是我。"
D.Strings[97588]="趁卫兵还没过来，我们得快一点。"
D.Strings[97589]="萨萨里安……真的是你吗？"
D.Strings[97590]="好久不见……"
D.Strings[97591]="谢谢你。那么激烈的战斗之后，我得好好歇上一会儿。"
D.Strings[97592]="诅咒解除了，我终于可以安息了。但英雄，请记住，不要勉强人做不愿意做的事。"
D.Strings[97593]="啊，谢谢你！我得去处理伤口了。"
D.Strings[97594]="我觉得自己不是战斗的料。我还是等这里安全一点了再回来吧。"
D.Strings[97595]="噢！小心！我的伤口还没愈合呢。"
D.Strings[97596]="我又能站起来了，可我的力气还没恢复。"
D.Strings[97597]="谢谢你！真没想到会有人来救我们！你是特意赶来帮忙的吗？"
D.Strings[97598]="我还有点虚弱。给我一点恢复的时间。"
D.Strings[97599]="这种饥渴何时才能停止？"
D.Strings[97600]="我已经喝不下了……"
D.Strings[97601]="喂！有人吗？"
D.Strings[97602]="这种饥渴简直无法忍受……"
D.Strings[97603]="好痛苦！快让它停下！"
D.Strings[97604]="英雄们，你们去对付克里提斯。我来挡住他长翅膀的同伙。"
D.Strings[97605]="虽然不是滋味，但与守望者合作能让我们各取所需。更大的牺牲我们都付出过。"
D.Strings[97606]="这边就快搞定了，我马上就得去搞下一台了。"
D.Strings[97607]="但愿这能管用……我的备用零件不多了。"
D.Strings[97608]="再折腾几下，它就能焕然一新了。"
D.Strings[97609]="要我马上修好这玩意儿也太过分了……这简直就是修理工的噩梦！"
D.Strings[97610]="早知道我就带另一个扳手过来了。这工作需要一点时间。"
D.Strings[97611]="哈哈！好吧！凡人，来送死吧！"
D.Strings[97612]="愿圣光拥你入怀，$g兄弟:姐妹;。"
D.Strings[97613]="不要担忧烦恼。我将在圣光中为你准备一席之地。"
D.Strings[97614]="圣光注视着你，我逝去的$g兄弟:姐妹;。"
D.Strings[97615]="愿你的伤口得到净化，在圣光中安然前行。"
D.Strings[97616]="这改变不了什么……这世界……必将……化为火海！"
D.Strings[97617]="我才不在乎赛拉怎么说呢……如果你需要勇士的帮助，他们就会出现。"
D.Strings[97618]="小心。她最后一次出现是在勇者之门附近。那鬼地方。"
D.Strings[97619]="你很懂得怎么跟这些生物战斗，可这只是个开始。"
D.Strings[97620]="这就是福枬，拿着它。愿它能帮你熬过黑暗的岁月。"
D.Strings[97621]="快，恶魔猎手。我不喜欢那边那堆篝火的样子。"
D.Strings[97622]="带我到军团入侵的前线去。"
D.Strings[97623]="太好了，大宗师来了！这些恶魔没机会了！"
D.Strings[97624]="这里交给我们吧。大宗师，去南方的寺院找陈和艾吉拉。他们更需要你的帮助！"
D.Strings[97625]="|TInterface\\Icons\\inv_bannerpvp_02.blp:20|t你获得了|cFFFF0000|Hspell:185265|h[为了联盟]|h|r效果！"
D.Strings[97626]="我很荣幸，$n。在踏上征程时，我可没想到自己会被选为你的勇士。我不会让你失望的。"
D.Strings[97627]="身为伊利丹的仆从，我一直都觉得很荣幸。可正式加入伊利达雷……别看，$n，我快哭了。"
D.Strings[97628]="我向你保证，$n，我会用我所有的力量，以及夺魂之镰的所有力量去追查凯丽娅和瓦雷迪斯的下落。"
D.Strings[97629]="我们是不会轻易投降的！"
D.Strings[97630]="他们终于找到我们了……"
D.Strings[97631]="燃烧军团非常残酷。"
D.Strings[97632]="你说我的家人会没事吗？我没有看见他们。"
D.Strings[97633]="如果先知的屏障崩溃，我们就全完了！"
D.Strings[97634]="卡拉诺斯南部的空中发现巨型恶魔！它朝我们冲过来了！"
D.Strings[97635]="空中发现巨型恶魔！它朝卡拉诺斯冲过来了！快派人支援！"
D.Strings[97636]="需要武器锻造师的帮助吗，$n？把你的武器给我，我来看看能做点什么。"
D.Strings[97637]="<交出你的武器。>"
D.Strings[97638]="焕然一新。出去时小心点，$n。"
D.Strings[97639]="夺魂之镰告诉我，它很嫉妒你收获了那么多强大的灵魂。"
D.Strings[97640]="全力撞击先知的屏障，仆从们！它很快就会崩溃，德莱尼的希望也一样！"
D.Strings[97641]="我们需要其他指挥中心的几个零件。然后，邪能之槌号就可以前往尼斯卡拉了。"
D.Strings[97642]="听起来不妙。邪能之槌号的南边好像有什么非常巨大的东西。"
D.Strings[97643]="你早该把阿莱利和杰斯招募为勇士了。他们有这个资格。"
D.Strings[97644]="邪恶的怪物！你们已经偷走了我的生命！还想要从我这里夺走什么？"
D.Strings[97645]="我们并肩战斗了那么久。当然接受！"
D.Strings[97646]="我随时为你和伊利达雷而战。接下来怎么办，$n？"
D.Strings[97647]="你计划如何升级职业大厅？"
D.Strings[97648]="你想找个能干活儿的人吗？我就是。"
D.Strings[97649]="<埃奥瑟拉召唤她的幼龙攻击针石熔渣场！>"
D.Strings[97650]="伊利达雷！伊利丹的仆从！听我说！"
D.Strings[97651]="我们夺回了萨格里特钥石。我们击退了基尔加丹，并侵入了军团的世界。我们还战胜了宿敌，凯丽娅和瓦雷迪斯·邪魂。"
D.Strings[97652]="鉴于这一系列的伟大胜利，我们要向$n授予最高荣誉，屠魔者的头衔。"
D.Strings[97653]="|TInterface\\Icons\\Ability_Druid_ChallangingRoar:20|t%s正在施放|cFFFF0000|Hspell:200580|h[疯狂怒吼]|h|r。快停止施法！"
D.Strings[97654]="一个哨兵开始发出低沉的警报声。"
D.Strings[97655]="一个哨兵不断发出非常紧急的警报。"
D.Strings[97656]="恶魔死去的同时，你听到有个更大的透镜哨兵从房间的入口处升起。"
D.Strings[97657]="最后一个透镜也沉了下去，你听到由于能量激增而产生的轻柔嗡鸣声在房间中回荡。"
D.Strings[97658]="哨兵从牢房中吸取了奇怪的能量，房间内的安保措施关闭了。"
D.Strings[97659]="随着魔像的倒下，发出警报声的哨兵也关闭了。"
D.Strings[97660]="哨兵开始散发出能量的嗡鸣声。"
D.Strings[97661]="|TInterface\\Icons\\SPELL_DRUID_BEARHUG:20|t%s正在施放|cFFFF0000|Hspell:198376|h[原始狂暴]|h|r！"
D.Strings[97662]="地窟里充斥着魔法护卫。关押恶魔格雷泽的监狱里也有这样的系统。"
D.Strings[97663]="很好，这应该能保持地窟正常封闭，直到我们夺回地窟为止。现在，去找到叛徒并干掉她！"
D.Strings[97664]="其他的守望者告诉我，我们地窟的地下三层受到了严重破坏，某些系统很快就会失去能量。"
D.Strings[97665]="我想要你进去，完成能量转移的工作。这任务本身很容易，但那里的守卫措施很森严。"
D.Strings[97666]="敏锐并不是守望者米拉娜的特点。"
D.Strings[97667]="干得好。现在，去找到叛徒并击败她。"
D.Strings[97668]="身为军需官，我的职责就是分发月刃，并教导守望者使用它们。"
D.Strings[97669]="我们的人手太少，需要再收集一些武器。进入守望者地窟，找回我们阵亡姐妹的月刃。"
D.Strings[97670]="我一看这些月刃，就知道是哪位守望者的。每一把都是我亲自分发和训练使用的。"
D.Strings[97671]="我怀疑有些魔誓恶魔猎手并未逃离监狱。我通常都不在乎囚犯的死活，但潜伏在黑暗中的恶魔猎手太危险了，不能放任不管。"
D.Strings[97672]="设法进入恶魔猎手区，并解决潜伏在阴影中的一切吧。"
D.Strings[97673]="这生物和邪能物质呆在一起，会变成什么样？想想我都会发抖。"
D.Strings[97674]="多亏了你，否则我们还不知道。现在，找到叛徒，让她付出代价。"
D.Strings[97675]="我接到报告说，有个特别棘手的囚犯差点逃跑了。幸好地窟的一个安全措施困住了她。"
D.Strings[97676]="力场当然没法坚持太久。快进入地窟，把那头怪兽彻底解决掉。"
D.Strings[97677]="打得好。现在，把叛徒解决掉。"
D.Strings[97678]="燃烧军团夺走了许多珍贵之物。"
D.Strings[97679]="很多人还在为死去的亲友悲伤，还在怀念往日的和平。然而最黑暗的时刻恐怕尚未来到。"
D.Strings[97680]="但那不是今天！"
D.Strings[97681]="今天，我们要欢庆一个新团体的诞生！今天，我们要为友谊和团结干杯！"
D.Strings[97682]="在大宗师的领导下，每一天都将是新的黎明！"
D.Strings[97683]="我们永不放弃，今天的战斗是为了更好的明天！"
D.Strings[97684]="向残寺派致敬！"
D.Strings[97685]="为残寺派干杯！美猴王最喜欢这个地方了！"
D.Strings[97686]="对，对！靠近点，朋友！$B$B我看到你手里有些好东西！朋友需要些什么呢？来几件小饰品怎么样？"
D.Strings[97687]="那好吧，你想要什么？"
D.Strings[97688]="要驯服艾露尼斯可不容易。拿上这些卷轴。艾格文曾用它们压制住了艾露尼斯，或许你也可以。"
D.Strings[97689]="您的意志实现了，主人！"
D.Strings[97690]="别害怕，$c，我们会为破碎海滩的亡魂复仇的。当那一天来临时，我会与你并肩战斗。"
D.Strings[97691]="我想看看你的货物。"
D.Strings[97692]="你在干嘛？酒都煮过头了！全毁了！看来我们得从头开始了！"
D.Strings[97693]="其他德莱尼为什么想要伤害我们？"
D.Strings[97694]="我要爸爸！"
D.Strings[97695]="你见过我妈妈没有？"
D.Strings[97696]="我真是吓坏了！那些发火的德莱尼人谁都不放过！"
D.Strings[97697]="现在回去安全吗？"
D.Strings[97698]="谢谢你，$g先生:女士;。"
D.Strings[97699]="击败恶魔，然后完成恢复地窟能量的启动序列。"
D.Strings[97700]="哦……我对这个序列表示抱歉。守望者玛拉丝就喜欢谜题。"
D.Strings[97701]="如果四骑士想要对抗燃烧军团，他们就需要一个领袖。"
D.Strings[97702]="他要拥有不容质疑的强大灵魂，以及对世界的忠诚。"
D.Strings[97703]="因此，我将你们带到这里，为我们寻找一位领袖。"
D.Strings[97704]="这些墙的后面埋葬着提里奥·弗丁的遗体，他是史上最伟大的英雄之一。"
D.Strings[97705]="白银之手不会乖乖把人交出来的。所以，我们得来硬的！"
D.Strings[97706]="我们别无选择。"
D.Strings[97707]="死亡领主，下令吧，我们马上行动。"
D.Strings[97708]="石母派来了她的巨龙。快躲起来！"
D.Strings[97709]="她派了一个地表住民来帮她干脏活儿。干掉那个萨满！"
D.Strings[97710]="燃烧军团占领了这片土地，萨满。穴居人要是不听话就得死。我们很清楚这一点。"
D.Strings[97711]="出去，滚出去！我们什么都不会告诉你的！"
D.Strings[97712]="我们看到那把锤子从天而降。我们知道它在哪儿。"
D.Strings[97713]="我们把它的下落告诉了一个恶魔。他的名字叫格斯逊。"
D.Strings[97714]="你已经太迟了，太迟了……在碎岩之渊……燃烧军团已经得到它了……"
D.Strings[97715]="你好，$n。我能为你做点什么吗？比如一份最新的侦察报告，或是燃烧军团在艾泽拉斯的行动报告？"
D.Strings[97716]="我们得救了！所有人都去圣光穹顶！"
D.Strings[97717]="埃索达的英雄为我们打开了一条通道！"
D.Strings[97718]="是时候了，兄弟姐妹们！去圣光穹顶！"
D.Strings[97719]="燃烧军团会让我们更加强大的！"
D.Strings[97720]="穴居人必将再次崛起！"
D.Strings[97721]="我们是燃烧军团的仆人！"
D.Strings[97722]="我没救了……我只感觉……"
D.Strings[97723]="$n，很高兴考瓦斯能这么快找到你。"
D.Strings[97724]="$n，我们需要你帮忙做个战略决策。"
D.Strings[97725]="仿佛就在昨天，我们就站在这个地方，准备以巫妖王的名义摧毁圣光。$b$b而今天，我们站在这里，却不是为了毁灭……而是为了拯救这个世界免遭毁灭。"
D.Strings[97726]="抓住锁链，帮帮我！"
D.Strings[97727]="坚持住，托里姆！这些恶魔不是我们的对手！"
D.Strings[97728]="麦格尼打了个响指。"
D.Strings[97729]="那就让我们来测试一下你的历史知识吧！暗夜精灵看守者的最高层叫什么？"
D.Strings[97730]="游侠将军。"
D.Strings[97731]="守护者。"
D.Strings[97732]="守望者。"
D.Strings[97733]="哨兵。"
D.Strings[97734]="那就让我们来测试一下你的历史知识吧！钢鬃和刺背是哪个种族的两大对立部族？"
D.Strings[97735]="野猪人。"
D.Strings[97736]="豺狼人。"
D.Strings[97737]="刃牙虎人。"
D.Strings[97738]="鹰身人。"
D.Strings[97739]="那就让我们来测试一下你的历史知识吧！下面哪个是伊利丹的纳迦副官以及艾萨拉女王的前侍女？"
D.Strings[97740]="纳兹夏尔。"
D.Strings[97741]="瓦丝琪。"
D.Strings[97742]="扎哈拉。"
D.Strings[97743]="瓦丽丝琪。"
D.Strings[97744]="那就让我们来测试一下你的历史知识吧！以下哪种潘达利亚生物是包括猜忌、绝望和愤怒在内的各类负面情绪的化身？"
D.Strings[97745]="螳螂妖。"
D.Strings[97746]="兔妖。"
D.Strings[97747]="猢狲。"
D.Strings[97748]="煞魔。"
D.Strings[97749]="那就让我们来测试一下你的历史知识吧！在屈服于魔瘾之前，失心者曾属于哪个种族？"
D.Strings[97750]="血精灵。"
D.Strings[97751]="人类。"
D.Strings[97752]="暗夜精灵。"
D.Strings[97753]="被遗忘者。"
D.Strings[97754]="那就让我们来测试一下你的历史知识吧！维克多·奈法里奥斯勋爵是以下哪条巨龙的人类伪装？"
D.Strings[97755]="萨贝里安。"
D.Strings[97756]="伊萨里奥斯。"
D.Strings[97757]="奈法利安。"
D.Strings[97758]="萨菲隆。"
D.Strings[97759]="那就让我们来测试一下你的历史知识吧！无头骑士的名言：“湮远而艰辛的探索到此为止……”的下半句是？"
D.Strings[97760]="“真正的强者将由命运择示！”"
D.Strings[97761]="“真正的正当者将由命运择示！”"
D.Strings[97762]="“真正的正义者将由命运择示！”"
D.Strings[97763]="不要让任何东西挡住你前进的步伐！"
D.Strings[97764]="“真正的愉悦者将由命运择示！”"
D.Strings[97765]="那就让我们来测试一下你的历史知识吧！土地精最珍视的私人财产是什么？"
D.Strings[97766]="背包。"
D.Strings[97767]="牦牛。"
D.Strings[97768]="幸运符。"
D.Strings[97769]="霉运符。"
D.Strings[97770]="那就让我们来测试一下你的历史知识吧！血羽、风怒和巫翼都是哪个种族的生物？"
D.Strings[97771]="鸦人。"
D.Strings[97772]="卡利鸟。"
D.Strings[97773]="角鹰兽。"
D.Strings[97774]="那就让我们来测试一下你的历史知识吧！环绕时光之穴的沙漠叫做？"
D.Strings[97775]="奥丹姆。"
D.Strings[97776]="塔纳利斯。"
D.Strings[97777]="希利苏斯。"
D.Strings[97778]="凄凉之地。"
D.Strings[97779]="那就让我们来测试一下你的历史知识吧！地精将以下哪片区域改造成了部落标志的形状？"
D.Strings[97780]="艾萨拉。"
D.Strings[97781]="科赞。"
D.Strings[97782]="杜隆塔尔。"
D.Strings[97783]="莫高雷。"
D.Strings[97784]="那就让我们来测试一下你的历史知识吧！以下哪个不是兽人部族？"
D.Strings[97785]="霜狼。"
D.Strings[97786]="战歌。"
D.Strings[97787]="龙喉。"
D.Strings[97788]="那就让我们来测试一下你的历史知识吧！看守伊利丹·怒风的狱卒是以下哪位暗夜精灵？"
D.Strings[97789]="加洛德·影歌。"
D.Strings[97790]="玛法里奥·怒风。"
D.Strings[97791]="玛维·影歌。"
D.Strings[97792]="卡力菲克司。"
D.Strings[97793]="那就让我们来测试一下你的历史知识吧！以仁慈著称，却支持了死亡之翼的前暴风城精神领袖叫什么名字？"
D.Strings[97794]="本尼迪塔斯。"
D.Strings[97795]="纯洁的凯瑟琳。"
D.Strings[97796]="格雷森·沙东布瑞克。"
D.Strings[97797]="虔诚的亚瑟。"
D.Strings[97798]="那就让我们来测试一下你的历史知识吧！克鲁什、摩什和爵德都是什么类型的生物？"
D.Strings[97799]="猩猩。"
D.Strings[97800]="暴龙。"
D.Strings[97801]="巨人。"
D.Strings[97802]="食人魔。"
D.Strings[97803]="那就让我们来测试一下你的历史知识吧！连接阿拉希高地和湿地的大桥叫什么名字？"
D.Strings[97804]="断桥。"
D.Strings[97805]="晨之桥。"
D.Strings[97806]="萨弗隆大桥。"
D.Strings[97807]="萨多尔大桥。"
D.Strings[97808]="作为一个小个子，你很勇猛，矮人。这里怎么了？"
D.Strings[97809]="先打了再说！"
D.Strings[97810]="那就让我们来测试一下你的历史知识吧！在大灾变之前，我们可以在哪里找到曼科里克妻子的遗体？"
D.Strings[97811]="千针石林。"
D.Strings[97812]="贫瘠之地。"
D.Strings[97813]="那就让我们来测试一下你的历史知识吧！吉安娜在肯瑞托的导师是谁？"
D.Strings[97814]="大法师安东尼达斯。"
D.Strings[97815]="大法师卡德加。"
D.Strings[97816]="大法师茉德拉。"
D.Strings[97817]="大法师克尔苏加德。"
D.Strings[97818]="那就让我们来测试一下你的历史知识吧！达拉然最早位于东部王国的哪里？"
D.Strings[97819]="阿拉希高地。"
