D.Strings[97821]="希尔斯布莱德丘陵。"
D.Strings[97822]="提瑞斯法林地。"
D.Strings[97823]="那就让我们来测试一下你的历史知识吧！阿尔萨斯被击败后，谁成为了巫妖王？"
D.Strings[97824]="提里奥·弗丁。"
