D.Strings[97826]="达里安·莫格莱尼。"
D.Strings[97827]="泰瑞纳斯·米奈希尔二世。"
D.Strings[97828]="那就让我们来测试一下你的历史知识吧！以下哪位不是最初创立白银之手的五位圣骑士之一？"
D.Strings[97829]="乌瑟尔。"
D.Strings[97830]="亚历山德罗斯。"
D.Strings[97831]="格文拉德。"
D.Strings[97832]="赛丹。"
D.Strings[97833]="那就让我们来测试一下你的历史知识吧！以下哪位深渊领主在被伊利丹·怒风囚禁前曾经统治过外域？"
D.Strings[97834]="啊，我的英雄回来了！"
D.Strings[97835]="阿兹加洛。"
D.Strings[97836]="布鲁塔卢斯。"
D.Strings[97837]="玛诺洛斯。"
D.Strings[97838]="玛瑟里顿。"
D.Strings[97839]="大地神殿的萨满什么都不知道。"
D.Strings[97840]="那就让我们来测试一下你的历史知识吧！以下哪位成为了拉格纳罗斯的第二位管理者，看守着火焰之地的萨弗隆城堡？"
D.Strings[97841]="管理者鹿盔。"
D.Strings[97842]="管理者埃克索图斯。"
D.Strings[97843]="巨石之炉失踪了几个勘探者，但他们对此毫无头绪。"
D.Strings[97844]="管理者贝丝缇拉克。"
D.Strings[97845]="管理者沙恩诺克斯。"
D.Strings[97846]="那就让我们来测试一下你的历史知识吧！在情节人期间，以下哪位药剂师不可能出现在影牙城堡？"
D.Strings[97847]="弗莱伊。"
D.Strings[97848]="去吧，拿回你的武器，杀光寻找它的恶魔渣滓。"
D.Strings[97849]="拜克斯特。"
D.Strings[97850]="科普兰。"
D.Strings[97851]="汉摩尔。"
D.Strings[97852]="那就让我们来测试一下你的历史知识吧！以下哪个地精贸易公司以掠夺艾泽拉斯的自然资源而著称？"
D.Strings[97853]="黑水强盗。"
D.Strings[97854]="风险投资公司。"
D.Strings[97855]="卡亚罗贸易公司。"
D.Strings[97856]="把你们的烂摊子收拾好，血肉之子，别再往我的国度丢垃圾了！"
D.Strings[97857]="烟林牧场。"
D.Strings[97858]="小心！绿皮的节奏加快了！干掉他们！让他们死！"
D.Strings[97859]="那就让我们来测试一下你的历史知识吧！将萨尔当做奴隶关押在敦霍尔德城堡的人类叫什么名字？"
D.Strings[97860]="奥里登·匹瑞诺德。"
D.Strings[97861]="加林·托尔贝恩。"
D.Strings[97862]="达瓦尔·普瑞斯托。"
D.Strings[97863]="埃德拉斯·布莱克摩尔。"
D.Strings[97864]="那就让我们来测试一下你的历史知识吧！以下哪个兽人在德拉诺打开了无数传送门并撕裂了兽人的故乡？"
