D.Strings[97875]="背包商人。"
D.Strings[97876]="水果商人。"
D.Strings[97877]="材料商人。"
D.Strings[97878]="武器商人。"
D.Strings[97879]="那就让我们来测试一下你的历史知识吧！第一个骑着海龟神真子离开潘达利亚的熊猫人是谁？"
D.Strings[97880]="少昊。"
D.Strings[97881]="辛慈。"
D.Strings[97882]="丽丽·风暴烈酒。"
D.Strings[97883]="刘浪。"
D.Strings[97884]="那就让我们来测试一下你的历史知识吧！萨鲁法尔的兄弟，唯一打过上古之战的兽人叫什么名字？"
D.Strings[97885]="布洛克斯加。"
D.Strings[97886]="伊崔格。"
D.Strings[97887]="德拉诺什·萨鲁法尔。"
D.Strings[97888]="德雷克塔尔。"
D.Strings[97889]="那就让我们来测试一下你的历史知识吧！帮助萨尔逃离敦霍尔德城堡的人类叫什么名字？"
D.Strings[97890]="克拉米·朗斯顿。"
D.Strings[97891]="吉安娜·普罗德摩尔。"
D.Strings[97892]="特蕾莎·福克斯顿。"
D.Strings[97893]="哇哈，蠢蛋，就这样！干掉绿皮，反败为胜！"
D.Strings[97894]="我并不想引发冲突，但白银之手的圣骑士恐怕不会合作。"
D.Strings[97895]="如果有可能，我们得避免正面冲突。"
D.Strings[97896]="礼拜堂后面有一座墓穴，那里的圣光之力比较薄弱。"
D.Strings[97897]="唤醒墓穴里的亡者，就能引开卫兵，让我们有充足的时间进入礼拜堂。"
D.Strings[97898]="那就让我们来测试一下你的历史知识吧！死亡之翼归来时，摧毁了位于黑海岸的哪座联盟城市？"
D.Strings[97899]="洛达内尔。"
D.Strings[97900]="亚米萨兰。"
D.Strings[97901]="奥伯丁。"
D.Strings[97902]="古树之林。"
D.Strings[97903]="那就让我们来测试一下你的历史知识吧！喝下诺格弗格药剂后不可能出现以下哪种后果？"
D.Strings[97904]="这把武器的祝福可不是白享受的。勇敢面对你的命运吧！"
D.Strings[97905]="缩小。"
D.Strings[97906]="变成骷髅。"
D.Strings[97907]="获得缓落术效果。"
D.Strings[97908]="喷火。"
D.Strings[97909]="那就让我们来测试一下你的历史知识吧！哪种乐器可以让别人不由自主地翩翩起舞？"
D.Strings[97910]="烈焰短笛。"
D.Strings[97911]="凤凰王的金曦琴。"
D.Strings[97912]="寄魂战鼓。"
D.Strings[97913]="上古长笛。"
D.Strings[97914]="那就让我们来测试一下你的历史知识吧！祖尔金在被俘并逃脱的过程中失去了哪只手和哪只眼？"
D.Strings[97915]="右眼，左臂。"
D.Strings[97916]="左眼，左臂。"
D.Strings[97917]="右眼，右臂。"
D.Strings[97918]="左眼，右臂。"
D.Strings[97919]="那就让我们来测试一下你的历史知识吧！在德莱尼语中，以下哪句话是“一路平安”的意思？"
D.Strings[97920]="非常感谢，英雄。你必须尽快赶往圣光穹顶。先知在等待你的到来！"
D.Strings[97921]="我们会拖住这些疯狂的同胞，快去圣光穹顶吧！我们的人民需要你！"
D.Strings[97922]="快，英雄，去圣光穹顶！"
D.Strings[97923]="先知正在圣光穹顶抵挡入侵者！他需要帮助！"
D.Strings[97924]="都过来，快！用力拉！"
D.Strings[97925]="我不知道先知还能支撑屏障多久。时间宝贵！"
D.Strings[97926]="我们……能……做到！"
D.Strings[97927]="美妙的混乱！我们去掏卫兵的口袋吧。我敢打赌，里面一定有伪装的邪教徒！"
D.Strings[97928]="那就让我们来测试一下你的历史知识吧！哈克娅的配偶叫什么名字？"
D.Strings[97929]="洛卡纳哈。"
D.Strings[97930]="马格瑞亚。"
D.Strings[97931]="安卡。"
D.Strings[97932]="那就让我们来测试一下你的历史知识吧！探险者大厅中展览的红龙头骨是属于谁的？"
D.Strings[97933]="瓦拉斯塔兹。"
D.Strings[97934]="阿弗拉沙斯塔兹。"
D.Strings[97935]="凯雷斯特拉兹。"
D.Strings[97936]="泰拉纳斯塔兹。"
D.Strings[97937]="那就让我们来测试一下你的历史知识吧！第一个驯养云端翔龙的熊猫人叫什么名字？"
D.Strings[97938]="蒋。"
D.Strings[97939]="苏琪。"
D.Strings[97940]="安离。"
D.Strings[97941]="作为一个凡人，你战斗得非常英勇。"
D.Strings[97942]="杜同。"
D.Strings[97943]="你并不是我期待的援军。不过，我还是要感谢你。"
D.Strings[97944]="那就让我们来测试一下你的历史知识吧！在巨魔的赞达拉语中，“atal'ai”是什么意思？"
D.Strings[97945]="虔诚者。"
D.Strings[97946]="受眷顾者。"
D.Strings[97947]="没想到一个凡人居然能够这么凶猛地战斗。感谢你。"
D.Strings[97948]="选民。"
D.Strings[97949]="忠诚者。"
D.Strings[97950]="我是来帮助你和托里姆的。他在哪里？"
D.Strings[97951]="那就让我们来测试一下你的历史知识吧！以下哪个教派受过兽人的暗影议会影响，并有纳伽兹和玛雷兹·考尔这样的信徒？"
D.Strings[97952]="火刃氏族。"
D.Strings[97953]="萨格雷。"
D.Strings[97954]="阿古斯的觉醒。"
D.Strings[97955]="秘教徒。"
D.Strings[97956]="那就让我们来测试一下你的历史知识吧！一位联盟叛徒的儿子日后成长为了辛迪加的首领，他叫什么名字？"
D.Strings[97957]="伊瑟顿。"
D.Strings[97958]="这边走。跟上我！"
D.Strings[97959]="艾登。"
D.Strings[97960]="埃德拉斯。"
D.Strings[97961]="奥里登。"
D.Strings[97962]="别再浪费时间了！"
D.Strings[97963]="他们在酒馆里等着你。"
D.Strings[97964]="当然。我很同意，这件事就是个……灾难。但是，你仍然具有某种影响……"
D.Strings[97965]="我们住在城市的另一边是有道理的，朋友。"
D.Strings[97966]="我可以为人民改变许多……对……"
D.Strings[97967]="一柄战锤和一头恶魔从天而降……"
D.Strings[97968]="我们看到战锤掉了下来。"
D.Strings[97969]="那个恶魔警告过我们，他们会来找战锤的……"
D.Strings[97970]="来自上面世界的萨满来找战锤了！"
D.Strings[97971]="恶魔警告过我们！阻止那个萨满！"
D.Strings[97972]="一个恶魔找到了我们。我们只能听命行事。"
D.Strings[97973]="我们必须保护战锤！"
D.Strings[97974]="什么都不要告诉萨满。"
D.Strings[97975]="谢谢你，英雄。我差点就变成那个怪物的美餐了！"
D.Strings[97976]="没有历史，就没有未来。"
D.Strings[97977]="我很荣幸。照我说的办，她在晚餐前就能当上顾问了。"
D.Strings[97978]="兄弟姐妹们，今晚在猪和哨声见。使徒在等着我们！"
D.Strings[97979]="所以，邪教徒正在猪和哨声集会。我们走！这个使徒逃不了……"
D.Strings[97980]="又来了一群！他们不可能一直攻击下去……对吧？"
D.Strings[97981]="还记得这地方吗，布莱恩？"
D.Strings[97982]="你好，大宗师。在这样的日子里，愿诸灵与你同在。"
D.Strings[97983]="真是个喝酒的好日子，不是吗，大宗师？"
D.Strings[97984]="你好，大宗师。祝你今天一切顺利。"
D.Strings[97985]="等这一切都结束后，我要继续旅行。大宗师，我该去哪儿呢？"
D.Strings[97986]="午安，大宗师。我能帮你什么忙吗？"
D.Strings[97987]="大宗师，你看见丽丽了吗？她训练又迟到了。"
D.Strings[97988]="卡拉赞！这就对了。我应该在麦迪文收藏的一本古老的编年史中读过关于创世之柱的记载。"
D.Strings[97989]="你准备好回去找神真子了吗？"
D.Strings[97990]="不！姐妹们……为我……报仇！"
D.Strings[97991]="你……是来帮我们的？这地方已经被占领了！其他人都在D区，如果还有人活着的话！我得休息一下了……"
D.Strings[97992]="我还以为我已经完了。这地方已经被占领了！其他人都在D区，如果还有人活着的话！我要休息一下了……"
D.Strings[97993]="陈和丽丽是我们强大的盟友，我知道应该怎么使用他们。"
D.Strings[97994]="训练新的部队通常都需要一点时间，但我可以为你突击训练一批，大宗师。"
D.Strings[97995]="明智的选择，大宗师。我可以为你的职业大厅研究一切进阶技能。"
D.Strings[97996]="和西边的泰克泰克交谈。他会立即把你带往天禅院。"
D.Strings[97997]="我们的勇士应该可以追踪敌人的行动。我只希望能找到我的学生……趁还来得及。"
D.Strings[97998]="给我带些皮革来，我很乐意用我的不朽啤酒花来换。"
D.Strings[97999]="至少，我们的勇士可以吸引军团的攻击力，坚持到我们在岛上准备好防线为止。希望事态不要发展到那样的地步吧。"
D.Strings[98000]="快点，大宗师！上面山脊上的战斗正打到激烈的时候。你最好赶快加入战场！"
D.Strings[98001]="还没完呢……伊利达雷。"
D.Strings[98002]="我不需要凡人的武器！"
D.Strings[98003]="把它放在侦察地图上就行了。"
D.Strings[98004]="让我们看看能有什么想法吧。"
D.Strings[98005]="啊，不错。这个很精致，连翅膀上掉落的粉尘都栩栩如生。它一定会让大家高兴的。"
D.Strings[98006]="对，这样就好多了。这个角看起来很真实。"
D.Strings[98007]="唔，这边要处理一下。羽毛展开得太大了。"
D.Strings[98008]="现在我该检查些什么呢？"
D.Strings[98009]="这个幻象怎么样？"
D.Strings[98010]="嘿，别让它进来！我们在开派对呢！"
D.Strings[98011]="我……我什么都想不起来了……"
D.Strings[98012]="我的想法……它能听到我的想法！"
D.Strings[98013]="我在这儿干什么？"
D.Strings[98014]="我肯定不会随便攻击你的！出什么事了？"
D.Strings[98015]="如果那家伙能对我做这种事，天知道他们还能做出什么事来！"
D.Strings[98016]="我本以为自己什么都见识过了……可它……快离开这儿！快走！"
D.Strings[98017]="我的幻象将是你们的末日！"
D.Strings[98018]="幻象……破灭了。"
D.Strings[98019]="这些英雄给了入侵者沉重的一击！去吧，带着我的祝福，用圣光审判残余的恶魔，为我们剩下的人民清扫出一条安全通道吧！"
D.Strings[98020]="我可以照顾自己，黛文纽斯；但这道屏障外还有许多幸存者需要你的帮助！别再浪费时间了！"
D.Strings[98021]="小心点，死亡骑士。这里是圣地，我们不容你们放肆。"
D.Strings[98022]="伊利达雷随时为你效劳。"
D.Strings[98023]="破碎者向你致敬。"
D.Strings[98024]="你的一名枯法者逃跑了！抓住他！"
D.Strings[98025]="真是美味的精灵肉！"
D.Strings[98026]="在魔网节点间穿梭，收集能量！"
D.Strings[98027]="无礼的兽人！你应该等着我的！"
D.Strings[98028]="已收集到足够的能量，魔网逐渐枯竭了。"
D.Strings[98029]="使用你新获得的透视力量找到提米苟斯。"
D.Strings[98030]="你感应到提米苟斯就在北边的很远处。"
D.Strings[98031]="你感应到提米苟斯就在东边的很远处。"
D.Strings[98032]="你感应到提米苟斯就在南边的很远处。"
D.Strings[98033]="一切尽在掌握中！那些蠢货太弱了！没有他们更好！"
D.Strings[98034]="你感应到提米苟斯就在西边的很远处。"
D.Strings[98035]="你感应到提米苟斯就在你当前位置北边的不远处。"
D.Strings[98036]="你感应到提米苟斯就在你当前位置东北边的不远处。"
D.Strings[98037]="你感应到提米苟斯就在你当前位置东边的不远处。"
D.Strings[98038]="你感应到提米苟斯就在你当前位置东南边的不远处。"
D.Strings[98039]="你感应到提米苟斯就在你当前位置南边的不远处。"
D.Strings[98040]="你感应到提米苟斯就在你当前位置西南边的不远处。"
D.Strings[98041]="你感应到提米苟斯就在你当前位置西边的不远处。"
D.Strings[98042]="你感应到提米苟斯就在你当前位置西北边的不远处。"
D.Strings[98043]="你感应到提米苟斯就在你当前位置北边的极近处。"
D.Strings[98044]="你感应到提米苟斯就在你当前位置东北边的极近处。"
D.Strings[98045]="你感应到提米苟斯就在你当前位置东边的极近处。"
D.Strings[98046]="给我！给我！"
D.Strings[98047]="你感应到提米苟斯就在你当前位置东南边的极近处。"
D.Strings[98048]="你感应到提米苟斯就在你当前位置南边的极近处。"
D.Strings[98049]="你感应到提米苟斯就在你当前位置西南边的极近处。"
D.Strings[98050]="你感应到提米苟斯就在你当前位置西边的极近处。"
D.Strings[98051]="你感应到提米苟斯就在你当前位置西北边的极近处。"
D.Strings[98052]="你找到了提米苟斯！"
D.Strings[98053]="亚尔林跟我在一起。他们把鲁德拉弄到哪儿去了？还有，他们对我的山羊做了什么？快跑吧，$n！离这里远点儿！"
D.Strings[98054]="干掉他们，$n。使出全力吧。等我把伤口包扎好，我就回去，我向你保证！"
D.Strings[98055]="拜托了，$n——找到剩下的人！可怜的维隆和亚尔林！我不知道他们被带到哪儿去了！"
D.Strings[98056]="哇，你真勇敢！谢谢你帮助我们！"
D.Strings[98057]="啊，援军总算到了。拿到麦迪文之书了？我原本是在等耶戈什，不过都一样。还有，你迟到了。"
D.Strings[98058]="耶戈什和其他人都死了？这倒是……方便了。"
D.Strings[98059]="无所谓。古尔丹知道达拉然之眼在这里，但托尔巴拉德太大了。我认为这里有份重要文件，一份囚犯的名单。"
D.Strings[98060]="干得好，瓦拉加尔。"
D.Strings[98061]="凭借着无穷的智慧，纳伽兹派他最后的门徒下去侦察了。我建议你去搞清楚他怎么了，其他人去别处找。"
D.Strings[98062]="继续战斗，瓦拉加尔。"
D.Strings[98063]="嗯……被迫撤退之前，我看到泰拉尼斯往右边去了。"
D.Strings[98064]="哟，伙计！我有消息要告诉你！"
D.Strings[98065]="记住，我们从来没说过话，明白吗？"
D.Strings[98066]="|TInterface\\Icons\\ability_paladin_blindinglight2:20|t拉法拉开始施放|cFFFF0404|Hspell:219075|h[耀眼之光]|h|r。移开你的视线！"
D.Strings[98067]="那边那个！来帮帮我！小心，否则它会把你也拖进去的！"
D.Strings[98068]="你……你不是英雄吗？你为什么在帮助暗影议——不管那么多了！把我拉出去！我会报答你的，我保证！"
D.Strings[98069]="你在干什么呢？帮帮我！"
D.Strings[98070]="我……我会效忠你！我家有很多传家宝物和财富！全归你！都是你的了！"
D.Strings[98071]="你要干什么……不不不！"
D.Strings[98072]="还跟得上我吗，凡人？那就好。"
D.Strings[98073]="又一头巨型恶魔往卡拉诺斯去了！它已经冲得太远了，我们跟不上它了！"
D.Strings[98074]="托里姆！奥丁派他的勇士来帮忙了。"
D.Strings[98075]="他们还在前仆后继地涌来！我想办法挡住他们。北边这条路通往平台，$n。去帮托里姆！"
D.Strings[98076]="看！这只是奥达奇力量的一小部分！"
D.Strings[98077]="一个凡人？指挥奥丁的大军？！父亲他疯了吗！"
D.Strings[98078]="你会大吃一惊的。这个凡人杀起恶魔比芬雷尔捉野鹿还快！"
D.Strings[98079]="我要亲自考验你。这里有大量恶魔……让我看看奥丁有没有选错人吧！"
D.Strings[98080]="出色的战斗，勇士。"
D.Strings[98081]="鲜血与荣耀。"
D.Strings[98082]="你为自己赢得了地位，战士。"
D.Strings[98083]="你成功了！而且还活着！"
D.Strings[98084]="送我回家吧，欧库勒斯。"
D.Strings[98085]="……除非你打算下半辈子都背着鱼鳍过日子。"
D.Strings[98086]="别听布莱恩的。去吧，去摸一下那颗珍珠。我倒要看看会有什么事。"
D.Strings[98087]="有个沉眠多年的远古之灵随着军团的归来而苏醒了。一定要净化妮拉西娅的邪恶！找到她盘踞的那个废墟，然后解决她。"
D.Strings[98088]="后退！不要靠近那颗珍珠！"
D.Strings[98089]="|TInterface\\Icons\\Ability_Warlock_EverlastingAffliction:20|t阿克蒙德对你施放了|cFFFF0000|Hspell:219143|h[邪影爆裂]|h|r！快跑进恩赐之池！"
D.Strings[98090]="大魔导师……阻止她……"
D.Strings[98091]="这没用！"
D.Strings[98092]="夜之子必将统治这个世界！"
D.Strings[98093]="原谅我……艾利桑德。"
D.Strings[98094]="让我们看看我能……挖点什么出来……"
D.Strings[98095]="小心！别碰那颗珍珠！"
D.Strings[98096]="砍树"
D.Strings[98097]="别担心我们，干掉这些纳迦！"
D.Strings[98098]="黑锋骑士团听候你的吩咐。"
D.Strings[98099]="它是如此闪耀，让我情不自禁。"
D.Strings[98100]="萨斯多拉……我有好多年没见过它了！你背上的这把弓可是风行者家族的传家宝。"
D.Strings[98101]="我母亲将它传给了我姐姐。但愿你这个新主人能比她走运些。"
D.Strings[98102]="如果你不愿臣服于女王，那就去死吧！"
D.Strings[98103]="看一眼我的珍珠吧，旱鸭子！"
D.Strings[98104]="我的珍珠将决定你的命运，$R！"
D.Strings[98105]="记住，$n，萨斯多拉代表着我家族的传承……我的传承。我很关切它在你手中的表现。"
D.Strings[98106]="你这样老练的射手才是这把弓的好归宿。相信你不会让它蒙羞的。别让我失望。"
D.Strings[98107]="找到泰拉尼斯时已经晚了？可惜……"
D.Strings[98108]="总之跟我来吧！这里有东西，我……需要你的帮助。"
D.Strings[98109]="这本书归我了……而你将遭遇一些“意外”！"
D.Strings[98110]="我才是……古尔丹的左膀右臂……"
D.Strings[98111]="雷霆图腾的人民欢迎雄鹰之爪的主人！"
D.Strings[98112]="感受我的愤怒吧，恶魔！"
D.Strings[98113]="梵妮莎最后看了你一眼，然后走开了。"
D.Strings[98114]="枯法者今天的训练已经完成了。"
D.Strings[98115]="我们已经尽快赶来了！感谢圣光你安然无恙，先知！"
D.Strings[98116]="遵命，先知！"
D.Strings[98117]="这是一个神话，一个传说，在穷街陋巷中口口相传。"
D.Strings[98118]="相信在场的有不少人都曾听说过渡鸦之眼的传说吧？"
D.Strings[98119]="其他人狐疑地看着瓦莉拉，一脸的不信。瓦莉拉则波澜不惊地继续讲述着她的故事。"
D.Strings[98120]="人们都以为这块强大的宝石只是个传说。但我保证，它是真的。"
D.Strings[98121]="据说这块宝石能理解一切语言，识别一切地图。不仅如此，它还能破解一切密码。"
D.Strings[98122]="但最重要的是，它可以让我们破译军情七处的密信。而且，我们知道它的下落。"
D.Strings[98123]="胡说！不过她向来如此。根本没这种什么渡鸦之眼。这只是老女人的故事，用来吓唬想要隐藏秘密的小贼罢了。"
D.Strings[98124]="说的没错。我们说的正是秘密的末日。呃，反正都是别人的秘密。"
D.Strings[98125]="在一千年前，拉文凯斯领主从维库人那里偷来了渡鸦之眼。他的副官在上古之战中使用了它。"
D.Strings[98126]="风向变了，快调整你的瞄准方向来弥补。"
D.Strings[98127]="感谢您造访钢铁议会和档案馆。"
D.Strings[98128]="感谢您造访观测场。"
D.Strings[98129]="目前这两处设施都已经关闭，正在进行清扫与日常维护。请改日再行到访。"
D.Strings[98130]="愿您在奥杜尔感到愉快！"
D.Strings[98131]="非常遗憾，通道正在进行结构性评估，目前无法进入。对因此带来的不便我们深表歉意。"
D.Strings[98132]="愿您在奥杜尔感到愉快！离开之前请记得填写访客满意度调查表。"
D.Strings[98133]="燃烧军团必将征服这个世界！"
D.Strings[98134]="空的？纳伽兹也不在，我明白了。别担心，我们都清楚，那些低层成员就想往上爬。别废话了。我们要找的东西就在这里！"
D.Strings[98135]="恭喜，你成功地走出了迷宫！"
D.Strings[98136]="我感觉附近……有骚动。我们去看看。跟我来！"
D.Strings[98137]="在那儿！不安的死者挡住了路。解决那些鬼魂，好吗？"
D.Strings[98138]="哎哟！你偏离了道路！"
D.Strings[98139]="嗯……我明白了。这说的显然是虚空恐魔。它肯定是在扭曲虚空里吞噬了达拉然之眼。快，去巴拉丁监狱！"
D.Strings[98140]="你摧毁了大部分邪能传送门，削弱了拉基什补充援军的能力。现在，集中精力寻找幸存者吧！"
D.Strings[98141]="多亏了你，大部分人都安然返回圣光穹顶了！该集中精力解决剩余的邪能传送门了，结束拉基什的入侵吧！"
D.Strings[98142]="沿着小路走到迷宫尽头。"
D.Strings[98143]="大海在召唤！"
D.Strings[98144]="我们是阴影中的战士。"
D.Strings[98145]="我们还剩了一些药水和补给品。尽你所能去消除威胁吧！"
D.Strings[98146]="这可不是商人该来的地方！"
D.Strings[98147]="谢谢你。我刚才也砍倒了几个敌人，可我得走了。我担心那些家伙会活剐了我。"
D.Strings[98148]="让他们看看，我们是不会拱手让出塔伦米尔的！"
D.Strings[98149]="这里是个闹鬼的墓穴。如果没有必要，我们还是别在这里久留了。"
D.Strings[98150]="站起来，$n！跟赫尔库拉一起打倒这个燃烧军团的威胁！让他们看看一个$c的真正实力吧！"
D.Strings[98151]="在战场中尽可能地避免受到伤害。祝你好运！"
D.Strings[98152]="我要去调查一些事。与此同时，千万别让军情七处的家伙知道我们的真实意图。"
D.Strings[98153]="我再也控制不了了。一定要淹死你！"
D.Strings[98154]="我不知道你打算怎么登上那艘幽灵船……纳格法尔号。可要想证实我对这玩意儿的猜测，你就得想办法登船。如果有可能的话，最好别把你的命给送掉了。"
D.Strings[98155]="我在渡鸦庭院等你，小心别被跟踪了。"
D.Strings[98156]="以黑暗女王的名义，站起来击败燃烧军团吧！"
D.Strings[98157]="这儿真恐怖。看你能否找到渡鸦之眼吧。我在这里掩护你。"
D.Strings[98158]="抱歉，我不太擅长战斗，但我相信克莱格和汉斯会对你大有帮助的。"
D.Strings[98159]="愿月光照亮你的道路。"
D.Strings[98160]="愿星光照亮你的道路。"
D.Strings[98161]="我……要回去了。我跟这些体面人毫无瓜葛。"
D.Strings[98162]="另外，我接受你的感谢！"
D.Strings[98163]="我喜欢你的想法，月郡。"
D.Strings[98164]="有政治嗅觉的人可不止你一个。"
D.Strings[98165]="很荣幸能接受这一任命。这是难以言喻的荣耀。"
D.Strings[98166]="是的，我明白。小心点，我们这儿快要没位置了。"
D.Strings[98167]="暗箭伤人的卑鄙蠢货！那个头衔本该属于我！"
D.Strings[98168]="你窃取了我的荣耀！你用毫无根据的指控破坏了我的名誉！"
D.Strings[98169]="阁下，你太失态了。一切都尘埃落定了。"
D.Strings[98170]="你的星辰即将熄灭！"
D.Strings[98171]="但愿这能尽快结束。"
D.Strings[98172]="我会夺回属于我的荣耀！进行古老的仪式——塔尔艾什吧！"
D.Strings[98173]="我有10份浸水的魔力要给你。"
D.Strings[98174]="看来你弄到了一些浸水的魔力？让我来帮你拿吧……"
D.Strings[98175]="我可不是为了这个才来的。"
D.Strings[98176]="部落的战士们！散开！今天，我们要集中力量攻击燃烧军团。等这场战斗结束后，我们再来收拾联盟的渣滓。"
D.Strings[98177]="钓鱼？……真的？！"
D.Strings[98178]="带我一起去吧。求你了！"
D.Strings[98179]="我会从你的勇士手中夺回属于我的头衔，莉莉丝！"
D.Strings[98180]="你不是我的对手！我比你更强！"
D.Strings[98181]="我要夺回属于我的东西！"
D.Strings[98182]="我是被……陷害的……"
D.Strings[98183]="挑战者？别惹我发笑了！"
D.Strings[98184]="军团给了我们无穷的力量！"
D.Strings[98185]="臣服于夏多雷的力量吧！"
D.Strings[98186]="我不会被你们这种人打败的！"
D.Strings[98187]="他们……承诺过……"
D.Strings[98188]="对我来说，走大路会轻松一点。"
D.Strings[98189]="动物园在那边。"
D.Strings[98190]="当心你的背后。"
D.Strings[98191]="别磨蹭。你会后悔的。"
D.Strings[98192]="我可不是导游。酒庄就在城市的另一边。"
D.Strings[98193]="我的时间可是很宝“贵”的。"
D.Strings[98194]="你看到附近有别人在转悠吗？没有吧？知道为什么吗？"
D.Strings[98195]="嗨……"
D.Strings[98196]="我讨厌你的脸！"
D.Strings[98197]="能够管理酒庄是一份巨大的荣耀。"
D.Strings[98198]="你玩得开心吗？"
D.Strings[98199]="我们只生产最好的酒。"
D.Strings[98200]="感谢你的来访！"
D.Strings[98201]="祝你过得愉快。"
D.Strings[98202]="改天再来！"
D.Strings[98203]="对，我平时都是这么快乐。不，我才不会骂你呢。"
D.Strings[98204]="希望这能让你感到愉快。我已经“高兴”地不行了。"
D.Strings[98205]="你知道吗，我可以这样坚持一整天。"
D.Strings[98206]="放松点。来喝一杯吧。"
D.Strings[98207]="只要把你的需求告诉我就行。"
D.Strings[98208]="如果你想抱怨，我的主管玛尔迦很乐意受理你的投诉。"
D.Strings[98209]="动物园只对游客——嗯哼。酒庄只对客户开放。"
D.Strings[98210]="你需要月之守卫做些什么吗？"
D.Strings[98211]="我们守护着苏拉玛。"
D.Strings[98212]="我们的职责已经完成了，但我留了下来。"
D.Strings[98213]="如果你需要我，我就在这里。"
D.Strings[98214]="你的时机选择无可挑剔。"
D.Strings[98215]="看看月之守卫的困境吧。"
D.Strings[98216]="你是来帮我们的吗？"
D.Strings[98217]="我会守护这片土地，直到最后一刻。"
D.Strings[98218]="我的家园虽然沦为废墟，但我依然坚强。"
D.Strings[98219]="月之守卫很快就会消亡。"
D.Strings[98220]="我们的末日来得毫无征兆。"
D.Strings[98221]="我的责任就是守卫这座要塞，直到最后一刻。"
D.Strings[98222]="我会坚持下去的。"
D.Strings[98223]="我们被击败了，只留下回忆。"
D.Strings[98224]="这里有着最好的美酒。"
D.Strings[98225]="只有大师才能为艾利桑德酿酒。"
D.Strings[98226]="我能品出每一种味道。"
D.Strings[98227]="祝你喝得愉快！"
D.Strings[98228]="享受美酒。"
D.Strings[98229]="你好像……被我的知识吓傻了。"
D.Strings[98230]="我猜你也是个学者吧。多么相似的故事。"
D.Strings[98231]="我敢用一座金山来跟你打赌，你喝的全都是酒糟，平民。"
D.Strings[98232]="这不是我们的森林，但我们会适应的。"
D.Strings[98233]="愿艾露恩之光指引你的道路。"
D.Strings[98234]="请接收来自神殿的问候，朋友。"
D.Strings[98235]="她的光芒依然照耀着此处。"
D.Strings[98236]="苏拉玛不会重蹈瓦尔莎拉的覆辙。我敢肯定。"
D.Strings[98237]="勇敢向前！"
D.Strings[98238]="苏拉玛永远都是晴天。"
D.Strings[98239]="这里不是瓦尔莎拉，但它也不错。"
D.Strings[98240]="一路平安，朋友。"
D.Strings[98241]="夏多雷是……天选的……"
D.Strings[98242]="欢迎来到避难所。"
D.Strings[98243]="别客气。我们都一样。"
D.Strings[98244]="小心当地人。"
D.Strings[98245]="我们挡不住他们！"
D.Strings[98246]="你伤害不了我们！"
D.Strings[98247]="为了夏多雷！"
D.Strings[98248]="为了苏拉玛！"
D.Strings[98249]="我们要保卫自己的土地！"
D.Strings[98250]="感受夏多雷的力量吧！"
D.Strings[98251]="这是夏多雷的时代！"
D.Strings[98252]="我要处决你，下等人！"
D.Strings[98253]="我们是天选的统治者！"
D.Strings[98254]="一个外来者都不要放过！"
D.Strings[98255]="在我们的力量面前颤抖吧！"
D.Strings[98256]="下等杂种！"
D.Strings[98257]="你必将臣服于我们！"
D.Strings[98258]="谁都别想挑战我们！"
D.Strings[98259]="我们是……天选之民……"
D.Strings[98260]="你拿到梦魇样本了吗？"
D.Strings[98261]="不……这不对！把坏幼苗干掉，别让它跑了！"
D.Strings[98262]="去找大德鲁伊巨蹄，把事情告诉他。我来看看它还剩下些什么。"
D.Strings[98263]="恶魔，你胆敢惊扰我的安眠？！"
D.Strings[98264]="跟瓦莉拉说，我们在看着她。"
D.Strings[98265]="啊，你并不是恶魔嘛！"
D.Strings[98266]="来吧，兄弟们，燃烧军团攻来了！"
D.Strings[98267]="死吧，魔誓叛徒！"
D.Strings[98268]="终于，我再度获得平静。"
D.Strings[98269]="你听到了轻柔的流水声。"
D.Strings[98270]="你感觉提米苟斯被某种明亮的光芒给催眠了。"
D.Strings[98271]="附近有一些古代符文，可你还是明显感觉到了孤单。"
D.Strings[98272]="你感觉那些被诅咒已久的生物拥有了新的形态。"
D.Strings[98273]="你获得了超然万物的感觉。"
D.Strings[98274]="你听到了树叶在风中发出的轻响。"
D.Strings[98275]="你闻到了阳光下柔和的花香味儿。"
D.Strings[98276]="你听到了羽毛掠过空气的声音，蹄子践踏大地的声音，以及爪子抓挠树木的声音。"
D.Strings[98277]="你依稀听到了水流的声音。"
D.Strings[98278]="你感觉到了来自上方的安全感。"
D.Strings[98279]="你感觉一头优雅的生物昂首阔步地走了过去。"
D.Strings[98280]="你很好奇，幽灵真的会友好吗？"
D.Strings[98281]="你感觉到了一个黑暗的身影。"
D.Strings[98282]="你闻到了潮湿的黑土气味。"
D.Strings[98283]="你感觉周围的大地在震颤。"
D.Strings[98284]="你听到了小火苗噼啪作响的声音。"
D.Strings[98285]="你感觉自己身处一群朋友中间。"
D.Strings[98286]="你感觉到了月亮的影像。"
D.Strings[98287]="你听到附近有一座大瀑布。"
D.Strings[98288]="你为这些恶心的生物感到难过。"
D.Strings[98289]="这里有漂亮的水晶！"
D.Strings[98290]="你感觉周围充斥着魔网能量。"
D.Strings[98291]="你感觉附近的魔力网络上有一条缝隙。"
D.Strings[98292]="你感觉周围都是高耸的建筑。"
D.Strings[98293]="这些水晶好大啊！"
D.Strings[98294]="你感觉好像回到了家中。"
D.Strings[98295]="这里有好多陪你玩的朋友！"
D.Strings[98296]="你感觉附近有一个巨大的魔网能量池。"
D.Strings[98297]="艾利桑德，我辜负了你……"
D.Strings[98298]="我不能输给一个贱种！"
D.Strings[98299]="我们……失败了。"
D.Strings[98300]="赫尔库拉！好久不见啊。"
D.Strings[98301]="我们必须……坚持……"
D.Strings[98302]="不！我还不能死……"
D.Strings[98303]="抵抗是徒劳的……"
D.Strings[98304]="你的存在亵渎了这座神殿，恶魔！"
D.Strings[98305]="为了奥杜尔！"
D.Strings[98306]="你不属于这里，恶魔。滚吧！"
D.Strings[98307]="坚持住，霍迪尔！我带来了帮手。这些恶魔打不过我们！"
D.Strings[98308]="一个凡人带领着苍穹要塞的军队？这是亵渎！"
D.Strings[98309]="我们将重建这个世界。"
D.Strings[98310]="这不是普通的凡人。$n是奥丁的选民！"
D.Strings[98311]="阻止它！不惜一切代价！"
D.Strings[98312]="夏多雷永垂不朽。"
D.Strings[98313]="你干嘛总是缠着我不放？"
D.Strings[98314]="走开！"
D.Strings[98315]="我们的时代已经到来。"
D.Strings[98316]="我们的时代降临了！"
D.Strings[98317]="夜之子必将君临天下。"
D.Strings[98318]="保重。"
D.Strings[98319]="请帮帮我，$n。我的小朋友提米苟斯在这一带失踪了。"
D.Strings[98320]="我会对你施放一个法术，让你在短时间内获得未卜先知的能力。用你的新能力找到提米苟斯吧。"
D.Strings[98321]="太感谢你了，$n！"
D.Strings[98322]="愿暗夜指引你的道路。"
D.Strings[98323]="愿艾利桑德指引你的道路。"
D.Strings[98324]="愿星辰指引你的道路。"
D.Strings[98325]="我们重新回到了这个世界。"
D.Strings[98326]="夏多雷必将崛起。"
D.Strings[98327]="我的货物都是最顶级的。"
D.Strings[98328]="看看吧，我这儿什么都有。"
D.Strings[98329]="你想来点儿什么？"
D.Strings[98330]="我的东西绝对是最便宜的了！"
D.Strings[98331]="跟你做生意很愉快。"
D.Strings[98332]="我们已经躲藏得太久了。"
D.Strings[98333]="你想聊聊吗？"
D.Strings[98334]="我们又回到了星空之下。"
D.Strings[98335]="夜之子永垂不朽。"
D.Strings[98336]="我们是不朽的。"
D.Strings[98337]="苏拉玛已经崛起。"
D.Strings[98338]="赞美艾利桑德的智慧。"
D.Strings[98339]="我们再也不用躲藏了。"
D.Strings[98340]="暗夜井滋养着我们。"
D.Strings[98341]="快点！"
D.Strings[98342]="这是个混乱的时代。小心背后。"
D.Strings[98343]="愿暗夜井的恩赐与你同在。"
D.Strings[98344]="愿暗夜保佑你。"
D.Strings[98345]="你的世界将属于我们！"
D.Strings[98346]="夏多雷已经归来。"
D.Strings[98347]="愿星光照亮你的旅途，朋友。"
D.Strings[98348]="你这是在螳臂当车。仆从们，消灭$g他:她;！"
D.Strings[98349]="派出愤怒领主！阻止这些多管闲事的蝼蚁！"
D.Strings[98350]="你是在挑战萨格拉斯的无穷大军，蠢货！姐妹们，我要$g他:她;的脑袋！"
D.Strings[98351]="对于一个先知来说，你的预言能力太差劲了……"
D.Strings[98352]="*沃洛斯发出痛苦的哀鸣*"
D.Strings[98353]="该活动一下了。"
D.Strings[98354]="把最近的恶魔指给我看吧。"
D.Strings[98355]="我的利刃在渴望战斗。"
D.Strings[98356]="你竟敢亵渎我们的土地？"
D.Strings[98357]="寸土必争！"
D.Strings[98358]="你低估了被遗忘者的力量！"
D.Strings[98359]="看上头。看到那个锚点了吗？你就用它爬上去吧。"
D.Strings[98360]="这地方可真大……把这些违禁品都带走！"
D.Strings[98361]="我的心中满是同情。我与他们分享了一份古老的恩赐。"
D.Strings[98362]="拿着这个钩子。我能找到一个更合适藏东西的地方。"
D.Strings[98363]="冥想开拓了我们的眼界，现在，我们有办法将你收集到的资源注入那件古老的神器中了。"
D.Strings[98364]="我在那儿等你。我得确保我的货物不会落入他们的手中。"
D.Strings[98365]="看到阿格拉玛之盾没有落入斯科瓦尔德和他的恶魔盟友之手，我深感欣慰。"
D.Strings[98366]="史诗般的任务正在等待着你，$n。毫无疑问，在未来的几百年里，你的光辉事迹一定会在吟游诗人中间口口相传的。"
D.Strings[98367]="去吧，勇士，让这个燃烧军团看看瓦拉加尔的怒火！"
D.Strings[98368]="夜之子已经归来。"
D.Strings[98369]="站到啸山熔炉前面来，高举你的武器吧。它将唤醒这把武器的真正力量！"
D.Strings[98370]="你好，朋友！光明之翼欢迎你的到来！"
D.Strings[98371]="燃烧军团必将为觊觎我的国度而后悔。我的大军听候你的调遣。带领他们走向荣耀吧！"
D.Strings[98372]="不不不，我美丽的林地正在受到伤害。朋友，你能帮忙吗？"
D.Strings[98373]="那是阿坎多尔古树。它滋养了他们。他们安居乐业了一段时间。"
D.Strings[98374]="但很快，那棵树就不稳定了。"
D.Strings[98375]="阿坎多尔枯死了。狂野的魔力将法兰纳尔的居民全部扭曲。"
D.Strings[98376]="我的失败催生了法多雷。但我不会再失败了。"
D.Strings[98377]="这里关押着最危险的囚犯。你最好别四处乱晃。没人知道阴影里藏着什么……"
D.Strings[98378]="联盟和部落为争夺这座监狱还打过仗呢。和以往一样，那些傻瓜的努力毫无意义。\n"
D.Strings[98379]="我敢肯定，你从未对付过虚空恐魔。避开它的视线攻击，别挡我的道。我可不是来保护你的！"
D.Strings[98380]="唔，要做的事情好多……时间好少……但小精龙还要继续努力。"
D.Strings[98381]="|TInterface\\Icons\\sha_spell_fire_felfire:20|t%s正在施放|cFFFF0000|Hspell:219571|h[邪霜死爆]|h|r！快打断它！"
D.Strings[98382]="野兽倒下了！我又胜利了。"
D.Strings[98383]="让我来。你笨手笨脚的，肯定会造成无法挽回的伤害。"
D.Strings[98384]="我拿到眼睛了，而书在你手里。嗯，好吧，你来拿着它。快去萨格拉斯之墓，别让古尔丹久等。"
D.Strings[98385]="又见面了，$n。泰坦之击跟你相得益彰。"
D.Strings[98386]="米米尔隆！你怎么会在这里？"
D.Strings[98387]="严格来说，这只是我的投影，不是真实的存在。定期检查是个好习惯。"
D.Strings[98388]="泰坦之击和哈提都很强大。"
D.Strings[98389]="我只是确定一下泰坦之击以及里面的雷霆之火运转正常。你知道的，我向来以它们为傲！"
D.Strings[98390]="但愿你的发明能帮助我们战胜燃烧军团。"
D.Strings[98391]="我的发明向来出色。事实上，我已经有新计划了！我很乐意跟你讨论一下！"
D.Strings[98392]="我们下次再玩好吗？"
D.Strings[98393]="魔力尝起来是紫色的！"
D.Strings[98394]="坚守善良，保持坚强。"
D.Strings[98395]="好好享用你的魔力果汁吧！"
D.Strings[98396]="暗夜井万岁！"
D.Strings[98397]="我现在就想玩。"
D.Strings[98398]="拜托！去做点好玩的事吧！"
D.Strings[98399]="抱歉，我还有事要做。"
D.Strings[98400]="你一定还有别的地方可去吧？"
D.Strings[98401]="除了这里，你就没地方可去了吗？"
D.Strings[98402]="你真是我的眼中钉肉中刺。"
D.Strings[98403]="你去黑鸦堡垒时，我得去处理另一件紧急事务了。我们在暗影大厅见。"
D.Strings[98404]="[大笑]"
D.Strings[98405]="噩梦何时才能结束？"
D.Strings[98406]="好了，够了。"
D.Strings[98407]="你想找麻烦吗？"
D.Strings[98408]="因为你很快就会有麻烦了。"
D.Strings[98409]="对了！我决定不请你参加我的升职庆祝会。"
D.Strings[98410]="你去烦别人怎么样？"
D.Strings[98411]="你看，我只想站完这班岗，为艾泽拉斯带来一个新纪元而已。"
D.Strings[98412]="你能让我那么做么？你会让我带来这个新纪元吗？"
D.Strings[98413]="<叹气>我该接受艾萨拉那个职位的。"
D.Strings[98414]="你知道吗，不是所有人都能像我这样精通魔法的。"
D.Strings[98415]="看看你，再看看我。我可是魔法大师。"
D.Strings[98416]="我参加过苏拉玛最顶尖的魔法学会。"
D.Strings[98417]="至于你。你连最简单的戏法都变不了。"
D.Strings[98418]="我甚至专门研究过战斗魔法，而且是以全班第一名的成绩毕业的。"
D.Strings[98419]="现在再说回我。可惜，你不是我。低头，现在抬头。"
D.Strings[98420]="你看。魔法让我像钻石一样闪闪发光。"
D.Strings[98421]="|TInterface\\Icons\\ability_mage_timewarp:20|t时间的流逝速度恢复了正常。"
D.Strings[98422]="|TInterface\\Icons\\ability_mage_timewarp:20|t时间的流逝速度加快了。"
D.Strings[98423]="|TInterface\\Icons\\ability_mage_timewarp:20|t时间的流逝速度减慢了。"
D.Strings[98424]="你休想动摇我！"
D.Strings[98425]="嗜魔者！"
D.Strings[98426]="苏拉玛仍然是大分裂的废墟中一颗闪亮的明珠。"
D.Strings[98427]="我们将探索广阔的世界，告诉他们我们依然重要！"
D.Strings[98428]="你看起来很年轻，还能玩这种把戏。你能为我考虑一下吗？"
D.Strings[98429]="我会抓住这个机会，给闯入者设下陷阱。我相信我们一定会再见面的！"
D.Strings[98430]="我们必将浴光重生。"
D.Strings[98431]="我会帮你的。"
D.Strings[98432]="纳鲁能帮你什么忙吗？"
D.Strings[98433]="愿圣光与你同行。"
D.Strings[98434]="愿圣光照亮你的道路。"
D.Strings[98435]="小心点，我可是很暴躁的。"
D.Strings[98436]="别把我蹭脏了。"
D.Strings[98437]="你想从外头看看神殿吗？"
D.Strings[98438]="你找到了！我会好好保管，并立即把它们送到安全的地方去的。"
D.Strings[98439]="这大厅……我从没见过这种地方。"
D.Strings[98440]="够了！我受不了你了。"
D.Strings[98441]="抓紧享受胜利吧。军团必将撕碎这个世界！"
D.Strings[98442]="她要跑了！"
D.Strings[98443]="不能让她就这样逃走！"
D.Strings[98444]="啊……这下好多了！"
D.Strings[98445]="很好，你拿到零件了！给XR9-47，让他带给我。"
D.Strings[98446]="古代传送器，和苏拉玛城里的差不多，看来它们都关着。"
D.Strings[98447]="XR9-47，快把零件送来！"
D.Strings[98448]="<XR9-47的齿轮期待地转动着。>"
D.Strings[98449]="米米尔隆，XR9-47把零件送来了吗？"
D.Strings[98450]="我们要撕碎你的灵魂！"
D.Strings[98451]="总算有点乐子了。"
D.Strings[98452]="军团征服万物！"
D.Strings[98453]="尝尝真正的恐惧吧！"
D.Strings[98454]="叛军已经让街道尸横遍野了，你却在这里举行无聊的贵族聚会？"
D.Strings[98455]="你会成为很好的祭品。"
D.Strings[98456]="我保证，大魔导师，局势已经得到了控制。追捕一小撮异见人士只是小菜一碟，而且——"
D.Strings[98457]="米米尔隆，我把精华交换器弄丢了，能再给我一个吗？"
D.Strings[98458]="你阻止不了我们所有人……"
D.Strings[98459]="胡闹？你难道没发现，我们找到的尸体上都有一朵暮色百合吗？那是塔莉萨最喜欢的花！"
D.Strings[98460]="我只是燃烧大军中的一员……"
D.Strings[98461]="我……我不明白您的意思，大魔导师。"
D.Strings[98462]="湮灭降临！"
D.Strings[98463]="这世界必将……化为灰烬。"
D.Strings[98464]="那我就直说了吧。你暗杀塔莉萨的行动搞砸了。事实上，她还活得好好的，正在……"
D.Strings[98465]="等等，这儿还有别人。"
D.Strings[98466]="这是……徒劳的……"
D.Strings[98467]="这不可能！我的卫兵不可能让人闯进来！"
D.Strings[98468]="会有人为我报仇的。"
D.Strings[98469]="我们将烤焦这个世界！"
D.Strings[98470]="倒下我一个……还会有更多。"
D.Strings[98471]="总算有个像样的猎物了……"
D.Strings[98472]="别来惹我们！"
D.Strings[98473]="显然你又失败了，麦兰杜斯。我给你一个机会。干掉这些外来者，我得回暗夜要塞了。"
D.Strings[98474]="这么快就走了吗，大魔导师？"
D.Strings[98475]="敌人正在逼近，你还想让我浪费时间去跟无聊的贵族闲聊？看看吧，蠢货！这儿有人。"
D.Strings[98476]="我们又见面了！洛休斯和赛拉娜刚刚跟我说了你的事迹。"
D.Strings[98477]="等收集到足够的荒野精华后再来找我吧，大德鲁伊。我相信别人都不可能完成这个困难的任务。"
D.Strings[98478]="我们也做出了决定，是时候离开这个地方了。"
D.Strings[98479]="月之守卫不复存在了。没有人能拯救我们深爱的要塞。"
D.Strings[98480]="我们不能忽视玛洛恩的警告。森林之父正身陷险境，我们得帮帮他……否则这片荒野就没救了。"
D.Strings[98481]="重建传送门可不容易。我们要花上几个月的时间才能完成仪式。"
D.Strings[98482]="你好，大宗师！我带来了彭戍大师的口信。"
D.Strings[98483]="很荣幸能与你并肩作战，大德鲁伊。让我们一起保护自然的平衡。"
D.Strings[98484]="我与你同在，大德鲁伊。为艾泽拉斯而战！"
D.Strings[98485]="耶！我喜欢你……让我们并肩战斗吧！"
D.Strings[98486]="我听你的，大德鲁伊。让我们一起保护荒野吧。"
D.Strings[98487]="噢！让我好好抱抱你！我们要一起拯救那么多小动物了！"
D.Strings[98488]="我会祈求艾露恩治疗伤者，复活死者。谢谢你，大德鲁伊。"
D.Strings[98489]="我的爪子锋利无比，随时准备捕猎。猎物连我的影子都摸不着。"
D.Strings[98490]="好了。这些树人可以参战了。"
D.Strings[98491]="我年轻时曾受过战士的训练……感觉就好像是上辈子的事了一样。不过，我的剑术还是很不错的！"
D.Strings[98492]="我很乐意为议会贡献力量，大德鲁伊。我听说过你的伟大成就。"
D.Strings[98493]="将你获得的灵魂和资源注入这个熔炉，就能解锁你武器中真正的毁灭之力！"
D.Strings[98494]="我研究过各种各样的魔法。虽然人人都觉得自己的法术才是最棒的，但我可以向你保证，它们几乎都是千篇一律的。"
D.Strings[98495]="成功了！在你的力量面前，燃烧军团必败！"
D.Strings[98496]="邪能魔法没什么“稀奇”的！"
D.Strings[98497]="大德鲁伊，我带来了议会的口信！"
D.Strings[98498]="你一直都是勇猛的荒野守护者。你运用那把古老武器的技巧证明你完全有资格成为我们的勇士。"
D.Strings[98499]="现在，通过你取得的胜利和你收集到的资源，我们可以唤醒你那件神器中的全部力量。"
D.Strings[98500]="我觉得，死在剑下和死在法术下没什么区别！"
D.Strings[98501]="搞定了吗，朋友？好，很好！卡里杜斯给你开门。回达拉然，快，快！"
D.Strings[98502]="燃烧军团杀了我全家。去死吧！"
D.Strings[98503]="让纪元之种为你的武器灌注力量吧。看着它变得前所未有的强大！"
D.Strings[98504]="我的剑术和法术一样出色。你喜欢哪样？"
D.Strings[98505]="叽里咕噜……等等，噢！嘿。小心点，那些纳迦可不友好。他们一直想要奴役附近的浅鳍鱼人部族。这里是他们抵抗入侵的最后一个避难所了。我们非常需要你的帮助！\n\n还有一件事……如果你得到了那些纳迦手上的上古神器，能带回来给我吗？我的研究有需要。我保证不会让你白干的！"
D.Strings[98506]="拿走我手里所有的上古神器吧！"
D.Strings[98507]="主人，我带来了奥图里斯的口信。"
D.Strings[98508]="他们很快就会扑上来的。我可以把我们传送到安全的地方去。"
D.Strings[98509]="主人，我带来了凯恩的口信。"
D.Strings[98510]="我可以用我的剑，可我不想把它浪费在你这种人身上。"
D.Strings[98511]="黑暗收割议会一直都很钦佩你的技巧，虚空领主。能驾驭如此强大的武器真是令人振奋！"
D.Strings[98512]="通过你征服的恶魔以及你收集到的资源，我们可以举行一个仪式，唤醒这件神器的黑暗命运！"
D.Strings[98513]="在魔血祭坛前举起你的武器吧。它将用可怕的能量为这把武器注入地狱之力！"
D.Strings[98514]="你寻找这件神器的决定有了丰厚的回报。我从未见过一个法师能与自己的武器如此默契。"
D.Strings[98515]="你为提瑞斯秘法会赢得的胜利，以及收集到的资源，可以让我们解锁那件神器里的全部力量。"
D.Strings[98516]="举起你的武器，让守护者熔炉为它注入力量吧！"
D.Strings[98517]="先知，我这儿有努波顿给你的信。"
D.Strings[98518]="我们的直升机就要到了。我们必须去警告联盟和部落。"
D.Strings[98519]="必须让他们的舰队调头。破碎海滩是个死亡陷阱。"
D.Strings[98520]="他们告诉了我们一个方法，用你收集来的资源解锁这件神器真正的力量。"
D.Strings[98521]="举起你的武器吧，先知。让大地、空气、烈焰与流水之灵帮助他们的勇士！"
D.Strings[98522]="你的武器中流淌着艾泽拉斯的生命之血！运用你的智慧，用它打击敌人吧！"
D.Strings[98523]="有情况吗，中尉？"
D.Strings[98524]="这座岛上挤满了恶魔。比我们估计的还要……"
D.Strings[98525]="你的胜利和你收集到的资源让我们找到了唤醒那件神器全部力量的方法。"
D.Strings[98526]="用渡鸦之眼破译军情七处的加密信件吧，$n。"
D.Strings[98527]="只要我们信仰坚定，还有你这个勇士在，那燃烧军团就休想占领艾泽拉斯！"
D.Strings[98528]="嘘！这是给你的信……渡鸦的亲笔信！"
D.Strings[98529]="干我们这行的，都会想办法与趁手的武器建立起紧密的联系。可你与这对匕首间的默契程度真是前所未见。"
D.Strings[98530]="你从破碎群岛上收集来的资源让我们能够解锁这对匕首中更加强大的杀戮力量了。"
D.Strings[98531]="看来，你们发现了我们的小秘密。"
D.Strings[98532]="在无冕者锻炉前举起你的武器，让它为你的匕首注入致命的力量吧！"
D.Strings[98533]="虽然你走过一小段孤独的道路，但你与这件古老武器间的联系更加紧密了。"
D.Strings[98534]="现在，通过你连续的胜利以及你收集到的资源，我们可以解锁你那件神器中的全部力量了。"
D.Strings[98535]="通过你取得的胜利，以及你在讨伐黑暗时收集到的资源，我们终于可以解锁你那件武器的强大力量了！"
D.Strings[98536]="看，远古列王祭坛正在为你的神器注入力量，让它变得更加强大！"
D.Strings[98537]="在漫长的生命中，我从未见过哪个战士能与他的武器如此默契。它的体内仿佛流淌着你的血液。"
D.Strings[98538]="你在破碎群岛的辉煌战绩让我们有了重铸那把武器所需的胜利与资源，这将唤醒它真正的力量。"
D.Strings[98539]="来吧，到奥丁的熔炉前来。看着吧，你的神器经过重铸，将变得空前强大！"
D.Strings[98540]="现在，你终于有一件配得上我的战争使者的武器了！继续为瓦拉加尔带来荣耀吧！"
D.Strings[98541]="我向你们保证，你们的宝贝舰队一定会落入我们的陷阱。"
D.Strings[98542]="你休想逍遥法外，迪瑟洛克！"
D.Strings[98543]="噢？那你恐怕要失望了。因为你，马迪亚斯·肖尔，会帮我们的。"
D.Strings[98544]="现在，我就是军情七处的领袖了！"
D.Strings[98545]="洛林在广场上。塞莱莎通常在运河边。希尔乐则在集市上。他们都很显眼。"
D.Strings[98546]="沙拉撒曼绝对不想作为腐蚀的使者存在下去。织梦者为他的离去而哀伤，也为他痛苦的终结而快慰。"
D.Strings[98547]="军团来了！拿出你们的力气，准备好你们的法术，战争开始了！"
D.Strings[98548]="不要乱！打倒他们！"
D.Strings[98549]="喜欢这个派对吗？我听说了一个丑闻。"
D.Strings[98550]="敌人来势汹汹！不管你们是为神祇、国王还是金钱而战，快打倒他们！"
D.Strings[98551]="使出你们吃奶的力气！全力攻击！快干掉这个邪恶的野兽！"
D.Strings[98552]="战斗还在继续，朋友们。散开！把这些恶魔赶出希尔斯布莱德！"
D.Strings[98553]="很高兴能跟你合作。"
D.Strings[98554]="艾泽拉斯的英雄们！如果你们热爱希尔斯布莱德，就起来战斗吧！"
D.Strings[98555]="拿出你们全部的实力，无论是魔法还是力量！把这个恶魔赶回虚空去！"
D.Strings[98556]="拯救了塔伦米尔，就等于保住了整个洛丹伦。好好回味这场胜利吧，但记住……这只是个开始！"
D.Strings[98557]="快点回来！"
D.Strings[98558]="我必须回去。"
D.Strings[98559]="我在这儿坚持不了多久。"
D.Strings[98560]="我们的珠宝无与伦比。"
D.Strings[98561]="我的作品无与伦比。"
D.Strings[98562]="我的每件作品都是完美的。就算是我学徒做的也一样。"
D.Strings[98563]="小声点。"
D.Strings[98564]="我可不想引起任何人的注意。"
D.Strings[98565]="我就知道你靠得住。"
D.Strings[98566]="我们全指望你的胜利了。"
D.Strings[98567]="快点回来。来买点东西也不错啊。"
D.Strings[98568]="我们到楼下去看看。小心脚下。"
D.Strings[98569]="这下好多了。"
D.Strings[98570]="奇怪。地面好像是……一张地图？"
D.Strings[98571]="可以肯定的是——魔网能量从四面八方被汇聚到了这里。"
D.Strings[98572]="你好，最近有什么趣事吗？"
D.Strings[98573]="你好，有什么新消息吗？"
D.Strings[98574]="瓦拉加尔在等待你的命令。"
D.Strings[98575]="你需要侍从吗？"
D.Strings[98576]="在联盟与部落舰队抵达前几个小时，我们来到了破碎海滩。"
D.Strings[98577]="它的……元素……"
D.Strings[98578]="弓箭手随时待命！"
D.Strings[98579]="森林是同呼吸共命运的整体。"
D.Strings[98580]="一个出色的对手！"
D.Strings[98581]="战斗结束后，我要去喝一杯！"
D.Strings[98582]="……躺下吧！"
D.Strings[98583]="我们去喝一杯庆功酒吧！"
D.Strings[98584]="我需要……休息一会儿。"
D.Strings[98585]="真的……好痛啊。"
D.Strings[98586]="别担心，我会掩护你的！"
D.Strings[98587]="这能行！"
D.Strings[98588]="我知道你需要什么！"
D.Strings[98589]="这个该死的蠢蛋死定了！"
D.Strings[98590]="蠢蛋想打架？我就让你打个够！"
D.Strings[98591]="这个蠢蛋像不像个球？我要拍扁他的头！"
D.Strings[98592]="这个蠢蛋完蛋了！甜蜜的胜利！"
D.Strings[98593]="哇哈哈！我们赢了！打架最有趣了！"
D.Strings[98594]="痛快的战斗！让他们瞧瞧我们的厉害吧！"
D.Strings[98595]="痛死啦！美猴王要趴一会儿！"
D.Strings[98596]="蠢蛋打倒了美猴王！太可怕了！"
D.Strings[98597]="就这样吧！美猴王要走了。挨打可不好玩！"
D.Strings[98598]="他们一定会大吃一惊。"
D.Strings[98599]="我们将出奇制胜！"
D.Strings[98600]="重拳快打！"
D.Strings[98601]="我要踢爆你的屁股！"
D.Strings[98602]="啊，这一定很棒！"
D.Strings[98603]="你原本就丑，死了就更丑了。"
D.Strings[98604]="先祖会为我们骄傲的。"
D.Strings[98605]="你还是死掉比较好。"
D.Strings[98606]="干掉它们，风暴比克！"
D.Strings[98607]="撕碎他们，好姑娘！"
D.Strings[98608]="我的狮鹫在渴望战斗！"
D.Strings[98609]="好痛啊……你先走吧。"
D.Strings[98610]="呃……我受了点伤……"
D.Strings[98611]="让元素在你体内流淌吧！"
D.Strings[98612]="原初之水将净化万物！"
D.Strings[98613]="潮汐永不停歇！"
D.Strings[98614]="看来你需要帮助，朋友。"
D.Strings[98615]="大地之环与你同在！"
D.Strings[98616]="元素已经降下了旨意！"
D.Strings[98617]="大家面前的，是位真正的勇士，曾为联盟赢得过许多伟大的胜利。"
D.Strings[98618]="这就是我们苦练的目的！"
D.Strings[98619]="我们的敌人完蛋了！"
D.Strings[98620]="谁也阻挡不了我们。"
D.Strings[98621]="他们手中的古老武器象征着希望，这是属于人民的希望。"
D.Strings[98622]="我受伤了……你走吧，别管我了！"
D.Strings[98623]="我会好起来的。"
D.Strings[98624]="站住别动！"
D.Strings[98625]="你为什么不能……安静一会儿呢？！"
D.Strings[98626]="这家伙不是我的对手。"
D.Strings[98627]="我所过之处只余灰烬！"
D.Strings[98628]="我们的敌人将化为灰烬！"
D.Strings[98629]="一个小小的……挫折……呃……"
D.Strings[98630]="看看袋子里有什么，好吗？"
D.Strings[98631]="伙计，我感觉我们要走运了！"
D.Strings[98632]="黑暗给了我们力量！呃……至少有时候会！"
D.Strings[98633]="黑暗将彻底吞噬你！"
D.Strings[98634]="睡吧……"
D.Strings[98635]="你抵抗不了的！睡吧！"
D.Strings[98636]="安静……梦境在召唤！"
D.Strings[98637]="没人能抵挡我们的力量！"
D.Strings[98638]="自然的敌人必将败亡。"
D.Strings[98639]="我们掌握着荒野的力量。"
D.Strings[98640]="不要挑战自然的守护者。"
D.Strings[98641]="我需要一点时间……来恢复。"
D.Strings[98642]="我得……暂时留下了……"
D.Strings[98643]="大自然是我们的盟友！"
D.Strings[98644]="感受自然的怒火吧！"
D.Strings[98645]="我是自然的守护者。"
D.Strings[98646]="荒野给了我力量！"
D.Strings[98647]="伊利达雷是不可阻挡的！"
D.Strings[98648]="我会掩护你的！"
D.Strings[98649]="我会与你并肩作战！"
D.Strings[98650]="你不是一个人在战斗！"
D.Strings[98651]="快攻击，敌人过来了！"
D.Strings[98652]="我的攻击快如闪电！"
D.Strings[98653]="很高兴能与你并肩作战。"
D.Strings[98654]="死得真快。"
D.Strings[98655]="敌人休想阻止我们。"
D.Strings[98656]="呃……我必须……撤退了……"
D.Strings[98657]="仇恨……吞噬了我的灵魂！"
D.Strings[98658]="我的怒火……无法遏制了！"
D.Strings[98659]="这里太安静了。这可有点不妙啊……"
D.Strings[98660]="我羡慕你的命运。"
D.Strings[98661]="我是死亡的使者！"
D.Strings[98662]="我坚持不下去了……放了我！"
D.Strings[98663]="你为什么要……这么……对我？"
D.Strings[98664]="即将发动攻击！"
D.Strings[98665]="我行动如风。"
D.Strings[98666]="蜘蛛！"
D.Strings[98667]="我的剑蓄势待发！"
D.Strings[98668]="我们是不可阻挡的。"
D.Strings[98669]="我们又干掉了一个敌人。"
D.Strings[98670]="我的伤……太重了……"
D.Strings[98671]="有个好像掉我头上了！弄走它！"
D.Strings[98672]="小意思。"
D.Strings[98673]="你的愿望就是我的命令。"
D.Strings[98674]="你休想逃出隐秘通途的手心！"
D.Strings[98675]="雪羽！攻击！"
D.Strings[98676]="干掉他们，雪羽！"
D.Strings[98677]="这是一座死城。我只渴望安宁。"
D.Strings[98678]="你将成为我的猎物！"
D.Strings[98679]="你逃不了的！"
D.Strings[98680]="我或许能在这里找到救赎。"
D.Strings[98681]="我会慢慢……好起来的……"
D.Strings[98682]="我得留下……"
D.Strings[98683]="现在我是个真正的猎人了！"
D.Strings[98684]="没有牺牲，就不会有进步。"
D.Strings[98685]="让我们干掉他们！"
D.Strings[98686]="这个交给我了！"
D.Strings[98687]="这可真刺激！"
D.Strings[98688]="我想找个助手。我想你应该能行。"
D.Strings[98689]="呃……别担心我……我会赶上你的……应该会。"
D.Strings[98690]="啊……好……痛啊……"
D.Strings[98691]="唔……我得休息一下。你先走吧！"
D.Strings[98692]="在这片圣地中，请谨言慎行。"
D.Strings[98693]="一枪爆头！"
D.Strings[98694]="我看到目标了！"
D.Strings[98695]="那就去吧。做你能做的。"
D.Strings[98696]="这个人头归我了！"
D.Strings[98697]="你不是提瑞斯秘法会的对手！"
D.Strings[98698]="在我们面前颤抖吧！"
D.Strings[98699]="见证大法师的力量吧！"
D.Strings[98700]="我们的敌人倒下了！"
D.Strings[98701]="毫无挑战性可言！"
D.Strings[98702]="不出我所料，我们胜利了。"
D.Strings[98703]="我伤得很重……你走吧，别管我。"
D.Strings[98704]="好痛啊。我需要一点时间来恢复！"
D.Strings[98705]="感受卡雷苟斯的怒火吧！"
D.Strings[98706]="吼！！"
D.Strings[98707]="去吧，动作快点！"
D.Strings[98708]="面对伟大的米尔豪斯吧！"
D.Strings[98709]="我要消灭、分解并灭绝……我说了消灭吗？"
D.Strings[98710]="我必须解开这些秘密……"
D.Strings[98711]="我都没出汗呢！"
D.Strings[98712]="我还杀过比这更大的蟑螂呢！"
D.Strings[98713]="我闭着眼睛都能做到！"
D.Strings[98714]="一个微不足道的小挫折而已……我得……喘口气了。"
D.Strings[98715]="我流血了吗？这是……血吗？"
D.Strings[98716]="这边，笨蛋！"
D.Strings[98717]="外表会欺骗你！"
D.Strings[98718]="嘿！这边！用力打我呀！"
D.Strings[98719]="血骑士们！呈攻击阵型！"
D.Strings[98720]="血骑士们！靠近我！"
D.Strings[98721]="正义是站在我们这边的！"
D.Strings[98722]="为荣耀而战吧！"
D.Strings[98723]="正义必胜！"
D.Strings[98724]="我的伤……太重了！"
D.Strings[98725]="我会好起来的……你走吧，别管我！"
D.Strings[98726]="愿圣光怜悯你们的灵魂。"
D.Strings[98727]="圣光净化一切！"
D.Strings[98728]="没有人能逃过圣光的制裁！"
D.Strings[98729]="那可是好多蜘蛛！"
D.Strings[98730]="圣光将惩戒我们的敌人！"
D.Strings[98731]="我们的敌人必将一一倒下！"
D.Strings[98732]="圣光眷顾了我们。"
D.Strings[98733]="我很乐意撕碎它们！"
D.Strings[98734]="我伤的很重……得休息一下……"
D.Strings[98735]="我得休息一下……别管我了，你走吧！"
D.Strings[98736]="这应该很刺激！"
D.Strings[98737]="我无所畏惧！"
D.Strings[98738]="精彩的战斗！"
D.Strings[98739]="这些伤……我会好的……"
D.Strings[98740]="哈……这些伤会成为……漂亮的疤痕……"
D.Strings[98741]="科洛米尔！"
D.Strings[98742]="雷霆！听从我的召唤！"
D.Strings[98743]="为了奥丁！！"
D.Strings[98744]="来面对我吧！"
D.Strings[98745]="尝尝钢铁的力量吧！"
D.Strings[98746]="倒在我的钢铁意志之下吧！"
D.Strings[98747]="今天是我们的胜利日！"
D.Strings[98748]="我会好起来的……你走吧……"
D.Strings[98749]="啊啊啊……"
D.Strings[98750]="一点小伤而已……"
D.Strings[98751]="在北地的寒风面前颤抖吧！"
D.Strings[98752]="感受霍迪尔的怒火吧！"
D.Strings[98753]="马迪亚斯·肖尔的消息传来，整个大厅都陷入了寂静。"
D.Strings[98754]="没人能挑战无冕者！"
D.Strings[98755]="看看我的本事吧！"
D.Strings[98756]="我刚开始热身呢！"
D.Strings[98757]="我受伤了……让我……喘口气……"
D.Strings[98758]="不……我还不想……死……"
D.Strings[98759]="让我来帮你扳回一城吧！"
D.Strings[98760]="刺客从来都不缺活儿干！"
D.Strings[98761]="我们是暗影中的利刃！"
D.Strings[98762]="我要大开杀戒了。"
D.Strings[98763]="听我口令。"
D.Strings[98764]="杀戮并不有趣……这只是我们必须完成的工作而已。"
D.Strings[98765]="该死……"
D.Strings[98766]="所有人都将……畏惧我们。"
D.Strings[98767]="我必须暂时……撤退了……"
D.Strings[98768]="这个伤口很深……我得休息一下。"
D.Strings[98769]="不留残骸。"
D.Strings[98770]="干掉目标。"
D.Strings[98771]="你的弱点就是我们的优势！"
D.Strings[98772]="战局将从此扭转！"
D.Strings[98773]="臣服于黑锋骑士团吧！"
D.Strings[98774]="我就在你身边。"
D.Strings[98775]="黑锋骑士团团结一致。"
D.Strings[98776]="黑锋骑士团必胜！"
D.Strings[98777]="我受伤了……需要治疗……"
D.Strings[98778]="继续前进吧，别管我……完成我们的……任务……"
D.Strings[98779]="腐肠腐肠！"
D.Strings[98780]="烂！肠！"
D.Strings[98781]="腐肠！！！！"
D.Strings[98782]="骑士们！出发！"
D.Strings[98783]="在四骑士面前颤抖吧！"
D.Strings[98784]="碾碎我们的敌人吧！"
D.Strings[98785]="阿达尔！赐予我们力量吧！"
D.Strings[98786]="圣光照耀着我们！"
D.Strings[98787]="纳鲁永远与我们同在。"
D.Strings[98788]="暗影指引着我。"
D.Strings[98789]="你的意志必将臣服于我！"
D.Strings[98790]="暗影吞噬了你。"
D.Strings[98791]="让死神抓走你！"
D.Strings[98792]="只是有点痛……我会赶上你的……"
D.Strings[98793]="哼……呃……我会好起来的。"
D.Strings[98794]="死亡……老朋友……今天可不行……"
D.Strings[98795]="我们为圣光而战！"
D.Strings[98796]="我是圣光的化身！"
D.Strings[98797]="我将净化这个世界！"
D.Strings[98798]="我保卫了圣光。"
D.Strings[98799]="圣光长存。"
D.Strings[98800]="我们胜利了。"
D.Strings[98801]="我的光熄灭了……"
D.Strings[98802]="我的力量消散了……"
D.Strings[98803]="我还会回来的……"
D.Strings[98804]="圣光将压倒我们的敌人！"
D.Strings[98805]="我们的灵魂之火熊熊燃烧！"
D.Strings[98806]="沐浴在圣光之中吧。"
D.Strings[98807]="没用的蝼蚁。我要让你们求死不能！"
D.Strings[98808]="不！要塞必将沦陷！"
D.Strings[98809]="看着自己珍爱的世界在眼前崩塌，你们一定很无助吧？"
D.Strings[98810]="你们应该认清自己的地位，凡人。"
D.Strings[98811]="你们的存在毫无意义！准备咽气吧，凡人！"
D.Strings[98812]="疾病能让敌人衰弱，以便你用强大的近战攻击了结他们。"
D.Strings[98813]="但你最强大的盟友还是死亡本身。亡者复生可以把尸体复活为你的食尸鬼爪牙。"
D.Strings[98814]="你应该随时保持爪牙的存在。"
D.Strings[98815]="爆发可以造成持续伤害并让附近的敌人染上恶性瘟疫。"
D.Strings[98816]="脓疮打击可以造成伤害，并对你的目标造成溃烂之伤。"
D.Strings[98817]="脓疮打击后紧接天灾打击，很少有敌人能招架这一套连环猛击。"
D.Strings[98818]="而我们就在最中心……"
D.Strings[98819]="使用枯萎凋零腐化你脚下的土地，对影响范围内的所有敌人造成伤害，并让你的部分攻击技能获得强化效果，可以打击额外的目标。"
D.Strings[98820]="死亡之握能让你抓取远处的目标，并将其拉到身边。没有敌人能逃脱你冰冷的魔爪！"
D.Strings[98821]="来自幽暗城的援军快到了！"
D.Strings[98822]="什么会需要这么大的力量？也许是一件武器？"
D.Strings[98823]="而那些守着它的卫兵……他们已经守了多久了……"
D.Strings[98824]="<叹气。>现在我的疑问更多了！"
D.Strings[98825]="真是一个完美的避难所。在回苏拉玛前，我就暂时住这里吧。"
D.Strings[98826]="但首先，我需要盟友。"
D.Strings[98827]="|TInterface\\Icons\\ability_siege_engineer_overload:20|t拉克斯的伐木机已经|cFFFF0404|Hspell:219614|h[失控！]|h|r！快跳上飞艇！"
D.Strings[98828]="啊，书总算到了……还是我那爱管闲事的老熟人带来的！准备倒向胜者了吗，“英雄”？"
D.Strings[98829]="你们俩收集神器的表现都很好，一定会在暗影议会里有一席之地的。"
D.Strings[98830]="有了这些，我们就能强化这座传送门，打开通往无数恶魔世界的道路。燃烧军团的全部力量都将倾泻到这个可悲的星球上！"
D.Strings[98831]="我会穿过传送门，去阿古斯充当稳定锚点。你们要集中能量，让它们通过权杖，扩大裂口，制造无数传送门。"
D.Strings[98832]="呃……伟大的主人！该由谁来执掌权杖呢？"
D.Strings[98833]="你掌握的冰霜之力能让你召唤一只水元素，我们就从它开始吧。"
D.Strings[98834]="寒冰箭有时会触发寒冰指效果，这也能大幅提高冰枪术的伤害。我们来试试吧。"
D.Strings[98835]="|TInterface\\Icons\\Ability_Hunter_RapidRegeneration:20|t斯纳格开始施放|cFFFF0404|Hspell:219848|h[弹幕]|h|r！快跳到地面上去！"
D.Strings[98836]="霍迪尔，等等！"
D.Strings[98837]="但你要小心，它会攻击沿途的所有敌人，而不仅是你的目标。"
D.Strings[98838]="啊，我只需要一个人来主持仪式。所以你们快“讨论”一下这个问题吧，做好准备……"
D.Strings[98839]="在这种情况下，我们就需要一些额外的防护措施了。寒冰护体可以制造一面冰盾，吸收敌人的攻击。"
D.Strings[98840]="使用了它，敌人就无法选中你，从而让你逃离战场。但要小心！它的效果持续不了多久。"
D.Strings[98841]="但用双腿来跑未免太普通了！幸好，你有一个很适合魔法大师身份的法术。"
D.Strings[98842]="闪现术能让你传送一小段距离，躲开威胁或靠近敌人。"
D.Strings[98843]="冰霜新星能将附近的敌人冻结在原地，让你拉开距离，更安全地消灭他们。现在，我们先练习冻结敌人。"
D.Strings[98844]="看来我们最终还是敌人。可惜，你本可以成为出色的仆人！"
D.Strings[98845]="你能使用名为暴风雪的强大法术，用寒冰碎片攻击目标区域。这个名字不错吧？"
D.Strings[98846]="我已经在修了！等我们的朋友检测完，我就能接通第一条线路。"
D.Strings[98847]="你还没有见识到我真正的实力呢！"
D.Strings[98848]="居然被……下等生物……杀了……"
D.Strings[98849]="欧库勒斯，你能修好大厅的传送器吗？"
D.Strings[98850]="我早料到你会胜利了。我想过帮助奥莱利斯对付你，可你的头脑或许还有点用处。你就把这当成……一次提拔吧。别让我失望！"
D.Strings[98851]="时间到了！念咒吧，将权杖的力量集中到祭坛上。今天，我们将带来世界末日！"
D.Strings[98852]="你还可以变成枭兽形态，提高你的伤害和防御。"
D.Strings[98853]="这些攻击能够造成持续伤害，是很好的起手技能。"
D.Strings[98854]="星涌术会消耗星界能量，用阳炎之怒积累储备吧。"
D.Strings[98855]="超凡之盟能够调动星体，在短时间内提高你的日光和月光法术的伤害。"
D.Strings[98856]="现在，我们可以修复古代传送网了。如果你在外面找到我的旧道标，一定要激活它们！"
D.Strings[98857]="冷血的杜贡是我们的宿敌。有人在雪盲崖发现了他。去解决这个怪物吧。"
D.Strings[98858]="欧库勒斯结局对话。"
D.Strings[98859]="塔莉萨结局对话。"
D.Strings[98860]="杜贡真应该躲在自己的山头上的。谢谢你，勇士，多亏了你，我的人民更加安全了。"
D.Strings[98861]="你的死……会很壮观。"
D.Strings[98862]="明月打击不但可以直接对你的目标造成伤害，还能伤害附近的敌人。"
D.Strings[98863]="斜掠可以让你的目标流血，持续伤害他们。"
D.Strings[98864]="你的“撕碎”技能还可以对流血的目标造成额外的伤害，所以这两个技能应该搭配使用。"
D.Strings[98865]="蠢货！你的背叛只能拖延注定的命运！等你熟悉的一切都毁灭后，我要把你关进牢笼，看着你崩溃。"
D.Strings[98866]="猛虎之怒可以恢复一些能量值，并在一小段时间内，令你的伤害提高。"
D.Strings[98867]="作为凶猛撕咬的替代技能，割裂可以对你的目标造成持续的流血伤害，而且它在战斗早期很适合用来消耗连击点数。"
D.Strings[98868]="和凶猛撕咬一样，割裂也是终结技，最好在拥有5个连击点数时使用。"
D.Strings[98869]="生存本能可以在短时间内降低你所受的伤害。将它留到紧急情况下再使用吧！"
D.Strings[98870]="横扫也能对附近所有的敌人造成伤害，但如果你的目标在流血，那它就能造成更多的伤害。所以你最好将痛击和横扫搭配使用。"
D.Strings[98871]="霍迪尔总是太过冲动了。\n\n不过他对你的判断是正确的。我从没想到过一介区区凡人居然能够配得上奥丁的祝福。你真是个难解之谜，$n。"
D.Strings[98872]="痛击可以对附近所有的敌人造成伤害，并使其流血一小段时间。"
D.Strings[98873]="该走了，朋友！这边！"
D.Strings[98874]="急奔能在短时间内大幅提高你的移动速度。它无法频繁使用，所以把它留到紧急情况下用吧。"
D.Strings[98875]="当你受伤时，用愈合来恢复你的生命值。"
D.Strings[98876]="凶暴野兽能让你召唤附近的一头野兽加入战斗并攻击你的目标一小段时间。"
D.Strings[98877]="你！外来者！帮个忙，踩到另一个开关上去，好吗？"
D.Strings[98878]="好了，总算打开了。"
D.Strings[98879]="别担心，你的宠物结实着呢！使用杀戮命令能让宠物进行强力攻击，这也是个很好的起手技能。"
D.Strings[98880]="现在，我要杀了你。有遗言吗？"
D.Strings[98881]="治疗宠物可以让你为受伤的宠物治疗。"
D.Strings[98882]="多重射击可以让你向目标附近的数个敌人发射箭矢。"
D.Strings[98883]="霍迪尔总是太过冲动了。\n\n不过他对你的判断是正确的。我从没想到过一介凡人居然能够配得上奥丁的祝福。你真是个难解之谜，$n。\n\n等你准备好以后，我会把你传送出去的。"
D.Strings[98884]="使用这一技能还能让你的宠物顺劈数个敌人。"
D.Strings[98885]="啊，我认得这个徽记。看来塔莉萨雇了个外来者……我们已经落魄成这样了吗？"
D.Strings[98886]="站到永恒狩猎祭坛前来吧。让它为你的武器灌注力量，让它变得空前强大！"
D.Strings[98887]="他们消失了……传送门关闭了！"
D.Strings[98888]="你干得很好。我不该质疑父亲的选择。如果你愿意帮我们找到霍迪尔，奥杜尔的大军就是你的后盾。"
D.Strings[98889]="这可以积累真气，这种资源能让你施放出最强大的攻击。"
D.Strings[98890]="它的攻击力要比猛虎掌高得多，所以你可以使用幻灭踢来消耗多余的真气。"
D.Strings[98891]="你已声名远扬，你那件可怕神器的力量也在随之增长。"
D.Strings[98892]="它还能攻击目标附近的其他敌人。所以你要尽量多用怒雷破，或是在面对多个敌人时使用。"
D.Strings[98893]="使用翔龙在天可以扑向你的目标，而在半空中再次使用，则可以结束飞行，对附近的敌人造成伤害。"
D.Strings[98894]="此时，你可以让一个敌人瘫痪，使他退出战斗！分筋错骨可以让一个敌人昏迷一小段时间，但受到任何伤害都会令其恢复意识。"
D.Strings[98895]="如果你发现自己要面对三个或者更多的对手，你可以运用自己的精魂造出分身，自己做自己的盟友！你的分身会自动攻击敌人。"
D.Strings[98896]="你可以对看不顺眼的人使用它，不过最好还是留着它对付最强大的敌人吧！"
D.Strings[98897]="你的主要移动手段是滚地翻，它能让你沿着你的移动方向快速翻滚一段距离。"
D.Strings[98898]="你应该尽量多使用它。"
D.Strings[98899]="在开始前，我们要先给你的武器涂上毒药。"
D.Strings[98900]="在熔炉前举起战刃，让它为这件武器注入力量吧！"
D.Strings[98901]="达里安·莫格莱尼！这是什么意思？！"
D.Strings[98902]="战斗中最好的起手技能是锁喉，这个带有削弱效果的流血攻击能让敌人受到持续伤害。"
D.Strings[98903]="用5个连击点数施放割裂时，你能造成强力的流血攻击，让敌人受到持续伤害。"
D.Strings[98904]="猩红之瓶是一种炼金混合物，能为你恢复一部分生命值。"
D.Strings[98905]="此时，你可以使用暗影步，它能让你保持潜行状态，从容地发起攻击。"
D.Strings[98906]="刀扇可以对你周围所有的敌人造成伤害。它每击中一个敌人，还能产生一个连击点数。"
D.Strings[98907]="烈焰震击能点燃敌人，让他们在你施放其他法术时持续燃烧。"
D.Strings[98908]="在敌人受到烈焰震击影响时使用熔岩爆裂，能提高它的伤害。"
D.Strings[98909]="目标变成青蛙后，将暂时无法攻击你。一旦遭到攻击，敌人就会变回原形。"
D.Strings[98910]="元素不仅会破坏，它们还有修复的能力。"
D.Strings[98911]="我们要试用的第一个攻击技能是火舌。它能用烈焰点燃你的武器，烧灼敌人。"
D.Strings[98912]="熔岩猛击会使用漩涡值为你的副手武器注入熔岩，让你打出强力一击。"
D.Strings[98913]="在触发风暴使者后使用风暴打击。"
D.Strings[98914]="毁灭闪电会对你面前所有的目标造成伤害。它击中多个敌人还能强化你的武器，造成更多的伤害！"
D.Strings[98915]="如果你在战斗中遇到了麻烦，你可以召唤两头野性狼魂来为你作战。"
D.Strings[98916]="<叹气。>好吧，我就是瓦尔托伊。"
D.Strings[98917]="赶紧跑吧。但你最终还是得死。"
D.Strings[98918]="我感觉我们中间有个密探。"
D.Strings[98919]="唔。就让我的猎物再等等吧……"
D.Strings[98920]="很好。享受这短暂的……自由吧。"
D.Strings[98921]="唔。我很快就会找到你的……"
D.Strings[98922]="你的攻击包括能累积和消耗神圣能量的远程法术和近战攻击。"
D.Strings[98923]="你对圣光的虔诚使你能够向敌人投出强大的审判之锤。"
D.Strings[98924]="一旦敌人进入攻击范围，你可以使用十字军打击进行攻击。"
D.Strings[98925]="圣盾术可以防止攻击伤害到你。"
D.Strings[98926]="暗言术：痛能用暗影能量污染敌人，缓慢但持续地伤害他们。"
D.Strings[98927]="这是你最常用的伤害法术，最好在无法使用苦修时使用它。"
D.Strings[98928]="真言术：盾就是你最实用的防御技能之一。在激活后，它能吸收所有的伤害。"
D.Strings[98929]="在战斗中，千万别忘了维持你的护盾。"
D.Strings[98930]="幸好，你对这种情况并非束手无策。心灵尖啸能恐吓附近的对手，令他们因恐惧而逃跑。"
D.Strings[98931]="但这对你来说不算什么。圣光给了你为自己和盟友治疗的能力。"
D.Strings[98932]="痛楚会造成越来越高的伤害，是一个很好的起手技能。"
D.Strings[98933]="腐蚀术这个法术会影响其目标，在效果持续期间造成暗影伤害。"
D.Strings[98934]="吸取灵魂是你最常用的攻击技能，能伤害敌人并为你治疗。"
D.Strings[98935]="痛苦无常是个强大的法术，能像痛楚和腐蚀术一样造成持续伤害，但灵魂碎片能让它的伤害更高。"
D.Strings[98936]="你掌握的黑暗魔法还能召唤一个恶魔来为你效劳。"
D.Strings[98937]="你可以用恐惧唤醒他们内心的噩梦，令他们暂时失去战斗力。"
D.Strings[98938]="它无法频繁使用，所以要留在紧急情况下使用。"
D.Strings[98939]="使用你的灵魂石技能将你的灵魂保存起来。别担心，你不会用到它的！但保存好你的灵魂后，你就可以随时死而复生了。"
D.Strings[98940]="马迪亚斯·肖尔带领我们军情七处小队对这座岛进行了秘密侦察。我们正在等待撤离。"
D.Strings[98941]="致死打击就是这样一种技能。尽量多使用它吧。"
D.Strings[98942]="乘胜追击只能在这段时间内使用，它能在你攻击新敌人时为你恢复生命值。"
D.Strings[98943]="顺劈斩也能让你同时攻击前方的数个敌人。顺劈斩每击中一个目标，你的下一个旋风斩就能造成更多的伤害！"
D.Strings[98944]="旋风斩能让你大幅度挥舞武器，在你周围的敌人中间掀起一阵腥风血雨。"
D.Strings[98945]="保护好她，我来治疗她的伤势！"
D.Strings[98946]="使用死亡之握将我的战士拉向你。"
D.Strings[98947]="%s倒下了！你的盟友撤退了。"
D.Strings[98948]="使用假死骗过我的战士，打断他的攻击。"
D.Strings[98949]="使用冰霜新星冻结我的战士。"
D.Strings[98950]="使用消失躲过我的战士。"
D.Strings[98951]="把我的战士变成青蛙！"
D.Strings[98952]="这个技能无法频繁使用，要留在紧急情况下使用。"
D.Strings[98953]="使用恐惧威吓我的战士。"
D.Strings[98954]="许多法术都会消耗大量法力值。但你能够巧妙地回避这一问题。"
D.Strings[98955]="看！光影祭坛将为你的武器注入力量！"
D.Strings[98956]="圣光随时为你效劳。"
D.Strings[98957]="呃。这里到底发生什么鬼事情了？"
D.Strings[98958]="愿暗影拥抱你。"
D.Strings[98959]="我还是走吧。我可不想死在这里。"
D.Strings[98960]="使用纠缠根须将我的战士定身。"
D.Strings[98961]="让我们的宿敌在你释放出的怒火和毁灭中颤抖吧！"
D.Strings[98962]="$n，到我这儿来。"
D.Strings[98963]="这位是部落最伟大的勇士，是连克强敌，为我们夺取过无数胜利的英雄。"
D.Strings[98964]="他们手中的上古神兵会将恐惧植入每个胆敢威胁我们的敌人心中。"
D.Strings[98965]="这次招募完成地很快。不过以后招募灰舌战士所需的时间就比较长了。"
D.Strings[98966]="你好，亲爱的，很高兴见到你。\n\n我能帮你什么忙吗？"
D.Strings[98967]="你好，$n。为了达成互信，我想我应该解释一下。"
D.Strings[98968]="你说得对，把一切都告诉我吧，洛拉姆斯。"
D.Strings[98969]="该从哪儿说起呢？我想最重要的应该就是我和那个恶魔之间的战斗。"
D.Strings[98970]="污染者拉瑟莱克是负责征服诅咒之地的恐惧魔王。我去那里阻止他。可事情却没有按照我计划的那样发展。"
D.Strings[98971]="最后，污染者控制了我，而我则牺牲了自己，与他同归于尽了。我们的灵魂被困在了一把魔剑中，陷入了无尽的争斗。"
D.Strings[98972]="后来，那把剑被摧毁了。我们的灵魂逃了出来，却被送入了扭曲虚空。可是，拉瑟莱克的恶魔灵魂非常强大。和许多恐惧魔王一样，他逐渐生出了新的躯体。据说，只有在扭曲虚空里才能真正灭杀他们。"
D.Strings[98973]="在他的新躯体里，我们的灵魂仍然争斗不休。我占据了上风……至少在大部分时间里是如此，但偶尔还是会有反复。我们恶魔猎手早已习惯镇压内心的恶魔了。"
D.Strings[98974]="等我再次恢复意识时，我们已经被逐出了扭曲虚空，受到燃烧军团的征召来入侵艾泽拉斯。在邪焰隘口，我尽力阻挠了他们的行动。"
D.Strings[98975]="剩下的你都知道了。你的勇士赶来，找到了我，然后我就来到了这里。"
D.Strings[98976]="如果你愿意接受的话，我很乐意为你效劳。我拥有拉瑟莱克的全部知识。请让我帮助你对抗燃烧军团吧。"
D.Strings[98977]="你下来了吗？我们还有活儿要干呢！"
D.Strings[98978]="拜托！我们不能再等下去了！很安全的。我保证！"
D.Strings[98979]="这里都是我们的人。相信我！我们很安全。"
D.Strings[98980]="我不能再等下去了。必须找个人来修好这些切割者。"
D.Strings[98981]="我现在没空跟你胡扯。快下来！"
D.Strings[98982]="我不知道……我感觉不太安全。"
D.Strings[98983]="你上次也这么说，结果我差点被一头恶魔给活吃了！"
D.Strings[98984]="我只是，呃……想来看看这里是不是安全。对……已经安全了。"
D.Strings[98985]="我可不想死！"
D.Strings[98986]="万一他们又回来了怎么办？"
D.Strings[98987]="等着一切结束后再来找我吧，$n。霜狼氏族就需要你这样的$c。"
D.Strings[98988]="快，穿过我的传送门！快跑！"
D.Strings[98989]="到法尔多拉神殿来见我。为了保护未来，我们得研究历史。"
D.Strings[98990]="多年前，来自苏拉玛的流亡者定居于此。"
D.Strings[98991]="在这种状态下，阿坎多尔还能生长。"
D.Strings[98992]="我们得搞清上一棵阿坎多尔失败的原因。它的碎片或许会有答案。"
D.Strings[98993]="您好，感谢您参加《军团再临》内测！\n\n我可以为您提供职业大厅的各种物资。"
D.Strings[98994]="我需要职业大厅物资。"
D.Strings[98995]="|TInterface\\Icons\\creatureportrait_cyclone_nodebris:20|t%s使用|cFFFF0000|Hspell:212115|h[时空斩]|h|r打断了畸体！"
D.Strings[98996]="被你的武器砍中的魔蝠痛苦地尖叫起来！"
D.Strings[98997]="现在，这对匕首才真正配得上暗影中的王者！愿你的匕首悄无声息，一击毙命。"
D.Strings[98998]="你一直都是圣光的勇士。现在，你又有了一件配得上你高贵事业的武器！"
D.Strings[98999]="愿这把武器伴为你打开通往胜利的道路！"
D.Strings[99000]="你的武器中流转着自然的精华！在你手中，它将让威胁到艾泽拉斯的黑暗势力瑟瑟发抖！Andu-falah-dor！"
D.Strings[99001]="对！邪恶的荣耀在等着你！有了这件武器，你就能打垮燃烧军团！让基尔加丹都瑟瑟发抖！"
D.Strings[99002]="在这远离暗夜井的地方，我们必须接受一切能找到的魔力。"
D.Strings[99003]="看来塔莉萨和我想的一样——古老的魔网能量流能勉强糊口。"
D.Strings[99004]="我们只需要唤醒它们。"
D.Strings[99005]="你应该还记得，当时你也在场。"
D.Strings[99006]="你……你有发现了，对吧？"
D.Strings[99007]="能让你安宁下来的发现……"
D.Strings[99008]="向你致敬，勇士。"
D.Strings[99009]="<出发并加入突袭破碎海滩的战斗>"
D.Strings[99010]="让我们开始突袭破碎海滩吧！"
D.Strings[99011]="<这头狮鹫拍打着翅膀，期待着即将到来的战斗>"
D.Strings[99012]="谢谢你，大领主。我……被仇恨蒙蔽了。"
D.Strings[99013]="我的愚蠢葬送了许多人。我现在明白了，这不是正义之道。"
D.Strings[99014]="我们极度渴望的安宁。"
D.Strings[99015]="最重要的是你还活着，波鲁斯。来吧，让我们返回圣光之愿礼拜堂。"
D.Strings[99016]="不！霍迪尔！他们对你做了什么？！"
D.Strings[99017]="啊，一份适合女王的礼物。谢谢你……"
D.Strings[99018]="现在，阿坎多尔的力量属于我了！"
D.Strings[99019]="不！你做了什么？！"
D.Strings[99020]="来吧，我的孩子们！啃光他们的骨头吧！"
D.Strings[99021]="阿坎多尔会复活的！有了它的力量，我们就能返回地表了！"
D.Strings[99022]="谁都逃不出我的网！"
D.Strings[99023]="啊……我的战利品……它变沉重了……"
D.Strings[99024]="这颗种子正在苏醒。它渴了。"
D.Strings[99025]="这是阿坎多尔——来自古代法师的礼物。"
D.Strings[99026]="这是一棵树，吸取魔网的能量。它能带来生命……或毁灭。"
D.Strings[99027]="照料阿坎多尔是个重任——我们共同的重任。"
D.Strings[99028]="所以，这座大厅就是为它而建的……可这是什么东西？"
D.Strings[99029]="让我们继续研究我的神器吧。"
D.Strings[99030]="仇恨！！"
D.Strings[99031]="我们可是奥术大师，暗夜精灵。一棵树还是能搞定的。"
D.Strings[99032]="我看到你前往破碎群岛了。拜托，告诉我，你见过我丈夫吗？"
D.Strings[99033]="他的盒坠？你在哪儿找到的？\n\n不！我不相信！他一定还活着！\n\n塞德里克。噢，我亲爱的塞德里克，求你回到我身边。\n\n不要丢下我一个人……"
D.Strings[99034]="哼，真傲慢。你迟早会明白的。"
D.Strings[99035]="你认识这个盒坠吗？"
D.Strings[99036]="要把烧焦的盒坠交给阿兰娜吗？"
D.Strings[99037]="阿坎多尔能让你获得新生。你没有其他出路了。"
D.Strings[99038]="山谷行者结局对话。"
D.Strings[99039]="瓦尔托伊结局对话。"
D.Strings[99040]="阿坎多尔正处在关键阶段。"
D.Strings[99041]="如果没有足够的能量让它进化，它就会枯死。"
D.Strings[99042]="你能帮我修理装备吗？"
D.Strings[99043]="外来者，立刻去跟瓦尔托伊谈谈！"
D.Strings[99044]="你要激活剩下的能量流。"
D.Strings[99045]="所有能量流都激活并达到最大了！"
D.Strings[99046]="这还不够……"
D.Strings[99047]="瓦尔托伊，你能想办法再抽取一些力量吗？哪怕是一点点也好。"
D.Strings[99048]="唔……苏拉玛下方的主管道抽取量是我们十倍。"
D.Strings[99049]="如果能炸掉那条管道，从理论上说，能量就会涌回沙尔艾兰了。"
D.Strings[99050]="他们的术士从上方发动了攻击！"
D.Strings[99051]="怎么才能炸掉那条管道呢？"
D.Strings[99052]="来场魔力风暴也许行。"
D.Strings[99053]="魔力风暴，你疯了吗？"
D.Strings[99054]="对。但它能管用！我们制造一个扭曲力场，然后——"
D.Strings[99055]="不用跟我们说细节，去做就是了。我就指望你了。"
D.Strings[99056]="我听说了你们的疯狂计划。你们不会是想撇下我单干吧？"
D.Strings[99057]="我又不瞎。我能看到苏拉玛出了什么事。"
D.Strings[99058]="我不会袖手旁观。高风险才有高回报，所以我要加入。"
D.Strings[99059]="噢，还有，不用担心我的报酬——你们可以事后付款。"
D.Strings[99060]="大人！我们遭到了攻击……是……是黑锋骑士团！"
D.Strings[99061]="你们别想毁掉我的新宠物！被我教训过之后，你们就会向军团俯首称臣了！"
D.Strings[99062]="我们是来找提里奥·弗丁的遗体的。别惹出不必要的麻烦。"
D.Strings[99063]="你休想得逞，达里安。圣光绝不允许！"
D.Strings[99064]="击败那个艾瑞达女巫！这是拯救霍迪尔的最后机会！"
D.Strings[99065]="邪能……消失了……"
D.Strings[99066]="燃烧军团会付出代价的！"
D.Strings[99067]="我还以为你只对赚钱感兴趣。"
D.Strings[99068]="开始测量……"
D.Strings[99069]="准备就绪。我们拿到需要的坐标了。"
D.Strings[99070]="好了各位，靠紧点。别害羞，都抱在一起。"
D.Strings[99071]="唔……有点酸，还有点——噢，我的……就是它。"
D.Strings[99072]="我可以将你们传送过主防线。你们准备离开时，就激活这个道标，我就能拉你们回来。"
D.Strings[99073]="接下来这点很重要——一旦魔力风暴爆发，就会对我的传送产生严重的干扰。你得在风暴爆发前离开！"
D.Strings[99074]="进去，放下设备，然后在它爆炸前出来。这算不上复杂。"
D.Strings[99075]="但这很重要。如果我们失败，苏拉玛就完了。"
D.Strings[99076]="看来你们的……死亡领主……终于到了。"
D.Strings[99077]="注意你的语气，加林。"
D.Strings[99078]="你是在跟自己不了解的力量作对！"
D.Strings[99079]="非常感谢你的帮助。"
D.Strings[99080]="先休息，再报仇。"
D.Strings[99081]="继续战斗。我们决不能认输。"
D.Strings[99082]="战斗才刚刚开始。"
D.Strings[99083]="你的援助很及时。"
D.Strings[99084]="部落必胜。"
D.Strings[99085]="是的，快到了。"
D.Strings[99086]="这看着不像真的Y号水渠。你确定那老家伙能行吗?"
D.Strings[99087]="我从来没遇到过撬不开的锁。"
D.Strings[99088]="只要给我一点时间。"
D.Strings[99089]="快！把魔力风暴发生器放在水渠附近！"
D.Strings[99090]="你准备好前往黑鸦堡垒了吗？"
D.Strings[99091]="动作快点！有大批卫兵冲过来了。"
D.Strings[99092]="情况有点不对……时光迁跃定序器——"
D.Strings[99093]="引线坏了。我们必须手动触发法力风暴。"
D.Strings[99094]="救命！我打不过这些怪物！"
D.Strings[99095]="我太虚弱了，保护不了自己。救命！"
D.Strings[99096]="我们必须赶去目的地，而且要快。"
D.Strings[99097]="你要保护我！"
D.Strings[99098]="请说得通俗点。"
D.Strings[99099]="等等，我们不是该在风暴爆发“前”离开吗？"
D.Strings[99100]="我们别无选择，必须完成这个任务。"
D.Strings[99101]="我们只需要坚持到风暴结束就行！"
D.Strings[99102]="说得轻巧……"
D.Strings[99103]="你要来点魔力果汁吗？我喝饱了。"
D.Strings[99104]="想跟我们玩吗？但你得扮坏人。"
D.Strings[99105]="哇，你真高！"
D.Strings[99106]="我没闯祸，对吧？"
D.Strings[99107]="天空真漂亮！"
D.Strings[99108]="我是铁炉堡之子，你休想打倒我！尝尝炮弹吧！"
D.Strings[99109]="你就这点本事吗？我可以这样打上一整天！"
D.Strings[99110]="魔力风暴更猛了！我们得关掉那个东西！"
D.Strings[99111]="我们已经没希望了，你还不明白吗？"
D.Strings[99112]="谢谢……你……"
D.Strings[99113]="这太危险了！魔力洪流会把我们撕成碎片的！"
D.Strings[99114]="这是你们欠我的……"
D.Strings[99115]="阿鲁因！不！！"
D.Strings[99116]="欧库勒斯，让我们离开这儿！"
D.Strings[99117]="呃……我们活下来了……"
D.Strings[99118]="阿鲁因人呢？！"
D.Strings[99119]="<咳嗽>嗯……"
D.Strings[99120]="别说话！你受伤了——"
D.Strings[99121]="嘿……<咳嗽>告诉凡瑟尔……我很感谢……他……"
D.Strings[99122]="我们大功告成了……<喘气>对吧？"
D.Strings[99123]="是你。你救了我们。求你了……好好休息吧。"
D.Strings[99124]="来吧……我们去看看其他人。"
D.Strings[99125]="祝你拥有美好的一天，$n。无冕者的事务还算顺利吧？"
D.Strings[99126]="看。古代法师的礼物。"
D.Strings[99127]="为了实现无冕者的目标，我随时可以前往任何地方做任何事。"
D.Strings[99128]="阿坎多尔不仅能滋养你。它枝头的果实，能真正救赎你。"
D.Strings[99129]="$n，对吧？我听维库人谈论过你。$b$b这些山头已经平静下来了。稍后再回来跟这座半岛的野兽战斗，证明自己吧。"
D.Strings[99130]="渡鸦之眼是破译军情七处信件的关键。"
D.Strings[99131]="干得好！看这边，$n。"
D.Strings[99132]="这些魔网能量球似乎遵循着某种运动轨迹？我很好奇它们会指向哪里？"
D.Strings[99133]="你去调查一下如何？"
D.Strings[99134]="把他们弄上船。灵魂引擎需要燃料！"
D.Strings[99135]="别哭哭啼啼的！你们将为伟大的事业献身。"
D.Strings[99136]="真是了不起，$n！"
D.Strings[99137]="军团感谢你们的牺牲。你们应该自豪！"
D.Strings[99138]="放心好了，没人会想你们的。"
D.Strings[99139]="接着走。我们不能让灵魂引擎久等。"
D.Strings[99140]="我们为这棵树付出了极高的代价……你确定它能养活我们吗？"
D.Strings[99141]="这条浅浅的河谷中栖息着山羊、雄鹿、座狼还有巨熊。这些野兽的确很凶猛，但如果你能展现出足够的实力，就能驯服它们。$b$b战胜那些野兽，它们就会服从你。骑上它们，你就能把敌人撞到山崖下面去了。$b$b但你要小心风暴之爪，它就栖息在风暴之触的乱岩之间。很多人都说他是不可能被驯服的。许多人都尝试过，可他们都死了。"
D.Strings[99142]="$n，你终于来风暴之触半岛证明自己了！你已经展现过自己的勇气。但在这里，光有勇气是不够的。$b$b这座峡谷里的野兽可不在乎你往日的英勇事迹。它们只看重力量。$b$b现在，像你这样的英雄们正在试图驯服这些野兽，并在战斗中一较高下。你打算接受挑战吗？"
D.Strings[99143]="太令人震惊了。"
D.Strings[99144]="整本日记都写满了这座洞穴对当地的动植物造成的影响，但其中有几条记载吸引了你的眼球。\n\n第五条：\n这座洞穴里的成分很有趣。我从工作室里带来了一些水晶，并将它们放在各个地点，想看看这里的能量会对它们造成什么影响。 \n\n第十七条： \n在与水晶共振后，我就能制造出抵消一切魔法的能量护盾。这个发现足以制造出一支无敌的大军！ \n\n第二十三条：\n这种屏障也不是完美无缺的。在与所有三颗水晶共振后，其他使用者就能集合他们的力量抵消屏障。在向上级展示成果之前，我必须想办法解决这个缺陷。"
D.Strings[99145]="大领主，斥候说巴纳扎尔就在山谷里。快行动吧，我们得堵住他！"
D.Strings[99146]="波鲁斯！"
D.Strings[99147]="我们得找到肖尔，这才能证明迪瑟洛克是个冒牌货。"
D.Strings[99148]="机会来了！快用祭坛召唤坏传送门，别召唤好的！快！"
D.Strings[99149]="勇士们，你们成功了！我感觉古尔丹的仪式力量正在增长，我们得快一点了。我可以把你们传送回暗夜要塞。你们准备好了吗？"
D.Strings[99150]="我想前往群星庭院（地下城）。"
D.Strings[99151]="你休想干扰我的研究！"
D.Strings[99152]="或许这会是一条新出路……"
D.Strings[99153]="可怜虫……尖叫着去死吧！"
D.Strings[99154]="|TInterface\\Icons\\shaman_pvp_lightninglasso:20|t%s正在施放|cFFFF0000|Hspell:220101|h[死亡之箭]|h|r！快打断它！"
D.Strings[99155]="我要感谢你，外来者。"
D.Strings[99156]="啊，圣光的守护者来了。我们等候多时了。"
D.Strings[99157]="到此为止了，巴纳扎尔。我要为死去的同胞讨回公道！"
D.Strings[99158]="你要的是公道……还是复仇，圣骑士？仇恨可是条不归路。"
D.Strings[99159]="啊啊啊！！！啊啊啊！！！"
D.Strings[99160]="可怜虫。贾沃克斯，杀了他，但别让他死的太快。"
D.Strings[99161]="喂食时间到了，我的宠物！"
D.Strings[99162]="快来吃新鲜的肉！"
D.Strings[99163]="来补充邪能吧……"
D.Strings[99164]="比死亡更可怕的命运在等着你，小德莱尼！"
D.Strings[99165]="这家伙会成为猎犬的美餐！"
D.Strings[99166]="慢点吃，我的宠物！"
D.Strings[99167]="我们即将迎来夜之子的新纪元。"
D.Strings[99168]="没有你，这一切都不可能实现。"
D.Strings[99169]="现在，我们要集中全部力量。等时机到来时，我们就会召唤你来帮助我们解放苏拉玛。"
D.Strings[99170]="<咳嗽。>阿鲁因，是你吗？这里太黑了……"
D.Strings[99171]="我明白……他从来都不懂得明哲保身……"
D.Strings[99172]="谢谢你……我会记住的。"
D.Strings[99173]="去邪魂堡垒周围放一些炸药分散注意吧。我在那里等你。"
D.Strings[99174]="外界的可怕阳光刺伤了你的巨鼠的眼睛！快返回下水道！"
D.Strings[99175]="你好，大祭司。我能为你做些什么吗？"
D.Strings[99176]="风云汇聚……"
D.Strings[99177]="惊天一击！"
D.Strings[99178]="抱歉，英雄。我可不能冒着破产的危险留下来。等这里安全了以后我再来吧。"
D.Strings[99179]="我们撤到了水晶大厅北边倒塌的尖塔这里。我们正在抵挡恶魔的强袭，但防线正在迅速崩溃！"
D.Strings[99180]="这些助祭会帮上大忙的。"
D.Strings[99181]="不要妄下结论，阿隆索斯。我们得搞清楚这个暗影牧师说的是不是真的。"
D.Strings[99182]="又是暗影牧师的连篇鬼话。我一点儿都不吃惊。如果你过分依赖虚空，就一定会变成这样。"
D.Strings[99183]="我很乐意为你效劳。"
D.Strings[99184]="干掉他们！快！"
D.Strings[99185]="快动起来，帮我们一把。杵在这儿对你对大家都没有任何好处。"
D.Strings[99186]="什么？谁派你来的？我让他们派出最优秀的$c，他们就派了你来？$B$B那好吧……你最好赶紧行动起来。这还有一大堆恶魔呢，别缩手缩脚的了。"
D.Strings[99187]="做好准备！它过来了！"
D.Strings[99188]="知道吗，它们在嘲讽我们。是暗影。它们看到了我们的末日。"
D.Strings[99189]="没有牺牲，这场战争就无法获胜。提里奥明白自由的代价。"
D.Strings[99190]="提里奥就在下方的勇士大厅里。我们会尽快追上你的，死亡领主。"
D.Strings[99191]="恶魔杀害了我的大部分萨满。我们退到了这里，准备背水一战。$B$B<努波顿叹了口气。>$B$B如果你是来帮忙的，那就做好打硬仗的准备吧，朋友！$B$B我好像听到又来了一支大军。你准备好了吗？"
D.Strings[99192]="我准备好了，努波顿！让他们来吧！"
D.Strings[99193]="你们听不到它们的声音，对吗？它们在狂笑……在警告我们。末日即将来临。"
D.Strings[99194]="虚空在呢喃着我们的命运，那是可怕的死亡！为你所爱的人们点一根蜡烛吧，牧师，因为末日已经来临，我们无处可逃。"
D.Strings[99195]="又干掉了一个！干得好。现在，出去找到剩下的敌人！这附近多的是。"
D.Strings[99196]="我想他们是想杀了我！"
D.Strings[99197]="别去打扰我的客人，他们在游览动物园呢。否则我只能干掉你了。"
D.Strings[99198]="东问西问只会害你送命。让我给你演示一下吧！"
D.Strings[99199]="喔唷！这下肯定要留疤了。我还是给自己治疗一下吧。"
D.Strings[99200]="唔……我得去缝两针了。我会在战斗结束之前回来的！"
D.Strings[99201]="我完全没有准备！我得休息一下了。"
D.Strings[99202]="你管那些玩意儿叫什么？我没想到会这样！"
D.Strings[99203]="看来我还得再练练。"
D.Strings[99204]="我这把骨头就像好几年没动过了似的！来吧，让我们找个蜥蜴看不见的地方谈谈。"
D.Strings[99205]="把你们的力量给我！"
D.Strings[99206]="强化你们主人的力量吧！"
D.Strings[99207]="别客气，$n。一些新鲜的补给品或许能让我们的部队振作起来。我会努力收集一些的。"
D.Strings[99208]="该下锅了！"
D.Strings[99209]="%s紧张地着环顾四周，磨蹭了许久才进入田野。"
D.Strings[99210]="我们夺回了东点哨塔！继续努力。我们必须夺回属于自己的土地。"
D.Strings[99211]="你好！乌瑞恩国王希望所有的联盟英雄都能以最佳状态迎战燃烧军团。在前往破碎海滩的途中，让我们来复习一下你的战斗技巧吧。你准备好了就说一声。"
D.Strings[99212]="幸会！光荣的战斗在破碎海滩等着我们呢！大酋长希望所有的部落英雄做好万全的准备。我们花点时间做个战斗训练吧。只要你说一声，我们就开始！"
D.Strings[99213]="你好，$n。我们对散落在这一区域的一系列魔网能量节点很感兴趣。"
D.Strings[99214]="骑上这头魔刃豹，跑过那些魔网节点，它就会吸收那里残留的能量了。"
D.Strings[99215]="魔刃豹的直线奔跑速度很快，但转弯时会减速。"
D.Strings[99216]="收集足够的能量来喂饱它以供我们研究，你的任务就算完成了。"
D.Strings[99217]="看来我对这种……事准备得还很不充分。或许我应该等事态平息之后再回来。"
D.Strings[99218]="你真是客气，可我恐怕不该留在这里。我很快就会回来的。"
D.Strings[99219]="我们夺回了南点大门的控制权。我已经命令部队继续巡逻了。照顾好其他人。我们不能让燃烧军团继续前进了！"
D.Strings[99220]="被遗忘者们！盟友们！该站出来对抗燃烧军团了！做好准备！"
D.Strings[99221]="来吧，勇士们！响应战斗的召唤！燃烧军团盯上了塔伦米尔。"
D.Strings[99222]="守住阵地！不要后退！"
D.Strings[99223]="恶魔来了！让……他们……付出代价吧！"
D.Strings[99224]="他们又来了！别因为恐惧而抛弃责任！"
D.Strings[99225]="太强大了！他们还在不断变强！不要乱！"
D.Strings[99226]="砍掉这头恶魔的脑袋，我们就能占据上风！"
D.Strings[99227]="让这家伙为他的罪行付出代价吧！"
D.Strings[99228]="我们还有胜利的希望，勇士们。冲出去，赶走这些恶魔！"
D.Strings[99229]="我绝不允许任何恶魔在希尔斯布莱德横行！散开！消灭他们！"
D.Strings[99230]="黑暗在滋长。他们的影响范围还在扩大！挡住他们！"
D.Strings[99231]="又来了一群恶魔！必须阻止他们！"
D.Strings[99232]="你的疯狂到此为止了，恶魔！你死到临头了！"
D.Strings[99233]="很久很久以前，在凡人种族的纪元开始之前，至高守护者莱统治着南卡利姆多。"
D.Strings[99234]="痛哭流涕吧，恶魔！你打不垮我们！燃烧军团必败！"
D.Strings[99235]="泰坦阿曼苏尔授予至高守护者一对闪电之拳。这对拳刃是在回荡着风暴之声的天空中铸成，能让莱的拳头获得闪电的力量。"
D.Strings[99236]="至高守护者莱和泰坦创造的女巫海拉创造了四大元素位面，囚禁不听话的元素领主。"
D.Strings[99237]="他将通往这些国度的钥匙嵌入了他的盾牌，“至高守护者之盾”中。莱行走于元素位面，既是它们的狱卒，也是它们的主宰。"
D.Strings[99238]="与黑暗帝国的战争爆发时，至高守护者莱创造了一支岩石大军听从自己的指挥。这些生物被称为“魔古”，而他们称他们的神为“莱登”，或是“主宰莱”。"
D.Strings[99239]="庆祝胜利吧，但别忘了……时间有限。军团还会回来的。"
D.Strings[99240]="而魔古最终成了莱登的送葬者。许多个世纪后，魔古被血肉诅咒腐蚀，在雷电之王雷神的带领下，他们推翻了至高守护者。"
D.Strings[99241]="萨满，雷电之王获得了莱登的武器，可他并没有使用它们。"
D.Strings[99242]="雷神能像至高守护者一样驾驭风暴和怒火，可无法像他一样掌控元素。或许你有这种力量。"
D.Strings[99243]="胜利！快包扎伤口，恢复力气吧，我们得做好准备。燃烧军团的入侵才刚刚开始……"
D.Strings[99244]="你的同伴在等你。回我的寺院来找我吧。让我们看看，你能不能做到雷电之王做不到的事。"
D.Strings[99245]="夏多雷必将得到救赎。"
D.Strings[99246]="几乎没有凡人听说过至高守护者莱的历史，他掌控着元素位面，与魔古帝国关系密切。"
D.Strings[99247]="真了不起！我在想……"
D.Strings[99248]="低等贱民！削减他们的魔力酒配额也许能让他们明白到底谁才是做主的人。"
D.Strings[99249]="只要饿上一阵子，那些叛军就会像饿急了的老鼠一样自相残杀了。所有的同情分子也会暴露，秩序也就能恢复了！"
D.Strings[99250]="他们把他带到哪儿去了？"
D.Strings[99251]="他们对我的孩子做了什么？"
D.Strings[99252]="他现在应该已经回来了。"
D.Strings[99253]="这些该死的戏法。他们对我的儿子做了什么？"
D.Strings[99254]="我就是不明白，为什么有些市民会反对大魔导师的计划。"
D.Strings[99255]="噢，艾伦……你太年轻了，不该卷入这种事。"
D.Strings[99256]="对，这样就能镇住他们了！"
D.Strings[99257]="他在哪儿？我的艾伦在哪儿？"
D.Strings[99258]="燃烧军团只知道盯着眼前。他们正需要我这样目光长远的人来指引他们。"
D.Strings[99259]="我要那个僭越者的脑袋！"
D.Strings[99260]="宇宙里还有许多世界有待净化。谁比我更擅长此事呢？"
D.Strings[99261]="萨格拉斯会欣赏我的。他的力量能开阔我的头脑吗？我的头脑能提升他的力量吗？"
D.Strings[99262]="两路夹击！邪能卫士和末日守卫，攻击！"
D.Strings[99263]="够了！姐妹们，结束这场闹剧！"
D.Strings[99264]="我不知道该不该继续支持月郡家族夺得顾问的位置了。如果兰索斯还在的话，或许还行，可他的女儿……"
D.Strings[99265]="卡扎克，我在叫你！解决他们！"
D.Strings[99266]="我听说她是个软心肠，过于同情那些贱民了。"
D.Strings[99267]="我还想看到鲁文·暮湾成为新顾问呢。真可惜。"
D.Strings[99268]="我马上就去栖地找你。一路顺风。"
D.Strings[99269]="我敢打赌，这都是那些指挥官的错。贱民们把一切都毁了！"
D.Strings[99270]="如果让我说的话，应该让瓦斯塔瓦家族接过顾问的空缺。"
D.Strings[99271]="他们根本没有希望！他们已经把自己绑上了月郡家族的战车。"
D.Strings[99272]="科恩·斯特拉瑞斯那个杀人凶手？我才不信呢！"
D.Strings[99273]="就算他是，我也宁愿他当上顾问。他总比莉莉丝·月郡强。"
D.Strings[99274]="眼下我还有件急事要处理，但我很快就会去找你的。"
D.Strings[99275]="月郡家族的理念是对的。向平民释放善意可以把他们争取到我们这边来。"
D.Strings[99276]="善意？你在开玩笑吗？没收他们的魔力酒，他们就会自己爬回来了！"
D.Strings[99277]="有关顾问凡多斯的死，有什么线索了吗？"
D.Strings[99278]="我听说是被他抛弃的情人干的。"
D.Strings[99279]="真的？我还以为是哪个异见分子干的呢，不过一个被侮辱的情人听上去可刺激多了！"
D.Strings[99280]="我敢打赌，凡多斯说的死只是个开始。苏拉玛的每个贵族都将成为目标！"
D.Strings[99281]="小声点！大魔导师就在边上。你想惹她发火吗？"
D.Strings[99282]="呃……我的意思是秩序已经恢复了！我们安全极了，这全亏大魔导师！"
D.Strings[99283]="你知道吗？占星师艾塔乌斯特别聪明，他的脑袋比精灵贵族的重三倍，比平民重六倍！"
D.Strings[99284]="我刚才看到魔剑士奥鲁瑞尔在那儿走来走去的。她看上去总是那么……气呼呼的。"
D.Strings[99285]="这酒太差劲了。我敢打赌，麦兰杜斯肯定往里头掺水了。"
D.Strings[99286]="我才不在乎燃烧军团的存在呢。能站在赢家一边的感觉真不错。"
D.Strings[99287]="我们已经安逸了这么久。外来者为什么非要来捣乱呢？"
D.Strings[99288]="你知道吗，我有时觉得平民还不够尊重我们。"
D.Strings[99289]="哪个疯子会用暗夜井的力量灌注这个怪物？小心，如果创造它的目的是保护堡垒下层，防范入侵者，那它一定特别危险。"
D.Strings[99290]="撕碎他们的血肉，我的宠物！"
D.Strings[99291]="我要把你大卸八块！"
D.Strings[99292]="现在，夜之子的命运就掌握在外来者手中了……你们……要帮我们摆脱女王的可怕交易。"
D.Strings[99293]="牧师，过来！我需要你的帮助！"
D.Strings[99294]="Shanar daloras！我不知道这个东西是怎么形成的，但暗夜井的精华正在涌向它。"
D.Strings[99295]="这个笼子也许很结实，但记住，鱼人的头脑都很简单，很容易控制。"
D.Strings[99296]="这是个重要的日子，朋友们。在军团到来前，暗夜要塞的走廊里已经有整整一万年没有出现过外来者了。"
D.Strings[99297]="王宫就在前面。你们会发现，那里的守卫比下层还要森严。"
D.Strings[99298]="魔剑士！击败她之后，就没人能阻止我们打开王宫大门了！"
D.Strings[99299]="解放苏拉玛的战斗终于打响了！我们再也不用躲躲藏藏了！"
D.Strings[99300]="夜之子将与新老盟友一同赶走燃烧军团。我们的命运降临了，朋友们！将苏拉玛从恶魔手中解放出来，就能拯救全艾泽拉斯！Tor ilisar'thera'nal！"
D.Strings[99301]="大魔导师的统治该结束了！去塔楼，朋友们！推翻暴君，解放我们的人民！"
D.Strings[99302]="我试过硬闯，可这些木栅栏太结实了。"
D.Strings[99303]="我们必须在燃烧军团放出更多怪物前赶走他们！"
D.Strings[99304]="我的人民为艾利桑德和燃烧军团的交易付出了高昂的代价。我恨她！但她赋予你的魔法或许能打倒我们的敌人……并为她博得少许原谅。"
D.Strings[99305]="没想到我还活着吧，奥鲁瑞尔？"
D.Strings[99306]="艾塔乌斯自以为……高高在上。我得承认，看到他倒霉，我很高兴。"
D.Strings[99307]="我能说什么呢？他很忠于职守。"
D.Strings[99308]="奥鲁瑞尔教过无数夜之子剑术。她本是个宝贵的盟友，可惜她站错队了。"
D.Strings[99309]="斯夸恩！不！我会让你付出代价的！"
D.Strings[99310]="我们很快就能评估这份礼物的价值了。现在，该去对付古尔丹了！"
D.Strings[99311]="你们！"
D.Strings[99312]="我应该亲自解决你们，而不是把你们丢给麦兰杜斯。等我解决这些小崽子，你们的鲜血就将染红我的剑刃！"
D.Strings[99313]="大门被攻破了！抱歉没能早点赶到，我们在清理外围时遇到了一点麻烦。"
D.Strings[99314]="我会守住这片阵地的。塔莉萨，你的指点对我们的勇士很有价值。在接下来的战斗中，他们还将依赖你的智慧。"
D.Strings[99315]="苏拉玛的人民欠这些英雄一份还不清的恩情。我会陪他们战斗到底。"
D.Strings[99316]="我会盯着你们的。祝你们好运！"
D.Strings[99317]="在第三次大战中，提克迪奥斯死于伊利丹·怒风之手。那个恶魔猎手的灵魂应该很高兴这个恐惧魔王又惨死了一次。"
D.Strings[99318]="这是为了提里奥·弗丁，怪物！虽然不是克洛苏斯下的手，但他也导致了弗丁的死。"
D.Strings[99319]="看来这个星术师自视极高。但一个好的法师应该明白，智力并不等于一切！"
D.Strings[99320]="这么说，宫廷花匠把自己变成了植物？"
D.Strings[99321]="虽然我不擅长剑术，但她的技巧令我印象深刻。"
D.Strings[99322]="%s购买了一桌盛宴！快来旅店享用美食吧！"
D.Strings[99323]="%s购买了一箱骑乘巨鼠缰绳！快来卫兵岗哨附近领取你的临时巨鼠坐骑吧！"
D.Strings[99324]="%s在黑市的水域中投入了鱼饵！快来钓盲目之眼吧！"
D.Strings[99325]="%s从劳拉·马利那里购买了一些幼年变异战龟！快来驯服它们，别让它们跑了！"
D.Strings[99326]="尽管下令吧。"
D.Strings[99327]="%s将鳄鱼从下水道里冲了出来！"
D.Strings[99328]="我的大门永远向你敞开。"
D.Strings[99329]="%s惊醒了蝙蝠！小心你的脑袋！"
D.Strings[99330]="%s召唤了小鬼！"
D.Strings[99331]="%s与黑寡妇的潜行者签署了合同！小心你们的钱包！"
D.Strings[99332]="残月酒馆永不关门。"
D.Strings[99333]="%s对$n使用了狂野法力魔杖！"
D.Strings[99334]="我们只有团结一心，才能打败他们！"
D.Strings[99335]="我保留拒绝服务任何人的权利。"
D.Strings[99336]="只有跟这些英雄合作，我们才能赢得胜利！快，兄弟们，去圣光穹顶！先知需要我们！"
D.Strings[99337]="现在，我们该关门了。"
D.Strings[99338]="我需要喝一杯。"
D.Strings[99339]="在出发前，我还有一件小事要处理。我们一会儿见。"
D.Strings[99340]="也许有可能……"
D.Strings[99341]="马迪亚斯·肖尔就被关在南边的日蚀大厅里。"
D.Strings[99342]="带我去找马迪亚斯吧。"
D.Strings[99343]="我们要快速潜行到肖尔身边。"
D.Strings[99344]="跟上。肖尔就在附近了。"
D.Strings[99345]="我们得尽快找到马迪亚斯。"
D.Strings[99346]="他在这里面。"
D.Strings[99347]="已经不远了。"
D.Strings[99348]="|TInterface\\Icons\\spell_mage_temporalshield:20|t暗夜井中淌出了一颗|cFFFF0000|Hspell:219815|h[时光珠]|h|r！"
D.Strings[99349]="认真过好每一天。"
D.Strings[99350]="我们的力量和意志一样强大。"
D.Strings[99351]="死亡骑士！你在这里的所做所为是在亵渎一切神圣的存在！"
D.Strings[99352]="放弃这个邪恶的任务吧，否则就等着被圣光净化吧！"
D.Strings[99353]="我已经做了很多年猎人训练师了。看到我们取得的成就，我很自豪！"
D.Strings[99354]="外域有它的魅力。可我在听说了这个营地之后，就知道自己一定要亲眼来看看。"
D.Strings[99355]="各种族的猎人们，团结了起来……现在真是今非昔比了！"
D.Strings[99356]="我以前总是大口大口地喝法力药水。这没什么可自豪的，但我至少努力了！"
D.Strings[99357]="我可以帮你采购一些珍贵物品。"
D.Strings[99358]="$n，你被发现了。快隐身！"
D.Strings[99359]="看，那是引发爆炸的人！"
D.Strings[99360]="<这本指南看起来至少被一打各种野生动物蹂躏过了。虽然经过了反复修补，也已经完全读不了了。它还散发着一股刺鼻的麝香味儿。>"
D.Strings[99361]="人民必将崛起。"
D.Strings[99362]="我会为父亲增光添彩的。"
D.Strings[99363]="你没听过我的威名吗？"
D.Strings[99364]="别来惹我。我一定会赢。"
D.Strings[99365]="有趣吗？很好。抓紧享受吧。"
D.Strings[99366]="暗夜井在召唤我……"
D.Strings[99367]="我们的孤立政策结束了。"
D.Strings[99368]="另一个去哪儿了？"
D.Strings[99369]="小心你所信赖的人……"
D.Strings[99370]="干得好，$n！我已经等不及要分析这头魔刃豹了。我敢肯定，它周围的空气肯定都充斥着魔网能量。"
D.Strings[99371]="苏拉玛必将解放。"
D.Strings[99372]="外来者都是这么……急躁吗？"
D.Strings[99373]="好吧，该走了……"
D.Strings[99374]="<叹气。>我在天堂生活了一万年，现在却跟你一起被困在这里。"
D.Strings[99375]="等这事结束后，我一定要恢复那个护盾。"
D.Strings[99376]="啊，你好啊。"
D.Strings[99377]="你有发现了吗？"
D.Strings[99378]="我们要去哪儿？"
D.Strings[99379]="尊重魔法，否则它就会毁了你。"
D.Strings[99380]="祝你一路平安。"
D.Strings[99381]="测试。观察。再来一次！"
D.Strings[99382]="你要走了对吧？"
D.Strings[99383]="需要传送吗？你最好选个远点儿的地方……"
D.Strings[99384]="噢，给我闪开！"
D.Strings[99385]="多么神奇的发现，$n。这个装置似乎有某种机关保护。"
D.Strings[99386]="仔细看看这个盒子，开始解除机关吧。"
D.Strings[99387]="太好了，$n！这个信息对我们的研究极其珍贵。"
D.Strings[99388]="你看，这可是你逼我的。<叹气>"
D.Strings[99389]="时不时的，就会有勇敢的猎人来寻找雄鹰之爪。他们与雄鹰之魂沟通，接受她的祝福，然后开始自己的狩猎。可惜，这些人最后都只有一个下场：死亡。"
D.Strings[99390]="情况不对劲。有些奇怪的……小心！"
D.Strings[99391]="能量就在外面，我们触手可得。"
D.Strings[99392]="艾利桑德不该怀疑我们的魔法。"
D.Strings[99393]="你的协助可以帮我们赢下这场战争。"
D.Strings[99394]="你可以说话了。"
D.Strings[99395]="好帮手太难找了。"
D.Strings[99396]="魔力是永恒的。"
D.Strings[99397]="幸会，$n。你是来帮我搞科研的吗？"
D.Strings[99398]="你知道的，魔法不仅仅是召唤大火球去砸你的敌人而已。有时你也需要扔石头，非常大的石头。"
D.Strings[99399]="当然，我所谓的“扔”，其实是指点火来发射它。"
D.Strings[99400]="好了，课堂教学到此为止。过去试试吧，向我标记的目标开火。我稍后再回来收集数据。"
D.Strings[99401]="打得好，$n。这些够我今天用的了。"
D.Strings[99402]="<嗯哼。>你还在这儿啊。"
D.Strings[99403]="瓦尔——托伊。托伊！哎，算了算了。随你怎么叫了。"
D.Strings[99404]="这是某种古老的仪式吗？拿手指戳一个人，直到他失去耐心？"
D.Strings[99405]="在我们那儿，这种行为的后果是很严重的……"
D.Strings[99406]="知道吗，我已经听够“更多能量、更多能量。”魔法回廊不是装满了货物的马车——它只是传输能量的导管！"
D.Strings[99407]="你为什么要这么做？我知道和平总是让人心神不定，可是——"
D.Strings[99408]="你们曾有大把时间的找回圣矛，可都失败了。我将为鲜血图腾……夺回雄鹰之爪！"
D.Strings[99409]="秩序必须得到恢复。"
D.Strings[99410]="只要这个顽固的灵兽愿意屈服！"
D.Strings[99411]="我要用我的剑捍卫苏拉玛。"
D.Strings[99412]="又一个闯入者？别多管至高岭的闲事！"
D.Strings[99413]="夏多雷正在受难。"
D.Strings[99414]="擦亮你的剑。"
D.Strings[99415]="如果你想惹火我，那是没用的。"
D.Strings[99416]="我会好起来的。现在，继续前进吧！"
D.Strings[99417]="感谢你的帮助。如果你不介意的话，我得继续前进了。"
D.Strings[99418]="我们不能停止战斗。继续推进！"
D.Strings[99419]="我受过几千年的礼仪训练。你这点无聊的小骚扰对我来说，就像晨露一样转瞬即逝。"
D.Strings[99420]="<嘟哝>保持……坚强……"
D.Strings[99421]="够了！攻击，卡尔！抓瞎他的眼睛！"
D.Strings[99422]="……幸好我的猫头鹰喜欢你。"
D.Strings[99423]="你好，$c。愿圣光指引你的道路。"
